insert into public.bible_verses (translation_id, book_id, chapter, verse, text)
values
('kam', '2CH', 36, 7, 'O na Nevukatilesa atwaa ĩmwe ya mĩio ya nyũmba ya Yeova Mbaviloni, na amĩkĩa ĩkalũnĩ yake Mbaviloni.'),
('kam', '2CH', 36, 8, 'Na ĩndĩ meko ala angĩ ma Yeoiakimu, na mothatyo make ala wekaa, na ũla woonekie ĩũlũ wake, sisya, nĩmaandĩkĩtwe ĩvukunĩ ya asumbĩ ma Isilaeli na Yuta: na Yeoiakini mwana wake asumbĩka vandũ vake.'),
('kam', '2CH', 36, 9, 'Yeoiakini aĩ wa myaka nyanya yĩla wambĩlĩlye kũsumbĩka; na asumbĩka myeĩ ĩtatũ na mĩthenya ĩkũmi Yelusaleme; na eekaa ũla Yeova wonaa wĩ ũthũku.'),
('kam', '2CH', 36, 10, 'Na mwaka ũkyambĩlĩlya mũsumbĩ Nevukatilesa atũmana, na amũete Mbaviloni, vamwe na mĩio mĩseo ya nyũmba ya Yeova, na amũtw’ĩkĩthya Nzetekia mwana‐a‐ĩthe wake mũsumbĩ wa Yuta na Yelusaleme.'),
('kam', '2CH', 36, 11, 'Nzetekia aĩ wa myaka mĩongo ĩlĩ na ũmwe yĩla wambĩlĩlye kũsumbĩka; na asumbĩka myaka ĩkũmi na ũmwe Yelusaleme:'),
('kam', '2CH', 36, 12, 'na eekaa ũla Yeova Ngai wake wonaa wĩ ũthũku; ndaaĩnyivĩsya mwathani Yelemia akĩneena ndeto syaumĩte kanyw’anĩ wa Yeova.'),
('kam', '2CH', 36, 13, 'O na amũng’endea Nevukatilesa, ũla wamwĩavĩthisye na Ngai: ĩndĩ oomya ngingo yake, na oomanĩlya ngoo yake ndakamwĩthyũũĩe Yeova, Ngai wa Isilaeli.'),
('kam', '2CH', 36, 14, 'O na ĩngĩ anene onthe ma athembi, na andũ, mavĩtasya mũno makĩatĩĩa mothatyo onthe ma i mbaĩ; na mavukasya nyũmba ya Yeova ĩla wamĩvathie yĩthĩwe ntheu ku Yelusaleme.'),
('kam', '2CH', 36, 15, 'Na Yeova, Ngai wa aaĩthe moo, atũmanaa kwoo na kanyw’a wa atũmwa make, akyũkĩla tene na akĩtũmana, nĩkwĩthĩwa amew’ĩaa andũ make ĩnee, o na ũtũo wake:'),
('kam', '2CH', 36, 16, 'ĩndĩ nĩmamathekeeaa atũmwa ma Ngai, na kũvũthasya ndeto syake, na kũmavũthĩĩasya athani make, mũvaka ũthilĩku wa Yeova wamokĩlĩla andũ make, kũvika kũtyaĩ kya kũvosya.'),
('kam', '2CH', 36, 17, 'Kwondũ wa ũu amaetee mũsumbĩ wa Akalitei, ũla woaĩe anake moo na ũvyũ nyũmbanĩ ya vala vandũ vatheu voo, na ndaamwĩw’ĩa mwanake kana mwĩĩtu mũtheu ĩnee, o na mũtumĩa kana ũla wĩ mbuĩ: amanengane onthe kw’okonĩ kwake.'),
('kam', '2CH', 36, 18, 'Na mĩio yonthe ya nyũmba ya Ngai, mĩnene na mĩnini, na mothwii maie ma nyũmba ya Yeova, na mothwii maie ma mũsumbĩ, na ma anene make me mbee ũsumbĩnĩ, atwaa isu syonthe Mbaviloni.'),
('kam', '2CH', 36, 19, 'Na mavĩvya nyũmba ya Ngai, na maomboanga ũvai wa Yelusaleme, na mavĩvya na mwaki nyũmba syonthe nene mbanakavye sya vo, na maananga mĩio mĩseo ya vo yonthe.'),
('kam', '2CH', 36, 20, 'Na ala mavonokie ũvyũ amatwaa Mbaviloni; na maĩ athũkũmi make na ma ana make kũvika kũsumbĩka kwa ũsumbĩ wa Velisia:'),
('kam', '2CH', 36, 21, 'nĩ kana ndeto ya Yeova na kanyw’a wa Yelemia ĩanĩw’e, kũvika nthĩ yatanĩa masavato mayo: nũndũ o yĩla yeethĩiwe ĩei nĩw’o yalilikanaa savato, ĩanĩsye myaka mĩongo mũonza.'),
('kam', '2CH', 36, 22, 'Na ĩndĩ mwaka wa mbee wa kũsumbĩka kwa Kulusi mũsumbĩ wa Velisia, nĩ kana ndeto ya Yeova na kanyw’a wa Yelemia ĩanĩw’e, Yeova aamũkya veva wa Kulusi mũsumbĩ wa Velisia, kũvika atavan’ya ũsumbĩnĩ wake w’onthe, o na aandĩka, akyasya,'),
('kam', '2CH', 36, 23, 'Ũũ nĩw’o Kulusi mũsumbĩ wa Velisia ũnũkwasya, Yeova, Ngai wa ĩtunĩ, nũnengete mosumbĩ onthe ma nthĩ; na nũmbĩaĩĩte nĩmwakĩe nyũmba Yelusaleme, ĩla yĩ Yuta. O ũla wĩ katĩ wenyu wa andũ make onthe, Yeova Ngai wake nĩethĩwe vamwe nake, nake nĩambate.'),
('kam', 'EZR', 1, 1, 'Na mwaka wa mbee wa kũsumbĩka kwa Kulusi mũsumbĩ wa Velisia, nĩ kana ndeto ya Yeova na kwanyw’a wa Yelemia yĩanĩe, Yeova aamũkya veva wa Kulusi mũsumbĩ wa Velisia, na ĩndĩ atavan’ya ũsumbĩnĩ wake w’onthe, o na aandĩka, akyasya,'),
('kam', 'EZR', 1, 2, 'Ũũ nĩw’o Kulusi mũsumbĩ wa Velisia ũnũkwasya, Yeova, Ngai wa ĩtunĩ, nũnengete mosumbĩ onthe ma nthĩ; na nũmbĩaĩĩte nĩmwakĩe nyũmba Yelusaleme, ĩla yĩ Yuta.'),
('kam', 'EZR', 1, 3, 'O ũla wĩ katĩ wenyu wa andũ make onthe, Ngai wake nĩethĩwe vamwe nake, nake nĩambate Yelusaleme, ĩla yĩ Yuta, akatũngĩĩe nyũmba ĩla yĩ Yelusaleme, ĩla ya Yeova, Ngai wa Isilaeli (nake nĩwe Ngai).'),
('kam', 'EZR', 1, 4, 'Na o ũla wĩtiwa, vandũ o na va vala wĩkalĩte ũeni, andũ ma vandũ vau mamũtethye na vetha, na thaavu, na isamũ, na nyamũ, eka nthembo ya kumya na ngoo ya kwenda kwondũ wa nyũmba ya Ngai ĩla yĩ Yelusaleme.'),
('kam', 'EZR', 1, 5, 'Nĩvo ĩndĩ atongoi ma nyũmba sya aaĩthe ma Yuta na Mbenyamini, na athembi, na Alivai, mookĩlile, o asu onthe ala Ngai waamũkisye maveva moo mambate matũngĩĩe nyũmba ya Yeova ĩla yĩ Yelusaleme.'),
('kam', 'EZR', 1, 6, 'Na onthe ala mamathyũlũlũkĩte mamekĩa moko moo vinya nĩ kũmanenga mĩio ya vetha, na thaavu, na isamũ, na nyamũ, na syĩndũ syĩ vata mũno, vamwe na syonthe ila syathembiwe na ngoo ya kwenda.'),
('kam', 'EZR', 1, 7, 'O na mũsumbĩ Kulusi aumaalya mĩio ya nyũmba ya Yeova, ĩla Nevukatilesa waetie kuma Yelusaleme, na nĩwamĩkĩĩte nyũmbanĩ ya ngai syake;'),
('kam', 'EZR', 1, 8, 'o ĩsu Kulusi mũsumbĩ wa Velisia nĩwaumaalilye na kw’oko kwa Mithiletathi, mũsũvĩi wa ũthwii, na amĩtalĩla Sesivasali, mũnene wĩ mbee ũsumbĩnĩ wa Yuta.'),
('kam', 'EZR', 1, 9, 'Na ũũ nĩw’o ũtalo wayo: masaani mĩongo ĩtatũ ma thaavu, na masaani ngili ma vetha, na tũvyũ mĩongo ĩlĩ na kenda,'),
('kam', 'EZR', 1, 10, 'na mbakũli mĩongo ĩtatũ sya thaavu, na mbakũli maana ana na ĩkũmi sya vetha sya mũthemba ũngĩ, na mĩio ĩngĩ ngili.'),
('kam', 'EZR', 1, 11, 'Mĩio yonthe ya thaavu na vetha yaĩ ngili itano na maana ana. Ĩsu yonthe Sesivasali ambata nayo, yĩla asu mataviwe mambatiw’e Yelusaleme kuma Mbaviloni.'),
('kam', 'EZR', 2, 1, 'Na ĩndĩ aa nĩo ana ma kĩlungu kĩnene kya nthĩ, ala mambatie kuma kũla kũtavwanĩ kwa ala matavĩtwe, ala Nevukatilesa mũsumbĩ wa Mbaviloni wamatwaie Mbaviloni, ala masyokie Yelusaleme na Yuta, kĩla ũmwe ndũanĩ yoo;'),
('kam', 'EZR', 2, 2, 'ala mookie na Nzeluvaveli, nĩ Yesua, na Neemia, na Selaia, na Leelaia, na Molitekai, na Mbilisani, na Misivali, na Mbikivai, na Leumu, na Mbaana. Ũtalo wa aũme ma andũ ma Isilaeli:'),
('kam', 'EZR', 2, 3, 'Ana ma Valosi, ngili ilĩ na ĩana na mĩongo mũonza na elĩ.'),
('kam', 'EZR', 2, 4, 'Ana ma Sevatia maana atatũ na mĩongo mũonza na elĩ.'),
('kam', 'EZR', 2, 5, 'Ana ma Alaa, maana mũonza na mĩongo mũonza na atano.'),
('kam', 'EZR', 2, 6, 'Ana ma Vaathi‐moavi, o ma ana ma Yesua na Yoavu, ngili ilĩ na maana nyanya na ĩkũmi na elĩ.'),
('kam', 'EZR', 2, 7, 'Ana ma Elamu, ngili na maana elĩ na mĩongo ĩtano na ana.'),
('kam', 'EZR', 2, 8, 'Ana ma Nzatu, maana kenda na mĩongo ĩna na atano.'),
('kam', 'EZR', 2, 9, 'Ana ma Nzakai, maana mũonza na mĩongo thanthatũ.'),
('kam', 'EZR', 2, 10, 'Ana ma Mbani, maana thanthatũ na mĩongo ĩna na elĩ.'),
('kam', 'EZR', 2, 11, 'Ana ma Mbevai, maana thanthatũ na mĩongo ĩlĩ na atatũ.'),
('kam', 'EZR', 2, 12, 'Ana ma Asikati, ngili na maana elĩ na mĩongo ĩlĩ na elĩ.'),
('kam', 'EZR', 2, 13, 'Ana ma Atonikamu, maana thanthatũ na mĩongo thanthatũ na thanthatũ.'),
('kam', 'EZR', 2, 14, 'Ana ma Mbikivai, ngili ilĩ na mĩongo ĩtano na thanthatũ.'),
('kam', 'EZR', 2, 15, 'Ana ma Atini, maana ana na mĩongo ĩtano na ana.'),
('kam', 'EZR', 2, 16, 'Ana ma Ateli, wa Esekia, mĩongo kenda na nyanya.'),
('kam', 'EZR', 2, 17, 'Ana ma Mbenzai, maana atatũ na mĩongo ĩlĩ na atatũ.'),
('kam', 'EZR', 2, 18, 'Ana ma Yola, ĩana na ĩkũmi na elĩ.'),
('kam', 'EZR', 2, 19, 'Ana ma Asumu, maana elĩ na mĩongo ĩlĩ na atatũ.'),
('kam', 'EZR', 2, 20, 'Ana ma Ngivali, mĩongo kenda na atano.'),
('kam', 'EZR', 2, 21, 'Ana ma Mbethileemu, ĩana na mĩongo ĩlĩ na atatũ.'),
('kam', 'EZR', 2, 22, 'Andũ ma Netova, mĩongo ĩtano na thanthatũ.'),
('kam', 'EZR', 2, 23, 'Andũ ma Anathothi, ĩana na mĩongo ĩlĩ na nyanya.'),
('kam', 'EZR', 2, 24, 'Ana ma Asimavethi, mĩongo ĩna na elĩ.'),
('kam', 'EZR', 2, 25, 'Ana ma Kiliathi‐alimu, na Kevila, na Mbeelothi, maana mũonza na mĩongo ĩna na atatũ.'),
('kam', 'EZR', 2, 26, 'Ana ma Lama na Ngeva, maana thanthatũ na mĩongo ĩlĩ na ũmwe.'),
('kam', 'EZR', 2, 27, 'Andũ ma Mikimasi, ĩana na mĩongo ĩlĩ na elĩ.'),
('kam', 'EZR', 2, 28, 'Andũ ma Mbethi‐eli na Ai, maana elĩ na mĩongo ĩlĩ na atatũ.'),
('kam', 'EZR', 2, 29, 'Ana ma Nevo, mĩongo ĩtano na elĩ.'),
('kam', 'EZR', 2, 30, 'Ana ma Makivisi, ĩana na mĩongo ĩtano na thanthatũ.'),
('kam', 'EZR', 2, 31, 'Ana ma Elamu ũla ũngĩ, ngili na maana elĩ na mĩongo ĩtano na ana.'),
('kam', 'EZR', 2, 32, 'Ana ma Alimu, maana atatũ na mĩongo ĩlĩ.'),
('kam', 'EZR', 2, 33, 'Ana ma Loti, na Atiti, na Ono, maana mũonza na mĩongo ĩlĩ na atano.'),
('kam', 'EZR', 2, 34, 'Ana ma Yeliko, maana atatũ na mĩongo ĩna na atano.'),
('kam', 'EZR', 2, 35, 'Ana ma Senaa, ngili itatũ na maana thanthatũ na mĩongo ĩtatũ.'),
('kam', 'EZR', 2, 36, 'Athembi: ana ma Yetaia, wa nyũmba ya Yesua, maana kenda na mĩongo mũonza na atatũ.'),
('kam', 'EZR', 2, 37, 'Ana ma Imeli, ngili na mĩongo ĩtano na elĩ.'),
('kam', 'EZR', 2, 38, 'Ana ma Vasuli, ngili na maana elĩ na mĩongo ĩna na mũonza.'),
('kam', 'EZR', 2, 39, 'Ana ma Alimu, ngili na ĩkũmi na mũonza.'),
('kam', 'EZR', 2, 40, 'Alivai: ana ma Yesua na Katimieli, o ma ana ma Otavia, mĩongo mũonza na ana.'),
('kam', 'EZR', 2, 41, 'Aini: ana ma Asavu, ĩana na mĩongo ĩlĩ na nyanya.'),
('kam', 'EZR', 2, 42, 'Ana ma asũvĩi ma mĩomonĩ: ana ma Salumu, na ana ma Ateli, na ana ma Talimoni, na ana ma Akuvu, na ana ma Atita, na ana ma Sovai, onthe nĩ ĩana na mĩongo ĩtatũ na kenda.'),
('kam', 'EZR', 2, 43, 'Anethini: ana ma Nziia, na ana ma Aasuva, na ana ma Tavaothi,'),
('kam', 'EZR', 2, 44, 'na ana ma Kelosi, na ana ma Siaa, na ana ma Vatoni,'),
('kam', 'EZR', 2, 45, 'na ana ma Levana, na ana ma Akava, na ana ma Akuvu,'),
('kam', 'EZR', 2, 46, 'na ana ma Akavu, na ana ma Samulai, na ana ma Aananu,'),
('kam', 'EZR', 2, 47, 'na ana ma Ngiteli, na ana ma Kaali, na ana ma Leaia,'),
('kam', 'EZR', 2, 48, 'na ana ma Lesini, na ana ma Nekota, na ana ma Ngasamu,'),
('kam', 'EZR', 2, 49, 'na ana ma Usa, na ana ma Vasea, na ana ma Mbesai,'),
('kam', 'EZR', 2, 50, 'na ana ma Asana, na ana ma Ameuni, na ana ma Nevisimu,'),
('kam', 'EZR', 2, 51, 'na ana ma Mbakivuki, na ana ma Akuva, na ana ma Aliuli,'),
('kam', 'EZR', 2, 52, 'na ana ma Mbasiluthi, na ana ma Meita, na ana ma Alasa,'),
('kam', 'EZR', 2, 53, 'na ana ma Mbalikosi, na ana ma Sisela, na ana ma Teema,'),
('kam', 'EZR', 2, 54, 'na ana ma Nesia, na ana ma Ativa.'),
('kam', 'EZR', 2, 55, 'Ana ma athũkũmi ma Solomoni: ana ma Sotai, na ana ma Sovelethi, na ana ma Veluta,'),
('kam', 'EZR', 2, 56, 'na ana ma Yaala, na ana ma Ndalikoni, na ana ma Ngiteli,'),
('kam', 'EZR', 2, 57, 'na ana ma Sevatia, na ana ma Atili, na ana ma Vokelethi‐nzevaimu, na ana ma Ami.'),
('kam', 'EZR', 2, 58, 'Anethini onthe, na ana ma athũkũmi ma Solomoni, maĩ maana atatũ na mĩongo kenda na elĩ.'),
('kam', 'EZR', 2, 59, 'Na aa nĩo ala mambatie kuma Teli‐mela, na Teli‐alasa, na Keluvi, na Atani, na Imeli; ĩndĩ matyaatonya kwĩmanyĩthan’ya nyũmba sya aaĩthe moo, o na mbaĩ yoo, kana nĩ ma Isilaeli:'),
('kam', 'EZR', 2, 60, 'ana ma Ndelaia, na ana ma Tovia, na ana ma Nekota, maana thanthatũ na mĩongo ĩtano na elĩ.'),
('kam', 'EZR', 2, 61, 'Na ma ana ma athembi: ana ma Avaia, na ana ma Mbalisilai, nomo ana ma Akosi, ũla watwaie mwĩĩtu wa Mbalisilai Mũngileati, na eetanĩw’a na syĩtwa yoo.'),
('kam', 'EZR', 2, 62, 'Asu nĩmamanthie ĩvuku yoo yĩla matalĩtwe mosyaanĩo, ĩndĩ yĩtyaaoneka: kwondũ wa ũu nĩmatalilwe kwĩthĩwa nĩ avuku na maumw’a ũthembinĩ.'),
('kam', 'EZR', 2, 63, 'Na ngavana amea, matikaye syĩndũ ntheu mũno, kũvika kwaũngama mũthembi wĩ na Ulimu na Thumimu.'),
('kam', 'EZR', 2, 64, 'Ũmbano w’onthe vamwe waĩ ngili mĩongo ĩna na ilĩ na maana atatũ na mĩongo thanthatũ,'),
('kam', 'EZR', 2, 65, 'eka athũkũmi moo aũme na athũkũmi moo eĩtu, namo maĩ ngili mũonza na maana atatũ na mĩongo ĩtatũ na mũonza: na maĩ na aũme ma kwina na aka ma kwina maana elĩ.'),
('kam', 'EZR', 2, 66, 'Mbalasi syoo syaĩ maana mũonza na mĩongo ĩtatũ na thanthatũ; na nyũmbũ syoo, maana elĩ na mĩongo ĩna na itano;'),
('kam', 'EZR', 2, 67, 'na ngamĩle syoo, maana ana na mĩongo ĩtatũ na itano; na mang’oi moo, ngili thanthatũ na maana mũonza na mĩongo ĩlĩ.'),
('kam', 'EZR', 2, 68, 'Na atongoi amwe ma nyũmba sya aaĩthe, yĩla mavikie nyũmbanĩ ya Yeova yĩ Yelusaleme, nĩmaumisye na ngoo ya kwenda kwondũ wa nyũmba ya Ngai mamĩtũngĩe vandũ vayo:'),
('kam', 'EZR', 2, 69, 'manenganie kwĩanana na ũtonyi woo na maia vala vaiawa mbesa sya wĩa ilungu ngili mĩongo thanthatũ na ĩmwe sya thaavu, na latili ngili itano sya vetha, na ngũa ĩana yĩmwe sya athembi.'),
('kam', 'EZR', 2, 70, 'Na ĩndĩ athembi, na Alivai, na andũ amwe, na aini, na asũvĩi ma mĩomonĩ, na Anethini, matũaa ndũanĩ syoo, na Isilaeli onthe ndũanĩ syoo.'),
('kam', 'EZR', 3, 1, 'Na yĩla mwei wa mũonza wavikie na ana ma Isilaeli me ndũanĩ, andũ moombana vamwe Yelusaleme o ta mũndũ ũmwe.'),
('kam', 'EZR', 3, 2, 'Nĩvo ĩndĩ Yesua mwana wa Yosataki waũngamie, vamwe na athembi ana‐a‐ĩthe make, na Nzeluvaveli mwana wa Sealitieli, na ana‐a‐ĩthe make, na maaka kĩthembeo kya Ngai wa Isilaeli, mathembe nthembo sya kũvĩvw’a ĩũlũ wakyo, o tondũ kũandĩkĩtwe mĩaonĩ ya Mose mũndũ wa Ngai.'),
('kam', 'EZR', 3, 3, 'Na mailĩĩla kĩthembeo ĩtinanĩ yakyo; nũndũ maĩ na w’ĩa nũndũ wa andũ ma nthĩ isu: na mamũthembea Yeova nthembo sya kũvĩvw’a ĩũlũ wakyo, o nthembo sya kũvĩvw’a kĩoko na wĩoo.'),
('kam', 'EZR', 3, 4, 'Na malilikana mboka ya malwanda, o tondũ kũandĩkĩtwe, na mathemba nthembo sya kũvĩvw’a sya kĩla mũthenya kwa ũtalo wasyo, kwĩanana na ũtw’ĩo, o tondũ kwaaĩlĩte kwĩkawa kĩla mũthenya;'),
('kam', 'EZR', 3, 5, 'na ĩtina wa ũu nthembo ya kũvĩvw’a ĩtatw’ĩkanaa, na nthembo sya mĩtiso ya myei, na sya mboka syonthe itw’ĩtwe sya Yeova ila syavathĩtwe syĩthĩwe ntheu, na sya kĩla mũndũ ũla wamũthembee Yeova nthembo na ngoo ya kwenda.'),
('kam', 'EZR', 3, 6, 'Kuma mũthenya wa mbee wa mwei wa mũonza mambĩlĩlya kũmũthembea Yeova nthembo sya kũvĩvw’a: ĩndĩ wambĩlĩlyo wa ĩkalũ ya Yeova ndwaĩ ũnamba kwambĩlĩlw’a.'),
('kam', 'EZR', 3, 7, 'O na nĩmamanengie aki ma mavia, na aseũvya ma mbwaũ, mbesa; na ala ma Sitoni, na ala ma Tile, mamanenga kya ũya, na kya ũnyw’a, na mauta, makaete mĩtĩ ya mĩkũũ kuma Levanoni kũvika ũkanganĩ, ku Yova, kwĩanana na ũthei ũla manengiwe nĩ Kulusi mũsumbĩ wa Velisia.'),
('kam', 'EZR', 3, 8, 'Na ĩndĩ mwaka wa kelĩ wa kũka kwoo nyũmbanĩ ya Ngai Yelusaleme, mwei wa kelĩ, Nzeluvaveli mwana wa Sealitieli, na Yesua mwana wa Yosataki, na ala angĩ ma ana‐a‐ĩthe moo athembi na Alivai, na onthe ala maumĩte kũtavwanĩ makavika Yelusaleme nĩmambĩlĩlye, na maia Alivai, ala mavikĩtye myaka mĩongo ĩlĩ na mbee, methĩwe asyaĩĩsya ma wĩa wa nyũmba ya Yeova.'),
('kam', 'EZR', 3, 9, 'Nĩvo ĩndĩ Yesua vamwe na ana make na ana‐a‐ĩthe make, Katimieli na ana make, ana ma Yuta, maũngamie ta mũndũ ũmwe, methĩwe asyaĩĩsya ma athũkũmi nyũmbanĩ ya Ngai: ana ma Enatati, vamwe na ana moo na ana‐a‐ĩthe moo Alivai.'),
('kam', 'EZR', 3, 10, 'Na yĩla aki makwatisye wambĩlĩlyo wa ĩkalũ ya Yeova, nĩmaiie athembi mekĩĩte ngũa syoo me na masoo, na Alivai ana ma Asavu me na tũmasaya, mataĩe Yeova, kwĩanana na ũtw’ĩo wa Ndaviti mũsumbĩ wa Isilaeli.'),
('kam', 'EZR', 3, 11, 'Na maina makĩtĩkĩanĩsya makĩtaĩa na kũmũtũngĩa Yeova mũvea, makyasya, Nũndũ nĩ mũseo, nũndũ ũseo wake wĩ wendo kwa Isilaeli nĩwĩkalaa tene na tene. Na andũ onthe mookĩlya wasya mũnene, yĩla mamũtaĩe Yeova, nĩkwĩthĩwa mwambĩlĩlyo wa nyũmba ya Yeova waĩ mũkwatye.'),
('kam', 'EZR', 3, 12, 'Ĩndĩ aingĩ ma athembi na Alivai na atongoi ma nyũmba sya aaĩthe, atumĩa ala moonie nyũmba ya mbee, yĩla mwambĩlĩlyo wa nyũmba ĩno wakwatiw’e mene, maĩa na wasya mũtũlu; na aingĩ mookĩlya wasya mũnene nũndũ wa ũtanu:'),
('kam', 'EZR', 3, 13, 'ũndũ andũ mataĩ matonya kũvathũkan’ya kĩlonzo kya wasya wa ũtanu na kĩlonzo kya kũĩa kwa andũ; nũndũ andũ mookĩlilye wasya mũnene, na kĩlonzo nĩkyeew’ĩkie kũasa.'),
('kam', 'EZR', 4, 1, 'Na ĩndĩ yĩla nthũ sya Yuta na Mbenyamini syeewie ana ma ala matavĩtwe nĩmeũmwakĩa Yeova, Ngai wa Isilaeli, ĩkalũ;'),
('kam', 'EZR', 4, 2, 'nĩvo ĩndĩ syamũthengeeie Nzeluvaveli, na atongoi ma nyũmba sya aaĩthe, na syamea, Twake vamwe nenyu; nũndũ nĩtũmanthaa Ngai wenyu, o tondũ mwĩkaa; na nĩtũmũthembeaa kuma mĩthenya ya Esali‐atoni mũsumbĩ wa Asuli, ũla watũetie vaa.'),
('kam', 'EZR', 4, 3, 'Ĩndĩ Nzeluvaveli, na Yesua, na ala angĩ ma atongoi ma nyũmba sya aaĩthe ma Isilaeli, masyĩa, Mũti ũndũ naitũ tũkĩmwakĩa Ngai waitũ nyũmba; ĩndĩ ithyĩ ene vamwe tũkamwakĩa Yeova, Ngai wa Isilaeli, o tondũ Kulusi mũsumbĩ wa Velisia watwĩaĩe.'),
('kam', 'EZR', 4, 4, 'Nĩvo ĩndĩ andũ ma ĩ nthĩ monzethisye moko ma andũ ma Yuta, na mamathĩn’ya makyaka,'),
('kam', 'EZR', 4, 5, 'na maandĩka atai, masiĩĩe ũndũ mendaa kwĩka, mĩthenya yonthe ya Kulusi mũsumbĩ wa Velisia, o na kũvika kũsumbĩka kwa Ndalio mũsumbĩ wa Velisia.'),
('kam', 'EZR', 4, 6, 'Na kũsumbĩkanĩ kwa Aasuelo, wambĩlĩlyonĩ wa kũsumbĩka kwake, nĩmaandĩkie ndeto sya kũmavinganĩsya ala matwĩe Yuta na Yelusaleme.'),
('kam', 'EZR', 4, 7, 'Na mĩthenya ya Alitasasita, Mbisilamu na Mithiletathi na Taveeli, na atindan’ya make ala angĩ mamũandĩkĩa Alitasasita mũsumbĩ wa Velisia; na maandĩko ma valũa maandĩkĩtwe na ndeto sya Kĩsilia, na maalyũlwa kĩthyomonĩ kya Kĩsilia.'),
('kam', 'EZR', 4, 8, 'Leumu mũtwi na Simisai mũandĩki mamũandĩkĩa mũsumbĩ Alitasasita valũa ũndũ wa Yelusaleme ũilyĩ ũũ:'),
('kam', 'EZR', 4, 9, 'nĩvo ĩndĩ mũtwi Leumu na mũandĩki Simisai maandĩkie, o na atindan’ya moo ala angĩ, Andina, na Aavalisathiki, na Ataliveli, na Aavalisi, na Aalikevi, na Ambaviloni, na Asusaniki, na Andea, na Aelamu,'),
('kam', 'EZR', 4, 10, 'na mbaĩ ila ingĩ ila Osinavali mũnene na wa nguma waietie, na asia ndũanĩ ya Samalia, na nthĩ ĩngĩ ĩla yatialile mũingo wa ũla Ũsĩ, o ta ũu.'),
('kam', 'EZR', 4, 11, 'Ũũ nĩw’o wumĩĩsyo wa valũa ũla mamũtwaĩe mũsumbĩ Alitasasita: Athũkũmi maku, ithyĩ andũ ala twĩ mũingo wa ũla Ũsĩ, nũvoo.'),
('kam', 'EZR', 4, 12, 'Ũmanyĩke kwa mũsumbĩ, kana Ayuti ala mambatie kuma kwaku nĩmookie kwitũ Yelusaleme; nĩmeũtũngĩĩa ĩla ndũa ng’endu na nthũku, na nĩmaminĩte maũvai, na nĩmaseũvĩtye myambĩlĩlyo.'),
('kam', 'EZR', 4, 13, 'Na yu ũmanyĩke kwa mũsumbĩ, ethĩwa ndũa ĩsu ĩkatũngĩĩwa, na maũvai makathela, matikaumya koti, kana mũvothi, kana ũelo, na mũminũkĩlyo kũkeethĩwa wasyo kwa asumbĩ.'),
('kam', 'EZR', 4, 14, 'Yu ĩndĩ nĩkwĩthĩwa nĩtũĩsaa mũnyũ wumaa nyũmbanĩ nene ya mũsumbĩ, na kũtiaĩle kwitũ kwona mũsumbĩ aianangĩwa ndaĩa, kwondũ wa ũu nĩtũtũmanĩte na kũmanyĩthya mũsumbĩ;'),
('kam', 'EZR', 4, 15, 'nĩ kana kũmanthwe ĩvukunĩ ya molilikan’yo ma aaĩthe maku: now’o wĩona ĩvukunĩ ya molilikan’yo na ũkamanya ndũa ĩsu nĩ ndũa ng’endu, na yĩ wasyo kwa asumbĩ o na ilungunĩ nene sya nthĩ, na nĩmambĩlĩĩlye ũng’endu nthĩnĩ wayo kuma tene; na kwondũ wa ũndũ ũsu ndũa ĩno nĩyatw’ĩkĩthiwe ĩanzo.'),
('kam', 'EZR', 4, 16, 'Twĩmanyĩthya mũsumbĩ atĩĩ, ethĩwa ndũa ĩno ĩkatũngĩĩwa, na maũvai makathela, kwondũ wa ũndũ ũsu ndũkethĩwa na kĩanda mũingo wa ũla Ũsĩ.'),
('kam', 'EZR', 4, 17, 'Nĩvo ĩndĩ mũsumbĩ waetie ũsũngĩo kwa mũtwi Leumu, na kwa mũandĩki Simisai, na atindan’ya moo angĩ ala matwĩe Samalia, na ala angĩ mũingo wa ũla Ũsĩ: Mũuo, nũvoo.'),
('kam', 'EZR', 4, 18, 'Valũa ũla mwatũeteie nũsometwe nesa vala nĩĩ.'),
('kam', 'EZR', 4, 19, 'Nakwa natw’a, na kwamanthwa, na kwamanyĩka kana ndũa ĩsu tene nĩyamang’endeie asumbĩ, na ũlei na ũng’endu nĩsyeekiwe nthĩnĩ wayo.'),
('kam', 'EZR', 4, 20, 'O na kwaĩ asumbĩ maĩ vinya ala masumbĩkie Yelusaleme, ala masumbĩkie nthĩ yonthe mũingo wa ũla Ũsĩ; na maumĩw’a koti, na mũvothi, na ũelo.'),
('kam', 'EZR', 4, 21, 'Yu umyai ũtw’ĩo wa kũmaekethya andũ asu, o na ndũa ĩsu ndĩkatũngĩĩwe, kũvika yĩla ngaumya ũtw’ĩo.'),
('kam', 'EZR', 4, 22, 'Na sisyai mũtikaleele ũndũnĩ ũsu: wanangĩko wingĩvĩĩa kĩ asumbĩ mone wasyo?'),
('kam', 'EZR', 4, 23, 'Na ĩndĩ yĩla wumĩĩsyo wa valũa wa mũsumbĩ Alitasasita wasomewe vala ve Leumu na mũandĩki Simisai, na atindan’ya moo, nĩmamaendee Ayuti ku Yelusaleme mĩtũkĩ, na mamaekethya kwa ũng’endu na vinya.'),
('kam', 'EZR', 4, 24, 'Nĩvo ĩndĩ wĩa wa nyũmba ya Ngai ĩla yĩ Yelusaleme waekiwe; na waekiwe kũvika mwaka wa kelĩ wa kũsumbĩka kwa Ndalio mũsumbĩ wa Velisia.'),
('kam', 'EZR', 5, 1, 'Na ĩndĩ athani, mwathani Akai, na Nzekalia mwana wa Ito, mamathanĩa Ayuti ala maĩ Yuta na Yelusaleme; syĩtwanĩ ya Ngai wa Isilaeli mamathanĩa.'),
('kam', 'EZR', 5, 2, 'Nĩvo ĩndĩ Nzeluvaveli mwana wa Sealitieli, na Yesua mwana wa Yosataki, mookĩlile na mambĩlĩlya kũtũngĩĩa nyũmba ya Ngai ĩla yĩ Yelusaleme; na vamwe nao kwaĩ athani ma Ngai, makĩmatethya.'),
('kam', 'EZR', 5, 3, 'Ĩvinda o yĩu Tatenai, ngavana wa mũingo wa ũla Ũsĩ, na Sethali‐mbosenai, na atindan’ya moo, mooka vala maĩ, na mamakũlya, Nũũ wamũnengie ũtw’ĩo wa kũtũngĩĩa nyũmba ĩno, na kũminũkĩlya wako ũũ?'),
('kam', 'EZR', 5, 4, 'Nĩvo ĩndĩ twamatavisye atĩĩ, ũndũ masyĩtwa ma andũ ala mekwaka wako ũũ metawa.'),
('kam', 'EZR', 5, 5, 'Ĩndĩ itho ya Ngai woo yaĩ ĩũlũ wa atumĩa ma Ayuti, na matyaamaekethya, kũvika ũvoo ũmũvikĩe ndalio, na aimatũngĩa ũsũngĩo na valũa ũndũ wa ũndũ ũsu.'),
('kam', 'EZR', 5, 6, 'Wumĩĩsyo wa valũa ũla Tatenai, ngavana wa mũingo wa ũla Ũsĩ, na Sethali‐mbosenai, na atindan’ya make Aavalisaki, ala maĩ mũingo wa ũla Ũsĩ, matwaĩe mũsumbĩ Ndalio;'),
('kam', 'EZR', 5, 7, 'nĩmamũtwaĩe valũa ũla waandĩkiwe nthĩnĩ waw’o atĩĩ: Kwa mũsumbĩ Ndalio, mũuo w’onthe.'),
('kam', 'EZR', 5, 8, 'Ũmanyĩke kwa mũsumbĩ, atĩ nĩtwaendie Yuta kĩlungu kĩnene kya nthĩ, nyũmbanĩ ya Ngai mũnene, ĩla ĩnĩũtũngĩĩwa na mavia manene, na mĩtĩ yĩkĩtwe mawakonĩ; na wĩa ũsu nũendeee na kĩthing’ĩĩsyo na nũkwaĩla mokonĩ moo.'),
('kam', 'EZR', 5, 9, 'Nĩvo ĩndĩ twakũlilye atumĩa asu, na twamea atĩĩ, Nũũ ũla wamũnengie ũtw’ĩo wa kũtũngĩĩa nyũmba ĩno, na kũminũkĩlya wako ũũ?'),
('kam', 'EZR', 5, 10, 'O na twamakũlya masyĩtwa moo, tũkũmanyĩthye, nĩ kana tũandĩke masyĩtwa ma andũ ala maĩ atongoi moo.'),
('kam', 'EZR', 5, 11, 'Na ũũ nĩw’o ũsũngĩo matũsũngĩie, makyasya, Ithyĩ twĩ athũkũmi ma Ngai wa ĩtunĩ na nthĩ, na nĩtũũtũngĩĩa nyũmba ĩla yaakiwe myaka ĩno mingĩ mĩvĩtu, ĩla mũsumbĩ mũnene wa Isilaeli wakie yathela.'),
('kam', 'EZR', 5, 12, 'Ĩndĩ ĩtina wa aaĩthe maitũ mamũthatya Ngai wa ĩtunĩ, nĩwamanenganie kw’okonĩ kwa Nevukatilesa mũsumbĩ wa Mbaviloni, Mũkalitei, ũla wanangie nyũmba ĩno, na amatwaa andũ Mbaviloni.'),
('kam', 'EZR', 5, 13, 'Ĩndĩ mwaka wa mbee wa kũsumbĩka kwa Kulusi mũsumbĩ wa Mbaviloni, mũsumbĩ Kulusi nĩwatwie ũtw’ĩo kana nyũmba ĩno ya Ngai ĩtũngĩĩwe.'),
('kam', 'EZR', 5, 14, 'O na mĩio ya thaavu na vetha ya nyũmba ya Ngai, ĩla Nevukatilesa waumisye ĩkalũnĩ yĩla yaĩ Yelusaleme, na amĩete ĩkalũni ya Mbaviloni, ĩsu mũsumbĩ Kulusi aumya ĩkalũnĩ ya Mbaviloni, na yanengwa mũndũ ũmwe ũla wetawa syĩtwa yake Sesivasali, ũla wamũtw’ĩkĩthisye ngavana;'),
('kam', 'EZR', 5, 15, 'na amwĩa, Osa mĩio ĩno, ũende, ũmĩkĩe ĩkalũnĩ yĩla yĩ Yelusaleme, na nyũmba ya Ngai ĩtũngĩĩwe vandũ vayo.'),
('kam', 'EZR', 5, 16, 'Nĩvo ĩndĩ Sesivasali ũsu wokie, na akwatya myambĩlĩlyo ya nyũmba ya Ngai ĩla yĩ Yelusaleme: na kuma ĩvinda yĩu kũvika o na yu no yakawa, ĩndĩ o na yu ndĩnathela.'),
('kam', 'EZR', 5, 17, 'Yu kwondũ wa ũu, ethĩwa mũsumbĩ nũkwona nĩ ũseo, nĩkũmanthwe nyũmbanĩ ya kwia mothwii ya mũsumbĩ, ĩla yĩ Mbaviloni, ethĩwa ũũ nĩw’o, atĩ ũtw’ĩo nĩwatwiwe nĩ mũsumbĩ Kulusi kana nyũmba ĩno ya Ngai ĩtũngĩĩwe kũũ Yelusaleme: na mũsumbĩ natũmanyĩthye kwenda kwake ũndũnĩ ũsu.'),
('kam', 'EZR', 6, 1, 'Nĩvo ĩndĩ mũsumbĩ Ndalio watie ũtw’ĩo, na kwamanthwa nyũmbanĩ ya mavuku, vala syĩndũ syĩ vata siĩtwe Mbaviloni.'),
('kam', 'EZR', 6, 2, 'Na kwooneka ku Akimetha, nyũmbanĩ nene ya ũsumbĩ ĩla yĩ kĩlungunĩ kĩnene kya nthĩ kĩtawa Metia, ĩvuku ĩkũnze, na nthĩnĩ wayo kwaĩ kũandĩke ũndũ wa ũlilikan’yo atĩĩ:'),
('kam', 'EZR', 6, 3, 'Mwaka wa mbee wa kũsumbĩka kwa mũsumbĩ Kulusi, mũsumbĩ Kulusi nĩwatwie ũtw’ĩo wa atĩĩ: Ũndũ wa nyũmba ya Ngai Yelusaleme, nyũmba nĩkatũngĩĩwe, vandũ va kũthembeaa nthembo, na myambĩlĩlyo yayo ĩkwatwe yĩ vinya; ũtũlu wayo mĩkono mĩongo thanthatũ, na ũthanthau wayo mĩkono mĩongo thanthatũ;'),
('kam', 'EZR', 6, 4, 'yĩ na mĩsoa ĩtatũ ya mavia manene, na mũsoa wa mbwaũ nzaũ: na mbesa sya kũĩvĩa nĩsyumw’e nyũmbanĩ ya mũsumbĩ.'),
('kam', 'EZR', 6, 5, 'O na mĩio ya thaavu na vetha ya nyũmba ya Ngai, ĩla Nevukatilesa waumisye ĩkalũnĩ yĩla yĩ Yelusaleme, na amĩete Mbaviloni, ĩtũngwe, ĩtwawe ĩngĩ ĩkalũnĩ yĩla yĩ Yelusaleme, kĩla ũmwe vandũ vaw’o; naku ũkamĩkĩe nyũmbanĩ ya Ngai.'),
('kam', 'EZR', 6, 6, 'Kwondũ wa ũu yu, Tatenai, ngavana mũingo wa ũla Ũsĩ, na Sethali‐mbosenai, na atindan’ya menyu Aavalisaki, ala me mũingo wa ũla Ũsĩ, ĩvathanei na kw’o:'),
('kam', 'EZR', 6, 7, 'ekanai na wĩa wa nyũmba ĩsu ya Ngai; ngavana wa Ayuti na atumĩa ma Ayuti matũngĩĩe nyũmba ĩsu ya Ngai vandũ vayo.'),
('kam', 'EZR', 6, 8, 'Na ũndũ ũngĩ nĩngũtw’a ũndũ mwĩĩka atumĩa asu ma Ayuti ũndũ wa kũtũngĩĩa nyũmba ĩsu ya Ngai: mbesa sya kũĩvĩa ninengwe andũ asu na kĩthing’ĩĩsyo kuma syĩndũnĩ sya mũsumbĩ, o sya koti wa mũingo wa ũla Ũsĩ, matikasiĩĩwe.'),
('kam', 'EZR', 6, 9, 'Na kĩla me vata nakyo, tũsalũ, o na ndũũme, na tũtena twa malondu, syĩthĩwe nthembo sya kũvĩvĩw’a Ngai wa ĩtunĩ: o na nganũ, na mũnyũ, na mbinyu, na mauta, kwĩanana na ndeto ya athembi ala me Yelusaleme, manengwe syo mũthenya na mũthenya vate kũeka;'),
('kam', 'EZR', 6, 10, 'nĩ kana mamũthembee Ngai wa ĩtunĩ nthembo syĩ mũuke mũseo, na maivoyea thayũ wa mũsumbĩ na wa ana make.'),
('kam', 'EZR', 6, 11, 'O na nĩnĩtw’ĩte ũtw’ĩo, o ũla ũkaalyũla ndeto ĩno, mũamba wĩumw’a nyũmbanĩ yake, nake nĩeũkĩlw’a na kwambwa ĩũlũ waw’o; na nyũmba yake nĩtw’ĩke ũtũnda wa syaa nũndũ wa ũu:'),
('kam', 'EZR', 6, 12, 'na Ngai ũla watumie syĩtwa yake yĩkala vo nang’uthũle asumbĩ onthe na ngo sya andũ ila ikatambũũkya kw’oko kwasyo kũalyũla ndeto isu, syanange nyũmba ĩsu ya Ngai ĩla yĩ Yelusaleme. Nyie Ndalio nĩnĩtw’ĩte ũtw’ĩo, nĩwĩkwe na kĩthing’ĩĩsyo kyonthe.'),
('kam', 'EZR', 6, 13, 'Nĩvo ĩndĩ Tatenai, ngavana wa mũingo wa ũla Ũsĩ, na Sethali‐mbosenai na atindan’ya moo, nĩkwĩthĩwa mũsumbĩ Ndalio nũtũmanĩte, meekie ũu na kĩthing’ĩĩsyo kyonthe.'),
('kam', 'EZR', 6, 14, 'Na atumĩa ma Ayuti nĩmaakie na maathimĩka, kwondũ wa kwathana kwa mwathani Akai na Nzekalia mwana wa Ito. Na nĩmaakie na yathela, kwĩanana na mwĩao wa Ngai wa Isilaeli, na kwĩanana na ũtw’io wa Kulusi, na Ndalio, na Alitasasita mũsumbĩ wa Velisia.'),
('kam', 'EZR', 6, 15, 'Na nyũmba ĩsu yathela mũthenya wa katatũ wa mwei wa Atali ũla waĩ mwakanĩ wa thanthatũ wa kũsumbĩka kwa mũsumbĩ Ndalio.'),
('kam', 'EZR', 6, 16, 'Na ana ma Isilaeli, na athembi na Alivai, na ana ala angĩ ma ala matavĩtwe, malilikana na ũtanu kũvathwa kwa nyũmba ĩsu yĩthĩwe ntheu.'),
('kam', 'EZR', 6, 17, 'Na makĩvatha nyũmba ĩsu ya Ngai yĩthĩwe ntheu nĩmathembie tũsalũ iana, na ndũũme maana elĩ, na tũtena twa malondu maana ana; na nthenge ĩkũmi na ilĩ syĩthĩwe nthembo kwondũ wa naĩ kwondũ wa Isilaeli onthe, kwĩanana na ũtalo wa mbaĩ sya Isilaeli.'),
('kam', 'EZR', 6, 18, 'Na maia athembi nguthunĩ syoo, na Alivai nguthunĩ syoo, kwondũ wa ũthũkũmi wa Ngai, ũla wĩ Yelusaleme; o tondũ kũandĩkĩtwe ĩvukunĩ ya Mose.'),
('kam', 'EZR', 6, 19, 'Na ana ma ala matavĩtwe malilikana vasaka mũthenya wa ĩkũmi na ĩna wa mwei wa mbee.'),
('kam', 'EZR', 6, 20, 'Nũndũ athembi na Alivai nĩmetheetye vamwe; onthe maĩ atheu; na moaa vasaka kwondũ wa ana onthe ma ala matavĩtwe, na kwondũ wa athembi ana‐a‐ĩthe moo, na kwondũ woo ene.'),
('kam', 'EZR', 6, 21, 'Na ana ma Isilaeli ala maumĩte kũtavwanĩ, na onthe ala meevathĩĩe kwoo kuma ũvukunĩ wa mbaĩ sya nthĩ ĩsu, mamanthe Yeova, Ngai wa Isilaeli, asu maya,'),
('kam', 'EZR', 6, 22, 'na malilikana na ũtanu mboka ya kĩmũtũ kĩte ĩlawa mĩthenya mũonza; nũndũ Yeova nũmatanĩthĩtye, na nĩwalyũlĩte ngoo ya mũsumbĩ wa Asuli ĩmelekele, ekĩe moko moo vinya wĩanĩ wa nyũmba ya Ngai, Ngai wa Isilaeli.'),
('kam', 'EZR', 7, 1, 'Na ĩndĩ ĩtina wa maũndũ asu, kũsumbĩkanĩ kwa Alitasasita mũsumbĩ wa Velisia, Esala mwana wa Selaia, mwana wa Asalia, mwana wa Ilikia,'),
('kam', 'EZR', 7, 2, 'mwana wa Salumu, mwana wa Nzatoki, mwana wa Aituvu,'),
('kam', 'EZR', 7, 3, 'mwana wa Amalia, mwana wa Asalia, mwana wa Melaiothi,'),
('kam', 'EZR', 7, 4, 'mwana wa Nzelaia, mwana wa Usisi, mwana wa Mbuki,'),
('kam', 'EZR', 7, 5, 'mwana wa Avisua, mwana wa Vineasi, mwana wa Eleasali, mwana wa Aluni, mũthembi mũnene—'),
('kam', 'EZR', 7, 6, 'Esala o ũsu nĩwambatie kuma Mbaviloni. Na aĩ maũndĩki mũmanyi mĩaonĩ ya Mose, ĩla Yeova, Ngai wa Isilaeli, wanenganĩte; na mũsumbĩ amũnenga ũndũ w’onthe ũla wamwĩtĩtye, kwĩanana na kw’oko kwa Yeova Ngai wake ĩũlũ wake.'),
('kam', 'EZR', 7, 7, 'Na kwambata Yelusaleme amwe ma ana ma Isilaeli, na ma athembi, na Alivai, na aini, na asũvĩi ma mĩomonĩ, na Anethini, mwaka wa mũonza wa kũsumbĩka kwa mũsumbĩ Alitasasita.'),
('kam', 'EZR', 7, 8, 'Nake avika Yelusaleme mwei wa katano, mwaka wa mũonza wa kũsumbĩka kwa ũ mũsumbĩ.'),
('kam', 'EZR', 7, 9, 'Nũndũ mũthenya wa mbee wa mwei wa mbee nĩw’o wambĩlĩlye kwambata kuma Mbaviloni; na mũthenya wa mbee wa mwei wa katano nĩw’o wavikie Yelusaleme, kwĩanana na kw’oko kũseo kwa Ngai wake ĩũlũ wake.'),
('kam', 'EZR', 7, 10, 'Nũndũ Esala eelekeletye ngoo yake amanthe mĩao ya Yeova, na kũmĩka, na kũmanyĩsya Isilaeli myamũlo na motw’ĩo.'),
('kam', 'EZR', 7, 11, 'Na ĩndĩ ũũ nĩw’o wumĩĩsyo wa valũa ũla mũsumbĩ Alitasasita wanengie mũthembi Esala, mũandĩki, o mũandĩki wa ndeto sya mĩao ya Yeova, na wa motw’ĩo make kwa Isilaeli:'),
('kam', 'EZR', 7, 12, 'Alitasasita, mũsumbĩ wa asumbĩ, valũa ũũ wakwa ũmũvikĩe mũthembi Esala, mũandĩki wa mĩao ya Ngai wa ĩtunĩ, mwĩanĩu, nũvoo.'),
('kam', 'EZR', 7, 13, 'Nĩngũtw’a ũtw’ĩo, kana onthe ma andũ ma Isilaeli, na athembi moo, na Alivai, ũsumbĩnĩ wakwa, ala mekwenda na ngoo yoo ene kũthi Yelusaleme, maende naku.'),
('kam', 'EZR', 7, 14, 'Nũndũ nũtũmĩtwe nĩ mũsumbĩ na atai make mũonza, ũkũlye ũndũ wa Yuta na Yelusaleme, kwĩanana na mwĩao wa Ngai waku ũla wĩ kw’okonĩ kwaku,'),
('kam', 'EZR', 7, 15, 'na ũikua vetha na thaavu, ũla mũsumbĩ na atai make mamumĩsye na ngoo ya kwenda Ngai wa Isilaeli ũla ũtũo wake wĩ Yelusaleme,'),
('kam', 'EZR', 7, 16, 'na vetha na thaavu w’onthe ũla wĩona kĩlungunĩ kĩnene kyonthe kya nthĩ kĩtawa Mbaviloni, vamwe na nthembo ya andũ ĩla yaumiw’e na ngoo ya kwenda, na ya athembi, makĩthemba na ngoo ya kwenda kwondũ wa nyũmba ya Ngai woo ĩla yĩ Yelusaleme;'),
('kam', 'EZR', 7, 17, 'kwondũ wa ũu ũkathooe mĩtũkĩ na mbesa isu, tũsalũ twa mũew’a, na ndũũme, na tũtena twa malondu, na nthembo sya mũtu na nthembo sya kũnyuwa sya kũthembanĩsya nasyo, na ũkaithembe kĩthembeonĩ kya nyũmba ya Ngai wenyu, ĩla yĩ Yelusaleme.'),
('kam', 'EZR', 7, 18, 'Na ũndũ o na wĩva wĩona wĩ ũseo, we na ana‐a‐ĩthe maku, mwĩke na vetha na thaavu ũla ũkatiala, ĩkai ũu kwĩanana na kwenda kwa Ngai wenyu.'),
('kam', 'EZR', 7, 19, 'Na mĩio ĩla ũnengetwe ũndũ wa ũthũkũmi wa nyũmba ya Ngai waku, mĩnengane vala ve Ngai wa Yelusaleme.'),
('kam', 'EZR', 7, 20, 'Na kĩla kĩĩthĩawa vata kũvĩtũka isu ũndũ wa nyũmba ya Ngai waku, kĩla wĩĩthĩawa vata kũnengane, kĩnengane kuma nyũmbanĩ ya kwia mothwii ya mũsumbĩ.'),
('kam', 'EZR', 7, 21, 'Nakwa, o nyie, mũsumbĩ Alitasasita, nĩngũmatw’ĩa ũtw’ĩo asũvĩi onthe ma ũthwii ala me mũingo wa ũla Ũsĩ, atĩ ũndũ o na wĩva ũla mũthembi Esala, mũandĩki wa mĩao ya Ngai wa ĩtunĩ, ũkenda kwenyu, ũndũ ũsu wĩkwe na kĩthing’ĩĩsyo kyonthe,'),
('kam', 'EZR', 7, 22, 'o kũvika talendi ĩana sya vetha, na kũvika ithimi ĩana sya nganũ, na kũvika vathi ĩana sya mbinyu, na kũvika vathi ĩana sya mauta, na mũnyũ vate kũtala ũndũ wĩana.'),
('kam', 'EZR', 7, 23, 'O ũla wĩaĩtwe nĩ Ngai wa ĩtunĩ, nĩwĩkwe ki kwondũ wa nyũmba ya Ngai wa ĩtunĩ; nũndũ kwaĩle kĩ kwĩthĩwa ũthilĩku ĩũlũ wa ũsumbĩ wa mũsumbĩ na ana make?'),
('kam', 'EZR', 7, 24, 'Na ĩngĩ nĩtũũmũmanyĩthya, ũndũ wa athembi o na meva na Alivai, kana aini, kana asũvĩi ma mĩomonĩ, kana Anethini, kana athũkũmi ma nyũmba ĩsu ya Ngai, kũiosana na mĩao kũmaumĩthya koti, kana mũvothi, kana ũelo.'),
('kam', 'EZR', 7, 25, 'Naku we, Esala, kwĩanana na ũĩ wa Ngai waku ũla wĩ kw’okonĩ kwaku, ia amũli na asili, o onthe ala mesĩ mĩao ya Ngai waku, ala matonya kũsilan’ya andũ onthe ala me mũingo wa ũla Ũsĩ; na mũmanyĩsyei ũla ũteũmĩmanya.'),
('kam', 'EZR', 7, 26, 'Na o na ũla ũtakeka mĩao ya Ngai waku, na mĩao ya mũsumbĩ, nasilĩlwe na kĩthito kyonthe, ethĩwa nĩ kũawa, kana kumw’a nthĩ yake, kana kwosewa syĩndũ syake, kana kwovwa.'),
('kam', 'EZR', 7, 27, 'Yeova, Ngai wa aaĩthe maitũ, nataĩwe, ũla wĩkĩĩte mũsumbĩ ũndũ ta ũsu ngoonĩ, amyanakavye nyũmba ya Yeova ĩla yĩ Yelusaleme;'),
('kam', 'EZR', 7, 28, 'na ũmbonee ũseo wĩ wendo vala ve mũsumbĩ, na atai make, na vala ve anene onthe me mbee ũsumbĩnĩ me vinya ma mũsumbĩ. Nakwa nĩneekĩiwe vinya kwĩanana na kw’oko kwa Yeova Ngai wakwa ĩũlũ wakwa, na noomban’ya kuma kwa Isilaeli andũ anene mambate nakwa.'),
('kam', 'EZR', 8, 1, 'Na ĩndĩ aa nĩmo atongoi ma nyũmba sya aaĩthe moo, na aa nĩmo mosyaanĩo ma ala mambatie nakwa kuma Mbaviloni, kũsumbĩkanĩ kwa mũsumbĩ Alitasasita:'),
('kam', 'EZR', 8, 2, 'Wa ana ma Vineasi, nĩ Ngelisoni. Wa ana ma Ithamali, nĩ Ndanieli. Wa ana ma Ndaviti, nĩ Atusi.'),
('kam', 'EZR', 8, 3, 'Wa ana ma Sekania, wa ana ma Valosi, nĩ Nzekalia; na ala maĩ nake mosyaanĩonĩ kwatalilwe aũme ĩana na mĩongo ĩtano.'),
('kam', 'EZR', 8, 4, 'Wa ana ma Vaathi‐moavi, nĩ Elioenai mwana wa Nzelaia; na ala maĩ nake aũme maana elĩ.'),
('kam', 'EZR', 8, 5, 'Wa ana ma Sekania, nĩ mwana wa Yaanzieli; na ala maĩ nake aũme maana atatũ.'),
('kam', 'EZR', 8, 6, 'Na wa ana ma Atini, nĩ Eveti mwana wa Yonathani; na ala maĩ nake aũme mĩongo ĩtano.'),
('kam', 'EZR', 8, 7, 'Na wa ana ma Elamu, nĩ Yesaia mwana wa Athalia; na ala maĩ nake aũme mĩongo mũonza.'),
('kam', 'EZR', 8, 8, 'Na wa ana ma Sevatia, nĩ Nzevatia mwana wa Mikaeli; na ala maĩ nake aũme mĩongo nyanya.'),
('kam', 'EZR', 8, 9, 'Na wa ana ma Yoavu, nĩ Ovatia mwana wa Yeiieli; na ala maĩ nake aũme maana elĩ na ĩkũmi na nyanya.'),
('kam', 'EZR', 8, 10, 'Na wa ana ma Selomithi, nĩ mwana wa Yosiviia; na ala maĩ nake aũme ĩana na mĩongo thanthatũ.'),
('kam', 'EZR', 8, 11, 'Na wa ana ma Mbevai, nĩ Nzekalia mwana wa Mbevai; na ala maĩ nake aũme mĩongo ĩlĩ na nyanya.'),
('kam', 'EZR', 8, 12, 'Na wa ana ma Asikati, nĩ Yoanani mwana wa Akatani; na ala maĩ nake aũme ĩana na ĩkũmi.'),
('kam', 'EZR', 8, 13, 'Na ma ana ma Atonikamu, ala anini; na aa nĩmo masyĩtwa moo: Eliveleti, na Yeueli, na Semaia; na ala maĩ nao aũme mĩongo thanthatũ.'),
('kam', 'EZR', 8, 14, 'Na ma ana ma Mbikivai, nĩ Uthai na Nzavutu; na ala maĩ nao aũme mĩongo mũonza.'),
('kam', 'EZR', 8, 15, 'Nakwa namombanĩsya ũsĩnĩ ũla ũtheeete Aava; na twekala maeemanĩ maitũ kw’o mĩthenya ĩtatũ: na namasisya andũ, o na athembi, na ndyaaona vo ũmwe wa ana ma Livai.'),
('kam', 'EZR', 8, 16, 'Nĩvo ĩndĩ natũmanie Elieseli, na Alieli, na Semaia, na Elinathani, na Yalivu, na Elinathani, na Nathani, na Nzekalia, na Mesulamu, andũ anene; o na Yoialivu, na Elinathani, ala maĩ amanyĩsya.'),
('kam', 'EZR', 8, 17, 'Na namatũma kwa mũnene Ito vandũ vetawa Kasivia; na namatavya ũla memũtavya Ito, na ana‐a‐ĩthe make Anethini, vandũ vau Kasivia, matũetee athũkũmi ma nyũmba ya Ngai waitũ.'),
('kam', 'EZR', 8, 18, 'Na kwĩanana na kw’oko kũseo kwa Ngai waitũ ĩũlũ waitũ matũetee mũndũ wĩ ũmanyi wa ana ma Mali mwana wa Livai, mwana wa Isilaeli; na Selevia, e na ana make na ana‐a‐ĩthe make, ĩkũmi na nyanya;'),
('kam', 'EZR', 8, 19, 'na Asavia, na vamwe nake Yesaia wa ana ma Melali, e na ana‐a‐ĩthe make na ana moo, mĩongo ĩlĩ;'),
('kam', 'EZR', 8, 20, 'na ma Anethini, ala Ndaviti na anene me mbee ũsumbĩnĩ mamaumĩtye ũndũ wa ũthũkũmi wa Alivai, Anethini maana elĩ na mĩongo ĩlĩ: onthe nĩmawetiwe na masyĩtwa.'),
('kam', 'EZR', 8, 21, 'Na ĩndĩ natavan’ya kũtĩĩa ũya ku, ũsĩnĩ wa Aaaa, nĩ kana tũmwĩnyivĩsye Ngai waitũ, tũmanthe kwake nzĩa ndũngalu ũndũ witũ ene, na ũndũ wa syana sitũ nini, na ũndũ wa syĩndũ sitũ syonthe.'),
('kam', 'EZR', 8, 22, 'Nũndũ nĩnĩnasonokie kwĩtya mũsumbĩ nguthu ya asikalĩ na andũ ala matũlite mbalasi matũtethye ũndũ wa amaitha nzĩanĩ, nĩkwĩthĩwa twaĩ tũnaneena na mũsumbĩ, tũkĩmwĩa, Kw’oko kwa Ngai waitũ kwĩ ĩũlũ wa onthe ala mamũmanthaa nĩ kana kũmaetee ũseo; ĩndĩ ũtonyi wake na ũthilĩku wake wĩ ĩũlũ wa onthe ala mamũtiaa.'),
('kam', 'EZR', 8, 23, 'Na ĩndĩ twatĩĩa ũya na twamwĩsũva Ngai waitũ kwondũ wa ũndũ ũsu: nake atwĩthukĩĩsya.'),
('kam', 'EZR', 8, 24, 'Na ĩndĩ naia andũ ĩkũmi na elĩ ma anene ma athembi, o Selevia, na Asavia, na ĩkũmi ma ana‐a‐ĩthe moo vamwe nao,'),
('kam', 'EZR', 8, 25, 'na namathimĩa vetha, na thaavu, na mĩio, o nthembo ũndũ wa nyũmba ya Ngai waitũ, ĩla mũsumbĩ, na atai make, na anene make me mbee ũsumbĩnĩ, na Isilaeli onthe ala maĩ vo, maumisye:'),
('kam', 'EZR', 8, 26, 'nathimĩa kw’okonĩ kwoo talendi sya vetha maana thanthatũ na mĩongo ĩtano, na mĩio ya vetha ya talendi ĩana; na ya thaavu talendi ĩana;'),
('kam', 'EZR', 8, 27, 'na mbakũli mĩongo ĩlĩ sya thaavu, sya ilungu ngili sya thaavu, na mĩio ĩlĩ ya ũthuku mũseo mũkute, yĩ vata ta thaavu.'),
('kam', 'EZR', 8, 28, 'Na namea, Inyw’ĩ mwĩ atheu kwa Yeova, na mĩio nĩ mĩtheu; na vetha na thaavu nĩ nthembo ya kũmumĩsya Yeova, Ngai wa aaĩthe menyu, na ngoo ya kwenda.'),
('kam', 'EZR', 8, 29, 'Syaĩĩsyai, na mũkĩmĩsũvĩa, kũvika yĩla mwĩmĩthima vala ve anene ma athembi na Alivai, na anene me mbee ũsumbĩnĩ ma nyũmba sya aaĩthe ma Isilaeli, ku Yelusaleme, tũsũmbanĩ twa nyũmba ya Yeova.'),
('kam', 'EZR', 8, 30, 'Na ĩndĩ athembi na Alivai moosa vetha na thaavu ũla mathimĩĩwe, vamwe na mĩio, maitwae Yelusaleme nyũmbanĩ ya Ngai waitũ.'),
('kam', 'EZR', 8, 31, 'Nĩvo ĩndĩ twaumie ũsĩ wa Aava mũthenya wa ĩkũmi na ĩlĩ wa mwei wa mbee, tũende Yelusaleme: na kw’oko kwa Ngai waitũ kwaĩ ĩũlũ waitũ, na atumya kw’okonĩ kwa amaitha na ala moveesyaa nzĩanĩ.'),
('kam', 'EZR', 8, 32, 'Na twavika Yelusaleme, na twekala vo mĩthenya ĩtatũ.'),
('kam', 'EZR', 8, 33, 'Na mũthenya wa kana vetha na thaavu na mĩio syathimĩwa nyũmbanĩ ya Ngai waitũ na syanengwa Melemothi mwana wa mũthembi Ulia kw’okonĩ kwake (na vamwe nake kwaĩ Eleasali mwana wa Vineasi: na vamwe nao kwaĩ Yosavati mwana wa Yesua, na Noatia mwana wa Mbinui, Alivai)—'),
('kam', 'EZR', 8, 34, 'syonthe syĩ ndale na syĩ nthime: na ũito w’onthe waandĩkwa ĩvinda yiu.'),
('kam', 'EZR', 8, 35, 'Ana ma ala matavĩtwe, ala maumie kũtavwanĩ, nĩmamũthembee Ngai wa Isilaeli nthembo ya kũvĩvw’a, tũsalũ twa mũew’a ĩkũmi na twĩlĩ ũndũ wa Isilaeli onthe, na ndũũme mĩongo kenda na thanthatũ, na tũtena twa malondu mĩongo mũonza na mũonza, na nthenge ĩkũmi na ilĩ syĩthĩwe nthembo kwondũ wa naĩ: Isu syonthe syaĩ nthembo sya kũvĩvĩw’a Yeova.'),
('kam', 'EZR', 8, 36, 'Na manenga asumbĩ anini, na makavana mũingo wa ũla Ũsĩ, motw’ĩo ma mũsumbĩ: na matethya andũ, na nyũmba ya Ngai.'),
('kam', 'EZR', 9, 1, 'Na ĩndĩ yĩla maũndũ asu mathelile, anene me mbee ũsumbĩnĩ manthengeea, makĩmbĩa, Andũ ma Isilaeli, na athembi na Alivai, matyaaĩvathana na ngo sya andũ ma i nthĩ, ĩndĩ nĩmekaa kwĩanana na mothatyo moo, o ma Akanaani, na Aititi, na Avelisi, na Ayevusi, na Aamimoni, na Amoavi, na Amisili, na Aamoli.'),
('kam', 'EZR', 9, 2, 'Nũndũ nĩmatwaĩte eĩtu moo matw’ĩke aka moo ene na makatwaĩa ana moo, na ĩndĩ ũsyao mũtheu nĩwĩvulanĩtye na ngo sya andũ ma nthĩ isu: ĩĩ, moko ma anene me mbee ũsumbĩnĩ na ma asumbĩki nĩmo matongoesye ĩvĩtyonĩ yĩu.'),
('kam', 'EZR', 9, 3, 'Na yĩla neewie ũvoo ũsu natembũanga ngũa yakwa, o na ngũa yakwa ndasa, na nakũa nzw’ĩĩ sya mũtwe wakwa na kĩng’ew’a kyakwa, na nekala nthĩ nĩ mũthokoanu.'),
('kam', 'EZR', 9, 4, 'Nĩvo ĩndĩ noombanĩwe nĩ kĩla mũndũ ũla watetemiwe nĩ ndeto sya Ngai wa Isilaeli, nũndũ wa ĩvĩtyo ya asu ala matavĩtwe; na nekala nĩ mũthokoanu kũvika kũthemba nthembo ya wĩoo.'),
('kam', 'EZR', 9, 5, 'Na ĩvinda ya nthembo ya wĩoo nookĩla kuma kwĩnyivyanĩ kwakwa, ngũa yakwa o na ngũa yakwa ndasa yĩ ndembũange; na navalũka na mau makwa, na namũtambũũkĩsya Yeova Ngai wakwa moko makwa;'),
('kam', 'EZR', 9, 6, 'na nasya, Ame Ngai wakwa, nĩngũsonoka na kwonan’ya nthoni ũthyũnĩ wakwa ũndũ wa ũkũkĩlĩlya ũthyũ wakwa, Ngai wakwa; nũndũ mothũku maitũ nĩmaingĩvĩte ĩũlũ wa mĩtwe yaitũ, na kũvĩtan’ya kwitũ nĩkũvikĩte matunĩ.'),
('kam', 'EZR', 9, 7, 'Kuma mĩthenya ya aaĩthe maitũ kũvika ũmũnthĩ nĩtwekalile twĩ avĩtan’ya mũno; na nũndũ wa mothũku maitũ, ithyĩ, na asumbĩ maitũ, na athembi maitũ, nĩtũnenganĩtwe kw’okonĩ kwa asumbĩ ma i nthĩ, o kwa ũvyũ, na kũtavwa, na kũvutwa, na kũsonokwa mothyũ, o tondũ tũilyĩ ũmũnthĩ.'),
('kam', 'EZR', 9, 8, 'Na yu kavinda kanini mũno mumo nĩwonanĩtwe kuma kwa Yeova Ngai waitũ, atũtiĩe ũtialo wa kũvonoka, na atũnenge kyambo vandũ vake vatheu, nĩ kana Ngai waitũ atonye kũsalukya metho maitũ, na kũtũvuũkya vanini ũkombonĩ witũ.'),
('kam', 'EZR', 9, 9, 'Nũndũ twĩ ngombo; ĩndĩ Ngai waitũ ndatũtiĩte o na twĩ ũkombonĩ witũ, ĩndĩ nũtwonea ũseo wĩ wendo methonĩ ma asumbĩ ma Velisia, atũnenga ũvuũkyo, tũtũngĩĩe nyũmba ya Ngai waitũ, na tũseũvye kũla kũomboe kwayo, na atũnenge ũvai ku Yuta na Yelusaleme.'),
('kam', 'EZR', 9, 10, 'Na yu, ame Ngai waitũ, twĩasya ata ĩtina wa ũu? Nũndũ nĩtũtiĩte mĩao yaku'),
('kam', 'EZR', 9, 11, 'ĩla weaie na makanyw’a ma athũkũmi maku athani, ũkyasya, nthĩ, ĩla mũendete mũmĩmesye, nĩ nthĩ mbuku ũndũ wa ũvuku wa ngo sya andũ ma i nthĩ, nũndũ wa mothatyo moo, ala mamyusũĩtye kuma ngalĩ ĩmwe kũvika ĩla ĩngĩ na ũvuku woo:'),
('kam', 'EZR', 9, 12, 'yu kwondũ wa ũu mũtikanengane eĩtu menyu kwa ana moo, o na mũtikatwaĩe ana menyu eitũ moo, o na mũtikamamanthĩe mũuo kana ũuno tene na tene; nĩ kana mwĩthĩwe mwĩ vinya, na mũye ũseo wa ĩ nthĩ, na kũmĩtia yĩthĩwe ũtiĩwa wa syana syenyu tene na tene.'),
('kam', 'EZR', 9, 13, 'Na ĩtina wa ũu w’onthe ũla watũkĩtĩkĩe nũndũ wa meko maitũ mathũku, na nũndũ wa kũvĩtan’ya kwitũ kũnene, nĩkwĩthĩwa we Ngai waitũ nũtũkũnĩte ũndũ ũnini kwĩ ũndũ mothũku maitũ maĩlwe, na nũtũnengete ũtialo ũilyĩ ũu,'),
('kam', 'EZR', 9, 14, 'ithyĩ tũkatũla mĩao yaku ĩngĩ, na kũkwatanwa tũtwaanĩthw’e na ngo sya andũ ala mekaa mothatyo asu? Ndũkatũthatĩa mũvaka ũtũmine, kũtikethĩwe ũtialo, kana ũmwe wa kũvonoka?'),
('kam', 'EZR', 9, 15, 'Ame Yeova, Ngai wa Isilaeli, we wĩ mũlũngalu; nũndũ nĩtũtiele ũtialo ũla mũvonoku, o ũndũ ũilyĩ ũmũnthĩ: sisya, twĩ mbee waku twĩ avĩtan’ya; nũndũ vati ũmwe ũtonya kũũngama mbee waku nũndũ wa ũndũ ũsu.'),
('kam', 'EZR', 10, 1, 'Na ĩndĩ yĩla Esala wavoyie na aumbũla, akĩĩa na kwĩvalũkya nthĩ mbee wa nyũmba ya Ngai, nĩwombanĩwe nĩ ũmbano mũnene mũno wa aũme na aka na syana kuma nthĩnĩ wa Isilaeli; nũndũ andũ nĩmaĩie mũno.'),
('kam', 'EZR', 10, 2, 'Na Sekania mwana wa Yeiieli, mwana ũmwe wa Elamu, asũngĩa na amwĩa Esala, Nĩtũmũvĩtanĩsye Ngai waitũ, na nĩtũtwaĩte aka ma nthĩ ĩngĩ ma ngo sya andũ ma ĩ nthĩ: ĩndĩ yu ve wĩkwatyo wa Isilaeli ũndũ wa ũndũ ũsu.'),
('kam', 'EZR', 10, 3, 'Kwondũ wa ũu yu tũtianĩe ũtianĩo na Ngai waitũ tũeke iveti isu syonthe, na ala masyaĩtwe nĩsyo, kwĩanana na ũtao wa mwĩaĩi wakwa, na wa ala matetemaa nũndũ wa mwĩao wa Ngai waitũ; na nĩkwĩkwe kwĩanana na mĩao.'),
('kam', 'EZR', 10, 4, 'Ũkĩla; nũndũ ũvoo nĩ waku, naitũ twĩ vamwe naku: ĩthĩwa na ũkũmbaũ mũnene, nokĩka ũu.'),
('kam', 'EZR', 10, 5, 'Nĩvo ĩndĩ Esala wokĩlile, na amaavĩthya anene ma athembi, na Alivai, na Isilaeli onthe, kana meke kwĩanana na ndeto ĩsu. Na ĩndĩ meeava.'),
('kam', 'EZR', 10, 6, 'Na ĩndĩ Esala ookĩla kuma vu mbee wa nyũmba ya Ngai, na alika kasũmbanĩ ka Yeoanani mwana wa Eliasivu: na avika vo, ndaaya lĩu, kana kũnyw’a manzĩ; nũndũ nĩwewie woo ũndũ wa ĩvĩtyo ya ala matavĩtwe.'),
('kam', 'EZR', 10, 7, 'Na matavan’ya Yuta na Yelusaleme kw’onthe kwa ana onthe ma ala matavĩtwe, mombane Yelusaleme;'),
('kam', 'EZR', 10, 8, 'na o ũla ũtaaũka mĩthenya ĩsu ĩtatũ, kwĩanana na ũtao wa anene me mbee ũsumbĩnĩ na atumĩa, syĩndũ syake syonthe ikooswa, nake mwene akavetwa ũmbanonĩ wa ala matavĩtwe.'),
('kam', 'EZR', 10, 9, 'Na ĩndĩ andũ onthe ma Yuta na Mbenyamini makomana Yelusaleme mĩthenya ĩsu ĩtatũ ĩtanathela (kwaĩ mwei wa kenda, mũthenya wa mĩongo ĩlĩ wa mwei); na andũ onthe mekala vala vandũ vathanthau ngalĩ ya mbee ya nyũmba ya Ngai, makĩtetema nũndũ wa ũndũ ũsu, na nũndũ wa ĩla mbua nene.'),
('kam', 'EZR', 10, 10, 'Na mũthembi Esala aũngama, na amea, Nĩmũvĩtĩtye, na nĩmũtwaĩte aka ma nthĩ ĩngĩ, mwingĩvye ĩvĩtyo ya Isilaeli.'),
('kam', 'EZR', 10, 11, 'Yu ĩndĩ mumbũlĩlei Yeova, Ngai wa aaĩthe menyu, na mũkĩka kwenda kwake; na ĩvathanei na ngo sya andũ ma ĩ nthĩ, na aka ma nthĩ ĩngĩ.'),
('kam', 'EZR', 10, 12, 'Nĩvo ĩndĩ ũmbano w’onthe wasũngĩie, na waneena na wasya mũnene, O ũndũ ũneenete ũndũ witũ, no mũvaka twĩke.'),
('kam', 'EZR', 10, 13, 'Ĩndĩ andũ nĩ aingĩ, na nĩ ĩvinda ya mbua nyingĩ, na tũtitonya kũũngama nza: o na ũũ ti wĩa wa mũthenya ũmwe kana ĩlĩ; nũndũ nĩtũvĩtĩtye mũno ũndũnĩ ũsu.'),
('kam', 'EZR', 10, 14, 'Yu anene maitũ me mbee ũsumbĩnĩ maiwe kwondũ wa ũmbano w’onthe, na onthe ala me ndũanĩ sitũ ala matwaĩte aka ma nthĩ ĩngĩ nĩmoke mavinda matw’ĩĩtwe, na vamwe nao atumĩa ma kĩla ndũa, na asili masyo, kũvika ũthilĩku mwai wa Ngai waitũ ũthyũũwe wume kwitũ, kũvika ũndũ ũsu ũthele.'),
('kam', 'EZR', 10, 15, 'No Yonathani mwana wa Asaeli na Yaseia mwana wa Tikiva maũngamie na kũlea ũndũ ũsu: na Mesulamu na Savethai Mũlivai mamatethya.'),
('kam', 'EZR', 10, 16, 'Na ana ma ala matavĩtwe meeka ũu. Na mũthembi Esala, vamwe na atongoi amwe ma nyũmba sya aaĩthe, kũatĩĩa nyũmba sya aaĩthe moo, na onthe kũatĩĩa masyĩtwa moo, maiwa; na makela nthĩ mũthenya wa mbee wa mwei wa ĩkũmi masũanĩe ũndũ ũsu.'),
('kam', 'EZR', 10, 17, 'Na mamina na andũ onthe ala matwaĩte aka ma nthĩ ĩngĩ mũthenya wa mbee wa mwei wa mbee.'),
('kam', 'EZR', 10, 18, 'Na ananĩ ma athembi kwooneka ala matwaĩte aka ma nthĩ ĩngĩ; asu nĩmo aa, ma ana ma Yesua, nĩ mwana wa Yosataki, na ana‐a‐ĩthe make, Maaseia, na Elieseli, na Yalivu, na Ngetalia.'),
('kam', 'EZR', 10, 19, 'Nao manengane mĩkono kana nĩmeũeka iveti syoo; na nĩkwĩthĩwa maĩ na ĩvĩtyo, nĩmathembie ndũũme ya ndĩthyanĩ ũndũ wa ĩvĩtyo yoo.'),
('kam', 'EZR', 10, 20, 'Na ma ana ma Imeli: Aanani na Sevatia.'),
('kam', 'EZR', 10, 21, 'Na ana ma Alimu: Maaseia, na Eliya, na Semaia, na Yeiieli, na Usia.'),
('kam', 'EZR', 10, 22, 'Na ma ana ma Vasuli: Elioenai, na Maaseia, na Isumaeli, na Nethaneli, na Yosavati, na Elasa.'),
('kam', 'EZR', 10, 23, 'Na ma Alivai: Yosavati, na Simei, na Kelaia (nĩwe Kelita), na Vethaia, na Yuta, na Elieseli.'),
('kam', 'EZR', 10, 24, 'Na ma aini: Eliasivu. Na ma asũvĩi ma mĩomonĩ: Salumu, na Telemu, na Uli.'),
('kam', 'EZR', 10, 25, 'Na ma Isilaeli: Ma ana ma Valosi: Lamia, na Isia, na Malikiya, na Miyamini, na Eleasali, na Malikiya, na Mbenaia.'),
('kam', 'EZR', 10, 26, 'Na ma ana ma Elamu: Matania, na Nzekalia, na Yeiieli, na Avati, na Yelemothi, na Eliya.'),
('kam', 'EZR', 10, 27, 'Na ma ana ma Nzatu: Elioenai, na Eliasivu, na Matania, na Yelemothi, na Nzavati, na Asisa.'),
('kam', 'EZR', 10, 28, 'Na ma ana ma Mbevai: Yeoanani, na Aanania, na Nzavai, na Athilai.'),
('kam', 'EZR', 10, 29, 'Na ma ana ma Mbani: Mesulamu, na Maluku, na Ataia, na Yasuvu, na Seali, na Yelemothi.'),
('kam', 'EZR', 10, 30, 'Na ma ana ma Vaathi‐moavi: Atena, na Kelali, na Mbenaia, na Maaseia, na Matania, na Mbesaleli, na Mbinui, na Manase.'),
('kam', 'EZR', 10, 31, 'Na ma ana ma Alimu: Elieseli, na Isiya, na Malikiya, na Semaia, na Simeoni,'),
('kam', 'EZR', 10, 32, 'na Mbenyamini, na Maluku, na Semalia.'),
('kam', 'EZR', 10, 33, 'Na ma ana ma Asumu: Matenai, na Matatha, na Nzavati, na Eliveleti, na Yelemai, na Manase, na Simei.'),
('kam', 'EZR', 10, 34, 'Ma ana ma Mbani: Maatai, na Amilamu, na Ueli,'),
('kam', 'EZR', 10, 35, 'na Mbenaia, na Mbeteia, na Kelui,'),
('kam', 'EZR', 10, 36, 'na Vania, na Melemothi, na Eliasivu,'),
('kam', 'EZR', 10, 37, 'na Matania, na Matenai, na Yaasu,'),
('kam', 'EZR', 10, 38, 'na Mbani, na Mbinui, na Simei,'),
('kam', 'EZR', 10, 39, 'na Selemia, na Nathani, na Ataia,'),
('kam', 'EZR', 10, 40, 'na Makinatevai, na Sasai, na Sialai,'),
('kam', 'EZR', 10, 41, 'na Asaleeli, na Selemia, na Semalia,'),
('kam', 'EZR', 10, 42, 'na Salumu, na Amalia, na Yosevu.'),
('kam', 'EZR', 10, 43, 'Ma ana ma Nevo: Yeieli, na Matithia, na Nzavati, na Nzevina, na Ito, na Yoeli, na Mbenaia.'),
('kam', 'EZR', 10, 44, 'Asu onthe nĩmatwaĩte aka ma nthĩ ĩngĩ; na amwe moo maĩ na iveti ila syamasyaĩe syana.'),
('kam', 'NEH', 1, 1, 'Ndeto sya Neemia mwana wa Akalia. Na kweethĩwa mwei wa Kiselevu, mwaka wa mĩongo ĩlĩ, yĩla naĩ nyũmbanĩ nene ya ũsumbĩ ku Susani,'),
('kam', 'NEH', 1, 2, 'Aanani ooka, ũmwe wa ana‐a‐asa makwa, we na andũ amwe ala maumĩte Yuta; na namakũlya ũvoo wa Ayuti ala mavonokie ala matialile ma ala matavĩtwe, na ũvoo wa Yelusaleme.'),
('kam', 'NEH', 1, 3, 'Na mambĩa, Ũtialo ũla ũtialĩte wa ala matavĩtwe ku kĩlungunĩ kyu kĩnene kya nthĩ wĩ na thĩna mũnene na kũvũthw’a: o na ũvai wa Yelusaleme naw’o nĩ mũomboku, na mbingĩlo syayo nivĩvĩtw’e na mwaki.'),
('kam', 'NEH', 1, 4, 'Na kweethĩwa, yĩla neewie ndeto isu, nekala nthĩ na naĩa, na nameta mĩthenya ĩmwe; na natĩĩa ũya na navoya mbee wa Ngai wa ĩtunĩ,'),
('kam', 'NEH', 1, 5, 'na nasya, Nĩngũkwĩsũva, ame Yeova, Ngai wa ĩtunĩ, Ngai mũnene na wa kũtĩsya, ũla wĩanĩasya ũtianĩo na ũseo wĩ wendo kwa ala mamwendaa na kũkwataa mĩao yake:'),
('kam', 'NEH', 1, 6, 'yu kũtũ kwaku nĩkwĩthukĩĩsye, na metho maku methĩwe masalukĩtye, nĩ kana wĩthukĩĩsye kũvoya kwa mũthũkũmi waku, kũla ngũvoya nĩ mbee waku ĩvinda yĩĩ, mũthenya na ũtukũ, ũndũ wa ana ma Isilaeli athũkũmi maku, yĩla ngumbũla naĩ sya ana ma Isilaeli, ila twakũvĩtanĩĩsye. Ĩĩ, nyie na nyũmba ya asa wakwa nĩtũvĩtĩtye:'),
('kam', 'NEH', 1, 7, 'nĩtũkwĩkĩte naĩ mũno, na tũtyasũvĩaa mĩao, kana myamũlo, kana motw’ĩo, ala wamwĩaĩe Mose mũthũkũmi waku.'),
('kam', 'NEH', 1, 8, 'Nĩngũkwĩsũva, lilikana ndeto ĩla wamwĩaĩe mũthũkũmi waku Mose, ũkĩmwĩa, Ethĩwa mũkavĩtya, ngamũnyaĩĩkya katĩ wa ngo sya andũ:'),
('kam', 'NEH', 1, 9, 'ĩndĩ ethĩwa mũkanzyokea, na kũkwataa mĩao yakwa na kũmĩkaa, o na ethĩwa alũngw’a menyu me ngalĩko ya mũminũkĩlyo ya matu, kuma vau ngamomban’ya, na ngamaete vandũ vala nĩnyuvĩte, nĩkalye syĩtwa yakwa vo.'),
('kam', 'NEH', 1, 10, 'Na ĩndĩ aa nĩo athũkũmi maku na andũ maku, ala ũmovoetye na vinya waku mũnene, na kw’oko kwaku kwĩ vinya.'),
('kam', 'NEH', 1, 11, 'Ame Mwĩaĩi, nĩngũkwĩsũva, kũtũ kwaku yu nĩkwĩthukĩĩsye kũvoya kwa mũthũkũmi waku, na kũvoya kwa athũkũmi maku, ala matanĩaa kũkĩa syĩtwa yaku; na nĩngũkwĩsũva, ũmũathime mũthũkũmi waku ũmũnthĩ, na ũimwĩw’ĩa tei methonĩ ma mũndũ ũũ. (Na ĩndĩ naĩ mũnengi wa mũsumbĩ mbinyu.)'),
('kam', 'NEH', 2, 1, 'Na kweethĩwa mwei wa Nisani, mwaka wa mĩongo ĩlĩ wa kũsumbĩka kwa mũsumbĩ Alitasasita, yĩla mbinyu yaĩ mbee wake, noosa mbinyu na namũnenga mũsumbĩ. Nakwa ndyaatukya ũthyũ wakwa nĩ mbee wake ĩvinda o na yĩva.'),
('kam', 'NEH', 2, 2, 'Na mũsumbĩ angũlya, Ũtukĩtye ũthyũ waku nĩkĩ, na ndwĩ mũwau? Ũũ ti ũndũ ũngĩ ate o woo wa ngoo. Nĩvo ĩndĩ nakwatiwe nĩ w’ĩa mũnene.'),
('kam', 'NEH', 2, 3, 'Na namwĩa mũsumbĩ, Mũsumbĩ nĩekale thayũ tene na tene: ũthyũ wakwa ũlea kũtuka nĩkĩ, yĩla ndũa, vandũ va ngunga sya aaĩthe makwa vala vathikawa akw’ũ, nĩ ĩanzo, na mbingĩlo syayo nĩvĩvĩtw’e na mwaki?'),
('kam', 'NEH', 2, 4, 'Nĩvo ĩndĩ mũsumbĩ wangũlilye, Wĩenda ata? Na ĩndĩ navoya Ngai wa itunĩ.'),
('kam', 'NEH', 2, 5, 'Na namwĩa mũsumbĩ, Ethĩwa mũsumbĩ nũkwendeew’a, na ethĩwa mũthũkũmi waku nĩwonete ũseo vala ũĩ, nĩenda ũndũme ku Yuta, ndũanĩ yĩ ngunga sya aaĩthe makwa vala vathikawa akw’ũ, nĩmĩtũngĩĩe.'),
('kam', 'NEH', 2, 6, 'Na mũsumbĩ angũlya (kĩveti kyake nakyo kyekalĩte vamwe nake), Kyalo kyaku kĩkeethĩwa kya ĩvinda yĩana ata? Na ũkasyoka ĩndĩĩ? Na ĩndĩ mũsumbĩ nĩwendeew’e nĩ kũndũma; nakwa namũtavya ĩvinda.'),
('kam', 'NEH', 2, 7, 'Na ĩngĩ namwĩa mũsumbĩ, Ethĩwa nĩkũmwendeesya mũsumbĩ, nĩnengwe mavalũa, nĩmatwaĩe makavana ala me mũingo wa ũla Ũsĩ, nĩ kana manenge ũthei nĩvĩte mũvaka nĩvike Yuta;'),
('kam', 'NEH', 2, 8, 'na valũa wa kũmũtwaĩa Asavu, mũsũvĩi wa mũtitũ wa mũsumbĩ, nĩ kana anenge mĩtĩ nĩseũvye mĩamba ya mbingĩlo sya nyũmba nene yĩ kĩemo ĩla ĩkwatanĩte na ĩ nyũmba, na ya ũvai wa ndũa, na ya nyũmba ĩla nĩmĩlika. Na mũsumbĩ nĩwanengie, kwĩanana na kw’oko kũseo kwa Ngai wakwa ĩũlũ wakwa.'),
('kam', 'NEH', 2, 9, 'Na ĩndĩ navika kwa makavana mũingo wa ũla Ũsĩ, na namanenga mavalũa ma mũsumbĩ. Na mũsumbĩ atũmĩte vamwe nakwa makavuteni ma ita na andũ matũlĩte mbalasi.'),
('kam', 'NEH', 2, 10, 'Na yĩla Sanavalati Mũoloni, na mũthũkũmi Tovia, Mũamimoni, meewie ũu, nĩmeewie woo nũndũ nĩkũkĩte mũndũ ũla ũkwenda kũmamanthĩa ana ma Isilaeli ũseo.'),
('kam', 'NEH', 2, 11, 'Na ĩndĩ navika Yelusaleme, na naĩ vo mĩthenya ĩtatũ.'),
('kam', 'NEH', 2, 12, 'Na nookĩla ũtukũ, nyie na andũ amwe avũthũ; o na ndyaatavya mũndũ o na wĩva ũla Ngai wakwa wĩkĩĩte ngoonĩ yakwa nĩwĩke kwondũ wa Yelusaleme; o na ndyaĩ na nyamũ, ate o ĩla nyamũ natũlĩte.'),
('kam', 'NEH', 2, 13, 'Na naumaala ũtukũ na mbingĩlo ya kyandanĩ, nelekele kĩthima kya nzoka, na kũvika mbingĩlo ya kumĩlya vũũ, na nasisya maũvai ma Yelusaleme, ala maomboetwe, na mbingĩlo syamo syaĩ mbĩvye na mwaki.'),
('kam', 'NEH', 2, 14, 'Nĩvo ĩndĩ naendeeie kũvika mbingĩlo ya nthongo ya manzĩ o na ndianĩ ya mũsumbĩ: ĩndĩ vatyaĩ vandũ nyamũ ĩla yanguĩte ĩvĩtĩla.'),
('kam', 'NEH', 2, 15, 'Nĩvo ĩndĩ nambatie ũtukũ vakuvĩ na kalũsĩ, na nasisya ũvai; na neetulũla, na navota na mbingĩlo ya kyandanĩ, na ũu nasyoka.'),
('kam', 'NEH', 2, 16, 'Na asumbĩki matyaamanya vala naendie, kana ũndũ neekie; o na ndyamatavĩtye Ayuti, kana athembi, kana anene me ndaĩa, kana asumbĩki, o na angĩ ala matethasya wĩa.'),
('kam', 'NEH', 2, 17, 'Nĩvo ĩndĩ nameie, Nĩmũkwona ũndũ ũũ ũthũku ũla twĩ naw’o, ũndũ Yelusaleme nĩ ĩanzo, na mbingĩlo syayo nĩ mbĩvye na mwaki: ũkai, tũtũngĩĩe ũvai wa Yelusaleme, nĩ kana tũtikethĩwe ma kũvũthw’a ĩngĩ.'),
('kam', 'NEH', 2, 18, 'Na namatavya ũndũ wa kw’oko kwa Ngai wakwa kũla kũseo ĩũlũ wakwa, o na ũndũ wa ndeto sya mũsumbĩ ila waneenete nakwa. Nao masya, Tũkĩlei twake. Na ĩndĩ nĩmeekĩie moko moo vinya kwondũ wa wĩa ũsu mũseo.'),
('kam', 'NEH', 2, 19, 'Ĩndĩ yĩla Sanavalati Mũoloni, na mũthũkũmi Tovia, Mũamimoni, na Ngesemu Mwalavu, meewie ũu, matũthekeea mũno, na matũvũthĩĩsya, na makũlya, Ũndũ ũũ mũkwĩka nĩ mwaũ? Mũkamũng’endeea mũsumbĩ?'),
('kam', 'NEH', 2, 20, 'Nĩvo ĩndĩ namasũngĩie, na namea, Ngai wa ĩtunĩ akatũathima; kwondũ wa ũu ithyĩ athũkũmi make tũkookĩla na kwaka: ĩndĩ inyw’ĩ mũti na kĩanda, kana kĩlungu, kana ũlilikan’yo, Yelusaleme.'),
('kam', 'NEH', 3, 1, 'Nĩvo ĩndĩ mũthembi mũnene Eliasivu wokĩlile vamwe na ana‐a‐ĩthe athembi, na matũngĩĩa mbingĩlo ya malondu; mamĩvathan’ya yĩthĩwe ntheu, na maũngamya mĩomo yayo; o na mamĩvathan’ya kũvika mwako mũtũlu wa mũnyoolo wa Ananeli.'),
('kam', 'NEH', 3, 2, 'Na ĩtina wake andũ ma Yeliko maaka. Na ĩtina woo Nzakuli mwana wa Imili aaka.'),
('kam', 'NEH', 3, 3, 'Na ana ma Asenaa maaka mbingĩlo ya makũyũ; na meekĩa mĩamba yayo, na maũngamya mĩomo yayo, na meekĩa ivingi syayo, na ivingo syayo.'),
('kam', 'NEH', 3, 4, 'Na ĩtina woo Melemothi mwana wa Uliya, mwana wa Akosi, atũngĩĩa. Na ĩtina woo Mesulamu mwana wa Mbelekia, mwana wa Mesesaveli, atũngĩĩa. Na ĩtina woo Nzatoki mwana wa Mbaana atũngĩĩa.'),
('kam', 'NEH', 3, 5, 'Na ĩtina woo Atekoa matũngĩĩa; ĩndĩ anene me ndaĩa moo matyaalikya ngingo syoo wĩanĩ wa mwĩaĩi woo.'),
('kam', 'NEH', 3, 6, 'Na mbingĩlo ya tene yatũngĩĩwa nĩ Yoiata mwana wa Vasea na Mesulamu mwana wa Mbesoteia; maia mĩamba yayo, na maũngamya mĩomo yayo, na meekĩa ivingi syayo, na ivingo syayo.'),
('kam', 'NEH', 3, 7, 'Na ĩtina woo Melatia Mũngiveoni, na Yatoni Mũmelonothi, andũ ma Ngiveoni, na ma Misiva, matũngĩĩa, ala ma kĩvĩla kya ũsumbĩ kya ngavana mũingo wa ũla Ũsĩ.'),
('kam', 'NEH', 3, 8, 'Na ĩtina woo Usieli mwana wa Aliaia, wa atwii ma thaavu, atũngĩĩa. Na ĩtina wake Aanania ũmwe wa aseũvya ma manukato atũngĩĩa, nao malũlũmĩlya Yelusaleme o kũvika ũvai mũthanthau.'),
('kam', 'NEH', 3, 9, 'Na ĩtina woo Lavaia mwana wa Uulu atũngĩĩa, mũsumbĩki wa nyunzu ya kĩvalo kya Yelusaleme.'),
('kam', 'NEH', 3, 10, 'Na ĩtina woo Yetaia mwana wa Alumavu atũngĩĩa, kwelekela nyũmba yake. Na ĩtina wake Atusi mwana wa Asavineia atũngĩĩa.'),
('kam', 'NEH', 3, 11, 'Malikiya mwana wa Alimu, na Asuvu mwana wa Vaathi‐moavi, matũngĩĩa kĩlungu kĩngĩ, na mwako mũtũlu wa mũnyoolo wĩ maiko manene.'),
('kam', 'NEH', 3, 12, 'Na ĩtina wake Salumu mwana wa Aloesi, mũsumbĩki wa nyunzu ya kĩvalo kya Yelusaleme, atũngĩĩa, we na eĩtu make.'),
('kam', 'NEH', 3, 13, 'Anuni na ala matwĩe Nzanoa matũngĩĩa mbingĩlo ya kyandanĩ; mamyaka, na maũngamya mĩomo yayo, na meekĩa ivingi syayo, na ivingo syayo, na matũngĩĩa mĩkono ngili ya ũvai kũvika mbingĩlo ya kumĩlya vũũ.'),
('kam', 'NEH', 3, 14, 'Na Malikiya mwana wa Lekavi, mũsumbĩki wa kĩvalo kya Mbethi‐akelemu, atũngĩĩa mbingĩlo ya kumĩlya vũũ; amyaka, na aũngamya mĩomo yayo, na eekĩa ivingi syayo, na ivingo syayo.'),
('kam', 'NEH', 3, 15, 'Na Saluni mwana wa Koli‐ose, mũsumbĩki wa kĩvalo kya Misiva, atũngĩĩa mbingĩlo ya nthongo ya manzĩ; amyaka, na amĩvw’ĩka, na aũngamya mĩomo yayo, na eekĩa ivingi syayo, na ivingo syayo, o na ũvai wa ndia ya Siela vakuvĩ na mũũnda wa mũsumbĩ, o kũvika mbasyanĩ ĩla ĩtheeete kuma ndũanĩ ya Ndaviti.'),
('kam', 'NEH', 3, 16, 'Na ĩtina wake Neemia mwana wa Asivuki, mũsumbĩki wa nyunzu ya kĩvalo kya Mbethi‐suli, atũngĩĩa kũvika vala velekele ngunga sya Ndaviti vala vathikawa akw’ũ, na kũvika ndia ĩla yaseũviw’e, na kũvika nyũmba ya ila ngũmbaũ.'),
('kam', 'NEH', 3, 17, 'Na ĩtina wake Alivai, me na Leumu mwana wa Mbani, matũngĩĩa. Na ĩtina wake Asavia, mũsumbĩki wa nyunzu ya kĩvalo kya Keila, atũngĩĩa, kwondũ wa kĩvalo kyake.'),
('kam', 'NEH', 3, 18, 'Na ĩtina wake ana‐a‐ĩthe moo matũngĩĩa, Mbavai mwana wa Enatati, mũsumbĩki wa nyunzu ya kĩvalo kya Keila.'),
('kam', 'NEH', 3, 19, 'Na ĩtina wake Eseli mwana wa Yesua, mũsumbĩki wa Misiva, atũngĩĩa kĩlungu kĩngĩ, kwelekela kyambato kya vala vaiawa mĩio ya kaũ vala ũvai weekotele.'),
('kam', 'NEH', 3, 20, 'Na ĩtina wake Mbaluku mwana wa Nzavai atũngĩĩa kĩlungu kĩngĩ na ũthangaau, kuma vala ũvai weekotele kũvika mũomo wa nyũmba ya mũthembi mũnene Eliasivu.'),
('kam', 'NEH', 3, 21, 'Na ĩtina wake Melemothi mwana wa Uliya mwana wa Akosi atũngĩĩa kĩlungu kĩngĩ, kuma mũomonĩ wa nyũmba ya Eliasivu o kũvika mũthya wa nyũmba ya Eliasivu.'),
('kam', 'NEH', 3, 22, 'Na ĩtina wake athembi, andũ ma Ũiĩ, matũngĩĩa.'),
('kam', 'NEH', 3, 23, 'Na ĩtina woo Mbenyamini na Asuvu matũngĩĩa kwelekela nyũmba yoo. Na ĩtina woo Asalia mwana wa Maaseia mwana wa Anania atũngĩĩa vakuvĩ na nyũmba yake mwene.'),
('kam', 'NEH', 3, 24, 'Na ĩtina wake Mbinui mwana wa Enatati atũngĩĩa kĩlungu kĩngĩ, kuma nyũmba ya Asalia kũvika vala ũvai weekotele, na kũvika kĩkotonĩ.'),
('kam', 'NEH', 3, 25, 'Valali mwana wa Usai atũngĩĩa kwelekela vala ũvai weekotele, na mwako mũtũlu wa mũnyoolo ũla wumĩlĩte nyũmbanĩ ya ĩũlũ ya mũsumbĩ, ĩla yĩ vakuvĩ na nza ya kolokolo. Na ĩtina wake Vetaia mwana wa Valosi atũngĩĩa.'),
('kam', 'NEH', 3, 26, '(Na ĩndĩ Anethini nĩmatũaa Oveli, kũvika vandũ velekele mbingĩlo ya manzĩ kwelekela wumĩlonĩ wa syũa, na mwako mũtũlu wa mũnyoolo ũla wumĩlĩte.)'),
('kam', 'NEH', 3, 27, 'Na itina wake Atekoa matũngĩĩa kĩlungu kĩngĩ, kwelekela mwako mũnene mũtũlu wa mũnyoolo ũla wumĩlĩte, na kũvika ũvai wa Oveli.'),
('kam', 'NEH', 3, 28, 'Athembi matũngĩĩa ĩũlũ wa mbingĩlo ya mbalasi, kĩla ũmwe kwelekela nyũmba yake mwene.'),
('kam', 'NEH', 3, 29, 'Na ĩtina woo Nzatoki mwana wa Imeli atũngĩĩa kwelekela nyũmba yake mwene. Na ĩtina wake Semaia mwana wa Sekania, mũsũvĩi wa mbingĩlonĩ ya ngalĩ ya wumĩlonĩ wa syũa, atũngĩĩa.'),
('kam', 'NEH', 3, 30, 'Na ĩtina wake Aanania mwana wa Selemia, na Anuni mwana wa thanthatũ wa Nzalavi, matũngĩĩa kĩlungu kĩngĩ. Na ĩtina wake Mesulamu mwana wa Mbelekia atũngĩia kwelekela kasũmba kake.'),
('kam', 'NEH', 3, 31, 'Na ĩtina wake Malikiya ũmwe wa atwii ma thaavu atũngĩĩa kũvika nyũmba ya Anethini, na ya athoosya ma mĩio, kwelekela mbingĩlo ya Amivikati, na kũvika kwambata kwa kĩkoto.'),
('kam', 'NEH', 3, 32, 'Na atwii ma thaavu ma athoosya ma mĩio matũngĩĩa katĩ wa kwambata kwa kĩkoto na mbingĩlo ya malondu.'),
('kam', 'NEH', 4, 1, 'Ĩndĩ kweethĩwa yĩla Sanavalati wewie kana nĩtũtũngĩĩa ũvai, athilĩka, na akwatwa nĩ woo mũnene, na amathekeea Ayuti mũno.'),
('kam', 'NEH', 4, 2, 'Na aneenea vu mbee wa ana‐a‐ĩthe na ita sya Samalia, na akũlya, Ayuti aa mate na vinya meĩka ata? Makelũlũmĩlya? Makathemba nthembo? Makamina mũthenya o ũmwe? Makokĩlya mavia kuma ivumbunĩ sya mavuthĩ, na nĩ mavĩvye?'),
('kam', 'NEH', 4, 3, 'Na ĩndĩ Tovia Mũamimoni aĩ vakuvĩ nake, na asya, Wako ũũ mekwaka, ethĩwa mbĩwa ĩkambata ĩũlũ, ĩkaomboa ũvai woo wa mavia.'),
('kam', 'NEH', 4, 4, 'Ĩthukĩĩsye, ame Ngai waitũ; nũndũ nĩtũũvũthw’a: na tũnga kũtũvũthya kwoo mĩtwenĩ yoo ene, noimanengane methĩwe mũtavo nthĩ ya kũtavwa;'),
('kam', 'NEH', 4, 5, 'na ndũkavw’ĩke ũthũku woo, na naĩ yoo ndĩkavutwe vala ũĩ; nũndũ nĩmakũthatisye aki mene.'),
('kam', 'NEH', 4, 6, 'Na ĩndĩ nĩtwatũngĩĩe ũvai; na ũvai w’onthe wakwatanw’a kũvika nyunzu ya ũtũlu waw’o: nũndũ andũ maĩ na kwenda kwa kũtethya wĩa.'),
('kam', 'NEH', 4, 7, 'Ĩndĩ kweethĩwa, yĩla Sanavalati, na Tovia, na Alavu, na Aamimoni, na Aasitoti, meewie kana kũtũngĩĩa kwa maũvai ma Yelusaleme nĩkũendeeaa, na moomboku nĩmambĩlĩlw’e kũlindwa, nĩvo ĩndĩ mathilĩkile mũno;'),
('kam', 'NEH', 4, 8, 'na onthe masũanĩa vamwe moke mokite na Yelusaleme, na kwĩkĩa kĩthokoo nthĩnĩ wayo.'),
('kam', 'NEH', 4, 9, 'Ĩndĩ twamũvoya Ngai waitũ, na twaia asyaĩĩsya mũthenya na ũtukũ, nũndũ woo.'),
('kam', 'NEH', 4, 10, 'Na Yuta asya, Vinya wa ala makuaa mĩio nĩ mũoleku, na ve mavuthĩ maingĩ; na kwondũ wa ũu tũtitonya kwaka ũvai.'),
('kam', 'NEH', 4, 11, 'Na nthũ sitũ syasya, Matikamanya, o na kwona, kũvika yĩla twĩlika katĩ woo, na kũmoaa, na kũekethya ũ wĩa.'),
('kam', 'NEH', 4, 12, 'Na kweethĩwa, yĩla Ayuti ala matwĩe vakuvĩ nao mookie, matũtavya mavinda ĩkũmi kuma kũndũ kw’onthe, Mũvaka mũtũsyokee.'),
('kam', 'NEH', 4, 13, 'Kwondũ wa ũu naia andũ kũndũ kwĩ ĩtheo mũno ũtheinĩ wĩ mbĩlĩlo wa ũvai, kũndũ kũthei, naia vo andũ kũatĩĩa mĩvĩa yoo me na mbyũ syoo, na matumo moo, na mata moo.'),
('kam', 'NEH', 4, 14, 'Na nasisya, na nookĩla, na namea ala anene me ndaĩa, na asumbĩki, na andũ ala angĩ, Mũtikamakĩe: lilikanai Mwĩaĩi, ũla mũnene na wa kũtĩsya, na mũimokitĩa ana‐a‐ĩthe menyu, na ana menyu na eĩtu menyu, na iveti syenyu, na nyũmba syenyu.'),
('kam', 'NEH', 4, 15, 'Na kweethĩwa, yĩla amaitha maitũ meewie ũvoo ũsu nũmanyĩkĩte kwitũ, na Ngai nũtw’ĩkĩthĩtye ũsũanĩo woo wa mana, ithyonthe nĩtwasyokie ũvainĩ, kĩla mũndũ wĩanĩ wake.'),
('kam', 'NEH', 4, 16, 'Na kweethĩwa kuma ĩvinda yĩu, nyunzu ya athũkũmi makwa matethisye wĩa, na nyunzu yoo makwete matumo, na ngao, na mata, na tũkoti twa iaa; na asumbĩki mamaũngamĩa nyũmba yonthe ya Yuta.'),
('kam', 'NEH', 4, 17, 'Ala matũngĩĩaa ũvai na ala makuaa mĩio meeyaĩkya moo ene; kĩla mũndũ na kw’oko kũmwe kwake atethya wĩa, na akwata mũio wake wa kaũ na kũla kũngĩ;'),
('kam', 'NEH', 4, 18, 'na aki, kĩla ũmwe eeyovete ũvyũ wake kĩnyunyunĩ kyake, na maaka ta ũu. Na mũvuvi wa soo aĩ vakuvĩ nakwa.'),
('kam', 'NEH', 4, 19, 'Nakwa namea anene me ndaĩa, na asumbĩki, na andũ ala angĩ, Wĩa nĩ mũnene na mwingĩ, na ithyĩ nĩtũtaanĩĩsye ũvainĩ, ũmwe kũasa na ũla ũngĩ:'),
('kam', 'NEH', 4, 20, 'o vala mwĩĩw’a wasya wa soo, tũmbanĩei vau; Ngai waitũ akatũkitĩa.'),
('kam', 'NEH', 4, 21, 'Na ĩndĩ twatethasya wĩa ũu: na nyunzu yoo makwete matumo kuma masangya kũvika yĩla ndata syaumĩlile.'),
('kam', 'NEH', 4, 22, 'O ta ũu ĩvinda yĩu namea andũ, Kĩla mũndũ e na mũthũkũmi wake nakome Yelusaleme, nĩ kana ũtukũ methĩwe asũvĩi maitũ, na makĩtethya wĩa mũthenya.'),
('kam', 'NEH', 4, 23, 'Kwondũ wa ũu nyie, o na ana‐a‐asa makwa, o na athũkũmi makwa, o na andũ ma nguthu ya asũvĩi ala mangatĩĩe, vati ũmwe waitũ waaumya ngũa syake, kĩla ũmwe nĩwaendaa na mũio wake wa kaũ ũsĩnĩ.'),
('kam', 'NEH', 5, 1, 'Nĩvo ĩndĩ kwookĩlile kĩĩo kĩnene kya andũ na kya iveti syoo ĩũlũ wa ana‐a‐ĩthe moo Ayuti.'),
('kam', 'NEH', 5, 2, 'Nũndũ kwaĩ amwe ala maisye, Ithyĩ, na ana maitũ, na eĩtu maitũ, nĩ aingĩ: twosei lĩu wa mbaa ngetha, nĩ kana tũye na kwĩkala thayũ.'),
('kam', 'NEH', 5, 3, 'O na kwaĩ amwe ala maisye, Nĩtumĩtye mĩũnda yaitũ, na mĩũnda yaitũ ya mĩsavivũ, na nyũmba sitũ, syĩthĩwe ngwatĩlĩlyo: twosei lĩu wa mbaa ngetha nũndũ wa yũa yĩĩ.'),
('kam', 'NEH', 5, 4, 'O na kwaĩ angĩ ala maisye, Nĩtũkovete mbesa ũndũ wa koti wa mũsumbĩ, na nĩtwiĩte mĩũnda yaitũ na mĩũnda yaitũ ya mĩsavivũ yĩthĩwe ngwatĩlĩlyo.'),
('kam', 'NEH', 5, 5, 'Ĩndĩ yu mĩĩ yaitũ no ta mĩĩ ya ana‐a‐ĩthe maitũ, na syana sitũ nĩ ta syana syoo: na, kaĩ, nĩtũkũete ũkombonĩ ana maitũ na eĩtu maitũ methĩwe athũkũmi, na eĩtu maitũ amwe me ũkombonĩ o na yu: o na tũti na vinya wa kũsiĩĩa ũndũ ũsu; nũndũ andũ angĩ me na mĩũnda yaitũ na mĩũnda yaitũ ya mĩsavivũ.'),
('kam', 'NEH', 5, 6, 'Na yĩla neewie kũĩa kwoo na ndeto isu nĩnathatie mũno.'),
('kam', 'NEH', 5, 7, 'Na ĩndĩ nasũanĩa thayũnĩ wakwa, na nakananĩa na anene me nguma na asumbĩki, na namea, Nĩmũmaumĩthya ũtandĩthyo mbesanĩ kĩla ũmwe kwa mwana‐a‐ĩthe wake. Na namombanĩsya ũmbano mũnene.'),
('kam', 'NEH', 5, 8, 'Na namea, Kwĩanana na ũtonyi witũ ithyĩ nĩtwovoetye ana‐a‐ĩthe maitũ Ayuti, ala mathooew’e i mbaĩ; nenyu nĩmũkwĩtĩkĩla kũmathoosya o na ana‐a‐ĩthe menyu, nao nĩmaĩle ũthooew’a ithyĩ? Na ĩndĩ mavindya ki, na matyaaona ndeto.'),
('kam', 'NEH', 5, 9, 'Na ĩngĩ nasya, Ũndũ ũũ mũkwĩka ti ũseo: mũtyaĩle kũendaa mũkĩmũkĩa Ngai waitũ, nĩ kana i mbaĩ amaitha maitũ itikethĩwe na kĩvũthya?'),
('kam', 'NEH', 5, 10, 'O nakwa, ana‐a‐asa makwa na athũkũmi mwaka, nĩmakovethasya mbesa na lĩu wa mbaa ngetha. Nĩngũmwĩsũva, tũekei ũtandĩthyo ũsu.'),
('kam', 'NEH', 5, 11, 'Nĩngũmwĩsũva, o ũmũnthĩ mũmatũngĩe mĩũnda yoo, na mĩũnda yoo ya mĩsavivũ, na mĩũnda yoo ya mĩthata, na nyũmba syoo, o na kĩlungu kya ĩana kya i mbesa, na kya lĩu wa mbaa ngetha, na mbinyu mbĩthĩ, na mauta, ala mwamaumĩthĩtye.'),
('kam', 'NEH', 5, 12, 'Nĩvo ĩndĩ maisye, Nĩtũũmatũngĩa, na tũtikenda kĩndũ kwoo; now’o tũkwĩka, o tondũ ũkwasya. Nĩvo ĩndĩ nametie athembi, na nameavĩthya, makeke kwĩanana na watho ũsu.'),
('kam', 'NEH', 5, 13, 'Na ũndũ ũngĩ navuunza ngũa yakwa, na nasya, O ta ũu Ngai navuunze kĩla mũndũ aume nyũmbanĩ yake, na ũthũkũminĩ wake, ũla ũtakeanĩsya watho ũũ; o w’o avuunzwe, na kũtiwa e mũthei. Na ũmbano w’onthe wasya, Ameni, na wataĩa Yeova. Na andũ meeka kwĩanana na watho ũsu.'),
('kam', 'NEH', 5, 14, 'Na ũndũ ũngĩ kuma ĩvinda naiiwe nĩthĩwe ngavana woo nthĩ ya Yuta, kuma mwaka wa mĩongo ĩlĩ o kũvika mwaka wa mĩongo ĩtatũ na ĩlĩ wa kũsumbĩka kwa mũsumbĩ Alitasasita, nayo nĩ myaka ĩkũmi na ĩlĩ, nyie na ana‐a‐asa makwa tũtyaaya lĩu wa ngavana.'),
('kam', 'NEH', 5, 15, 'Ĩndĩ makavana ala maĩ mbee wakwa nĩmatw’ĩkie mũio kwa andũ, na moosa kwoo lĩu na mbinyu, o vamwe na sekeli mĩongo ĩna sya vetha; ĩĩ, o na athũkũmi moo nĩmeetũlasya ĩũlũ wa andũ: ĩndĩ nyie ndyaaĩka ũu, nũndũ wa kũmũkĩa Ngai.'),
('kam', 'NEH', 5, 16, 'Ĩĩ, ũndũ ũngĩ naendeea wĩanĩ wa ũvai ũũ, o na tũtyaathooa nthĩ o na ĩĩva: na athũkũmi makwa onthe moombanĩa vo wĩanĩ.'),
('kam', 'NEH', 5, 17, 'Vamwe na ũu mesanĩ yakwa kwaĩ andũ ĩana na mĩongo ĩtano ma Ayuti na asumbĩki, eka asu ala mookie kwitũ kuma mbaĩnĩ ila syatũthyũlũlũkĩte.'),
('kam', 'NEH', 5, 18, 'Na ĩndĩ lĩu ũla waseũvĩtw’e wa mũthenya ũmwe waĩ ng’ombe ĩmwe na malondu thanthatũ manou mũno; o na ngũkũ syaseũvw’a ũndũ wakwa, na mũthenya ũmwe katĩ wa mĩthenya ĩkũmi mbio ya mĩthemba yonthe ya mbinyu: ĩndĩ o na ũu w’onthe ndyaametya lĩu wa ngavana, nũndũ ũkombo waĩ mũito andũnĩ asu.'),
('kam', 'NEH', 5, 19, 'Ame Ngai wakwa, ndilikanĩla ũndũ wa ũseo, w’onthe ũla neekie ũndũ wa andũ aa.'),
('kam', 'NEH', 6, 1, 'Na ĩndĩ kweethĩwa yĩla Sanavalati na Tovia, na Ngesemu Mwalavu, na amaitha maitũ ala angĩ, mataviw’e nĩnĩtũngĩĩe ũvai, na vati vandũ vavũthũe vatiele nthĩnĩ waw’o (o na kau kũvika ĩvinda yĩu ndyambĩte kũũngamya mĩomo mbingĩlonĩ),'),
('kam', 'NEH', 6, 2, 'Sanavalati na Ngesemu matũmana kwakwa, makĩmbĩa, Ũka, tũkomane mũsyĩ ũmwe ũiĩnĩ wa Ono. Ĩndĩ nĩmasũanĩĩte kũmbĩka naĩ.'),
('kam', 'NEH', 6, 3, 'Nakwa natũma atũmwa kwoo, ngĩmea, Nĩngũtethya wĩa mũnene, na nditonya kũtheea: wĩa ũũngame nĩkĩ, yĩla ngũtia, na kũtheea vala mũĩ?'),
('kam', 'NEH', 6, 4, 'Na matũmana kwakwa mavinda ana o ta ũu; nakwa namasũngĩa o ta ya mbee.'),
('kam', 'NEH', 6, 5, 'Nĩvo ĩndĩ Sanavalati watũmie mũthũkũmi wake kwakwa o ta ũu ĩvinda ya katano e na valũa ũte mũvinge kw’okonĩ kwake,'),
('kam', 'NEH', 6, 6, 'ũla waandĩkĩtwe, Nĩkũneenetwe i mbaĩnĩ, o na Ngesemu easya atĩ we na Ayuti nĩmũũsũanĩa kũng’enda; na nũndũ wa ũu nũkũtũngĩĩa ũvai: naku nũkwenda kwĩthĩwa mũsumbĩ woo, kwĩanana na ndeto isu.'),
('kam', 'NEH', 6, 7, 'O na nĩwiĩte athani matavan’ye ũvoo waku Yelusaleme, makyasya, Ve mũsumbĩ Yuta: na yu mũsumbĩ akatavw’a kwĩanana na ndeto isu. Ĩndĩ yu ũka, tũsũanĩe vamwe.'),
('kam', 'NEH', 6, 8, 'Nĩvo ĩndĩ natũmanie kwake, ngĩmwĩa, Vati maũndũ mekĩkĩte ta asu ala ũkwasya, ĩndĩ nue ũmasũanĩaa na ngoo yaku mwene.'),
('kam', 'NEH', 6, 9, 'Nũndũ onthe nĩmendaa kũtũtĩsya, makyasya, Moko moo makonzethw’a wĩanĩ, ndũkatethw’e. Ĩndĩ yu, ame Ngai, mbĩkĩa moko makwa vinya.'),
('kam', 'NEH', 6, 10, 'Nakwa nathi nyũmbanĩ ya Semaia mwana wa Ndelaia mwana wa Meetaveli, ũla waĩ mũsiĩĩe; nake asya, Tũkomane nyũmbanĩ ya Ngai, nthĩnĩ wa ĩkalũ, na tũivinga mĩomo ya ĩkalũ: nũndũ makooka makũae; ĩĩ, ũtukũ makooka makũae.'),
('kam', 'NEH', 6, 11, 'Nakwa nasya, Mũndũ ũilyĩ takwa nĩwaĩle kũkĩa? Na ve ũũ, ailyĩ takwa, ũla ũtonya kũlika ĩkalũnĩ atangĩĩe thayũ wake? Nyie ndilika.'),
('kam', 'NEH', 6, 12, 'Na namanya, kaĩ, Ngai ndamũtũmĩte; ĩndĩ ambathanĩe wathani ũsu: na Tovia na Sanavalati maĩ manamũtuva.'),
('kam', 'NEH', 6, 13, 'Nĩwatuviwe ũndũ wa ũu, nĩ kana nĩkĩe, na kwĩka ũndũ ũsu, wĩthĩwe naĩ kwakwa, nĩ kana methĩwe na ũndũ ũthũku wa kũngweta, mambũthye.'),
('kam', 'NEH', 6, 14, 'Ame Ngai wakwa, lilikana Tovia na Sanavalati kwĩanana na mawĩa asu moo, o na mwathani mũndũ mũka Noatia, na athani ala angĩ, ala mendaa kũmbĩkĩa w’ĩa.'),
('kam', 'NEH', 6, 15, 'Na ĩndĩ ũvai nĩwathelile mũthenya wa mĩongo ĩlĩ na ĩtano wa mwei wa Eluli, nthĩnĩ wa mĩthenya mĩongo ĩtano na ĩlĩ.'),
('kam', 'NEH', 6, 16, 'Na kweethĩwa, yĩla amaitha maitũ onthe meewie ũu, mbaĩ syonthe ila syatũthyũlũlũkĩte syakĩa, na syathelelw’a ndaĩa methonĩ masyo ene; nũndũ nĩmamanyie kana wĩa ũsu watethiw’e nĩ Ngai waitũ.'),
('kam', 'NEH', 6, 17, 'Na ũndũ ũngĩ mĩthenyanĩ ĩsu anene me ndaĩa ma Yuta mamũtwaĩa Tovia mavalũa maingĩ, na mavalũa ma Tovia mamavikĩa.'),
('kam', 'NEH', 6, 18, 'Nũndũ kwaĩ aingĩ Yuta ala mamwĩavĩthĩsye, nĩkwĩthĩwa aĩ mũthoni wa Sekania mwana wa Alaa; na mwana wake Yeoanani aĩ anatwaa mwĩĩtu wa Mesulamu mwana wa Mbelekia.'),
('kam', 'NEH', 6, 19, 'O na maweta meko make maseo vala nĩĩ, na mamũtũngĩa ndeto syakwa. Na Tovia andetee mavalũa ma kũmbĩkĩa w’ĩa.'),
('kam', 'NEH', 7, 1, 'Na ĩndĩ kweethĩwa, yĩla ũvai wathelile, na namina kũũngamya mĩomo, na asũvĩi ma mĩomonĩ, na aini, na Alivai maiwa.'),
('kam', 'NEH', 7, 2, 'Naia mwana‐a‐ia wakwa Aanani, na Aanania ngavana wa nyũmba nene yĩ kĩemo, meaĩe Yelusaleme; nũndũ nake aĩ mũndũ wĩ kĩthito, na akĩaa Ngai kũvĩtũka aingĩ.'),
('kam', 'NEH', 7, 3, 'Nakwa namea, Mbingĩlo sya Yelusaleme itikavingũwe kũvika syũa yavyũva; na o yĩla maũngamĩte makĩsyaĩĩsya, mavinge mĩomo, nenyu mũimĩkĩa ivingo: na iai asyaĩĩsya ma ala matwĩe Yelusaleme, kĩla ũmwe ũsyaĩĩsyonĩ wake, na kĩla ũmwe elekele nyũmba yake.'),
('kam', 'NEH', 7, 4, 'Na ĩndĩ ndũa yaĩ nthanthau na nene; ĩndĩ andũ maĩ avũthũ nthĩnĩ wayo, na nyũmba ityaĩ mbake.'),
('kam', 'NEH', 7, 5, 'Na Ngai wakwa eekĩa ngoonĩ yakwa nũmban’ye anene me ndaĩa, na asumbĩkĩ, na andũ, nĩ kana matalwe mosyaanĩonĩ. Nakwa noona ĩvuku ya mosyaanĩo ma ala mambie kwambata, na neethĩa kũandĩkĩtwe nthĩnĩ wayo atĩĩ:'),
('kam', 'NEH', 7, 6, 'Aa nĩo ana ma ĩ kĩlungu kĩnene kya nthĩ, ala mambatie kuma kũtavwanĩ kwa ala matwaiwe, ala Nevukatilesa mũsumbĩ wa Mbaviloni wamatwaĩte, na ala masyokie Yelusaleme na Yuta, kĩla ũmwe ndũanĩ yake;'),
('kam', 'NEH', 7, 7, 'ala mookie na Nzeluvaveli, na Yesua, na Neemia, na Asalia, na Laamia, na Naaamani, na Molitekai, na Mbilisani, na Mbisivelethi, na Mbikivai, na Neumu, na Mbaana. Ũtalo wa aũme ma andũ ma Isilaeli:'),
('kam', 'NEH', 7, 8, 'Ana ma Valosi, ngili ilĩ na ĩana na mĩongo mũonza na elĩ.'),
('kam', 'NEH', 7, 9, 'Ana ma Sevatia, maana atatũ na mĩongo mũonza na elĩ.'),
('kam', 'NEH', 7, 10, 'Ana ma Alaa, maana thanthatũ na mĩongo ĩtano na elĩ.'),
('kam', 'NEH', 7, 11, 'Ana ma Vaathi‐moavi, ma ana ma Yesua na Yoavu, ngili ilĩ na maana nyanya na ĩkũmi na nyanya.'),
('kam', 'NEH', 7, 12, 'Ana ma Elamu, ngili na maana elĩ na mĩongo ĩtano na ana.'),
('kam', 'NEH', 7, 13, 'Ana ma Nzatu, maana nyanya na mĩongo ĩna na atano.'),
('kam', 'NEH', 7, 14, 'Ana ma Nzakai, maana mũonza na mĩongo thanthatũ.'),
('kam', 'NEH', 7, 15, 'Ana ma Mbinui, maana thanthatũ na mĩongo ĩna na nyanya.'),
('kam', 'NEH', 7, 16, 'Ana ma Mbevai, maana thanthatũ na mĩongo ĩlĩ na nyanya.'),
('kam', 'NEH', 7, 17, 'Ana ma Asikati, ngili ilĩ na maana atatũ na mĩongo ĩlĩ na elĩ.'),
('kam', 'NEH', 7, 18, 'Ana ma Atonikamu, maana thanthatũ na mĩongo thanthatũ na mũonza.'),
('kam', 'NEH', 7, 19, 'Ana ma Mbikivai, ngili ilĩ na mĩongo thanthatũ na mũonza.'),
('kam', 'NEH', 7, 20, 'Ana ma Atini, maana thanthatũ na mĩongo ĩtano na atano.'),
('kam', 'NEH', 7, 21, 'Ana ma Ateli, wa Esekia, mĩongo kenda na nyanya.'),
('kam', 'NEH', 7, 22, 'Ana ma Asumu, maana atatũ na mĩongo ĩlĩ na nyanya.'),
('kam', 'NEH', 7, 23, 'Ana ma Mbenzai, maana atatũ na mĩongo ĩlĩ na ana.'),
('kam', 'NEH', 7, 24, 'Ana ma Alivu, ĩana na ĩkũmi na elĩ.'),
('kam', 'NEH', 7, 25, 'Ana ma Ngiveoni, mĩongo kenda na atano.'),
('kam', 'NEH', 7, 26, 'Andũ ma Mbethi‐leemu na Netova, ĩana na mĩongo nyanya na nyanya.'),
('kam', 'NEH', 7, 27, 'Andũ ma Anathothi, ĩana na mĩongo ĩlĩ na nyanya.'),
('kam', 'NEH', 7, 28, 'Andũ ma Mbethi‐asimavethi, mĩongo ĩna na elĩ'),
('kam', 'NEH', 7, 29, 'Andũ ma Kiliathi‐yealimu, na Kevila, na Mbeelothi, maana mũonza na mĩongo ĩna na atatũ.'),
('kam', 'NEH', 7, 30, 'Andũ ma Lama, na Ngeva, maana thanthatũ na mĩongo ĩlĩ na ũmwe.'),
('kam', 'NEH', 7, 31, 'Andũ ma Mikimasi, ĩana na mĩongo ĩlĩ na elĩ.'),
('kam', 'NEH', 7, 32, 'Andũ ma Mbethi‐eli na Ai, ĩana na mĩongo ĩlĩ na atatũ.'),
('kam', 'NEH', 7, 33, 'Andũ ma Nevo ya kelĩ, mĩongo ĩtano na elĩ.'),
('kam', 'NEH', 7, 34, 'Ana ma Elamu ya kelĩ, ngili na maana elĩ na mĩongo ĩtano na ana.'),
('kam', 'NEH', 7, 35, 'Ana ma Alimu, maana atatũ na mĩongo ĩlĩ.'),
('kam', 'NEH', 7, 36, 'Ana ma Yeliko, maana atatũ na mĩongo ĩna na atano.'),
('kam', 'NEH', 7, 37, 'Ana ma Loti, na Atiti, na Ono, maana mũonza na miongo ĩlĩ na ũmwe.'),
('kam', 'NEH', 7, 38, 'Ana ma Senaa, ngili itatũ na maana kenda na mĩongo ĩtatũ.'),
('kam', 'NEH', 7, 39, 'Athembi: ana ma Yetaia, wa nyũmba ya Yesua, maana kenda na mĩongo mũonza na atatũ.'),
('kam', 'NEH', 7, 40, 'Ana ma Imeli, ngili na mĩongo ĩtano na elĩ.'),
('kam', 'NEH', 7, 41, 'Ana ma Vasuli, ngili na maana elĩ na mĩongo ĩna na mũonza.'),
('kam', 'NEH', 7, 42, 'Ana ma Alimu, ngili na ĩkũmi na mũonza.'),
('kam', 'NEH', 7, 43, 'Alivai: ana ma Yesua, wa Katimieli, ma ana ma Oteva, mĩongo mũonza na ana.'),
('kam', 'NEH', 7, 44, 'Aini: ana ma Asavu, ĩana na mĩongo ĩna na nyanya.'),
('kam', 'NEH', 7, 45, 'Asũvĩi ma mĩomonĩ: ana ma Salumu, na ana ma Ateli, na ana ma Talimoni, na ana ma Akuvu, na ana ma Atita, na ana ma Sovai, ĩana na mĩongo ĩtatũ na nyanya.'),
('kam', 'NEH', 7, 46, 'Anethini: ana ma Nziia, na ana ma Asiuva, na ana ma Tavaothi,'),
('kam', 'NEH', 7, 47, 'na ana ma Kelosi, na ana ma Sia, na ana ma Vatoni,'),
('kam', 'NEH', 7, 48, 'na ana ma Levana, na ana ma Akava, na ana ma Salimai,'),
('kam', 'NEH', 7, 49, 'na ana ma Aananu, na ana ma Ngiteli, na ana ma Kaali,'),
('kam', 'NEH', 7, 50, 'na ana ma Leaia, na ana ma Lesini, na ana ma Nekota,'),
('kam', 'NEH', 7, 51, 'na ana ma Ngasamu, na ana ma Usa, na ana ma Vasea,'),
('kam', 'NEH', 7, 52, 'na ana ma Mbesai, na ana ma Ameuni, na ana ma Nevisimu,'),
('kam', 'NEH', 7, 53, 'na ana ma Mbakivuki, na ana ma Akuva, na ana ma Aliuli,'),
('kam', 'NEH', 7, 54, 'na ana ma Mbasiluthi, na ana ma Meita, na ana ma Alasa,'),
('kam', 'NEH', 7, 55, 'na ana ma Mbalikosi, na ana ma Sisela, na ana ma Tema,'),
('kam', 'NEH', 7, 56, 'na ana ma Nesia, na ana ma Ativa.'),
('kam', 'NEH', 7, 57, 'Ana ma athũkũmi ma Solomoni: ana ma Sotai, na ana ma Sovelethi, na ana ma Velita,'),
('kam', 'NEH', 7, 58, 'na ana ma Yaala, na ana ma Ndalikoni, na ana ma Ngiteli,'),
('kam', 'NEH', 7, 59, 'na ana ma Sevatia, na ana ma Atili, na ana ma Vokelethi‐nzevaimu, na ana ma Amoni.'),
('kam', 'NEH', 7, 60, 'Anethini onthe, na ana ma athũkũmi ma Solomoni, maĩ maana atatũ na mĩongo kenda na elĩ.'),
('kam', 'NEH', 7, 61, 'Na aa nĩo ala mambatie kuma Teli‐mela, na Teli‐alasa, na Keluvi, na Atoni, na Imeli; ĩndĩ matyaatonya kwĩmanyĩthan’ya nyũmba sya aaĩthe moo, o na mbaĩ yoo, kana nĩ ma Isilaeli:'),
('kam', 'NEH', 7, 62, 'ana ma Ndelaia, na ana ma Tovia, na ana ma Nekota, maana thanthatũ na mĩongo ĩna na elĩ.'),
('kam', 'NEH', 7, 63, 'Na ma athembi: ana ma Ovaia, na ana ma Mbalisilai, nomo ana ma Akosi, ũla watwaie mwĩĩtu wa Mbalisilai Mũngileati, na eetanĩw’a na syĩtwa yoo.'),
('kam', 'NEH', 7, 64, 'Asu nĩmamanthie ĩvuku yoo yĩla matalĩtwe mosyaanĩo, ĩndĩ yĩtyaaoneka: kwondũ wa ũu nĩmatalilwe kwĩthĩwa nĩ avuku na maumw’a ũthembinĩ.'),
('kam', 'NEH', 7, 65, 'Na ngavana amea, matikaye syĩndũ ntheu mũno, kũvika kwaũngama mũthembi wĩ na Ulimu na Thumimu.'),
('kam', 'NEH', 7, 66, 'Ũmbano w’onthe vamwe waĩ ngili mĩongo ĩna na ilĩ na maana atatũ na mĩongo thanthatũ,'),
('kam', 'NEH', 7, 67, 'eka athũkũmi moo aũme na athũkũmi moo eĩtu, namo maĩ ngili mũonza na maana atatũ na mĩongo ĩtatũ na mũonza: na maĩ na aũme ma kwina na aka ma kwina maana elĩ na mĩongo ĩna na atano.'),
('kam', 'NEH', 7, 68, 'Mbalasi syoo syaĩ maana mũonza na mĩongo ĩtatũ na thanthatũ; na nyũmbũ syoo, maana elĩ na mĩongo ĩna na itano;'),
('kam', 'NEH', 7, 69, 'na ngamĩle syoo, maana ana na mĩongo ĩtatũ na itano; na mang’oi moo, ngili thanthatũ na maana mũonza na mĩongo ĩlĩ.'),
('kam', 'NEH', 7, 70, 'Na atongoi amwe ma nyũmba sya aaĩthe nĩmanenganie syĩndũ kwondũ wa ũ wĩa. Ngavana nĩwanenganie sya kwia vala vaiawa ũthwii ilungu ngili sya thaavu, mbakũli mĩongo ĩtano, na ngũa sya athembi maana atano na mĩongo ĩtatũ.'),
('kam', 'NEH', 7, 71, 'Na atongoi amwe ma nyũmba sya aaĩthe nĩmanenganie sya kwia vala vaiawa ũthwii wa wĩa ilungu ngili mĩongo ĩlĩ sya thaavu, na latili ngili ilĩ na maana elĩ sya vetha.'),
('kam', 'NEH', 7, 72, 'Na ila ala angĩ manenganie nĩ ilungu ngili mĩongo ĩlĩ sya thaavu, na latili ngili ilĩ sya vetha, na ngũa sya athembi mĩongo thanthatũ na mũonza.'),
('kam', 'NEH', 7, 73, 'Na ĩndĩ athembi, na Alivai, na asũvĩi ma mĩomonĩ, na aini, na andũ amwe, na Anethini, na Isilaeli onthe, nĩmekalile ndũanĩ syoo. Na yĩla mwei wa mũonza wavikie, ana ma Isilaeli maĩ ndũanĩ syoo.'),
('kam', 'NEH', 8, 1, 'Na andũ onthe moombanĩa vamwe ta mũndũ ũmwe vala vandũ vathanthau vaĩ mbee wa mbingĩlo ya manzĩ; na matavya mũandĩki Esala aete ĩvuku ya mĩao ya Mose, ĩla Yeova weaĩe Isilaeli.'),
('kam', 'NEH', 8, 2, 'Na mũthembi Esala aete mĩao ĩsu mbee wa ũmbano, aũme o na aka, na onthe ala maĩ matonya kwĩw’a na kũmanya, mũthenya wa mbee wa mwei wa mũonza.'),
('kam', 'NEH', 8, 3, 'Nake ayĩsoma elekele vala vandũ vathanthau vaĩ mbee wa mbingĩlo ya manzĩ kuma kĩoko tene kũvika mũthenya katĩ, e mbee wa aũme na aka, na ala maĩ matonya kũmanya; na matũ ma andũ onthe meethukĩĩsye ĩvuku ya mĩao.'),
('kam', 'NEH', 8, 4, 'Na mũandĩki Esala aũngama vandũ vatũlu vakĩtwe na mĩtĩ, vala maseũvisye kwondũ wa ũndũ ũsu; na ũtee wake kwaũngama Matithia, na Sema, na Anaia, na Uliya, na Ilikia, na Maaseia, kw’okonĩ kwake kwa aũme; na kw’okonĩ kwake kwa aka kwaũngama Vetaia, na Misaeli, na Malikiya, na Asumu, na Asivatana, na Nzekalia, na Mesulamu.'),
('kam', 'NEH', 8, 5, 'Na Esala avuũa ĩvuku andũ onthe mene (nũndũ aĩ ĩũlũ wa andũ onthe); na yĩla wayĩvuũie, andũ onthe maũngama.'),
('kam', 'NEH', 8, 6, 'Na Esala amũtaia Yeova, Ngai mũnene; na andũ onthe masũngĩa, Ameni, Ameni, makyũkĩlya moko moo: na makunamya mĩtwe yoo, na mathaitha Yeova mothyũ moo melekelye nthĩ.'),
('kam', 'NEH', 8, 7, 'O na Yesua, na Mbani, na Selevia, na Yamini, na Akuvu, na Savethai, na Otia, na Maaseia, na Kelita, na Asalia, na Yosavati, na Aananu, na Velaia, na Alivai, mamalyũlĩla andũ ĩla mĩao: na andũ no maũngeme vala maĩ.'),
('kam', 'NEH', 8, 8, 'Na masoma ĩvukunĩ, o mĩaonĩ ya Ngai, na wasya mũseo; na moonan’ya ũalyũlo, na ĩndĩ mamanya ũndũ masomewe.'),
('kam', 'NEH', 8, 9, 'Na Neemia, ũla waĩ ngavana, na mũthembi Esala mũandĩki, na Alivai ala mamamanyĩisye andũ, mamea andũ onthe, Mũnthĩ ũũ nĩ mũtheu kwa Yeova Ngai wenyu; mũtikamete kana kũĩa. Nũndũ andũ onthe nĩmaĩie, yĩla meewie ndeto sya ĩla mĩao.'),
('kam', 'NEH', 8, 10, 'Nĩvo ĩndĩ wameie, Ĩeendeei, mũye mathunya, na kũnyw’a kĩla kĩ mũyo, na mũimũtwaĩa kya ũya ũla ũtaseũvĩw’a kĩndũ; nũndũ mũnthĩ ũũ nĩ mũtheu kwa Mwĩaĩi waitũ: o na mũtikethĩwe na woo; nũndũ ũtanu wa Yeova nĩ vinya wenyu.'),
('kam', 'NEH', 8, 11, 'Na ĩndĩ Alivai mavindĩthya andũ onthe, makĩmea, Ĩkilĩlyei, nũndũ mũthenya ũũ nĩ mũtheu; o na mũtikethĩwe na woo.'),
('kam', 'NEH', 8, 12, 'Na andũ onthe makwata nzĩa mathi, maye, na manyw’e, na matwaanĩe kya ũya, na kũtana mũno, nũndũ nĩmamanyie ndeto ila mataviw’e.'),
('kam', 'NEH', 8, 13, 'Na mũthenya wa kelĩ atongoi ma nyũmba sya aaĩthe ma andũ onthe, na athembi, na Alivai, mamũmbanĩa mũandĩki Esala, nĩ kana methukĩĩsye ndeto sya mĩao.'),
('kam', 'NEH', 8, 14, 'Na moona kũandĩkĩtwe mĩaonĩ, kana Yeova nĩweaie na kanyw’a wa Mose, ana ma Isilaeli mekalae malwandanĩ mbokanĩ ya mwei wa mũonza;'),
('kam', 'NEH', 8, 15, 'na nĩ kana manyaĩĩkye na kũtavan’ya ndũanĩ syoo syonthe, na Yelusaleme, makyasya, Umaalai mũende kĩĩmanĩ, mũlatye mbonge sya mĩthata, na mbonge sya mĩthata ya kĩthekanĩ, na mbonge sya mĩtĩ ya mĩandasi, na mathangũ ma mĩtende, na mbonge sya mĩtĩ mĩthungu, sya kũseũvya malwanda, o tondũ kũandĩkĩtwe.'),
('kam', 'NEH', 8, 16, 'Na ĩndĩ andũ maumaala mathi, na maiete, na meeseũvĩsya malwanda, kĩla mũndũ kyalanĩ kya nyũmba yake, na nza syoo, na nza sya nyũmba ya Ngai, na vala vandũ vathanthau va mbingĩlo ya manzĩ, na vandũ vathanthau va mbingĩlo ya Evalaimu.'),
('kam', 'NEH', 8, 17, 'Na ũmbano w’onthe wa ala maumĩte kũtavwanĩ maseũvya malwanda, na mekala ala malwandanĩ: nũndũ kuma mĩthenya ya Yesua mwana wa Nuni kũvika mũthenya ũsu ana ma Isilaeli matyaaĩka ũu. Na kwaĩ ũtanu mwingĩ mũno.'),
('kam', 'NEH', 8, 18, 'O na mũthenya na mũthenya, kuma mũthenya wa mbee kũvika mũthenya wa mũminũkĩlyo, asomaa ĩvukunĩ ya mĩao ya Ngai. Na malilikana mboka mĩthenya mũonza; na mũthenya wa nyanya kwaĩ ũmbano ũkilĩtye, kwĩanana na ũtw’ĩo.'),
('kam', 'NEH', 9, 1, 'Na ĩndĩ mũthenya wa mĩongo ĩlĩ na ĩna wa mwei ũsu ana ma Isilaeli moombana na kũtĩĩa ũya, mevw’ĩkĩte makunia, na kwĩyũmba mũthanga.'),
('kam', 'NEH', 9, 2, 'Na ũsyao wa Isilaeli wataanĩsya na andũ onthe ma nthĩ ingĩ, na maũngama na kumbũla naĩ syoo, na mothũku ma aaĩthe moo.'),
('kam', 'NEH', 9, 3, 'Na maũngama vala maĩ na masoma ĩvukunĩ ya mĩao ya Yeova Ngai woo masaa atatũ ma mũthenya; na masaa angĩ atatũ maumbũla, na mathaitha Yeova Ngai woo.'),
('kam', 'NEH', 9, 4, 'Nĩvo ĩndĩ kwaũngamie ĩũlũ wa mbasya sya Alivai andũ aa: Yesua, na Mbani, na Katimieli, na Sevania, na Mbuni, na Selevia, na Mbani, na Kienani, na mamwĩkaĩla Yeova Ngai woo na wasya mũnene.'),
('kam', 'NEH', 9, 5, 'Nĩvo ĩndĩ Alivai, Yesua, na Katimieli, na Mbani, na Asavineia, na Selevia, na Otia, na Sevania, na Vethaia, maisye, Ũngamai mũtaĩe Yeova Ngai wenyu kuma tene kũvika tene; na syĩtwa yaku ĩtheu nĩyĩtaĩwe, yĩla ĩnene kwĩ ũathimo w’onthe na ndaĩa.'),
('kam', 'NEH', 9, 6, 'Nue Yeova, o we wĩ weka; nue woombie ĩtu, ĩtu yĩla yĩ ĩũlũ wa matu, vamwe na nguthu yonthe yamo, na nthĩ na syĩndũ syonthe syĩ ĩũlũ wayo, na maũkanga na syonthe syĩ nthĩnĩ wamo, na nue wisũvĩaa syonthe; na nguthu ya ĩtunĩ nĩkũthaithaa.'),
('kam', 'NEH', 9, 7, 'Nue Yeova Ngai, ũla wamũnyuvie Avalamu, na wamumya Ulu wa Akalitei, na wamũnenga syĩtwa ya Avalaamu,'),
('kam', 'NEH', 9, 8, 'na woonie ngoo yake yĩ kĩthito vala ũĩ, na watianĩa ũtianĩo nake ũnengane nthĩ ya Mũkanaani, na Mũititi, na Mũamoli, na Mũvelisi, na Mũyevusi, na Mũngilikasi, ũmĩnenge ũsyao wake yo, na nĩwĩanĩsye ndeto syaku; nũndũ wĩ mũlũngalu.'),
('kam', 'NEH', 9, 9, 'Naku woona thĩna wa aaĩthe maitũ Misili, na weew’a kĩĩo kyoo ũtee wa Ũkanga Mũtune,'),
('kam', 'NEH', 9, 10, 'na woonan’ya syama na moseng’yo kwa Valao, na athũkũmi make onthe, na andũnĩ onthe ma nthĩ yake; nĩkwĩthĩwa nĩweesĩ nĩmamekie na ngathĩĩo, naku weeseũvĩsya syĩtwa, o tondũ kũilyĩ ũmũnthĩ.'),
('kam', 'NEH', 9, 11, 'Na waaan’ya ũkanga mbee woo, na ĩndĩ mavĩtĩla ũkanganĩ katĩ makinyĩle nthĩ nyũmũ; na ala mamaatĩĩe wamekya syũngũnĩ, o ta ĩvia manzĩnĩ maingĩ.'),
('kam', 'NEH', 9, 12, 'Na ĩngĩ wamatongoesya mũthenya wĩ nthĩnĩ wa kĩtuĩ kya mũumbĩ; na ũtuku wĩ nthĩnĩ wa kĩtuĩ kya mwaki, ũmanenge kyeni nzĩanĩ ĩla maĩle kũthi nayo.'),
('kam', 'NEH', 9, 13, 'Na ĩngĩ watheea kĩĩmanĩ kya Sinai, na waneena nao wĩ ĩtunĩ, na wamanenga motw’ĩo malũngalu na mĩao ya w’o, na myamũlo na mĩao mĩseo,'),
('kam', 'NEH', 9, 14, 'na wamamanyĩthya savato waku mũtheu, na wameaĩa mawĩaĩo, na myamũlo, na mĩao, na kanyw’a wa Mose, mũthũkũmi waku,'),
('kam', 'NEH', 9, 15, 'na wamanenga kĩmũtũ kuma ĩtunĩ nũndũ wa nzaa yoo, na wamaumĩsya manzĩ ĩvianĩ nũndũ wa waũni woo, na wameaĩa malike mamĩmesye nthĩ ĩla weevĩtie kũmanenga.'),
('kam', 'NEH', 9, 16, 'Ĩndĩ mo na aaĩthe maitũ meekaa na ngathĩĩo, na moomya ngingo syoo, na matyaaĩthukĩĩsya mĩao yaku,'),
('kam', 'NEH', 9, 17, 'na malea kwĩw’a, o na matyaalilikana moseng’yo maku ala weekie katĩ woo, ĩndĩ moomya ngingo syoo, na ũng’endunĩ woo maia kavuteni masyoke ũkombonĩ woo. Ĩndĩ we wĩ Ngai wĩyũmbanĩtye kũekea, wĩ mũseo na wĩ wa tei, mũmĩĩsya wa kũthata, na wusũĩte ũseo wĩ wendo, na ndwaamatia.'),
('kam', 'NEH', 9, 18, 'Ĩĩ, yĩla maĩ maneeseũvĩsya mũvw’anano wa kasaũ ka ng’ombe na syĩndũ matwekethetye, na masya, Ũũ nĩ Ngai waku ũla wakumisye Misili, na maĩ maneeka mothatyo manene;'),
('kam', 'NEH', 9, 19, 'ĩndĩ we kwondũ wa matei maku maingĩ ndwaamatia weũnĩ: kĩtuĩ kya mũumbĩ kĩtyaauma ĩũlũ woo mũthenya, kĩmatongoesye nzĩanĩ; kana kĩtuĩ kya mwaki ũtukũ, kĩmanenge kyeni na kũmon’ya nzĩa ĩla maĩle kũthi nayo.'),
('kam', 'NEH', 9, 20, 'O na wanengane Veva waku mũseo amamanyĩsye, na ndwaamavata lĩu waku wĩtawa mana makanyw’anĩ moo, na wamanenga manzĩ ũndũ wa waũni woo.'),
('kam', 'NEH', 9, 21, 'Ĩĩ, wameanĩsya mavata myaka mĩongo ĩna weũnĩ, na matyaĩ vata na kĩndũ; ngũa syoo ityaakũa, na maũũ moo matyaaimba.'),
('kam', 'NEH', 9, 22, 'Na ĩngĩ wamanenga mosumbĩ na ngo sya andũ, ila wamaaanĩsye kwĩanana na ianda syoo: kwondũ wa ũu mamesya nthĩ ya Sioni, o nthĩ ya mũsumbĩ wa Evisoni, na nthĩ ya Oku mũsumbĩ wa Mbasani.'),
('kam', 'NEH', 9, 23, 'O na waingĩvya syana syoo ta ndata sya ĩtunĩ, na wamaete malike nthĩ ĩla watavisye aaĩthe moo ũndũ wayo, kana makamĩlika mamĩmesye.'),
('kam', 'NEH', 9, 24, 'Na ĩndĩ ana malika mamĩmesya ĩ nthĩ, naku wamakĩlĩlya ala matwĩe ĩ nthĩ vinya mbee woo, o Akanaani, na wamanengane mokonĩ moo, vamwe na asumbĩ moo, na ngo sya andũ sya ĩ nthĩ, nĩ kana mameke o ũndũ mekwenda.'),
('kam', 'NEH', 9, 25, 'Na makwata ndũa mbiie, na nthĩ nou, na makwata nyũmba syusũĩte syĩndũ syonthe nzeo syĩthĩwe syoo, na ithima ila syakĩtwe, na mĩũnda ya mĩsavivũ, na mĩũnda ya mĩthata, na mĩtĩ mingĩ mũno ĩsyaaa matunda: na ĩndĩ maya na mavũna, na manoa, na meetanĩthya ũseonĩ waku mũnene.'),
('kam', 'NEH', 9, 26, 'O na ũu w’onthe, malea kwĩw’a, na makũng’endea, na mekya mĩao yaku ĩtina woo, na mooaa athani maku ala mamakũsĩĩa mamatũnge ĩngĩ kwaku, na meeka mothatyo manene.'),
('kam', 'NEH', 9, 27, 'Kwondũ wa ũu wamanengane kw’okonĩ kwa amaitha moo, ala mamathĩnisye: na ĩvinda ya thĩna woo, yĩla makwĩkaĩlile, weew’a wĩ ĩtunĩ; na kwĩanana na matei maku maingĩ wamanenga atangĩĩi ala mamatangĩĩie kũmaumya kw’okonĩ kwa amaitha moo.'),
('kam', 'NEH', 9, 28, 'Ĩndĩ mamina kũthũmũa, meeka ũthũku ĩngĩ wene; kwondũ wa ũu wamaeka kw’okonĩ kwa amaitha moo, nao mamasumbĩka: ĩndĩ yĩla masyokie, na makwĩkaĩla, weew’a wĩ ĩtunĩ; na wamavonokya mavinda maingĩ kwĩanana na matei maku,'),
('kam', 'NEH', 9, 29, 'na wamakũsĩĩa, nĩ kana ũmaete ĩngĩ mĩaonĩ yaku. Ĩndĩ nao meeka na ngathĩĩo, na matyaaĩthukĩĩsya mĩao yaku, ĩndĩ mavĩtya motw’ĩo maku (ala ethĩwa mũndũ nũmekaa, akekala thayũ nthĩnĩ wamo), na makwambatĩsya kĩtuo, na moomya ngingo syoo, na malea kwĩthukĩĩsya.'),
('kam', 'NEH', 9, 30, 'Ĩndĩ woomĩĩsye nao myaka mingĩ, na wamakũsĩĩa na Veva waku na makanyw’a ma athani maku: ĩndĩ matyaatea matũ: kwondũ wa ũu wamanengane kw’okonĩ kwa ngo sya andũ sya i nthĩ.'),
('kam', 'NEH', 9, 31, 'O na ũu w’onthe, ũndũ wa matei maku maingĩ ndwaamamina vyũ, o na ndwaamatia; nũndũ wĩ Ngai mũseo na wĩ wa tei.'),
('kam', 'NEH', 9, 32, 'Na ĩndĩ kwondũ wa ũu, Ngai waitũ, Ngai mũnene, na wĩ vinya, na wa ũtĩsya, ũla wĩanĩasya ũtianĩo na ũseo wĩ wendo, thĩna w’onthe ũla watũkwatie ithyĩ, na asumbĩ maitũ, na anene maitũ me mbee ũsumbĩnĩ, na athembi maitũ, na athani maitũ, na aaithe maitũ, na andũ maku onthe, kuma ĩvinda ya asumbĩ ma Asuli kũvika mũnthĩ ũũ, ndũkoneke ta mũnini vala ũĩ.'),
('kam', 'NEH', 9, 33, 'Ĩndĩ wĩ mũlũngalu ũndũnĩ w’onthe ũla watũkwatie; nũndũ naku nĩwĩkĩte na w’o, ĩndĩ ithyĩ nĩtwĩkĩte ũthũku;'),
('kam', 'NEH', 9, 34, 'o na asumbĩ maitũ, o na anene maitũ me mbee ũsumbĩnĩ, o na athembi maitũ, o na aaĩthe maitũ, matyaasũvĩa mĩao yaku, kana kwĩthukĩĩsya myamũlo yaku na mokũsĩ maku, ala wamakũsĩĩe namo.'),
('kam', 'NEH', 9, 35, 'Nũndũ matyaakũthũkũma ũsumbĩnĩ woo, o na ũseonĩ waku mũnene ũla wamonisye, o na nthĩnĩ wa nthĩ nene na nou ĩla wamanengie mene, o na matyaaĩthyũũa matie mawĩa moo mathũku.'),
('kam', 'NEH', 9, 36, 'Sisya, twĩ athũkũmi ũmũnthĩ, na ũndũ wa nthĩ ĩla wanengie aaĩthe maitũ maye ũsyao wayo na ũseo wayo, sisya, twĩ athũkũmi nthĩnĩ wayo.'),
('kam', 'NEH', 9, 37, 'Nayo nĩnĩũmasyaĩa wingĩvo mwingĩ asumbĩ ala wamaiie ĩũlũ waitũ nũndũ wa naĩ sitũ: o na me na vinya ĩũlũ wa mĩĩ yaitũ, na indo sitũ, o ũndũ mekwenda, na ithyĩ twĩ na thĩna mwingĩ.'),
('kam', 'NEH', 9, 38, 'Ĩndĩ o na ũu w’onthe nĩtũũtianĩa ũtianĩo mũlũmu, na kũandĩka; na anene maitũ me mbee ũsumbĩnĩ, na Alivai maitũ, na athembi maitũ, nĩmekũwĩkĩa ũsiĩlo.'),
('kam', 'NEH', 10, 1, 'Na ĩndĩ ala meekĩie ũsiĩlo nĩo aa: ngavana Neemia, mwana wa Akalia, na Nzetekia,'),
('kam', 'NEH', 10, 2, 'na Selaia, na Asalia, na Yelemia,'),
('kam', 'NEH', 10, 3, 'na Vasuli, na Amalia, na Malikaya,'),
('kam', 'NEH', 10, 4, 'na Atusi, na Sevania, na Maluku,'),
('kam', 'NEH', 10, 5, 'na Alimu, na Melemothi, na Ovatia,'),
('kam', 'NEH', 10, 6, 'na Ndanieli, na Nginethoni, na Mbaluku,'),
('kam', 'NEH', 10, 7, 'na Mesulamu, na Aviya, na Miyamini,'),
('kam', 'NEH', 10, 8, 'na Maasia, na Mbilikai, na Semaia; asu maĩ athembi.'),
('kam', 'NEH', 10, 9, 'Na Alivai nĩmo aa: Yesua mwana wa Asania, na Mbinui, wa ana ma Enatati, na Katimieli:'),
('kam', 'NEH', 10, 10, 'na ana‐a‐ĩthe moo, Sevania, na Otia, na Kelita, na Velaia, na Aananu,'),
('kam', 'NEH', 10, 11, 'na Mika, na Leovu, na Asavia,'),
('kam', 'NEH', 10, 12, 'na Nzakuli, na Selevia, na Sevania,'),
('kam', 'NEH', 10, 13, 'na Otia, na Mbani, na Mbeninu.'),
('kam', 'NEH', 10, 14, 'Anene ma andũ: Valosi, na Vaathi‐moavi, na Elamu, na Nzatu, na Mbani,'),
('kam', 'NEH', 10, 15, 'na Mbuni, na Asikati, na Mbevai,'),
('kam', 'NEH', 10, 16, 'na Atoniya, na Mbikivai, na Atini,'),
('kam', 'NEH', 10, 17, 'na Ateli, na Esekia, na Asulu,'),
('kam', 'NEH', 10, 18, 'na Otia, na Asumu, na Mbenzai,'),
('kam', 'NEH', 10, 19, 'na Alivu, na Anathothi, na Novai,'),
('kam', 'NEH', 10, 20, 'na Makiviasi, na Mesulamu, na Eesili,'),
('kam', 'NEH', 10, 21, 'na Mesesaveli, na Nzatoki, na Yatua,'),
('kam', 'NEH', 10, 22, 'na Velatia, na Aananu, na Anaia,'),
('kam', 'NEH', 10, 23, 'na Osea, na Aanania, na Asuvu,'),
('kam', 'NEH', 10, 24, 'na Aloesi, na Vilia, na Soveki,'),
('kam', 'NEH', 10, 25, 'na Leumu, na Asavina, na Maaseia,'),
('kam', 'NEH', 10, 26, 'na Aiya, na Aananu, na Ananu,'),
('kam', 'NEH', 10, 27, 'na Maluku, na Alimu, na Mbaana.'),
('kam', 'NEH', 10, 28, 'Na andũ ala angĩ, athembi, na Alivai, na asũvĩi ma mĩomonĩ, na aini, na Anethini, na onthe ala meevathĩte kuma ngonĩ sya andũ sya i nthĩ makwate mĩao ya Ngai, na iveti syoo, na ana moo, na eĩtu moo, kĩla ũmwe ũla waĩ na ũĩ na ũmanyi;'),
('kam', 'NEH', 10, 29, 'malũman’ya na ana‐a‐ĩthe moo, anene moo me ndaĩa, na meelikya kĩumonĩ, na wĩvĩtonĩ, maendae mĩaonĩ ya Ngai, ĩla yanenganiwe nĩ Mose mũthũkũmi wa Ngai, na kũsũvĩa kwĩkaa mĩao yonthe ya Yeova Mwĩaĩi waitũ, na motw’ĩo make na mĩao yake;'),
('kam', 'NEH', 10, 30, 'na kana tũtikanengane eĩtu maitũ kwa ngo sya andũ sya nthĩ ĩsu, kana kũmatwaĩa ana maitũ eĩtu moo;'),
('kam', 'NEH', 10, 31, 'na ethĩwa ngo sya andũ sya ĩ nthĩ ikaete syĩndũ kana lĩu o na wĩva mathoosye mũthenya wa savato, tũtikamathooee mũthenya wa savato, kana mũthenya mũtheu; o na tũkaeka mwaka wa mũonza, na kũandũa kwa kĩla thiĩ.'),
('kam', 'NEH', 10, 32, 'Na ĩngĩ nĩtweetw’ĩĩe motw’ĩo, twĩyumĩthye kĩla mwaka kĩlungu kya katatũ kya sekeli ũndũ wa ũthũkũmi wa nyũmba ya Ngai waitũ;'),
('kam', 'NEH', 10, 33, 'ũndũ wa imũtũ ila siĩawa Yeova, na ũndũ wa nthembo ya mũtu ĩtatw’ĩkanaa, na ũndũ wa nthembo ya kũvĩvw’a ĩla ĩtatw’ĩkanaa, na ũndũ wa masavato, na mĩtiso ya myei, na mboka itw’ĩtwe, na syĩndũ ntheu, na nthembo kwondũ wa naĩ syĩthĩwe wĩw’anĩthyo wa Isilaeli, na ũndũ wa wĩa w’onthe wa nyũmba ya Ngai waitũ.'),
('kam', 'NEH', 10, 34, 'Na twalimana, athembi, na Alivai, na andũ, ũndũ wa nthembo ya ngũ, ietawe nyũmbanĩ ya Ngai waitũ, kwĩanana na nyũmba sya aaĩthe maitũ, mavinda matw’ĩtwe, mwaka na mwaka, ivĩvaw’e kĩthembeonĩ kya Yeova Ngai waitũ, o tondũ kũandĩkĩtwe mĩaonĩ;'),
('kam', 'NEH', 10, 35, 'na tũetae nyũmbanĩ ya Yeova ũsyao wa mbee wa nthĩ yaitũ, na ũsyao wa mbee wa ũsyao w’onthe wa mĩtĩ ya mĩthemba yonthe, mwaka na mwaka;'),
('kam', 'NEH', 10, 36, 'o na kĩla kĩsyaĩtwe mbee kya ana maitũ, na kya indo sitũ, o tondũ kũandĩkĩtwe mĩaonĩ, na kĩla kĩsyaĩtwe mbee kya ndĩthya sitũ sya ng’ombe na ndĩthya sitũ sya mbũi na malondu, kĩetawe nyũmbanĩ ya Ngai waitũ, kĩthĩwe kya athembi ala mathũkũmaa nyũmbanĩ ya Ngai waitũ;'),
('kam', 'NEH', 10, 37, 'na tũmaetee athembi tũsũmbanĩ twa nyũmba ya Ngai waitũ ũsyao wa mbee wa mũtu witũ, na nthembo sitũ sya kũkĩlw’a, na ũsyao wa mĩthemba yonthe ya mĩtĩ, na mbinyu mbĩthĩ na mauta; na ilungu sya ĩkũmi sya nthĩ yaitũ tũmaetee Alivai; nĩkwĩthĩwa nao Alivai, nĩmosaa ilungu sya ĩkũmi ndũanĩ syonthe kũla tũĩmaa.'),
('kam', 'NEH', 10, 38, 'Na mũthembi mwana wa Aluni akethĩwaa vo na Alivai yĩla Alivai meosaa ilungu sya ĩkũmi: na Alivai makaetae kĩlungu kya ĩkũmi kya ilungu isu sya ĩkũmi nyũmbanĩ ya Ngai waitũ, tũsũmbanĩ, nyũmbanĩ ya kwia mothwii.'),
('kam', 'NEH', 10, 39, 'Nũndũ ana ma Isilaeli na ana ma Livai makaete nthembo ya kũkĩlw’a ya lĩu wa mbaa ngetha, na ya mbinyu mbĩthĩ, na ya mauta, tũsũmbanĩ, vala ve mĩio ya vala vandũ vatheu, na athembi ala mathũkũmaa, na asũvĩi ma mĩomonĩ, na aini: na tũtikaeka nyũmba ya Ngai waitũ.'),
('kam', 'NEH', 11, 1, 'Na anene me mbee ũsumbĩnĩ ma andũ nĩmatũaa Yelusaleme: o na andũ ala angĩ malimana, nĩ kana maete kĩla andũ ĩkũmi ũmwe akatũae Yelusaleme ndũa ntheu, na ala kenda matũae ndũanĩ ila ingĩ.'),
('kam', 'NEH', 11, 2, 'Na andũ mamaathima andũ onthe ala meenenganie na kwenda kwa ngoo matuae Yelusaleme.'),
('kam', 'NEH', 11, 3, 'Aa ĩndĩ nĩo anene ma ĩ kĩlungu kĩnene kya nthĩ ala matwĩe Yelusaleme: ĩndĩ ndũanĩ sya Yuta kĩla mũndũ nĩwekalaa ng’ũndũnĩ yake mwene ndũanĩ syoo, nao nĩ aa, Isilaeli, na athembi, na Alivai, na Anethini, na ana ma athũkũmi ma Solomoni.'),
('kam', 'NEH', 11, 4, 'Na amwe ma ana ma Yuta, na ma ana ma Mbenyamini nĩmatũaa Yelusaleme. Ma ana ma Yuta: Athaia mwana wa Usia, mwana wa Nzekalia, mwana wa Amalia, mwana wa Sevatia, mwana wa Maalaleli, wa ana ma Velesi;'),
('kam', 'NEH', 11, 5, 'na Maaseia mwana wa Mbaluku, mwana wa Koli‐ose, mwana wa Aasaia, mwana wa Ataia, mwana wa Yoialivu, mwana wa Nzekalia, mwana wa Mũsilo.'),
('kam', 'NEH', 11, 6, 'Ana onthe ma Velesi ala matwĩe Yelusaleme maĩ andũ me ũkũmbaũ maana ana na mĩongo thanthatũ na nyanya.'),
('kam', 'NEH', 11, 7, 'Na aa nĩo ana ma Mbenyamini: Salu mwana wa Mesulamu, mwana wa Yoeti, mwana wa Vetaia, mwana wa Kolaia, mwana wa Maaseia, mwana wa Ithieli, mwana wa Yesaia.'),
('kam', 'NEH', 11, 8, 'Na ĩtina wake Ngavai, na Salai, maana kenda na mĩongo ĩlĩ na nyanya.'),
('kam', 'NEH', 11, 9, 'Na Yoeli mwana wa Nzikili aĩ mũsyaĩĩsya woo; na Yuta mwana wa Asenua aĩ wa kelĩ wa kũsyaĩĩsya ndũa.'),
('kam', 'NEH', 11, 10, 'Na athembi: Yetaia mwana wa Yoialivu, na Yakini,'),
('kam', 'NEH', 11, 11, 'na Selaia mwana wa Ilikia, mwana wa Mesulamu, mwana wa Nzatoki, mwana wa Melaiothi, mwana wa Aituvu, mũtongoi nyũmbanĩ ya Ngai,'),
('kam', 'NEH', 11, 12, 'vamwe na ana‐a‐ĩthe moo ala matethasya wĩa wa ĩ nyũmba, maana nyanya na mĩongo ĩlĩ na elĩ; na Ataia mwana wa Yeloamu, mwana wa Velalia, mwana wa Amisi, mwana wa Nzekalia, mwana wa Vasuli, mwana wa Malikiya,'),
('kam', 'NEH', 11, 13, 'vamwe na ana‐a‐ĩthe make, anene ma nyũmba sya aaĩthe, maana elĩ na mĩongo ĩna na elĩ; na Amasaai mwana wa Asaleeli, mwana wa Aasai, mwana wa Mesilemothi, mwana wa Imeli,'),
('kam', 'NEH', 11, 14, 'vamwe na ana‐a‐ĩthe moo, ngũmbaũ nene, ĩana na mĩongo ĩlĩ na nyanya. Na mũsyaĩĩsya woo aĩ Nzavitieli, mwana wa Aketolimu.'),
('kam', 'NEH', 11, 15, 'Na ma Alivai: Semaia mwana wa Asuvu, mwana wa Asilikamu, mwana wa Asavia, mwana wa Mbuni;'),
('kam', 'NEH', 11, 16, 'na Savethai na Yosavati, ma anene ma Alivai, ala maĩ asyaĩĩsya ma wĩa wa nza wa nyũmba ya Ngai;'),
('kam', 'NEH', 11, 17, 'na Matania mwana wa Mika, mwana wa Nzaveti, mwana wa Asavu, ũla waĩ mũtongoesya wa kwambĩlĩlya kũtũnga mũvea mboyanĩ, na Mbakivukia, ũla waĩ wa kelĩ katĩ wa ana‐a‐ĩthe make; na Avata mwana wa Samua, mwana wa Ngalali, mwana wa Yetuthuni.'),
('kam', 'NEH', 11, 18, 'Alivai onthe ĩla ndũanĩ ntheu maĩ maana elĩ na mĩongo nyanya na ana.'),
('kam', 'NEH', 11, 19, 'O na asũvĩi ma mĩomonĩ, Akuvu na Talimoni, na ana‐a‐ĩthe moo, ala masyaĩĩasya mbingĩlonĩ, maĩ ĩana na mĩongo mũonza na elĩ.'),
('kam', 'NEH', 11, 20, 'Na ala angĩ ma Isilaeli, ma athembi, Alivai, maĩ ndũanĩ syonthe sya Yuta, kĩla ũmwe ũtiĩwanĩ wake.'),
('kam', 'NEH', 11, 21, 'Ĩndĩ Anethini nĩmatũaa Oveli: na Nziia na Ngisiva maĩ asyaĩĩsya ma Anethini.'),
('kam', 'NEH', 11, 22, 'O na mũsyaĩĩsya wa Alivai ku Yelusaleme aĩ Usisi mwana wa Mbani, mwana wa Asavia, mwana wa Matania, mwana wa Mika, wa ana ma Asavu, ala maĩ aini, asyaĩĩsya ma wĩa wa nyũmba ya Ngai.'),
('kam', 'NEH', 11, 23, 'Nũndũ kwaĩ mwĩao wumĩte kwa mũsumbĩ ũndũ woo, na wĩanĩsyo wa mavata nũtw’ĩtwe kwondũ wa aini, o tondũ mavata ma kĩla mũthenya meanaa.'),
('kam', 'NEH', 11, 24, 'Na Vethaia mwana wa Mesesaveli, wa ana ma Nzela, mwana wa Yuta, aiĩtwe nĩ mũsumbĩ aseũvye maũndũ onthe ma andũ.'),
('kam', 'NEH', 11, 25, 'Na ũndũ wa mĩsyĩ, na mĩũnda yayo, amwe ma ana ma Yuta nĩmatũaa Kiliathi‐aliva na tũtũla twayo, na Ndivoni na tũtũla twayo, na Yekaviseeli na mĩsyĩ yayo,'),
('kam', 'NEH', 11, 26, 'na ku Yesua, na Molata, na Mbethi‐veleti,'),
('kam', 'NEH', 11, 27, 'na Asali‐suali, na Mbeeli‐sieva na tũtũla twayo,'),
('kam', 'NEH', 11, 28, 'na Nzikilaki, na Mekona na tũtũla twayo,'),
('kam', 'NEH', 11, 29, 'na Enilimoni, na Nzola, na Yalimuthi,'),
('kam', 'NEH', 11, 30, 'na Nzanoa, na Atulumu, na mĩsyĩ yasyo, na Lakisi na mĩũnda yayo, na Aseka na tũtũla twayo. Na ĩndĩ nĩmambie maeema moo kuma Mbeeli‐sieva kũvika kyanda kya Inomu.'),
('kam', 'NEH', 11, 31, 'Ana ma Mbenyamini nao nĩmatũaa kuma Ngeva na mbee wa kw’o, Mikimasi na Aiya, na ku Mbethi‐eli na tũtũla twayo,'),
('kam', 'NEH', 11, 32, 'na Anathothi, na Novu, na Anania,'),
('kam', 'NEH', 11, 33, 'na Asoli, na Lama, na Ngitaimu,'),
('kam', 'NEH', 11, 34, 'na Atiti, na Nzevoimu, na Nevalati,'),
('kam', 'NEH', 11, 35, 'na Loti, na Ono, kyandanĩ kya ndũĩka.'),
('kam', 'NEH', 11, 36, 'Na ma Alivai, nguthu imwe sya Yuta syavulana na Mbenyamini.'),
('kam', 'NEH', 12, 1, 'Na ĩndĩ aa nĩo athembi na Alivai ala mambatie vamwe na Nzeluvaveli mwana wa Sealitieli, na Yesua: Selaia, na Yelemia, na Esala,'),
('kam', 'NEH', 12, 2, 'na Amalia, na Maluku, na Atusi,'),
('kam', 'NEH', 12, 3, 'na Sekania, na Leumu, na Melemothi,'),
('kam', 'NEH', 12, 4, 'na Ito, na Nginethoi, na Aviya,'),
('kam', 'NEH', 12, 5, 'na Miyamini, na Maatia, na Mbilika,'),
('kam', 'NEH', 12, 6, 'na Semaia, na Yoialivu, na Yetaia,'),
('kam', 'NEH', 12, 7, 'na Salu, na Amoki, na Ilikia, na Yetaia. Asu nĩo anene ma athembi na ma ana‐a‐ĩthe moo mĩthenyanĩ ya Yesua.'),
('kam', 'NEH', 12, 8, 'Na ĩngĩ Alivai: Yesua, na Mbinui, na Katimieli, na Selevia, na Yuta, na Matania, ũla waĩ mũtongoesya wa ala matũngaa mũvea, we na ana‐a‐ĩthe make.'),
('kam', 'NEH', 12, 9, 'O na Mbakivukia na Uni, ana‐a‐ĩthe moo, mamathengeea kũatĩĩa mosyaĩĩsyo moo.'),
('kam', 'NEH', 12, 10, 'Na Yesua asyaa Yoiakimu, na Yoiakimu asyaa Eliasivu, na Eliasivu asyaa Yoiata,'),
('kam', 'NEH', 12, 11, 'na Yoaita asyaa Yonathani, na Yonathani asyaa Yatua.'),
('kam', 'NEH', 12, 12, 'Na mĩthenyanĩ ya Yoiakimu kwaĩ athembi, atongoi ma nyũmba sya aaĩthe: wa Selaia, nĩ Melaia; wa Yelemia, nĩ Aanania;'),
('kam', 'NEH', 12, 13, 'wa Esala, nĩ Mesulamu; wa Amalia, nĩ Yeoanani;'),
('kam', 'NEH', 12, 14, 'wa Maluki, nĩ Yonathani; wa Sevania, nĩ Yosevu;'),
('kam', 'NEH', 12, 15, 'wa Alimu, nĩ Atena, wa Melaiothi, nĩ Elikai;'),
('kam', 'NEH', 12, 16, 'wa Ito, nĩ Nzekalia; wa Nginethoni, nĩ Mesulamu;'),
('kam', 'NEH', 12, 17, 'wa Aviya, nĩ Nzikili; wa Miniamini, wa Moatia, nĩ Vilitai;'),
('kam', 'NEH', 12, 18, 'wa Mbilika, nĩ Samua; wa Semaia, nĩ Yonathani;'),
('kam', 'NEH', 12, 19, 'na wa Yoialivu, nĩ Matenai; wa Yetaia, nĩ Usisi;'),
('kam', 'NEH', 12, 20, 'wa Salai, nĩ Kalai; wa Amoki, nĩ Eveli;'),
('kam', 'NEH', 12, 21, 'wa Ilikia, nĩ Asavia; wa Yetaia, nĩ Nethaneli.'),
('kam', 'NEH', 12, 22, 'Ũndũ wa Alivai, mĩthenyanĩ ya Eliasivu, na Yoiata, na Yoanani, na Yatua, nĩkwaandĩkiwe atongoi ma nyũmba sya aaĩthe; o na athembi, ũsumbĩkonĩ wa Ndalio Mũvelisia.'),
('kam', 'NEH', 12, 23, 'Ana ma Livai, atongoi ma nyũmba sya aaĩthe, nĩmaandĩkiwe ĩvukunĩ ya maũndũ ma mavinda o kũvika mĩthenya ya Yoanani mwana wa Eliasivu.'),
('kam', 'NEH', 12, 24, 'Na anene ma Alivai: Asavia, na Selevia, na Yesua mwana wa Katimieli, vamwe na ana‐a‐ĩthe moo ala mamathengeee, mataĩae na kũtũngaa mũvea, kwĩanana na mwĩao wa Ndaviti mũndũ wa Ngai, ũsyaĩĩsyo na ũsyaĩĩsyo.'),
('kam', 'NEH', 12, 25, 'Matania, na Mbakivukia, na Ovatia, na Mesulamu, na Talimoni, na Akuvu, maĩ asũvĩi ma mĩomonĩ makĩsyaĩĩsya nyũmba sya kwia mĩio syĩ mbingĩlonĩ.'),
('kam', 'NEH', 12, 26, 'Asu nĩo maĩ mĩthenyanĩ ya Yoiakimu mwana wa Yesua, mwana wa Yosataki, na mĩthenyanĩ ya ngavana Neemia, na ya mũthembi Esala mũandĩki.'),
('kam', 'NEH', 12, 27, 'Na ĩvinda ya kũvatha ũvai wa Yelusaleme wĩthĩwe mũtheu nĩmamanthie Alivai mamuamya kũndũ kwoo kw’onthe, mamaete Yelusaleme, malilikane na ũtanu kũvatha kwa ũvai wĩthĩwe mũtheu, makĩtũnga mũvea, o na makina, me na tũmasaya, na inanda, na mbeve.'),
('kam', 'NEH', 12, 28, 'Na ana ma aini moombana, kuma ũiĩnĩ ũla ũthyũlũlũkĩte Yelusaleme, o na kuma mĩsyĩ ya Anetovathi;'),
('kam', 'NEH', 12, 29, 'na Mbethingilikali, na kuma mĩũndanĩ ya Ngeva na Asimuvethi: nũndũ aini nĩmeeyakĩe mĩsyĩ kũthyũlũlũka Yelusaleme.'),
('kam', 'NEH', 12, 30, 'Na athembi na Alivai meethesya; na mathesya andũ, na i mbingĩlo, na ũvai.'),
('kam', 'NEH', 12, 31, 'Nĩvo ĩndĩ nambatisye anene me mbee ũsumbĩnĩ ma Yuta ũvainĩ ĩũlũ, na naia nguthu ilĩ nene ila syatũngaa mũvea na syaenda iatĩanĩe; nguthu ĩmwe yaenda ngalĩ ya kw’oko kwa aũme ĩũlũ wa ũvai kwelekela mbingĩlo ya kumĩlya vũũ:'),
('kam', 'NEH', 12, 32, 'na ĩtina wa ĩsu kwaendie Osaia, na nyunzu ya anene me mbee ũsumbĩnĩ ma Yuta,'),
('kam', 'NEH', 12, 33, 'na Asalia, na Esala, na Mesulamu,'),
('kam', 'NEH', 12, 34, 'na Yuta, na Mbenyamini, na Semaia, na Yelemia,'),
('kam', 'NEH', 12, 35, 'na amwe ma ana ma athembi me na masoo: Nzekalia mwana wa Yonathani, mwana wa Semaia, mwana wa Matania, mwana wa Mikaia, mwana wa Nzakuli, mwana wa Asavu;'),
('kam', 'NEH', 12, 36, 'vamwe na ana‐a‐ĩthe make, Semaia, na Asaleeli, na Milalai, na Ngilalai, na Maai, na Nethaneli, na Yuta, na Aanani, me na syĩndũ sya kũinga sya Ndaviti mũndũ wa Ngai; na mũandĩki Esala amatongoesya.'),
('kam', 'NEH', 12, 37, 'Na vakuvĩ na mbingĩlo ya nthongo ya manzĩ, na kũenda maeleele, mambata mbasyanĩ sya ndũa ya Ndaviti, kyambatonĩ kya ũvai ĩũlũ wa nyũmba ya Ndaviti, o kũvika mbingĩlo ya manzĩ kwelekela ngalĩ ya wumĩlonĩ wa syũa.'),
('kam', 'NEH', 12, 38, 'Na nguthu ĩla ĩngĩ yamo ĩla yatũngaa mũvea yamathaũa, nakwa namaatĩĩa, vamwe na nyũnzu ya andũ, ĩũlũ wa ũvai, mbee wa mwako mũtũlu wa mũnyoolo wĩ maiko manene, o kũvika ũvainĩ mũthanthau,'),
('kam', 'NEH', 12, 39, 'na mbee wa mbingĩlo ya Evalaimu, na vakuvĩ na mbingĩlo ya tene, na vakuvĩ na mbingĩlo ya makũyũ, na mwako mũtũlu wa mũnyoolo wa Ananeli, na mwako mũtũlu wa mũnyoolo wa Amea, o kũvika mbingĩlo ya malondu: na maũngama mbingĩlonĩ ya nguthu ya asũvĩi.'),
('kam', 'NEH', 12, 40, 'Ũu nĩw’o nguthu isu ilĩ sya ala matũngĩaa mũvea nyũmbanĩ ya Ngai syaũngamie, o nakwa na nyunzu ya asumbĩki vamwe nakwa;'),
('kam', 'NEH', 12, 41, 'na athembi, Eliakimu, na Maaseia, na Miniamini, na Mikaia, na Elioenai, na Nzekalia, na Aanania, me na masoo;'),
('kam', 'NEH', 12, 42, 'na Maaseia, na Semaia, na Eleasali, na Usisi, na Yeoanani, na Malikiya, na Elamu, na Eseli. Na aini maina na wasya mũnene, vamwe na Yesilalia mwinĩthya woo.'),
('kam', 'NEH', 12, 43, 'Na mathemba nthembo nyingĩ mũthenya ũsu, na matana; nũndũ Ngai nĩwamatanĩthisye na ũtanu mũnene; o na aka na syana matana: na ĩndĩ ũtanu wa Yelusaleme weew’ĩkie kũasa.'),
('kam', 'NEH', 12, 44, 'Na mũthenya ũsu andũ nĩmaiiwe masũvĩe tũsũmba tũla twa mothwii maie, na twa nthembo sya kũkĩlw’a, na twa mosyao ma mbee, na twa ilungu sya ĩkũmi, momban’ye nthĩnĩ watw’o, kwĩanana na mĩũnda ya i ndũa, ilungu ila itw’ĩtwe nĩ mĩao kwondũ wa athembi na Alivai: nũndũ Yuta nĩwatanĩe athembi na Alivai ala mathũkũmaa.'),
('kam', 'NEH', 12, 45, 'Na masũvĩaa wĩaĩo wa Ngai woo, na wĩaĩo wa ũthesyo, na aini na asũvĩi ma mĩomonĩ meeka o ũu, kwĩanana na mwĩao wa Ndaviti, na wa Solomoni mwana wake.'),
('kam', 'NEH', 12, 46, 'Nũndũ mĩthenyanĩ ya Ndaviti na Asavu ya tene kwaĩ mũtongoesya wa aini, na mbathi sya ndaĩa na mũvea kwa Ngai.'),
('kam', 'NEH', 12, 47, 'Na mĩthenyanĩ ya Nzeluvaveli, na mĩthenyanĩ ya Neemia Isilaeli onthe nĩmanenganie ilungu sya aini na asũvĩi ma mĩomonĩ, o ũndũ vata wa kĩla mũthenya weanaa: na maia kĩla kya Alivai; na Alivai maia kĩla kyaĩ kya ana ma Aluni.'),
('kam', 'NEH', 13, 1, 'Mũthenya ũsu nĩmasomie ĩvukunĩ ya Mose andũ makĩw’a; na nĩkwoonekie kũandĩkĩtwe nthĩnĩ wayo, atĩ Mũamimoni na Mũmoavi matikalika ũmbanonĩ wa Ngai tene na tene,'),
('kam', 'NEH', 13, 2, 'nĩkwĩthĩwa matyaamathaũsya ana ma Isilaeli kĩmũtũ na manzĩ, ĩndĩ matuvie Mbalaamu, amaumanĩe: ĩndĩ Ngai waitũ aalyũla kĩumo kyu kĩthĩwe ũathimo.'),
('kam', 'NEH', 13, 3, 'Na kweethĩwa, yĩla meewie mĩao, mavatha kwa Isilaeli nguthu yonthe ya elikya.'),
('kam', 'NEH', 13, 4, 'Na ĩndĩ ũu ũtanekĩka, mũthembi Eliasivu, ũla waiiwe asũvĩae tũsũmba twa nyũmba ya Ngai waitũ, nũndũ aĩ na ndũũ na Tovia,'),
('kam', 'NEH', 13, 5, 'aĩ anamũseũvĩsya kasũmba kanene, vala tene maiaa nthembo sya mũtu, na ũvumba, na mĩio, na ilungu sya ĩkũmi sya lĩu wa mbaa ngetha, na mbinyu mbĩthĩ, na mauta, ila syeeaĩtwe inengawe Alivai, na aini, na asũvĩi ma mĩomonĩ; na nthembo sya kũkĩlw’a kwondũ wa athembi.'),
('kam', 'NEH', 13, 6, 'Ĩndĩ ĩvinda yu yonthe ndyaĩ Yelusaleme; nũndũ nĩnaendie kwa mũsumbĩ mwaka wa mĩongo ĩtatũ na ĩlĩ wa kũsumbĩka kwa Alitasasita mũsumbĩ wa Mbaviloni: na ĩtina wa mĩthenya ĩmwe namwĩtya mũsumbĩ ũthei wa kũthi,'),
('kam', 'NEH', 13, 7, 'na navika Yelusaleme, na namanya ũthũku ũla Eliasivu wekie kwondũ wa Tovia, aimũseũvĩsya kasũmba nza sya nyũmba ya Ngai.'),
('kam', 'NEH', 13, 8, 'Na ũndũ ũsu wambĩw’ĩthya woo mũno: kwondũ wa ũu nekĩĩsya nza syĩndũ syonthe vyũ sya Tovia kũsyumya kasũmbanĩ.'),
('kam', 'NEH', 13, 9, 'Nĩvo ĩndĩ neeaie, na mathesya tũsũmba: na naete vo ĩngĩ mĩio ya nyũmba ya Ngai, vamwe na nthembo sya mũtu na ũvumba.'),
('kam', 'NEH', 13, 10, 'Na namanya Alivai matyaanengwa ilungu syoo; na ĩndĩ Alivai na aini, ala matethasya wĩa, nĩmakĩĩte kĩla ũmwe akathi mũũndanĩ wake mwene.'),
('kam', 'NEH', 13, 11, 'Na ĩndĩ natetan’ya na asumbĩki, na nakũlya, Nĩkĩ nyũmba ya Ngai ĩtiĩtwe? Na namomban’ya na naia kĩla mũndũ vandũ vake.'),
('kam', 'NEH', 13, 12, 'Nĩvo ĩndĩ Yuta onthe maetie kĩlungu kya ĩkũmi kya lĩu wa mbaa ngetha na mbinyu mbĩthĩ na mauta kũla kwiawa syĩndũ.'),
('kam', 'NEH', 13, 13, 'Na naia asũvĩi ma ũsũvĩaa kũla kwiawa ũthwii, mũthembi Selemia, na mũandĩki Nzatoki, na wa Alivai, Vetaia: na ĩtina woo kwaĩ Aananu mwana wa Nzakuli, mwana wa Matania; nũndũ nĩmatalwa me kĩthito, na wĩa woo waĩ wa kũmaaanĩsya ana‐a‐ĩthe moo.'),
('kam', 'NEH', 13, 14, 'Ame Ngai wakwa, ndilikana ũndũnĩ ũsu, na ndũkavute meko makwa maseo ala neekie kwondũ wa nyũmba ya Ngai wakwa, na kwondũ wa mawĩa mayo.'),
('kam', 'NEH', 13, 15, 'Mĩthenya ĩsu nĩnoonie Yuta andũ amwe makĩkinyanga iangĩo sya mbinyu savatonĩ, o na makĩete syove sya ngetha, makuĩthĩtye mang’oi; o na mbinyu, na nzavivũ, na makũyũ, na mĩthenya yonthe ya mĩio, ĩla malikilye Yelusaleme mũthenya wa savato: nakwa namakũsĩĩa mũthenya ũla mathooisye lĩu.'),
('kam', 'NEH', 13, 16, 'O na andũ ma Tile nĩmatwĩe vo nthĩnĩ, ala maetie makũyũ, na mĩthemba yonthe ya syĩndũ sya ũthoosya, na mamathooesye ana ma Yuta mũthenya wa savato, o na nthĩnĩ wa Yelusaleme.'),
('kam', 'NEH', 13, 17, 'Nĩvo ĩndĩ natetanisye na anene me ndaĩa ma Yuta, na namakũlya, Ũndũ ũũ ũthũku ũla mũkwĩka nĩ mwaũ, na kũvukya mũthenya wa savato?'),
('kam', 'NEH', 13, 18, 'Aaĩthe menyu matyaaĩka ũu, na Ngai waitũ ndaatũetee ũthũku ũũ w’onthe, o na ndũanĩ ĩno? Ĩndĩ inyw’ĩ nĩmũetee Isilaeli ũthilĩku ũngĩ ũndũ wa kũvukya savato.'),
('kam', 'NEH', 13, 19, 'Na kweethĩwa, yĩla mbingĩlo sya Yelusaleme syambĩlĩlye kũya ũmololi savato ũtanamba kũvika, neeaa mĩomo ĩvingwe, na neeaa ndĩkavingũwe kũvika savato wathela: na naia athũkũmi amwe makwa masũvĩe i mbingĩlo, mũio o na wĩva ndũkalikwe nthĩnĩ mũthenya wa savato.'),
('kam', 'NEH', 13, 20, 'Kwondũ wa ũu atandĩthya na athoosya ma mĩthemba yonthe ya syĩndũ makoma ũtee wa Yelusaleme ĩvinda yĩmwe kana kelĩ.'),
('kam', 'NEH', 13, 21, 'Nĩvo ĩndĩ namakũsĩĩie, na namakũlya, Mwĩkoma mũthengeee ũvai nĩkĩ? Ethĩwa mũkeeka ũu ĩngĩ ngamũkwata. Kuma ĩvinda yĩu matyaaũka ĩngĩ mũthenya wa savato.'),
('kam', 'NEH', 13, 22, 'Nakwa nameaĩa Alivai meevathan’ye methĩwe atheu, na moke masũvĩe i mbingĩlo, mavathan’ye mũthenya wa savato wĩthĩwe mũtheu. Ame Ngai wakwa, ndilikanĩla ũndũ ũsu naw’o, noindeka kwĩanana na ũnene wa ũseo waku wĩ wendo.'),
('kam', 'NEH', 13, 23, 'O na mĩthenya ĩsu nĩnoonie Ayuti ala matwaĩte aka ma Asitoti, na ma Amimoni, na ma Moavi:'),
('kam', 'NEH', 13, 24, 'na ana moo nĩmaneenaa nyunzu ya kĩthyomo kya Asitoti, na matyaatonya kũneena kĩthyomo kya Ayuti, ĩndĩ kwĩanana na kĩthyomo kya kĩla ũko wa andũ.'),
('kam', 'NEH', 13, 25, 'Nakwa natetan’ya nao, na namaumanĩa, na nakũna amwe moo, na nakũa nzw’ĩĩ syoo, na nameavĩthya na Ngai, ngĩmea, Mũtikaamanenge ana moo eĩtu menyu, kana mũtikaamatwaĩe ana menyu eĩtu moo, o na kũmatwaa ũndũ wenyu ene.'),
('kam', 'NEH', 13, 26, 'Solomoni mũsumbĩ wa Isilaeli ndaaĩka naĩ maũndũnĩ asu? Ĩndĩ mbaĩnĩ nyingĩ vatyaĩ mũsumbĩ wailyĩ take, na endwa nĩ Ngai wake, na Ngai amũtw’ĩkĩthya mũsumbĩ wa Isilaeli onthe: ĩndĩ o nake aka ma nthĩ ĩngĩ mamũvĩtĩthya.'),
('kam', 'NEH', 13, 27, 'Tũkamwĩw’a inyw’ĩ ĩndĩ twĩke ũthũku ũũ w’onthe, tũmũvĩtanĩsye Ngai waitũ tũkĩtwaa aka ma nthĩ ĩngĩ?'),
('kam', 'NEH', 13, 28, 'Na mwana ũmwe wa Yoiata, mwana wa mũthembi mũnene Eliasivu, aĩ mũthoni wa Sanavalati Mũoloni: kwondũ wa ũu namũlũngya aume vala nĩĩ.'),
('kam', 'NEH', 13, 29, 'Ame Ngai wakwa, malilikane, nĩkwĩthĩwa nĩmavukĩtye ũthembi, na ũtianĩo wa ũthembi, na wa Alivai.'),
('kam', 'NEH', 13, 30, 'Ũu nĩw’o namatheisye ngĩmavathan’ya na andũ onthe ma nthĩ ĩngĩ, na naia mosyaĩĩsyo ũndũ wa athembi na ũndũ wa Alivai, kĩla ũmwe wĩanĩ wake;'),
('kam', 'NEH', 13, 31, 'na ũndũ wa nthembo ya ngũ, mavinda matw’ĩtwe, na ũndũ wa mosyao ma mbee. Ame Ngai wakwa, ndilikana ũmbĩke ũseo.'),
('kam', 'EST', 1, 1, 'Na kweethĩwa mĩthenyanĩ ya Aasuelo (Aasuelo ũsu nĩ ũla wasumbĩkĩte kuma India o na kũvika Ethiovia, ĩũlũ wa ilungu nene sya nthĩ ĩana na mĩongo ĩlĩ na mũonza),'),
('kam', 'EST', 1, 2, 'mĩthenya ĩsu, yĩla mũsumbĩ Aasuelo wekalĩte kĩvĩlanĩ kyake kya ũsumbĩ, kĩla kyaĩ nyũmbanĩ nene ya ũsumbĩ ku Susani,'),
('kam', 'EST', 1, 3, 'mwaka wa katatũ wa kũsumbĩka kwake, avokea anene make onthe me mbee ũsumbĩnĩ na athũkũmi make mboka; ala me ũtonyi ma Velisia na Metia, anene me ndaĩa na anene me mbee ũsumbĩnĩ ma ilungu isu nene sya nthĩ, meethĩwa mbee wake;'),
('kam', 'EST', 1, 4, 'nĩvo wonanisye ũthwii wa ũsumbĩ wake mũnene na ndaĩa ya ũnene wake mwingĩ mĩthenya mingĩ, o mĩthenya ĩana na mĩongo nyanya.'),
('kam', 'EST', 1, 5, 'Na matukũ asu meanĩa, mũsumbĩ avokea andũ onthe ala maĩ nyũmbanĩ nene ya ũsumbĩ ku Susani, mboka, anene o na anini, mĩthenya mũonza, vau nza ya nyũmba nene mbanakavye ya mũsumbĩ yĩ mũũnda.'),
('kam', 'EST', 1, 6, 'Vaniinĩtw’e ngũa nzaũ, na syĩ waiũ, na sya vuluu, syovetwe na ndii sya katane nzeo na iilyĩ ta ndune ngomenĩ sya vetha ituĩnĩ sya mavia maseo: mokomo maĩ ma thaavu na vetha, mekĩtwe vandũ vaseũvye na mavia maseo matune, na meũ, na me ĩuuku, na maiũ.'),
('kam', 'EST', 1, 7, 'Na mamanenga manyw’ĩe mĩionĩ ya thaavu (mĩio ĩla yaĩ kĩvathũkan’yo ũmwe na ũla ũngĩ), na mbinyu ya kĩũsumbĩ mbingĩ mũno, kwĩanana na ũlau wa mũsumbĩ.'),
('kam', 'EST', 1, 8, 'Na kũnyw’a kũu kwaĩ o kwĩanana na mwĩao; vatyaĩ ũtonya kũingĩĩw’a: nũndũ ũu mũsumbĩ nĩwatw’ĩte kwa anene onthe ma nyũmba yake, kana mo meke kwĩanana na kwenda kwa kĩla mũndũ.'),
('kam', 'EST', 1, 9, 'Nake Vasiti mũka wa mũsumbĩ avokea iveti ila syaĩ nyũmbanĩ ya kĩũsumbĩ ya mũsumbĩ Aasuelo mboka.'),
('kam', 'EST', 1, 10, 'Mũthenya wa mũonza, yĩla ngoo ya mũsumbĩ yatanĩtw’e nĩ mbinyu, ameaĩa Meumani, na Mbisitha, na Alivona, na Mbikitha, na Avakitha, na Nzethali, na Kalikasi, avakũe mũonza ala mathũkũmĩaa mbee wa mũsumbĩ Aasuelo,'),
('kam', 'EST', 1, 11, 'mamũete Vasiti mũka wa mũsumbĩ mbee wa mũsumbĩ e na ngovia ya kĩũsumbĩ, asyony’e ngo sya andũ na anene me mbee ũsumbĩnĩ ũseo wake; nũndũ aĩ mũseo kwa kũsiw’a.'),
('kam', 'EST', 1, 12, 'Ĩndĩ Vasiti mũka wa mũsumbĩ alea kũka kwondũ wa mwĩao wa mũsumbĩ ũla watwaĩwe nĩ ala avakũe: kwondũ wa ũu mũsumbĩ athilĩka mũno, na ũthatu wake wakana nthĩnĩ wake.'),
('kam', 'EST', 1, 13, 'Nĩvo ĩndĩ mũsumbĩ wakũlilye andũ oĩ, ala meesĩ mavinda (nũndũ ũu waĩ mwĩkalĩle wa mũsumbĩ kwa onthe ala meesĩ mwĩao na ũsili:'),
('kam', 'EST', 1, 14, 'na ala mamũatĩĩe ũnenenĩ maĩ Kalisena, na Sethali, na Atimatha, na Talisisi, na Melesi, na Malisena, na Memukani, anene mũonza me mbee ũsumbĩnĩ ma Velisia na Metia, ala moonaa ũthyũ wa mũsumbĩ, na mekalaa me ma mbee ũsumbĩnĩ ũsu),'),
('kam', 'EST', 1, 15, 'Twĩmwĩka ata Vasiti mũka wa mũsumbĩ kwĩanana na mwĩao, nĩkwĩthĩwa ndaneka ũtw’ĩo wa mũsumbĩ Aasuelo ũla watwaĩwe nĩ ala avakũe?'),
('kam', 'EST', 1, 16, 'Na Memukani asũngĩa vala ve mũsumbĩ na anene mbee ũsumbĩnĩ, Vasiti mũka wa mũsumbĩ ndaneka mũsumbĩ naĩ e weka, ĩndĩ o na anene onthe me mbee ũsumbĩnĩ, na ngo syonthe sya andũ ila syĩ ilungunĩ nene syonthe sya nthĩ sya mũsumbĩ Aasuelo.'),
('kam', 'EST', 1, 17, 'Nũndũ wĩko ũũ wa mũka wa mũsumbĩ ũkanyaĩĩkw’a kwa aka onthe, mavũthye aũme moo methonĩ moo, yĩla kwĩtavanw’a, Mũsumbĩ Aasuelo aneeaĩe Vasiti mũka wa mũsumbĩ aetwe mbee wake, ĩndĩ ndaneeũka.'),
('kam', 'EST', 1, 18, 'Na mũnthĩ ũũ aka ma anene me mbee ũsumbĩnĩ ma Velisia na Metia, meew’a wĩko wa mũka wa mũsumbĩ, makaneena o ta ũu kwa anene onthe me mbee ũsumbĩnĩ ma mũsumbĩ. Na ĩndĩ kũkookĩla kĩvũthya kĩnene na ũthilĩku.'),
('kam', 'EST', 1, 19, 'Ethĩwa nĩwendeesya mũsumbĩ, nĩkume mwĩao wa kĩũsumbĩ kuma kwake, na ũkĩandĩkwa katĩ wa mĩao ya Avelisia na Ametia, ĩla ĩtaalyũkaa, kana Vasiti ndakaaũke ĩngĩ vala ve mũsumbĩ Aasuelo; na mũsumbĩ nanenge ũngĩ wĩ kavaa kwĩ we kĩanda kya kĩũsumbĩ vandũ vake.'),
('kam', 'EST', 1, 20, 'Na yĩla ũtw’ĩo wa mũsumbĩ ũla wĩumya wĩnyaĩĩkw’a ũsumbĩnĩ wake w’onthe (nũndũ nĩ mũnene), iveti syonthe ikanengae aũme masyo ndaĩa, anene o na anini.'),
('kam', 'EST', 1, 21, 'Na ndeto ĩsu yendeesya mũsumbĩ na anene me mbee ũsumbĩnĩ; na mũsumbĩ eeka o kwĩanana na ndeto ya Memukani:'),
('kam', 'EST', 1, 22, 'nũndũ nĩwatwaie mavalũa ilungunĩ nene syonthe sya nthĩ sya mũsumbĩ, kĩla kĩlungu kĩnene kya nthĩ o kwĩanana na maandĩko makyo, na kĩla ũko wa andũ kũatĩĩa kĩthyomo kyaw’o, nĩ kana kĩla mũndũ amĩsumbĩke nyũmba yake mwene, na atavan’ye o kwĩanana na kĩthyomo kya andũ make.'),
('kam', 'EST', 2, 1, 'Ĩtina wa maũndũ asu, yĩla ũthilĩku wa mũsumbĩ Aasuelo wauisye, amũlilikana Vasiti, na ũndũ wekie, na ũndũ watw’ĩĩwe.'),
('kam', 'EST', 2, 2, 'Nĩvo ĩndĩ athũkũmi ma mũsumbĩ ala mamũthũkũmaa mamwĩie, Nĩkũmanthwe eĩtu ma mũika atheu na aseo kwondũ wa mũsumbĩ:'),
('kam', 'EST', 2, 3, 'na mũsumbĩ naie anene ilungunĩ nene syonthe sya nthĩ sya ũsumbĩ wake, nĩ kana mombanĩsye eĩtu onthe ma mũika atheu na aseo nyũmbanĩ nene ya ũsumbĩ ku Susani, nyũmbanĩ ya aka, ũsũvĩonĩ kwa Ekai, mũvakũe wa kwa mũsumbĩ, ũla ũsũvĩaa aka; na manengwe syĩndũ syoo kwondũ wa kwĩthesya;'),
('kam', 'EST', 2, 4, 'na mwĩĩtu ũla wĩendeesya mũsumbĩ natw’ĩke mũka wa mũsumbĩ vandũ va Vasiti. Na ũndũ ũsu wendeesya mũsumbĩ; na eeka ũu.'),
('kam', 'EST', 2, 5, 'Na kwaĩ Mũyuti ũmwe nyũmbanĩ ya ũsumbĩ ku Susani, ũla wetawa Molitekai, mwana wa Yaili, mwana wa Simei, mwana wa Kisu, Mũmbenyamini,'),
('kam', 'EST', 2, 6, 'ũla watwaĩtwe kuma Yelusaleme na ala matavĩtwe vamwe na Yekonĩa mũsumbĩ wa Yuta, ũla Nevukatilesa mũsumbĩ wa Mbaviloni wamũtwaie.'),
('kam', 'EST', 2, 7, 'Nake amũea Atasisa, nake nĩ Esita, mwĩĩtu wa mwendw’aĩthe: nũndũ ndaĩ na ĩthe o na nyinyia, na mwĩĩtu ũsu aĩ mwanake na mũseo; na yĩla ĩthe na nyinyia makwie, Molitekai amwosa ethĩwe mwĩĩtu wake mwene.'),
('kam', 'EST', 2, 8, 'Na kweethĩwa, yĩla mwĩao wa mũsumbĩ na ũtw’ĩo wake weew’ĩkie, na eĩtu aingĩ moombanĩw’a nyũmbanĩ nene ya ũsumbĩ ku Susani, ũsũvĩonĩ kwa Ekai, Esita atwawa nyũmbanĩ ya mũsumbĩ, ku ũsũvĩonĩ kwa Ekai, mũsũvĩi wa aka.'),
('kam', 'EST', 2, 9, 'Na ũla mwĩĩtu amwendeesya, na oona ũseo kwake; na amũnenga na mĩtũkĩ syĩndũ syake kwondũ wa kwĩthesya, vamwe na malĩu make, na anengwa eĩtu mũonza ala maĩle ũnengwa kuma nyũmbanĩ ya mũsumbĩ: na amũthamĩĩsya e na eĩtu make vandũ vala vaseo mbee nyũmbanĩ ya aka.'),
('kam', 'EST', 2, 10, 'Esita ndaamanyĩthan’ya andũ make kana ũko wake; nũndũ Molitekai nĩwamwĩaĩĩte kana ndakaamanyĩthan’ye.'),
('kam', 'EST', 2, 11, 'Na Molitekai nĩwangangaa kĩla mũthenya mbee wa nza ya nyũmba ya aka, amanye ũndũ Esita ũilyĩ, na ũndũ wĩmũtw’ĩkĩkĩa.'),
('kam', 'EST', 2, 12, 'Na ĩndĩ yĩla kyathĩ kyavikie kya kĩla mwĩĩtu kũenda kwa mũsumbĩ Aasuelo, ĩtina wa kwĩkĩwa kwake kwĩanana na mwĩao wa aka myei ĩkũmi na ĩlĩ (nũndũ ũu waĩ wĩanĩsyo wa kwĩthesya kwoo, atĩĩ, myei thanthatũ ya mauta ma manemane, na myei thanthatũ ya syĩndũ syĩ mũuke mũseo vamwe na syĩndũ sya kwĩthesya sya aka),'),
('kam', 'EST', 2, 13, 'nĩvo ĩndĩ kĩla mwĩĩtu waendie kwa mũsumbĩ kũatĩĩa maũndũ aa: kĩla wendaa nĩwanengiwe kũthi nakyo kuma nyũmbanĩ ya aka kũvika nyũmbanĩ ya mũsumbĩ.'),
('kam', 'EST', 2, 14, 'Athi wĩoo, na kĩoko auma athi nyũmbanĩ ya kelĩ ya aka, ũsũvĩonĩ kwa Saasikasi, mũvakũe wa kwa mũsumbĩ, ũla wasũvĩaa aka ngombo: ndaalika kwa mũsumbĩ ĩngĩ, ate o mũsumbĩ nĩwendeew’e nĩwe, na eetwa na syĩtwa.'),
('kam', 'EST', 2, 15, 'Na ĩndĩ yĩla kyathĩ kya Esita kyavikie kya kũthi kwa mũsumbĩ, mwĩĩtu wa Aviaili mwendw’a‐ĩthe wa Molitekai, ũla wamwosete ethĩwe mwĩĩtu wake, ndaaenda kĩndũ o na kĩva no kĩla Ekai mũvakũe wa kwa mũsumbĩ, mũsũvĩi wa aka, watw’ĩte. Na Esita oona ũseo methonĩ ma onthe ala mamũsyaĩĩsye.'),
('kam', 'EST', 2, 16, 'Na ĩndĩ Esita atwawa kwa mũsumbĩ Aasuelo nyũmbanĩ yake ya kĩũsumbĩ mwei wa ĩkũmi, naw’o nĩ mwei wa Tevethi, mwaka wa mũonza wa kũsumbĩka kwake.'),
('kam', 'EST', 2, 17, 'Na mũsumbĩ endie Esita kwĩ aka ala angĩ onthe, na oona waĩlu na ũseo methonĩ make kwĩ eĩtu atheu ala angĩ onthe; kwondũ wa ũu amwĩkĩa ngovia ya kĩũsumbĩ mũtwenĩ wake, na amũtw’a mũka wa mũsumbĩ vandũ va Vasiti.'),
('kam', 'EST', 2, 18, 'Nĩvo ĩndĩ mũsumbĩ wamavokee anene make onthe me mbee ũsumbĩnĩ na athũkũmi make mboka nene, nayo nĩ mboka ya Esita; na athũmũsya ilungu nene sya nthĩ koti, na anengane mĩthĩnzĩo, kwĩanana na ũlau wa mũsumbĩ.'),
('kam', 'EST', 2, 19, 'Na yĩla eĩtu asu atheu moombaniw’e ĩvinda ya kelĩ, nĩvo Molitekai wekalile nthĩ mbingĩlonĩ kwa mũsumbĩ.'),
('kam', 'EST', 2, 20, 'Esita ndaĩ anamba kũmanyĩthan’ya ũko wake kana andũ make; o tondũ Molitekai wamwĩaĩĩte: nũndũ Esita eekĩte o tondũ Molitekai wamwĩaĩaa, o ta yĩla waeiwe nĩwe.'),
('kam', 'EST', 2, 21, 'Mĩthenya ĩsu, yĩla Molitekai wekalaa nthĩ mbingĩlonĩ kwa mũsumbĩ, avakũe elĩ ma kwa mũsumbĩ, Mbikithana na Telesi, ma asu ala masũvĩaa myalyonĩ, mathilĩka, na mamantha kũmũkwata mũsumbĩ Aasuelo.'),
('kam', 'EST', 2, 22, 'Na ũndũ ũsu wamanyĩka nĩ Molitekai, ũla nake wamwonisye Esita mũka wa mũsumbĩ; na Esita atavya mũsumbĩ ũndũ ũsu syĩtwanĩ ya Molitekai.'),
('kam', 'EST', 2, 23, 'Na yĩla ũndũ ũsu wakũlanganilw’e, na wooneka nĩ wa w’o, asu me elĩ masũw’a mũtĩnĩ: na waandĩkwa ĩvukunĩ ya maũndũ ma mavinda vu mbee wa mũsumbĩ.'),
('kam', 'EST', 3, 1, 'Ĩtina wa maũndũ asu mũsumbĩ Aasuelo amũnenevya Amani mwana wa Ametatha Mũakaki, na amũkĩlya, na aia kĩvĩla kyake ĩũlũ wa anene onthe me mbee ũsumbĩnĩ ala maĩ nake.'),
('kam', 'EST', 3, 2, 'Na athũkũmi onthe ma mũsumbĩ, ala maĩ mbingĩlonĩ kwa mũsumbĩ, makunama, na kũmwĩkunamĩsya Amani vyũ; nũndũ mũsumbĩ nĩweaĩte ũu ũndũ wake. Ĩndĩ Molitekai ndaakunama, o na kũmwĩkunamĩsya.'),
('kam', 'EST', 3, 3, 'Nĩvo ĩndĩ athũkũmi ma mũsumbĩ, ala maĩ mbingĩlonĩ kwa mũsumbĩ, makũlilye Molitekai, Nĩkĩ ũũtũla mwĩao wa mũsumbĩ?'),
('kam', 'EST', 3, 4, 'Na ĩndĩ kweethĩwa, makĩneena nake mũthenya na mũthenya, nake ndaamethukĩĩsya, mamũtavya Amani, masisye ethĩwa maũndũ ma Molitekai makaũngama: nũndũ amatavĩtye kana nĩ Mũyuti.'),
('kam', 'EST', 3, 5, 'Na yĩla Amani wonie kana Molitekai ndaakunama, o na kũmwĩkunamĩsya, nĩvo ĩndĩ Amani wausũiwe nĩ ũthilĩku.'),
('kam', 'EST', 3, 6, 'Ĩndĩ asũanĩa ndwĩanĩa kũmũkwata Molitekai e weka; nũndũ nĩmamũmanyĩthĩtye ũko wa andũ wa Molitekai: kwondũ wa ũu Amani amantha kũmananga Ayuti onthe ala maĩ ũsumbĩnĩ w’onthe wa Aasuelo, o ũko wa andũ wa Molitekai.'),
('kam', 'EST', 3, 7, 'Mwei wa mbee, naw’o nĩ mwei wa Nisani, mwaka wa ĩkũmi na ĩlĩ wa kũsumbĩka kwa mũsumbĩ Aasuelo, mekya Vuli, naw’o nĩ kũlimana, vu mbee wa Amani mũthenya na mũthenya, na mwei na mwei, kũvika mwei wa ĩkũmi na ĩlĩ, naw’o nĩ mwei wa Atali.'),
('kam', 'EST', 3, 8, 'Na Amani amwĩa mũsumbĩ Aasuelo, Ve ũko ũmwe wa andũ ũnyaĩĩkĩe kũũ na kũũ katĩ wa ngo sya andũ ilungunĩ nene sya nthĩ sya ũsumbĩ waku; na mĩao yoo ĩ kĩvathũkan’yo na ya kĩla ũko wa andũ; o na maikwataa mĩao ya mũsumbĩ: kwondũ wa ũu kũti ũuno kwa mũsumbĩ kũmaeka mekale.'),
('kam', 'EST', 3, 9, 'Ethĩwa nĩkwendeesya mũsumbĩ, nĩkũandĩkwe nĩ kana manangwe: nakwa ngaĩva talendi ngili ĩkũmi sya vetha mokonĩ ma asu masyaĩĩsya mawĩa ma mũsumbĩ, ietwe kũla kwiawa ũthwii kwa mũsumbĩ.'),
('kam', 'EST', 3, 10, 'Na mũsumbĩ aumya ngome yake kyaanĩ kyake, na amũnenga Amani mwana wa Ametatha Mũakaki, ũla mũmaitha wa Ayuti.'),
('kam', 'EST', 3, 11, 'Na mũsumbĩ amwĩa Amani, Ũla vetha nĩwanengwa, o na ũko wa andũ naw’o, wĩke naw’o ũndũ ũkwona wĩ ũseo.'),
('kam', 'EST', 3, 12, 'Nĩvo ĩndĩ aandĩki ma mũsumbĩ meetiwe mwei wa mbee, mũthenya wa ĩkũmi na ĩtatũ waw’o; na kwaandĩkiwe kwĩanana na w’onthe, ũla Amani weaĩe asumbĩ anini ma kwa mũsumbĩ, na makavana ala maĩ ĩũlũ wa kĩla kĩlungu kĩnene kya nthĩ, na anene me mbee ũsumbĩnĩ ma kĩla ũko wa andũ, kwa kĩla kĩlungu kĩnene kya nthĩ kwĩanana na maandĩko makyo, na kĩla ũko wa andũ kũatĩĩa kĩthyomo kyaw’o; kwaandĩkwa syĩtwanĩ ya mũsumbĩ Aasuelo, na kũsiĩlwa na ngome ya mũsumbĩ.'),
('kam', 'EST', 3, 13, 'Na mavalũa matwawa nĩ atwai ma mavalũa ilungunĩ nene syonthe sya nthĩ sya mũsumbĩ, mamanange, na kũmoaa, na kũmamina, Ayuti onthe, o ma mũika na ala akũũ, syana nini na aka, mũthenya ũmwe, o mũthenya wa ĩkũmi na ĩtatũ wa mwei wa ĩkũmi na ĩlĩ, naw’o nĩ mwei wa Atali, na makyosa syĩndũ syoo syĩthĩwe mũtavo.'),
('kam', 'EST', 3, 14, 'Na wumĩĩsyo wa ũla ũandĩko, nĩ kana ũtw’ĩo ũnyaĩĩkwe kĩla kĩlungu kĩnene kya nthĩ, watavaniw’e kwa ngo syonthe sya andũ, nĩ kana meĩthĩwa meyũmbanĩtye mũthenya ũsu.'),
('kam', 'EST', 3, 15, 'Atwai ma mavalũa mathi mekalaatĩte nũndũ wa mwĩao wa mũsumbĩ, na ũtw’ĩo watavaniw’e nyũmbanĩ nene ya ũsumbĩ ku Susani. Na mũsumbĩ na Amani mekala nthĩ manyw’e; ĩndĩ ndũa ya Susani yasũanĩwa.'),
('kam', 'EST', 4, 1, 'Na ĩndĩ yĩla Molitekai wamanyie w’onthe ũla wĩkĩtwe, Molitekai atembũanga ngũa syake, na eekĩa makunia na kwĩyũmba mũu, na aenda na ku ndũani katĩ, na akaya na wasya mũtũlu na kĩĩo kĩ woo;'),
('kam', 'EST', 4, 2, 'na ooka o vu mbee wa mbingĩlo ya kwa mũsumbĩ: nũndũ vatyaĩ ũtonya kũlika mbingĩlonĩ kwa mũsumbĩ ekĩe makunia.'),
('kam', 'EST', 4, 3, 'Na kĩla kĩlungu kĩnene kya nthĩ, o vala mwĩao wa mũsumbĩ na ũtw’ĩo wake wavikie, kwaĩ woo mũnene katĩ wa Ayuti, na kũtĩĩa kũya, na kũĩa, na kũmeta; na aingĩ makoma makunianĩ na mũunĩ.'),
('kam', 'EST', 4, 4, 'Na eĩtu athũkũmi ma Esita na avakũe ma kwake mooka na mamũtavya; na mũka wa mũsumbĩ eew’a woo mũnene mũno: na anengane ngũa ĩkekĩwe Molitekai, na kũmumya makunia make; ĩndĩ ndaamyosa.'),
('kam', 'EST', 4, 5, 'Nĩvo ĩndĩ Esita wetie Athaki, ũmwe wa avakũe ma kwa mũsumbĩ, ũla wamwiĩte amũthũkũmae, na amwĩaĩa aende vala ve Molitekai, akamanye ũu nata, na kĩtumi nĩ kyaũ.'),
('kam', 'EST', 4, 6, 'Na ĩndĩ Athaki aenda vala ve Molitekai vala vandũ vathanthau va ndũa, vu vala ve mbingĩlo ya kwa mũsumbĩ.'),
('kam', 'EST', 4, 7, 'Na Molitekai amũtavya w’onthe ũla ũmũkĩtĩkĩe, na ũtalo wa w’o wa mbesa ila Amani wathanĩte kũnengane kũla kwiawa ũthwii wa mũsumbĩ nũndũ wa Ayuti, amamine.'),
('kam', 'EST', 4, 8, 'Na ĩndĩ amũnenga wumĩĩsyo wa ũandĩko wa ũla ũtw’ĩo ũla watavaniw’e vu Susani wa kũmamina, awon’ye Esita, na kũmũvuanĩsya, na kũmũtavya aende kwa mũsumbĩ, na kũmũvoya, na kũmwĩsũva, nũndũ wa andũ make.'),
('kam', 'EST', 4, 9, 'Na Athaki ooka na atavya Esita ndeto sya Molitekai.'),
('kam', 'EST', 4, 10, 'Nĩvo ĩndĩ Esita waneenie na Athaki, na amũnenga ũtũmane wa Molitekai, akĩmwĩa:'),
('kam', 'EST', 4, 11, 'Athũkũmi onthe ma mũsumbĩ, na andũ ma ilungu nene sya nthĩ sya mũsumbĩ, nĩmeũmanya, mũndũ o na wĩva, ethĩwa nĩ mũndũ mũũme kana mũndũ mũka, wĩũka alike kwa mũsumbĩ kũvika nza ya nthĩnĩ, ate mwĩte, ve mwĩao ũmwe kwake, kana akooawa, ate o ala mũsumbĩ wĩmatambũũkĩsya ĩla ndata ya thaavu ya ũsumbĩ, nĩ kana atonye kwĩkala thayũ: ĩndĩ nyie ndineeĩtwa nĩlike kwa mũsumbĩ mĩthenya ĩno mĩongo ĩtatũ.'),
('kam', 'EST', 4, 12, 'Na matavya Molitekai ndeto sya Esita.'),
('kam', 'EST', 4, 13, 'Nĩvo ĩndĩ Molitekai wameaĩe mamũtũngĩe Esita ũsũngĩo, Ndũkeesũanĩĩe mwene kana ũkavĩtĩa nyũmbanĩ ya mũsumbĩ, kwĩ Ayuti onthe.'),
('kam', 'EST', 4, 14, 'Nũndũ ethĩwa ũkavindya ki ĩvinda yĩĩ, nĩvo ĩndĩ ũthasyo na ũvonokyo ũkookĩla kwa Ayuti kuma vandũ vangĩ, ĩndĩ we na nyũmba ya au mũkaaa: na nũũ wĩsĩ kana ndwaalika ũsumbĩnĩ nũndũ wa ĩvinda ta yĩĩ?'),
('kam', 'EST', 4, 15, 'Nĩvo ĩndĩ Esita wameaĩe mamũtũngĩe Molitekai ũsũngĩo,'),
('kam', 'EST', 4, 16, 'Enda, ũmban’ye Ayuti onthe ala me Susani, na mũitĩĩa kũya nũndũ wakwa, o na mũikaye o na mũikanyw’e mĩthenya ĩtatũ, ũtukũ kana mũthenya: nyie nakwa na eĩtu athũkũmi makwa tũkatĩĩa kũya o ta ũu; na ĩndĩ ngaenda vala ve mũsumbĩ, o na kau ti kwĩanana na mwĩao: na ethĩwa nĩngwaa, nongwaa.'),
('kam', 'EST', 4, 17, 'Na ĩndĩ Molitekai eeyĩendea, na eeka kwĩanana na w’onthe ũla Esita wamwĩaĩe.'),
('kam', 'EST', 5, 1, 'Na ĩndĩ kweethĩwa mũthenya wa katatũ, Esita eekĩa ngũa syake sya kĩũsumbĩ, na aũngama nza ya nthĩnĩ ya nyũmba ya mũsumbĩ, kwelekela nyũmba ya mũsumbĩ: na mũsumbĩ ekala kĩvĩlanĩ kyake kya kĩũsumbĩ nyũmbanĩ ya kĩũsumbĩ, kwelekela ũlikĩlo wa nyũmba.'),
('kam', 'EST', 5, 2, 'Na kweethĩwa, yĩla mũsumbĩ wonie Esita mũka aũngeme nza, anengwa kwona ũseo methonĩ make; na mũsumbĩ amũtambũũkĩsya Esita ndata ya thaavu ya ũsumbĩ ĩla yaĩ kw’okonĩ kwake. Na ĩndĩ Esita athengeea vakuvĩ, na akiita mũthya wa ndata ya ũsumbĩ.'),
('kam', 'EST', 5, 3, 'Nĩvo ĩndĩ mũsumbĩ wamũkũlilye, Wĩenda kyaũ, Esita, mũka wa mũsumbĩ? Na vata waku nĩ mwaũ? Nũkũnengwa o na ethĩwa nĩ nyunzu ya ũsumbĩ.'),
('kam', 'EST', 5, 4, 'Na Esita amwĩa, Ethĩwa nĩkwoneka wĩ ũseo kwa mũsumbĩ, mũsumbĩ na Amani nĩmoke mũnthĩ ũũ mbokanĩ ĩla nzeũvĩtye nũndũ wake.'),
('kam', 'EST', 5, 5, 'Nĩvo ĩndĩ mũsumbĩ waisye, Kalaatai Amani nĩ kana kũtonye kwikwa o tondũ Esita wasya. Na ĩndĩ mũsumbĩ na Amani mooka mbokanĩ ĩla Esita waseũvĩtye.'),
('kam', 'EST', 5, 6, 'Na mũsumbĩ amũkũlĩlya Esita vu mbokanĩ ya mbinyu, Vata waku nĩ mwaũ? Na nũũnengwa: na wĩenda kĩ? O na ethĩwa nĩ nyunzu ya ũsumbĩ ũkeekwa.'),
('kam', 'EST', 5, 7, 'Nĩvo ĩndĩ Esita wasũngĩie, na amwĩa, Vata wakwa na kwenda kwakwa nĩ atĩĩ:'),
('kam', 'EST', 5, 8, 'Ethĩwa nĩnonete ũseo methonĩ ma mũsumbĩ, na ethĩwa nĩwendeesya mũsumbĩ kũnenga vata wakwa, na kwĩka kwenda kwakwa, mũsumbĩ na Amani nĩmoke mbokanĩ ĩla nĩmaseũvĩsya, na ngeeka ũnĩ o tondũ mũsumbĩ waĩtye.'),
('kam', 'EST', 5, 9, 'Nĩvo ĩndĩ Amani aumaala mũthenya ũsu e mũtanu na e na mũyo ngoonĩ: ĩndĩ yĩla Amani wonie Molitekai mbingĩlonĩ kwa mũsumbĩ, kana ndaaũngama o na kũmwathũkĩa, ausũwa nĩ ũthilĩku ĩũlũ wa Molitekai.'),
('kam', 'EST', 5, 10, 'Ĩndĩ Amani eesiĩĩa mwene, na enũka; na atũmana anyanyae na Nzelesi mũka wake moke.'),
('kam', 'EST', 5, 11, 'Na Amani amatalĩla ũnene wa mothwii make, na wingĩ wa syana syake, na maũndũ onthe ala mũsumbĩ wamũneneveesye, na ũndũ ũmwiĩte ĩũlũ wa anene me mbee ũsumbĩnĩ na athũkũmi ma mũsumbĩ.'),
('kam', 'EST', 5, 12, 'Na ĩngĩ Amani amea, Ĩĩ, Esita mũka wa mũsumbĩ ndanaeka mũndũ ũngĩ alike vamwe na mũsumbĩ mbokanĩ ĩla eĩseũvĩtye ĩndĩ no nyie: na ũnĩ ĩngĩ nĩnĩtĩtwe nowe vamwe na mũsumbĩ.'),
('kam', 'EST', 5, 13, 'Ĩndĩ ũu w’onthe kwakwa no ta mana, yĩla ngũmwona Molitekai ũla Mũyuti ekalĩte mbingĩlonĩ kwa mũsumbĩ.'),
('kam', 'EST', 5, 14, 'Nĩvo ĩndĩ Nzelesi mũka wake na anyanyae make onthe mamwĩie, Nĩkũseũvw’e mũtĩ ũtũlĩte mĩkono mĩongo ĩtano, na ũnĩ ũineena na mũsumbĩ nĩ kana Molitekai atonye kũsũw’a vo: na ĩndĩ ũithi ũtanĩte wĩ na mũsumbĩ mbokanĩ. Na ũndũ ũsu wendeesya Amani; na atuma mũtĩ ũseũvw’a.'),
('kam', 'EST', 6, 1, 'Ũtukũ ũsu mũsumbĩ ndaatonya kũkoma; nake eeaa mavuku ma molilikan’yo ma mavinda maetwe, na makĩsomewa vu mbee wa mũsumbĩ.'),
('kam', 'EST', 6, 2, 'Na vooneka vaandĩkĩtwe, kana Molitekai nĩwatavanisye ũvoo wa Mbikithana na Telesi, avakũe elĩ ma kwa mũsumbĩ, asu masũvĩaa myalyonĩ, ala mamanthaa kũmũkwata mũsumbĩ Aasuelo.'),
('kam', 'EST', 6, 3, 'Na mũsumbĩ akũlya, Nĩ ndaĩa na ũnene mwaũ ila inengetwe Molitekai nũndũ wa ũndũ ũũ? Nĩvo ĩndĩ athũkũmi ma mũsumbĩ ala mamũthũkũmaa mamwĩie, Nde ũndũ waaĩkwa.'),
('kam', 'EST', 6, 4, 'Na mũsumbĩ akũlya, Nũũ ũla wĩ nza? Na ĩndĩ Amani aĩ anooka nza yĩ ũtee wa nyũmba ya mũsumbĩ, aneene na mũsumbĩ ũndũ wa kũsũsya Molitekai ũla mũtĩnĩ ũmũseũvĩsye.'),
('kam', 'EST', 6, 5, 'Na athũkũmi ma mũsumbĩ mamwĩa, Sisya, Amani aũngeme nza. Na mũsumbĩ asya, Nalike nthĩnĩ.'),
('kam', 'EST', 6, 6, 'Na ĩndĩ Amani alika nthĩnĩ. Na mũsumbĩ amũkũlya, Kwĩĩkĩka ata kwa mũndũ ũla mũsumbĩ wendeew’e nĩ kũmũtaĩa? Na ĩndĩ Amani asya ngoonĩ yake, Nĩ kwaũ ũla mũsumbĩ wendeew’e nĩ kũmũtaĩa mũno kwĩ nyie mwene?'),
('kam', 'EST', 6, 7, 'Na Amani amwĩa mũsumbĩ, Nũndũ wa mũndũ ũla mũsumbĩ wendeew’e nĩ kũtaĩa,'),
('kam', 'EST', 6, 8, 'ngũa ya kĩũsumbĩ ĩetwe ĩla mũsumbĩ wakothaa kwĩkĩa, na mbalasi ĩla mũsumbĩ ũtũlaa ĩũlũ, ĩla mũtwenĩ wayo yĩkĩawa ngovia ya kĩũsumbĩ:'),
('kam', 'EST', 6, 9, 'na ngũa na mbalasi ninenganwe kw’okonĩ kwa ũmwe wa ala anene ma mũsumbĩ me mbee ũsumbĩnĩ, ũla wĩ ndaĩa mbee, nĩ kana mamĩkĩe mũndũ ũla mũsumbĩ ũnũkwendeew’a nĩ kũtaĩa, na kũmũtũlya mbalasinĩ akinyĩlw’e nzĩanĩ nene ya ĩ ndũa, na kũtavan’ya e mbee wake, Ũũ nĩw’o wĩĩkwa mũndũ ũla mũsumbĩ wĩendeew’a nĩ kũtaĩa.'),
('kam', 'EST', 6, 10, 'Nĩvo indĩ mũsumbĩ wamwĩie Amani, Ĩkalaate, na ũyosa ngũa na mbalasi, o tondũ wasya na ũyĩka o ta ũu na Molitekai Mũyuti, ũla wĩkalaa mbingĩlonĩ kwa mũsumbĩ: kũtikatiale ũndũ wa onthe ala ũneenete.'),
('kam', 'EST', 6, 11, 'Nĩvo ĩndĩ Amani wosie ĩ ngũa na mbalasi, na eekĩa Molitekai, na amũtũlya akinyĩlw’e nzĩanĩ nene ya ĩ ndũa, na atavan’ya e mbee wake, Ũũ nĩw’o wĩĩkwa mũndũ ũla mũsumbĩ wĩendeew’a nĩ kũtaĩa.'),
('kam', 'EST', 6, 12, 'Na Molitekai ooka ĩngĩ mbingĩlonĩ kwa mũsumbĩ. Ĩndĩ Amani eekalaata athi nyũmbanĩ kwake, akĩw’a woo mũnene na avw’ĩkĩte mũtwe wake.'),
('kam', 'EST', 6, 13, 'Na Amani atalĩla Nzelesi mũka wake na anyanyae make onthe kĩla ũndũ ũla wamũkĩtĩkĩa. Nĩvo ĩndĩ andũ oĩ make na Nzelesi mũka wake mamwĩie, Ethĩwa Molitekai, ũla wambĩlĩlya kũvalũka mbee wake, nĩ wa mbaĩ ya Ayuti, we ndũkamũtonya, ĩndĩ vate ndĩi ũkavalũkaa mbee wake.'),
('kam', 'EST', 6, 14, 'Na makĩneenanga nake, kwooka avakũe ma kwa mũsumbĩ, na mekalaata kũmũtwaa Amani mbokanĩ ĩla waseũvĩtye.'),
('kam', 'EST', 7, 1, 'Na ĩndĩ mũsumbĩ na Amani malika mbokanĩ ya Esita mũka wa mũsumbĩ.'),
('kam', 'EST', 7, 2, 'Na mũsumbĩ eea Esita ĩngĩ mũthenya wa kelĩ me mbokanĩ ya mbinyu, Vata waku nĩ mwaũ, Esita, mũka wa mũsumbĩ? Na nũũnengwa: na wĩenda kĩ? O na ethĩwa nĩ nyunzu ya ũsumbĩ ũkeekwa.'),
('kam', 'EST', 7, 3, 'Nĩvo ĩndĩ Esita mũka wa mũsumbĩ wasũngĩie na amwĩa, Ethĩwa nĩnonete ũseo methonĩ maku, we mũsumbĩ, na ethĩwa nĩwendeesya mũsumbĩ, thayũ wakwa nĩnengwe kwondũ wa vata wakwa, na andũ makwa kwondũ wa kwenda kwakwa:'),
('kam', 'EST', 7, 4, 'nũndũ twĩ athoosye, nyie na andũ makwa, twanangwe, tũawe, na kwaa. Ĩndĩ kethĩwa tũthooetw’e aũme na aka twĩthĩwe ngombo, nĩĩthĩwa nĩvindĩtye, o na kau mũmaitha ũsu ndethĩwa atonya kũĩvĩa wasyo wa mũsumbĩ.'),
('kam', 'EST', 7, 5, 'Nĩvo ĩndĩ mũsumbĩ Aasuelo waneenie na amũkũlya Esita mũka wa mũsumbĩ, Nĩwe ũũ, na aĩva, ũsu ũtatĩte ũtw’a ngoonĩ yake kwĩka ũu?'),
('kam', 'EST', 7, 6, 'Na Esita amwĩa, Nthũ na mũmaitha, nake nĩ Amani ũũ mũthũku. Nĩvo ĩndĩ Amani wakwatĩwe nĩ w’ĩa vu mbee wa mũsumbĩ na mũka wa mũsumbĩ.'),
('kam', 'EST', 7, 7, 'Na mũsumbĩ ookĩla e mũthilĩku kuma mbokanĩ ya mbinyu na aenda mũũndanĩ wa nyũmba nene ya ũsumbĩ: na Amani aũngama esũvane nũndũ wa thayũ wake vala ve Esita mũka wa mũsumbĩ; nũndũ nĩwonie kana ve ũthũku ũtw’ĩtwe nĩ mũsumbĩ.'),
('kam', 'EST', 7, 8, 'Nĩvo ĩndĩ mũsumbĩ wasyokie kuma mũũndanĩ wa nyũmba nene ya ũsumbĩ alike vala vandũ va ĩla mboka ya mbinyu; na Amani avalũkĩte ũkomonĩ ũla Esita wailyĩ. Nĩvo ĩndĩ mũsumbĩ waisye, Kaĩ nũtonya kũmwĩka na vinya mũka wa mũsumbĩ nĩ vo nyũmbanĩ? Ndeto ĩsu ĩkyuma kanyw’anĩ wa mũsumbĩ, mamũvw’ĩka Amani ũthyũ.'),
('kam', 'EST', 7, 9, 'Nĩvo ĩndĩ Alivona, ũmwe wa avakũe ala maĩ vo mbee wa mũsumbĩ, waisye, Na ĩngĩ sisya, mũtĩ wa mĩkono mĩongo ĩtano ũtũlu waw’o, ũla Amani ũseũvĩtye nũndũ wa Molitekai, ũla waneenie nesa ũndũ wa mũsumbĩ, ũũngamĩtw’e nyũmbanĩ kwa Amani. Na mũsumbĩ asya, Mũsũsyei ĩũlũ waw’o.'),
('kam', 'EST', 7, 10, 'Na ĩndĩ mamũsũsya Amani mũtĩnĩ mũtũlu ũla waseũvĩsye Molitekai. Na ĩndĩ ũthilĩku wa mũsumbĩ wausya.'),
('kam', 'EST', 8, 1, 'Mũthenya ũsu mũsumbĩ Aasuelo amũnenga Esita mũka nyũmba ya Amani, mũmaitha wa Ayuti. Na Molitekai ooka vala ve mũsumbĩ; nũndũ Esita nĩwatavanĩtye ũndũ mailen’ye.'),
('kam', 'EST', 8, 2, 'Na mũsumbĩ aumya ngome yake, ĩla waumĩsye Amani, na amĩnenga Molitekai. Na Esita amwĩa Molitekai ĩũlũ wa nyũmba ya Amani.'),
('kam', 'EST', 8, 3, 'Na Esita aneena o ĩngĩ mbee wa mũsumbĩ, na avalũka nthĩ maũũnĩ make, na amwĩsũva na methoi avete ũthũku wa Amani Mũakaki, na ũsũanĩo wake ũla wasũanĩĩe Ayuti.'),
('kam', 'EST', 8, 4, 'Nĩvo ĩndĩ mũsumbĩ watambũũkĩsye Esita ndata ya thaavu yake ya ũsumbĩ. Kwondũ wa ũu Esita ookĩla, na aũngama mbee wa mũsumbĩ.'),
('kam', 'EST', 8, 5, 'Na amwĩa, Ethiwa nĩwendeesya mũsumbĩ, na ethĩwa nĩnonete ũseo methonĩ make, na ũndũ ũkwoneka wĩ ũlũngalu vala ve mũsumbĩ, na ngĩmwendeesya methonĩ make, nĩkũandĩkwe kũalyũlwe mavalũa ala masũanĩiwe nĩ Amani, mwana wa Ametatha Mũakaki, ala waandĩkie ma kũmina Ayuti ala me ilungunĩ nene syonthe sya nthĩ sya mũsumbĩ:'),
('kam', 'EST', 8, 6, 'nũndũ ndonya ata kũmĩĩsya kwona ũthũku ũla wĩũka kwa andũ makwa? Kana ndonya ata kũmĩĩsya kwona wanangĩko wa ũko wakwa?'),
('kam', 'EST', 8, 7, 'Nĩvo ĩndĩ mũsumbĩ Aasuelo weie Esita mũka na Molitekai Mũyuti, Sisyai, nĩnĩnengete Esita nyũmba ya Amani, nake mamũsũsya mũtĩnĩ, nĩkwĩthĩwa atambũũkĩsye Ayuti kw’oko kwake amakwate.'),
('kam', 'EST', 8, 8, 'Na ĩngĩ andĩkĩai Ayuti o tondũ mũkwenda, syĩtwanĩ ya mũsumbĩ, na mũkyũsiĩla na ngome ya mũsumbĩ; nũndũ ũandĩko ũla ũandĩkĩtwe syĩtwanĩ ya mũsumbĩ, na kũsiĩlwa na ngome ya mũsumbĩ, vati mũndũ ũtonya ũalyũla.'),
('kam', 'EST', 8, 9, 'Nĩvo ĩndĩ aandĩki ma mũsumbĩ meetiwe ĩvinda yĩu, mwei wa katatũ, naw’o nĩ mwei wa Sivani, mũthenya wa mĩongo ĩlĩ na ĩtatũ waw’o; na kwaandĩkĩtwe kwĩanana na w’onthe ũla Molitekai weaĩĩte Ayuti, na asumbĩ anini, na makavana na anene me mbee ũsumbĩnĩ ma ilungu nene sya nthĩ ila syĩkuma India kũvika Ethiovia, ilungu nene sya nthĩ ĩana na mĩongo ĩlĩ na mũonza, kwa kĩla kĩlungu kĩnene kya nthĩ kwĩanana na ũandĩko wakyo, na kwa kĩla ũko wa andũ kũatĩĩa kĩthyomo kyaw’o, na kwa Ayuti kwĩanana na ũandĩko woo, na kũatĩĩa kĩthyomo kyoo.'),
('kam', 'EST', 8, 10, 'Na aandĩka syĩtwanĩ ya mũsumbĩ Aasuelo, na oosĩĩla na ngome ya mũsumbĩ, na atwaa mavalũa na atwai ma mavalũa matũlĩte mbalasi, matũlĩte mbalasi syĩ maũũ ila syekalaa ũthũkũminĩ wa mũsumbĩ, isyaĩtwe mbalasinĩ sya ũsumbĩ:'),
('kam', 'EST', 8, 11, 'ala nthĩnĩ wamo mũsumbĩ amanenga Ayuti ala maĩ kĩla ndũa ũthei wa kũmbana, na kwĩyĩũngamĩa mathayũ moo, manange, na kũaa, na kũtuma waa, ũtonyi w’onthe wa andũ na wa kĩlungu kĩnene kya nthĩ ũla wĩenda kũmavithũkĩa, anini moo na iveti, na kũkwata syĩndũ syoo syĩthĩwe mũtavo,'),
('kam', 'EST', 8, 12, 'o mũthenya ũmwe ilungunĩ nene syonthe sya nthĩ sya mũsumbĩ Aasuelo, naw’o nĩ mũthenya wa ĩkũmi na ĩtatũ wa mwei wa ĩkũmi na ĩlĩ, naw’o nĩ mwei wa Atali.'),
('kam', 'EST', 8, 13, 'Wumĩĩsyo wa ũandĩko, nĩ kana ũtw’ĩo ũtavanw’e kĩla kĩlungu kĩnene kya nthĩ, wanyaĩĩkw’a kwa ngo syonthe sya andũ, na kana Ayuti methĩwe meyũmbanĩtye mũthenya ũsu kwĩĩvanĩsya ene amaithanĩ moo.'),
('kam', 'EST', 8, 14, 'Kwondũ wa ũu atwai ma mavalũa ala matũlĩte mbalasi syĩ maũũ ila syekalaa ũthũkũminĩ wa mũsumbĩ mathi, makalaatĩtwe na kũkũlũswa nĩ mwĩao wa mũsumbĩ; na ũtw’ĩo waumĩwe nyũmbanĩ nene ya ũsumbĩ ku Susani.'),
('kam', 'EST', 8, 15, 'Na Molitekai aumaala kuma vala mũsumbĩ waĩ ekĩe ngũa ya kĩũsumbĩ ya vuluu na nzaũ, na e na ngovia nene ya ũsumbĩ ya thaavu, na e na kĩtonyeo kĩseo kya katane kĩilyĩ ta kĩtune: na ndũa ya Susani yookĩlya wasya na yaĩ na mũyo.'),
('kam', 'EST', 8, 16, 'Ayuti maĩ na kyeni na mũyo, na ũtanu na ndaĩa.'),
('kam', 'EST', 8, 17, 'Na kĩla kĩlungu kĩnene kya nthĩ, na kĩla ndũa, o vala mwĩao wa mũsumbĩ na ũtw’ĩo wake wavikie, Ayuti maĩ na mũyo na ũtanu, na mboka na mũthenya mũseo. Na aingĩ kuma katĩ wa ngo sya andũ sya ĩ nthĩ matw’ĩka Ayuti; nũndũ kũkĩa Ayuti nĩkwamakwatie.'),
('kam', 'EST', 9, 1, 'Na ĩndĩ mwei wa ĩkũmi na ĩlĩ, naw’o nĩ mwei wa Atali, mũthenya wa ĩkũmi na ĩtatũ waw’o, yĩla mwĩao wa mũsumbĩ na ũtw’ĩo wake wathengeee kwĩanĩwa, mũthenya ũla amaitha ma Ayuti meekwatasya methĩwe na ũsumbĩko ĩũlũ wamo (ĩndĩ nĩwasyokie kwĩalyũla, atĩ Ayuti maĩ na ũsumbĩko ĩũlũ wa asu mamamenaa),'),
('kam', 'EST', 9, 2, 'Ayuti meeyũmbanĩsya ndũanĩ syoo ilungunĩ nene syonthe sya nthĩ sya mũsumbĩ Aasuelo, mamatambũũkĩsye kw’oko asu mamanthaa kũmathĩn’ya: o na vati mũndũ waatonya kũmasiĩĩa; nũndũ kũmakĩa kwakwatie ngo syonthe sya andũ.'),
('kam', 'EST', 9, 3, 'Na anene onthe me mbee ũsumbĩnĩ ma ila ilungu nene sya nthĩ, na asumbĩ anini, na makavana, na ala matethasya mawĩa ma mũsumbĩ, matetheesya Ayuti; nĩkwĩthĩwa kũmũkĩa Molitekai nĩkwamakwatie.'),
('kam', 'EST', 9, 4, 'Nũndũ Molitekai aĩ mũnene nyũmbanĩ ya mũsumbĩ, na nguma yake yanyaĩĩka ilungunĩ nene syonthe sya nthĩ; nũndũ ũ mũndũ Molitekai nĩwaendeee kũneneva na kũneneva.'),
('kam', 'EST', 9, 5, 'Na Ayuti makũna amaitha moo onthe na makũna ma ũvyũ, na ũai na wanangĩko, na mameka o tondũ mendie asu mamamenaa.'),
('kam', 'EST', 9, 6, 'Na nyũmbanĩ nene ya ũsumbĩ ku Susani, Ayuti mooaie na kũmina andũ maana atano.'),
('kam', 'EST', 9, 7, 'Na Valisandatha, na Ndalivoni, na Asivatha,'),
('kam', 'EST', 9, 8, 'na Volatha, na Atalia, na Alitatha,'),
('kam', 'EST', 9, 9, 'na Valimasita, na Alisai, na Alitai, na Vaisatha,'),
('kam', 'EST', 9, 10, 'ala ana ĩkũmi ma Amani mwana wa Ametatha, mũmaitha wa Ayuti, mamoaa; ĩndĩ mũtavo maiaaũtambũũkĩsya moko moo.'),
('kam', 'EST', 9, 11, 'Mũthenya ũsu ũtalo wa ala mooaĩwe nyũmbanĩ nene ya ũsumbĩ ku Susani, waetwe mbee wa mũsumbĩ.'),
('kam', 'EST', 9, 12, 'Na mũsumbĩ amwĩa Esita mũka, Ayuti nĩmooaie na kũmina andũ maana atano nyũmbanĩ nene ya ũsumbĩ ku Susani, na ana ĩkũmi ma Amani; na ĩndĩ mekĩte ata ũtialonĩ wa ilungu nene sya nthĩ ila ingĩ sya mũsumbĩ! Na yu vata waku nĩ mwaũ? Na nũũnengwa: kana kwenda kwaku kũngĩ nĩ kwaũ? Na ũkeekwa.'),
('kam', 'EST', 9, 13, 'Nĩvo ĩndĩ Esita waisye, Ethĩwa nĩwendeesya mũsumbĩ, nĩkũnenganwe kwa Ayuti ala matwĩe Susani kwĩka ũnĩ o kwĩanana na ũtw’ĩo wa ũmũnthĩ, na ala ana ĩkũmi ma Amani nĩmasũw’e ũla mũtĩnĩ mũtũlu.'),
('kam', 'EST', 9, 14, 'Na mũsumbĩ eeaa ũu wĩkwe: na ũtw’ĩo waumĩwe vu Susani; na masũsya ala ana ĩkũmi ma Amani.'),
('kam', 'EST', 9, 15, 'Na Ayuti ala maĩ Susani moombana ĩngĩ mũthenya wa ĩkũmi na ĩna wa mwei wa Atali, na mooaĩa andũ maana atatũ vu Susani; ĩndĩ mũtavo maiaaũtambũũkĩsya moko moo.'),
('kam', 'EST', 9, 16, 'Na Ayuti ala angĩ ala maĩ ilungunĩ nene sya nthĩ sya mũsumbĩ moombana, na meeyĩũngamĩa mathayũ moo, na mathũmũa kuma amaithanĩ moo, na mamoaa ala mamamenaa ngili mĩongo mũonza na itano; ĩndĩ mũtavo maiaaũtambũũkĩsya moko moo.'),
('kam', 'EST', 9, 17, 'Ũu weekiwe mũthenya wa ĩkũmi na ĩtatũ wa mwei wa Atali; na mũthenya wa ĩkũmi na ĩna waw’o mathũmũa, na mootw’a mũthenya wa mboka na wa mũyo.'),
('kam', 'EST', 9, 18, 'Ĩndĩ Ayuti ala maĩ Susani moombana mũthenya wa ĩkũmi na ĩtatũ waw’o, na wa ĩkũmi na ĩna waw’o; na mũthenya wa ĩkũmi na ĩtano waw’o mathũmũa, na mootw’a mũthenya wa mboka na mũyo.'),
('kam', 'EST', 9, 19, 'Kwondũ wa ũu Ayuti ma mĩsyĩ, ala matwĩe tũtũla tũte twake na maũvai, matw’a mũthenya wa ĩkũmi na ĩna wa mwei wa Atali mũthenya wa mũyo na mboka, na mũthenya mũseo, na wa kũtwaanĩaa syĩndũ ũmwe na ũla ũngĩ.'),
('kam', 'EST', 9, 20, 'Na Molitekai aandĩka maũndũ asu, na atwaa mavalũa kwa Ayuti onthe ala maĩ ilungunĩ nene syonthe sya nthĩ sya mũsumbĩ Aasuelo, kũla kũkuvĩ na kũla kũasa,'),
('kam', 'EST', 9, 21, 'kũmalũlũmĩlya kana masũvĩae mũthenya wa ĩkũmi na ĩna wa mwei wa Atali, na mũthenya wa ĩkũmi na ĩtano waw’o, kĩla mwaka,'),
('kam', 'EST', 9, 22, 'o mĩthenya ĩsu ĩla Ayuti mathũmũie kuma amaithanĩ moo, na mwei ũla wamaalyũkĩle kuma woonĩ kũlika mũyonĩ, na kuma woonĩ mũnene kũlika mũthenya mũseo; nĩ kana mamĩtw’e mĩthenya ya mboka na ya mũyo, na ya kũtwaanĩaa syĩndũ ũmwe na ũla ũngĩ, na mĩthĩnzĩo kwa ngya.'),
('kam', 'EST', 9, 23, 'Na Ayuti meetĩkĩla kwĩka ũndũ mambĩlĩlye, na tondũ Molitekai wamaandĩkĩe;'),
('kam', 'EST', 9, 24, 'nĩkwĩthĩwa Amani mwana wa Ametatha Mũakaki, mũmaitha wa Ayuti onthe, asilĩte ĩũlũ wa Ayuti amanange, na akĩkya Vuli, naw’o nĩ kũlimana, nĩ kana amamine, na kwananga;'),
('kam', 'EST', 9, 25, 'ĩndĩ yĩla ũvoo wavikie vala ve mũsumbĩ, eeaa na mavalũa kana ũsũanĩo ũsu mũthũku, ũla wasũanĩĩe Ayuti, ũsyoke ĩũlũ wa mũtwe wake mwene, na kana we na ana make masũw’e mũtĩnĩ mũtũlu.'),
('kam', 'EST', 9, 26, 'Kwondũ wa ũu meeta mĩthenya ĩsu Vulimu, kũatĩĩa syĩtwa ya Vuli. Na ĩndĩ kwondũ wa ndeto syonthe sya valũa ũsu, na ũndũ ũla monete kwondũ wa ũndũ ũsu, na ũndũ wamakĩtĩkie,'),
('kam', 'EST', 9, 27, 'Ayuti meeaa, na kwĩyaĩkya ene, na ĩũlũ wa ũsyao woo, na ĩũlũ wa onthe ala meevulanĩtye namo, nĩ kana ũndũ ũsu ndũkaathele, kana makasũvĩaa mĩthenya ĩsu ĩlĩ kwĩanana na ũandĩko wayo, na kwĩanana na kũtw’ĩwa ĩvinda yayo, kĩla mwaka;'),
('kam', 'EST', 9, 28, 'na kana mĩthenya ĩsu ĩkalilikanawe na kũsũvĩawa kĩla nzyawanĩ, na kĩla mũvĩa, na kĩla kĩlungu kĩnene kya nthĩ, na kĩla ndũa; na nĩ kana mĩthenya ĩsu ya Vulimu ndĩkaathele kuma katĩ wa Ayuti, o na ũlilikano wayo ndũkaaae kuma ũsyaonĩ woo.'),
('kam', 'EST', 9, 29, 'Nĩvo ĩndĩ Esita mũka wa mũsumbĩ, mwĩĩtu wa Aviaili, na Molitekai Mũyuti, maandĩkie na ũkũmũ w’onthe malũlũmĩlye valũa ũsu wa kelĩ wa Vulimu.'),
('kam', 'EST', 9, 30, 'Na atwaa mavalũa kwa Ayuti onthe ilungunĩ nene sya nthĩ ĩana na mĩongo ĩlĩ na mũonza sya ũsumbĩ wa Aasuelo, na ndeto sya mũuo na sya w’o,'),
('kam', 'EST', 9, 31, 'malũlũmĩlye mĩthenya ĩsu ya Vulimu mavindanĩ mayo ala maiĩtwe, kwĩanana na ũndũ Molitekai Mũyuti na Esita mũka wa mũsumbĩ mameaĩe, na ũndũ meetw’ĩĩe ene na ũsyao woo, ũvoonĩ wa kũtĩĩa kũya na kũĩa kwoo.'),
('kam', 'EST', 9, 32, 'Na mwĩao wa Esita walũlũmĩlya maũndũ asu ma Vulimu; na waandĩkwa yĩla ĩvukunĩ.'),
('kam', 'EST', 10, 1, 'Na mũsumbĩ Aasuelo aumĩthya ĩ nthĩ, na ithamanĩ sya ũkanga, koti.'),
('kam', 'EST', 10, 2, 'Na meko onthe ma ũtonyĩ wake na wa vinya wake mũnene, na ũtalo w’onthe wa ũnene wa Molitekai, ũndũ mũsumbĩ wamũnenevisye, matiandĩkĩtwe mavukunĩ ma meko ma mavinda ma asumbĩ ma Metia na Velisia?'),
('kam', 'EST', 10, 3, 'Nũndũ Molitekai ũsu Mũyuti aĩ wa kelĩ ũnenenĩ kwa mũsumbĩ Aasuelo, na mũnene katĩ wa Ayuti, na kwĩtĩkĩlwa nĩ wingĩ wa ana‐aĩthe, akĩmanthĩa andũ make ũseo, na aineena mũuo na ũsyao wake w’onthe.'),
('kam', 'JOB', 1, 1, 'Kwaĩ mũndũ nthĩ ya Usi, syĩtwa yake eetawa Yovu; na mũndũ ũsu aĩ mwĩanĩu na mũlũngalu, ũmwe ũla wamũkĩaa Ngai, na wethyũũĩte akatia ũthũku.'),
('kam', 'JOB', 1, 2, 'Na asyaĩwe ana mũonza na eĩtu atatũ.'),
('kam', 'JOB', 1, 3, 'O na ũthwii wake naw’o waĩ malondu ngili mũonza, na ngamĩle ngili itatũ, na syove maana atano sya ng’ombe, na mang’oi maka maana atano, na andũ aingĩ mũno ma nyũmba yake; kwondũ wa ũu mũndũ ũsu aĩ mũnene kwĩ ana onthe ma ngalĩ ya wumĩlonĩ wa syũa.'),
('kam', 'JOB', 1, 4, 'Na ana make maenda makĩvoka mboka nyũmbanĩ ya kĩla ũmwe mũthenya wake; na matũmana mameta eĩtu‐a‐inyia moo atatũ maye na kũnyw’a nao.'),
('kam', 'JOB', 1, 5, 'Na kweethĩwa, yĩla mĩthenya ya mboka yoo yakomanie, kana Yovu atũmana amatheethya, na ookĩla kĩoko tene, na athemba nthembo sya kũvĩvw’a kwĩanana na ũtalo woo onthe: nũndũ Yovu aasya, Nokwĩthĩwa ana makwa nĩmavĩtisye, na kũmũuma Ngai ngoonĩ syoo. Ũu now’o Yovu wekaa mavinda onthe.'),
('kam', 'JOB', 1, 6, 'Na kweethĩwa mũthenya ũla ana ma Ngai mookie kwĩyumĩlya mbee wa Yeova, nake Satani ooka katĩ wamo.'),
('kam', 'JOB', 1, 7, 'Na Yeova amwĩa Satani, Wauma va? Nĩvo ĩndĩ Satani wamũsũngĩie Yeova, na amwĩa, Nauma kwanganga kũũ na kũũ nthĩ na kũtambũkanga kũũ na kũũ ĩũlũ wayo.'),
('kam', 'JOB', 1, 8, 'Na Yeova amwĩa Satani, Nũsũanĩĩte ũndũ wa mũthũkũmi wakwa Yovu? Nũndũ kũti ũngĩ take ĩũlũ wa nthĩ, mũndũ mwĩanĩu na mũlũngalu, ũla ũmũkĩaa Ngai, na wĩthyũũĩte akatia ũthũku.'),
('kam', 'JOB', 1, 9, 'Na ĩndĩ Satani asũngĩa Yeova, na amũkũlya, Yovu nũmũkĩaa Ngai mana?'),
('kam', 'JOB', 1, 10, 'Ndwĩkĩĩte wiio kũmũthyũlũlũka, o na nyũmba yake, na kyonthe kĩla wĩ nakyo, ngalĩ syonthe? Nũathimĩte wĩa wa moko make, na ũthwii wake nĩwingĩvĩte nthĩ.'),
('kam', 'JOB', 1, 11, 'Ĩndĩ tambũũkya kw’oko kwaku yu, noikiita kyonthe kĩla wĩ nakyo, nake akakũuma ũthyũnĩ waku.'),
('kam', 'JOB', 1, 12, 'Na Yeova amwĩa Satani, Sisya, kyonthe kĩla wĩ nakyo kĩ ũtonyinĩ waku; ĩndĩ we mwene ndũkamũtambũũkĩĩsye kw’oko kwaku. Na ĩndĩ Satani auma vala ve Yeova.'),
('kam', 'JOB', 1, 13, 'Na kweethĩwa mũthenya ũmwe yĩla ana make na eĩtu make maĩ makĩya na kũnyw’a mbinyu nyũmbanĩ ya mũkũũe woo,'),
('kam', 'JOB', 1, 14, 'atĩ mũtũmwa ooka vala ve Yovu, na amwĩa, Ng’ombe syĩĩ ikĩĩma na mang’oi makĩya vakuvĩ nasyo;'),
('kam', 'JOB', 1, 15, 'na Aseva maivithũkĩa, na maitwaa; ĩĩ, nĩmooaa athũkũmi kwa kũmatemanga na ũvyũ; na no nyie navonoka nĩ nyioka nĩkũtavye.'),
('kam', 'JOB', 1, 16, 'Na yĩla waneenaa kwooka ũngĩ, na asya, Mwaki wa Ngai nĩwavalũka kuma ĩtunĩ, na wavĩvya malondu na athũkũmi, na wamamina; na no nyie navonoka nĩ nyioka ngũtavye.'),
('kam', 'JOB', 1, 17, 'O yĩla waneenaa, ũngĩ nake ooka, na asya, Akalitei matilĩkana nguthu itatũ, na mavithũka vala ve ngamĩle, na maitwaa, ĩĩ, na kũaa athũkũmi kwa kũmatemanga na ũvyũ; na no nyie navonoka nĩ nyioka ngũtavye.'),
('kam', 'JOB', 1, 18, 'Na o yĩla waneenaa kwooka ũngĩ, na asya, Ana maku na eĩtu maku meĩ makĩya na kũnyw’a mbinyu nyũmbanĩ ya ũla mũkũũ woo;'),
('kam', 'JOB', 1, 19, 'na, sisya, kĩseve kĩnene kyooka kuma weũnĩ, na kyakũna ikoto inya sya nyũmba, na yamavalũkĩla anake, na nĩmakw’a; na no nyie navonoka nĩ nyioka ngũtavye.'),
('kam', 'JOB', 1, 20, 'Na ĩndĩ Yovu ookĩla, na atembũanga ngũa yake ndasa, na eenza mũtwe wake, na eevalũkya nthĩ, na athaitha;'),
('kam', 'JOB', 1, 21, 'na asya, Nĩnaumie ĩvunĩ ya mwaitũ nĩ mũthei, na ngasyoka vo nĩ mũthei: Yeova nĩwanenganie, na Yeova nĩwosete; syĩtwa ya Yeova yĩtaĩwe.'),
('kam', 'JOB', 1, 22, 'Ũndũnĩ ũsu w’onthe Yovu ndaavĩtya, kana kwilĩĩla Ngai na ũtumanu.'),
('kam', 'JOB', 2, 1, 'Na ĩngĩ kweethĩwa mũthenya ũla ana ma Ngai mookie kwĩyumĩlya mbee wa Yeova, nake Satani ooka katĩ woo eyumĩlye mbee wa Yeova.'),
('kam', 'JOB', 2, 2, 'Na Yeova amwĩa Satani, Wauma va? Na Satani asũngĩa Yeova, na amwĩa, Nauma kwanganga kũũ na kũũ nthĩ, na kuma kũtambũka kũũ na kũũ ĩũlũ wayo.'),
('kam', 'JOB', 2, 3, 'Na Yeova amwĩa Satani, Nũsũanĩĩte ũndũ wa mũthũkũmi wakwa Yovu? Nũndũ kũti ũngĩ take nthĩ, mũndũ mwĩanĩu na mũlũngalu, ũla ũmũkĩaa Ngai, na kwĩthyũũa kũtia ũthũku: na kũvika yu nũlũmasya wĩanĩu wake, o na kau nĩwanthing’ĩĩsye ũndũ wake, nĩmwanange vate kĩtumi.'),
('kam', 'JOB', 2, 4, 'Na Satani asũngĩa Yeova, na asya, Kĩkonde vandũ va kĩkonde, ĩĩ, kyonthe kĩla mũndũ wĩ nakyo nũnenganae kwondũ wa thayũ wake.'),
('kam', 'JOB', 2, 5, 'Ĩndĩ tambũũkya kw’oko kwaku yu, ũkiite ĩvĩndĩ yake na nyama ya mwĩĩ wake, na akakũuma ũthyũnĩ waku.'),
('kam', 'JOB', 2, 6, 'Na Yeova amwĩa Satani, Sisya, e kw’okonĩ kwaku; no mũeke e thayũ.'),
('kam', 'JOB', 2, 7, 'Na ĩndĩ Satani auma mbee wa Yeova, na amũkũna Yovu na mĩimũ mĩthũku kuma ũnyaĩĩ wa kũũ kwake kũvika lolotya wake.'),
('kam', 'JOB', 2, 8, 'Na eeyosea kĩlĩo kya kwĩvaavaa nakyo; na ekala mũunĩ.'),
('kam', 'JOB', 2, 9, 'Na ĩndĩ kĩveti kyake kyamwĩa, Kũvika o na yu no ũlũmĩtye wĩanĩu waku? Uma Ngai noikw’a.'),
('kam', 'JOB', 2, 10, 'Ĩndĩ akĩtavya, Nũũneena ta ũmwe wa aka atumanu ũndũ maneenaa. Nata? Tũkoosa ũseo kw’okonĩ kwa Ngai, na tũikosa ũthũku? Ũndũnĩ ũsu w’onthe Yovu ndaavĩtya na ilomo syake.'),
('kam', 'JOB', 2, 11, 'Na yĩla anyanyae atatũ ma Yovu meewie ũthũku ũsu w’onthe ũla wamũkĩe, mooka kĩla ũmwe kuma vandũ vake; Elivasi Mũtemani, na Mbilitati Mũsui, na Nzovali Mũnaamathi; na matw’a kyathĩ vamwe maende kũmũĩĩa na kũmũkiakisya.'),
('kam', 'JOB', 2, 12, 'Na yĩla mookĩlilye metho moo me kũasa, na matyaamũmanya, mookĩlya mawasya moo, na kũĩa; na kĩla ũmwe atembũanga ngũa yake ndasa, na molũlĩlya kĩtoo mĩtwenĩ yoo kwelekela ĩtunĩ.'),
('kam', 'JOB', 2, 13, 'Na ĩndĩ mekala nthĩ vamwe nake mĩthenya mũonza na matukũ mũonza, na vai ũmwe waaneena ndeto nake: nũndũ moonie kana woo wake nĩ mwingĩ mũno.'),
('kam', 'JOB', 3, 1, 'Ĩtina wa ũu Yovu aathamya kanyw’a wake, na aumanĩa mũthenya wake.'),
('kam', 'JOB', 3, 2, 'Na Yovu asũngĩa na asya:'),
('kam', 'JOB', 3, 3, 'Mũthenya nĩwae ũla nasyaiwe, Na ũtukũ ũla waisye, Kana ka kavĩsĩ nĩkaitavĩtwe.'),
('kam', 'JOB', 3, 4, 'Mũthenya ũsu nĩwĩthĩwe kĩvindu; Ngai ũla wĩ ĩũlũ ndakomanthe, O na kyeni kĩtikokenee.'),
('kam', 'JOB', 3, 5, 'Kĩvindu na kyuu kya kĩkw’ũ nĩsyasye wasyo e syo; Ĩthweo nĩyĩkalae ĩũlũ waw’o; Kyonthe kĩla kĩtuma mũthenya wĩthĩwa mwiũ nĩkyũtĩsye.'),
('kam', 'JOB', 3, 6, 'Na ũndũ wa ũtukũ ũsu, kĩvindu kya ngokomi nĩkyũkwate: Ndũkatane katĩ wa mĩthenya ya mwaka; Ndũkatalwe ũtalonĩ wa myei.'),
('kam', 'JOB', 3, 7, 'Sisya, ũtukũ ũsu nĩwĩthĩwe wĩ w’oka; Wasya o na wĩva wa ũtanu ndũkalike nthĩnĩ waw’o.'),
('kam', 'JOB', 3, 8, 'Nĩmaumanĩe ala maumanĩaa ũ mũthenya, Ala meyũmbanĩtye kũthũlũmũa leviathani.'),
('kam', 'JOB', 3, 9, 'Ndata sya ũmithinĩ waw’o nĩsyĩthĩwe kĩvindu: Nũmanthe kyeni, ĩndĩ ndũkakyone; O na ndũkone ilomo sya metho ma kĩoko:'),
('kam', 'JOB', 3, 10, 'Nĩkwĩthĩwa ndwaavinga mĩomo ya ĩvu ya mwaitũ, Kana kũvitha metho makwa thĩna.'),
('kam', 'JOB', 3, 11, 'Nĩkĩ ndyaakw’a o kuma ĩvunĩ? Nĩkĩ ndyaaumwa nĩ veva yĩla mwaitũ wanzyaie?'),
('kam', 'JOB', 3, 12, 'Nĩkĩ mau mambosie? Kana nondo, nonge?'),
('kam', 'JOB', 3, 13, 'Nũndũ yu nĩthĩwa ngomete na kũvindya; Nĩthĩwa ngomete too; na ĩndĩ nĩthĩwa nĩthũmũĩte,'),
('kam', 'JOB', 3, 14, 'Vamwe na asumbĩ na atai ma kũũ nthĩ, Ala meeyakĩe ene kũndũ kwanangĩku;'),
('kam', 'JOB', 3, 15, 'Kana vamwe na anene me mbee ũsumbĩnĩ ala maĩ na thaavu, Ala mausũisye nyũmba syoo vetha:'),
('kam', 'JOB', 3, 16, 'Kana ta kĩvuno kĩvithe kĩvunĩtwe, ndyĩthĩwa naaĩthĩwa, Ta twana tũnini tũla tũtaona kyeni.'),
('kam', 'JOB', 3, 17, 'Vau ala athũku nĩmaekaa kũthĩna; Na vau ala me na mĩnoo nĩmathũmũaa,'),
('kam', 'JOB', 3, 18, 'Vau ala ove nĩmethũmũĩtye vamwe; Matyĩw’aa wasya wa mũũngamĩi.'),
('kam', 'JOB', 3, 19, 'Ala anini na ala anene me vo; Na mũthũkũmi nĩ mũthasye kuma kwa vwana wake.'),
('kam', 'JOB', 3, 20, 'Nĩkĩ kyeni nĩkĩnengetwe ũla wĩ na ũnyamao, Na thayũ ũla wĩ na ũũ ngoonĩ yake;'),
('kam', 'JOB', 3, 21, 'Ala me na mea ma kĩkw’ũ, ĩndĩ kĩtyũkaa, Na makĩnzĩaa kũvĩtũka mothwii mavithe;'),
('kam', 'JOB', 3, 22, 'Ala matanaa mũno, Na me na mũyo, yĩla matonya kwona mbũa?'),
('kam', 'JOB', 3, 23, 'Nĩkĩ kyeni nĩkĩnengawa mũndũ ũla ũvithĩtwe nzĩa yake, Na ũla Ngai ũmũthyũlũlũkĩtye wiio?'),
('kam', 'JOB', 3, 24, 'Nũndũ kũvevũũka kwakwa nĩkũkaa ndanamba kũya, Na kũluma kwakwa nĩkwonoetw’e ta manzĩ.'),
('kam', 'JOB', 3, 25, 'Nũndũ ũndũ ũla nĩkĩaa nĩwũkaa ĩũlũ wakwa, Na ũla nĩkĩaa nũmbũkĩaa.'),
('kam', 'JOB', 3, 26, 'Ndiuĩtye, o na ndikilĩtye, o na ndi na ũthũmũo; Ĩndĩ thĩna nĩwũkaa.'),
('kam', 'JOB', 4, 1, 'Na ĩndĩ Elivasi Mũtemani asũngĩa, na asya,'),
('kam', 'JOB', 4, 2, 'Ethĩwa mũndũ akatata kũneena naku, ũkeew’a woo? Ĩndĩ nũũ ũtonya kwĩsiĩĩa ndakaneene?'),
('kam', 'JOB', 4, 3, 'Sisya, nũmanyĩĩtye aingĩ, Na nũmekĩĩte vinya moko maleelu.'),
('kam', 'JOB', 4, 4, 'Ndeto syaku nĩsyatw’ĩĩkaa ũla wavalũkaa, Na nĩwalũmasya mau mate vinya.'),
('kam', 'JOB', 4, 5, 'Ĩndĩ yu nũkũkĩe, naku nũkũleela; Nũũkũkiita, naku nũkũũũya.'),
('kam', 'JOB', 4, 6, 'Kũmũkĩa Ngai tikw’o ũĩkĩĩi waku, Na ũlũngalu wa mĩendele yaku tiw’o wĩkwatyo waku?'),
('kam', 'JOB', 4, 7, 'Lilikana, nĩngũkwĩsũva, nũũ waaa, ate na ĩvĩtyo? Kana nĩ va ala alũngalu mavetetwe?'),
('kam', 'JOB', 4, 8, 'Kwĩanana na ũndũ nonete, ala menzaa ũthũku, Na kũvũĩa thĩna, makethaa o w’o.'),
('kam', 'JOB', 4, 9, 'Kwondũ wa veva wa Ngai nĩmaaa, Na kwondũ wa kĩuutani kya ũthatu wake nĩmaminawa.'),
('kam', 'JOB', 4, 10, 'Kũluma kwa mũnyambũ, na wasya wa mũnyambũ mwai, Na maeo ma mĩnyambũ ya mĩika, nĩmatũlĩtwe.'),
('kam', 'JOB', 4, 11, 'Mũnyambũ mũkũũ nĩwanangĩkaa nũndũ kũti kya nzyĩma, Na tũswii twa mũnyambũ mũka nĩtũnyaĩĩkĩtw’e kũasa.'),
('kam', 'JOB', 4, 12, 'Ĩndĩ ũvoo nĩwaetiwe kwakwa na kĩmbithĩ, Na kũtũ kwakwa kwoosa kĩwe kyaw’o.'),
('kam', 'JOB', 4, 13, 'Mosũanĩonĩ mawoninĩ ma ũtukũ, Yĩla too mũnene ũkwataa andũ,'),
('kam', 'JOB', 4, 14, 'W’ĩa nĩwambũkĩe, na kũtetema, Ũla watumie mavĩndĩ makwa onthe mathingithanga.'),
('kam', 'JOB', 4, 15, 'Na ĩndĩ veva wavĩtĩla mbee wa ũthyũ wakwa; Maw’ĩa ma mwĩĩ wakwa maũngama.'),
('kam', 'JOB', 4, 16, 'Waũngama, ĩndĩ ndyaatonya kwona mũvw’anĩle waw’o; Mũvw’ano waĩ mbee wa metho makwa: Kwaĩ ũkilyo, na neew’a wasya, ũkyasya,'),
('kam', 'JOB', 4, 17, 'Mũndũ ũla ũkusaa akeethĩwa mũlũngalu kwĩ Ngai? Mũndũ akeethĩwa mũtheu kwĩ Mũmbi wake?'),
('kam', 'JOB', 4, 18, 'Sisya, ndaĩkĩĩaa athũkũmi make; Na alaĩka make nũmawetaa ũtumanu:'),
('kam', 'JOB', 4, 19, 'Nĩ mbee veanata ala mekalaa nyũmbanĩ sya yũmba, Ala wambĩlĩlyo woo wĩ kĩtoonĩ, Ala makinyangawa ta lungulu!'),
('kam', 'JOB', 4, 20, 'Katĩ wa kĩoko na wĩoo nĩmanangawa: Nĩmaaa tene na tene vate ũmwe wonaa ta ũndũ.'),
('kam', 'JOB', 4, 21, 'Ĩkanda yoo ya ĩeema yĩtithaaw’a nthĩnĩ woo? Nĩmakusaa, o na mate na ũmanyi.'),
('kam', 'JOB', 5, 1, 'Ĩtana yu; ve ũmwe wĩkũsũngĩa? Na ũkeethyũũĩa wĩva wa ala atheu?'),
('kam', 'JOB', 5, 2, 'Nũndũ ũthatu nĩwũaa mũndũ mũtumanu, Na kĩwĩu nĩkyũaa ũla ũte kĩlĩko.'),
('kam', 'JOB', 5, 3, 'Nĩnonete mũtumanu aitambũũkya mĩi: Ĩndĩ nĩnaumanĩe ũtũo wake na kĩthũlũmũko.'),
('kam', 'JOB', 5, 4, 'Syana syake syĩ kũasa na ũsũvĩo, Na nikanyangĩwe mbingĩlonĩ, O na vati ũmwe wa kwivonokya:'),
('kam', 'JOB', 5, 5, 'Ala me na nzaa nĩmaĩsaa ngetha yasyo, O na kũmyumya mĩw’anĩ; Na kĩtei nĩkyathamasya kyose ũthwii woo.'),
('kam', 'JOB', 5, 6, 'Nũndũ ũnyamao ndumaa kĩtoonĩ, O na thina ndũthandĩkaa kuma nthĩ;'),
('kam', 'JOB', 5, 7, 'Ĩndĩ mũndũ asyaĩawa thĩna, O ta ngala sya mwaki ĩũlũkaa ĩũlũ.'),
('kam', 'JOB', 5, 8, 'Ĩndĩ ngalĩ ĩ yakwa, nĩthĩwa nĩmũmantha Ngai, Na kwia ũvoo wakwa kwa Ngai;'),
('kam', 'JOB', 5, 9, 'Ũla wĩkaa maũndũ manene na ala matamanthĩka, Maũndũ ma ũseng’ya matatalĩka:'),
('kam', 'JOB', 5, 10, 'Ũla uasya mbua ĩũlũ wa nthĩ, Na ũtũmaa manzĩ isesinĩ;'),
('kam', 'JOB', 5, 11, 'Kwondũ wa ũu nũmokĩlasya ala me ĩtheo, Na ala mametaa makĩtũlw’a vala vate mũisyo.'),
('kam', 'JOB', 5, 12, 'Nĩwanangaa mosũanĩo ma nzeleke, Na ĩndĩ moko moo matitonya kwĩka ũndũ masũanĩĩte.'),
('kam', 'JOB', 5, 13, 'Nũkwataa ala oĩ ũselekenĩ woo; Na ũtao wa ala ai nĩwanangĩkaa kwa kũkalaatwa.'),
('kam', 'JOB', 5, 14, 'Nĩmakomanaa na kĩvindu kwĩ mũthenya, Na kũvavata mũthenya katĩ o ta ũtukũ.'),
('kam', 'JOB', 5, 15, 'Ĩndĩ nũtangĩĩaa kuma ũvyũnĩ wa makanyw’a moo. O athĩni kw’okonĩ kwa ala me ũtonyi.'),
('kam', 'JOB', 5, 16, 'Kwondũ wa ũu ngya syĩ na wĩkwatyo, Na ũthũku ũitumasya kanyw’a waw’o.'),
('kam', 'JOB', 5, 17, 'Sĩsya, nĩ mũtanu mũndũ ũla Ngai ũmũkanasya: Kwondũ wa ũu ndũkavũthye kũkũnwa nĩ Mwene Vinya W’onthe.'),
('kam', 'JOB', 5, 18, 'Nũndũ nũkũnaa, na nĩwovaa; Nĩwũkitĩkasya, na moko make maivosya.'),
('kam', 'JOB', 5, 19, 'Akakũvonokya kuma mathĩnanĩ thanthatũ; Ĩĩ, mathĩnanĩ mũonza vai ũthũku ũkakũkiita.'),
('kam', 'JOB', 5, 20, 'Yũanĩ akakwovosya kuma kĩkw’ũnĩ; Na kaũnĩ kuma vĩnyanĩ wa ũvyũ.'),
('kam', 'JOB', 5, 21, 'Ũkavithwa kwa mũsalisa wa ũĩmĩ; O na ndũkakĩa wanangĩko yĩla wĩũka.'),
('kam', 'JOB', 5, 22, 'Ũkathekeea wanangĩko na nzaa; O na ndũkakĩa nyamũ sya nthĩ.'),
('kam', 'JOB', 5, 23, 'Nũndũ ũkeethĩwa na wĩw’ano na mavia ma nthĩ; Na nyamũ sya nthĩ ikeethĩwa na mũuo naku.'),
('kam', 'JOB', 5, 24, 'Na ũkamanya kana ĩeema yaku yĩ na mũuo; Na ũkasisya ĩĩthya yaku, na ũkeethĩa vati kĩndũ kyau vo.'),
('kam', 'JOB', 5, 25, 'O na ũkamanya kana ũsyao waku ũkeethĩwa mwingĩ, Na mosyaanĩo maku ta nyeki sya nthĩ.'),
('kam', 'JOB', 5, 26, 'Ũkavika mbũanĩ yaku wĩ na myaka mĩanĩu, O ta kyove kya ngetha ũndũ kĩkawa kyavika ĩvinda yakyo.'),
('kam', 'JOB', 5, 27, 'Sisya ũu, nĩtũthianĩte, now’o ũilyĩ; Wĩw’e, na ũyũmanya wone ũseo.'),
('kam', 'JOB', 6, 1, 'Nĩvo ĩndĩ Yovu asũngĩa na asya,'),
('kam', 'JOB', 6, 2, 'A! Kethĩwa woo wakwa nũthimĩka, Na wanangĩko wakwa w’onthe mũnene kwiwa ithiminĩ!'),
('kam', 'JOB', 6, 3, 'Nũndũ yu wĩthĩwa wĩ mũito kwĩ kĩthangathĩ kya maũkanga: Kwondũ wa ũu ndeto syakwa nivulũkaa.'),
('kam', 'JOB', 6, 4, 'Nũndũ mĩsyĩ ya Mwene Vinya W’onthe yĩ nthĩnĩ wakwa, Veva wakwa nũnyusyaa ĩvai yayo: Motĩsyo ma Ngai nĩmendaũĩsye.'),
('kam', 'JOB', 6, 5, 'Ĩng’oi ya kĩthekanĩ nĩyanasya yĩ na nyeki? Kana ng’ombe nĩyanasya ĩkĩya lĩu wayo?'),
('kam', 'JOB', 6, 6, 'Kĩndũ kĩte mũsamo nĩkĩĩka kĩte mũnyũ? Kana ve mũsamo mũuunĩ mweũ wa ĩtumbĩ?'),
('kam', 'JOB', 6, 7, 'Ngoo yakwa nĩleaa kwikiita; Nĩ ta lĩu wĩ tiiki kwakwa.'),
('kam', 'JOB', 6, 8, 'A! Kethĩwa ndonya kwona kĩla ngwĩtya; Na Ngai akanenga kĩndũ kĩla nĩ na mea makyo!'),
('kam', 'JOB', 6, 9, 'O atĩ kethĩwa Ngai mĩwendeew’a nĩ kũnganyanga; Atĩ akalekya kw’oko kwake, na kũmbeta!'),
('kam', 'JOB', 6, 10, 'Ũu wĩthĩwe ũkiakisyo wakwa kũvika yu, Ĩĩ, nĩtanĩe woo ũla ũtekwĩw’ĩa tei, Atĩ ndinakaĩa ndeto sya Ũla Mũtheu.'),
('kam', 'JOB', 6, 11, 'Vinya wakwa nĩ mwaũ, kana neteele? Na mũminũkĩlyo wakwa nĩ mwaũ, nũmĩĩsye?'),
('kam', 'JOB', 6, 12, 'Vinya wakwa nĩ vinya wa mavia? Kana mwĩĩ wakwa nĩ wa ũthuku?'),
('kam', 'JOB', 6, 13, 'Ti ũndũ ndi na ũtethyo nthĩnĩ wakwa, Na ũĩ nũlũngĩtw’e kũasa nakwa?'),
('kam', 'JOB', 6, 14, 'Ũla ũkilyĩ kũthelekela nĩwaĩle kwonw’a ũseo nĩ mũnyanyae; O ũla ũekaa kũmũkĩa Mwene Vinya W’onthe.'),
('kam', 'JOB', 6, 15, 'Ana‐a‐asa makwa nĩmekĩte ũkengani ta kalũsĩ, Ta ũkinyĩlo wa tũlũsĩ tũla tũng’alaa;'),
('kam', 'JOB', 6, 16, 'Tũla twiĩtw’e nĩ manzĩ momĩtw’e nĩ mbevo, Na nthĩnĩ watw’o ĩa nĩyĩvithaa:'),
('kam', 'JOB', 6, 17, 'Ĩvĩnda yĩla tũkũvyũva, nĩtũũng’ala; Yĩla kwavyũva, nĩtũng’alĩlaa vandũ vatw’o.'),
('kam', 'JOB', 6, 18, 'Aendi ma kyalo ala maendaa na nzĩa yatw’o nĩmathũkaa; Nĩmambataa kũndũ kwanangĩku, na makyaa.'),
('kam', 'JOB', 6, 19, 'Aendi ma kyalo ma Tema nĩmasiisye, Nguthu sya Sieva nĩsyameteelile,'),
('kam', 'JOB', 6, 20, 'Nĩmasonokiw’e nũndũ maĩ na wĩkwatyo; Nĩmookie vo, na mathokoanw’a.'),
('kam', 'JOB', 6, 21, 'Na yu inyw’ĩ no vathei; Nĩmũkwona ũtĩsyo, na mũikĩa.'),
('kam', 'JOB', 6, 22, 'Nĩnaisye, Nengae nyie? Kana, Umyai mũthĩnzĩo kwondũ wakwa wa syĩndũ syenyu?'),
('kam', 'JOB', 6, 23, 'Kana, Mbonokyai kuma kw’okonĩ kwa nthũ? Kana, Mbovosyai kuma kw’okonĩ kwa athĩn’ya?'),
('kam', 'JOB', 6, 24, 'Manyĩsyai nyie, na ngakilya: Na mbon’yai nĩmanye nĩvĩtĩtye ũndũnĩ wĩva.'),
('kam', 'JOB', 6, 25, 'Ndeto sya ũlũngalu ko syĩ vinya! Ĩndĩ ũkan’yo wenyu, naw’o ũkanasya kyaũ?'),
('kam', 'JOB', 6, 26, 'Nĩmũsũanĩa kũkan’ya ndeto, Nũndũ ndeto sya ũmwe ũla wĩyĩtũkĩte itilyĩ kĩseve?'),
('kam', 'JOB', 6, 27, 'Ĩĩ, mwenda kũlimanĩla ala makw’ĩĩwe nĩ aaĩthe, Na kũtw’ĩkĩthya mũnyanyae wenyu wa kũtandĩthya nake.'),
('kam', 'JOB', 6, 28, 'Yu kwondũ wa ũu endeew’ai nĩ kũnzisya; Nũndũ nĩ w’o ndikaneena ũvũngũ mothyũnĩ menyu.'),
('kam', 'JOB', 6, 29, 'Ĩthyũũei, nĩngũmwĩsũva, kũtikethĩwe ũsili ũte wa katĩ; Ĩĩ, ĩthyũũei ĩngĩ, ũvoo wakwa nĩ mũlũngalu.'),
('kam', 'JOB', 6, 30, 'Ve ũsili ũte wa katĩ ũĩmĩnĩ wakwa? Kaakaa wakwa ndũmanyaa maũndũ mathũku?'),
('kam', 'JOB', 7, 1, 'Vati kaũ wa mũndũ kũũ nthĩ? Na mĩthenya yake ti ta mĩthenya ya mũthũkũmi ũtuvawa?'),
('kam', 'JOB', 7, 2, 'Ta mũthũkũmi ũla wendaa mũno muunyĩ, Na ta ũla ũtuvawa ũla weteelaa ĩtuvi yake:'),
('kam', 'JOB', 7, 3, 'Ta ũu nanengiwe kwĩthĩwa na myei ya thĩna, Na matukũ me mĩnoo nĩmatwiwe kwondũ wakwa.'),
('kam', 'JOB', 7, 4, 'Yĩla ngũkoma, nĩasya, Ngookĩla ĩndĩĩ, na ũtukũ ũithela? Nakwa nusũĩtwe nĩ kwĩalyũlanga kũvika kũitheana.'),
('kam', 'JOB', 7, 5, 'Mwĩĩ wakwa nũkwatanĩte na iinyu na tũvali twa kĩtoo; Kĩkonde kyakwa nĩkĩũkwatana, na kĩilekan’ya ĩngĩ.'),
('kam', 'JOB', 7, 6, 'Mĩthenya yakwa ĩ mĩtũkĩ kwĩ mbavini, Nayo ĩthelaa vate wĩkwatyo.'),
('kam', 'JOB', 7, 7, 'A! Lilikana kana thayũ wakwa nĩ mũthũmũ: Itho yakwa yĩtikona ũseo ĩngĩ.'),
('kam', 'JOB', 7, 8, 'Itho ya ũla ũmbonaa yĩtikambona ĩngĩ; Metho maku makeethĩwa ĩũlũ wakwa, ĩndĩ ndikethĩwa.'),
('kam', 'JOB', 7, 9, 'O tondũ ĩthweo yĩminawa na yĩkyaa, Now’o ũla ũtheeaa Seoli ndakambata ĩngĩ.'),
('kam', 'JOB', 7, 10, 'Ndakasyoka ĩngĩ nyũmbanĩ yake, O na vandũ vake vatikamũmanya ĩngĩ.'),
('kam', 'JOB', 7, 11, 'Kwondũ wa ũu ndikasiĩĩa kanyw’a wakwa; Nganeena woonĩ mũnene wa veva wakwa; Nganyungunyĩsya ũũnĩ wa ngoo yakwa.'),
('kam', 'JOB', 7, 12, 'Nyie nĩ ũkanga, kana mũkũnga wa ũkanganĩ, Ũndũ ũmbiĩaa mũsyaĩĩsya?'),
('kam', 'JOB', 7, 13, 'Yĩla ngwasya, Ũkomo wakwa ũkangiakisya, Ũkomo wakwa ũkanyivĩsya mũnyungunyĩsya wakwa;'),
('kam', 'JOB', 7, 14, 'Nĩvo ĩndĩ nũũndelemya na ndoto, Na kũndĩsya na mawoni:'),
('kam', 'JOB', 7, 15, 'Na kwondũ wa ũu ngoo yakwa nĩnyuvaa kwitwa, Na kĩkw’ũ kwĩ mavĩndĩ aa makwa.'),
('kam', 'JOB', 7, 16, 'Nĩngũthĩtha thayũ wakwa; ndikwenda kwĩkala thayũ ĩndĩ yonthe: Ndeka; nũndũ mĩthenya yakwa nĩ mana.'),
('kam', 'JOB', 7, 17, 'Mũndũ nĩ kĩndũ kyaũ, ũndũ ũmũnenevasya, Na ũndũ ũmũlilikanaa,'),
('kam', 'JOB', 7, 18, 'Na ũndũ ũendaa vala ũĩ kĩla kĩoko, Na kũmũtata kĩla kavinda?'),
('kam', 'JOB', 7, 19, 'Nĩ ĩvinda yĩana ata ũkanzisya, Kana kũlea kũndia nĩ nyioka nĩmelye mata makwa?'),
('kam', 'JOB', 7, 20, 'Ethĩwa nĩmbĩtĩtye, nĩkwĩka ata, we mũsyaĩĩsya wa andũ? Nĩkĩ ũmbiĩte nĩthĩwe ũvano wa kũathawa nue, Ũkethĩa nĩ mũio kwakwa mwene?'),
('kam', 'JOB', 7, 21, 'Na nũndũ wa kĩ ndũekea ĩvĩtyo yakwa, na kũveta ũthũku wakwa? Nũndũ yu ngakoma kĩtoonĩ; Na ũkamantha na kĩthing’ĩĩsyo, ĩndĩ ndikethĩwa.'),
('kam', 'JOB', 8, 1, 'Na ĩndĩ Mbilitati Mũsui asũngĩa, na asya,'),
('kam', 'JOB', 8, 2, 'Ukaneena maũndũ aa kũvika ĩndĩĩ? Na ndeto sya kanyw’a waku ikeethĩwa ta kĩseve kĩ vinya kũvika ĩndĩĩ?'),
('kam', 'JOB', 8, 3, 'Ngai nĩwelelũkasya ũsili wa katĩ? Kana Mwene Vinya W’onthe nĩwelelũkasya ũlũngalu?'),
('kam', 'JOB', 8, 4, 'Ethĩwa syana syaku nimũvĩtanĩsye, Nake nĩwinenganĩte kw’okonĩ kwa ĩvĩtyo yasyo;'),
('kam', 'JOB', 8, 5, 'Kethĩwa ũkamantha Ngai na kĩthing’ĩĩsyo, Na kũmwĩsũva Mwene Vinya W’onthe;'),
('kam', 'JOB', 8, 6, 'Kethĩwa wĩ mũtheu na mũlũngalu: Vate ndĩi yu ethĩwa okĩlĩte kwondũ waku, Na kũtuma ũtũo wa ũlũngalu waku ũathimĩka.'),
('kam', 'JOB', 8, 7, 'O na kau wambĩlĩlyo waku waĩ mũnini, Ĩndĩ mũminũkĩlyo waku ũkaingĩva mũno.'),
('kam', 'JOB', 8, 8, 'Ĩndĩ nĩngũkwĩsũva, kũlya nzyawa ya tene, Na ĩnengane ũndũnĩ ũsu ũla aaĩthe mayo mamanthie'),
('kam', 'JOB', 8, 9, '(Nũndũ ithyĩ twĩ ma ĩoo, na tũtyĩsĩ ũndũ, Nĩkwĩthĩwa mĩthenya yaitũ kũũ nthĩ no muunyĩ);'),
('kam', 'JOB', 8, 10, 'Ndĩkakũmanyĩsya, na ũkũtavya, Na kũneena ndeto kuma ngoonĩ yayo?'),
('kam', 'JOB', 8, 11, 'Malula nĩmatonya kũmea vate ndaka? Makangaa nĩmatonya kũmea vate manzĩ?'),
('kam', 'JOB', 8, 12, 'O yĩla me mathithinĩu na mate mateme, Nĩmavovaa mĩtũkĩ kwĩ ũsũni o na wĩva.'),
('kam', 'JOB', 8, 13, 'Now’o iilyĩ nzĩa sya onthe ala molawa nĩ Ngai; Na wĩkwatyo wa ũla ũtakĩaa Ngai ũkaaa:'),
('kam', 'JOB', 8, 14, 'Wĩkwatyo wake ũkavetwa, Ũĩkĩĩi wake nĩ ũlũalũĩ.'),
('kam', 'JOB', 8, 15, 'Akaaĩĩa nyũmba yake, ĩndĩ ndĩkaũngama: Akamĩkwata, ĩndĩ ndĩkekala.'),
('kam', 'JOB', 8, 16, 'Nake nĩ mũthithinĩu o na kwĩ syũa, Na nthongooo syake nitambaa ĩũlũ wa mũũnda wake.'),
('kam', 'JOB', 8, 17, 'Mĩi yake nĩyĩlingĩlĩte kĩvumbu kya mavia, Nũsiasya vandũ va mavia.'),
('kam', 'JOB', 8, 18, 'Ethĩwa akaanangwa kuma vandũ vake, Nĩvo ĩndĩ vakamũkaĩa vakyasya, Ndyaakwona.'),
('kam', 'JOB', 8, 19, 'Sisya, ũũ nĩw’o ũtanu wa nzĩa yake; Na angĩ makathandĩka kuma nthĩ.'),
('kam', 'JOB', 8, 20, 'Sisya, Ngai ndakamwĩkya ũtee mũndũ mwĩanĩu, O na ndakaũngamya eki ma naĩ.'),
('kam', 'JOB', 8, 21, 'Akausũsya kanyw’a waku na ĩtheka, Na ilomo syaku na wasya mũnene.'),
('kam', 'JOB', 8, 22, 'Ala makũmenaa makeevw’ĩka nthoni; Na ĩeema ya ala athũku yĩtikethĩwa ĩngĩ.'),
('kam', 'JOB', 9, 1, 'Na ĩndĩ Yovu asũngĩa, na asya,'),
('kam', 'JOB', 9, 2, 'Nĩ w’o nĩnĩsĩ kana ũu nĩ wa w’o: Ĩndĩ mũndũ atonya kwĩthĩwa mũlũngalu kwa Ngai ata?'),
('kam', 'JOB', 9, 3, 'Ethĩwa nũnũkwendeew’a nĩ kũkananĩa nake, Ndatonya kũmũsũngĩa ũndũ ũmwe katĩ wa ngili.'),
('kam', 'JOB', 9, 4, 'Nĩ mũĩ ngoonĩ, na e ũtonyi vinyanĩ: Nũũ ũla ũmwĩyũmĩsya, na aiathimĩka?'),
('kam', 'JOB', 9, 5, 'Nĩwe ũla ũthamasya iĩma, na itimanya, Yĩla wing’uthũlanga ũthatunĩ wake;'),
('kam', 'JOB', 9, 6, 'Ũla ũthingithangasya nthĩ kuma vandũ vayo, Na ituĩ syayo ikĩtetema;'),
('kam', 'JOB', 9, 7, 'Ũla wĩaĩaa syũa, na yĩkĩlea kuma, Na kũvw’ĩkĩthya ndata;'),
('kam', 'JOB', 9, 8, 'Ũla e weka ũtambũũkasya matu, Na kũkinya itulumonĩ sya ũkanga;'),
('kam', 'JOB', 9, 9, 'Ũla ũseũvasya ndata syĩtawa Ayisi, na Olioni, na Kĩeemea, Na tũsũmba twa ngalĩ ya ĩtheo;'),
('kam', 'JOB', 9, 10, 'Ũla wĩkaa maũndũ manene matamanyĩka, Ĩĩ, maũndũ ma ũseng’ya matatalĩka.'),
('kam', 'JOB', 9, 11, 'Sisya, nũnũũvĩtĩla vakuvĩ nakwa, na ndimwona: O na aendeea mbee, ĩndĩ ndimũmanya.'),
('kam', 'JOB', 9, 12, 'Sisya, nũkwataa sya nzyĩma, nũũ ũtonya kũmũsiĩĩa? Nũũ wĩmwĩa, Wĩĩka ata?'),
('kam', 'JOB', 9, 13, 'Ngai ndakatũnga ũthatu wake; Ĩtheo wake atethya ma Laavi nĩmakunamaa.'),
('kam', 'JOB', 9, 14, 'Nyie nĩmũsũngĩa ata, Na kũnyuva ndeto syakwa sya kũsũanĩa nake?'),
('kam', 'JOB', 9, 15, 'Nake, o na kethĩwa nyie nĩ mũlũngalu, ndimũsũngĩa; Nĩthĩwa namwĩsũva mũsili wakwa.'),
('kam', 'JOB', 9, 16, 'Kethĩwa nĩneetanie, na ayĩthĩwa nĩwanzũngĩie, Ĩndĩ ndyĩthĩwa neetĩkĩlile kana nĩwethukĩĩsye wasya wakwa.'),
('kam', 'JOB', 9, 17, 'Nũndũ nũmbanangaa na kĩuutani, Na kwingĩvya mawũkite makwa vate kĩtumi.'),
('kam', 'JOB', 9, 18, 'Ndakandeka nĩveve, Ĩndĩ nũmbusũsya na ũũ.'),
('kam', 'JOB', 9, 19, 'Ethĩwa nĩtũwetaa vinya, sisya, nĩwe ũtonyi! Na ethĩwa nĩ ũsili wa katĩ, easya atĩĩ, Nũũ ũla wĩmbĩta silanĩ?'),
('kam', 'JOB', 9, 20, 'O na ethĩwa nĩ mũlũngalu, kanyw’a wakwa mwene ũkandw’a mũvĩtanya: O na nĩ mwĩanĩu, ũkoonan’ya nĩ na ngũlũ.'),
('kam', 'JOB', 9, 21, 'Nĩ mwĩanĩu; ndyĩsiasya mwene; Nĩngũvũthya thayũ wakwa.'),
('kam', 'JOB', 9, 22, 'No ũndũ ũmwe; kwondũ wa ũu nĩasya, We nĩwanangaa ala eanĩu na ala athũku.'),
('kam', 'JOB', 9, 23, 'Ethĩwa ũthĩn’yo nĩwũaa na kĩthũlũmũko, Akavũĩa ngũĩ kũtatwa kwa ũla ũte ĩvĩtyo.'),
('kam', 'JOB', 9, 24, 'Nthĩ nĩnenganĩtwe kw’okonĩ kwa athũku; Nũvw’ĩkaa mothyũ ma asili mayo: Ethĩwa ti we, nũũ ĩndĩ?'),
('kam', 'JOB', 9, 25, 'Ĩndĩ mĩthenya yakwa ĩ mĩtũkĩ kwĩ mũsembi: Nĩendaa, ndĩonaa ũseo.'),
('kam', 'JOB', 9, 26, 'Ĩvĩtĩte ta ngalawa ila iendaa mĩtũkĩ; Ta ndiũ ĩla ĩtheeeaa nzyĩma.'),
('kam', 'JOB', 9, 27, 'Ethĩwa nĩasya, Ngoolwa nĩ mũnyungunyĩsyo wakwa, Ngaeka kũluta ũthyũ wakwa, na ngeethĩwa na ũtanu;'),
('kam', 'JOB', 9, 28, 'Nĩngũkĩa mawoo makwa onthe, Nĩnĩsĩ ndũkasya ndi na ĩvĩtyo.'),
('kam', 'JOB', 9, 29, 'Ngatuwa mũvĩtan’ya; Nũndũ wa kĩ ĩndĩ nĩtethasya wĩa mana?'),
('kam', 'JOB', 9, 30, 'Ethĩwa ngathamba na manzĩ ma ĩa, Na kũthesya moko makwa vyũ;'),
('kam', 'JOB', 9, 31, 'Ĩndĩ ũkandikya mũtaũnĩ, Na ngũa syakwa mwene ikanthĩtha.'),
('kam', 'JOB', 9, 32, 'Nũndũ we ti mũndũ, takwa, nĩ kana nĩmũsũngĩe, Tũkomane silanĩ.'),
('kam', 'JOB', 9, 33, 'Vati mũsilan’ya katĩ waitũ, Ũla ũtonya kwilĩĩla kw’oko kwake ĩũlũ waitũ ithyelĩ.'),
('kam', 'JOB', 9, 34, 'Navete ndata yake kwakwa, Na kũtĩsya kwake kũtikandelemye:'),
('kam', 'JOB', 9, 35, 'Nĩvo ĩndĩ nĩneena, na ndikamũkĩa; Nũndũ ndiilyĩ ũu nthĩnĩ wakwa.'),
('kam', 'JOB', 10, 1, 'Ngoo yakwa nĩkolete thayũ wakwa; Nganenga mũnyungunyĩsyo wakwa ũthei vyũ; Nganeena ũũnĩ wa ngoo yakwa.'),
('kam', 'JOB', 10, 2, 'Ngamwĩa Ngai, Ndũkandw’e mũvĩtan’ya; Mbon’ya ũndũ ũtuma ũkĩlan’ya vinya nakwa.'),
('kam', 'JOB', 10, 3, 'Nĩ ũseo kwaku kũthĩn’ya, Na kũvũthya wĩa wa moko maku, Na kũkenea ũtao wa ala athũku?'),
('kam', 'JOB', 10, 4, 'Wĩ na metho ma mwĩĩ? Kana wonaa o tondũ mũndũ wonaa?'),
('kam', 'JOB', 10, 5, 'Mĩthenya yaku nĩ ta mĩthenya ya mũndũ, Kana myaka yaku ta mĩthenya ya mũndũ,'),
('kam', 'JOB', 10, 6, 'Ũndũ ũkũlanasya ũndũ wa ũthũku wakwa, Na kũthiana ũndũ wa naĩ yakwa,'),
('kam', 'JOB', 10, 7, 'O na kau nĩwĩsĩ atĩ ndi mũthũku, Na vati ũmwe ũtonya kũmbonokya kw’okonĩ kwaku?'),
('kam', 'JOB', 10, 8, 'Moko maku nĩmangwatanisye na kũmbũmba Ngalĩ syonthe vamwe; ĩndĩ nũmbanangaa.'),
('kam', 'JOB', 10, 9, 'Lilikana, nĩngũkwĩsũva, kana nũmbũmbĩte ta yũmba; Na ũkandũnga kĩtoonĩ ĩngĩ?'),
('kam', 'JOB', 10, 10, 'Ndũmbonoetye ta ĩia, Na ũkatuma nĩkama ta matulu?'),
('kam', 'JOB', 10, 11, 'Nũmbw’ĩkĩte kĩkonde na nyama, Na nũngwatanĩtye na mavĩndĩ na malangũ'),
('kam', 'JOB', 10, 12, 'Nũnengete thayũ na ũseo wĩ wendo; Na ũsyaĩĩsyo waku nũsũvĩĩte veva wakwa.'),
('kam', 'JOB', 10, 13, 'Ĩndĩ maũndũ aa nĩwamavithie ngoonĩ yaku; Nĩnĩsĩ ũu wĩ kwaku:'),
('kam', 'JOB', 10, 14, 'Ethĩwa ngũvĩtya, nĩvo ĩndĩ wĩmbĩkĩa ũvano, Na ndũkandw’a ta nde na ũndũ kwondũ wa ũthũku wakwa.'),
('kam', 'JOB', 10, 15, 'Ethĩwa nĩ mũthũku, woo nĩ wakwa; Na ethĩwa nĩ mũlũngalu, ndikokĩlya mũtwe wakwa Nusũĩtwe nĩ nthoni, Na kũsyaĩĩsya thĩna wakwa.'),
('kam', 'JOB', 10, 16, 'Na ethĩwa mũtwe wakwa nĩwĩtũlasya, we nũnzyĩmaa ta mũnyambũ; Na ĩngĩ nĩwĩyonanasya kwakwa atĩ wĩ ũseng’yo.'),
('kam', 'JOB', 10, 17, 'Nĩwongeleelaa ngũsĩ syaku ĩũlũ wakwa. Na kũmbingĩvĩsya ũthatu waku: Nguthu na nguthu syĩ ũlũ wakwa.'),
('kam', 'JOB', 10, 18, 'Nĩkĩ ĩndĩ wambumisye ĩvunĩ? Nĩthĩwa naumiwe nĩ veva, na vaiĩthĩwa itho yaambona.'),
('kam', 'JOB', 10, 19, 'Ngethĩwa ta ndyaaĩthĩwa; Ngethĩwa nakuiwe kuma ĩvunĩ kũvika mbũanĩ.'),
('kam', 'JOB', 10, 20, 'Mĩthenya yakwa ti mĩvũthũ? Eka ĩndĩ, Na ndeka, nĩ kana nikiakiĩke o vanini,'),
('kam', 'JOB', 10, 21, 'Ndanamba kũthi vala ndakasyoka kuma vo, O nthĩ ya kĩvindu na kyuu kya kĩkw’ũ;'),
('kam', 'JOB', 10, 22, 'Nthĩ yĩ kĩvindu ta ũtukũ katĩ, Nthĩ ya kyuu kya kikw’ũ, ĩte ũseũvyo wa maũndũ, Na vala kyeni nĩ ta ũtukũ katĩ.'),
('kam', 'JOB', 11, 1, 'Na ĩndĩ Nzovali Mũnaamathi asũngĩa, na asya,'),
('kam', 'JOB', 11, 2, 'Ndeto mbingĩ mũno ityaĩle kũsũngĩwa? Na mũndũ wusũĩte kũneena nĩwaĩle kũtalĩlwa ũlũngalu?'),
('kam', 'JOB', 11, 3, 'Ngathĩĩo syaku nĩsyaĩle kũtuma andũ mavindya? Na yĩla ũũkaakasya, mũndũ o na wĩva ndakakũsonokya?'),
('kam', 'JOB', 11, 4, 'Nũndũ nũkwasya, Ũmanyĩsyo wakwa nĩ mũtheu, Na nĩ mũtheu methonĩ maku.'),
('kam', 'JOB', 11, 5, 'A! Kethĩwa Ngai akaneena, Na ũkũtumũĩsya ilomo syake,'),
('kam', 'JOB', 11, 6, 'Na kũkwon’ya syĩmbithĩ sya ũĩ! Nũndũ nake e na ũmanyi mwingĩ mũno. Manya ĩndĩ kana Ngai nũkũandũa kwaku ũndũ ũnini kwĩ ũla waĩle ũthũku waku.'),
('kam', 'JOB', 11, 7, 'Nũtonya kũmũmanya Ngai kwondũ wa kũmantha? Nũtonya kũmũmanya Mwene Vinya W’onthe ki?'),
('kam', 'JOB', 11, 8, 'Wĩ ĩũlũ ta ĩtu; ũtonya kwĩka ata? Mũliku kwĩ Seoli; ũtonya kũmanya kyaũ?'),
('kam', 'JOB', 11, 9, 'Ũthimi waw’o nĩ mũasa kwĩ nthĩ, Na mũthanthau kwĩ ũkanga.'),
('kam', 'JOB', 11, 10, 'Ethĩwa nũvĩtĩlaa, na kwova, Na kwĩta ũsilĩlonĩ, nũũ indĩ ũtonya kũmũsiĩĩa?'),
('kam', 'JOB', 11, 11, 'Nũndũ nake niwisi andũ me ũvũngũ: O na nĩwonaa ũthũku, o na ethĩwa ndosũanĩa.'),
('kam', 'JOB', 11, 12, 'Ĩndĩ mũndũ ũte kĩĩĩ nde na ũmanyi, Ĩĩ, mũndũ nũsyaawa ta katena ka ĩng’oi ya kĩthekanĩ.'),
('kam', 'JOB', 11, 13, 'Ethĩwa nũlũngalasya ngoo yaku, Na kũtambũũkya moko maku mamwelekele;'),
('kam', 'JOB', 11, 14, 'Ethĩwa ũthũku wĩ kw’okonĩ kwaku, ũvete kũasa, Na ũla ũte ũlũngalu ndũkekale maeemanĩ maku.'),
('kam', 'JOB', 11, 15, 'Nĩ w’o ĩndĩ ũkookĩlya ũthyũ waku vate kalanga; Ĩĩ, ũkeethĩwa mũlũmu, na ndũkakĩa:'),
('kam', 'JOB', 11, 16, 'Nũndũ ũkoolwa nĩ thĩna waku; Ũkoolilikana ta manzĩ ala mavĩtu.'),
('kam', 'JOB', 11, 17, 'Na thayũ waku ũkeethĩwa wĩsang’ũlĩtye kwĩ mũthenya katĩ; O na ethĩwa ve kĩvindu, kĩkeethĩwa ta kĩoko.'),
('kam', 'JOB', 11, 18, 'Na ũkeethĩwa wĩyelele, nĩkwĩthĩwa kwĩ wĩkwatyo; Ĩĩ, ũkamantha vakuvĩ naku, na ũkathũmũa vate mũisyo.'),
('kam', 'JOB', 11, 19, 'O na ũkakoma, na vai ũla ũkakũtelemya; Ĩĩ, aingĩ makakwĩsũva.'),
('kam', 'JOB', 11, 20, 'Ĩndĩ metho ma athũku makaya mbindu, Na matikethĩwa na nzĩa ya kũkĩa nayo; Na wĩkwatyo woo ũkeethĩwa wa kũmwa nĩ veva.'),
('kam', 'JOB', 12, 1, 'Na ĩndĩ Yovu asũngĩa, na asya,'),
('kam', 'JOB', 12, 2, 'Vate nzika no inyw’ĩ andũ ki, Na ũĩ ũkakusanĩsya vamwe nenyu.'),
('kam', 'JOB', 12, 3, 'Ĩndĩ nĩ na ũmanyi tenyu; Ndi mũnyivu kĩlĩko kwĩ inyw’ĩ: Ĩĩ, nũũ ũtesĩ maũndũ ta asu?'),
('kam', 'JOB', 12, 4, 'Nyie nĩilyĩ ta mũndũ ũla ũthekeeawa nĩ mũtũi wake, Nyie ũla namwĩkaĩlile Ngai, na asũngĩa: Mũlũngalu, mũndũ mwĩanĩu nĩ wa kũthekeewa.'),
('kam', 'JOB', 12, 5, 'Ũsũanĩonĩ wa ũla ũthũmũĩte ve kĩvũthya ũndũ wa thĩna; Nĩkyũmbanĩte kwondũ wa ala maũũ moo matendelũka.'),
('kam', 'JOB', 12, 6, 'Maeema ma avutani nĩmaunĩka, Na ala mathatasya Ngai nĩmeyelele; Mokonĩ moo Ngai nũnenganae na wingĩ.'),
('kam', 'JOB', 12, 7, 'Ĩndĩ yu kũlya nyamũ, na ikakũmanyĩsya; Na nyũnyi sya yayaya, na ikakũtavya:'),
('kam', 'JOB', 12, 8, 'Kana neena na nthĩ, na ĩkakũmanyĩsya; Na makũyũ ma ũkanganĩ makakũtavya.'),
('kam', 'JOB', 12, 9, 'Nũũ ũla ũtesĩ kwondũ wa isu syonthe, Kana kw’oko kwa Yeova nĩkwĩkĩte ũu,'),
('kam', 'JOB', 12, 10, 'Na thayũ wa kĩla kĩndũ kĩ thayũ wĩ kw’okonĩ kwake, Na mĩthũmũ ya mbaa andũ onthe?'),
('kam', 'JOB', 12, 11, 'Kũtũ kũtitataa ndeto, O tondũ kaakaa ũsamaa lĩu waw’o?'),
('kam', 'JOB', 12, 12, 'Ũĩ wĩ kwa andũ akũũ, Na ũmanyi mĩthenyanĩ mingĩ.'),
('kam', 'JOB', 12, 13, 'Ũĩ na ũtonyi syĩ na Ngai; E na ũtao na ũmanyi.'),
('kam', 'JOB', 12, 14, 'Sisya, nũomboaa, na kũitonyeka kwakwa ĩngĩ; Nũvingĩaa mũndũ na kũivingũĩka.'),
('kam', 'JOB', 12, 15, 'Sisya, nũsiĩĩaa manzĩ, na nĩmang’alaa; Ĩngĩ, nũmalekasya, na nĩmakulumanasya nthĩ.'),
('kam', 'JOB', 12, 16, 'Vinya na ũĩ syĩ nake; Mũkengwa na mũkengani nĩ make.'),
('kam', 'JOB', 12, 17, 'Nũtongoeasya atai mathi me mavũla, Na nũtw’ĩkĩthasya asili ndia.'),
('kam', 'JOB', 12, 18, 'Nũthaasya syĩndũ syovete asumbĩ, Na kũmavotoa inyunyu syoo mĩsivi.'),
('kam', 'JOB', 12, 19, 'Nũtongoeasya athembi mathi me mavũla; Na kwananga ala me na ũtonyi.'),
('kam', 'JOB', 12, 20, 'Nũvetaa ndeto sya ala maĩkĩĩawa, Na kũveta ũmanyi wa ala akũu.'),
('kam', 'JOB', 12, 21, 'Nĩwonoasya kũvũthya ĩũlũ wa anene me mbee ũsumbĩnĩ, Na kũleelya mũsivi wa ala me na vinya.'),
('kam', 'JOB', 12, 22, 'Nĩwumĩlasya maũndũ maliku kuma kĩvindunĩ, Na kũete kyuu kya kĩkw’ũ kyeninĩ.'),
('kam', 'JOB', 12, 23, 'Nĩwingĩvasya mbaĩ, na nũsyanangaa: Nũnenevasya mbaĩ, na nĩwitwaa syĩ ndave.'),
('kam', 'JOB', 12, 24, 'Nũvetaa ũmanyi anenenĩ ma andũ ma nthĩ, Na nũtumaa manganga weũnĩ vala vate nzĩa.'),
('kam', 'JOB', 12, 25, 'Nĩmavavataa kĩvindũnĩ vate kyeni; Na kũtuma malũalũa ta mũthengi.'),
('kam', 'JOB', 13, 1, 'Sisya, itho yakwa nĩyonete ũu w’onthe, Kũtũ kwakwa nĩkũwĩw’ĩte na kũkomanya.'),
('kam', 'JOB', 13, 2, 'O ũndũ inyw’ĩ mwĩsĩ, now’o nakwa nĩsĩ: Ndi mũnyivu kĩlĩko kwĩ inyw’ĩ.'),
('kam', 'JOB', 13, 3, 'Nĩw’o nenda kũneena na Mwene Vinya W’onthe, Na nĩngwenda kũsũanĩa na Ngai.'),
('kam', 'JOB', 13, 4, 'Ĩndĩ inyw’ĩ mwĩ atili ma movũngũ; Inyw’onthe mwĩ aiiti mate vata.'),
('kam', 'JOB', 13, 5, 'A! Kethĩwa inyw’ĩ mũkavindya ki! Ũu nĩw’o wĩthĩwa ũĩ wenyu.'),
('kam', 'JOB', 13, 6, 'Ĩw’ai yu ũndũ nĩsũanĩĩte, Na ĩthukĩĩsyei mawĩsũvano ma ilomo syaka.'),
('kam', 'JOB', 13, 7, 'Mũkaneena ũndũ ũte ũlũngalu kwondũ wa Ngai, Na kũneena ũkengani kwondũ wake?'),
('kam', 'JOB', 13, 8, 'Mũkamwendeesya? Mũkateta kwondũ wa Ngai?'),
('kam', 'JOB', 13, 9, 'Nĩ ũseo akakwĩkuũa? Kana o tondũ mũndũ ũkengaa mũndũ, mũkamũkenga?'),
('kam', 'JOB', 13, 10, 'Nde ndĩi ya ũmũkan’ya, Ethĩwa mwonanasya wendeesyo na kĩmbithĩ.'),
('kam', 'JOB', 13, 11, 'Ũnene wake ndũkamũtelemya, Na ũtĩsyo wake kũmũvalũkĩla?'),
('kam', 'JOB', 13, 12, 'Mĩneeno yenyu ya ũlilikan’yo nĩ nthimo sya mũu, Maũvai menyu nĩ maũvai ma yũmba.'),
('kam', 'JOB', 13, 13, 'Vindyai, ndekai, nĩ kana nĩneene; O ũla wĩmbũkĩa nĩwũke.'),
('kam', 'JOB', 13, 14, 'Nĩkĩ ngaũma nyama ya mwĩĩ wakwa, na maeo makwa, Na kwia thayũ wakwa kw’okonĩ kwakwa?'),
('kam', 'JOB', 13, 15, 'Sisya, akambũaa; ndi na wĩkwatyo: Ĩndĩ o na ũu w’onthe ngaĩkĩĩthya mĩendele yakwa mbee wake.'),
('kam', 'JOB', 13, 16, 'Na ũũ naw’o ũkeethĩwa ũtangĩĩo wakwa, Atĩ mũndũ ũtakĩaa Ngai ndakamũthengeea.'),
('kam', 'JOB', 13, 17, 'Ĩw’ai na kĩthing’ĩĩsyo kũneena kwakwa, Na ũtavan’yo wakwa nĩwĩthĩwe matũnĩ menyu.'),
('kam', 'JOB', 13, 18, 'Sisyai yu, nĩnĩseũvĩtye ũvoo wakwa; Nĩnĩsĩ atĩ nĩ mũndũ mũlũngalu.'),
('kam', 'JOB', 13, 19, 'Nũũ ũla wĩkananĩa nakwa? Ethĩwa ngavindya ngaumwa nĩ veva.'),
('kam', 'JOB', 13, 20, 'No maũndũ elĩ ndũkambĩke; Na ĩndĩ ndikevitha ũthyũnĩ waku:'),
('kam', 'JOB', 13, 21, 'Veta kw’oko kwaku kũasa nakwa; Na ũtĩsyo waku ndũkandelemye.'),
('kam', 'JOB', 13, 22, 'Na ĩndĩ ĩtana, na ngakwĩtĩka; Kana ndeka nĩneene, naku ũinzũngĩa.'),
('kam', 'JOB', 13, 23, 'Mothũku makwa na naĩ syakwa nĩ syĩana? Tuma nĩmanya kũvĩtya kwakwa na na yakwa.'),
('kam', 'JOB', 13, 24, 'Nĩkĩ ũvithaa ũthyũ waku, Na kũndw’a ta mũmaitha waku?'),
('kam', 'JOB', 13, 25, 'Ũkathĩn’ya ĩtũ yĩũlũkangaw’a? Na ũkaatĩĩa ũa wũmũ?'),
('kam', 'JOB', 13, 26, 'Nũndũ nũandĩkaa maũndũ me ũũ ĩũlũ wakwa, Na kũndw’a mũtiĩwa wa mothũku ma wana wakwa:'),
('kam', 'JOB', 13, 27, 'Nũmbĩkĩaa maũũ makwa mĩtĩnĩ ya kũmoveea, Na nũnziasya mĩendele yakwa yonthe; Nĩwĩkĩaa mũvaka wa nyaĩĩ sya maũũ makwa:'),
('kam', 'JOB', 13, 28, 'O na kau nĩilyĩ kĩndũ kyou kĩla kĩthelaa, Ta ngũa ĩla ĩĩtwe nĩ lungulu.'),
('kam', 'JOB', 14, 1, 'Mũndũ, ũla ũsyaĩtwe nĩ mũndũ mũka, Nĩ wa mĩthenya mĩvũthũ, na ausũĩte thĩna.'),
('kam', 'JOB', 14, 2, 'Nĩwumĩlaa ta ĩlaa, na kũtilwa: Nũsembaa ta muunyĩ, na ndekalaa.'),
('kam', 'JOB', 14, 3, 'Naku wĩmũsalukĩlya metho maku ũla ũilyĩ ũu, Na kũndwaa nĩsile naku?'),
('kam', 'JOB', 14, 4, 'Nũũ ũtonya kumya kĩndũ kĩtheu nthĩnĩ wa kĩla kĩte kĩtheu? Vaiĩ ũmwe.'),
('kam', 'JOB', 14, 5, 'Nũndũ mĩthenya yake nĩtw’ĩtwe, Ũtalo wa myei yake wĩ naku, Na nũtw’ĩte mĩvaka yake ũndũ ũtatonya kũmĩkĩla;'),
('kam', 'JOB', 14, 6, 'Eka ũmũsisya, nĩ kana athũmũe, Kũvika eanĩsye mũthenya wake ta mũndũ ũtuvawa.'),
('kam', 'JOB', 14, 7, 'Nũndũ ve wĩkwatyo ũndũ wa mũtĩ, Ethĩwa ũkatemwa, ũkathongooa ĩngĩ, Na kana ĩthongooo ya ũvonge waw’o ĩtikaeka.'),
('kam', 'JOB', 14, 8, 'O na ethĩwa mũi waw’o ũkakũĩa nthĩnĩ wa nthĩ, Na kĩtina kyaw’o kĩkoomĩa mũthanganĩ;'),
('kam', 'JOB', 14, 9, 'Ĩndĩ kwondũ wa mũuke wa manzĩ ũkaete wenze, Na kũthongoosya mbonge ta mũtĩ mwĩũ.'),
('kam', 'JOB', 14, 10, 'Ĩndĩ mũndũ nũkusaa, na aianangĩka: Ĩĩ, mũndũ nĩwumawa nĩ veva, na aĩva?'),
('kam', 'JOB', 14, 11, 'O tondũ manzĩ manyivaa ũkanganĩ, Na ũsĩ nũnyivasya, na ũing’ala;'),
('kam', 'JOB', 14, 12, 'Now’o mũndũ nũkomaa na ndokĩlaa: Kũvika yĩla matu matikethĩwa vo ĩngĩ, matikaamũka, Kana kũamũkw’a kuma toonĩ woo.'),
('kam', 'JOB', 14, 13, 'A! Kethĩwa ũkambitha nthĩnĩ wa Seoli, Kethĩwa ũkanzũvĩa na kĩmbithĩ, kũvika ũthatu waku ũvĩte, Kethĩwa ũkandw’ĩĩa ĩvinda ĩtw’ĩtwe, na kũndilikana!'),
('kam', 'JOB', 14, 14, 'Ethĩwa mũndũ akakw’a, akeethĩwa thayũ ĩngĩ? Mĩthenya yonthe ya kaũ wakwa ngeteela, Kũvika ũthasyo wakwa ũvike.'),
('kam', 'JOB', 14, 15, 'Naku wĩthĩwa wĩtana, nakwa ngakwĩtĩka: Ũkeethĩwa na mea ma wĩa wa moko maku.'),
('kam', 'JOB', 14, 16, 'Ĩndĩ yu nũtalaa matambya makwa: Ndũsyaĩĩasya naĩ yakwa?'),
('kam', 'JOB', 14, 17, 'Kũvĩtya kwakwa nĩkũsiĩlĩtwe mũvukonĩ, Na nĩwovete ũthũku wakwa.'),
('kam', 'JOB', 14, 18, 'Ĩndĩ kĩĩma kĩiombokanga nĩkyanangĩkaa; Na ĩvia nĩyĩvetetwe kuma vandũ vayo;'),
('kam', 'JOB', 14, 19, 'Manzĩ nĩmathĩĩvaa mavia; Kũkĩla kwamo nĩkũkuaa kĩtoo kya nthĩ: O ta ũu naku nĩwanangaa wĩkwatyo wa mũndũ.'),
('kam', 'JOB', 14, 20, 'Nũmũkĩlasya vinya tene na tene, nake nũvĩtaa; Naku nũalyũlaa ũthyũ wake, na kũmwĩa athi.'),
('kam', 'JOB', 14, 21, 'Ana make nĩmavikĩaa ndaĩa, nake ndesĩ: Na nĩmatheeaw’a nthĩ, ĩndĩ ndamanyaa ũndũ woo.'),
('kam', 'JOB', 14, 22, 'Ĩndĩ mwĩĩ wake nĩwalasya, Na ngoo yake nĩmeteaa nthĩnĩ wake.'),
('kam', 'JOB', 15, 1, 'Na ĩndĩ Elivasi Mũtemani asũngĩa, na asya,'),
('kam', 'JOB', 15, 2, 'Mũndũ mũĩ nĩwaĩle kũsũngĩa na ũmanyi wa mana, Na kwĩyusũsya kĩseve kyumĩte wumĩlonĩ wa syũa?'),
('kam', 'JOB', 15, 3, 'Nĩwaĩle kũneenan’ya na ndeto itauna, Kana moneeni ala ũtatonya kwĩka namo?'),
('kam', 'JOB', 15, 4, 'Ĩĩ, nũvetaa w’ĩa, Na kũsiĩĩa ũthaithi mbee wa Ngai.'),
('kam', 'JOB', 15, 5, 'Nũndũ ũthũku waku nũmanyĩasya kanyw’a waku, Na nũnyuvaa ũĩmĩ wa nzeleke.'),
('kam', 'JOB', 15, 6, 'Kanyw’a waku mwene nũkũtusaa mũvĩtan’ya, na ti i nyie: Ĩĩ, ilomo syaku mwene, nikũkũsĩĩaa.'),
('kam', 'JOB', 15, 7, 'Nue mũndũ wa mbee wa kũsyawa? Kana wasyaiwe tene kwĩ iĩma?'),
('kam', 'JOB', 15, 8, 'Nĩwĩw’ĩte ũtao wa kĩmbithĩ wa Ngai? Na kũkũsiĩĩa ũĩ wĩthĩwe waku wĩ weka?'),
('kam', 'JOB', 15, 9, 'Wĩsĩ ũndũ wĩva, ũla tũtesĩ? Ũmanya ũndũ wĩva, ũla ũte nthĩnĩ waitũ?'),
('kam', 'JOB', 15, 10, 'Ala me mbuĩ na atumĩa akũu mũno onthe me vamwe naitũ, Akũũ mũno kwĩ au.'),
('kam', 'JOB', 15, 11, 'Mokiakisyo ma Ngai nĩ manini kwaku, O ndeto ĩla ya ũuu kwaku?'),
('kam', 'JOB', 15, 12, 'Nĩkĩ ngoo yaku ĩkũtwaaa kũasa? Na nĩkĩ metho maku mekũvenaven’ya na ngathĩĩo,'),
('kam', 'JOB', 15, 13, 'Ũndũ ũkũthyũũa veva waku ũkite na Ngai, Na kũvulũkya ndeto kuma kanyw’anĩ waku?'),
('kam', 'JOB', 15, 14, 'Mũndũ nĩ mwaũ, kana ethĩwe mũtheu? Na ũla ũsyaĩtwe nĩ mũndũ mũka, kana ethĩwe mũlũngalu?'),
('kam', 'JOB', 15, 15, 'Sisya, ndaĩkĩĩaa ala make atheu; Ĩĩ, matu ti matheu methonĩ make:'),
('kam', 'JOB', 15, 16, 'Avukĩte ata ũla ũthatasya na nĩ mũvuku, Mũndũ ũla ũnyusaa ũthũku ta manzĩ!'),
('kam', 'JOB', 15, 17, 'Ngakwon’ya, mbĩthukĩĩsya; Na ũndũ ũla nonete nĩw’o ngatavan’ya'),
('kam', 'JOB', 15, 18, '(Ũndũ ũla andũ oi matavanĩtye Kuma kwa aaĩthe moo, na matyaovitha;'),
('kam', 'JOB', 15, 19, 'Ala manengiwe ĩ nthĩ me oka, Na vati mũeni waavĩtĩla katĩ woo):'),
('kam', 'JOB', 15, 20, 'Mũndũ mũthũku nĩwaũnyaw’a nĩ woo mĩthenya yake yonthe, O ũtalo wa myaka ĩla yiĩtwe kwondũ wa mũthĩn’ya.'),
('kam', 'JOB', 15, 21, 'Kĩlonzo kya motĩsyo kĩ matũnĩ make; Ũunĩkonĩ mwanangi akamũkĩa.'),
('kam', 'JOB', 15, 22, 'Ndekwĩtĩkĩla atĩ akasyoka kuma kĩvindunĩ, Na nĩweteelawa nĩ ũvyũ.'),
('kam', 'JOB', 15, 23, 'Nĩwangangaa kũasa aimantha lĩu, akyasya, Ũĩva? Nĩwĩsĩ kana mũthenya wa kĩvindu nĩwũmbanĩtw’e kw’okonĩ kwake.'),
('kam', 'JOB', 15, 24, 'Ũnyamao na woo mwingĩ niũmũtelemya; Nimũkĩlasya vinya, ta mũsumbĩ wĩyũmbanĩtye kũkita.'),
('kam', 'JOB', 15, 25, 'Nĩkwĩthĩwa nũmũtambũũkĩĩtye Ngai kw’oko kwake, Na kũmwĩkaa Mwene Vinya W’onthe na ngathĩĩo;'),
('kam', 'JOB', 15, 26, 'Nũsembaa vala ũĩ na ngingo nyũmũ, E na tũkalo twĩ na tũlũta twa kĩaa;'),
('kam', 'JOB', 15, 27, 'Nĩkwĩthĩwa nũvw’ĩkĩte ũthyũ wake na ũnou wake, Na kũmbanĩsya mathunya kĩnyunyunĩ kyake;'),
('kam', 'JOB', 15, 28, 'Na nĩwekalĩte ndũanĩ nthei, Nyũmbanĩ ila mũndũ o na wĩva ũtaitũa, Ila syakilĩlye kũtw’ĩka ivumbu;'),
('kam', 'JOB', 15, 29, 'Ndakethĩwa mũthwii, o na syĩndũ syake itikekalaa, O na mothwii moo matikaingĩvw’a ĩũlũ wa nthĩ.'),
('kam', 'JOB', 15, 30, 'Ndakauma kĩvindunĩ; Ũmũĩ ũkoomya mbonge syake, Na kwondũ wa mĩthũmũ ya kanyw’a wa Ngai akathi vyũ.'),
('kam', 'JOB', 15, 31, 'Ndakaĩkĩĩe vathei, ayĩkenga mwene; Nũndũ ĩtuvi yake yĩkeethĩwa vathei.'),
('kam', 'JOB', 15, 32, 'Ũu ũkeanĩwa mbee wa ĩvinda yake, Na ũvonge waku ndũkethĩwa mwĩũ.'),
('kam', 'JOB', 15, 33, 'Akathingithya etĩkye nzavivũ syake ite mbĩu ta mũsavivũ, Na kwĩtĩkya malaa make ta mũtĩ wa mũthata.'),
('kam', 'JOB', 15, 34, 'Nũndũ nguthu ya ala matakĩaa Ngai ndĩkethĩwa na ũsyao, Na mwaki ũkamina maeema ma vala vaumaw’a mavaki.'),
('kam', 'JOB', 15, 35, 'Nĩmaitavaa ũthũku, na kũsyaa naĩ, Na ngoo syoo iseũvasya ũkengani.'),
('kam', 'JOB', 16, 1, 'Na ĩndĩ Yovu asũngĩa na asya,'),
('kam', 'JOB', 16, 2, 'Nĩnĩw’ĩte maũndũ maingĩ ta asu: Inyw’onthe mwĩ akiakisya ma kũthĩn’ya.'),
('kam', 'JOB', 16, 3, 'Ndeto sya mana ikeethĩwa na mũminũkĩlyo? Kana nĩ kyaũ kĩla kĩkũthatasya ũsũngie?'),
('kam', 'JOB', 16, 4, 'O nakwa nĩndonya kũneena tenyu; Kethĩwa thayũ wenyu wĩ vandũ va thayũ wakwa, Nĩthĩwa ndonya kũmban’ya ndeto ĩũlũ wenyu, Na kũmũthingithĩsya mũtwe wakwa.'),
('kam', 'JOB', 16, 5, 'Ĩndĩ nĩthĩwa ngĩmwĩkĩa vinya na kanyw’a wakwa, Na ũkiakisyo wa ilomo syakwa wĩthĩwa ũkĩnyivya woo wenyu.'),
('kam', 'JOB', 16, 6, 'O na kau nĩngũneena, woo wakwa ndũnyivaa; O na ngavindya, nĩolekelwa nĩ ũndũ mwaũ?'),
('kam', 'JOB', 16, 7, 'Ĩndĩ yu nũnoetye: Nĩwanangĩte nguthu yakwa yonthe.'),
('kam', 'JOB', 16, 8, 'Naku nũngwete mũno, na ũũ nĩ ũkũsĩ ĩũlũ wakwa: Na ũmosu wakwa nũmbũkĩlĩle, Naw’o nũkũngũsĩĩa ũthyũnĩ wakwa.'),
('kam', 'JOB', 16, 9, 'Nũndembũangĩte ũthatunĩ wake, na kũnthĩn’ya; Nũmbevetanĩsye maeo make: Nthũ yakwa nĩkũngũnũĩa metho mayo mai.'),
('kam', 'JOB', 16, 10, 'Nĩmambathamĩsye kanyw’a woo; Nĩmangũnĩte ĩtau na kĩvũthya: Nĩmembũmbanĩsye.'),
('kam', 'JOB', 16, 11, 'Ngai nũnenganĩte nyie kwa ala matakĩaa Ngai, Na kũmbĩkya mokonĩ ma ala athũku.'),
('kam', 'JOB', 16, 12, 'Nĩneethũmũĩtye na andilan’ya; Ĩĩ, nũngwatĩte ĩkoti, na kũng’atangan’ya nĩthĩwe ilungu: O na nũmbũkĩlĩtye nĩthĩwe ũvano wake wa kũatha.'),
('kam', 'JOB', 16, 13, 'Andũ make ma mata nĩmanthyũlũlũkaa; Nĩwatũaa kĩnyunyu kyakwa, na ndew’ĩaa tei; Nĩwĩtaa nyongo yakwa nthĩ.'),
('kam', 'JOB', 16, 14, 'Nũmbanangaa na wanangĩko ĩũlũ wa wanangĩko; Nũmbithũkĩaa ta ngũmbaũ.'),
('kam', 'JOB', 16, 15, 'Nĩndumĩte makunĩa makwete kĩkonde kyakwa, Na nĩniĩte ũvya wakwa kĩtoonĩ.'),
('kam', 'JOB', 16, 16, 'Ũthyũ wakwa nĩ mũtune kwondũ wa kũĩa, Na ilomonĩ sya metho makwa ve kyuu kya kĩkw’ũ;'),
('kam', 'JOB', 16, 17, 'O na kau vati ũng’endu mokonĩ makwa, Na mboya yakwa nĩ ntheu.'),
('kam', 'JOB', 16, 18, 'We nthĩ, ndũkavw’ĩke nthakame yakwa, Na kũĩa kwakwa kũikethĩwe na vandũ va ũthũmũo.'),
('kam', 'JOB', 16, 19, 'O na yu, sisya, ngũsĩ yakwa yĩ ĩtunĩ, Na ũla ũngũsĩĩaa e ĩũlũ.'),
('kam', 'JOB', 16, 20, 'Anyanyawa nĩmambũthasya: Ĩndĩ itho yakwa nĩyĩmwĩtĩkĩĩasya Ngai methoi,'),
('kam', 'JOB', 16, 21, 'Kana alũlũmĩlye kĩanda ĩ kya mũndũ mbee wa Ngai, Na kya mwana wa mũndũ mbee wa mũtũi wake!'),
('kam', 'JOB', 16, 22, 'Nũndũ myaka mĩvũthũ yavĩta, Ngathi na nzĩa ĩla ndakamĩsyokela ĩngĩ.'),
('kam', 'JOB', 17, 1, 'Veva wakwa nũminĩtwe, mĩthenya yakwa nĩthelete, Mbũa nĩĩyũmbanĩtye kwondũ wakwa.'),
('kam', 'JOB', 17, 2, 'Vate ndĩi kwĩ akaakaan’ya vala nĩĩ, Na itho yakwa nĩyĩsiasya ũthatyo woo.'),
('kam', 'JOB', 17, 3, 'Yu nengane ngwatĩlĩlyo, ĩthĩwa mũĩkĩĩwa kwakwa naku; Nũũ ũla wĩkwatana kw’oko nakwa?'),
('kam', 'JOB', 17, 4, 'Nũndũ nũvithĩte ngoo syoo itikamanye: Kwondũ wa ũu ndũkamanenevya.'),
('kam', 'JOB', 17, 5, 'Ũla ũnenganae anyanyae methĩwe mũtavo, O na metho ma syana syake makasekeea.'),
('kam', 'JOB', 17, 6, 'Ĩndĩ nũndw’ĩkĩthĩtye wa kũvũthw’a nĩ andũ; Nao nĩmandwĩlaa mata ũthyũnĩ.'),
('kam', 'JOB', 17, 7, 'Itho yakwa nayo yĩ na mbindu nũndũ wa woo, Na mamutha makwa onthe nĩ ta kyuu.'),
('kam', 'JOB', 17, 8, 'Andũ alũngalu makaseng’w’a nĩ ũu. Na ũla ũte ĩvĩtyo akeethũlũmũĩla ũla ũtakĩaa Ngai.'),
('kam', 'JOB', 17, 9, 'Ĩndĩ ũla mũlũngalu akalũmya nzĩa yake, Na ũla wĩ na moko matheu akongeleela vinya mbee na mbee.'),
('kam', 'JOB', 17, 10, 'Ĩndĩ ũndũ wenyu inyw’onthe, syokai; Na ndikona mũndũ mũĩ katĩ wenyu.'),
('kam', 'JOB', 17, 11, 'Mĩthenya yakwa nĩ mĩvĩtu, mosũanĩo makwa nĩ matile, O mosũanĩo ma ngoo yakwa.'),
('kam', 'JOB', 17, 12, 'Nĩmalyũlaa ũtukũ wĩthĩwe mũthenya: Nĩmekwasya, Kyeni kĩ vakuvĩ na kĩvindu.'),
('kam', 'JOB', 17, 13, 'Ethĩwa nĩeteela Seoli vethĩwe nyũmba yakwa; Ethĩwa nalanĩtye ũkomo wakwa kĩvindunĩ;'),
('kam', 'JOB', 17, 14, 'Ethĩwa nĩtavĩtye wanangĩko, Nue nau; Na kĩinyu, Nue mwaitũ na mwĩĩtu‐a‐ia;'),
('kam', 'JOB', 17, 15, 'Wĩkwatyo wakwa ũĩva ĩndĩ? Na ũndũ wa wĩkwatyo wakwa, nũũ ũla wĩwona?'),
('kam', 'JOB', 17, 16, 'Ũkatheea kũvika ivingonĩ sya Seoli, O yĩla kũkethĩwa ũthũmũo kĩtoonĩ.'),
('kam', 'JOB', 18, 1, 'Nĩvo ĩndĩ Mbilitati Mũsui wasũngĩie, na asya,'),
('kam', 'JOB', 18, 2, 'Mũkamantha ndeto kũvika ĩndĩĩ? Sũanĩai, na ĩtina tũkaneena.'),
('kam', 'JOB', 18, 3, 'Nũndũ wa kĩ tũtalawa ta nyamũ Na kũtw’ĩka avuku mũsyaĩtye?'),
('kam', 'JOB', 18, 4, 'We ũla ũĩtembũanga ũthatunĩ waku, Nthĩ ĩkaekwa kwondũ waku? Kana ĩvia yĩkathamw’a kuma vandũ vayo?'),
('kam', 'JOB', 18, 5, 'Ĩĩ, kyeni kya ala athũku kĩkavow’a, Na ngala ya mwaki wake ndĩkakena.'),
('kam', 'JOB', 18, 6, 'Kyeni kĩkeethĩwa kĩvindu ĩeemanĩ yake, Na taa wake ĩũlũ wake ũkavow’a.'),
('kam', 'JOB', 18, 7, 'Matambya ma vinya wake makavivinyawa, Na ũtao wake mwene ũkamwĩkya nthĩ.'),
('kam', 'JOB', 18, 8, 'Nũndũ nĩwĩkĩtw’e kĩteinĩ nĩ maũũ make mwene, Na nũkinyaa ĩũlũ wa itei.'),
('kam', 'JOB', 18, 9, 'Kĩloo kĩkamũkwatya kĩtiinyo, Na mũteo ũkamũlũmya.'),
('kam', 'JOB', 18, 10, 'Mũkwa nũvithĩtwe nthĩ kwondũ wake, Na kĩtei kwondũ wake nzĩanĩ.'),
('kam', 'JOB', 18, 11, 'Motĩsyo makamũtelemya kĩla ngalĩko, Na makamũatĩĩa itiinyonĩ syake.'),
('kam', 'JOB', 18, 12, 'Vinya wake ũkaũmwa nĩ nzaa, Na wanangĩko mũnene ũkeethĩwa wũmbanĩtw’e ũtee wake.'),
('kam', 'JOB', 18, 13, 'Mamutha ma mwĩĩ wake makaanangwa, Ĩĩ, mũsyawa wa mbee wa kĩkw’ũ akamina mamutha make.'),
('kam', 'JOB', 18, 14, 'Akaumw’a ĩeemanĩ yake yĩla ũĩkĩĩaa; Na akatwawa vala ve mũsumbĩ wa motĩsyo.'),
('kam', 'JOB', 18, 15, 'Kĩla kĩte kyake kĩkekalaa ĩeemanĩ yake: Mũvĩlĩtĩ ũkanyaĩĩkw’a ũtũonĩ wake.'),
('kam', 'JOB', 18, 16, 'Mĩi yake ĩkoomĩla ĩtheo, Na ĩũlũ ũvonge wake ũkatilwa.'),
('kam', 'JOB', 18, 17, 'Ũlililan’yo wake ũkaaa nthĩ, Na ndakethĩwa na syĩtwa nzĩanĩ nene.'),
('kam', 'JOB', 18, 18, 'Akalũngw’a kuma kyeninĩ kũvika kĩvindunĩ, Na kũlũngw’a kuma ĩũlũ wa nthĩ.'),
('kam', 'JOB', 18, 19, 'Ndakethĩwa na mwana kana nzũkũlũ katĩ wa andũ make, Kana ũmwe ũtĩala vala wekalĩte ũeni.'),
('kam', 'JOB', 18, 20, 'Ala makoka ĩtina makaseng’w’a nĩ mũthenya wake, O tondũ ala maendie mbee matelemilw’e.'),
('kam', 'JOB', 18, 21, 'Nĩ w’o motũo ma ala matakĩaa Ngai mailyĩ, Na vau nĩvo vandũ va ũla ũtamanyaa Ngai.'),
('kam', 'JOB', 19, 1, 'Na ĩndĩ Yovu asũngĩa na asya,'),
('kam', 'JOB', 19, 2, 'Mũkathatya ngoo yakwa kũvika ĩndĩĩ, Na kũndilanga ilungu na ndeto?'),
('kam', 'JOB', 19, 3, 'Mavinda aa ĩkũmi nĩmũmbũthĩtye: Mũtisonokaa ũndũ wa kũnthĩn’ya na vinya.'),
('kam', 'JOB', 19, 4, 'O na ethĩwa nĩ w’o nĩnĩvĩtĩtye, Ĩvĩtyo yakwa nĩyĩkalaa nakwa mwene.'),
('kam', 'JOB', 19, 5, 'Ethĩwa nĩ w’o mũkeenenevya ĩũlũ wakwa, Na kũete ĩũlũ wakwa kũvũthw’a kwakwa;'),
('kam', 'JOB', 19, 6, 'Manyai yu kana Ngai nũngĩlĩtye vinya ũvoonĩ wakwa, Na nũnthyũlũlũkĩtye kĩtei kyake.'),
('kam', 'JOB', 19, 7, 'Sisya, nĩngũkaya ũndũ wa kũthĩnw’a, ĩndĩ ndikwĩw’ĩka: Nĩngwĩtya ũtethyo, ĩndĩ vati ũsili wa katĩ.'),
('kam', 'JOB', 19, 8, 'Nĩwiiĩte nzĩa yakwa ũndũ ndatonya kũvita, Na kwia kĩvindu nzĩanĩ syakwa.'),
('kam', 'JOB', 19, 9, 'Nũmbenete ndaĩa yakwa, Na kumya ngovia ya ũsumbĩ mũtwenĩ wakwa.'),
('kam', 'JOB', 19, 10, 'Nũnomboangĩte kĩla ngalĩko, na nĩ mũthelu; Na wĩkwatyo wakwa we nũkũĩte ta mũtĩ.'),
('kam', 'JOB', 19, 11, 'Nũmbakanĩsye ũthilĩku wake, Na nũndalaa kwake ta ũmwe wa nthũ syake.'),
('kam', 'JOB', 19, 12, 'Nguthu syake nĩsyũkaa vamwe, Na kwĩnza nzĩa syoo inziĩĩe, Na kwaka maeema kũthyũlũlũka ĩeema yakwa.'),
('kam', 'JOB', 19, 13, 'Nĩwĩkĩtye ana‐a‐asa makwa kũasa nakwa, Na ala nĩsene nao nĩmataanĩĩtye nakwa vyũ.'),
('kam', 'JOB', 19, 14, 'Andũ makwa nĩ athelu, Na anyanyawa ala nĩsene nao nĩmolĩtwe ninyie.'),
('kam', 'JOB', 19, 15, 'Ala mekalaa nyũmbanĩ yakwa, na athũkũmi makwa eĩtu mandalaa nĩ mũeni: Nyie nĩ mũndũ wa nthĩ ĩngĩ methonĩ moo.'),
('kam', 'JOB', 19, 16, 'Nĩngũmwĩta mũthũkũmi wakwa na ndambĩtĩka, O na kau nĩmwĩsũva na kanyw’a wakwa.'),
('kam', 'JOB', 19, 17, 'Mĩthũmũ yakwa nĩ mĩeni kwa kĩveti kyakwa, Na wĩsũvano wakwa nĩ mũeni kwa syana sya mwaitũ.'),
('kam', 'JOB', 19, 18, 'O na syana nini nimbũthasya; Ethĩwa nĩngũkĩla, niũneena ĩũlũ wakwa.'),
('kam', 'JOB', 19, 19, 'Anyanyawa onthe ala twĩsene nĩmanthĩthaa, Na ala namendaa nĩmangalyũkĩle.'),
('kam', 'JOB', 19, 20, 'Ĩvĩndĩ yakwa nĩyĩlũmanĩtye na kĩkonde kyakwa na nyama syakwa, No kĩni kya maeo makwa mbonokete nakyo.'),
('kam', 'JOB', 19, 21, 'Mbĩw’ĩai tei, mbĩw’ĩai tei, inyw’ĩ anyanyawa; Nũndũ kw’oko kwa Ngai nĩkũngiitĩte.'),
('kam', 'JOB', 19, 22, 'Nĩkĩ mũũnthĩn’ya o ta Ngai, Na mũtikwĩanĩwa nĩ nyama sya mwĩĩ wakwa!'),
('kam', 'JOB', 19, 23, 'A! Kethĩwa ndeto syakwa nĩ nandĩke yu! A! Kethĩwa nĩ nandĩke ĩvukunĩ!'),
('kam', 'JOB', 19, 24, 'Kethĩwa nivanĩĩwa ĩvianĩ tene na tene, Na kĩandĩki kya kĩaa na ĩvulũ!'),
('kam', 'JOB', 19, 25, 'Ĩndĩ ngalĩ ĩ yakwa nĩnĩsĩ Mwovosya wakwa e thayũ, Na mũminũkĩlyo akaũngama ĩũlũ wa nthĩ:'),
('kam', 'JOB', 19, 26, 'Na ĩtina wa kwanangĩka kwa kĩkonde kyakwa, o mwĩĩ ũũ, Ngamwona Ngai nĩ na mwĩĩ wakwa;'),
('kam', 'JOB', 19, 27, 'Ũla nyie, o nyie, nĩmwona, nyie mwene, Na metho makwa makoona, na ti ta mũeni. Ngoo yakwa nĩyathela nthĩnĩ wakwa.'),
('kam', 'JOB', 19, 28, 'Ethĩwa mwĩasya, A! Ũndũ tĩmũthĩn’ya! Na kĩtina kya ũndũ ũũ nĩ kyoneku nthĩnĩ wakwa;'),
('kam', 'JOB', 19, 29, 'Kĩai ũvyũ: Nũndũ ũthilĩku nũetae mosilĩlo ma ũvyũ, Nĩ kana mũmanye atĩ ve ũsilĩlo.'),
('kam', 'JOB', 20, 1, 'Na ĩndĩ Nzovali Mũnaamathi asũngĩa, na asya,'),
('kam', 'JOB', 20, 2, 'Kwondũ wa ũu mosũanĩo makwa nĩmeũnzũngĩa, O kwondũ wa mĩtũkĩ yakwa ĩla yĩ nthĩnĩ wakwa.'),
('kam', 'JOB', 20, 3, 'Nĩnĩw’ĩte ũkan’yo ũla ũnzonokasya; Na veva wa ũmanyi wakwa nũũnzũngĩa.'),
('kam', 'JOB', 20, 4, 'Ndũũmanya ũu kuma tene, Kuma mũndũ aiwa nthĩ,'),
('kam', 'JOB', 20, 5, 'Kana kũkĩlya vinya kwa ala athũku nĩ kwa ĩvinda ĩkuvĩ, Na ũtanu wa ala matakĩaa Ngai no wa kavinda kanini mũno?'),
('kam', 'JOB', 20, 6, 'O na ethĩwa ũasa wake ũkambata kũvika matunĩ, Na mũtwe wake ũkavika mathweonĩ;'),
('kam', 'JOB', 20, 7, 'Ĩndĩ akaaa tene na tene ta mai make mwene: Ala mamwonete makasya, Aĩva?'),
('kam', 'JOB', 20, 8, 'Akaũlũka ta ndoto, na ndakoneka: Ĩĩ, akalũngw’a ta woni wa ũtukũ'),
('kam', 'JOB', 20, 9, 'Itho yĩla yamwonie yĩtikamwona ĩngĩ; O na vandũ vake vatikamwona ĩngĩ.'),
('kam', 'JOB', 20, 10, 'Syana syake ikamantha ũseo kwa ngya, Na moko make makatũnga ũthwii wake.'),
('kam', 'JOB', 20, 11, 'Mavĩndĩ make nĩmausũĩte wana wake, Ĩndĩ ũkakoma nake kĩtoonĩ.'),
('kam', 'JOB', 20, 12, 'O na kau ũthũku wĩ mũyo kanyw’anĩ wake, O na nũvithaa ungu wa ũĩmĩ wake,'),
('kam', 'JOB', 20, 13, 'O na nũwĩw’ĩaa tei, na nũleaa kũlekya, Ĩndĩ no kũwĩkalya kanyw’anĩ wake;'),
('kam', 'JOB', 20, 14, 'Ĩndĩ lĩu wake nũalyũkĩle maanĩ make, Nĩ nyongo ya syĩko nthĩnĩ wake.'),
('kam', 'JOB', 20, 15, 'Nũmeletye ũthwii, na akootavĩka ĩngĩ; Ngai akawumya ĩvunĩ yake.'),
('kam', 'JOB', 20, 16, 'Akoonga ũoi wa syĩko: Ũĩmĩ wa nzoka mbai ũkamũaa.'),
('kam', 'JOB', 20, 17, 'Ndakasiasya mbũsĩ, Tũlũsĩ tũvĩtĩte twa ũkĩ wa nzũkĩ na mauta.'),
('kam', 'JOB', 20, 18, 'Kĩla wenoesya akatũnga, na ndakakĩmelya; Kwĩanana na ũthwii ũla wũmbanĩtye, ndakatana.'),
('kam', 'JOB', 20, 19, 'Nũndũ nũthĩnĩtye ngya na kwitia; Nũomboete nyũmba na vinya, na ndakamĩtũngĩĩa.'),
('kam', 'JOB', 20, 20, 'Nĩkwĩthĩwa ndaamanya ũuu nthĩnĩ wake, Ndakatangĩĩa kĩndũ o na kĩva kĩla ũtanĩaa.'),
('kam', 'JOB', 20, 21, 'Kũtyaĩ kĩndũ kĩtiele kĩla ũtaakĩmina; Kwondũ wa ũu ũunĩko wake ndũkekala.'),
('kam', 'JOB', 20, 22, 'Wusũunĩ wa wĩanĩu wake akeethĩwa mũvivinye: Kw’oko kwa kĩla mũndũ ũla wĩ thĩanĩ kũkooka ĩũlũ wake.'),
('kam', 'JOB', 20, 23, 'Yĩla ũkilĩlye kusũsya ĩvu yake, Ngai akekya wai wa ũthilĩku wake ĩũlũ wake, Na akoonosya ĩũlũ wake o yĩla wĩĩthĩwa akĩya.'),
('kam', 'JOB', 20, 24, 'Akakĩĩa mĩio ya kaũ ya iaa, Na ũta wa ũthuku ũkamũtonya mũkuthũ.'),
('kam', 'JOB', 20, 25, 'Nũkusasya, na nũkuma mwĩĩnĩ wake; Ĩĩ, mũthya mũtisu kuma nyongonĩ yake: Motĩsyo me ĩũlũ wake.'),
('kam', 'JOB', 20, 26, 'Kĩvindu kyonthe nĩkiĩtwe kwondũ wa mothwii make: Mwaki ũtakanĩtw’e nĩ mũndũ ũkamũmina; Ũkamina kĩla kĩtiele ĩeemanĩ yake.'),
('kam', 'JOB', 20, 27, 'Matu makoonan’ya ũthũku wake, Na nthĩ ĩkamũkĩlĩla.'),
('kam', 'JOB', 20, 28, 'Wingĩvo wa nyũmba yake ũkaenda; Ũthwii wake ũkaenda ũvĩtĩte mũthenya wa ũthilĩku wake.'),
('kam', 'JOB', 20, 29, 'Kyu nĩkyo kĩanda kya mũndũ mũthũku kyumĩte kwa Ngai, Na ũtiĩwa ũtw’ĩĩwe nĩ Ngai.'),
('kam', 'JOB', 21, 1, 'Na ĩndĩ Yovu asũngĩa, na asya,'),
('kam', 'JOB', 21, 2, 'Ĩw’ai na kĩthing’ĩĩsyo ndeto syakwa; Na ũũ nĩwĩthĩwe mokiakisyo menyu.'),
('kam', 'JOB', 21, 3, 'Ndekai, nakwa nganeena; Na namina kũneena, endeeai na kũvũa ngũĩ.'),
('kam', 'JOB', 21, 4, 'Ngalĩ ĩ yakwa, nĩngũnyungunyĩĩsya mũndũ? Na nĩkĩ ndyaĩle kwaa wũmĩĩsyo?'),
('kam', 'JOB', 21, 5, 'Nzisyai, na kũseng’a, Na kunĩkai makanyw’a menyu na moko menyu.'),
('kam', 'JOB', 21, 6, 'O yĩla ngũlilikana nĩngũũũya, Na w’ĩa mũnene nũkwataa nyama syakwa.'),
('kam', 'JOB', 21, 7, 'Nĩkĩ ala athũku mekalaa thayũ, Maikũa, ĩĩ, kũendeea kwĩthĩwa na vinya?'),
('kam', 'JOB', 21, 8, 'Ũsyao woo nũlũlũmĩlw’e vamwe nao mene, Na syana syoo mbee wa metho moo.'),
('kam', 'JOB', 21, 9, 'Nyũmba syoo syĩ na mũuo vate w’ĩa, O na ndata ya Ngai ndĩ ĩũlũ woo.'),
('kam', 'JOB', 21, 10, 'Nzaũ yoo nĩsyaĩthasya, ndĩleelaa; Ng’ombe nga yoo nĩsyaaa, na ndĩvunaa kasaũ kayo.'),
('kam', 'JOB', 21, 11, 'Nĩmaumaalasya twana twoo tũnini ta ndĩthya ya mbũi na malondu, Na syana syoo ikĩtũlĩlanga.'),
('kam', 'JOB', 21, 12, 'Nĩsinaa na kathembe na mbeve, Na kũtana ũndũ wa wasya wa mũtũlilũ.'),
('kam', 'JOB', 21, 13, 'Mĩthenya yoo maminĩaa ũunĩkonĩ, Na o kavinda kanini nĩmatheeaa Seoli.'),
('kam', 'JOB', 21, 14, 'Na mamwĩa Ngai, Uma vaa tũĩ; Nũndũ tũtikwenda ũmanyi wa nzĩa syaku.'),
('kam', 'JOB', 21, 15, 'Mwene Vinya W’onthe nĩ kyaũ, ũndũ twaĩle kũmũthũkũma? Na tũkeethĩwa na ũtandĩthyo mwaũ, ethĩwa nĩtũũmũvoya?'),
('kam', 'JOB', 21, 16, 'Sisya, ũunĩko ndwĩ kw’okonĩ kwoo: Ũtao wa ala athũku wĩ kũasa nakwa.'),
('kam', 'JOB', 21, 17, 'Taa wa ala athũku ũvoaw’a mavinda meana ata? Kana wanangĩko woo mũnene kũmokĩa? Kana Ngai kũaan’ya mawoo ũthatunĩ wake?'),
('kam', 'JOB', 21, 18, 'Kana mailyĩ mavuthĩ mbee wa kĩseve, Na ta wewa ũla kĩuutani kĩtwaaa?'),
('kam', 'JOB', 21, 19, 'Inyw’ĩ mwĩasya, Ngai nĩwiĩaa syana syake ũthũku. Namũĩve mwene, nĩ kana omanye:'),
('kam', 'JOB', 21, 20, 'Metho make mwene nĩmone wanangĩko wake mwene, Na nanyw’e ũthilĩku wa Mwene Vinya W’onthe.'),
('kam', 'JOB', 21, 21, 'Nũndũ e vata mwaũ na nyũmba yake ĩtina wake, Yĩla ũtalo wa myei yake wĩtilwa?'),
('kam', 'JOB', 21, 22, 'Mũndũ o na wĩva akamũmanyĩsya Ngai ũmanyi, Nũndũ nũsilĩlaa ala me ĩũlũ?'),
('kam', 'JOB', 21, 23, 'Mũndũ nũkusaa e na vinya wake mwĩanĩu, Athũmũĩte na auĩtye ki.'),
('kam', 'JOB', 21, 24, 'Ndoo syake nĩ mbusũu ĩia, Na mũthungo wa mavĩndĩ make nĩ mwololo.'),
('kam', 'JOB', 21, 25, 'Na ũngĩ nũkusaa e na woo wa ngoo, Na ndaasama ũseo nongi.'),
('kam', 'JOB', 21, 26, 'Nĩmakomaa ũndũ ũmwe kĩtoonĩ, Na kĩinyu nĩkĩmavw’ĩkaa.'),
('kam', 'JOB', 21, 27, 'Sisya, nĩnĩsĩ mosũanĩo menyu, Na mosũanĩo ala mũkwenda kũmbĩka naĩ namo.'),
('kam', 'JOB', 21, 28, 'Nũndũ inyw’ĩ mwĩasya, Nyũmba ya mũnene wĩ mbee ũsumbĩnĩ ĩĩva? Na ĩeema yĩla ala athũku matwĩe yĩĩva?'),
('kam', 'JOB', 21, 29, 'Mũtyaakũlya aendi ma kyalo? Na mũtyĩsĩ ũndũ monanasya,'),
('kam', 'JOB', 21, 30, 'Atĩ mũndũ mũthũku nũsũvĩawa kũvika mũthenya wa wanangĩko mũnene? Atĩ nĩmatongoeaw’a kũvika mũthenya wa ũthilĩku?'),
('kam', 'JOB', 21, 31, 'Nũũ ũla wĩmũtavĩsya ũthyũnĩ mũendele wake? Na nũũ ũla wĩmũĩva ũndũ wĩkĩte?'),
('kam', 'JOB', 21, 32, 'Ĩndĩ akakuwa kũvika mbũanĩ, Na andũ makasyaĩĩsya vala wĩthikwa.'),
('kam', 'JOB', 21, 33, 'Mavali ma mwanda makeethĩwa me mũyo kwake, Na andũ onthe makamũatĩĩa, O tondũ matatalĩka ala maĩ mbee wake.'),
('kam', 'JOB', 21, 34, 'Nĩkĩ mũngiakisya mana, Nũndũ mosũngĩonĩ menyu kĩla kĩtialĩte no ũvũngũ?'),
('kam', 'JOB', 22, 1, 'Na ĩndĩ Elivasi Mũtemani asũngĩa, na asya,'),
('kam', 'JOB', 22, 2, 'Mũndũ nũtonya kũmũuna Ngai? Vate ndĩi ũla mũĩ nĩwĩunaa mwene.'),
('kam', 'JOB', 22, 3, 'Nĩ ũndũ wa kwendeesya Mwene Vinya W’onthe, atĩ wĩ mũlũngalu? Kana nĩ ũtandĩthyo wake, atĩ nĩwĩanĩasya mĩendele yaku?'),
('kam', 'JOB', 22, 4, 'Nĩ ũndũ wa kũmũkĩa kwaku, atĩ nũkũkanasya, Na kũlikan’ya naku silanĩ?'),
('kam', 'JOB', 22, 5, 'Ũthũku waku ti mũnene? O na kũti mũminũkĩlyo wa mothũku maku.'),
('kam', 'JOB', 22, 6, 'Nũndũ nĩwosete ngwatĩlĩlyo sya mwana‐a‐au mana, Na kũmavena ala ngya ngũa syoo.'),
('kam', 'JOB', 22, 7, 'Ndũmanengete ala me na mĩnoo manzĩ ma ũnyw’a, Na nũmavatĩte lĩu ala me na nzaa.'),
('kam', 'JOB', 22, 8, 'Ĩndĩ ũndũ wa ngũmbaũ, yaĩ na nthĩ; Na mũndũ wĩ ndaĩa, nake nĩwamĩtũaa.'),
('kam', 'JOB', 22, 9, 'Nĩwũmbũũkĩtye aka ndiwa me athei, Na moko ma ala makw’ĩĩwe nĩ aaĩthe nĩmatũlĩtwe.'),
('kam', 'JOB', 22, 10, 'Kwondũ wa ũu itei nikũthyũlũlũkaa, Na w’ĩa wa kĩthũlũmũko nũkũthĩnasya,'),
('kam', 'JOB', 22, 11, 'O na kĩvindu, na ndũtonya kwona, Na manzĩ maingĩ nĩmakũvw’ĩkaa.'),
('kam', 'JOB', 22, 12, 'Ngai nde ũtũlunĩ wa ĩtu? Na sisya ũasa wa ndata, kũla syĩng’ũthĩte!'),
('kam', 'JOB', 22, 13, 'Naku wĩasya, Ngai esĩ kyaũ? Nũtonya kũsila asiĩlyĩ kĩvindu kya ngokomi?'),
('kam', 'JOB', 22, 14, 'Mathweo makamu nĩ kĩvw’ĩki kyake, na kwondũ wa ũu ndonaa; Na akinyaa kĩlingenĩ kya ĩtu.'),
('kam', 'JOB', 22, 15, 'Ũkakwataa nzĩa ngũũ Ĩla andũ athũku makinyĩle?'),
('kam', 'JOB', 22, 16, 'Ala mavulilw’e ĩvinda yoo yĩtanavika, Ala wambĩlĩlyo woo woonoiw’e ta kalũsĩ,'),
('kam', 'JOB', 22, 17, 'Ala mamwĩie Ngai, Uma vala tũĩ; Na, Mwene Vinya W’onthe atonya kũtwĩka ata?'),
('kam', 'JOB', 22, 18, 'Ĩndĩ ausũsya nyũmba syoo na syĩndũ nzeo: Ĩndĩ ũtao wa ala athũku wĩ kũasa nakwa.'),
('kam', 'JOB', 22, 19, 'Ala alũngalu moona ũu, na nĩmeũtana; Na ala mate na ĩvĩtyo mamathekeea mũno,'),
('kam', 'JOB', 22, 20, 'Makyasya, Nĩ w’o ala matũkĩlĩĩle nĩmavetetwe, Na ũtialo woo nũminĩtwe nĩ mwaki.'),
('kam', 'JOB', 22, 21, 'Manyana yu nake, na ĩthĩwa na mũuo: Kwondũ wa ũu ũseo ũkooka kwaku.'),
('kam', 'JOB', 22, 22, 'Osa, nĩngũkwĩsũva, mĩao kuma kanyw’anĩ wake, Nokia ndeto syake ngoonĩ yaku.'),
('kam', 'JOB', 22, 23, 'Ethĩwa wĩmũsyokea Mwene Vinya W’onthe ũkaakwa, Ethĩwa wĩveta kũasa ũla ũte ũlũngalu maeemanĩ maku.'),
('kam', 'JOB', 22, 24, 'Na ia ũthwii waku kĩtoonĩ, Na thaavu wa Ovilu katĩ wa mavia me tũlũsĩnĩ;'),
('kam', 'JOB', 22, 25, 'Na Mwene Vinya W’onthe akeethĩawa ũthwii waku, Na vetha wĩ vata mũno kwaku.'),
('kam', 'JOB', 22, 26, 'Nũndũ nĩvo ũketanĩthĩsya nthĩnĩ wa Mwene Vinya W’onthe, Na ũkamũkĩlĩlya Ngai ũthyũ waku.'),
('kam', 'JOB', 22, 27, 'Ũkamũvoyaa, nake akakwĩthukĩĩasya; Naku ũkeanĩasya mawĩvĩto maku.'),
('kam', 'JOB', 22, 28, 'O na ũkatw’a ũndũ, na ũkalũlũmĩlw’a kwaku; Na kyeni kĩkakeneeaa mĩendele yaku.'),
('kam', 'JOB', 22, 29, 'Yĩla makakwĩkya nthĩ, ũkasya, Kwĩ kũkĩla; Na mũndũ wĩ na wĩnyivyo akamũtangĩĩa.'),
('kam', 'JOB', 22, 30, 'Akamũvonokya ũla wĩ na ĩvĩtyo: Ĩĩ, akavonokw’a kwondũ wa ũtheu wa moko maku.'),
('kam', 'JOB', 23, 1, 'Na ĩndĩ Yovu asũngĩa na asya,'),
('kam', 'JOB', 23, 2, 'O na ũmũnthĩ mũnyungunyĩsyo wakwa wĩ na ũlei: Ĩkũna yakwa nĩ ĩito kwĩ kũluma kwakwa.'),
('kam', 'JOB', 23, 3, 'A! Kethĩwa nĩnĩsĩ vala ndonya kũmwona! Kethĩwa nĩmbika o kĩvĩlanĩ kyake!'),
('kam', 'JOB', 23, 4, 'Ngethĩwa ngia ũvoo wakwa ũatianĩe mbee wake, Na kusũsya kanyw’a wakwa na ngananĩo.'),
('kam', 'JOB', 23, 5, 'Ngethĩwa ngĩmanya ndeto ila wĩnzũngĩa, Na kũmanya ũla wĩndavya.'),
('kam', 'JOB', 23, 6, 'Akakĩlan’ya vinya nakwa ũnenenĩ wa vinya wake? Aiee; ĩndĩ akambĩthukĩĩsya.'),
('kam', 'JOB', 23, 7, 'Vo ũla mũlũngalu akethĩwa atonya kũsũanĩa nake; Kwondũ wa ũu ngethĩwa nĩvonokete tene na tene kuma kwa mũsili wakwa.'),
('kam', 'JOB', 23, 8, 'Sisya, nĩendaa mbee, ĩndĩ nde vo; Na nĩsyokaa na ĩtina, ĩndĩ nditonya kũmwona;'),
('kam', 'JOB', 23, 9, 'Nĩendaa kw’okonĩ kwa aka, yĩla ũtethasya wĩa, ĩndĩ nditonya kũmwona; Evithaa ngalĩ ya kw’oko kwa aũme, nĩ kana ndikamwone.'),
('kam', 'JOB', 23, 10, 'Ĩndĩ nake nĩwĩsĩ nzĩa ĩla nĩendaa nayo; Yĩla wĩmina kũndata, ngauma ta thaavu.'),
('kam', 'JOB', 23, 11, 'Ũnyaĩĩ wakwa nũkwatĩte matambya make; Nzĩa yake nĩnĩmĩkwatĩte, na ndyaaelelũka.'),
('kam', 'JOB', 23, 12, 'Ndinasyoka na ĩtina na kũtia mĩao ya ilomo syake; Niĩte ndeto sya kanyw’a wake kũvĩtũka lĩu wakwa ũla wĩ vata.'),
('kam', 'JOB', 23, 13, 'Ĩndĩ e na kĩlilikano kĩmwe, na nũũ ũtonya kũmũthyũũa? Na ũndũ ngoo yake yendaa, now’o wĩkaa.'),
('kam', 'JOB', 23, 14, 'Nũndũ nĩwĩanĩasya ũla ũtw’ĩtwe kwondũ wakwa: Na maũndũ maingĩ ta asu me nake.'),
('kam', 'JOB', 23, 15, 'Kwondũ wa ũu nĩtelemetwe mũno nĩ mbee wake; Yĩla ngũsũanĩa, nĩngũmũkĩa.'),
('kam', 'JOB', 23, 16, 'Nũndũ Ngaĩ nũtumĩte ngoo yakwa ĩthelekela, Na Mwene Vinya W’onthe nũndelemetye mũno;'),
('kam', 'JOB', 23, 17, 'Nũndũ ndyaavetwa kĩvindu kĩtanoka, O nake ndaavw’ĩka ũthyũ wakwa ndikone kĩvindu kya ngokomi.'),
('kam', 'JOB', 24, 1, 'Nĩkĩ mavinda mayiĩtw’e nĩ Mwene Vinya W’onthe? Na nĩkĩ ala mamwĩsĩ matyonaa mĩthenya yake?'),
('kam', 'JOB', 24, 2, 'Nĩvo maĩ amwe ala makũĩĩasya syambo sya mĩvaka; Nĩmavutanaa ndĩthya sya mbũi na malondu, na kwiĩthya.'),
('kam', 'JOB', 24, 3, 'Nĩmatavaa ĩng’oi ya ala makw’ĩĩwe nĩ aaĩthe; Nĩmosaa ng’ombe ya mũndũ mũka ndiwa yĩthĩwe ngwatĩlĩlyo.'),
('kam', 'JOB', 24, 4, 'Nĩmathũkasya athĩni maume nzĩanĩ: Ngya syonthe sya nthĩ nĩsyĩvithaa.'),
('kam', 'JOB', 24, 5, 'Sisya, ta mang’oi ma kĩthekanĩ me yalatanĩ Nĩmaumaalaa maende wĩanĩ woo, makĩmantha lĩu na kĩthing’ĩĩsyo; Weũ nũmanengae lĩu kwondũ wa syana syoo.'),
('kam', 'JOB', 24, 6, 'Nĩmakethaa lĩu woo mũũndanĩ; Na nĩmethĩanasya ngethanĩ ya mĩsavivũ ya ala athũku.'),
('kam', 'JOB', 24, 7, 'Nĩmakomaa ũtukũ w’onthe me athei mate na ngũa, Na mate na kya kwĩvw’ĩka mbevonĩ.'),
('kam', 'JOB', 24, 8, 'Me na ũthithu wa mĩono ya mbua ya iĩmanĩ, Na kwĩyaĩanĩsya na ĩvia nũndũ kũti wĩvitho.'),
('kam', 'JOB', 24, 9, 'Nĩvo maĩ ala makusasya ala makw’ĩĩwe nĩ aaĩthe kũmaumya nondonĩ, Na kwosa ngwatĩlĩlyo kwa ngya;'),
('kam', 'JOB', 24, 10, 'Na kwondũ wa ũu niendaa syĩ nthei ite na ngũa, Na nũndũ wa kwĩthĩwa na nzaa nikuaa syove sya ngetha.'),
('kam', 'JOB', 24, 11, 'Niseũvasya mauta me nthĩnĩ wa maũvai ma andũ asu; Nikinyangĩaa nzavivũ iangĩonĩ syoo, na kũthĩnw’a nĩ waũni.'),
('kam', 'JOB', 24, 12, 'Andũ nĩmalumaa me ndũanĩ yĩ andũ aingĩ, Na ngoo ya ũla mũkite nĩkayaa: Ĩndĩ Ngai ndasiasya ũtumanu ũsu.'),
('kam', 'JOB', 24, 13, 'Asu nĩ ma ala mang’endeaa kyeni; Matyĩsĩ nzĩa syakyo, Kana kwĩkalaa nzĩanĩ syakyo.'),
('kam', 'JOB', 24, 14, 'Mũaani nĩwũkĩlaa kwĩ w’oa; Nĩwũaaa ngya na athĩni; Na ũtukũ nĩ ta kĩng’ei.'),
('kam', 'JOB', 24, 15, 'O na itho ya kĩlaalai nĩyeteelaa ũmithi, Kĩkyasya, Vati itho yĩkambona: Na kĩialyũlanga ũthyũ wakyo.'),
('kam', 'JOB', 24, 16, 'Kĩvindunĩ nĩmavũthũaa nyũmba: Nĩmevingĩa mũthenya; Matyĩsĩ kyeni.'),
('kam', 'JOB', 24, 17, 'Nũndũ kĩoko kwa asu onthe nĩ ta kĩvindu kya ngokomi; Nũndũ nĩmesĩ motĩsyo ma kĩvindu kya ngokomi.'),
('kam', 'JOB', 24, 18, 'Nĩmavĩtaa mĩtũkĩ ĩũlũ wa manzĩ; Kĩanda kyoo nĩkĩumanĩwe nthĩ: Matyathũkĩlaa nzĩanĩ yĩ mĩũnda ya mĩsavivũ.'),
('kam', 'JOB', 24, 19, 'Mũnyao na muutĩa niminaa manzĩ ma ĩa: Now’o Seoli vamekaa ala mavĩtĩtye.'),
('kam', 'JOB', 24, 20, 'Ĩvu yĩkamũla; Kĩinyu kĩkamũya na mũyo; Ndakalilikanwa ĩngĩ; Na ũla ũte ũlũngalu ũkatũlwa ta mũtĩ.'),
('kam', 'JOB', 24, 21, 'Nũminaa ngũngũ ĩla ĩtasyaaa, Na ndamwĩkaa mesa mũndũ mũka ndiwa.'),
('kam', 'JOB', 24, 22, 'Ĩndĩ Ngai nũsũvĩaa na vinya wake ũla wĩ na ũtonyi: Ũla ũte na wĩkwatyo wa thayũ nĩwũkĩlaa.'),
('kam', 'JOB', 24, 23, 'Ngai nũmanengae kwĩyelela, na nĩmathũmũaa nthĩnĩ wakw’o; Na metho make nĩmasiasya mĩendele yoo.'),
('kam', 'JOB', 24, 24, 'Nĩmeũnenevw’a; ĩndĩ kavinda kanini, na nĩmeũthi; Ĩĩ, nĩmeũtheew’a, nĩmeũvetwa ta angĩ onthe, Na nĩmeũtilwa ta mĩthya ya iia sya lĩu wa mbaa ngetha.'),
('kam', 'JOB', 24, 25, 'Na ethĩwa ti ta ũu yu, nũũ ũla wĩonan’ya ki kana nĩ mũneeni wa ũvũngũ, Na kũtw’ĩkĩthya kũneena kwakwa kũte vata?'),
('kam', 'JOB', 25, 1, 'Na ĩndĩ Mbilitati Mũsui asũngĩa, na asya,'),
('kam', 'JOB', 25, 2, 'Ũsumbĩko na w’ĩa syĩ nake; Nũseũvasya mũuo e kũndũ kwake kũtũlu.'),
('kam', 'JOB', 25, 3, 'Ita syake nitalĩka? Na nũũ ũla kyeni kyake kĩtamumĩlĩlaa?'),
('kam', 'JOB', 25, 4, 'Mũndũ atonya ata kwĩthĩwa mũlũngalu kwa Ngai? Kana atonya ata kwĩthĩwa mũtheu ũla ũsyaĩtwe nĩ mũndũ mũka?'),
('kam', 'JOB', 25, 5, 'Sisya, o na mwei ndwĩ na ũtisu, Na ndata ti ntheu methonĩ make:'),
('kam', 'JOB', 25, 6, 'Na mũndũ nata, nake nĩ kĩinyu! Na mwana wa mũndũ, nake nĩ kĩinyu!'),
('kam', 'JOB', 26, 1, 'Na ĩndĩ Yovu asũngĩa na asya,'),
('kam', 'JOB', 26, 2, 'A! Ũndũ ũmũtethetye ũla ũte vinya! Ũndũ ũtangĩĩĩte kw’oko kũte na vinya!'),
('kam', 'JOB', 26, 3, 'A! Ũndũ ũmũtaĩte ũla ũte na ũĩ, Na kũvuan’ya mũno ũmanyi mwĩanĩu!'),
('kam', 'JOB', 26, 4, 'Ũtavĩtye ndeto ũũ? Na nĩ veva waũ umĩte kwaku?'),
('kam', 'JOB', 26, 5, 'Ala makwie nĩmatetemaa Me ungu wa ala manzĩ na ala matwĩe kw’o.'),
('kam', 'JOB', 26, 6, 'Seoli ve ũtheinĩ mbee wa Ngai, Na Avatoni vati kya kũvavw’ĩka.'),
('kam', 'JOB', 26, 7, 'Nũtambũũkĩasya ngalĩ ya ĩũlũ vandũ vathei, Na kũsũnzũlya nthĩ vate kĩndũ.'),
('kam', 'JOB', 26, 8, 'Nũvingĩaa manzĩ mathweonĩ make makamu; Na ĩthweo yĩtitembũangwa yĩ ĩtheo wamo.'),
('kam', 'JOB', 26, 9, 'Nĩwiiĩaa ũthyũ wa kĩvĩla kyake kya ũsumbĩ, Na kwalan’ya ĩthweo yake ĩũlũ wakyo.'),
('kam', 'JOB', 26, 10, 'Nĩwiĩte mũvaka ĩũlũ wa iw’ũ, Kũvika vala kyeni na kĩvindu ivakanĩle.'),
('kam', 'JOB', 26, 11, 'Ituĩ sya ĩtu nitetemaa Na kũseng’a nũndũ wa kũkan’ya kwake.'),
('kam', 'JOB', 26, 12, 'Nĩwũkĩlanasya ũkanga na vinya wake, Na kwondũ wa ũmanyi wake nũtonyaa Laavi mũkuthũ.'),
('kam', 'JOB', 26, 13, 'Matu nĩmanakavaw’a nĩ Veva wake; Kw’oko kwake nĩkũtonyete nzoka ya kũnyoloka mĩtũkĩ.'),
('kam', 'JOB', 26, 14, 'Sisya, ii no ndee sya nzĩa syake: Na kaĩ no kĩwe kĩnini twĩw’aa ũndũ wake! Ĩndĩ kĩtundumo kya vinya wake nũũ ũtonya ũkĩmanya?'),
('kam', 'JOB', 27, 1, 'Na Yovu aneena ngelekan’yo yake ĩngĩ, na asya,'),
('kam', 'JOB', 27, 2, 'O tondũ Ngai wĩ thayũ, ũla ũvetete kĩanda kyakwa, Na Mwene Vinya W’onthe, ũla ũthĩnĩtye ngoo yakwa'),
('kam', 'JOB', 27, 3, '(Nũndũ thayũ wakwa o na yu no mũima nthĩnĩ wakwa, Na mĩthũmũ ya Ngai yĩ manyiũũnĩ makwa);'),
('kam', 'JOB', 27, 4, 'Vate ndĩi ilomo syakwa itikaneena ũla ũte ũlũngalu, O na ũĩmĩ wakwa ndũkaneena ũkengani.'),
('kam', 'JOB', 27, 5, 'Nĩkwĩthĩwe kũasa nakwa kũmũtalĩla ũlũngalu: Kũvika nakw’a ndikaveta kwakwa wĩanĩu wakwa.'),
('kam', 'JOB', 27, 6, 'Nĩngũlũmya ũlũngalu wakwa, ndikoeka ũthi: Ngoo yakwa ndĩkangan’ya ĩvinda yonthe nĩ thayũ.'),
('kam', 'JOB', 27, 7, 'Mũmaitha wakwa nĩethĩwe ta ũla mũthũku, Na ũla ũmbũkĩlĩĩlaa nĩethĩwe ta ũla ũte mũlũngalu.'),
('kam', 'JOB', 27, 8, 'Nũndũ wĩkwatyo wa ũla ũtakĩaa Ngai nĩ mwaũ, o na ethĩwa nĩwĩyonee ũtandĩthyo, Yĩla Ngai wĩosa thayũ wake?'),
('kam', 'JOB', 27, 9, 'Ngai akeew’a kũkaya kwake, Yĩla thĩna wĩmũkĩa?'),
('kam', 'JOB', 27, 10, 'Akeetan’ya nthĩnĩ wa Mwene Vinya W’onthe, Na kũmwĩkaĩla Ngai mavinda onthe?'),
('kam', 'JOB', 27, 11, 'Ngakũmanyĩsya ũndũ wa kw’oko kwa Ngai; Ũndũ ũla wĩ na Mwene Vinya W’onthe ndikovitha.'),
('kam', 'JOB', 27, 12, 'Sisyai, inyw’onthe ene nĩmũwonete; Nĩkĩ ĩndĩ nĩmũtw’ĩkĩte ma mana ki?'),
('kam', 'JOB', 27, 13, 'Kĩĩ nĩkyo kĩanda kya mũndũ mũthũku kwa Ngai, Na ũtiĩwa wa athĩn’ya, ũla mosaa kwa Mwene Vinya W’onthe:'),
('kam', 'JOB', 27, 14, 'Ethĩwa syana syake nikwingĩvaa, syĩ kwondũ wa ũvyũ; Na ũsyao wake ndũkavũnwa nĩ lĩu.'),
('kam', 'JOB', 27, 15, 'Ala make ala metiala makathikwa kĩkw’ũnĩ, Na aka make ndiwa matikethĩwa na kĩĩo.'),
('kam', 'JOB', 27, 16, 'O na ethĩwa akomban’ya kĩvumbu kya vetha ta kĩtoo, Na kũseũvĩthya ngũa ta yũmba;'),
('kam', 'JOB', 27, 17, 'Nake nũtonya kwĩseũvĩthya, ĩndĩ ala alũngalu makasyĩkĩa, Na ala mate na ĩvĩtyo makeeaan’ya ũ vetha.'),
('kam', 'JOB', 27, 18, 'Nũnũkwaka nyũmba yake ta lungulu, Na ta ĩlwanda mũsũvĩi ũnũkwaka.'),
('kam', 'JOB', 27, 19, 'Nũnũũkoma e mũthwii, ĩndĩ ndakombanw’a vamwe na aaĩthe make; Nũnũũsalukya metho make, na nde vo.'),
('kam', 'JOB', 27, 20, 'Motĩsyo mamũkwataa ta manzĩ; Kĩuutani kĩmũyaa ũtukũ.'),
('kam', 'JOB', 27, 21, 'Kĩseve kyumĩte ngalĩ ya wumĩlonĩ wa syũa nĩkĩmũtwaa, nake aithi; Na kĩimumya vyũ vandũ vake.'),
('kam', 'JOB', 27, 22, 'Nũndũ Ngai akamwĩkĩsya, na ndakew’ĩa tei: Nake akenda kũsemba kuma kw’okonĩ kwake.'),
('kam', 'JOB', 27, 23, 'Andũ makamũkũnangĩa mbĩ, Na makamũtimba aume vandũ vake.'),
('kam', 'JOB', 28, 1, 'Vate ndĩi ve ĩima ya vetha, Na vandũ va thaavu ũla matheasya.'),
('kam', 'JOB', 28, 2, 'Kĩaa nĩkyumaw’a nthĩ, Na ũthuku nũtwekethaw’a kuma ĩvianĩ.'),
('kam', 'JOB', 28, 3, 'Mũndũ nĩwiĩte mũvaka wa kĩvindu, Na kũmantha, kũvika mũvaka wĩ kũasa mbee, Mavia me wiũnĩ na me kĩvindunĩ kya ngokomi.'),
('kam', 'JOB', 28, 4, 'Nĩwĩnzaa ĩima kũasa na vala andũ matũaa; Nĩmolawa nĩ ũkinyĩlo wa kũũ; Nĩmeũsũnzũlw’a kũasa na andũ, nĩmasũaa kũu na kũu.'),
('kam', 'JOB', 28, 5, 'Ũndũ wa nthĩ, lĩu nĩwumaa kwayo; Na ĩtheo nĩkũlumanaw’a ta kũkũlumanw’a nĩ mwaki.'),
('kam', 'JOB', 28, 6, 'Mavianĩ mayo nĩ vala ve tũvila twa savili, Na yĩ na mũthanga wa thaavu.'),
('kam', 'JOB', 28, 7, 'Nzĩa ĩsu vaiĩ nyũnyi mbai ĩmĩsĩ, O na itho ya kĩvaalala yĩtyaamyona:'),
('kam', 'JOB', 28, 8, 'Nyamũ syĩ ngathĩĩo ityaamĩkinya, O na mũnyambũ mwai ndwaamĩkinyĩla.'),
('kam', 'JOB', 28, 9, 'Nũtambũũkĩĩsya kw’oko kwake ĩvia yũmũ mũno; Nũkũlumanasya iĩma na mĩi.'),
('kam', 'JOB', 28, 10, 'Nĩwalasya mokinyĩlo mavianĩ; Na itho yake nĩyonaa kĩla kĩndũ kĩ vata mũno.'),
('kam', 'JOB', 28, 11, 'Nũvingĩaa tũlũsĩ tũikavivũke; Na kĩla kĩvithe nũetae kyeninĩ.'),
('kam', 'JOB', 28, 12, 'Ĩndĩ ũĩ ũkooneka va? Na vandũ va ũmanyi nĩ va?'),
('kam', 'JOB', 28, 13, 'Mũndũ ndesĩ thooa waw’o; O na ndwoneka nthĩ ya ala me thayũ.'),
('kam', 'JOB', 28, 14, 'Kyũngũ nĩkyaasya, Ndwĩ nthĩnĩ wakwa; Na ũkanga nĩwaasya, Ndwĩ nakwa.'),
('kam', 'JOB', 28, 15, 'Ndũtonya kũthoowa na thaavu, O na vetha ndũkathimwa wĩthĩwe thooa waw’o.'),
('kam', 'JOB', 28, 16, 'Ndũtonya kwĩananw’a thooa waw’o na thaavu wa Ovilu, Kana kavila ke thooa mũnene ka nzumalati, kana ka savili.'),
('kam', 'JOB', 28, 17, 'Thaavu na kĩsisyo ititonya kwĩananw’a naw’o, O na ndũkakũanw’a na mĩio ya wanake ya thaavu mũseo.'),
('kam', 'JOB', 28, 18, 'Vethalũka kana kĩsisyo kĩtisu itikawetwa: Ĩĩ, thooa wa ũĩ nĩ mũnene kũvĩtũka tũvila twa maliani.'),
('kam', 'JOB', 28, 19, 'Kavila ka tovasi ka Ethiovia kaitonya kwĩananw’a naw’o, O na ndũkeanan’ya thooa na thaavu mũseo.'),
('kam', 'JOB', 28, 20, 'Ũĩ wumaa va ĩndĩ? Na vandũ va ũmanyi nĩ va?'),
('kam', 'JOB', 28, 21, 'Nũndũ nũvithanĩtw’e na metho ma onthe me thayũ, Na kũvithwa nyũnyi sya yayaya itikawone.'),
('kam', 'JOB', 28, 22, 'Wanangĩko na kĩkw’ũ nikwasya, Nĩtwĩw’ĩte na matũ maitũ ĩsyũ yaw’o.'),
('kam', 'JOB', 28, 23, 'Ngai nũmanyaa nzĩa yaw’o, Na nĩwĩsĩ vandũ vaw’o.'),
('kam', 'JOB', 28, 24, 'Nũndũ nake nĩwona kũvika itulu sya nthĩ, Na kũsisya ĩtheo wa ĩtu yonthe;'),
('kam', 'JOB', 28, 25, 'Aseũvya kĩthimo kya kĩseve: Ĩĩ, nũthimaa manzĩ na kĩthimi.'),
('kam', 'JOB', 28, 26, 'Yĩla waseũvisye ũtw’ĩo ũndũ wa mbua, Na nzĩa ya ũtisi wa kĩtundumo;'),
('kam', 'JOB', 28, 27, 'Nĩvo ĩndĩ wawonie, na ootavan’ya; Oolũlũmĩlya, ĩĩ, na kũmantha.'),
('kam', 'JOB', 28, 28, 'Na amwĩa mũndũ, Sisya, kũmũkĩa Mwĩaĩi, nĩkw’o ũĩ; Na kũtia ũthũku nĩkw’o ũmanyi.'),
('kam', 'JOB', 29, 1, 'Na Yovu aneena ngelekan’yo yake ĩngĩ, na asya,'),
('kam', 'JOB', 29, 2, 'A! Kethĩwa nĩilyĩ o tondũ nailyĩ myei ya tene, Ta mĩthenya ĩla Ngai wanzũvĩaa;'),
('kam', 'JOB', 29, 3, 'Yĩla taa wake wakeneaa mũtwenĩ wakwa, Na kwondũ wa kyeni kyake navĩtĩlaa kĩvindunĩ;'),
('kam', 'JOB', 29, 4, 'O tondũ nailyĩ wĩunĩ wa mĩthenya yakwa, Yĩla ũnyanya wa Ngai waĩ ĩũlũ wa ĩeema yakwa;'),
('kam', 'JOB', 29, 5, 'Yĩla Mwene Vinya W’onthe waĩ nakwa, Na syana syakwa inthyũlũlũkĩte:'),
('kam', 'JOB', 29, 6, 'Yĩla matambya makwa mathambaw’a na mauta, Na ĩvia yambonoeasya tũlũsĩ twa mauta!'),
('kam', 'JOB', 29, 7, 'Yĩla naumaalaa mbingĩlonĩ ya ndũa, Yĩla naiaa kĩvĩla kyakwa nzĩanĩ nene,'),
('kam', 'JOB', 29, 8, 'Anake mambona nĩmeevithaa, Na ala akũũ mookĩlaa na kũũngama;'),
('kam', 'JOB', 29, 9, 'Anene nĩmeesiĩĩaa kũneena, Na kũkunĩka makanyw’a na moko moo;'),
('kam', 'JOB', 29, 10, 'Wasya wa anene me ndaĩa nĩwakilasya, Na ũĩmĩ woo uilũman’ya na kaakaa wa kanyw’a woo.'),
('kam', 'JOB', 29, 11, 'Nũndũ yĩla kũtũ kwambĩw’aa, nĩkwangathimaa; Na yĩla itho yambonaa, nĩyangũsĩĩaa:'),
('kam', 'JOB', 29, 12, 'Nĩkwĩthĩwa nĩnavonokasya ngya ila syakayaa, O na ũla wakw’ĩĩwe nĩ ĩthe, ũla ũtaĩ na mũndũ wa kũmũtethya.'),
('kam', 'JOB', 29, 13, 'Ũathimo wa ũla wakilĩlye kwaa nĩwambũkĩaa; Na natumaa ngoo ya mũndũ mũka ndiwa yina ũndũ wa ũtanu.'),
('kam', 'JOB', 29, 14, 'Nekĩaa ũlũngalu, na ũkĩmbw’ĩka: Ũsili wakwa wa katĩ wailyĩ ta ngũa ndasa na ngovia ya ũsumbĩ.'),
('kam', 'JOB', 29, 15, 'Nakwa naĩ metho kwa ililinda, Na naĩ maũũ kwa ala mathuaa.'),
('kam', 'JOB', 29, 16, 'Na naĩ ĩthe wa athĩni: Na ũvoo wa ũla ndaamanya nĩnoomanthaa.'),
('kam', 'JOB', 29, 17, 'Na natũlaa ngambu sya ũla ũte mũlũngalu, Na kumya sya nzyĩma maeonĩ make.'),
('kam', 'JOB', 29, 18, 'Nĩvo ĩndĩ naisye, Ngakw’a ndalanĩ yakwa, Na ngaingĩvya mĩthenya yakwa ta kĩthangathĩ:'),
('kam', 'JOB', 29, 19, 'Mũi wakwa nũtambũũkĩte manzĩnĩ, Na ĩmwe nĩyĩkalaa ũtukũ w’onthe ũvongenĩ wakwa:'),
('kam', 'JOB', 29, 20, 'Ũnene wakwa nĩ mweũ nthĩnĩ wakwa, Na ũta wakwa nũtũngĩtwe mweũ kw’okonĩ kwakwa.'),
('kam', 'JOB', 29, 21, 'Andũ nĩmambĩthukĩĩasya, na kweteela, Na nĩmavindasya mew’e ũtao wakwa.'),
('kam', 'JOB', 29, 22, 'Ndeto syakwa syathela matyaneenaa ĩngĩ; Na kũneena kwakwa nĩkwavolotangaa ĩũlũ woo.'),
('kam', 'JOB', 29, 23, 'Na nĩmambeteelaa ta kweteela mbua; Na nĩmaathamasya kanyw’a woo mũno ta kwosa mbua ya uũa.'),
('kam', 'JOB', 29, 24, 'Nĩnamasiasya na ũtanu, yĩla mataĩ na ũĩkĩĩi; Na kyeni kya ũthyũ wakwa matyaakĩkya nthĩ.'),
('kam', 'JOB', 29, 25, 'Nĩnamanyuvĩaa nzĩa yoo, na nekalaa nthĩ ta mũnene, Na nekalaa ta mũsumbĩ itanĩ Ta ũmwe ũla ũkiakiasya ala mametaa.'),
('kam', 'JOB', 30, 1, 'Ĩndĩ yu ala anini kwĩ nyie nĩmeũmbũthya, Ala aaĩthe moo navũthĩtye kũmekĩanĩsya na ngitĩ sya ndĩthya yakwa ya mbũi na malondu.'),
('kam', 'JOB', 30, 2, 'Ĩĩ, vinya wa moko moo, ũkanguna na kyaũ? Andũ ala mewĩthĩtye myaka yoo na ĩkanangĩka.'),
('kam', 'JOB', 30, 3, 'Nĩ amosu nũndũ wa kwaĩwa na yũa; Nĩmavevetaa nthĩ nyũmũ, kũla kwĩ wiũ wa vathei na wanangĩko.'),
('kam', 'JOB', 30, 4, 'Nĩmovaa kyũnyũ vakuvĩ na ikuthu; Na mĩi ya mũlutemu nĩ lĩu woo.'),
('kam', 'JOB', 30, 5, 'Nĩmalũngĩtw’e kuma katĩ wa andũ; Nĩmauĩtye ũkemi ĩtina woo ta kũatĩĩa kĩng’ei;'),
('kam', 'JOB', 30, 6, 'Kwondũ wa ũu nĩmatũaa myandanĩ yi ũtĩsyo, Maĩmanĩ ma nthĩ na ma mavia.'),
('kam', 'JOB', 30, 7, 'Nĩmekwanĩsya ikuthunĩ; Mombanĩte ungu wa syĩnyeelya.'),
('kam', 'JOB', 30, 8, 'Nĩ syana sya ndia, ĩĩ, syana sya andũ mate kĩĩĩ; Nĩmakũniwe maumw’e ĩ nthĩ.'),
('kam', 'JOB', 30, 9, 'Na yu nĩtw’ĩkĩte wathi woo, Ĩĩ, nĩ wa kũvũthw’a nĩo.'),
('kam', 'JOB', 30, 10, 'Nĩmanthĩthaa, nĩmaũngamaa mevathanĩte nakwa, Na matiũlea kũndw’ĩla mata ũthyũnĩ wakwa.'),
('kam', 'JOB', 30, 11, 'Nũndũ nũthaĩtye ĩkanda yake, na kũnthĩn’ya; Na nĩmavetete mũkwa mbee wakwa.'),
('kam', 'JOB', 30, 12, 'Kw’okonĩ kwakwa kwa aũme nguthu ya imaamai nĩyũkĩlaa; Nĩmalutaa maũũ makwa maende ũtee, Na nĩmambũkĩlĩlasya nzĩa syoo sya wanangĩko.'),
('kam', 'JOB', 30, 13, 'Nĩmaanangaa nzĩa yakwa, Nĩmakalaataa wanangĩko wakwa mũnene, O andũ ala mate na mũtethya.'),
('kam', 'JOB', 30, 14, 'Nĩmokaa o ta kũvĩtĩla ũvũthũenĩ mũnene: Katĩ wa ũomboku nĩmembonoeasya.'),
('kam', 'JOB', 30, 15, 'Motĩsyo nĩmethyũũĩte mambũkĩe; Nĩmaatĩĩaa ndaĩa yakwa ta kĩseve; Na ũunĩko wakwa nũvĩtĩe ta ĩthweo.'),
('kam', 'JOB', 30, 16, 'Na yu ngoo yakwa nĩyĩtĩkĩte nthĩnĩ wakwa; Mĩthenya ya thĩna nĩngwatĩte.'),
('kam', 'JOB', 30, 17, 'Ũtukũ mavĩndĩ makwa nĩmasinangĩawa nthĩnĩ wakwa, Kyalya kĩla kĩmbevetaa kĩilikaa.'),
('kam', 'JOB', 30, 18, 'Kwondũ wa vinya mũnene wa Ngai ngũa yakwa nĩ ngalyũku; Nĩngwete ta kala ya ĩkoti yakwa.'),
('kam', 'JOB', 30, 19, 'Nũmbĩkĩtye ndakanĩ, Na nĩnĩtw’ĩkĩte ta kĩtoo na mũu.'),
('kam', 'JOB', 30, 20, 'Nĩkwĩkaĩlaa, na ndũnzũngĩaa: Nĩũngamaa, naku nũngeteeaa.'),
('kam', 'JOB', 30, 21, 'Nũalyũkĩte wĩthĩwe mwai kwakwa; Nũnthĩnasya na vinya wa kw’oko kwaku.'),
('kam', 'JOB', 30, 22, 'Nũmbũkĩlasya kĩsevenĩ, nũtumaa nĩkuwa nĩkyo; Na nũndweketheasya kĩuutaninĩ.'),
('kam', 'JOB', 30, 23, 'Nũndũ nĩnĩsĩ ũkambikya kĩkw’ũnĩ, Na nyũmbani ĩla ĩtw’ĩĩwe andũ onthe me thayũ.'),
('kam', 'JOB', 30, 24, 'O na ũu w’onthe mũndũ ndatambũũkasya kw’oko aivalũka? Kana wanangĩkonĩ wake mũnene kwondũ wa ũu ndakayaa one ũtethyo?'),
('kam', 'JOB', 30, 25, 'Ndyaaĩa kwondũ wa ũla waĩ thĩnanĩ? Ngoo yakwa ndĩaĩw’a woo kwondũ wa mũthĩni?'),
('kam', 'JOB', 30, 26, 'Yĩla namanthie ũseo, ũthũku wooka; Na yĩla neeteelile kyeni, kwookie kĩvindu.'),
('kam', 'JOB', 30, 27, 'Ngoo yakwa nĩnĩkũũũya, na ndĩthũmũaa; Mĩthenya ya thĩna nĩmbũkĩe.'),
('kam', 'JOB', 30, 28, 'Nĩendaa na kĩmeto vate syũa: Nĩũngamaa ũmbanonĩ, na kũkaya none ũtethyo.'),
('kam', 'JOB', 30, 29, 'Nyie nĩ mwana‐a‐ĩthe wa mbĩwa, Na mũtindan’ya wa nyaa.'),
('kam', 'JOB', 30, 30, 'Kĩkonde kyakwa nĩ kiũ, na nĩkĩmbuma, Na mavĩndĩ makwa nĩ mavĩvye nĩ muutĩa.'),
('kam', 'JOB', 30, 31, 'Kwondũ wa ũu mbeve yakwa nĩalyũkĩte ĩkatw’ĩka ya kũmeta, Na mũtũlilũ wakwa wĩ na wasya wa ala maĩaa.'),
('kam', 'JOB', 31, 1, 'Nyie nĩnatianĩe ũtianĩo na metho makwa; Ndonya ata ĩndĩ kũsisya mwĩĩtu mũtheu?'),
('kam', 'JOB', 31, 2, 'Nũndũ kĩanda nĩ kyaũ kuma ĩũlũ kwa Ngai, Na ũtiĩwa kuma ĩũlũ kwa Mwene Vinya W’onthe?'),
('kam', 'JOB', 31, 3, 'Ti wanangĩko mũnene kwa ala mate alũngalu, Na thĩna kwa eki ma naĩ?'),
('kam', 'JOB', 31, 4, 'Nake ndekwona mĩendele yakwa? Na kũtala matambya makwa onthe?'),
('kam', 'JOB', 31, 5, 'Ethĩwa nĩnaendanisye na ũvũngũ, Na kũũ kwakwa nĩkweekalaatile kũkengana'),
('kam', 'JOB', 31, 6, '(Nyie nĩthimwe na kĩthimi kya katĩ, Nĩ kana Ngai amanye wĩanĩu wakwa);'),
('kam', 'JOB', 31, 7, 'Ethĩwa matambya makwa nĩmeelelũkile kũtia nzĩa, Na ngoo yakwa yaendie kũatĩĩa metho makwa, Na ethĩwa ũvuku nĩwĩkwatĩle moko makwa:'),
('kam', 'JOB', 31, 8, 'Nĩvo ĩndĩ nĩvuĩe, na ũngĩ nĩaye; Ĩĩ, ũsyao wa mũunda wakwa ũkũwe na mĩi.'),
('kam', 'JOB', 31, 9, 'Ethĩwa ngoo yakwa nĩyasengasengiwe nĩ mũndũ mũka, Nakwa neteelile mũomonĩ wa mũtũi wakwa;'),
('kam', 'JOB', 31, 10, 'Nĩvo ĩndĩ kĩveti kyakwa nĩkĩthiĩe ũngĩ, Na angĩ makĩkomee.'),
('kam', 'JOB', 31, 11, 'Nũndũ yĩu nĩ ĩvĩtyo yai; Ĩĩ, nĩ naĩ ya kũsilĩlwa nĩ asili:'),
('kam', 'JOB', 31, 12, 'Nũndũ nĩ mwaki ũla ũminaa kũvika wanangĩko, Na ũkakũanĩsya na mĩi wingĩvo wakwa w’onthe.'),
('kam', 'JOB', 31, 13, 'Ethĩwa nĩnĩvũthĩtye ũvoo wa mũthũkũmi wakwa mũndũ mũũme kana mũndũ mũka, Yĩla maneenanisye nakwa;'),
('kam', 'JOB', 31, 14, 'Ngeeka ata ĩndĩ yĩla Ngai wĩũkĩla? Na yĩla wĩsila, ngamũsũngĩa ata?'),
('kam', 'JOB', 31, 15, 'Ũla wambũmbĩe ĩvunĩ ndaamũmba? Na ti ũmwe ũla watũmbĩe ĩvunĩ?'),
('kam', 'JOB', 31, 16, 'Ethĩwa nĩnaimie ngya kĩla syendete, Kana kũtuma metho ma mũndũ mũka ndiwa maseekea,'),
('kam', 'JOB', 31, 17, 'Kana naya kĩlungu kyakwa nĩ nyioka, Na ũla wakw’ĩĩwe nĩ ĩthe ndaaya kyakyo'),
('kam', 'JOB', 31, 18, '(Aiee, kuma wana wakwa nĩweanie e nakwa ta ũkwĩana e na ĩthe, Na ũ mũndũ mũka nĩnĩmũtongoeetye kuma o nauma ĩvunĩ ya mwaitũ);'),
('kam', 'JOB', 31, 19, 'Ethĩwa nĩnoonie mũndũ o na wĩva akyaa nũndũ wa kwaĩwa nĩ ngũa, Kana mũthĩni ate na kya kwĩvw’ĩka;'),
('kam', 'JOB', 31, 20, 'Ethĩwa kĩnyunyu kyake kĩtyaangathima, Na ethĩwa nake ndaaĩkĩwa muutĩa nĩ w’ĩa wa malondu makwa;'),
('kam', 'JOB', 31, 21, 'Ethĩwa nĩnĩmũkĩlĩĩlye ũla wakw’ĩĩwe nĩ ĩthe kw’oko kwakwa, Nĩkwĩthĩwa nĩnoonie ũtethyo wakwa mbingĩlonĩ:'),
('kam', 'JOB', 31, 22, 'Nĩvo ĩndĩ kĩtuo kyakwa kĩkavũkĩle kĩkombenĩ kya kĩtuo, Na kw’oko kwakwa nĩkũtũlĩkĩle ĩvĩndĩnĩ.'),
('kam', 'JOB', 31, 23, 'Nũndũ wanangĩko mũnene wumĩte kwa Ngai nĩ ũtĩsyo kwakwa, Na kwondũ wa ũnene wake nditonya kwĩka ũndũ.'),
('kam', 'JOB', 31, 24, 'Ethĩwa ndw’ĩte thaavu wĩkwatyo wakwa, Na kũtavya thaavu mũseo, Nue ũĩkĩĩi wakwa;'),
('kam', 'JOB', 31, 25, 'Ethĩwa nĩnatanie nũndũ wa ũthwii wakwa kwingĩva, Na nĩkwĩthĩwa kw’oko kwakwa nĩkwosie mwingĩ;'),
('kam', 'JOB', 31, 26, 'Ethĩwa nĩnasiisye syũa yĩla yatisaa, Kana mwei ũkĩendeea ũtisunĩ,'),
('kam', 'JOB', 31, 27, 'Na ngoo yakwa yasengasengwa na kĩmbithĩ, Na kanyw’a wakwa wamumunya kw’oko kwakwa:'),
('kam', 'JOB', 31, 28, 'Ĩsu nayo nĩ naĩ ya kũsilĩlwa nĩ asili; Nũndũ nĩthĩwa nakaĩa Ngai ũla wĩ ĩũlũ.'),
('kam', 'JOB', 31, 29, 'Ethĩwa nĩnĩtanie nũndũ wa wanangĩko wa ũla wamenie, Kana kwĩyũkĩlya yĩla ũthũku wamũkwatie'),
('kam', 'JOB', 31, 30, '(Ĩĩ, ndyaaeka kanyw’a wakwa wĩke naĩ Kwondũ wa kwĩtya thayũ wake na kĩumo);'),
('kam', 'JOB', 31, 31, 'Ethĩwa andũ ma ĩeema yakwa matyaasya, Nũũ ũtonya kwona ũmwe ũla ũtaavũnw’a nĩ nyama syake?'),
('kam', 'JOB', 31, 32, '(Mwĩkali wa ũeni ndaakoma nzĩanĩ nene; Ĩndĩ nĩnamũvingũĩaa mũendi wa kyalo mĩomo yakwa);'),
('kam', 'JOB', 31, 33, 'Ethĩwa ta Atamu nĩnavw’ĩkie mavĩtyo makwa, Kwondũ wa kũvitha naĩ yakwa kĩthũinĩ kyakwa,'),
('kam', 'JOB', 31, 34, 'Nũndũ nĩnakĩie wingĩ wa andũ, Na kĩvũthya kya mĩvĩa ya andũ nĩkyandĩsisye, Na ĩndĩ navindya, na ndyaaumaala mũomonĩ—'),
('kam', 'JOB', 31, 35, 'A! Kethĩwa nĩ na ũmwe wa kũmbĩthukĩĩsya! (Sisya, saii wakwa nĩ ũũ, Mwene Vinya W’onthe nanzũngĩe) Na kethĩwa nĩ na ũvingan’yo ũla nthũ yakwa ĩandĩkĩte!'),
('kam', 'JOB', 31, 36, 'Vate ndĩi nĩũkua kĩtuonĩ kyakwa; Nĩwoveea kwakwa ta ngovia ya ũsumbĩ:'),
('kam', 'JOB', 31, 37, 'Nĩmũtavya ũtalo wa matambya makwa; Nĩmũthengeea ta mũnene wĩ mbee ũsumbĩnĩ.'),
('kam', 'JOB', 31, 38, 'Ethĩwa nthĩ yakwa nĩnĩũndonzanĩlya, Na mĩkao yayo kũĩa vamwe;'),
('kam', 'JOB', 31, 39, 'Ethĩwa nĩnaĩe mosyao mayo vate mbesa, Kana nĩnatumie ene mayo masya thayũ woo:'),
('kam', 'JOB', 31, 40, 'Thangila nimee vandũ va nganũ, Na maia mathũku vandũ va mbaale. Ndeto sya Yovu nĩsyathela.'),
('kam', 'JOB', 32, 1, 'Na ĩndĩ andũ asu atatũ nĩmaekie kũsũngĩa Yovu, nũndũ aĩ mũlũngalu methonĩ make mwene.'),
('kam', 'JOB', 32, 2, 'Nĩvo ĩndĩ ũthilĩku wa Eliu mwana wa Mbalakeli Mũvusi, wa mũvĩa wa Lamu, wakanie: ũthilĩku wake wamwakanĩa Yovu, nĩkwĩthĩwa nĩwetalile mwene mũlũngalu kwĩ kũtalĩla Ngai ũlũngalu.'),
('kam', 'JOB', 32, 3, 'O na ĩngĩ ũthilĩku wake wamakanĩa anyanyae make atatũ, nĩkwĩthĩwa matyaĩ na ũsũngĩo, ĩndĩ matw’a Yovu nĩ mũvĩtan’ya.'),
('kam', 'JOB', 32, 4, 'Eliu aĩ aneteela kũneena na Yovu, nĩkwĩthĩwa asu maĩ akũũ kwĩ we.'),
('kam', 'JOB', 32, 5, 'Na yĩla Eliu wonie kana vati ũsungĩo kanyw’anĩ wa andũ asu atatũ, ũthilĩku wake wakana.'),
('kam', 'JOB', 32, 6, 'Na Eliu mwana wa Mbalakeli asũngĩa na asya, Nyie nĩ mũnini, na inyw’ĩ mwĩ akũũ mũno; Kwondũ wa ũu nĩneesiĩĩe, na nakĩa kũmwon’ya ũndũ ngwona.'),
('kam', 'JOB', 32, 7, 'Naisye, Mĩthenya nĩyaĩle kũneena, Na wingĩ wa myaka nĩwaĩle kũmanyĩsya ũĩ.'),
('kam', 'JOB', 32, 8, 'Ĩndĩ kwĩ veva nthĩnĩ wa mũndũ, Na mĩvevo ya Mwene Vinya W’onthe nĩmanengae ũmanyi.'),
('kam', 'JOB', 32, 9, 'Ti ala anene me na ũĩ, Kana akũũ ala mamanyaa ũsili wa katĩ.'),
('kam', 'JOB', 32, 10, 'Kwondũ wa ũu nasya, Mbĩthukĩĩsyai; Nakwa ngoonan’ya ũndũ ngwona.'),
('kam', 'JOB', 32, 11, 'Sisyai, nĩneteelile ndeto syenyu, Neethukĩĩsya nĩw’e mosũanĩo menyu, Yĩla mũũmanthaa ũndũ wa kũneena.'),
('kam', 'JOB', 32, 12, 'Ĩĩ, nĩnĩmwĩthukĩĩsye, Na, sisyai, vatyaĩ waamwĩtĩkĩlĩthya Yovu, Kana ũla wasũngĩie ndeto syake, katĩ wenyu.'),
('kam', 'JOB', 32, 13, 'Ĩsũvĩei mũtikese kũneena, Nĩtwonete ũĩ; Ngai nũtonya kũmũkĩlya vinya, ti mũndũ:'),
('kam', 'JOB', 32, 14, 'Nũndũ ndaambelekelya ndeto syake; O nakwa ndikamũsũngĩa na ndeto syenyu.'),
('kam', 'JOB', 32, 15, 'Nĩmeũseng’a, matisũngĩa ĩngĩ: Mati na ndeto ya kũneena.'),
('kam', 'JOB', 32, 16, 'Nakwa ngeeteela, nũndũ matiũneena, Nũndũ maũngeme, na matikũsũngĩa ĩngĩ?'),
('kam', 'JOB', 32, 17, 'Nakwa nĩngũsũngĩa ngalĩ ĩ yakwa, O nakwa ngoonan’ya ũndũ ngwona.'),
('kam', 'JOB', 32, 18, 'Nũndũ nĩ mũsũu ndeto; Nĩngũthing’ĩĩw’a nĩ veva nthĩnĩ wakwa.'),
('kam', 'JOB', 32, 19, 'Sisyai, kĩthũi kyakwa nĩ ta mbinyu ĩte na ũmĩlo; Ta tũthatwa tweũ twa mbinyu tũla tũkilyĩ kwatũka.'),
('kam', 'JOB', 32, 20, 'Nakwa nĩngũneena, nĩ kana nĩvuũkw’e; Ngatumũkya ilomo syakwa na kũsũngĩa.'),
('kam', 'JOB', 32, 21, 'Nĩngũmwĩsũva, ndikone mũndũ ta kĩndũ; O na ndikamũnenga mũndũ o na wĩva masyĩtwa ma ũmũkathĩĩa.'),
('kam', 'JOB', 32, 22, 'Nũndũ ndyĩsĩ kũnengane masyĩtwa ma kũkathĩĩa; Ethĩwa nĩ ũu Mũmbi wakwa nĩkũmbosa mĩtũkĩ.'),
('kam', 'JOB', 33, 1, 'Ĩndĩ, Yovu, nĩngũkwĩsũva, ĩw’a kũneena kwakwa, Noiĩthukĩĩsya ndeto syakwa syonthe.'),
('kam', 'JOB', 33, 2, 'Sisya yu, nĩnathamĩtye kanyw’a wakwa; Ũĩmĩ wakwa nũneenete kanyw’anĩ wakwa.'),
('kam', 'JOB', 33, 3, 'Ndeto syakwa ikaneena ũlũngalu wa ngoo yakwa; Na ũndũ ũla ilomo syakwa syĩsĩ nĩw’o ikaneena w’o.'),
('kam', 'JOB', 33, 4, 'Veva wa Ngai nĩwambũmbie, Na mĩthũmũ ya Mwene Vinya W’onthe nĩnengae nyie thayũ.'),
('kam', 'JOB', 33, 5, 'Ethĩwa nũtonya, nzũngĩa; Neena ndeto syaku iatĩĩanĩe mbee wakwa, ũngama.'),
('kam', 'JOB', 33, 6, 'Sisya, nĩilyĩ kwa Ngai o ũndũ ũilyĩ: O nakwa nĩnoombiwe na yũmba.'),
('kam', 'JOB', 33, 7, 'Sisya, ũtĩsyo wakwa ndũkakũtelemya, O na kũvivinya kwakwa kũikethĩwa kũito ĩũlũ waku.'),
('kam', 'JOB', 33, 8, 'Nĩ w’o nũneenete ngĩw’a, Na nĩnĩw’ĩte wasya wa ndeto syaku, ũkyasya,'),
('kam', 'JOB', 33, 9, 'Nyie nĩ mũtheu, vate naĩ; Ndi na ĩvĩtyo, o na vati ũthũku nthĩnĩ wakwa:'),
('kam', 'JOB', 33, 10, 'Sisya, nũntheaa, Nũndalaa nĩ mũmaitha wake;'),
('kam', 'JOB', 33, 11, 'Nĩwĩkĩaa maũũ makwa mĩtĩnĩ ya kũmoveea, Nũthianaa mĩendele yakwa yonthe.'),
('kam', 'JOB', 33, 12, 'Sisya, nĩngũũsũngĩa, ũndũnĩ ũũ ndwĩ mũlũngalu; Nũndũ Ngai nĩ mũnene kwĩ mũndũ.'),
('kam', 'JOB', 33, 13, 'Nĩkĩ ũũkĩlan’ya vinya nake, Nũndũ ndaumasya ũtalo wa ũndũ o na wĩva wake?'),
('kam', 'JOB', 33, 14, 'Nũndũ Ngai nũneenaa ĩmwe, Ĩĩ kelĩ, o na kau mũndũ ndonaa ta ũndũ.'),
('kam', 'JOB', 33, 15, 'Ndotonĩ, woninĩ wa ũtukũ, Andũ makomete too mũnene, Momboesye kĩtandanĩ;'),
('kam', 'JOB', 33, 16, 'Nĩvo ĩndĩ ũvingũaa matũ ma andũ, Na kũsiĩla ũmanyĩsyo woo,'),
('kam', 'JOB', 33, 17, 'Nĩ kana amũvete mũndũ ũndũnĩ ũla wendaa kwĩka, Na kũmũvitha mũndũ ngathĩĩo;'),
('kam', 'JOB', 33, 18, 'Nũsiĩĩaa thayũ wake ndũkalike yĩla ĩimanĩ, Na thayũ wake ndũkaw’e nĩ ũvyũ.'),
('kam', 'JOB', 33, 19, 'Nake nũkũnĩawa nĩ kyalya ũkomonĩ wake, Na ĩteta yĩtatw’ĩkanaa mavĩndĩnĩ make;'),
('kam', 'JOB', 33, 20, 'Na kwondũ wa ũu thayũ wake nũthĩthaa lĩu, Na ngoo yake lĩu mũseo.'),
('kam', 'JOB', 33, 21, 'Nyama yake nĩ mine, ndĩtonya kwoneka; Na mavĩndĩ make ala mataĩ moneku nĩmaumĩlĩte.'),
('kam', 'JOB', 33, 22, 'Ĩĩ, ngoo yake nĩthengeee yĩla ĩima, Na thayũ wake ala manangaa.'),
('kam', 'JOB', 33, 23, 'Ethĩwa ve mũlaĩka vamwe nake, Mũvuan’ya, ũmwe katĩ wa ngili, Kũmwon’ya mũndũ ũla ũseo kwake;'),
('kam', 'JOB', 33, 24, 'Nĩvo ĩndĩ Ngai nĩ mũseo kwake, na easya, Mũvonokye ndakatheee yĩla ĩimanĩ, Nĩnonete mbovosya.'),
('kam', 'JOB', 33, 25, 'Mwĩĩ wake ũkeethĩwa mwololo kwĩ wa kana; Nũsyokaa mĩthenyanĩ ya wana wake.'),
('kam', 'JOB', 33, 26, 'Nũmũvoyaa Ngai, nake nũmwĩkaa ũseo, Ũkethĩa nĩwonaa ũthyũ wake na ũtanu: Na nũmũtũngĩaa mũndũ ũlũngalu wake.'),
('kam', 'JOB', 33, 27, 'Nĩwĩnĩaa mbee wa andũ, na kwasya, Nĩnĩvĩtĩtye, na kwelelũkasya kĩla kya w’o, Na ndyaaunĩka:'),
('kam', 'JOB', 33, 28, 'Nĩwovoetye ngoo yakwa ndĩkatheee yĩla ĩimanĩ, Na thayũ wakwa ũkoona kyeni.'),
('kam', 'JOB', 33, 29, 'Sisya, maũndũ asu onthe Ngai nĩwĩkaa, Kelĩ, ĩĩ katatũ, kwa mũndũ,'),
('kam', 'JOB', 33, 30, 'Atũnge ngoo yake kuma yĩla ĩimanĩ, Nĩ kana eekĩwe kyeni nĩ kyeni kya ala me thayũ.'),
('kam', 'JOB', 33, 31, 'Sisya nesa, we Yovu, mbĩthukĩĩsya: Vindya, nakwa nĩngũneena.'),
('kam', 'JOB', 33, 32, 'Ethĩwa wĩ na ũndũ wa ũneena, nzũngĩa: Neena, nũndũ nĩngwenda ũkũtala mũlũngalu.'),
('kam', 'JOB', 33, 33, 'Ethĩwa ti ũu, mbĩthukĩĩsya: Vindya, na ngakũmanyĩsya ũĩ.'),
('kam', 'JOB', 34, 1, 'Na ũndũ ũngĩ Eliu asũngĩa na asya,'),
('kam', 'JOB', 34, 2, 'Ĩw’ai ndeto syakwa, ĩnyw’ĩ andũ oĩ; Na ngunũĩai matũ, inyw’ĩ ala mwĩ na ũmanyi.'),
('kam', 'JOB', 34, 3, 'Nũndũ kũtũ nĩkũtataa ndeto, O tondũ kaakaa ũsamaa lĩu.'),
('kam', 'JOB', 34, 4, 'Twĩnyuvĩe ũndũ ũla ũlũngalu: Tũmanye katĩ waitũ ene ũla ũseo.'),
('kam', 'JOB', 34, 5, 'Nũndũ Yovu nũneenete, Nyie nĩ mũlũngalu, Na Ngai nũvetete kĩanda kyakwa:'),
('kam', 'JOB', 34, 6, 'O na kau ũlũngalu wakwa wĩ vo nĩngũtalwa nĩ mũneeni wa ũvũngũ; Wũkite wakwa ndũvoeka, o na ndi na ĩvĩtyo.'),
('kam', 'JOB', 34, 7, 'Nĩ mũndũ wĩva ũilyĩ Yovu, Ũla ũnyusaa kĩvũthya ta manzĩ,'),
('kam', 'JOB', 34, 8, 'Ũla ũtindanasya na eki ma naĩ, Na kũtambũkanasya na andũ athe?'),
('kam', 'JOB', 34, 9, 'Nũndũ nake nũneenete, kũtiunaa mũndũ na kĩndũ Kwĩtan’ya nthĩnĩ wa Ngai.'),
('kam', 'JOB', 34, 10, 'Kwondũ wa ũu mbĩthukĩĩsyai, inyw’ĩ andũ mwĩ na ũmanyi: Nĩkwĩthĩwe kũasa na Ngai, atĩ eke ũthũku, Na kũasa na Mwene Vinya W’onthe, atĩ eke naĩ.'),
('kam', 'JOB', 34, 11, 'Nũndũ akamũĩva mũndũ wĩa wake, Na kũtuma kĩla mũndũ osa kwĩanana na mĩendele yake.'),
('kam', 'JOB', 34, 12, 'Ĩĩ, nĩ w’o ki, Ngai ndakeka ũthũku, O na Mwene Vinya W’onthe ndakelelũkya ũsili wa katĩ.'),
('kam', 'JOB', 34, 13, 'Nũũ ũla wamũnengie wĩaĩo ĩũlũ wa nthi? Kana nũũ ũla wiĩte nthĩ yonthe?'),
('kam', 'JOB', 34, 14, 'Ethĩwa akeelekelya ngoo yake mwene kwĩsisya, Ethĩwa akeeyũmbanĩsya veva wake na mĩthũmũ yake;'),
('kam', 'JOB', 34, 15, 'Mĩĩ yonthe ĩkaaa vamwe, Na mũndũ akatw’ĩka o kĩtoo ĩngĩ.'),
('kam', 'JOB', 34, 16, 'Ethĩwa yu wĩ na ũmanyi, ĩw’a ũũ: Ĩthukĩĩsye wasya wa ndeto syakwa.'),
('kam', 'JOB', 34, 17, 'O na ũmwe ũla ũmenaa ũsili wa katĩ akasumbĩka? Na ũkamũtw’a mũvĩtan’ya ũla mũlũngalu na wĩ ũtonyi?—'),
('kam', 'JOB', 34, 18, 'Ũla ũtavasya mũsumbĩ, Wĩ mũvuku, Kana ala me ndaĩa, Mwĩ athũku;'),
('kam', 'JOB', 34, 19, 'Ũla ũtonaa anene me mbee ũsumbĩnĩ ta kĩndũ, Kana kũsisya athwii kũvĩtũka ngya; Nũndũ onthe nĩ wĩa wa moko make.'),
('kam', 'JOB', 34, 20, 'Kavinda kanini nĩmakusaa o ũtukũ katĩ; Andũ nĩmathingithaw’a, na maivĩta, Na ala me na ũtonyi nĩmatwaawa vate kw’oko.'),
('kam', 'JOB', 34, 21, 'Nũndũ metho make nĩmasiasya nzĩa sya mũndũ, Na nĩwonaa mĩendele yake yonthe.'),
('kam', 'JOB', 34, 22, 'Vati kĩvindu, kana mũki mũnene, Vala eki ma naĩ matonya kwĩvitha.'),
('kam', 'JOB', 34, 23, 'Nũndũ nde vata kũsũanĩanga ũndũ wa mũndũ, Kana eũngama mbee wa Ngai ũsilĩlonĩ.'),
('kam', 'JOB', 34, 24, 'Nũtilangaa ngũmbaũ ilungu na nzĩa itamanyĩka, Na kwia angĩ vandũ voo.'),
('kam', 'JOB', 34, 25, 'Kwondũ wa ũu nũsiasya mawĩa moo; Na nũmakũlumanasya ũtukũ, na kwondũ wa ũu makyanangwa.'),
('kam', 'JOB', 34, 26, 'Nũmakũnaa ta andũ athũku Ala angĩ mamasyaĩtye;'),
('kam', 'JOB', 34, 27, 'Nũndũ nĩmaathũkie maeka kũmũatĩĩa, Na matyaaĩtĩkĩla nzĩa yake o na yĩva:'),
('kam', 'JOB', 34, 28, 'Kwondũ wa ũu matuma kĩĩo kya ngya kĩmũvikĩa, Na eew’a kĩĩo kya ala mathĩnaw’a.'),
('kam', 'JOB', 34, 29, 'Yĩla ũnenganae ũkilyo, nũũ ĩndĩ ũtonya kũtw’a nĩ mũvĩtan’ya? Na yĩla ũvithaa ũthyũ wake, nũũ ĩndĩ ũtonya kũmwona? Nĩ ũndũ ũmwe ethĩwa ũu wĩkawa kwa mbaĩ, kana kwa mũndũ:'),
('kam', 'JOB', 34, 30, 'Nĩ kana ũla ũtakĩaa Ngai ndakasũmbĩke, Nĩ kana vatikethĩwe ũmwe wa kũtea andũ.'),
('kam', 'JOB', 34, 31, 'Nũndũ ve ũmwe waamwĩa Ngai, Nĩnũmĩĩsye kũkũnwa, ndikavĩtya ĩngĩ:'),
('kam', 'JOB', 34, 32, 'Ũndũ ũla ndekwona manyĩsya nyie: Ethĩwa nĩnĩkĩte naĩ, ndikamĩka ĩngĩ?'),
('kam', 'JOB', 34, 33, 'Ũĩvanĩsyo wake ũkeethĩwa ta ũndũ ũkwenda, ũndũ ũkũlea? Nũndũ no mũvaka we ũnyuve, ti i nyie: Kwondũ wa ũu neena ũndũ wĩsĩ.'),
('kam', 'JOB', 34, 34, 'Andũ me na ũmanyi makambĩa, Ĩĩ, kĩla mũndũ mũĩ ũla ũmbĩw’aa:'),
('kam', 'JOB', 34, 35, 'Yovu aneenaa ate na ũmanyi, Na ndeto syake ti mbũĩ.'),
('kam', 'JOB', 34, 36, 'Nenda kethĩwa Yovu ũkatatwa kũvika mũminũkĩlyo, Nũndũ wake kũsũngĩa ta andũ athũku.'),
('kam', 'JOB', 34, 37, 'Nũndũ nĩwongeleelaa naĩ yake ũng’endu; Nũkũnangĩaa mbĩ syake katĩ waitũ, Na kwingĩvya ndeto syake vala ve Ngai.'),
('kam', 'JOB', 35, 1, 'Na ũndũ ũngĩ Eliu asũngĩa na asya,'),
('kam', 'JOB', 35, 2, 'Nũkũsũanĩa ũu nũkwaĩle, Kana nũkwasya, Ũlũngalu wakwa nĩ mũnene kwĩ wa Ngai,'),
('kam', 'JOB', 35, 3, 'Ũndũ ũkwasya, Kũkeethĩwa ũtandĩthyo mwaũ kwaku? Na, Ngeethĩwa na ũtandĩthyo mwaũ, kũvĩtũka kethĩwa nĩneekaa naĩ?'),
('kam', 'JOB', 35, 4, 'Nĩngũũsũngĩa, Na atindan’ya maku me naku.'),
('kam', 'JOB', 35, 5, 'Sisya matu, noyona; Ĩlooele yayaya, yĩla yĩ ĩũlũ kwĩ we.'),
('kam', 'JOB', 35, 6, 'Ethĩwa nũvĩtĩtye, ũmwĩkaa ata? Na ethĩwa mavĩtyo maku nĩ mongeleku, ũmwĩkaa ata?'),
('kam', 'JOB', 35, 7, 'Ethĩwa wĩ mũlũngalu, ũmũnengae kyaũ? Kana nake osaa kyaũ kw’okonĩ kwaku?'),
('kam', 'JOB', 35, 8, 'Ũthũku waku nũtonya kũthĩn’ya mũndũ o taku; Na ũlũngalu waku nũtonya kũuna mwana wa mũndũ.'),
('kam', 'JOB', 35, 9, 'Nũndũ wa wingĩ wa mathĩna andũ nĩmakayaa; Nũndũ wa kw’oko kwa ũla wĩ ũtonyi nĩmauaa mbu.'),
('kam', 'JOB', 35, 10, 'Ĩndĩ vai ũmwe ũkwasya, Ngai Mũmbi wakwa aĩva? Ũla ũnenganae mbathi ũtukũ,'),
('kam', 'JOB', 35, 11, 'Ũla ũtũmanyĩasya kũvĩtũka nyamũ sya nthĩ, Na kũtũĩvya kwĩ nyũnyi sya yayaya?'),
('kam', 'JOB', 35, 12, 'Nĩmaĩĩaa vau, ĩndĩ vai ũla ũsũngĩaa, Nũndũ wa ngathĩĩo ya andũ athũku.'),
('kam', 'JOB', 35, 13, 'Vate ndĩi Ngai ndakew’a kĩĩo kĩthei, O Mwene Vinya W’onthe ndakakĩtĩkĩla.'),
('kam', 'JOB', 35, 14, 'Nata yĩla waasya ndũmwonaa, Ũvoo wĩ mbee wake, naku nũmweteelaa!'),
('kam', 'JOB', 35, 15, 'Ĩndĩ yu, nũndũ ndaasila ũthatunĩ wake, O na ndasiasya mũno wĩnenevyo;'),
('kam', 'JOB', 35, 16, 'Kwondũ wa ũu Yovu nĩwathamasya kanyw’a wake mana; Nĩwingĩvasya ndeto vate ũmanyi.'),
('kam', 'JOB', 36, 1, 'O na Eliu aendeea, na asya,'),
('kam', 'JOB', 36, 2, 'Ndeka vanini, na nĩngũkwon’ya; Nũndũ nĩ na ũndũ wa kũneena ngalĩ ĩ ya Ngai.'),
('kam', 'JOB', 36, 3, 'Nĩngũete ũmanyi wakwa kuma kũasa, Na kũmũweta Mũmbi wakwa ũlũngalu.'),
('kam', 'JOB', 36, 4, 'Nũndũ nĩ w’o ndeto syakwa ti sya ũvũngũ: Ũmwe mwĩanĩu ũmanyinĩ e naku.'),
('kam', 'JOB', 36, 5, 'Sisya, Ngai e na ũtonyi, na ndavũthasya mũndũ o na wĩva: Nake e na ũtonyi vinyanĩ wa ũmanyi.'),
('kam', 'JOB', 36, 6, 'Ndasũvĩaa thayũ wa ũla mũthũku, Ĩndĩ nũnengae ala mathĩnaw’a kĩanda kyoo.'),
('kam', 'JOB', 36, 7, 'Ndaumasya metho make vala ve alũngalu: Ĩndĩ vamwe na asumbĩ me kĩvĩlanĩ kya ũsumbĩ Nũmaiaa tene na tene, nao nĩmanenevaw’a.'),
('kam', 'JOB', 36, 8, 'Na ethĩwa nĩmovawa na mbĩngũ, Na kũkwatw’a na ndii sya thĩna;'),
('kam', 'JOB', 36, 9, 'Nĩvo ĩndĩ ũmonasya wĩa woo, Na mavĩtyo moo, atĩ nĩmekĩte na ngathĩĩo.'),
('kam', 'JOB', 36, 10, 'O na nũvingũaa kũtũ kwoo mose ũmanyĩsyo, Na kwĩaĩa masyoke kuma naĩnĩ.'),
('kam', 'JOB', 36, 11, 'Ethĩwa nĩmethukĩĩasya na kũmũthũkũmaa, Makekalya mĩthenya yoo ũunĩkonĩ, Na myaka yoo motanunĩ.'),
('kam', 'JOB', 36, 12, 'Ĩndĩ ethĩwa matikethukĩĩsya, makaaa kwondũ wa ũvyũ, Na makakw’a mate na ũmanyi.'),
('kam', 'JOB', 36, 13, 'Ĩndĩ ala matakĩaa Ngai ngoonĩ nĩmeyiĩaa ũthatu: Matikayaa matethw’e yĩla ũnũũmova.'),
('kam', 'JOB', 36, 14, 'Nĩmakusaa wananĩ, Na thayũ woo nĩwaĩaa katĩ wa ala avuku.'),
('kam', 'JOB', 36, 15, 'Nũvonokasya ala mathĩnaw’a kwondũ wa thĩna woo, Na nũvingũaa kũtũ kwoo me ũnyamaonĩ.'),
('kam', 'JOB', 36, 16, 'Ĩĩ, enda ũkũtongoesya wume ũnyamaonĩ Ũkũlilya vandũ vathanthau, vala vate vavivinyanu; Na kĩla kĩiawa mesanĩ yaku kĩkeethĩwa kyusĩe ũnou.'),
('kam', 'JOB', 36, 17, 'Ĩndĩ nĩwusũĩte ũsilĩlo wa ala athũku: Ũsilĩlo na ũsili wa katĩ nikũkwete.'),
('kam', 'JOB', 36, 18, 'Ndũkaeke ũthilĩku ũkũthokoan’ye ũndũ wa makũna; O na wingĩ wa mbovosya ndũkakwelelũkye.'),
('kam', 'JOB', 36, 19, 'Kĩĩo kyaku kĩkaũtethya, ndũkethĩwe na thĩna, Kana mavinya onthe ma vinya waku?'),
('kam', 'JOB', 36, 20, 'Ndũkende ũtukũ, Yĩla andũ mavetawa vandũ voo.'),
('kam', 'JOB', 36, 21, 'Ĩsuvĩe, ndũketĩkĩle ũthũku: Nũndũ ũu nũnyuvĩte kwĩ thĩna.'),
('kam', 'JOB', 36, 22, 'Sisya, Ngai nĩwĩkaa na ũnene vinyanĩ wake: Nũũ mũmanyĩsya ũilyĩ take?'),
('kam', 'JOB', 36, 23, 'Nũũ ũla ũmwĩaĩĩte nzĩa yake? Kana nũũ ũtonya kwasya, Nĩwĩkĩte ũla ũte ũlũngalu?'),
('kam', 'JOB', 36, 24, 'Lilikana ũtaĩe wĩa wake, Ũla andũ mainĩte ũndũ waw’o.'),
('kam', 'JOB', 36, 25, 'Andũ onthe nĩmawonete; Mũndũ nũwonaa wĩ kũasa.'),
('kam', 'JOB', 36, 26, 'Sisya, Ngai nĩ mũnene, na tũtimwĩsĩ; Ũtalo wa myaka yake ndũmanthĩka.'),
('kam', 'JOB', 36, 27, 'Nũndũ nũkusasya ĩũlũ mavoloto ma manzĩ, Ala mavolotangasya mbua kuma mũkinĩ wamo,'),
('kam', 'JOB', 36, 28, 'Ĩla matu mamyonosya Na kũmĩvolotangĩlya mũndũ mbingĩ mũno.'),
('kam', 'JOB', 36, 29, 'Ĩĩ, ve ũmwe ũtonya kũmanya ũnyaĩĩku wa mathweo, Itundumo sya ĩlwanda yake?'),
('kam', 'JOB', 36, 30, 'Sisya, nũnyaĩĩkasya kyeni kyake kũmũthyũlũlũka; Na nũvw’ĩkaa nthĩ yĩ ungu wa ũkanga.'),
('kam', 'JOB', 36, 31, 'Nũndũ kwondũ wa maũndũ asu nũsilĩlaa ngo sya andũ; Nũnenganae lĩu mwingĩ.'),
('kam', 'JOB', 36, 32, 'Nũvw’ĩkaa moko make ũtisi, Na kũwĩaĩa ũathe vala vatw’ĩtwe.'),
('kam', 'JOB', 36, 33, 'Kĩlonzo kyaw’o nĩkĩtavanasya ũndũ wake, O na indo nasyo ũndũ wa kĩuutani kĩla kyũkĩte.'),
('kam', 'JOB', 37, 1, 'Ĩĩ, kwondũ wa ũu ngoo yakwa nitetemaa, Na kumw’a vandũ vayo.'),
('kam', 'JOB', 37, 2, 'Ĩw’a, ĩĩ, ĩw’a kĩlonzo kya wasya wake, Na kĩumo kĩla kyumaa kanyw’anĩ wake.'),
('kam', 'JOB', 37, 3, 'We nũkĩtũmaa kĩende ĩtheo wa ĩtu yonthe, Na ũtisi wake kũvika itulu sya nthĩ.'),
('kam', 'JOB', 37, 4, 'Ĩtina waw’o wasya nũlitũkaa; Nũtundumaa na wasya wa ũnene wake; Na ndasiĩĩaa motisi yĩla wasya wake wĩw’ĩka.'),
('kam', 'JOB', 37, 5, 'Ngai nũtundumaa na ũseng’ya na wasya wake; Nĩwĩkaa maũndũ manene, ala ithyĩ tũtatonya kũmamanya.'),
('kam', 'JOB', 37, 6, 'Nũndũ nũtavasya ĩa, Valũka we ĩũlũ wa nthĩ; No ta ũu mũono wa mbua, O na mĩono ya mbua yake yĩ vinya.'),
('kam', 'JOB', 37, 7, 'Nũsiĩĩaa kw’oko kwa kĩla mũndũ, Nĩ kana andũ onthe ala wombie mamanye ũu.'),
('kam', 'JOB', 37, 8, 'Nĩvo nyamũ ilikaa mawĩvithonĩ, Na kwĩkalaa isumonĩ syasyo.'),
('kam', 'JOB', 37, 9, 'Kuma motheinĩ ma ngalĩ ya ĩtheo kĩuutani nĩkyũkaa, Na mbevo kuma ngalĩ ya ĩũlũ.'),
('kam', 'JOB', 37, 10, 'Kwondũ wa nĩthũmũ ya Ngai manzĩ momĩtw’e nĩ mbevo nĩmonekaa; Na ũthanthau wa manzĩ ũikoomatana.'),
('kam', 'JOB', 37, 11, 'Ĩĩ, nũkuĩthasya ithweo ĩkamu manzĩ maingĩ; Nũtambũũkasya ĩthweo yĩ ũtisi wake.'),
('kam', 'JOB', 37, 12, 'Na nĩyĩthyũũawa kwondũ wa kũtongoew’a nĩwe, Nĩ kana meke ũndũ o na wĩva ũla ũnũũmeaĩa Ĩũlũ wa nthĩ yĩ andũ;'),
('kam', 'JOB', 37, 13, 'Ethĩwa nĩ kwondũ wa ũkan’yo, kana kwondũ wa nthĩ yake, Kana kwondũ wa ũseo wĩ wendo, nũtumaa yũka.'),
('kam', 'JOB', 37, 14, 'Ĩthukĩĩsye ũũ, we Yovu: Ũngama, ũsũanĩe mawĩa ma ũseng’ya ma Ngai.'),
('kam', 'JOB', 37, 15, 'Nĩwĩsĩ ũndũ Ngai wĩaa wĩaĩo wake ĩũlũ wamo, Na kũtuma ũtisi wa ĩthweo yake ũtisa?'),
('kam', 'JOB', 37, 16, 'Naku nĩwĩsĩ ũndũ mathweo masũnzũlĩtw’e, Mawĩa ma ũseng’ya ma ũla mwĩanĩu ũmanyinĩ?'),
('kam', 'JOB', 37, 17, 'Ũndũ ngũa syaku syĩ na muutĩa, Yĩla nthĩ ĩuĩtye nũndũ wa kĩseve kyumĩte ngalĩ ya ĩtheo?'),
('kam', 'JOB', 37, 18, 'Naku nũtonya kũtambũũkya ĩtu wĩ nake, Yĩla yĩ vinya ta kĩsisyo kĩseũvĩtw’e na syĩndũ itwekethetw’e?'),
('kam', 'JOB', 37, 19, 'Tũmanyĩsye ũla twĩneena nake; Nũndũ tũtitonya kũneena tũlũngalĩtye nũndũ wa kĩvindu.'),
('kam', 'JOB', 37, 20, 'Akatavw’a kana nĩenda kũneena? Kana mũndũ akenda kũmelw’a vyũ?'),
('kam', 'JOB', 37, 21, 'Na yu andũ matyonaa kyeni kĩla kĩtisaa matunĩ; Ĩndĩ kĩseve nĩkĩvĩtaa, na kũmaveta.'),
('kam', 'JOB', 37, 22, 'Kuma ngalĩ ya ĩũlũ ũtisu ta thaavu nĩwũkaa: Ngai e na ũnene wa ũtĩsya ĩũlũ wake.'),
('kam', 'JOB', 37, 23, 'Ũndũ wa Mwene Vinya W’onthe, tũtitonya kũmũmanya: Nake nĩ mũnene vinyanĩ; Na ndakathĩn’ya ũsilinĩ wa katĩ na ũlũngalunĩ mwingĩ.'),
('kam', 'JOB', 37, 24, 'Kwondũ wa ũu andũ mamũkĩaa: Ndasiasya andũ ala me na ũĩ ngoonĩ.'),
('kam', 'JOB', 38, 1, 'Nĩvo ĩndĩ Yeova wasũngĩie Yovu e kĩlinginĩ, na asya,'),
('kam', 'JOB', 38, 2, 'Ũũ nũũ ũla wĩkĩaa ũtao kĩvindu Na ndeto ite na ũmanyi?'),
('kam', 'JOB', 38, 3, 'Ĩvotoe kĩnyunyu kyaku yu ta mũndũ; Nũndũ ngakũkũlya, naku wĩndavya.'),
('kam', 'JOB', 38, 4, 'Waĩ va yĩla naiaa myambĩlĩlyo ya nthĩ? Neena, ethĩwa wĩ na ũmanyi.'),
('kam', 'JOB', 38, 5, 'Nũũ ũla weaie ithimo syayo, ethĩwa nĩwĩsĩ? Kana nũũ watambũũkisye ũlii ĩũlũ wayo?'),
('kam', 'JOB', 38, 6, 'Myambĩlĩlyo yayo yalũlũmĩlw’e na kyaũ? Kana nũũ waiie ĩvia ya kĩkotonĩ kyayo,'),
('kam', 'JOB', 38, 7, 'Yĩla ndata sya kĩoko syainie vamwe, Na ana onthe ma Ngai mookĩlya mawasya ũndũ wa kũtana?'),
('kam', 'JOB', 38, 8, 'Kana nũũ ũla wavingĩie ũkanga na mĩomo, Yĩla wavũngũkie, ta kuma ĩvunĩ;'),
('kam', 'JOB', 38, 9, 'Yĩla naseũvisye mathweo methĩwe ngũa yaw’o, Na kĩvindu kya ngokomi kĩthĩwe ngũa ya ũkenge kwondũ waw’o.'),
('kam', 'JOB', 38, 10, 'Na kũtw’ĩa mũvaka wakwa; Na kwia ivingi na mĩomo,'),
('kam', 'JOB', 38, 11, 'Na kwasya, Wĩvika vaa, ĩndĩ ti mbee; Na vaa itulumo syaku sya ngathĩĩo ikaũngamw’a?'),
('kam', 'JOB', 38, 12, 'Waaĩaĩa kĩoko kuma mĩthenya yaku yambĩlĩlya, Na kũtuma kũkya kũmanya vandũ vakw’o;'),
('kam', 'JOB', 38, 13, 'Nĩ kana kũvike itulunĩ sya nthĩ, Na ala athũku mavuunzwe mamyume?'),
('kam', 'JOB', 38, 14, 'Nĩalyũlawa ta yũmba yĩ ungu wa ũsiĩlo; Na syĩndũ syonthe ikyoneka ta ngũa:'),
('kam', 'JOB', 38, 15, 'Na kyeni kya ala athũku nĩkĩsiĩĩawa, Na kw’oko kũkĩlĩte nĩ kũtũlĩku.'),
('kam', 'JOB', 38, 16, 'Naku waalika mbulutinĩ sya ũkanga? Kana waatambũka syũngũlũtũnĩ sya kyũngũ?'),
('kam', 'JOB', 38, 17, 'Mbingĩlo sya kĩkw’ũ nĩsyavuaniw’e kwaku? Kana waaona mbingĩlo sya kyuu kya kĩkw’ũ?'),
('kam', 'JOB', 38, 18, 'Waamanya nthĩ ũthanthau wayo? Neena, ethĩwa nĩwĩsĩ ũu w’onthe.'),
('kam', 'JOB', 38, 19, 'Nzĩa nĩ yĩva ya kũthi ũtũonĩ wa kyeni? Na ũndũ wa kĩvindu, vandũ vakyo nĩ va,'),
('kam', 'JOB', 38, 20, 'Ũndũ ũkĩtwaa mũvakanĩ wakyo, Na kũmanya nzĩa sya kũthi nyũmba yakyo?'),
('kam', 'JOB', 38, 21, 'Vate nzika, nĩwĩsĩ, nũndũ waĩ mũsyae ĩvinda yĩu, Na ũtalo wa mĩthenya yaku nĩ mwingĩ!'),
('kam', 'JOB', 38, 22, 'Waavota vala ĩa yiawa, Kana waona vala mbua ya mavia yiawa,'),
('kam', 'JOB', 38, 23, 'Ĩla niĩte ũndũ wa ĩvinda ya thĩna, Mũthenya wa kũkita na wa kaũ?'),
('kam', 'JOB', 38, 24, 'Kyeni kĩaanaw’a na nzĩa yĩva, Kana kĩseve kyumĩte wumĩlonĩ wa syũa kĩnyaĩĩkaw’a ata kũũ nthĩ?'),
('kam', 'JOB', 38, 25, 'Nũũ ũla watũĩte ũkinyĩlo wa manzĩ maingĩ, Kana nzĩa ũndũ wa ũtisi wa kĩtundumo;'),
('kam', 'JOB', 38, 26, 'Kuasya mbua nthĩ vala vate mũndũ; Weũnĩ ũla ũte mũndũ;'),
('kam', 'JOB', 38, 27, 'Kũkolethya nthĩ mbanangĩku na nthei, Na kũtuma nyeki mbololo ĩthandĩka?'),
('kam', 'JOB', 38, 28, 'Mbua yĩ ĩthe? Kana nũũ ũla wasyaie mavoloto ma ĩmwe?'),
('kam', 'JOB', 38, 29, 'Manzi momĩtw’e nĩ mbevo maumie ĩvunĩ yaũ? Na ĩmwe ya ĩtunĩ yĩla yakamĩtw’e nĩ mbevo, nũũ wayĩsyaie?'),
('kam', 'JOB', 38, 30, 'Manzĩ mevithaa na kũtw’ĩka ta ĩvia, Na manzĩ me ĩũlũ wa kyũngũ maiyũma.'),
('kam', 'JOB', 38, 31, 'Nũtonya kwovanĩa Kĩeemea, Kana kũthasya kĩla kyovete Olioni?'),
('kam', 'JOB', 38, 32, 'Nũtonya kumĩlya nguthu ya ndata syĩtawa Masalothi ĩvinda yasyo? Kana nũtonya kũtongoesya Ayisi vamwe na ũkondo wayo?'),
('kam', 'JOB', 38, 33, 'Nĩwĩsĩ motw’ĩo ma matu? Nũtonya kũlũlũmĩlya ũsumbĩko wamo kũũ nthĩ?'),
('kam', 'JOB', 38, 34, 'Nũtonya kũkĩlya wasya waku kũvika mathweonĩ, Nĩ kana manzĩ maingĩ makũvw’ĩke?'),
('kam', 'JOB', 38, 35, 'Nũtonya kumĩlya motisi, kana maende, Na maikwĩa, Twĩ vaa?'),
('kam', 'JOB', 38, 36, 'Nũũ ũla wekĩie ũĩ nthĩnĩ? Kana nũũ wanengie kĩlilikano ũmanyi?'),
('kam', 'JOB', 38, 37, 'Nũũ ũtonya kũtala mathweo kwondũ wa ũĩ? Kana nũũ ũtonya kũmatulũla masũva ma ĩtu,'),
('kam', 'JOB', 38, 38, 'Yĩla mũthanga ũkwatanaa na ũitw’ĩka mũmũ, Na mavali makĩlũman’ya vamwe?'),
('kam', 'JOB', 38, 39, 'Nũtonya kũsyĩmĩa mũnyambũ mũka sya nzyĩma, Kana kũvũnĩthya mĩnyambũ ya mũika yĩ na nzaa,'),
('kam', 'JOB', 38, 40, 'Yĩla yoveeasya isumonĩ syayo, Na kwĩkalaa wĩvithonĩ yoveesye?'),
('kam', 'JOB', 38, 41, 'Nũũ ũnengae ngũngũũ kya nzyĩma yayo, Yĩla tũswii twayo tũmwĩkaĩla Ngai, Na kwanganga nũndũ wa kwaĩwa nĩ lĩu?'),
('kam', 'JOB', 39, 1, 'Nĩwĩsĩ ĩvinda ya kũsyaa ya mbũi sya kĩthekanĩ ila syĩ mavianĩ? Kana nũtonya kũmanya yĩla ndaatai isyaaa?'),
('kam', 'JOB', 39, 2, 'Nũtonya kũtala myei ĩla ikwĩanĩsya? Kana nĩwĩsĩ ĩvinda yĩla isyaaa?'),
('kam', 'JOB', 39, 3, 'Nitindiaa, nisyaaa maswii masyo, Nivetaa syalya syasyo.'),
('kam', 'JOB', 39, 4, 'Maswii masyo nĩmaĩsaa vinya, makĩanĩa weũnĩ; Nĩmaendaa, na matisyokaa ĩngĩ.'),
('kam', 'JOB', 39, 5, 'Nũũ ũla ũtũmĩte ĩng’oi ya kĩthekanĩ yĩende yĩ ĩthasye? Kana nũũ ũthaĩtye kĩla kyovete ĩng’oi yĩla yĩendaa mĩtũkĩ,'),
('kam', 'JOB', 39, 6, 'Yĩla naseũvĩsye weũ wĩthĩwe mũsyĩ wayo, Na nthĩ yĩ mũnyũ ũtũo wayo?'),
('kam', 'JOB', 39, 7, 'Nayo yĩvũthasya kĩtuu kya ndũa, O na yĩtyĩw’aa wasya mũtũlu wa mũingi.'),
('kam', 'JOB', 39, 8, 'Ũthanthau wa iĩma nĩ kĩsesi kyayo, Na nĩyĩmanthaa kĩla kĩndũ kĩũ.'),
('kam', 'JOB', 39, 9, 'Mboo ĩkendeew’a nĩ ũkũthũkũma? Kana ĩkekalaa vakuvĩ na kĩĩthĩsyo kyaku?'),
('kam', 'JOB', 39, 10, 'Nũtonya kwova mboo na mũkwa wayo mũkaonĩ? Kana ĩkenza myandanĩ ĩkũatĩĩe?'),
('kam', 'JOB', 39, 11, 'Ũkamĩĩkĩĩa nũndũ vinya wayo nĩ mũnene? Kana ũkamĩtianĩsya na wĩa waku?'),
('kam', 'JOB', 39, 12, 'Ũkamĩĩkĩĩa atĩ ĩkenũkya mbeũ syaku, Na kũmban’ya lĩu wa mbaa ngetha wa kĩvũĩo kyaku?'),
('kam', 'JOB', 39, 13, 'Nthwau sya nyaa nĩkũnanganaw’a na ngathĩĩo; Ĩndĩ nĩ nzĩa na maw’ĩa ma wendo?'),
('kam', 'JOB', 39, 14, 'Nũndũ nĩtiaa matumbĩ mayo ĩũlũ wa mũthanga, Na kũmekĩa muutĩa na kĩtoo,'),
('kam', 'JOB', 39, 15, 'Na kũlwa kana kũũ nĩkũtonya kũmakinyanga, Kana nyamũ mbai nĩtonya kũmakinyanga.'),
('kam', 'JOB', 39, 16, 'Nĩtwĩkaa tũswii twayo na vinya, ta tũte twayo: O na ethĩwa wĩa wayo nĩ mana, ndĩ na w’ĩa;'),
('kam', 'JOB', 39, 17, 'Nĩkwĩthĩwa Ngai nũmĩimĩthĩtye ũĩ, O na ndaamĩnenga ũmanyi.'),
('kam', 'JOB', 39, 18, 'Ĩvinda yĩla ĩyũkĩlasya ĩũlũ, Nĩvũthasya mbalasi na ũla ũmĩtũlĩte.'),
('kam', 'JOB', 39, 19, 'Nue ũmĩnengete mbalasi vinya wayo? Nue ũmĩvw’ĩkĩte ngingo yayo ũea ũtetemaa?'),
('kam', 'JOB', 39, 20, 'Nue ũtumaa ĩtũlĩla ta ngie? Ũnene wa kũtiva kwayo nĩ wa kũtĩsya.'),
('kam', 'JOB', 39, 21, 'Nĩvulasya na kũũ mwandanĩ, na kũtana vinyanĩ wayo: Nĩyumaalaa ĩende kũkomana na andũ mekĩte mĩio ya kaũ.'),
('kam', 'JOB', 39, 22, 'Nĩvũthasya w’ĩa, na ndĩtevaa; O na ndĩsyokaa na ĩtina kuma ũvyũnĩ.'),
('kam', 'JOB', 39, 23, 'Thyaka nũmĩlonzanĩlasya, Ĩtumo yĩla yĩtisũkaa na katumo kanini.'),
('kam', 'JOB', 39, 24, 'Nĩmelasya nthĩ na wai na ũthatu mũnene; O na ndĩtĩkĩlaa kana soo nĩwakaya.'),
('kam', 'JOB', 39, 25, 'O yĩla soo wesa ũvuvwa ĩkyasya, Aa! Na nĩĩw’aa mũuke wa kaũ wĩ kũasa, Kĩtundumo kya makavuteni, na mawasya manene.'),
('kam', 'JOB', 39, 26, 'Nĩ kwondũ wa ũĩ waku kĩlũĩ kĩũlũkaa kĩvolelete, Na kũtambũũkya nthwau syakyo kyelekelye ngalĩ ya ĩtheo?'),
('kam', 'JOB', 39, 27, 'Nĩ ũndũ wa mwĩao waku ndiũ yambataa, Na kwaka ndala yayo ĩũlũ?'),
('kam', 'JOB', 39, 28, 'Nĩyĩkalaa ũkeanĩ, na kũseũvya mũsyĩ wayo, Mũthyanĩ wa ũkea, na ngomenĩ yĩ vinya.'),
('kam', 'JOB', 39, 29, 'Ĩ vo nĩthianaa sya nzyĩma; Metho mayo mamyonaa yĩ kũasa.'),
('kam', 'JOB', 39, 30, 'Tũswii twayo natw’o nĩtũnyusaa nthakame: Na vala ve oawa, nayo yĩ vo.'),
('kam', 'JOB', 40, 1, 'O na ĩngĩ Yeova asũngĩa Yovu, na asya,'),
('kam', 'JOB', 40, 2, 'Mũtetan’ya akatetan’ya na Mwene Vinya W’onthe? Ũla ũkananĩa na Ngai, nasũngĩe.'),
('kam', 'JOB', 40, 3, 'Na ĩndĩ Yovu asũngĩa Yeova, na asya,'),
('kam', 'JOB', 40, 4, 'Sisya, nyie ti kĩndũ; ngakũsũngĩa kyaũ? Nĩngũkunĩka kanyw’a wakwa na kw’oko kwakwa.'),
('kam', 'JOB', 40, 5, 'Nĩneenete ĩmwe, na ndisũngĩa; Ĩĩ, kelĩ, ĩndĩ ndiũendeea.'),
('kam', 'JOB', 40, 6, 'Na ĩndĩ Yeova asũngĩa Yovu e kĩlinginĩ, na asya,'),
('kam', 'JOB', 40, 7, 'Ĩvotoe kĩnyunyu kyaku yu ta mũndũ: Ngakũkũlya, naku ũndavye.'),
('kam', 'JOB', 40, 8, 'Ũkaalyũla ũtw’ĩo wakwa? Ũkatw’a atĩ nyie nĩ na ĩvĩtyo, nĩ kana ũtalwe wĩ mũlũngalu?'),
('kam', 'JOB', 40, 9, 'Kana wĩ na kw’oko ta Ngai? Na nũtonya kũtunduma na wasya take?'),
('kam', 'JOB', 40, 10, 'Ĩyanakavye yu na ũnene na ũsumbĩko; Na kwĩvw’ĩka ndaĩa na ũsũng’wa.'),
('kam', 'JOB', 40, 11, 'Onosya wusũu wa ũthatu waku; Na sisya kĩla mwĩkathĩĩi, noimũnyivya.'),
('kam', 'JOB', 40, 12, 'Sisya kĩla mwĩkathĩĩi, noimũtheesya; Noimakinyangĩa ala athũku vala maũngyĩ.'),
('kam', 'JOB', 40, 13, 'Mavithe kĩtoonĩ vamwe; Move mothyũ moo vandũnĩ vavithe.'),
('kam', 'JOB', 40, 14, 'Nĩvo ĩndĩ nĩumbũla ũndũ waku Kana kw’oko kwaku mwene kwa aũme nĩkũtonya ũkũtangĩĩa.'),
('kam', 'JOB', 40, 15, 'Sisya yu, nguũ, ĩla namyũmbie o taku; Nĩĩsaa nyeki ta ng’ombe.'),
('kam', 'JOB', 40, 16, 'Sisya yu, vinya wayo wĩ kĩnyunyunĩ kyayo, Na ũtonyi wayo wĩ malangũnĩ ma ĩvu yayo.'),
('kam', 'JOB', 40, 17, 'Nĩvyũlasya kĩsithe kyayo ta mũtĩ wa mũkũũ: Malangũ ma mawaswa mayo nĩmakwatanĩte.'),
('kam', 'JOB', 40, 18, 'Mavĩndĩ mayo nĩ ta mĩtote ya ũthuku; Mamutha mayo nĩ ta ivingi sya iaa.'),
('kam', 'JOB', 40, 19, 'Nĩ nene katĩ wa mawĩa ma Ngai: Na ũla wamyũmbie nĩwe ũla wamĩnengie ũvyũ wayo.'),
('kam', 'JOB', 40, 20, 'Nĩ w’o iĩma nimeasya lĩu wayo, Vala nyamũ syonthe sya weũ ithaũkĩaa.'),
('kam', 'JOB', 40, 21, 'Nĩkomaa ĩtina wa mĩtĩ yĩ muunyĩ Wĩvithonĩ wa mĩangi na ndakanĩ.'),
('kam', 'JOB', 40, 22, 'Mĩtĩ ĩsu nĩmĩvw’ĩkaa na muunyĩ wayo; Mĩtĩ ĩla ĩmeaa kalũsĩnĩ nĩmĩthyũlũlũkaa.'),
('kam', 'JOB', 40, 23, 'Sisya, ethĩwa ũsĩ nũvingĩte ũkakĩla, ndĩtetema; Nũndũ yĩ na wĩkwatyo, o na ethĩwa ũsĩ ta Yolotani ũkookĩla kũvika kanyw’anĩ wayo.'),
('kam', 'JOB', 40, 24, 'Mũndũ o na wĩva nũmĩkwata ĩsyaĩĩsye, Kana kũtonya mũkuthũ ĩnyiũũnĩ yayo na kĩtei?'),
('kam', 'JOB', 41, 1, 'Nũtonya kũkusya leviathani na ngolya ya ũkwatya makũyũ? Kana kũvinyĩĩa ũĩmĩ wayo na ĩkanda?'),
('kam', 'JOB', 41, 2, 'Nũtonya kwĩkĩa ĩkanda ĩnyiũũnĩ yayo? Kana kũtonya mũkuthũ ũkambuu wayo na kavoloi?'),
('kam', 'JOB', 41, 3, 'Ĩkakwĩsũva na mawĩsũvano maingĩ? Kana ĩkakũtavya ndeto mbololo?'),
('kam', 'JOB', 41, 4, 'Ĩkatianĩa ũtianĩo naku, Nĩ kana ũmyose yĩthĩwe mũthũkũmi waku tene na tene?'),
('kam', 'JOB', 41, 5, 'Ũkathaũka nayo ta nyũnyi? Kana ũkamyova kwondũ wa athũkũmi maku eĩtu?'),
('kam', 'JOB', 41, 6, 'Nguthu sya atei ma makũyũ ikamĩtw’ĩkĩthya ũtandĩthyo wasyo? Ikamĩaan’ya katĩ wa atandĩthya?'),
('kam', 'JOB', 41, 7, 'Nũtonya kusũsya kĩkonde kyayo na mĩw’a ya kĩaa, Kana mũtwe wayo na tũtumo twa kũtonya makũyũ?'),
('kam', 'JOB', 41, 8, 'Ilĩĩla kw’oko kwaku ĩũlũ wayo; Lilikana kaũ ũsu, na ndũkeke ũu ĩngĩ.'),
('kam', 'JOB', 41, 9, 'Sisya, wĩkwatyo vala ĩĩ nĩ wa mana: Mũndũ ndevalũkw’a nthĩ no kũmyona?'),
('kam', 'JOB', 41, 10, 'Vati ũla mwai ũla ũtakĩa kũmĩamũkya; Nũũ ĩndĩ ũtonya kũũngama mbee wakwa?'),
('kam', 'JOB', 41, 11, 'Nũũ ũla wambie kũnenga, atĩ naĩle kũmũĩva? O kĩla kĩ ĩtheo wa ĩtu yonthe nĩ kyakwa.'),
('kam', 'JOB', 41, 12, 'Ndikavindya ũndũ wa mamutha mayo, Kana vinya wayo mũnene, kana wũmbe wayo mũseo.'),
('kam', 'JOB', 41, 13, 'Nũũ ũtonya kũmyumya ngũa yayo ya ĩũlũ? Nũũ wĩlika ngambuunĩ syayo?'),
('kam', 'JOB', 41, 14, 'Nũũ ũtonya kũvingũa mĩomo ya ũthyũ wayo? Ũtee wa maeo mayo kwĩ ũtĩsyo.'),
('kam', 'JOB', 41, 15, 'Makwaũ mayo me vinya nĩmo ngathĩĩo yayo, Makwatanĩte vamwe ta ũsiĩlo mũlũmu'),
('kam', 'JOB', 41, 16, 'Yĩmwe yĩthengeanĩe na yĩngĩ, Ũndũ nzeve ĩtatonya kũvĩtĩla katĩ wamo.'),
('kam', 'JOB', 41, 17, 'Nĩmakwatanĩte yĩmwe na yĩngĩ; Makwatene, ũndũ matatonya kũtaanw’a.'),
('kam', 'JOB', 41, 18, 'Kwathimũa kwayo kũkenasya kyeni, Na metho mayo nĩ ta ilomo sya metho sya kĩoko.'),
('kam', 'JOB', 41, 19, 'Momũĩ makanu maumaa kanyw’anĩ wayo, Na ngala sya mwaki nitũlĩlaa ikyuma.'),
('kam', 'JOB', 41, 20, 'Syũki nĩyumaa manyiũũnĩ mayo, Ta mbisũ ĩkĩtheũka na ta malula makanu.'),
('kam', 'JOB', 41, 21, 'Mĩthũmũ yayo nĩyakanasya makaa, Na ũmũĩ nĩwumaa kanyw’anĩ wayo.'),
('kam', 'JOB', 41, 22, 'Ngingonĩ yayo nĩvekalaa vinya, Na ũtĩsyo ũsũngasũngaa mbee wayo.'),
('kam', 'JOB', 41, 23, 'Makwaũ ma mwĩĩ wayo nĩmakwatanĩte: Nĩmomanĩle ĩũlũ wayo; matitonya kumĩka.'),
('kam', 'JOB', 41, 24, 'Ngoo yayo nĩ nũmu ta ĩvia; Ĩĩ, nũmu ta ĩvia ya kũthia.'),
('kam', 'JOB', 41, 25, 'Yĩla yũkĩlaa, ala me vinya nĩmakĩaa: Nũndũ wa w’ĩa mũnene nĩmeũvũavũanw’a.'),
('kam', 'JOB', 41, 26, 'Ethĩwa mũndũ nũmĩkũnaa na ũvyũ, no ta mana; Kana ĩtumo, kana katumo, kana mũsenge.'),
('kam', 'JOB', 41, 27, 'Nĩtalaa kĩaa ta ũa, Na ũthuku ta mũtĩ mwou.'),
('kam', 'JOB', 41, 28, 'Mũsyĩ ndũtonya kũtuma ĩkĩa: Mavia ma kĩkũtha malyũlawa nĩyo ta ũa.'),
('kam', 'JOB', 41, 29, 'Nzũma nitalawa ta ũa: Nĩthekeaa kwĩkw’a kwa katumo.'),
('kam', 'JOB', 41, 30, 'Ungu wayo nĩ ya ilĩo mbũĩ: Nĩvinyĩĩaa ĩũlũ wa ndaka ta kĩvũi.'),
('kam', 'JOB', 41, 31, 'Nĩtumaa kyũngũ kĩtheũka ta mbisũ: Nĩtw’ĩkĩthasya ũkanga ta mbisũ ya mauta ma ũvaka.'),
('kam', 'JOB', 41, 32, 'Nĩtumaa nzĩa ĩtisatisa ĩtina wayo; Mũndũ akasũanĩa kyũngũ kĩ mbuĩ.'),
('kam', 'JOB', 41, 33, 'Ĩũlũ wa nthĩ vati tayo, Ĩla yũmbĩtwe ĩte w’ĩa.'),
('kam', 'JOB', 41, 34, 'Nĩsiasya kĩla kĩndũ kĩ ĩũlũ: Nĩ mũsumbĩ ĩũlũ wa ana onthe ma ngathĩĩo.'),
('kam', 'JOB', 42, 1, 'Na ĩndĩ Yovu asũngĩa Yeova, na asya,'),
('kam', 'JOB', 42, 2, 'Nĩnĩsĩ nũtonya kwĩka maũndũ onthe, Na ũla ũkwenda kwĩka ndũsiĩĩka.'),
('kam', 'JOB', 42, 3, 'Ũũ nũũ ũla ũvithaa ũtao vate ũmanyi? Kwondũ wa ũu nĩnĩneenete ũndũ ndaamanya, Maũndũ ma ũnzeng’ya, ala ndeesĩ.'),
('kam', 'JOB', 42, 4, 'Ĩw’a, nĩngũkwĩsũva, na nganeena; Ngakũkũlya, naku ũndavye.'),
('kam', 'JOB', 42, 5, 'Nĩneew’ĩte ũvoo waku kwa kwĩw’a na kũtũ; Ĩndĩ yu itho yakwa nĩyĩũkwona:'),
('kam', 'JOB', 42, 6, 'Kwondũ wa ũu nĩngwĩthĩtha, Na nĩngwĩlilĩla kĩtoonĩ na mũunĩ.'),
('kam', 'JOB', 42, 7, 'Na kweethĩwa, kana yĩla Yeova waminie kũneena ndeto isu na Yovu, Yeova amwĩa Elivasi Mũtemani, Ũthilĩku wakwa nũkwakanĩe, o na anyanyau maku elĩ; nũndũ mũtyaaneenea ũndũ ũla wa w’o, o tondũ mũthũkũmi wakwa Yovu ũneenete.'),
('kam', 'JOB', 42, 8, 'Yu kwondũ wa ũu, mwĩyosee tũsalũ mũonza twa mũew’a na ndũũme mũonza, na kũmũendea Yovu mũthũkũmi wakwa, na kwĩthembea nthembo ya kũvĩvw’a; na mũthũkũmi wakwa Yovu akamũvoyea; nũndũ ngamwĩtĩkĩla, nĩ kana ndikamwĩke inyw’ĩ kwĩanana na ũtumanu wenyu; nũndũ mũtyaaneenea ũndũ ũla wa w’o, o tondũ mũthũkũmi wakwa Yovu ũneenete.'),
('kam', 'JOB', 42, 9, 'Na ĩndĩ Elivasi Mũtemani na Mbilitati Mũsui na Nzovali Mũnamaathi maenda, na meeka kwĩanana na ũndũ Yeova wameaĩe: na Yeova amwĩtĩkĩla Yovu.'),
('kam', 'JOB', 42, 10, 'Na Yeova amũtũngĩa Yovu kũtavĩwa kwake, yĩla wamavoyeie anyanyae make: na Yeova amũnenga Yovu kũndũ kwĩlĩ kwa ila waĩ nasyo mbee.'),
('kam', 'JOB', 42, 11, 'Nĩvo ĩndĩ ana‐a‐inyia make onthe, na eitu‐ainyia make onthe, na onthe ala meesene nake mbee mooka, na maĩsanĩa lĩu nake nyũmbanĩ yake: na mamũĩĩa, na kũmũkiakiasya ũndũ wa ũthũku w’onthe ũla Yeova wamũetee: o na kĩla mũndũ amũnenga kĩlungu kya mbesa, na kĩla ũmwe ngome ya thaavu.'),
('kam', 'JOB', 42, 12, 'Na ĩndĩ Yeova aathima mũminũkĩlyo wa Yovu kũvĩtũka wambĩlĩlyo wake: na aĩ na malondu ngili ĩkũmi na inya, na ngamĩle ngili thanthatũ, na syove sya ng’ombe ngili ĩmwe, na mang’oi maka ngili ĩmwe.'),
('kam', 'JOB', 42, 13, 'O na aĩ na ana mũonza na eĩtu atatũ.'),
('kam', 'JOB', 42, 14, 'Na eeta syĩtwa ũa ũla wa mbee, Yemima; na syĩtwa ya ũla wa kelĩ, Kesia; na syĩtwa ya ũla wa katatũ, Keloni‐avuki.'),
('kam', 'JOB', 42, 15, 'Na nthĩ yonthe vatyaoneka aka maĩ anake ta eĩtu ma Yovu: na ĩthe woo amanenga ũtiĩwa katĩ wa ana‐a‐inyia moo.'),
('kam', 'JOB', 42, 16, 'Na ĩtina wa ũu Yovu ekala thayũ myaka ĩana na mĩongo ĩna, na oona ana make na esũkũũe, o mosyaanĩo ana.'),
('kam', 'JOB', 42, 17, 'Na ĩndĩ Yovu akw’a, e mũkũu na wa matukũ maingĩ.'),
('kam', 'PSA', 1, 1, 'Kũathimwa nĩ mũndũ ũla ũtaendaa ũtaonĩ wa ala athũku, O na ndaũngamaa nzĩanĩ ya ala athe, O na ndekalaa kĩkalonĩ kya ala mavũthasya.'),
('kam', 'PSA', 1, 2, 'Ĩndĩ ũtanu wake wĩ mĩaonĩ ya Yeova; Na asũanĩaa mĩao yake mũthenya na ũtukũ.'),
('kam', 'PSA', 1, 3, 'Na akeethĩwa ailyĩ ta mũtĩ ũvandĩtwe ũtee wa mbũsĩ syĩ manzĩ, Ũla ũsyaaa ũsyao waw’o ĩvinda yaw’o, Na ĩtũ yaw’o yĩtivovaa; Na ũndũ o na wĩva wĩkaa nĩwaĩlaa.'),
('kam', 'PSA', 1, 4, 'Ala athũku matiilyĩ ũu, Ĩndĩ mailyĩ ta wewa ũũlũkĩtw’e nĩ ũkũngi.'),
('kam', 'PSA', 1, 5, 'Kwondũ wa ũu athũku matikaũngama ũsilĩlonĩ, Kana athe ũmbanonĩ wa ala alũngalu.'),
('kam', 'PSA', 1, 6, 'Nũndũ Yeova nĩwĩsĩ nzĩa ya ala alũngalu; Ĩndĩ nzĩa ya athe ĩkaaa.'),
('kam', 'PSA', 2, 1, 'Mbaĩ ilonzanĩlasya kĩ? Na ngo sya andũ kũsũanĩa ũndũ wa mana?'),
('kam', 'PSA', 2, 2, 'Asumbĩ ma nthĩ nĩmeyũmanĩlye, Na asũmbĩki nĩmesũanĩa vamwe, Ĩũlũ wa Yeova, na ĩũlũ wa ũla mwĩtĩkĩw’a mauta wake, makyasya,'),
('kam', 'PSA', 2, 3, 'Tũtusangei syĩndũ ila imovaa, Na ndii syoo tũsyĩkye kũasa naitũ.'),
('kam', 'PSA', 2, 4, 'We ũla ũilyĩ matunĩ akatheka: Mwĩaĩi akamathekeea.'),
('kam', 'PSA', 2, 5, 'Nĩvo ĩndĩ ũkaneena namo ũthilĩkunĩ wake, Na kũmathĩn’ya e na ũthatu mwai:'),
('kam', 'PSA', 2, 6, 'Nakwa nĩniĩte mũsumbĩ wakwa Kĩĩmanĩ kyakwa kĩtheu kya Saioni.'),
('kam', 'PSA', 2, 7, 'Nĩngũtavan’ya ũvoo wa ũla ũtw’ĩo: Yeova ambĩa, Nue mwana wakwa; Umũnthĩ nĩnaũsyaa.'),
('kam', 'PSA', 2, 8, 'Mbĩtya, na ngakũnenga mbaĩ syĩthĩwe ũtiĩwa waku, Na itulu sya nthĩ syĩthĩwe ng’ũndũ yaku.'),
('kam', 'PSA', 2, 9, 'Ũkamananga na ndata ya kĩaa; Ũkamang’atangan’ya matilĩkangane tũlungu ta mbisũ ya mũmbi.'),
('kam', 'PSA', 2, 10, 'Kwondũ wa ũu ĩthĩwai na ũĩ, inyw’ĩ asumbĩ: Likwai nĩ ũmanyi, inyw’ĩ asilĩli ma nthĩ.'),
('kam', 'PSA', 2, 11, 'Thũkũmai Yeova mũkĩmũkĩa, Na tanai na kũtetema.'),
('kam', 'PSA', 2, 12, 'Mũmumunyei ũla mwana, ndakese ũthata, na inyw’ĩ mũyaĩa nzĩanĩ, Nĩkwĩthĩwa ũthilĩku wake ũkilĩlye kwakana. Nĩ aathime onthe ala mevithaa nthĩnĩ wake.'),
('kam', 'PSA', 3, 1, 'Yeova, nthũ syakwa ko nĩsyaingĩviee! Nĩ aingĩ ala mambũkĩlĩle.'),
('kam', 'PSA', 3, 2, 'Nĩ aingĩ ala maasya ũndũ wa thayũ wakwa, Vati ũtethyo wa Ngai kwake.'),
('kam', 'PSA', 3, 3, 'Ĩndĩ we, ame Yeova, nue ngao ngalĩ syonthe syakwa; Na nũe ũtaĩo wakwa, na nue ũmbũkĩlasya mũtwe wakwa.'),
('kam', 'PSA', 3, 4, 'Nĩngũmwĩkaĩla Yeova na kanyw’a wakwa, Nake nũnũũnzũngĩa e kĩĩmanĩ kyake kĩla kĩtheu.'),
('kam', 'PSA', 3, 5, 'Nyie nĩnakomie na nalĩkwa; Na navindũka; nĩkwĩthĩwa Yeova nĩwe ũndw’ĩĩkaa.'),
('kam', 'PSA', 3, 6, 'Ndikakĩa andũ ngili makũmi Ala mambũkĩlĩle ngalĩ syonthe.'),
('kam', 'PSA', 3, 7, 'Ũkĩla, ame Yeova; ndangĩĩa, ame Ngai wakwa: Nĩkwĩthĩwa nũmakũnĩte amaitha makwa onthe ĩvĩndĩnĩ ya ĩtau; Nũtũlĩte maeo ma ala athũku.'),
('kam', 'PSA', 3, 8, 'Yeova ũtangĩĩo nĩ waku: Ũathimo waku wĩthĩwe ĩũlũ wa andũ maku.'),
('kam', 'PSA', 4, 1, 'Nzũngĩa yĩla nĩkwĩkaĩla, ame Ngai wa ũlũngalu wakwa; Nĩwanumisye yĩla naĩ thĩnanĩ: Mbĩw’ĩa tei, na ĩw’a mboya yakwa.'),
('kam', 'PSA', 4, 2, 'Inyw’ĩ ana ma andũ, nĩ ĩvinda yĩana ata ndaĩa yakwa ĩkĩalyũlwa yae ndaĩa? Nĩ ĩvinda yĩana ata mũkyenda maũndũ ma mana na kũatĩĩa ũvũngũ?'),
('kam', 'PSA', 4, 3, 'Ĩndĩ manyai kana Yeova nũvathĩte kwondũ wake ũla ũmũkĩaa Ngai: Yeova akeew’a yĩla ngũmwĩkaĩla.'),
('kam', 'PSA', 4, 4, 'Ĩthĩwai na w’ĩa, na mũikeke naĩ: Neenan’yai kĩla mũndũ na ngoo yake mwĩ mokomonĩ, na ĩthĩwai mũvindĩtye.'),
('kam', 'PSA', 4, 5, 'Umyai nthembo sya ũlũngalu, Na mũĩkĩĩo wenyu wĩthĩwe nthĩnĩ wa Yeova.'),
('kam', 'PSA', 4, 6, 'Nĩ aingĩ ala mekwasya, Nũũ ũla ũtonya kũtwon’ya ũseo o na wĩva? Yeova, tũkĩlĩlye kyeni kya ũthyũ waku.'),
('kam', 'PSA', 4, 7, 'Nũmbĩkĩĩte ũtanu ngoonĩ yakwa, Kũvĩtũka ũla me naw’o yĩla lĩu woo wa mbaa ngetha na mbinyu mbĩthĩ syoo ikwingĩva.'),
('kam', 'PSA', 4, 8, 'Ngakoma na mũuo na ĩngĩ ngalĩkwa; Nĩkwĩthĩwa nue, Yeova, wĩ weka ũtumaa nĩkala vate mũisyo.'),
('kam', 'PSA', 5, 1, 'Ĩthukĩĩsye ndeto syakwa, ame Yeova, Sũanĩa mavindĩĩsyo makwa.'),
('kam', 'PSA', 5, 2, 'Ĩthukĩĩsye wasya wa kĩĩo kyakwa, Mũsumbĩ wakwa, na Ngai wakwa; Nĩkwĩthĩwa nũe nĩkũvoyaa.'),
('kam', 'PSA', 5, 3, 'Ame Yeova, kĩoko ũkeew’a wasya wakwa; O kĩoko ngelekelya mboya yakwa kwaku, na ngekala ngĩsyaĩĩsya.'),
('kam', 'PSA', 5, 4, 'Nũndũ we ndwĩ Ngai ũla ũtanaw’a nĩ ũthũku: Ũthũku ndũkatũa naku.'),
('kam', 'PSA', 5, 5, 'Ala ekathĩĩi matikaũngama methonĩ maku: Nũmenaa onthe ala mekaa naĩ.'),
('kam', 'PSA', 5, 6, 'Ũkaananga ala maneenaa movũngũ: Yeova nũthĩthaa mũndũ ũla ũng’aatũkaw’a nĩ nthakame o na mũkengani.'),
('kam', 'PSA', 5, 7, 'Ĩndĩ nyie, nũndũ wa wingĩ wa tei waku wĩ wendo ngalika nyũmbanĩ yaku: Kĩkĩonĩ kyaku ngathaitha kwelekela ĩkalũ yaku ĩtheu.'),
('kam', 'PSA', 5, 8, 'Ndongoeasya, ame Yeova, ũlũngalunĩ waku nũndũ wa amaitha makwa; Lũngalya nzĩa yaku mbee wa ũthyũ wakwa.'),
('kam', 'PSA', 5, 9, 'Nĩkwĩthĩwa vai ũĩkĩĩthyo kanyw’anĩ woo; Nthĩnĩ woo no ũthũku mũthei; Mĩmeo yoo nĩ mbũa mbingũe; Nĩmendeeasya na ndeto sya ũkathĩĩo na nĩmĩ syoo.'),
('kam', 'PSA', 5, 10, 'Matw’ĩĩe nĩ avĩtan’ya, ame Ngai; Maeke mavalũke ũtaonĩ woo ene; Malũngye kwondũ wa mavĩtyo moo maingĩ; Nĩkwĩthĩwa nĩmakũng’endeie.'),
('kam', 'PSA', 5, 11, 'Ĩndĩ matane onthe ala mekwĩvitha nthĩnĩ waku, Mokĩlasye mawasya mavinda onthe nũndũ wa kũtana, nĩkwĩthĩwa nue ũmaseseaa: O na ala mendete syĩtwa yaku methĩwe na ũtanu nthĩnĩ waku.'),
('kam', 'PSA', 5, 12, 'Nũndũ ũkamũathima ũla mũlũngalu; Naku Yeova, wĩmũthyũlũlũka na ũseo o ta ngao.'),
('kam', 'PSA', 6, 1, 'Ame Yeova, ndũkangan’ye ũthatunĩ waku, O na ndũkanzilĩle woonĩ waku mũvyũ.'),
('kam', 'PSA', 6, 2, 'Mbĩw’ĩa tei, ame Yeova; nũndũ nĩ mũvovu: Ame Yeova, mbosya; nĩkwĩthĩwa mavĩndĩ makwa nĩmeũthĩna.'),
('kam', 'PSA', 6, 3, 'O na ngoo yakwa nĩnĩkũũũya mũno: Naku, ame Yeova, nĩ kũvika ĩndĩĩ?'),
('kam', 'PSA', 6, 4, 'Syoka, ame Yeova, vonokya thayũ wakwa: Ndangĩĩa kwondũ wa ũseo waku wĩ wendo.'),
('kam', 'PSA', 6, 5, 'Nĩkwĩthĩwa kĩkw’ũnĩ ndũlilikanawa: Ku Seoli nũũ ũla ũkakũtũngĩa mũvea?'),
('kam', 'PSA', 6, 6, 'Nĩnĩnoetwe nĩ kũluma kwakwa; Kĩla ũtukũ nĩindaa ũkomo wakwa methoinĩ; Ũkomo wakwa nĩngũnyithya na methoi makwa.'),
('kam', 'PSA', 6, 7, 'Itho yakwa nĩyĩũseekea nũndũ wa kũmaka; Nĩyĩũkũa nũndũ wa nthũ syakwa syonthe.'),
('kam', 'PSA', 6, 8, 'Umai vaa nĩĩ, inyw’onthe eki ma naĩ; Nĩkwĩthĩwa Yeova nĩwĩw’ĩte wasya wa kĩĩo kyakwa.'),
('kam', 'PSA', 6, 9, 'Yeova nĩwĩw’ĩte kũvoya kwakwa; Yeova akeetĩkĩla mboya yakwa.'),
('kam', 'PSA', 6, 10, 'Amaitha makwa onthe makasonokw’a na kũũũya mũno: Makasyoka na ĩtina, makasonokw’a o mĩtũkĩ.'),
('kam', 'PSA', 7, 1, 'Ame Yeova Ngai wakwa, nĩngwĩvitha nthĩnĩ waku: Ndangĩĩa kuma kwa andũ onthe ala mangatĩĩaa, na mbonokya,'),
('kam', 'PSA', 7, 2, 'Matikese kũtembũa thayũ wakwa ta mũnyambũ, Makĩtembũanga, vate wa kũvonokya.'),
('kam', 'PSA', 7, 3, 'Ame Yeova Ngai wakwa, ethĩwa nĩnĩkĩte ũũ; Ethĩwa kwĩ ũthũku mokonĩ makwa;'),
('kam', 'PSA', 7, 4, 'Ethĩwa nĩnĩmũtũngĩĩte ũthũku ũla waĩ na mũuo nakwa (Ĩĩ, nĩnĩmũvonoketye ũla waĩ nthũ yakwa vate kĩtumĩ);'),
('kam', 'PSA', 7, 5, 'Mũmaitha naatĩĩe thayũ wakwa, na kũkwata; Ĩĩ, nakinyangĩe thayũ wakwa nthĩ, Na kwia ndaĩa yakwa kĩtoonĩ.'),
('kam', 'PSA', 7, 6, 'Ũkĩla, ame Yeova, ũthatunĩ waku; Ĩyũkĩlye ĩũlũ wa ũthatu mwai wa nthũ syakwa, Na ũiamũka nũndũ wakwa; nĩwĩaĩte ũsilĩlo.'),
('kam', 'PSA', 7, 7, 'Ũmbano wa ngo sya andũ ũkũthyũlũlũke; Na wĩ ĩũlũ woo, syoka ĩũlũ.'),
('kam', 'PSA', 7, 8, 'Yeova nĩwe wĩsilanasya ngo sya andũ: Nzilĩla nyie, ame Yeova, kwĩanana na ũlũngalu wakwa, na w’o wakwa ũla wĩ nthĩnĩ wakwa.'),
('kam', 'PSA', 7, 9, 'Ame ũthũku wa ala athe ũthele, ĩndĩ naku lũlũmĩlya ala alũngalu: Nĩkwĩthĩwa Ngai mũlũngalu nũoasya mosũanĩo na ngoo.'),
('kam', 'PSA', 7, 10, 'Ngao yakwa yĩ kwa Ngai, Ũla ũtangĩĩaa ala alũngalu ngoonĩ.'),
('kam', 'PSA', 7, 11, 'Ngai nĩ mũsili mũlũngalu, Ĩĩ, Ngai ũla ũthataa kĩla mũthenya.'),
('kam', 'PSA', 7, 12, 'Ethĩwa mũndũ akalea kwĩalyũla, akanoa ũvyũ wake; Nĩwakoota ũta wake, na nũũkootete;'),
('kam', 'PSA', 7, 13, 'Na ĩngĩ nĩwamũseũvĩsye mĩio ya kĩkw’u; Atumaa mĩsyĩ yake yĩthĩwa na mwaki.'),
('kam', 'PSA', 7, 14, 'Sisyai, ũsu nĩwe ũnũkwaũnyw’a nĩ ũthũku; Ĩĩ, aitavĩte ũthũku, na nũsyaĩte ũvũngũ.'),
('kam', 'PSA', 7, 15, 'Nĩwĩnzĩte ĩima, na akayĩvukũa, Nake nũvalũkĩte mũkaonĩ ũla wĩnzĩte.'),
('kam', 'PSA', 7, 16, 'Ũthũku wake ũkasyoka mũtwenĩ wake mwene, Na ũng’endu wake ũkamũtheeea kyongo kyake.'),
('kam', 'PSA', 7, 17, 'Ngamũtũngĩa Yeova mũvea kwĩanana na ũlũngalu wake, Na ngaina ngĩkumya syĩtwa ya Yeova Ũla Wĩ Ĩũlũ wa Onthe.'),
('kam', 'PSA', 8, 1, 'Ame Yeova, Mwĩaĩi waitũ, Kaĩ syĩtwa yaku yĩnenevete nthĩ yonthe, We ũla waiie ũnene waku ĩũlũ wa matu!'),
('kam', 'PSA', 8, 2, 'Kuma kanyw’anĩ wa twana na tũũkenge ũlũlũmĩlye vinya, Kwondũ wa nthũ syaku, Nĩ kana ũvindĩthye ũla mũmaitha na mũĩvanĩsya.'),
('kam', 'PSA', 8, 3, 'Yĩla ngũsisya matu maku, wĩa wa syaa syaku, Mwei na ndata, ila syatw’ĩĩwe nue;'),
('kam', 'PSA', 8, 4, 'Mũndũ nĩ kĩndũ kyaũ, ũndũ ũmũlilikana? Na mwana wa mũndũ, ũndũ ũthi vala ũĩ?'),
('kam', 'PSA', 8, 5, 'Nĩkwĩthĩwa nĩwamutwie mũnini o vanini kwĩ Ngai, Na kũmwĩkĩa ngovia ya ũsumbĩ ya ũnene na ndaĩa.'),
('kam', 'PSA', 8, 6, 'Nũmũkĩlĩtye asumbĩke ĩũlũ wa mawĩa ma moko maku; Wamwiĩe syĩndũ syonthe ungu wa nyaĩĩ syake:'),
('kam', 'PSA', 8, 7, 'Malondu na ng’ombe syonthe, Ĩĩ, na nyamũ sya kĩthekanĩ,'),
('kam', 'PSA', 8, 8, 'Nyũnyi sya yayaya, na makũyũ ma ũkanganĩ, O kĩla kĩkũnĩlaa nzĩanĩ sya maũkanga.'),
('kam', 'PSA', 8, 9, 'Ame Yeova, Mwĩaĩi waitũ, Kaĩ syĩtwa yaku yĩnenevete nthĩ yonthe!'),
('kam', 'PSA', 9, 1, 'Ngamũtũngĩa Yeova mũvea na ngoo yakwa yonthe; Ngoonan’ya mawĩa maku onthe ma ũseng’ya.'),
('kam', 'PSA', 9, 2, 'Ngatana na kwĩw’a mũyo mũno nthĩnĩ waku: Ngaina ngĩkumya syĩtwa yaku, we Ũla Wĩ Ĩũlũ wa Onthe.'),
('kam', 'PSA', 9, 3, 'Yĩla amaitha makwa masyoka na ĩtina, Malulutĩkaa na kwaĩa mbee wa ũthyũ waku.'),
('kam', 'PSA', 9, 4, 'Nĩkwĩthĩwa nĩwanũnũmĩlĩlye kyanda kyakwa na ũvoo wakwa; Nĩwĩkalaa kĩvĩlanĩ kya ũsumbĩ ũkĩsila na ũlũngalu.'),
('kam', 'PSA', 9, 5, 'Nĩwakandĩie i mbaĩ, nĩwamanangie ala athe; Nĩwavutie masyĩtwa moo kũvika tene na tene.'),
('kam', 'PSA', 9, 6, 'Amaitha nĩmaminĩtwe, maĩ vo kũvika tene na tene; Na ndũa ila wang’uthũlangile, O na kũlilikanwa kwasyo nĩkwathelile.'),
('kam', 'PSA', 9, 7, 'Ĩndĩ Yeova ekalaa e mũsumbĩ tene na tene: Nĩwiĩte kĩvĩla kyake kya ũsumbĩ kya ũsila;'),
('kam', 'PSA', 9, 8, 'Na akasilĩla nthĩ na ũlũngalu, Nake akatw’ĩĩa ngo sya andũ sila ũla waĩlĩte.'),
('kam', 'PSA', 9, 9, 'Yeova nake akeethĩwa mwako mũtũlu mũno wa mũnyoolo wa ala mathĩnaw’a, Mwako mũtũlu mũno wa mũnyoolo mavindanĩ ma thĩna;'),
('kam', 'PSA', 9, 10, 'Na ala mesĩ syĩtwa yaku makakwĩkwatya we; Nĩkwĩthĩwa we, Yeova, ndũnamba kũmatia ala makũmanthaa.'),
('kam', 'PSA', 9, 11, 'Inai mũikumya Yeova, ũla ũtwĩe Saioni: Tavan’yai meko make katĩ wa andũ.'),
('kam', 'PSA', 9, 12, 'Nĩkwĩthĩwa ũla ũĩvanĩasya nthakame nũmalilikanaa; Ndolawa nĩ kũkaya kwa ngya.'),
('kam', 'PSA', 9, 13, 'Mbĩw’ĩa tei, ame Yeova; Sisya thĩna wakwa ũla nĩthĩnĩtw’e nĩ ala mamenaa nyie, We ũla ũmbũkĩlasya kuma mbingĩlonĩ sya kĩkw’ũ;'),
('kam', 'PSA', 9, 14, 'Nĩ kana nonan’ye ndaĩa yaku yonthe. Mbingĩlonĩ sya mwĩĩtu wa Saioni Ngatanĩa ũtangĩĩonĩ waku.'),
('kam', 'PSA', 9, 15, 'I mbaĩ nĩsyakulumanile ĩimanĩ yĩla syenzie: Mo ene nĩmakwatiw’e maũũ moo nĩ mũteo ũla mavithie.'),
('kam', 'PSA', 9, 16, 'Yeova nĩweyonanisye, nĩwatwie sila: Ũla mũthũku nũkwatĩtw’e nĩ wĩa wa moko make mwene.'),
('kam', 'PSA', 9, 17, 'Ala athũku makatũngwa Seoli, O na mbaĩ syonthe ila syoolilwe nĩ Ngai.'),
('kam', 'PSA', 9, 18, 'Nĩkwĩthĩwa athĩni matikolwa mavinda onthe, Kana wĩkwatyo wa ngya kwaa kũvika tene na tene.'),
('kam', 'PSA', 9, 19, 'Ũkĩla, ame Yeova; mũndũ ndakakĩlye vinya: I mbaĩ nisilĩĩlwe mbee waku.'),
('kam', 'PSA', 9, 20, 'Tuma makĩa, ame Yeova: I mbaĩ imanye atĩ no andũ.'),
('kam', 'PSA', 10, 1, 'Ũũngamĩte kũasa nĩkĩ, we Yeova? Nĩkĩ wĩvithaa mavinda ma thĩna?'),
('kam', 'PSA', 10, 2, 'Ũndũ wa wĩng’athĩlĩlyo wa athũku ũla ngya nũlũngaw’a mũno; Makwatw’e e mo nĩ mosũanĩo ala mavindĩĩsye.'),
('kam', 'PSA', 10, 3, 'Nĩkwĩthĩwa mũthũku nũkwĩkathĩĩa nũndũ wa kwenda kwa ngoo yake, Na ũla wĩ na ĩtomo nũkũmũlea, ĩĩ, o na kũmũvũthya Yeova.'),
('kam', 'PSA', 10, 4, 'Ũla mũthũku, wĩng’athĩlĩlyonĩ wa ũthyũ wake, easya atĩĩ, Ndakakũlya. Malilikano onthe make nĩ atĩĩ, Vai Ngai.'),
('kam', 'PSA', 10, 5, 'Nzĩa syake syĩkalaa ilũmĩte mavinda onthe; Mosilĩlo maku me ĩũlũ mũno, o kũla ũtatonya kũmona: Na ũndũ wa onthe ala me na ũthũ nake, amavuta na mĩthũmũ yake.'),
('kam', 'PSA', 10, 6, 'Easya ngoonĩ yake, Ndikathingithĩka; Mosyaanĩonĩ onthe ndikona thĩna.'),
('kam', 'PSA', 10, 7, 'Kanyw’a wake usũĩte kĩumo na ũkengani na kũthĩn’ya: Ungu wa ũĩmĩ wake vekalaa ũthũku na naĩ.'),
('kam', 'PSA', 10, 8, 'Ekalĩte mawoveesyonĩ ma mĩsyĩ; Syĩmbithĩnĩ nĩkw’o ũaĩaa ala mate na mavĩtyo; Metho make mekalaa makĩmantha na kĩmbithĩ ũla ũte na vinya.'),
('kam', 'PSA', 10, 9, 'Oveeasya na kĩmbithĩ o ta mũnyambũ wĩ kĩsumonĩ kyaw’o; Oveeasya akwate ngya: Nũkwataa ngya, yĩla ũnũũmĩkũsĩĩsya mũteonĩ wake.'),
('kam', 'PSA', 10, 10, 'Nũmandĩkaa, nũkunamaa, Nao ala mate na vinya mavalũkaa nũndũ wa ala make me na vinya.'),
('kam', 'PSA', 10, 11, 'Easya ngoonĩ yake; Ngai nĩũlĩtwe, Evithaa ũthyũ wake, ndakawona o na ĩndĩĩ.'),
('kam', 'PSA', 10, 12, 'Ukĩla, we Yeova; ame Ngai, ũkĩlya kw’oko kwaku: Ndũkolwe nĩ ala ngya.'),
('kam', 'PSA', 10, 13, 'Nĩ ũndũ wa kĩ mũthũku kũmũvũthya Ngai, Na kwasya ngoonĩ yake, Ndũkaĩvĩthya?'),
('kam', 'PSA', 10, 14, 'Nĩwoonie; nĩkwĩthĩwa nũsyaasya ũthũku na kĩmena, kũĩvanĩsya na kw’oko kwaku: Ula ũte na vinya eyiaa kwaku; Naku wĩkalĩte ũitetheesya ũla wakw’ĩĩwe nĩ ĩthe.'),
('kam', 'PSA', 10, 15, 'Tũla kw’oko kwa ũla mũthũku; Nake mũndũ mũthũku, mantha ũthũku wake mũvaka waeka kũwona.'),
('kam', 'PSA', 10, 16, 'Yeova nĩwe Mũsumbĩ kũvika tene na tene: I mbaĩ nithelete nthĩ yake.'),
('kam', 'PSA', 10, 17, 'Yeova, nĩwĩw’ĩte kwenda kwa ala auu: Ũkamaseũvya ngoo syoo, ũkatuma kũtũ kwaku kwĩw’a;'),
('kam', 'PSA', 10, 18, 'Ũtw’e sila wa ala makw’ĩĩwe nĩ aaĩthe na wa ala mathĩnaw’a, Nĩ kana mũndũ wa nthĩ ndakaatĩsye ĩngĩ.'),
('kam', 'PSA', 11, 1, 'Nĩngwĩvitha nthĩnĩ wa Yeova: Mwĩtavya thayũ wakwa ata, Ũlũka ta nyũnyi ũkĩĩe kĩĩmanĩ kyaku?'),
('kam', 'PSA', 11, 2, 'Nũndũ, sisya, ala athũku makootete mata moo, Mavakĩĩsye mĩsyĩ yoo ũanĩ, Nĩ kana maathĩe ala alũngalu ngoonĩ kĩvindunĩ;'),
('kam', 'PSA', 11, 3, 'Ethĩwa myambĩlĩlyo ĩkaanangwa, Ala alũngalu matonya kwĩka ata?'),
('kam', 'PSA', 11, 4, 'Yeova e ĩkalũnĩ yake ĩtheu; Yeova, kĩvĩla kyake kya ũsumbĩ kĩ ĩtunĩ; Metho make nĩmasyaasya, ilomo sya metho make nitataa, ana ma andũ.'),
('kam', 'PSA', 11, 5, 'Yeova nũtataa mũndũ mũlũngalu; Ĩndĩ ngoo yake nĩmenete ũla mũthũku na ũla wendete ũng’endu.'),
('kam', 'PSA', 11, 6, 'Akamauĩsya ala athũku itei; Mwaki na mũvĩlitĩ na kĩseve kĩla kĩvĩvasya nĩsyo ikethĩwa kĩanda kya kĩkombe kyoo.'),
('kam', 'PSA', 11, 7, 'Nĩkwĩthĩwa Yeova nĩ mũlũngalu; nĩwendete ũlũngalu: Ala alũngalu nĩmo makona ũthyũ wake.'),
('kam', 'PSA', 12, 1, 'Yeova, tangĩĩa; nĩkwĩthĩwa mũndũ ũla ũmũkĩaa Ngai nde vo ĩngĩ; Nũndũ ala me na kĩthito nĩ athelu katĩ wa ana ma andũ.'),
('kam', 'PSA', 12, 2, 'Maneenaa ũvũngũ kĩla mũndũ na mũtũi wake: Maneenaa na ilomo sya kwendeesya, na me na ngoo ilĩ.'),
('kam', 'PSA', 12, 3, 'Yeova akatila ilomo syonthe ila syendeeasya, Ũĩmĩ ũla ũneenaa na wĩkathĩĩo;'),
('kam', 'PSA', 12, 4, 'Ala maĩtye, Tũkakĩlya vinya na nĩmĩ sitũ; Ilomo ila twĩ nasyo no sitũ: mwĩaĩi ũla wĩ ĩũlũ waitũ nũũ?'),
('kam', 'PSA', 12, 5, 'Nũndũ wa ngya kũthĩna, nũndũ wa kũvevũũka kwa mũthĩni, Oyu nĩngũkĩla, easya ũu Yeova; Ngamwia vandũ vate mũisyo vala vamũvevũũkasya.'),
('kam', 'PSA', 12, 6, 'Ndeto sya Yeova nĩ ndeto ntheu; Ta vetha ũtheew’e ikonĩ ĩnene ya kũũ nthĩ, Ũtheetw’e kũndũ mũonza.'),
('kam', 'PSA', 12, 7, 'Ũkamasũvĩaa, we Yeova, Ũkamasũvĩaa kwa andũ ma ũsyao ũũ kũvika tene na tene.'),
('kam', 'PSA', 12, 8, 'Ala athũku mangangaa ngalĩ syonthe, Yĩla ũthũku ũkũnenevw’a katĩ wa ana ma andũ.'),
('kam', 'PSA', 13, 1, 'Nĩ kũvika ĩndĩĩ, ame Yeova? Ũkoolwa ninyie kũvika tene na tene? Nĩ ĩvinda yĩana ata ũkambitha ũthyũ waku?'),
('kam', 'PSA', 13, 2, 'Nĩ ĩvinda yĩana ata ngĩvindĩĩsya ngoonĩ yakwa, Ngĩkalaa na woo ngoonĩ yakwa mũthenya w’onthe? Nĩ ĩvinda yĩana ata mũmaitha wakwa akĩnenevw’a ĩũlũ wakwa?'),
('kam', 'PSA', 13, 3, 'Sisya nesa na ũinzũngĩa, ame Yeova Ngai wakwa: Ĩkĩa metho makwa kyeni, ndikakome too wa kĩkw’ũ;'),
('kam', 'PSA', 13, 4, 'Nĩ kana mũmaitha wakwa ndakese kwasya, Nĩnamũkĩlilye vinya; Ni kana nthũ syakwa itikatane yĩla ngũthingithangw’a.'),
('kam', 'PSA', 13, 5, 'Ĩndĩ nĩnaĩkĩĩe ũseo waku wĩ wendo; Ngoo yakwa ĩkatanĩa ũtangĩĩonĩ waku.'),
('kam', 'PSA', 13, 6, 'Ngamwinĩa Yeova, Nĩkwĩthĩwa nĩwambĩkie nesa na ũlau.'),
('kam', 'PSA', 14, 1, 'Ndia yaasya ngoonĩ yayo, Kũti Ngai. Nĩmathũkie, nĩmeekie mawĩa mathatasya; Vai ũmwe ũla wĩkaa nesa.'),
('kam', 'PSA', 14, 2, 'Yeova asyaĩĩsye ana ma andũ e ĩtunĩ, Asisye ethĩwa ve ũmwe ũla wĩ na ũmanyi, Ũla ũmũmanthaa Ngai.'),
('kam', 'PSA', 14, 3, 'Onthe nĩmathũkĩte ũtee; onthe vamwe nĩmatw’ĩkĩte avuku; Vai ũmwe wĩkaa nesa, aiee, o na ũmwe.'),
('kam', 'PSA', 14, 4, 'Eki ma naĩ onthe mati na ũmanyi nongi, Ala maĩsaa andũ makwa tondũ maĩsaa lĩu, Na matimwĩkaĩlaa Yeova?'),
('kam', 'PSA', 14, 5, 'Vau malikĩlwe nĩ w’ĩa mũnene; Nũndũ Ngai e vo ũsyaanĩonĩ wa ala alũngalu.'),
('kam', 'PSA', 14, 6, 'Maũndũ ma ũla ngya nĩmũũmasonokya, Ĩndĩ Yeova nĩwe wĩvitho wake.'),
('kam', 'PSA', 14, 7, 'A! Kethĩwa ũtangĩĩo wa Isilaeli wĩthĩwa wuma Saioni! Yĩla Yeova wĩtũnga andũ make maume kũtavwanĩ kwoo, Nĩvo ĩndĩ Yakovo wĩtana, na Isilaeli akeethĩwa na mũyo.'),
('kam', 'PSA', 15, 1, 'Yeova, nũũ ũla wĩĩkalaa wĩkalonĩ waku? Nũũ ũla wĩtũaa kĩĩmanĩ kyaku kĩla kĩtheu?'),
('kam', 'PSA', 15, 2, 'Nĩ ũla ũendaa na mĩendele myaĩlu, na aitethasya mawĩa malũngalu, Na aineenaa w’o ngoonĩ yake;'),
('kam', 'PSA', 15, 3, 'Nĩ ũla ũtasukanaa na uĩmĩ wake, Kana kwĩka mũnyanyae naĩ, Kana kwĩtĩkĩla ndeto sya kĩvũthya ĩũlũ wa mũtũi wake.'),
('kam', 'PSA', 15, 4, 'Methonĩ make ũla mũthũku mũno ũmenetwe, Ĩndĩ nũtaĩaa ala makĩaa Yeova; Eyĩkaa naĩ ũndũnĩ wa kwĩvĩta, na ndaalyũkaa;'),
('kam', 'PSA', 15, 5, 'Ndakovethasya mbesa syake atũngĩwe ũtandĩthyo, Kana kwosa ĩtuvi ya wendeesyo amũthĩn’ye ũla ũte na ĩvĩtyo. Ũla wĩkaa maũndũ asu ndathingithĩka o na ĩndĩĩ.'),
('kam', 'PSA', 16, 1, 'Nzũvĩa, ame Ngai; nĩkwĩthĩwa nthĩnĩ waku nĩngwĩvitha.'),
('kam', 'PSA', 16, 2, 'We ngoo yakwa, nĩwamwĩie Yeova, We nũe Mwĩaĩi wakwa: Ndi na ũseo ate o ũla umaa kwaku.'),
('kam', 'PSA', 16, 3, 'Ngalĩ ĩ ya atheu ala me kũũ nthĩ, Nĩo ma kũtaĩwa ala nĩtanĩaa nthĩnĩ woo.'),
('kam', 'PSA', 16, 4, 'Mawoo moo makaingĩvw’a ala maumasya mĩthĩnzĩo ũndũ wa ngai ingĩ: Nthembo syoo sya ũnyw’a sya nthakame ndikaithemba, Kana kũweta masyĩtwa moo ilomonĩ syakwa.'),
('kam', 'PSA', 16, 5, 'Yeova nĩwe ĩaĩ ya ũtiĩwa wakwa na wa kĩkombe kyakwa: Nũlũlũmĩlasya kĩanda kyakwa.'),
('kam', 'PSA', 16, 6, 'Nĩnathimĩwe kũndũ kũla kwendeeasya; Iĩ, nĩ na ũtiĩwa mũseo.'),
('kam', 'PSA', 16, 7, 'Nĩngũtaĩa Yeova, ũla ũnengete ũtao; Ĩĩ, ngoo yakwa nĩmanyĩasya mavinda ma ũtukũ.'),
('kam', 'PSA', 16, 8, 'Nĩmwiĩte Yeova mbee wakwa mavinda onthe: Nĩkwĩthĩwa e kw’okonĩ kwakwa kwa aũme, ndikathingithangw’a.'),
('kam', 'PSA', 16, 9, 'Kwondũ wa ũu ngoo yakwa yĩ na ũtanu, na ũnene wakwa nũtanaa: Mwĩĩ wakwa naw’o ũkatũaa vate mũisyo.'),
('kam', 'PSA', 16, 10, 'Nũndũ ndũkatia thayũ wakwa Seoli; O na ndũketĩkĩla ũla mũtheu waku one wanangĩko.'),
('kam', 'PSA', 16, 11, 'Ũkambon’ya nzĩa ya thayũ: Kũla ũĩ kwĩ ũtanu wusũĩte; Kw’okonĩ kwaku kwa aũme kwĩ maũndũ ma kwendeesya kũvika tene na tene.'),
('kam', 'PSA', 17, 1, 'Ame Yeova, ĩw’a ũla ũlũngalu, ĩthukĩĩsye kũkaya kwakwa; Ĩthukĩĩsye kũvoya kwakwa, kũla kumaa ilomonĩ ite na ũkengani.'),
('kam', 'PSA', 17, 2, 'Kũtw’ĩwa kwakwa kume vala ũĩ; Metho maku masisye maũndũ malũngalu.'),
('kam', 'PSA', 17, 3, 'Nĩwaoisye ngoo yakwa; nĩwookie vala nĩĩ ũtukũ; Nĩweenguũie, na ndwaaona nĩ na kaũndũ; Nĩnĩtw’ĩte atĩ ndikavĩtya na kanyw’a wakwa.'),
('kam', 'PSA', 17, 4, 'Meko ala mekawa nĩ andũ, ũndũ wa ndeto sya ilomo syaku Nĩnĩsiĩĩĩte ndikaatĩĩe nzĩa sya ala ang’endu.'),
('kam', 'PSA', 17, 5, 'Matambya makwa malũmĩte nzianĩ syaku, Nyaĩĩ syakwa itinatendelũka.'),
('kam', 'PSA', 17, 6, 'Nĩnakwĩkaĩla, nĩkwĩthĩwa ũkanzũngĩa, we Ngai: Tea kũtũ kwaku, wĩw’e ũla ngũneena.'),
('kam', 'PSA', 17, 7, 'Onan’ya ũseo waku wĩ wendo ũla ũseng’asya, We ũla ũmatangĩĩaa na kw’oko kwaku kwa aũme ala mevithaa nthĩnĩ waku Kuma kwa ala mamokĩlĩĩlaa.'),
('kam', 'PSA', 17, 8, 'Nzũvĩaa o ta kyũma kya itho; Mbitha ũngu wa muunyĩ wa nthwau syaku,'),
('kam', 'PSA', 17, 9, 'Ndikonwe nĩ athũku ala manthĩnasya, Ambũai, ala manthũlũlũkĩte.'),
('kam', 'PSA', 17, 10, 'Mavingĩwe nĩ monou moo: Maneenaa na ngathĩĩo na makanyw’a moo.'),
('kam', 'PSA', 17, 11, 'Oyu nĩmatũthyũlũlũkĩte matambyanĩ maitũ; Nĩmatũketee na metho moo nĩ kana matũvalũkye nthĩ.'),
('kam', 'PSA', 17, 12, 'Ailyĩ ta mũnyambũ wĩ na ũtoonu wa ũkwata, Na ta mũnyambũ wa mũika woveesye syĩmbithĩnĩ syaw’o.'),
('kam', 'PSA', 17, 13, 'Ũkĩla, ame Yeova, Mũsiĩĩe, mũvalũkye nthĩ: Vonokya thayũ wakwa kuma kw’okonĩ kwa ũla mũthũku na ũvyũ waku;'),
('kam', 'PSA', 17, 14, 'Na kwa andũ na kw’oko kwaku, ame Yeova, Kuma kwa andũ ma nthĩ ĩno, ala kĩanda kyoo kĩ thayũnĩ ũũ, Na ala mavu moo mavũnawa nĩ sya ĩkũmbĩ yaku: Nĩmeanĩawa nĩ syana, Na ũthwii woo ũla mũtialu ũitiĩwa syana syoo.'),
('kam', 'PSA', 17, 15, 'Ĩndĩ nyie, ngoona ũthyũ waku nĩ na ũlũngalu; Ngeanĩwa, yĩla nĩamũka, nĩvw’anene naku.'),
('kam', 'PSA', 18, 1, 'Nĩngwendete, we Yeova vinya wakwa.'),
('kam', 'PSA', 18, 2, 'Yeova nĩ ĩvia yakwa, na ngome yakwa, na mũvonokya wakwa; Ngai wakwa, ĩvia yakwa, ũla ngeevitha nthĩnĩ wake; Ngao yakwa, na ũvya wa ũtangĩĩo wakwa, na mwako wakwa mũtũlu mũno wa mũnyoolo.'),
('kam', 'PSA', 18, 3, 'Ngeekaĩla Yeova, ũla waĩle kũtaĩwa: Kwondũ wa ũu ngatangĩĩwa kuma kwa amaitha makwa.'),
('kam', 'PSA', 18, 4, 'Ndii sya kĩkw’ũ nĩsyeendingĩlile, Wingĩ wa maũndũ mate kĩkĩo kya Ngai nĩwambĩkĩie w’ĩa.'),
('kam', 'PSA', 18, 5, 'Ndii sya Seoli nĩsyeendingĩlile; Mĩteo ya kĩkw’ũ nĩyangwatie.'),
('kam', 'PSA', 18, 6, 'Nĩ thĩnanĩ ũsu namwĩkaĩla Yeova, Namũkayĩa Ngai wakwa: Nake nĩwewie wasya wakwa e ĩkalũnĩ yake, Na ũkayo wakwa walika matũnĩ make.'),
('kam', 'PSA', 18, 7, 'Na ĩndĩ nthĩ yathingitha na yatetema; Myambĩlĩlyo ya iĩma yathingithangw’a Na yatetema, nũndũ aĩ mũthilĩku.'),
('kam', 'PSA', 18, 8, 'Syũki yambata kuma manyiũũnĩ make, Na mwaki ũminaa wauma kanyw’anĩ wake: Makaa makanw’a nĩw’o.'),
('kam', 'PSA', 18, 9, 'Akonza matu, na atheea nthĩ; Na kĩvindu kya ngokomi kyaĩ ungu wa nyaĩĩ syake.'),
('kam', 'PSA', 18, 10, 'Aenda akuĩtwe nĩ mũkeluvi, na aũlũka: Ĩĩ, aũlũka na nthwau sya kĩseve.'),
('kam', 'PSA', 18, 11, 'Atw’ĩkĩthya kĩvindu wĩvitho wake, ĩlwanda yake yĩmũthyũlũlũkĩte, Kĩvindu kya kĩw’ũ, mathweo makamu matunĩ.'),
('kam', 'PSA', 18, 12, 'Nũndũ wa ũtisu mbee wake mathweo asu makamu make mavĩta, Mbua ya mavia na makaa ma mwaki.'),
('kam', 'PSA', 18, 13, 'Yeova nake atunduma e matunĩ, Na Ũla Wĩ Ĩũlũ wa Onthe aumya wasya wake, Mbua ya mavia na makaa ma mwaki.'),
('kam', 'PSA', 18, 14, 'Nake ekya mĩsyĩ yake, na amanyaĩĩkya; Ĩĩ, atisya motisi main gĩ, na amathokoan’ya.'),
('kam', 'PSA', 18, 15, 'Ĩvinda yĩu tũlũsĩ twa manzĩ twooneka, Na myambĩlĩlyo ya nthĩ yaumĩlw’a ũtheinĩ, Waikan’ya, we Yeova, Waiveveea mĩthũmũ ya manyiũũ maku.'),
('kam', 'PSA', 18, 16, 'Nĩwatũmanie kuma ĩũlũ, ambosa; Anumisye manzĩnĩ maingĩ.'),
('kam', 'PSA', 18, 17, 'Ambonokya kuma kwa mũmaitha wakwa wĩ vinya, Na kuma kwa ala mamenaa; nĩkwĩthĩwa maĩ na vinya kwĩ nyie.'),
('kam', 'PSA', 18, 18, 'Mambũkĩe mũthenya wa thĩna wakwa, mũnene; Ĩndĩ Yeova nĩwe wanũnũmĩlye.'),
('kam', 'PSA', 18, 19, 'Nĩwanumisye na kũndete vandũ vaamu mũno; Ambonokya, nũndũ nĩwendeeiw’e ninyie.'),
('kam', 'PSA', 18, 20, 'Yeova nĩwanduvie kwĩanana na ũlũngalu wakwa; Nĩwandĩvie kwĩanana na ũtheu wa moko makwa.'),
('kam', 'PSA', 18, 21, 'Nĩkwĩthĩwa nĩngwatĩte nzĩa sya Yeova, Na ndyaatia Ngai wakwa ngeka ũthũku.'),
('kam', 'PSA', 18, 22, 'Nũndũ motw’ĩo make onthe maĩ mbee wakwa, Na myamũlo yake ndyaataanĩsya nayo.'),
('kam', 'PSA', 18, 23, 'Na ĩngĩ naĩ mwĩanĩu kwake, Na neesiĩĩa ũthũku wakwa.'),
('kam', 'PSA', 18, 24, 'Kwondũ wa ũu Yeova nĩwandĩvie kwĩanana na ũlũngalu wakwa, Kwĩanana na ũtheu wa moko makwa ũla wonaa na metho make.'),
('kam', 'PSA', 18, 25, 'Kwa ũla wĩ tei ũkeeyonan’ya wĩ tei; Kwa mũndũ mwĩanĩu ũkeeyonan’ya wĩ mwĩanĩu;'),
('kam', 'PSA', 18, 26, 'Kwa ũla mũtheu ũkeeyonan’ya wĩ mũtheu; Na kwa ũla mũng’endu ũkeeyonan’ya wĩ na wai.'),
('kam', 'PSA', 18, 27, 'Nĩkwĩthĩwa ũkamatangĩĩa ala mathĩnaw’a; Ĩndĩ metho mekwĩng’athĩlĩlya ũkamatheesya.'),
('kam', 'PSA', 18, 28, 'Nĩkwĩthĩwa nue ũkakwatya taa wakwa: Yeova Ngai wakwa akamulĩka kĩvindu kyakwa.'),
('kam', 'PSA', 18, 29, 'Nũndũ kwondũ waku nĩngũvũthũa nguthu; Na kwondũ wa Ngai wakwa nĩngũthaanyũka ũvai.'),
('kam', 'PSA', 18, 30, 'Na ũndũ wa Ngai, nzĩa yake nĩ mbĩanĩu: Ndeto ya Yeova nĩtatĩtwe; Nake nĩ ngao ya onthe ala mevithaa nthĩnĩ wake.'),
('kam', 'PSA', 18, 31, 'Nũndũ Ngai nũũ, ate o Yeova? Na nũũ ĩvia, ate o Ngai waitũ?'),
('kam', 'PSA', 18, 32, 'We nĩ Ngai ũla ũmbotoaa vinya, Na nĩwe wĩanĩasya nzĩa yakwa.'),
('kam', 'PSA', 18, 33, 'Nũtw’ĩkĩthasya maũũ makwa ta maũũ ma ndaatai nga: Na nũmbiĩte ĩũlũ wa kũndũ kwakwa kũtũlu.'),
('kam', 'PSA', 18, 34, 'Nũmanyĩasya moko makwa kũkita; Kwondũ wa ũu moko makwa nĩmakootaa ũta wa ũthuku.'),
('kam', 'PSA', 18, 35, 'Naku nũnengete ngao ya ũtangĩĩo waku; Kw’oko kwaku kwa aũme nĩkw’o kũngwatĩte, Na ũuu waku nũnenevetye.'),
('kam', 'PSA', 18, 36, 'Nũnenevetye matambya makwa ungu wakwa, Na maũũ makwa matyaatendelũka.'),
('kam', 'PSA', 18, 37, 'Ngamaatĩĩa amaitha makwa, na kũmakwata; O na ndikethyũũa mũvaka maminwa vyũ.'),
('kam', 'PSA', 18, 38, 'Ngamatonya mũkuthũ, na ĩndĩ matikatonya kũkĩla: Makavalũka ungu wa nyaĩĩ syakwa.'),
('kam', 'PSA', 18, 39, 'Nĩkwĩthĩwa nũmbotoete vinya nũkite kaũ: Nũmakunamĩtye ala mambũkĩlĩle.'),
('kam', 'PSA', 18, 40, 'Na ĩngĩ nũtumĩte amaitha makwa mambon’ya mĩongo yoo, Nĩ kana nĩvete ala mamenaa.'),
('kam', 'PSA', 18, 41, 'Nĩmakayie, ĩndĩ vatyaĩ wa ũmatangĩĩa; Ĩĩ, mamwĩkaĩla Yeova, ĩndi ndaamasũngĩa.'),
('kam', 'PSA', 18, 42, 'Na ĩndĩ namatumbatumba mavinya ta kĩtoo mbee wa kĩseve; Namekya nza ta ndaka nzĩanĩ nene.'),
('kam', 'PSA', 18, 43, 'Nũmbonoketye kuma motetan’yonĩ ma andũ; Nũndw’ĩte mũnene wa ĩ mbaĩ: Ũko wa andũ ala ndaamanya ũkanthũkũma.'),
('kam', 'PSA', 18, 44, 'O yĩla meĩw’a ũvoo wakwa makambĩw’aa; Andũ ma nthĩ ĩngĩ makeenyivasya vala nĩĩ.'),
('kam', 'PSA', 18, 45, 'Andũ manthĩ ĩngĩ makathelekelya, Na makauma kũla mevithĩte matetemete.'),
('kam', 'PSA', 18, 46, 'Yeova e thayũ: na ĩvia yakwa yĩtaĩwe; Na nanenevw’e Ngai wa ũtangĩĩo wakwa,'),
('kam', 'PSA', 18, 47, 'O Ngai ũla ũndĩvanĩasya, Na kũnyivya ngo sya andũ syĩthĩwe ĩtheo wakwa.'),
('kam', 'PSA', 18, 48, 'Embonokya kwa amaitha makwa; Ĩĩ, nũmbũkĩlasya ĩũlũ wa ala mambũkĩlĩĩlaa; Nũmbonokasya kwa mũndũ mũng’endu.'),
('kam', 'PSA', 18, 49, 'Kwondũ wa ũu ngakũtũngĩa mũvea, ame Yeova, katĩ wa i mbaĩ, Na ngaina ngĩkumya syĩtwa yaku.'),
('kam', 'PSA', 18, 50, 'Nũnengae mũsumbĩ wake ũvonokyo mũnene, Na kwonanasya ũseo wĩ wendo kwa ũla mwĩtĩkĩw’a mauta wake, Kwa Ndaviti na ũsyao wake, tene na tene.'),
('kam', 'PSA', 19, 1, 'Matu nĩmatavanasya ũtheu mũtisu wa Ngai; Na yayaya yonanasya wĩa wa moko make.'),
('kam', 'PSA', 19, 2, 'Mũthenya na mũthenya nĩneenanasya, Ũtukũ na ũtukũ nĩsyonanasya ũmanyi.'),
('kam', 'PSA', 19, 3, 'Vai kĩneeno kana kĩthyomo; Wasya wasyo ndwĩw’ĩkaa.'),
('kam', 'PSA', 19, 4, 'Ũmanyĩsyo wasyo nũtũnganĩte nthĩ yonthe, Na ndeto syasyo kũvika itulu sya nthĩ. Nthĩnĩ wasyo nĩwĩkĩĩte wĩkalo wa syũa,'),
('kam', 'PSA', 19, 5, 'Yĩla yĩilyĩ mũtwaani akyuma kasũmbanĩ kake, Na yĩtanaa tondũ mũndũ wĩ vinya ũtanaa aisemba ũkĩlanyonĩ wake.'),
('kam', 'PSA', 19, 6, 'Kumĩla kwayo nĩ kuma kĩtulu kya matu, Na kũthyũlũlũka kwayo kũvika itulu syamo; Na vai kĩndũ kĩvithĩte ũvyũvu wayo.'),
('kam', 'PSA', 19, 7, 'Mĩao ya Yeova nĩ mĩanĩu, ĩkĩvuũkya ngoo; Ũkũsĩ wa Yeova nĩ mũlũmu, nũmũĩvasya ũla ũte na ũmanyi.'),
('kam', 'PSA', 19, 8, 'Mawĩaĩo ma Yeova nĩ ma w’o, matanasya ngoo: Mwĩao wa Yeova nĩ mũtheu, wĩkĩaa metho kyeni.'),
('kam', 'PSA', 19, 9, 'Kũmũkĩa Yeova nĩ kũtheu, kwĩkalaa tene na tene: Motw’ĩo ma Yeova nĩ ma w’o, na malũngalu ki.'),
('kam', 'PSA', 19, 10, 'Nĩmaĩlwe nĩ kwendwa kũvĩta thaavu, ĩĩ, kũvĩta thaavu mũseo mwingĩ: Namo me mũyo kwĩ ũkĩ wa nzũkĩ na mũvolotango wa mawa.'),
('kam', 'PSA', 19, 11, 'Na ĩngĩ kwondũ wamo mũthũkũmi waku nũtaĩkaa: Kwĩ ĩtuvi ĩnene kwondũ wa kũmasũvĩaa.'),
('kam', 'PSA', 19, 12, 'Nũũ ũla ũtonya kũmanya mavĩtyo make? Nthesya mavĩtyo ala mavithĩtwe.'),
('kam', 'PSA', 19, 13, 'Na ĩngĩ mũthũkũmi waku mũsiĩĩe na naĩ sya ngũlũ; Itikanzumbĩke: Na ĩndĩ ngeethĩwa nĩ mwaĩlu, Na ngeethĩwa nĩtheetw’e ĩvĩtyo yĩla ĩnene.'),
('kam', 'PSA', 19, 14, 'Ndeto sya kanyw’a wakwa, na mosũanĩo ma ngoo yakwa Nĩmetĩkĩlĩke mbee waku, Ame Yeova, ĩvia yakwa, na mwovosya wakwa.'),
('kam', 'PSA', 20, 1, 'Yeova nakũsũngĩe mũthenya wa thĩna; Syĩtwa ya Ngai wa Yakovo yĩkũkĩlye ĩũlũ;'),
('kam', 'PSA', 20, 2, 'Akũetee ũtethyo kuma vala vandũ vatheu, Na kũkwĩkĩa vinya e Saioni;'),
('kam', 'PSA', 20, 3, 'Alilikane nthembo syaku syonthe, Na amĩtĩkĩle nthembo yaku ya kũvĩvw’a;'),
('kam', 'PSA', 20, 4, 'Akũnenge kwenda kwa ngoo yaku, Na eanĩsye mosũanĩo maku onthe.'),
('kam', 'PSA', 20, 5, 'Tũkakĩlya vinya ũtangĩĩonĩ waku, Na syĩtwanĩ ya Ngai waitũ tũkookĩlya ivevelo sitũ: Yeova nakwĩanĩsye mboya syaku syonthe.'),
('kam', 'PSA', 20, 6, 'Oyu nĩnĩsĩ kana Yeova nũnũũtangĩĩa mwĩtĩkĩw’a mauta wake; Akamũsũngĩa e ĩtunĩ yake ĩtheu Na vinya wa ũtangĩĩo wa kw’oko kwake kwa aũme.'),
('kam', 'PSA', 20, 7, 'Andũ amwe mekwatasya makasya ma kaũ, na angĩ mbalasi; Ĩndĩ ithyĩ tũkawetaa syĩtwa ya Yeova Ngai waitũ.'),
('kam', 'PSA', 20, 8, 'Mo nĩmekunamĩtye nthĩ na kũvalũka; Ĩndĩ ithyĩ nĩtũkĩlĩte, na kũũngama ki.'),
('kam', 'PSA', 20, 9, 'Tangĩĩa, Yeova: Mũsumbĩ natũsũngĩe yĩla tũũmwĩkaĩla.'),
('kam', 'PSA', 21, 1, 'Mũsumbĩ akatana vinyanĩ waku, we Yeova; Na sisya ũndũ ũtanĩĩte ũtangĩĩo waku!'),
('kam', 'PSA', 21, 2, 'Nũmũnengete kwenda kwa ngoo yake, Na ndũnamũvata mboya sya ilomo syake.'),
('kam', 'PSA', 21, 3, 'Nĩkwĩthĩwa nũkomanĩte nake na moathimo ma ũseo: Nũmwĩkĩĩte mũtwenĩ wake ngovia ya ũsumbĩ ya thaavu mũseo.'),
('kam', 'PSA', 21, 4, 'Akũkũlilye thayũ, na wamũnenga w’o, Ĩĩ, mĩthenya mingĩ kũvika tene na tene.'),
('kam', 'PSA', 21, 5, 'Utaĩo wake nĩ mũnene ũndũ wa ũtangĩĩo waku: Nũmwiĩe ndaĩa na ũnene.'),
('kam', 'PSA', 21, 6, 'Nĩkwĩthĩwa nũathimĩtwe nue mũno mbee kũvika tene na tene: Nũũmũtanĩthya na ũtanu wa ũthyũ waku.'),
('kam', 'PSA', 21, 7, 'Nĩkwĩthĩwa mũsumbĩ nũĩkĩĩaa Yeova; Na kwondũ wa ũseo wĩ wendo wa Ũla Wĩ Ĩũlũ wa Onthe ndakathingithw’a.'),
('kam', 'PSA', 21, 8, 'Kw’oko kwaku kũkamavikĩa amaitha maku onthe; Kw’oko kwaku kwa aũme kũkamavikĩa onthe ala makumenaa.'),
('kam', 'PSA', 21, 9, 'Ũkamatw’ĩkĩthya ta iko ĩnene yĩ mwaki ĩvinda ya ũthatu waku: Yeova akamamelya ũthilĩkunĩ wake, Na ũla mwaki ũkamamina.'),
('kam', 'PSA', 21, 10, 'Ukaananga mosyao moo mavetwe kũũ nthĩ, Na ũsyao woo kuma katĩ wa ana ma andũ.'),
('kam', 'PSA', 21, 11, 'Nĩkwĩthĩwa nĩmakũsũanĩĩte ũthũku; Mavindĩĩsye ũsũanĩo matatonya kwĩka.'),
('kam', 'PSA', 21, 12, 'Nĩkwĩthĩwa ũkatuma monan’ya mĩongo yoo; Yĩla wĩkootea mothyũ moo ũta waku.'),
('kam', 'PSA', 21, 13, 'Ũnenevw’e, we Yeova, vinyanĩ waku: Na kwondũ wa ũu tũkaina na kũkatha ũtonyi waku.'),
('kam', 'PSA', 22, 1, 'Ngai wakwa, Ngai wakwa, ũndekee kĩ? Nĩkĩ wĩ kũasa ũu ũteũndethya, na wĩ kũasa na ndeto sya kĩlumo kyakwa?'),
('kam', 'PSA', 22, 2, 'Ame Ngai wakwa, nĩkaya mũthenya, ĩndĩ ndũũnzũngĩa; O na ũtukũ naw’o, na ndivindasya.'),
('kam', 'PSA', 22, 3, 'Ĩndĩ naku wĩ mũtheu. We ũla wĩkalaa ndaĩanĩ sya Isilaeli.'),
('kam', 'PSA', 22, 4, 'Aasa maitũ nĩmakũĩkĩĩe: Maĩkĩĩe, na wamavonokya.'),
('kam', 'PSA', 22, 5, 'Makwĩkaĩla, na mavonokw’a: Nĩmakũĩkĩĩe, na matyaasonokw’a.'),
('kam', 'PSA', 22, 6, 'Ĩndĩ nyie nĩ kĩinyu, na ndi mũndũ nyie; Mũkũngw’a kwa andũ, na kũvũthw’a andũnĩ.'),
('kam', 'PSA', 22, 7, 'Onthe ala mambonaa manthekeea mũno: Makĩkoota ilomo, makĩthingithangya mĩtwe, makyasya,'),
('kam', 'PSA', 22, 8, 'Nĩwamũĩkĩĩe Yeova, kana akamũvonokya: Namũvonokye, nĩkwĩthĩwa nĩwendeew’e nĩwe.'),
('kam', 'PSA', 22, 9, 'Ĩndĩ nue ũla wanumisye ĩvunĩ; Nĩwandĩkĩĩthisye yĩla naĩ nondonĩ sya mwaitũ.'),
('kam', 'PSA', 22, 10, 'Nĩnekiw’e kwaku o kuma ĩvunĩ; Nue Ngai wakwa ĩvinda yonthe kuma mwaitũ anzyaa.'),
('kam', 'PSA', 22, 11, 'Ndũkethĩwe wĩ kũasa nakwa; nũndũ thĩna wĩ vakuvĩ; Nĩkwĩthĩwa vai wa kũndethya.'),
('kam', 'PSA', 22, 12, 'Nĩnthyũlũlũkĩtwe nĩ nzaũ mbingĩ; Nzaũ syĩ vinya sya Mbasani nĩsyĩndingĩlĩte.'),
('kam', 'PSA', 22, 13, 'Nimbathamĩsye makanyw’a masyo, O ta mũnyambũ ũkĩvulya na kũluma.'),
('kam', 'PSA', 22, 14, 'Nĩnĩtĩkĩte o tondũ manzĩ metĩkaa, Na mavĩndĩ makwa onthe nĩmataanĩsye: Ngoo yakwa ĩilyĩ ta maseso; Nĩtwekee nthĩnĩ wakwa.'),
('kam', 'PSA', 22, 15, 'Vinya wakwa nĩũmĩte ta kĩlio; Na ũĩmĩ wakwa nũkwatanĩte na ngambuu syakwa; Na nũmbikĩtye kĩtoonĩ kya kĩkw’ũ.'),
('kam', 'PSA', 22, 16, 'Nĩkwĩthĩwa ngitĩ ninthyũlũlũkĩte: Nguthu ya eki ma naĩ nĩĩndingĩlĩte; Nĩmandonyie moko na maũũ.'),
('kam', 'PSA', 22, 17, 'Nĩndonya kũtala mavĩndĩ makwa onthe, Nao nĩmanzyaĩtye na kũngeteea;'),
('kam', 'PSA', 22, 18, 'Nĩmaanisye ngũa syakwa katĩ woo, Na kwondũ wa kĩtonyeo kyakwa kĩasa nĩmakĩlimanĩle.'),
('kam', 'PSA', 22, 19, 'Ame Yeova, ndũkethĩwe wĩ kũasa nakwa: We ũtethyo wakwa, ĩkalaate mĩtũkĩ ũndethye.'),
('kam', 'PSA', 22, 20, 'Vonokya thayũ wakwa na ũvyũ, No ũmwe wakwa ũvonokye na ũtonyi wa ngitĩ.'),
('kam', 'PSA', 22, 21, 'Ndangĩĩa na kanyw’a wa mũnyambu; Ĩĩ, nĩ mbyanĩ sya mboo nĩwanzũngĩie.'),
('kam', 'PSA', 22, 22, 'Ngatavan’ya syĩtwa yaku kwa ana‐a‐asa makwa: Ngakũtaĩa ũmbanonĩ.'),
('kam', 'PSA', 22, 23, 'Inyw’ĩ ala mũkĩaa Yeova, mũtaĩei; Inyw’onthe ũsyao wa Yakovo, mũkathei; Mũkĩei we, inyw’onthe ũsyao wa Isilaeli.'),
('kam', 'PSA', 22, 24, 'Nĩkwĩthĩwa we ndaavũthya kana kũthĩtha thĩna wa ũla ũthĩnaw’a; O na ndaamũvitha ũthyũ wake; Ĩndĩ yĩla wamwĩkaĩlile, nĩwamwĩwie.'),
('kam', 'PSA', 22, 25, 'Ndaĩa syakwa ũmbanonĩ ũla mũnene syumaa kũla ũĩ: Ngeanĩsya mawĩvĩto makwa mbee wa ala mamũkĩaa.'),
('kam', 'PSA', 22, 26, 'Ala auu makaĩsaa na kũvũna; Makamũtaĩaa Yeova ala mamũmanthaa: Ngoo syenyu syĩkale thayũ tene na tene.'),
('kam', 'PSA', 22, 27, 'Itulu syonthe sya nthĩ ikalilikana na kũmwĩthyũũĩa Yeova; Na mbee waku mĩvĩa yonthe ya i mbaĩ ĩkathaithaa.'),
('kam', 'PSA', 22, 28, 'Nĩkwĩthĩwa ũsumbĩ nĩ wa Yeova; Nake nĩwe ũsumbĩkĩte i mbaĩ.'),
('kam', 'PSA', 22, 29, 'Andũ ala anou onthe ma nthĩ makaĩsaa na kũthaitha: Namo onthe ala matheeaa kĩtoonĩ makatulya ndu mbee wake, O na ũla ũtatonya kwĩyĩkalya thayũ.'),
('kam', 'PSA', 22, 30, 'Kwĩ ũsyao ũkamũthũkũma; Kũkatavanw’a ũvoo wa Mwĩaĩi kũvika nzyawa ĩla ĩkoka.'),
('kam', 'PSA', 22, 31, 'Makooka na makatavan’ya ũlũngalu wake Andũnĩ ala makasyawa, kana nĩwe wekie ũu.'),
('kam', 'PSA', 23, 1, 'Yeova nĩwe mũĩthi wakwa; ndikaĩwa nĩ kĩndũ.'),
('kam', 'PSA', 23, 2, 'Nũndindiasya isesinĩ syĩ nyeki ya vuvĩ; Nũndongoeasya ũtee wa manzĩ makilĩtye ki.'),
('kam', 'PSA', 23, 3, 'Nũmbuũkasya ngoo yakwa: Nũndongoeasya nzĩanĩ sya ũlũngalu kwondũ wa syĩtwa yake.'),
('kam', 'PSA', 23, 4, 'Ĩĩ, o na ngavĩtĩla kyandanĩ kya kyuu kya kĩkw’ũ, Ndikakĩa ũndũ ũthũku; nĩkwĩthĩwa wĩ vamwe nakwa; Mũnzyũ waku na ndata yaku, ningiakiasya.'),
('kam', 'PSA', 23, 5, 'Nũmbalanĩlasya mesa mbee wa amaitha makwa: Nũmbakĩte mũtwe wakwa mauta; Kĩkombe kyakwa nĩkyusũĩte na nĩkĩkwĩtĩkanga.'),
('kam', 'PSA', 23, 6, 'Vate ngananĩo mĩthenya yonthe ya thayũ wakwa ũseo na tei nimbikĩlaa; Nakwa nĩngatĩnĩka nyũmbanĩ ya Yeova tene na tene.'),
('kam', 'PSA', 24, 1, 'Nthĩ nĩ ya Yeova, o na syĩndũ ila imyusũĩte; Nthĩ, na ala mamĩtwĩe.'),
('kam', 'PSA', 24, 2, 'Nĩkwĩthĩwa nĩwe wamyambĩlĩlye ĩũlũ wa maũkanga, Na amĩlũlũmĩlya ĩũlũ wa manzĩ maingĩ.'),
('kam', 'PSA', 24, 3, 'Nũũ ũla wĩambata kĩĩmanĩ kya Yeova? Na nũũ ũla wĩũngama vandũ vake vatheu?'),
('kam', 'PSA', 24, 4, 'Nĩ ũla wĩ na moko matheu, na ngoo ntheu; Ũla ũtaaĩyimbya aneene ũvũngũ, O na ndaaĩvĩta na ũkengani.'),
('kam', 'PSA', 24, 5, 'Nake akoosa ũathimo kuma kwa Yeova, Na ũlũngalu kuma kwa Ngai wa ũtangĩĩo wake.'),
('kam', 'PSA', 24, 6, 'Ũũ nĩw’o ũsyao wa ala mamũmanthaa, Ala mamanthaa ũthyũ waku we, Ngai wa Yakovo.'),
('kam', 'PSA', 24, 7, 'Ũkĩlyai mĩtwe yenyu, inyw’ĩ mbingĩlo; Ũkĩlai, inyw’ĩ mĩomo ya tene na tene: Na Mũsumbĩ wa ũtheu mũtisu akalika.'),
('kam', 'PSA', 24, 8, 'Mũsumbĩ ũsu wa ũtheu mũtisu nũũ? Nĩwe Yeova wĩ ũtonyi na vinya, Nĩ Yeova ũla wĩ na vinya kaũnĩ.'),
('kam', 'PSA', 24, 9, 'Ũkĩlyai mĩtwe yenyu, inyw’ĩ mbingĩlo; Ĩĩ, nenyu ũkĩlyai mĩtwe, inyw’ĩ mĩomo ya tene na tene: Na Mũsumbĩ wa ũtheu mũtisu akalika.'),
('kam', 'PSA', 24, 10, 'Mũsumbĩ ũsu wa ũtheu mũtisu nũũ? Yeova wa nguthu, Nĩwe Mũsumbĩ wa ũtheu mũtisu.'),
('kam', 'PSA', 25, 1, 'Nĩngũkũkĩlĩlya ngoo yakwa, we Yeova.'),
('kam', 'PSA', 25, 2, 'Ngai wakwa, nue nĩkwatĩtye, Ndikasonokw’e; Amaitha makwa matikangĩlye vinya.'),
('kam', 'PSA', 25, 3, 'Ĩĩ, ala makweteelaa vai ũmwe ũkasonokw’a: Makasonoka ala mekaa naĩ na ũkengani vate kĩtumi.'),
('kam', 'PSA', 25, 4, 'Mbon’ya moendelo maku, we Yeova; Manyĩsya nzĩa syaku.'),
('kam', 'PSA', 25, 5, 'Ndongoesya nthĩnĩ wa w’o waku, na kũmanyĩsya; Nĩkwĩthĩwa nue Ngai wa ũtangĩĩo wakwa; Nĩngũkweteela mũthenya w’onthe.'),
('kam', 'PSA', 25, 6, 'Lilikana, ame Yeova, matei maku mololo o na moseo maku me wendo; Nũndũ o na tene tene nĩ vo maĩ.'),
('kam', 'PSA', 25, 7, 'Ndũkalilikane naĩ sya wana wakwa, o na mavĩtyo makwa: Kwĩanana na ũseo waku wĩ wendo ndilikana, Kwondũ wa ũseo waku, ame Yeova.'),
('kam', 'PSA', 25, 8, 'Yeova nĩ mũseo na mũlũngalu: Kwondũ wa ũu akamamanyĩsya athe mamanye nzĩa.'),
('kam', 'PSA', 25, 9, 'Ala auu akamatongoeasya ũlũngalunĩ; Nao ala auu akamamanyĩsya nzĩa yake.'),
('kam', 'PSA', 25, 10, 'Nzĩa syonthe sya Yeova nĩ sya ũseo wĩ wendo na sya w’o Kwa ala malũmĩtye ũtianĩo wake na mokũsĩ make.'),
('kam', 'PSA', 25, 11, 'Kwondũ wa syĩtwa yaku, ame Yeova, Ndekea naĩ syakwa, nĩkwĩthĩwa nĩ nene.'),
('kam', 'PSA', 25, 12, 'Nĩ mũndũ wĩva ũla ũmũkĩaa Yeova? Ũsu akamũmanyĩsya nzĩa ĩla wĩnyuvaa.'),
('kam', 'PSA', 25, 13, 'Thayũ wake ũkatũaa o nesa; Na ũsyao wake ũkatiĩwa nthĩ.'),
('kam', 'PSA', 25, 14, 'Nzama ya Yeova yĩ na ala mamũkĩaa; Na akamon’ya ũtianĩo wake.'),
('kam', 'PSA', 25, 15, 'Metho makwa melekele Yeova mavinda onthe; Nĩkwĩthĩwa nake akanumya maũũ makwa mũteonĩ.'),
('kam', 'PSA', 25, 16, 'Ĩnthyũũĩe, na mbĩw’ĩa tei; Nũndũ nĩkalaa nĩ nyioka na nĩngũnyamaw’a.'),
('kam', 'PSA', 25, 17, 'Mathĩna ma ngoo yakwa nĩmaingĩvie: Numya monyamaonĩ makwa.'),
('kam', 'PSA', 25, 18, 'Sisya thĩna wakwa na kũnyamaa kwakwa; Na ndekea naĩ syakwa syonthe.'),
('kam', 'PSA', 25, 19, 'Sisya amaitha makwa, nĩkwĩthĩwa nĩ aingĩ; Na nĩmeũmena na kĩmena kyai.'),
('kam', 'PSA', 25, 20, 'Sũvĩa thayũ wakwa, na mbonokya: Ndikasonokw’e, nĩkwĩthĩwa nĩngwĩvitha nthĩnĩ waku.'),
('kam', 'PSA', 25, 21, 'Wĩanĩu na ũlũngalu nimbĩkalye nesa, Nĩkwĩthĩwa nĩngũkweteela.'),
('kam', 'PSA', 25, 22, 'Ovosya Isilaeli, ame Ngai, Aũme mathĩnanĩ make onthe.'),
('kam', 'PSA', 26, 1, 'Nzilĩla, ame Yeova, nĩkwĩthĩwa nĩnĩendete wĩanĩunĩ wakwa: Nake Yeova nĩnamwĩkwatisye vate kũthingithĩka.'),
('kam', 'PSA', 26, 2, 'Ndata, ame Yeova, na ũingosya; Ĩkuũe ngoo yakwa na kĩlĩko kyakwa.'),
('kam', 'PSA', 26, 3, 'Nũndũ ũseo waku wĩ wendo wĩ mbee wa metho makwa; Na nĩnĩendete nthĩnĩ wa w’o waku.'),
('kam', 'PSA', 26, 4, 'Ndyaaĩkalan’ya na andũ ma ũvũngũ; O na ndikaatĩanĩa na akengani.'),
('kam', 'PSA', 26, 5, 'Nĩngũmena ũmbano wa eki ma naĩ, Na ndikekala nthĩ na ala athũku.'),
('kam', 'PSA', 26, 6, 'Ngathambĩsya moko makwa ũtheunĩ wa kũlea kwĩka naĩ: Kwondũ wa ũu ngathyũlũlũka kĩthembeo kyaku, we Yeova;'),
('kam', 'PSA', 26, 7, 'Nĩ kana nĩtume wasya wa kũtũngĩa mũvea wĩw’ĩka, Na kũtavan’ya meko maku onthe ma ũseng’ya.'),
('kam', 'PSA', 26, 8, 'Yeova, nĩnendaa vau vala ve nyũmba yaku, O vandũ vala ũtheu mũtisu waku wĩkalaa.'),
('kam', 'PSA', 26, 9, 'Ndũkose thayũ wakwa vamwe na ala athe, O na ndũkose thayũ wakwa vamwe na andũ metĩkasya nthakame;'),
('kam', 'PSA', 26, 10, 'Nao mokonĩ moo kwĩ mĩkwa myathe, Na kw’oko kwoo kwa aũme kusũĩte mavaki.'),
('kam', 'PSA', 26, 11, 'Ĩndĩ nyie, ngaendaa wĩanĩunĩ wakwa: Mbovosya, na mbĩw’ĩa tei.'),
('kam', 'PSA', 26, 12, 'Kũũ kwakwa kũũngamaa vandũ vatindimalu: Maũmbanonĩ ngamũtaĩaa Yeova.'),
('kam', 'PSA', 27, 1, 'Yeova nĩ kyeni kyakwa na ũtangĩĩo wakwa; Ngakĩa ũũ? Yeova nĩ vinya wa thayũ wakwa; Nũũ ũla nĩkĩa?'),
('kam', 'PSA', 27, 2, 'Yĩla eki ma naĩ mambũkĩe maye nyama ya mwĩĩ wakwa, O nthũ syakwa na amaitha makwa, nĩmalũlũtĩkile na kũvalũka.'),
('kam', 'PSA', 27, 3, 'O na ethĩwa nguthu ĩkanthyũlũlũkya maeema, Ngoo yakwa ndĩkakĩa: O na ethĩwa kaũ ũkambũkĩlĩla, Ĩvinda yĩu ngethĩwa ngĩĩkĩĩa.'),
('kam', 'PSA', 27, 4, 'Ũndũ ũmwe nĩmũkũlĩtye Yeova, na nĩw’o nĩmanthaa: Nĩ kana nĩkalae nyũmbanĩ ya Yeova mĩthenya yonthe ya thayũ wakwa, Nonae ũseo wa Yeova, Na ũvoyeaa ĩkalũnĩ yake.'),
('kam', 'PSA', 27, 5, 'Nĩkwĩthĩwa mũthenya wa thĩna akambitha nthĩnĩ wa ĩlwanda yake: Wĩvithonĩ wa ĩeema yake akambitha; Akandũlya ĩũlũ wa ĩvia.'),
('kam', 'PSA', 27, 6, 'Na yu mũtwe wakwa ũkookĩlw’a ĩũlũ wa amaitha makwa ala manthyũlũlũkĩte; Na ngathembea nthembo sya ũtanu ĩeemanĩ yake; Ngaina, ĩĩ, ngaina ngĩmũkumya Yeova.'),
('kam', 'PSA', 27, 7, 'Ĩw’a, ame Yeova, yĩla ngũkwĩkaĩla na wasya wakwa: Na ĩngĩ mbĩw’ĩa tei, na nzũngĩa.'),
('kam', 'PSA', 27, 8, 'Yĩla waisye, Mantha ũthyũ wakwa; ngoo yakwa yakwĩa, Ũthyũ waku, Yeova, nĩw’o ngũmantha.'),
('kam', 'PSA', 27, 9, 'Ndũkambithe ũthyũ waku; Ndũkalũngye mũthũkũmi waku wĩ mũthatu: Wĩkalĩte wĩ mũtethya wakwa; Ndũkaandeke, kana kũndia, ame Ngai wa ũtangĩĩo wakwa.'),
('kam', 'PSA', 27, 10, 'Nũndũ nau na mwaitũ nĩmandiie, Ĩndĩ Yeova akambosa.'),
('kam', 'PSA', 27, 11, 'Manyĩsya ũendelo waku, ame Yeova; Na ndongoesya nzĩanĩ ndũngalu, Nũndũ wa amaitha makwa.'),
('kam', 'PSA', 27, 12, 'Ndũkanengane kwendanĩ kwa amaitha makwa: Nĩkwĩthĩwa ngũsĩ sya ũvũngũ nimbũkĩlĩle, Na ala kũveva kwoo nĩ kũthĩn’ya kũthei.'),
('kam', 'PSA', 27, 13, 'Nakwa nĩthĩwa nanyalile, keka neetĩkĩlile kana ngoona ũseo wa Yeova Nĩ o nthĩ ya andũ ala me thayũ.'),
('kam', 'PSA', 27, 14, 'Mweteele Yeova: Ĩthĩwa na vinya, na ngoo yaku yĩthĩwe na ũnyiau; Ĩĩ, mweteele Yeova.'),
('kam', 'PSA', 28, 1, 'Ame Yeova, nue nĩĩkaĩla: Ĩvia yakwa, ndũkalee ũmbĩw’a; Ethĩwa nũũmbindĩsya, Ngesa ũvw’anana na ala matheeaa yĩla ĩimanĩ.'),
('kam', 'PSA', 28, 2, 'Ĩw’aa wasya wa mawĩsũvano makwa, yĩla ngũkwĩkaĩla, Yĩla ngũkĩlya moko makwa melekele vandũ vaku vatheu va ũneenea.'),
('kam', 'PSA', 28, 3, 'Ndũkangusanĩsye vamwe na ala athũku, Vamwe na ala mekaa naĩ; Ala maneenaa mũuo na atũi moo, Ĩndĩ ũthũku wĩ ngoonĩ syoo.'),
('kam', 'PSA', 28, 4, 'Manenge o kwĩanana na wĩa woo, na kwĩanana na ũthũku wa meko moo: Ũmanenge kwĩanana na meko ma moko moo; Matũngĩe ũndũ maĩlwe.'),
('kam', 'PSA', 28, 5, 'Nĩkwĩthĩwa maiũsũanĩa meko ma Yeova, Kana wĩa wa moko make, Nake akamaomboa o na ndakamatũngĩĩa.'),
('kam', 'PSA', 28, 6, 'Yeova nataĩwe, Nũndũ nĩwewie wasya wa kwĩsũvana kwakwa.'),
('kam', 'PSA', 28, 7, 'Yeova nĩwe vinya wakwa na ngao yakwa; Ngoo yakwa nĩmũĩkĩĩe, na nĩngũtethw’a: Kwondũ wa ũu ngoo yakwa nĩtanaa mũno; Na ngamũtaĩa na wathi wakwa.'),
('kam', 'PSA', 28, 8, 'Yeova nĩ vinya woo, Nake nĩ ngome yĩ vinya ya ũtangĩĩo kwa mwĩtĩkĩw’a mauta wake.'),
('kam', 'PSA', 28, 9, 'Tangĩĩa andũ maku, na athima ũtiĩwa waku: O na ĩngĩ ĩthĩwa mũĩthi woo, ũmakuae kũvika tene na tene.'),
('kam', 'PSA', 29, 1, 'Mũwetei Yeova, inyw’ĩ ana ma ũla wĩ na ũtonyi, Mũwetei Yeova ũtaĩo na vinya.'),
('kam', 'PSA', 29, 2, 'Mũwetei Yeova ũtaĩo ũla waĩle syĩtwa yake; Mũthaithei Yeova na ũseo wa ũtheu.'),
('kam', 'PSA', 29, 3, 'Wasya wa Yeova wĩ ĩũlũ wa manzĩ: Ngai wa ũtaĩo nũtundumaa, O Yeova e ĩũlũ wa manzĩ maingĩ.'),
('kam', 'PSA', 29, 4, 'Wasya wa Yeova wĩ vinya; Wasya wa Yeova usũĩte ũnene.'),
('kam', 'PSA', 29, 5, 'Wasya wa Yeova ũtũlangaa mĩtĩ ya mĩkũũ; Ĩĩ, Yeova atũlangaa tũlungu mĩkũũ ĩla ya Levanoni.'),
('kam', 'PSA', 29, 6, 'Atumaa ĩtũva ta kasaũ; Iĩma sya Levanoni na Silioni itũva ta ĩswii ya mboo.'),
('kam', 'PSA', 29, 7, 'Wasya wa Yeova nĩwatũaa itw’ĩki sya mwaki.'),
('kam', 'PSA', 29, 8, 'Wasya wa Yeova nũthingithasya weũ; Yeova nũthingithasya weũ wa Katesi.'),
('kam', 'PSA', 29, 9, 'Wasya wa Yeova ũtumaa ndaatai isyaa, Naw’o ũtumaa mũtitũ wĩtĩkya matũ: Na ĩkalũnĩ yake o kĩla kĩndũ kĩneenaa, Ũtaĩo nĩ wake.'),
('kam', 'PSA', 29, 10, 'Yeova ekalile e Mũsumbĩ ĩũlũ wa kĩla Kĩw’ũ kingĩ; Ĩĩ, Yeova ekalaa e Mũsumbĩ tene na tene.'),
('kam', 'PSA', 29, 11, 'Yeova akanenga andũ make vinya; Yeova akamaathima andũ make na mũuo.'),
('kam', 'PSA', 30, 1, 'Ngakũkatha, we Yeova; nĩkwĩthĩwa nĩwambũkĩlilye ĩũlũ, Na ndwaamanenga amaitha makwa ũthei matane ĩũlũ wakwa.'),
('kam', 'PSA', 30, 2, 'Ame Yeova Ngai wakwa, Nĩnakwĩkaĩlile, na wambosya.'),
('kam', 'PSA', 30, 3, 'We Yeova, nĩwaumisye thayũ wakwa Seoli: Nũmbĩkalĩtye nĩ thayũ, ndikatheee yĩla ĩimanĩ.'),
('kam', 'PSA', 30, 4, 'Inai mũkĩkumya Yeova, inyw’ĩ atheu make, Tũngĩai mũvea syĩtwa yake ĩtheu ya ũlilikan’yo.'),
('kam', 'PSA', 30, 5, 'Nĩkwĩthĩwa ũthatu wake no wa kavinda kanini; Ũseo wake nĩwĩkalaa ĩvinda yonthe ya thayũ wa mũndũ: Kĩĩo kĩthĩawa ũtukũ, Ĩndĩ kĩoko kwĩthĩawa ũtanu.'),
('kam', 'PSA', 30, 6, 'Nakwa, yĩla naingĩvĩwe nasya, Ndikathingithĩka o na ĩndĩĩ.'),
('kam', 'PSA', 30, 7, 'Naku, Yeova, kwondũ wa ũseo waku nũtumĩte kĩĩma kyakwa kĩthĩwa na vinya: Wavithie ũthyũ waku; nakwa naũũya.'),
('kam', 'PSA', 30, 8, 'Nakwĩkaĩlile, we Yeova; Na kwa Yeova nĩneesũvanie:'),
('kam', 'PSA', 30, 9, 'Nthakame yakwa ĩkauna na kĩ, natheea yĩla ĩimanĩ? Kĩtoo kĩkakũtaĩa? Kĩkatavan’ya w’o waku?'),
('kam', 'PSA', 30, 10, 'Ĩw’a, ame Yeova, mbĩw’ĩa tei: Yeova, ĩthĩwa mũtethya wakwa.'),
('kam', 'PSA', 30, 11, 'Nũalyũlĩte kũmeta kwakwa kwĩthĩwe kũsũnga; Nũmbotooketye makunia makwa, na kũmbotoa ũtanu;'),
('kam', 'PSA', 30, 12, 'Nĩ kana ũnene wakwa ũkwinĩe, vate kũkilya. Ame Yeova Ngai wakwa, ngakũtũngĩa mũvea kũvika tene na tene.'),
('kam', 'PSA', 31, 1, 'We Yeova, nĩngwĩvitha nthĩnĩ waku; Ndũkaandeke nĩsonokw’e o na ĩndĩĩ: Mbonokya kwondũ wa ũlũngalu waku.'),
('kam', 'PSA', 31, 2, 'Tea kũtũ kwaku ũmbĩw’e; mbonokya mĩtũkĩ: Ĩthĩwa kwakwa ĩvia yĩ vinya, Nyũmba ya ngome ya kũndangĩĩa.'),
('kam', 'PSA', 31, 3, 'Nĩkwĩthĩwa nue ĩvia yakwa na ngome yakwa; Kwondũ wa ũu nũndũ wa syĩtwa yaku ndongoeasya na nginyae mbee.'),
('kam', 'PSA', 31, 4, 'Mbumya kĩteinĩ kĩla mandeie na kĩmbithĩ; Nĩkwĩthĩwa nue ngome yakwa yĩ vinya.'),
('kam', 'PSA', 31, 5, 'Veva wakwa nĩngwia kw’okonĩ kwaku: Nũmbovoetye, we Yeova, nue Ngai wa w’o.'),
('kam', 'PSA', 31, 6, 'Nĩngũmena ala metĩkĩlaa maũndũ ma mana ma ũvũngũ; Ĩndĩ nyie nĩĩkĩĩe Yeova.'),
('kam', 'PSA', 31, 7, 'Ngatana na kwĩw’a mũyo ũseonĩ waku wĩ wendo; Nĩkwĩthĩwa nĩwoonie thĩna wakwa: Nĩwamanyie mathĩna ma ngoo yakwa;'),
('kam', 'PSA', 31, 8, 'Na ndwaanengane kw’okonĩ kwa ũla mũmaitha; Nĩwaũngamisye maũũ makwa vandũ vaamu mũno.'),
('kam', 'PSA', 31, 9, 'Mbĩw’ĩa tei, ame Yeova, nĩkwĩthĩwa nĩngũthĩna: Itho yakwa nĩyĩũseekea nĩ woo, ĩĩ, o na ngoo yakwa na mwĩĩ wakwa.'),
('kam', 'PSA', 31, 10, 'Nĩkwĩthĩwa thayũ wakwa nũkũminw’a nĩ woo, Na myaka yakwa nĩthelete na kũvevũũka: Vinya wakwa nũũnyiva nũndũ wa naĩ syakwa, Na mavĩndĩ makwa nĩmeũkũa.'),
('kam', 'PSA', 31, 11, 'Nũndũ wa nthũ syakwa syonthe nĩtw’ĩkĩte wa kũvũthw’a, Ĩĩ, atũi makwa membũthya mũno, Na nĩngũkĩwa nĩ anyanyae makwa: Ala mambonie nzĩanĩ nĩmangĩie.'),
('kam', 'PSA', 31, 12, 'Nĩnoolile ta mũndũ mũkw’ũ ũndũ ũlaa: Ndilyĩ ta mũio mũkw’ũ.'),
('kam', 'PSA', 31, 13, 'Nĩkwĩthĩwa nĩnĩw’ĩte mawilĩĩlo ma aingĩ, Ũtĩsyo ngalĩ syonthe: Makĩnzamĩa, Masũanĩa nzĩa ya ũmbũaa.'),
('kam', 'PSA', 31, 14, 'Ĩndĩ nĩnakũĩkĩĩe, we Yeova: Nĩnaisye, Nue Ngai wakwa.'),
('kam', 'PSA', 31, 15, 'Mavinda makwa me mokonĩ maku: Mbonokya mokonĩ ma amaitha makwa, na kwa ala manthĩnasya.'),
('kam', 'PSA', 31, 16, 'Ũthyũ waku ũmũtisĩae mũthũkũmi waku: Ndangĩĩa kwondũ wa ũseo waku wĩ wendo.'),
('kam', 'PSA', 31, 17, 'Ndũkaandeke nĩsonokw’e, ame Yeova; nũndũ nĩngwĩkaĩlĩte: Ala athũku masonoke, makilĩlye ku Seoli.'),
('kam', 'PSA', 31, 18, 'Ilomo ila ineenaa ũvũngũ syĩthĩwe itatonya kũneena, Ilomo ila ineenea alũngalu ndeto nyũmũ, Na ngathĩĩo na kĩvũthya.'),
('kam', 'PSA', 31, 19, 'Asi! Ũseo waku nĩ mũnene, Ũla waiĩe ala makũkĩaa, Ũla weekie kwondũ wa ala mevithaa nthĩnĩ waku, Ana ma andũ mene!'),
('kam', 'PSA', 31, 20, 'Ũkamavitha ũvithonĩ vala ũĩ kuma iteinĩ sya andũ: Ũkamasũvĩa kĩmbithĩnĩ ĩlwandanĩ kuma motetan’yonĩ ma nĩmĩ.'),
('kam', 'PSA', 31, 21, 'Yeova nataĩwe; Nĩkwĩthĩwa nũmbonetye ũseo wake wĩ wendo wa ũseng’ya nĩ ndũanĩ nũmu.'),
('kam', 'PSA', 31, 22, 'Ĩndĩ nyie, nĩnaisye na mĩtũkĩ, Nĩ mũvete kuma mbee wa metho maku: Ĩndĩ we nĩweewie wasya wa kwĩsũvana kwakwa, Yĩla nakwĩkaĩlile.'),
('kam', 'PSA', 31, 23, 'Mwendei Yeova, inyw’ĩ atheu make onthe: Yeova nũmasũvĩaa ala me na kĩthito, Na nũĩvaa mũno ũla wĩtũlasya.'),
('kam', 'PSA', 31, 24, 'Ĩthĩwai na vinya, na ngoo syenyu syĩthĩwe na ũnyiau, Inyw’onthe ala mwĩkwatasya Yeova.'),
('kam', 'PSA', 32, 1, 'Kũathimwa nĩ mũndũ ũla ũekewe ĩvĩtyo yake, Ũla naĩ yake ĩvw’ĩkĩtwe.'),
('kam', 'PSA', 32, 2, 'Kũathimwa nĩ mũndũ ũla Yeova ũtamũtalĩlaa ũthũku, Na vevanĩ wake vai ũĩ wa ũkengani.'),
('kam', 'PSA', 32, 3, 'Yĩla navindisye, mavĩndĩ makwa makũa Nũndũ wa kũluma kwakwa mũthenya w’onthe.'),
('kam', 'PSA', 32, 4, 'Nĩkwĩthĩwa mũthenya na ũtukũ kw’oko kwaku kwaĩ kũito ĩũlũ wakwa: Nĩnyiaũkĩte ngethĩwa ta mũnyao wa ĩvinda ya syũa.'),
('kam', 'PSA', 32, 5, 'Nĩnakũmanyĩthisye naĩ yakwa, O na ndyaavitha ũthũku wakwa: Naisye, Nĩngũmumbũlĩla Yeova mavĩtyo makwa; Naku wandekea ũthũku wa naĩ yakwa.'),
('kam', 'PSA', 32, 6, 'Kwondũ wa ũu kĩla mũndũ ũmũkĩaa Ngai nakũvoye ĩvindayĩla ũkwoneka: Vate ndĩi yĩla manzĩ maingĩ makavinga na kũng’oka maikamũvikĩa.'),
('kam', 'PSA', 32, 7, 'Nue wĩvitho wakwa; ũkanzũvĩa ndikalike thĩnanĩ; Ũkanthyũlũlũkya mbathi sya ũvonokyo.'),
('kam', 'PSA', 32, 8, 'Ngakũmanyĩsya na kũkwon’ya nzĩa ĩla wĩendelaa: Ngakũtaa itho yakwa yĩkũketeee.'),
('kam', 'PSA', 32, 9, 'Mũtikethĩwe ta mbalasi, kana ta nyũmbũ, ila ita na ũmanyi; Ila syĩkĩwe itang’a sya kanyw’a na mĩkwa nĩ kana isiĩĩwe, Nĩ kana itikakũthengeee.'),
('kam', 'PSA', 32, 10, 'Mũndũ mwathe akeethĩwa na mawoo maingĩ; Ĩndĩ ũla ũmũĩkĩĩe Yeova, akathyũlũlũkwa nĩ ũseo wĩ wendo ngalĩ syonthe.'),
('kam', 'PSA', 32, 11, 'Tanai nthĩnĩ wa Yeova, na kwĩw’a mũyo, inyw’ĩ alũngalu; Na ũkĩlyai mawasya ma ũtanu, inyw’onthe ala mwĩ na ngoo ndũngalu.'),
('kam', 'PSA', 33, 1, 'Tanai nthĩnĩ wa Yeova, inyw’ĩ alũngalu: Kũtaĩa nĩ kwaĩle ala alũngalu.'),
('kam', 'PSA', 33, 2, 'Mũtũngĩei Yeova mũvea na mbeve: Mwinĩei mũkĩmũkumya na kĩnanda kĩ ndii ĩkũmi.'),
('kam', 'PSA', 33, 3, 'Mwinĩei wathi weũ; Ingai na ũtũĩka na wasya mũnene.'),
('kam', 'PSA', 33, 4, 'Nĩkwĩthĩwa ndeto ya Yeova nĩ ya w’o; Na wĩa wake w’onthe ũtethaw’a na kĩthito.'),
('kam', 'PSA', 33, 5, 'Nake nĩwendete ũlũngalu na ũsili wa katĩ: Nthĩ yusũĩte ũseo wĩ wendo wa Yeova.'),
('kam', 'PSA', 33, 6, 'Matu nĩmoombiwe na ndeto ya Yeova, Na nguthu syonthe syamo nĩsyoombĩwe nĩ mĩthũmũ ya kanyw’a wake.'),
('kam', 'PSA', 33, 7, 'Ombanasya kĩw’ũ kya ũkanga ta kĩvumbu: Ekĩaa manzĩ ma syũngũ makũmbĩnĩ.'),
('kam', 'PSA', 33, 8, 'Nthĩ yonthe nĩmũkĩe Yeova: Onthe ala matwĩe nthĩ mamũkĩe.'),
('kam', 'PSA', 33, 9, 'Nĩkwĩthĩwa aneenie, na ũu weekwa; Eeaĩe, na ũu walũma.'),
('kam', 'PSA', 33, 10, 'Yeova nũtw’ĩkĩthasya ũtao wa i mbaĩ wa mana; Nũtumaa mosũanĩo ma ngo sya andũ methĩwa mate na ũtonyi.'),
('kam', 'PSA', 33, 11, 'Ũtao wa Yeova nĩwĩkalaa kũvika tene na tene, Mosũanĩo ma ngoo yake kũvikĩa nzyawa syonthe.'),
('kam', 'PSA', 33, 12, 'Kũathimwa nĩ mbaĩ ĩla Ngai wayo nĩ Yeova, Andũ ala manyuvĩtwe nĩwe matw’ĩke ũtiĩwa wake.'),
('kam', 'PSA', 33, 13, 'Yeova nũsyaĩĩasya e Ĩtunĩ; Nĩwonaa ana onthe ma andũ;'),
('kam', 'PSA', 33, 14, 'E vala ũtwĩe nũsyaĩĩasya Onthe ala matwĩe nthĩ,'),
('kam', 'PSA', 33, 15, 'We ũla ũmbaa ngoo sya onthe, Ũla ũsũanĩaa mawĩa moo onthe.'),
('kam', 'PSA', 33, 16, 'Vai mũsumbĩ ũtangĩĩwa nũndũ wa nguthu kwĩthĩwa yĩ nyingĩ: Ngũmbaũ ndĩvonokw’a nũndũ wa vinya mwingĩ.'),
('kam', 'PSA', 33, 17, 'Mbalasi nĩ kĩndũ kya mana kya ũvonokya mũndũ; O na ndĩtonya ũtangĩĩa mũndũ ũndũ wa vinya wayo.'),
('kam', 'PSA', 33, 18, 'Sisya, itho ya Yeova yĩketeeaa ala mamũkĩaa, Ala mekwatasya ũseo wake wĩ wendo;'),
('kam', 'PSA', 33, 19, 'Kũvonokya thayũ woo kĩkw’ũnĩ, Na kũmekalya me thayũ kwĩ yũa.'),
('kam', 'PSA', 33, 20, 'Ngoo sitũ syeteelete Yeova: Nĩwe mũtethya waitũ na ngao yaitũ.'),
('kam', 'PSA', 33, 21, 'Nĩkwĩthĩwa ngoo sitũ ikatanĩaa nthĩnĩ wake, Nũndũ nĩtũĩkĩĩe syĩtwa yake ĩtheu.'),
('kam', 'PSA', 33, 22, 'Ũseo waku wĩ wendo wĩthĩwe ĩũlũ waitũ, ame Yeova, Kwĩanana na ũndũ tũkwĩkwatĩtye.'),
('kam', 'PSA', 34, 1, 'Ngamũtaĩaa Yeova mavinda onthe: Ndaĩa syake ikeethĩwa kanyw’anĩ wakwa mavinda onthe.'),
('kam', 'PSA', 34, 2, 'Thayũ wakwa ũkekathĩĩaa nthĩnĩ wa Yeova: Ala auu makeew’a ũu, na makatana.'),
('kam', 'PSA', 34, 3, 'Tũmũnenevyei Yeova vamwe, Na tũtũlyei syĩtwa yake vamwe.'),
('kam', 'PSA', 34, 4, 'Nĩnamũmanthie Yeova, na anzũngĩa, Na ambonokya kuma w’ĩanĩ wakwa w’onthe.'),
('kam', 'PSA', 34, 5, 'Mamũsyaisye, na matisatisa; Na mothyũ moo maikasonokw’a o na ĩndĩĩ.'),
('kam', 'PSA', 34, 6, 'Mũndũ ũũ ngya akaya, na Yeova amwĩw’a, Na amũtangĩĩa kuma mathĩnanĩ make onthe.'),
('kam', 'PSA', 34, 7, 'Mũlaĩka wa Yeova nũmathyũlũlũkaa ngalĩ syonthe ala mamũkĩaa, Na kũmavonokya.'),
('kam', 'PSA', 34, 8, 'Samai mũsisye kana Yeova nĩ mũseo: Kũathimwa nĩ mũndũ ũla wĩvithaa nthĩnĩ wake.'),
('kam', 'PSA', 34, 9, 'Kĩai Yeova, inyw’ĩ atheu make; Nĩkwĩthĩwa ala mamũkĩaa maikaĩwa nĩ kĩndũ.'),
('kam', 'PSA', 34, 10, 'Mĩnyambũ ya mũika nĩyaĩawa nĩ kĩndũ, na kwĩw’aa nzaa; Ĩndĩ ala mamũmanthaa Yeova matikaĩwa nĩ kĩndũ kĩseo o na kĩva.'),
('kam', 'PSA', 34, 11, 'Ũkai, inyw’ĩ syana, mbĩthukĩĩsyai: Ngamũmanyĩsya kũmũkĩa Yeova.'),
('kam', 'PSA', 34, 12, 'Nĩ mũndũ wĩva wendaa kwĩthĩwa na thayũ, Na wendaa kwĩthĩwa na mĩthenya mingĩ, nĩ kana one ũseo?'),
('kam', 'PSA', 34, 13, 'Sũvĩa ũĩmĩ waku ndũkaneene ũthũku, O na ĩlomo syaku itikaneene na ũĩ wa ũkengani.'),
('kam', 'PSA', 34, 14, 'Ĩvathane na ũthũku, na ũkĩka ũseo; Mantha mũuo, na ũyũatĩĩa.'),
('kam', 'PSA', 34, 15, 'Metho ma Yeova melekele alũngalu, Na matũ make nũteete ew’e kĩĩo kyoo.'),
('kam', 'PSA', 34, 16, 'Ũthyũ wa Yeova wĩ ĩũlũ wa ala mekaa ũthũku, Kũlilikanwa kwoo kũthele kũũ nthĩ.'),
('kam', 'PSA', 34, 17, 'Ala alũngalu makayie, na Yeova amew’a, Na amavonokya mathĩnanĩ moo onthe.'),
('kam', 'PSA', 34, 18, 'Yeova e vakuvĩ na ala matũlĩkĩte ngoo, Na nũtangĩĩaa ala mekwĩlila vevanĩ.'),
('kam', 'PSA', 34, 19, 'Mathĩna nĩ maingĩ ala mũndũ mũlũngalu wĩ namo; Ĩndĩ Yeova nũmũvonokasya kwamo onthe.'),
('kam', 'PSA', 34, 20, 'Nũsũvĩaa mavĩndĩ make onthe: Vai yĩmwe yamo ĩtũlĩku.'),
('kam', 'PSA', 34, 21, 'Ũthũku ũkooaa ala athũku; Na ala mamenaa alũngalu makasilĩlwa.'),
('kam', 'PSA', 34, 22, 'Yeova nũkwovosya thayũ wa athũkũmi make; Na vai ũmwe wa ala mevithaa nthĩnĩ wake ũkasilĩlwa.'),
('kam', 'PSA', 35, 1, 'Ame Yeova, kĩlan’ya na ala meũkĩlan’ya nakwa: Ũkita na ala meũkita nakwa.'),
('kam', 'PSA', 35, 2, 'Osa ngao na kakalo, Na ũngama ũndethye.'),
('kam', 'PSA', 35, 3, 'Umya ĩtumo nayo, na mavingĩe nzĩa ala meũngatĩĩa: Ĩa thayũ wakwa atĩĩ, Ninyie ũtangĩĩo waku.'),
('kam', 'PSA', 35, 4, 'Masonokw’e na kwanangĩwa ndaĩa ala mamanthaa thayũ wakwa: Matũngwe na ĩtina na kũthokoanwa ala manzũanĩĩaa ũthũku.'),
('kam', 'PSA', 35, 5, 'Nĩmethĩwe ta wewa mbee wa ũkũngi, Mũlaĩka wa Yeova akĩmalũngya.'),
('kam', 'PSA', 35, 6, 'Nzĩa yoo yĩthĩwe yĩ kĩvindu na ndendeu Na mũlaĩka wa Yeova akĩmaatĩĩa.'),
('kam', 'PSA', 35, 7, 'Nĩkwĩthĩwa mandeie na kĩtei kyoo ĩimanĩ vate kĩtumi; Vate kĩtumi nĩmenzĩe thayũ wakwa ĩima.'),
('kam', 'PSA', 35, 8, 'Wanangĩko ũmũkĩe atesĩ; Na kĩtei kyake kĩla wavithie kĩmũkwatye: Navalũke nthĩnĩ wakyo na kwanangĩka.'),
('kam', 'PSA', 35, 9, 'Na ngoo yakwa ĩkeethĩwa na ũtanu nthĩnĩ wa Yeova: Ĩkatana ũtangĩĩonĩ wake.'),
('kam', 'PSA', 35, 10, 'Mavĩndĩ makwa onthe makakũlya, Yeova, nũũ ũla ũilyĩ taku, Ũla ũtangĩĩa ngya kuma kwa ũla wĩ vinya kwĩ we, Ĩĩ, kũtangĩĩa ngya na ũla mũthĩni kuma kwa ũla ũmũvutaa?'),
('kam', 'PSA', 35, 11, 'Ngũsĩ sya ũvũngũ syookĩla; Na kũngũlya maũndũ ndamesĩ.'),
('kam', 'PSA', 35, 12, 'Mandĩvaa ũthũku vandũ va ũseo, Kũvika ngoo yakwa yamaka.'),
('kam', 'PSA', 35, 13, 'Ĩndĩ ngalĩ ĩ yakwa, yĩla maĩ awau, ngũa syakwa syaĩ sya makunia: Nĩnathĩnisye thayũ wakwa ngĩtĩĩa kũya; Na mboya yakwa yanzyokea kĩthũinĩ kyakwa.'),
('kam', 'PSA', 35, 14, 'Nĩneekie o ta waĩ mũnyanyawa kana mwana‐a‐ia: Nenamĩĩa nthĩ na kũmaka, ta ũla ũnũkũĩĩa inyia wake.'),
('kam', 'PSA', 35, 15, 'Ĩndĩ yĩla ngũthĩna maitana, na kũmbana vamwe: Mambũmbanĩa asu ameni, nakwa ndyaamanya; Mandembũanga, na matyaaeka:'),
('kam', 'PSA', 35, 16, 'Ta avũthya ala makaakaanĩasya mbokanĩ, Mambevetanĩasya maeo moo.'),
('kam', 'PSA', 35, 17, 'Mwĩaĩi, nĩ ĩvinda yĩana ata ũkĩsyaĩĩsya? Tangĩĩa thayũ wakwa mawananginĩ moo, No ũmwe ũtangĩĩe kwa ĩla mĩnyambũ.'),
('kam', 'PSA', 35, 18, 'Ngakũtũngĩa mũvea ũmbanonĩ ũla mũnene: Ngakũtaĩa katĩ wa andũ aingĩ.'),
('kam', 'PSA', 35, 19, 'Asu amaitha makwa matikandanĩe ũvũngũ; O na ala meũmena vate kĩtumi matikavenanĩsye na metho.'),
('kam', 'PSA', 35, 20, 'Nĩkwĩthĩwa matiũneena mũuo; Ĩndĩ memasũanĩĩa andũ ala avoo ma ĩ nthĩ ndeto sya ũkengani.'),
('kam', 'PSA', 35, 21, 'Ĩĩ, mambathamĩsye makanyw’a moo mũno; Maisye, Aa! Aa! Metho maitũ nĩmawonete.'),
('kam', 'PSA', 35, 22, 'Nue ũwonete, ame Yeova; ndũkakilye: Ame Mwĩaĩi, ndũkethĩwe wĩ kũasa nakwa.'),
('kam', 'PSA', 35, 23, 'Ũkĩla, na amũka ũtw’e sila ũla ũmbaĩle, O ũndũ wakwa, Ngai wakwa na Mwĩaĩi wakwa.'),
('kam', 'PSA', 35, 24, 'Nzilĩla, ame Yeova Ngai wakwa, kwĩanana na ũlũngalu waku; Maikatanw’e ninyie.'),
('kam', 'PSA', 35, 25, 'Matikasye ngoonĩ syoo, Aa! Ũu nĩw’o twendete: Matikasye, Nĩwamũmelya.'),
('kam', 'PSA', 35, 26, 'Masonokw’e na kũthokoanw’a vamwe asu ala matanĩaa thĩna wakwa: Mavw’ĩkwe nthoni na kwanangĩwa ndaĩa asu mekwĩnenevya ĩũlũ wakwa.'),
('kam', 'PSA', 35, 27, 'Mokĩlye mawasya na ũtanu, na kwĩw’a mũyo, ala mendeeaw’a nĩ ũlũngalu wakwa: Ĩĩ, maneenae mavinda onthe, Yeova anenevw’e, Ũla wendeeaw’a nĩ kwingĩvĩwa kwa mũthũkũmi wake.'),
('kam', 'PSA', 35, 28, 'Na ũĩmĩ wakwa ũkaneenaa ũvoo wa ũlũngalu waku Na ndaĩa yaku mũthenya w’onthe.'),
('kam', 'PSA', 36, 1, 'Ĩvĩtyo ya ũla mũthũku yĩmbĩa ngoonĩ yakwa, Kũi kũmũkĩa Ngai mbee wa metho make.'),
('kam', 'PSA', 36, 2, 'Nĩkwĩthĩwa methonĩ make nĩwĩyendeeasya mwene, Atĩ ũthũku wake ndũkamanyĩke na kũmenwa.'),
('kam', 'PSA', 36, 3, 'Ndeto sya kanyw’a wake nĩ sya ũthũku na ũkengani; Nũekete kwĩthĩwa na ũĩ o na kwĩka ũseo.'),
('kam', 'PSA', 36, 4, 'Nũsũanĩaa ũthũku e ũkomonĩ wake; Eleketye nzĩanĩ ĩte nzeo; Naw’o ũthũku ndamenaa.'),
('kam', 'PSA', 36, 5, 'Ũseo waku wĩ wendo, we Yeova, wĩ matunĩ; Kĩthito kyaku kĩvikĩte o na matunĩ.'),
('kam', 'PSA', 36, 6, 'Ũlũngalu waku ũilyĩ ta iĩma sya Ngai; Mosilĩlo maku nĩ kyũngũ kĩliku: Naku Yeova, wĩkalasya mũndũ thayũ o na nyamũ.'),
('kam', 'PSA', 36, 7, 'Ũseo waku wĩ wendo ko wĩ vata mũnene, ame Ngai! Na syana sya andũ syĩvithaa ungu wa muunyĩ wa nthwau syaku.'),
('kam', 'PSA', 36, 8, 'Makavũnw’a vyũ nĩ ũnou wa nyũmba yaku; Na ũkatuma manyw’a ma ũsĩ wa motanu maku.'),
('kam', 'PSA', 36, 9, 'Nũndũ nue wĩ na mbuluti ya thayũ: Kyeninĩ kyaku nĩvo tũkona kyeni'),
('kam', 'PSA', 36, 10, 'Endeea kwonan’ya ũseo waku wĩ wendo kwa ala meũkũmanya, Na ũlũngalu waku kwa ala alũngalu ngoonĩ.'),
('kam', 'PSA', 36, 11, 'Kũũ kwa ala mekathĩĩa kũikambũkĩe, O na kw’oko kwa mũthũku kũikandũngye.'),
('kam', 'PSA', 36, 12, 'Vu nĩvo eki ma ũthũku mavalũkĩte: Nĩmakimanĩtw’e na nthĩ, na matikatonya kũkĩla.'),
('kam', 'PSA', 37, 1, 'Ndũkenyamasye nũndũ wa ala mekaa naĩ, O na ndũkamew’ĩe kĩwĩu ala mekaa mawĩa mate malũngalu.'),
('kam', 'PSA', 37, 2, 'Nĩkwĩthĩwa mĩtũkĩ makatilwa ta nyeki, Na makooma o ta nyũnyi ila nziũ sya mũũndanĩ.'),
('kam', 'PSA', 37, 3, 'Mũĩkĩĩe Yeova, na ũkĩka ũseo; Tũaa ĩ nthĩ, na ũiĩsaa kĩthito kyake.'),
('kam', 'PSA', 37, 4, 'Ĩtan’ye nthĩnĩ wa Yeova; Nake akakũnenga kila ũvoyete na ngoo yaku.'),
('kam', 'PSA', 37, 5, 'Mwiĩe Yeova nzĩa yaku; Mũĩkĩĩe we, nake akeeka.'),
('kam', 'PSA', 37, 6, 'Nake akaumĩlya ũlũngalu waku o ta kyeni, Na ũsili waku ta kyeni kya mũthenya katĩ.'),
('kam', 'PSA', 37, 7, 'Thũmũa nthĩnĩ wa Yeova, na mweteele na wũmĩĩsyo: Ndũkenyamasye ũndũ wa ũla ũunĩkaa nzĩanĩ yake, Nũndũ wa ũla ũtumaa mosũanĩo mathũku mekĩka.'),
('kam', 'PSA', 37, 8, 'Eka ũthatu, na tia ũthilĩkũ: Ndũkenyamasye, nĩkw’o kũtumaa naĩ yĩkwa.'),
('kam', 'PSA', 37, 9, 'Nĩkwĩthĩwa eki ma naĩ makavetwa; Ĩndĩ ala mamweteelaa Yeova, asu makatiĩwa nthĩ.'),
('kam', 'PSA', 37, 10, 'Vatiele ĩvinda ĩnini, na mũthũku ndakethĩwa: Ĩĩ, ũkaketeea mũno vandũ vake, na ndakethĩwa.'),
('kam', 'PSA', 37, 11, 'Ĩndĩ ala auu makatiĩwa nthĩ, Na makeetan’ya mũuonĩ mwingĩ.'),
('kam', 'PSA', 37, 12, 'Ũla mũthũku amũsũanĩĩaa mũlũngalu ũthũku, Na kũmũvevetanĩsya maeo.'),
('kam', 'PSA', 37, 13, 'Nake Mwĩaĩi akamũtheka; Nĩkwĩthĩwa eona kana mũthenya wake nĩwũkĩte.'),
('kam', 'PSA', 37, 14, 'Athũku makũĩte ũvyũ, na nĩmakootete mata moo, Mavalũkye nthĩ ngya na athĩni, Mamoae ala alũngalu me nzĩanĩ.'),
('kam', 'PSA', 37, 15, 'Mbyũ syoo ikatonya ngoo syoo ene, Na mata moo makatũlwa.'),
('kam', 'PSA', 37, 16, 'Nĩ kavaa kĩndũ kĩnini kya mũndũ mũlũngalu. Kwĩ ũthwii mwingĩ wa andũ aingĩ athũku.'),
('kam', 'PSA', 37, 17, 'Nĩkwĩthĩwa moko ma ala athũku makatũlwa; Ĩndĩ ala alũngalu Yeova nũmatw’ĩĩkaa.'),
('kam', 'PSA', 37, 18, 'Yeova nĩwe wĩsĩ mĩthenya ya ala eanĩu; Na ũtiĩwa woo ũkeethĩwa wa tene na tene.'),
('kam', 'PSA', 37, 19, 'Maikasonoka ĩvinda ya ũthũku; Na mĩthenya ya yũa makeanĩaw’a.'),
('kam', 'PSA', 37, 20, 'Ĩndĩ ala athũku makaa, Na amaitha ma Yeova makeethĩwa ta ũnou wa tũtena twa malondu: Makathela; makathela o ta syũki.'),
('kam', 'PSA', 37, 21, 'Ũla mũthũku nũkovaa, na ndatũngaa; Ĩndĩ mũlũngalu ew’aa ĩnee, na ainengane.'),
('kam', 'PSA', 37, 22, 'Nĩkwĩthĩwa ala maathimĩtwe nĩwe makatiĩwa nthĩ; Na ala maumanĩwe nĩwe makavetwa.'),
('kam', 'PSA', 37, 23, 'Mĩendele ya mũndũ nĩlũlũmĩlw’e nĩ Yeova; Nake atanaa nzĩanĩ yake.'),
('kam', 'PSA', 37, 24, 'O na avalũka, ndakavika nthĩ vyu; Nĩkwĩthĩwa Yeova nĩwe ũnũũmũkwata na kw’oko.'),
('kam', 'PSA', 37, 25, 'Naĩ mũnini, na yu nĩ mũkũu; Ĩndĩ ndyaaona mũlũngalu atiĩtwe, Kana ũsyao wake ũkĩvoya lĩu.'),
('kam', 'PSA', 37, 26, 'Mũthenya w’onthe nĩwĩw’aa ĩnee, na kũkovethya; Na ũsyao wake nũathimawa.'),
('kam', 'PSA', 37, 27, 'Ĩvathane na ũthũku, nokĩka ũseo; Na ũkĩkala tene na tene.'),
('kam', 'PSA', 37, 28, 'Nĩkwĩthĩwa Yeova nũwendete sila wa katĩ, Na ndamatiaa atheu make; Nĩmasũvĩawa kũvika tene na tene: Ĩndĩ ũsyao wa ala athũku ũkavetwa vyũ.'),
('kam', 'PSA', 37, 29, 'Ala alũngalu makatiĩwa nthĩ, Na makatũa vo kũvika tene na tene.'),
('kam', 'PSA', 37, 30, 'Kanyw’a wa mũlũngalu ũneenaa ũndũ wa ũĩ, Na ũĩmĩ wake ũneenaa ũndũ wa sila wa katĩ.'),
('kam', 'PSA', 37, 31, 'Mwĩao wa Ngai wake wĩ ngoonĩ yake; Matambya make maikatendelũka nongi.'),
('kam', 'PSA', 37, 32, 'Ũla mũthũku nũsyĩmaa ũla mũlũngalu, Na amanthaa kũmũaa.'),
('kam', 'PSA', 37, 33, 'Yeova ndakamũtia kw’okonĩ kwake, Kana kũmũtw’a kwĩthĩwa mũvĩtan’ya yĩla wĩsilĩlwa.'),
('kam', 'PSA', 37, 34, 'Mweteele Yeova, na kwata nzĩa yake, Na akakũnenevya ũtiĩwe nthĩ: Yĩla athũku makavetwa, naku ũkoona ũu.'),
('kam', 'PSA', 37, 35, 'Nĩnonete mũthũku e na ũtonyi mwingĩ, Akĩnyasya mwene ta mũtĩ mwĩũ ũmeete mũthanganĩ wa nthĩ yaw’o.'),
('kam', 'PSA', 37, 36, 'Ĩndĩ kwavĩta mũndũ, na, sisya, nde vo: Ĩĩ, namũmantha, ĩndĩ ndanoneka.'),
('kam', 'PSA', 37, 37, 'Sisya nesa mũndũ mwĩanĩu, na keteea mũndũ mũlũngalu; Nĩkwĩthĩwa mũminũkĩlyo wa mũndũ ũsu ũkeethĩwa mũuo.'),
('kam', 'PSA', 37, 38, 'Ĩndĩ avĩtan’ya, makaanangwa vamwe: Mũminũkĩlyo wa athũku makavetwa vyũ.'),
('kam', 'PSA', 37, 39, 'Ĩndĩ ũtangĩĩo wa ala alũngalu nĩ wa Yeova: Nake nĩ ngome yoo yĩ vinya ĩvinda ya thĩna.'),
('kam', 'PSA', 37, 40, 'Yeova nũmatethasya, na kũmavonokya: Nũmavonokasya kwa athũku, na kũmatangĩĩa, Nũndũ mevithĩte nthĩnĩ wake.'),
('kam', 'PSA', 38, 1, 'Ame Yeova, ndũkangan’ye ũthilĩkunĩ waku; O na kũngũna kũtiikanĩ kwaku kũnene.'),
('kam', 'PSA', 38, 2, 'Nĩkwĩthĩwa mĩsyĩ yaku nĩngathangĩte mũno, Na kw’oko kwaku kũmbinyĩĩe ki.'),
('kam', 'PSA', 38, 3, 'Mwĩĩ wakwa ndwĩ na vandũ vaseo nũndũ wa ũthilĩku waku; O na mavĩndĩ makwa mati na mũuo nũndũ wa naĩ yakwa.'),
('kam', 'PSA', 38, 4, 'Nĩkwĩthĩwa mothũku makwa mang’okele mũtwenĩ wakwa: O ta mũio mũito nĩngũemwa nĩ ũito wamo.'),
('kam', 'PSA', 38, 5, 'Mawũkite makwa nĩmeũnyunga na nĩ mou, Nũndũ wa ũtumanu wakwa.'),
('kam', 'PSA', 38, 6, 'Nĩngwalw’a na kũkungulala mũno, Nĩngũthi ngĩmeta mũthenya w’onthe.'),
('kam', 'PSA', 38, 7, 'Nĩkwĩthĩwa kĩnyunyu kyakwa nĩkyusũĩte ĩvyũvĩ; Na mwĩĩ wakwa ndwĩ na vandũ vamwe vaseo.'),
('kam', 'PSA', 38, 8, 'Nĩngũnyala na kũuauĩka mũno: Nĩlumĩte kwondũ wa kũlea kũusya kwa ngoo yakwa.'),
('kam', 'PSA', 38, 9, 'Mwĩaĩi, kwenda kwakwa kw’onthe kwĩ mbee waku; Na kũluma kwakwa ndũvithĩtwe.'),
('kam', 'PSA', 38, 10, 'Ngoo yakwa nĩtumaa mũno, vinya wakwa nĩ mũnyivu: O na kyeni kya metho makwa, nakyo nĩ kĩthelu.'),
('kam', 'PSA', 38, 11, 'Endwa makwa na anyanyawa maũngamĩte mevathanĩte na ũthĩn’yo wakwa; Namo andũ ma nyũmba yakwa maũngamĩte kũasa nakwa.'),
('kam', 'PSA', 38, 12, 'Asu nao ala masyĩmaa thayũ wakwa mambiĩaa itei; Na ala mamanthaa kũmbĩka naĩ maneenaa maũndũ mathe, Na masũanĩaa mokengani mũthenya w’onthe.'),
('kam', 'PSA', 38, 13, 'Ĩndĩ nyie, ta mũndũ ũte matũ, ndikwĩw’a; Na nĩilyĩ ta mũndũ ũtaneenaa ũla ũtathamũkan’ya kanyw’a wake.'),
('kam', 'PSA', 38, 14, 'Iĩ, nĩilyĩ ta mũndũ ũtew’aa, Na ũla kanyw’anĩ wake vai mokan’yo.'),
('kam', 'PSA', 38, 15, 'Nĩkwĩthĩwa we, Yeova, nue nĩkwatasya: Ũkasũngĩa, ame Mwĩaĩi Ngai wakwa.'),
('kam', 'PSA', 38, 16, 'Nĩkwĩthĩwa nĩnaisye, Matikese kũndanĩa: Yĩla kũũ kwakwa kwĩtendelũka, menenevya ĩũlũ wakwa.'),
('kam', 'PSA', 38, 17, 'Nĩkwĩthĩwa ngilye kũvalũka, Na woo wakwa wĩ mbee wakwa mavinda onthe.'),
('kam', 'PSA', 38, 18, 'Nĩkwĩthĩwa ngaumbũla ũthũku wakwa; Ngeew’a woo nũndũ wa naĩ yakwa.'),
('kam', 'PSA', 38, 19, 'Ĩndĩ amaitha makwa me na ũthangaau, na me na vinya; Na ala mamenaa vate kĩtumi nĩmaingĩvie.'),
('kam', 'PSA', 38, 20, 'Namo ala maĩvaa ũthũku kwa ũseo Nĩ nthũ syakwa, nũndũ nyie nĩngũatĩĩa ũndũ ũla ũseo.'),
('kam', 'PSA', 38, 21, 'Ndũkandie, Yeova: Ame Ngai wakwa, ndũkethĩwe kũasa nakwa.'),
('kam', 'PSA', 38, 22, 'Ĩkalaate ũndethye, Ame Mwĩaĩi, ũtangĩĩo wakwa.'),
('kam', 'PSA', 39, 1, 'Nĩnaisye, Nĩngũsũvĩa mĩendele yakwa, Nĩ kana ndikavĩtye na ũĩmĩ wakwa: Ngasũvĩa kanyw’a wakwa ta kwova na mũkwa, Ĩvinda yĩla mũthũku wĩ mbee wakwa.'),
('kam', 'PSA', 39, 2, 'Neethĩwa ndeũneena, nĩnavindisye ki, o na ndyaaneena ũndũ ũseo; Na woo wakwa wookĩla.'),
('kam', 'PSA', 39, 3, 'Ngoo yakwa yavyũvĩa nthĩnĩ wakwa; O yĩla nasũanĩaa mwaki wakana; Na ĩndĩ naneena na ũĩmĩ wakwa:'),
('kam', 'PSA', 39, 4, 'Yeova, manyĩthya mũminũkĩlyo wakwa, Na ũtalo wa mĩthenya yakwa, ũndũ yĩana; Nĩmanye ũndũ mbinyĩte.'),
('kam', 'PSA', 39, 5, 'Sisya, mĩthenya yakwa ũmĩtw’ĩkĩthĩtye ta kũthima kwa kĩtaa kya kw’oko; Na ũasa wa thayũ wakwa ti kĩndũ mbee waku: Vate ndĩi kĩla mũndũ o na akeyaĩlya ata nĩ kĩndũ kya mana.'),
('kam', 'PSA', 39, 6, 'Vate ndĩi kĩla mũndũ aendaa o ta kyuu; Vate ndĩi nĩmekwĩthĩn’ya mana: Eyũmbanĩasya ũthwii, na ndesĩ ũla ũkotũngĩanĩa.'),
('kam', 'PSA', 39, 7, 'Na yu, Mwĩaĩi, nĩeteela kyaũ? Wĩkwatyo wakwa wĩ nthĩnĩ waku.'),
('kam', 'PSA', 39, 8, 'Mbonokya mavĩtyonĩ makwa onthe: Ndũkandw’ĩkĩthye kĩvũthya kya ala atumanu.'),
('kam', 'PSA', 39, 9, 'Nĩnavindisye, ndyaathamya kanyw’a wakwa; Nũndũ nue weekie ũu.'),
('kam', 'PSA', 39, 10, 'Mbathũkĩsya ĩkũna yaku: Nĩngũminwa nĩ ĩkũna ya kw’oko kwaku.'),
('kam', 'PSA', 39, 11, 'Yĩla ũũkan’ya mũndũ alũngale ũndũ wa ũthũku wake, Nũtumaa ũseo wake ũminwa ta ũĩtwe nĩ lungulu: Vate ndĩi kĩla mũndũ no kĩndũ kya mana.'),
('kam', 'PSA', 39, 12, 'Ĩw’a mboya yakwa, ame Yeova, na tea kũtũ wĩw’e ũkayo wakwa; Ndũkavindĩĩsye woona methoi makwa: Nĩkwĩthĩwa kwaku nyie nĩ mũeni, Mwĩkali wa ũeninĩ, o tondũ aaĩthe makwa onthe mailyĩ.'),
('kam', 'PSA', 39, 13, 'Ndeka, nĩ kana nĩtũngĩwe vinya ĩngĩ, Mbee wa ndanamba kũthi, na kũlea kwĩthĩwa ĩngĩ.'),
('kam', 'PSA', 40, 1, 'Nĩnamweteelile Yeova na ũmĩĩsyo; Nake eethukĩĩsya, na eew’a ũkayo wakwa.'),
('kam', 'PSA', 40, 2, 'Nĩwanumisye ĩimanĩ ĩthũku mũno mbee, anumya ndakanĩ ya yũmba; Na akinyĩthya maũũ makwa ĩvianĩ, na alũlũmĩlya mĩendele yakwa.'),
('kam', 'PSA', 40, 3, 'Nake nĩwĩkĩĩte wathi weũ kanyw’anĩ wakwa, nĩw’o ndaĩa ya Ngai waitũ: Aingĩ makoona ũu, na makakĩa, Na makamũĩkĩĩa Yeova.'),
('kam', 'PSA', 40, 4, 'Kũathimwa nĩ mũndũ ũla ũmũtusaa Yeova wĩkwatyo wake, O na ndataĩaa ekathĩĩi, kana ala mathũkaa kũatĩĩa movũngũ.'),
('kam', 'PSA', 40, 5, 'Nĩ maingĩ mũno mawĩa maku ma ũseng’ya ala ũtethetye, we Yeova Ngai wakwa, Na mosũanĩo maku ala melekele ithyĩ: Maitonya kwiwa maatĩanĩe mbee waku; Ethĩwa ngamatavan’ya na kũmaweta, Nĩ maingĩ ũndũ matatonya kũtalĩka.'),
('kam', 'PSA', 40, 6, 'Ndwĩw’aa mũyo nĩ nthembo na syĩndũ ila syumaw’a; Matũ makwa nĩwamakunũie: Nthembo ya kũvĩvw’a na nthembo ya naĩ ndũsyendete.'),
('kam', 'PSA', 40, 7, 'Nĩvo naisye, Sisya, nĩnooka; Ĩvukunĩ ĩkũnze nĩkũandĩkĩtwe ũndũ wakwa atĩĩ:'),
('kam', 'PSA', 40, 8, 'Nĩngũtana kwĩka kwenda kwaku, we Ngai wakwa; Ĩĩ, mwĩao waku wĩ ngoonĩ yakwa.'),
('kam', 'PSA', 40, 9, 'Nĩnatavanisye maũvoo ma ũtanu ma ũlũngalu ũmbanonĩ ũla mũnene; Sisya, ndikasiĩĩa ilomo syakwa, Ame Yeova, nue wĩsĩ.'),
('kam', 'PSA', 40, 10, 'Ndinavitha ũlũngalu waku nthĩnĩ wa ngoo yakwa; Nĩnaneenie ũndũ wa kĩthito kyaku na ũtangĩĩo waku; Ũseo waku wĩ wendo na w’o waku ndinavitha ũmbanonĩ ũla mũnene.'),
('kam', 'PSA', 40, 11, 'Naku Yeova, ndũkambate matei maku mololo; Ũseo waku wĩ wendo na w’o waku nimbĩkalye mavinda onthe.'),
('kam', 'PSA', 40, 12, 'Mothũku matatalĩka nĩmanthyũlũlũkĩte; Naĩ syakwa nĩsyangwata, na kwondũ wa ũu nditonya kũng’elela ĩũlũ; Nĩ nyingĩ kũvĩtũka nzw’ĩĩ sya mũtwe wakwa; Na ngoo yakwa nĩnĩũnthelela.'),
('kam', 'PSA', 40, 13, 'Ame Yeova, endeew’a nĩ kũmbonokya: Ĩkalaate ũndethye, ame Yeova.'),
('kam', 'PSA', 40, 14, 'Masonokw’e na kũthokoanw’a vamwe Ala mamanthaa thayũ wakwa mawanange: Matũngwe na ĩtina na kwanangĩwa ndaĩa Ala mew’aa mũyo nĩ kũnyamaw’a kwakwa.'),
('kam', 'PSA', 40, 15, 'Maekwe me athei kwondũ wa nthoni syoo Ala mambĩa, Aa! Aa!'),
('kam', 'PSA', 40, 16, 'Onthe ala makũmanthaa matane na kwĩw’a mũyo nthĩnĩ waku: Asu ala mendaa ũtangĩĩo waku maneenae mavinda onthe, Yeova nanenevw’e.'),
('kam', 'PSA', 40, 17, 'Nakwa nĩ ngya na mũthĩni; Ĩndĩ Mwĩaĩi nũndilikanaa: Nue mũtethya wakwa na mũvonokya wakwa; Ndũketeele, ame Ngai wakwa.'),
('kam', 'PSA', 41, 1, 'Kũathimwa nĩ ũla ũlilikanaa ngya: Mũthenya wa thĩna Yeova akamũvonokya.'),
('kam', 'PSA', 41, 2, 'Yeova akamũsũvĩa, na kũmwĩkalya e thayũ, Na akaathimwa e kũũ nthĩ; Na ndũkamũnengane kwendanĩ kwa amaitha make.'),
('kam', 'PSA', 41, 3, 'Yeova nĩwe ũkamũtethya e ũkomonĩ awaa: E mũwau nue ũmwalanĩlasya ũkomo wake w’onthe.'),
('kam', 'PSA', 41, 4, 'Nakwa nasya, ame Yeova mbĩw’ĩa tei: Vosya ngoo yakwa; nĩkwĩthĩwa nĩnakũvĩtanĩsye.'),
('kam', 'PSA', 41, 5, 'Amaitha makwa mengweta naĩ, makyasya, Akakw’a ĩndĩĩ, na syĩtwa yake yĩkyaa?'),
('kam', 'PSA', 41, 6, 'Na ethĩwa nĩwoka kũnzisya, aneenaa ũvũngũ; Ngoo yake ĩyũmbanĩasya ũthũku; Yĩla waumaala nza, akyũtavan’ya.'),
('kam', 'PSA', 41, 7, 'Onthe ala mamenaa nĩmanzukaa na kĩwe; Nĩmasũanĩaa ũthũku ĩũlũ wakwa.'),
('kam', 'PSA', 41, 8, 'Maasya nũlũmĩtwe nĩ ũwau mũthũku; Nake nũkomete yu ndakambĩla kũkĩla ĩngĩ.'),
('kam', 'PSA', 41, 9, 'Ĩĩ, o na mũnyanyawa ũla twĩsene, ũla namũĩkĩĩe, Ũla waĩsanĩaa lĩu nakwa, Nĩwe wambũkĩlĩlye kĩtiinyo kyake.'),
('kam', 'PSA', 41, 10, 'Ĩndĩ we, ame Yeova, mbĩw’ĩa tei na kũmbũkĩlya, Nĩ kana nĩĩvanĩsye.'),
('kam', 'PSA', 41, 11, 'Kwondũ wa ũu nĩngũmanya kana nĩwendeeawa ninyie, Nũndũ mũmaitha wakwa ndeũngĩlya vinya.'),
('kam', 'PSA', 41, 12, 'Ĩndĩ nyie, nũndũ wa wĩanĩu wakwa nũndw’ĩĩkaa, Na kũmbia mbee wa ũthyũ waku tene na tene.'),
('kam', 'PSA', 41, 13, 'Yeova, Ngai wa Isilaeli, nataĩwe, Kuma tene na tene na kũvika tene na tene. Ameni, na Ameni.'),
('kam', 'PSA', 42, 1, 'O tondũ ndaatai ĩvevavevaa ĩkĩmantha tũlũsĩ twa manzĩ, No ta ũu thayũ wakwa ũvevavevaa ũkĩũmantha, we Ngai.'),
('kam', 'PSA', 42, 2, 'Thayũ wakwa wĩ na waũni wa Ngai, wa Ngai ũla wĩ thayũ: Nakwa ngooka ĩndĩĩ na kumĩla mbee wa Ngai?'),
('kam', 'PSA', 42, 3, 'Methoi makwa nĩmeethĩiwe lĩu wakwa mũthenya na ũtukũ, Yĩla meĩkala maingũlangya mavinda onthe, Ngai waku aĩva?'),
('kam', 'PSA', 42, 4, 'Maũndũ aa nĩngũmalilikana, na kwĩtĩkya thayũ wakwa nthĩnĩ wakwa, O ũndũ naendie na nguthu, na kũmĩtongoesya kũvika nyũmbanĩ ya Ngai, Twaĩ na wasya wa ũtanu na ndaĩa, nguthu ya kũsũvĩa mũthenya mũtheu.'),
('kam', 'PSA', 42, 5, 'Nĩkĩ winamĩte, we thayũ wakwa? Na nĩkĩ ũkwĩthĩnĩsya nthĩnĩ wakwa? Ĩkwatye Ngai; nĩkwĩthĩwa ngasyoka kũmũkatha Nũndũ wa ũtethyo wa ũthyũ wake.'),
('kam', 'PSA', 42, 6, 'Ame Ngai wakwa, thayũ wakwa winamĩte nthĩnĩ wakwa: Kwondũ wa ũu nĩngũũlilikana kuma nthĩ ya Yolotani, Na kuma iĩmanĩ sya Elimoni, na kuma kalĩma ka Misali.'),
('kam', 'PSA', 42, 7, 'Kyũngũ kĩtaa kyũngũ kĩla kĩngĩ nũndũ wa kwan’ya kwa ndulumo syaku sya manzĩ: Itulumo syaku syonthe o na itulumo syaku nene nivĩtĩle ĩũlũ wakwa.'),
('kam', 'PSA', 42, 8, 'Yeova akeeaĩa ũseo wake wĩ wendo mũthenya; Na ũtukũ wathi wake ũkeethĩwa vamwe nakwa, O mboya ya kũmũvoyaa Ngai wa thayũ wakwa.'),
('kam', 'PSA', 42, 9, 'Ngamwĩa Ngai na nĩwe ĩvia yakwa, Nĩkĩ woolilwe ninyie? Nĩkĩ nĩendaa nĩmetete nũndũ wa kũthĩnw’a nĩ mũmaitha?'),
('kam', 'PSA', 42, 10, 'O ta nĩ na ũvyũ mavĩndĩnĩ makwa, nthũ syakwa niũmbũthya, Ikĩngũlangya mavinda onthe, Ngai waku aĩva?'),
('kam', 'PSA', 42, 11, 'Nĩkĩ winamĩte, we thayũ wakwa? Na nĩkĩ ũkwĩthĩnĩsya nthĩnĩ wakwa? Ĩkwatye Ngai; nĩkwĩthĩwa ngasyoka kũmũkatha. Ũla ũtethyo wa ũthyũ wakwa, na Ngai wakwa.'),
('kam', 'PSA', 43, 1, 'Ndw’ĩa sila, we Ngai, ndetanĩsya na mbaĩ ĩteũmũkĩa Ngai: Mbonokya na mũndũ mũkengani ũla ũtekaa w’o.'),
('kam', 'PSA', 43, 2, 'Nĩkwĩthĩwa nue Ngai wa vinya wakwa; nĩkĩ ũmbĩkĩtye ũtee? Nĩkĩ nĩendaa nĩmetete nũndũ wa kũthĩnw’a nĩ mũmaitha?'),
('kam', 'PSA', 43, 3, 'Ete kyeni kyaku na w’o waku; indongoesye: Imbikye kĩĩmanĩ kyaku kĩla kĩtheu, Na mawĩkalonĩ maku.'),
('kam', 'PSA', 43, 4, 'Ĩvinda yĩu ngavika kĩthembeonĩ kya Ngai, Vala ve Ngai, ũtanu wakwa mũnene mũno; Na ngakũtaĩa na mbeve, ame Ngai, Ngai wakwa.'),
('kam', 'PSA', 43, 5, 'Nĩkĩ winamĩte, we thayũ wakwa? Na nĩkĩ ũkwĩthĩnĩsya nthĩnĩ wakwa? Ĩkwatye Ngai; nĩkwĩthĩwa ngasyoka kũmũkatha, Ũla ũtethyo wa ũthyũ wakwa, na Ngai wakwa.'),
('kam', 'PSA', 44, 1, 'Nĩtwĩw’ĩte na matũ maitũ, we Ngai, Aaĩthe maitũ nĩmatũtavisye, Meko ala weekie matukũ moo, Mavinda ma tene.'),
('kam', 'PSA', 44, 2, 'Walũngilye i mbaĩ na kw’oko kwaku; Ĩndĩ mo nĩwamavandie kw’o: Wathĩnisye ngo sya andũ; Ĩndĩ mo wamanyasya kw’o.'),
('kam', 'PSA', 44, 3, 'Nĩkwĩthĩwa matyaosa nthĩ nũndũ wa ũvyũ woo, O na ti kw’oko kwoo kwamatangĩĩe; Ĩndĩ nĩ kw’oko kwaku kwa aũme, na kĩlalawa kyaku, na kyeni kya ũthyũ waku, Nĩkwĩthĩwa nĩwamendie.'),
('kam', 'PSA', 44, 4, 'Nue Mũsumbĩ wakwa, ame Ngai: Ĩae ũvonokyo ũndũ wa Yakovo.'),
('kam', 'PSA', 44, 5, 'Nũndũ wa vinya waku tũkavalũkya nthũ sitũ: Nũndũ wa syĩtwa yaku tũkamakinyanga ala matũkĩlĩĩlaa.'),
('kam', 'PSA', 44, 6, 'Nĩkwĩthĩwa ndikekwatya ũta wakwa, O na ũvyũ wakwa ndũkandangĩĩa.'),
('kam', 'PSA', 44, 7, 'Ĩndĩ nũtũtangĩĩĩte kuma nthũnĩ sitũ, Na nũmasonoketye ala matũmenaa.'),
('kam', 'PSA', 44, 8, 'Nĩtwĩkathĩĩĩte nthĩnĩ wa Ngai mũthenya w’onthe, Na tũkatũngĩa syĩtwa yaku mũvea tene na tene.'),
('kam', 'PSA', 44, 9, 'Ĩndĩ yu nĩwatwĩkisye ũtee kũasa, nĩwatwanangĩe ndaĩa, Na ndumaalanasya na nguthu sitũ sya kaũ.'),
('kam', 'PSA', 44, 10, 'Nũtumaa tũsyon’ya nthũ mĩongo yaitũ; Na ala matũmenaa mayĩtavĩa mĩtavo.'),
('kam', 'PSA', 44, 11, 'Ũtũnenganĩte ta malondu matw’ĩĩwe kũĩwa, Na kũtũnyaĩĩkya katĩ wa i mbaĩ.'),
('kam', 'PSA', 44, 12, 'Andũ maku nũmathooasya mana, Na ũthwii waku ndwingĩvĩtye nũndũ wa thooa ũla wamatee.'),
('kam', 'PSA', 44, 13, 'Nũtumaa twĩthĩwa ma kũvũthw’a nĩ atũi maitũ, Na ma kũvũĩwa ngũĩ na ma kũthekeewa nĩ ala me ngalĩ syonthe.'),
('kam', 'PSA', 44, 14, 'Nũtumaa twĩthĩwa ma kũvũthĩĩw’a katĩ wa i mbaĩ, Na kũtuma andũ mathingithangya mĩtwe.'),
('kam', 'PSA', 44, 15, 'Mũthenya w’onthe kwanangĩwa ndaĩa kwakwa kwĩ mbee wakwa, Na nthoni syĩ ũthyũnĩ wakwa nimbw’ĩkĩte,'),
('kam', 'PSA', 44, 16, 'Nũndũ wa wasya wa ũla ũvũthasya na kũumana, Kwondũ wa mũmaitha na mũĩvanĩsya.'),
('kam', 'PSA', 44, 17, 'Nĩtwookĩwe nĩ ũu w’onthe; ĩndĩ tũyaaũlwa nue, O na tũyaakengana ũtianĩonĩ waku.'),
('kam', 'PSA', 44, 18, 'Ngoo sitũ itisyokete na ĩtina, O na matambya maitũ matyaauma nzĩanĩ yaku,'),
('kam', 'PSA', 44, 19, 'O na kau nĩwatũtumbangĩe vala mbĩwa syĩkalaa, Na kũtũvw’ĩka na kyuu kya kĩkw’ũ.'),
('kam', 'PSA', 44, 20, 'Ethĩwa ithyĩ nĩtwoolĩtwe nĩ syĩtwa ya Ngai waitũ, Kana kũtambũũkĩsya ngai ngeni moko maitũ;'),
('kam', 'PSA', 44, 21, 'Nake Ngai ndakamantha ũndũ ũsu? Nĩkwĩthĩwa nĩwe wĩsĩ syĩmbithĩ sya ngoo.'),
('kam', 'PSA', 44, 22, 'Ĩĩ, kwondũ waku twĩũawa mũthenya w’onthe; Nĩtũtalawa kwĩthĩwa malondu ma kũawa.'),
('kam', 'PSA', 44, 23, 'Amũka, ũkometw’e nĩkĩ, we Mwĩaĩi? Ũkĩla, ndũkatwĩkye ũtee tene na tene.'),
('kam', 'PSA', 44, 24, 'Wĩvithĩa ũthyũ waku kĩ, Na kũlwa nĩ mathĩna maitũ na kũnyamaw’a kwitũ?'),
('kam', 'PSA', 44, 25, 'Nĩkwĩthĩwa ngoo sitũ nĩsinamĩte kĩtoonĩ: Mĩĩ yaitũ ĩkwatanĩte na nthĩ.'),
('kam', 'PSA', 44, 26, 'Ũkĩla ũtũtethye, Na twovosye kwondũ wa ũseo waku wĩ wendo.'),
('kam', 'PSA', 45, 1, 'Ngoo yakwa nĩyusũĩte na ĩketĩkangya ũndũ ũseo; Nĩngũneena maũndũ ala namũseũvĩsye mũsumbĩ: Ũĩmĩ wakwa nĩ kĩandĩki kya mũandĩki mwai.'),
('kam', 'PSA', 45, 2, 'Naku wĩ mũseo kũvĩtũka syana sya andũ; Mumo nĩwĩtĩkĩw’e ilomo syaku: Kwondũ wa ũu Ngai nũkũathimĩte kũvika tene na tene.'),
('kam', 'PSA', 45, 3, 'Ĩyove ũvyũ waku nthũnũnĩ we ũla wĩ na vinya, Nĩw’o ndaĩa yaku na ũnene waku.'),
('kam', 'PSA', 45, 4, 'Wĩ ũnenenĩ ũsu waku endeeaa ũkyathimĩkaa, Nũndũ wa w’o na ũuu na ũlũngalu: Na kw’oko kwaku kwa aũme kũkakũmanyĩsya maũndũ ma ũtĩsya.'),
('kam', 'PSA', 45, 5, 'Mĩsyĩ yaku nĩ myũĩ; Ngo sya andũ nivalũkaa ungu wa nyaĩĩ syaku; Yĩ ngoonĩ sya amaitha ma mũsumbĩ,'),
('kam', 'PSA', 45, 6, 'Kĩvĩla kyaku kya ũsumbĩ, ame Ngai, nĩ kya tene na tene: Ĩla ndata ya ũsumbĩ ya ũlũngalu nĩyo ndata ya ũsumbĩ waku.'),
('kam', 'PSA', 45, 7, 'We nĩwendete ũlũngalu, na kũmena ũthũku: Kwondũ wa ũu Ngai, Ngai waku, nĩwakwĩtĩkĩsye mauta, Mauta ma ũtanu, kũvĩta atindan’ya maku.'),
('kam', 'PSA', 45, 8, 'Ngũa syaku syonthe syĩ na mũuke wa manemane, na uuti, na kalavuu; Syĩndũ sya kũinga syĩ ndii kuma nyũmbanĩ nene syanakavĩtw’e na maeo ma nzou nĩsyakũtanisye.'),
('kam', 'PSA', 45, 9, 'Eĩtu ma asumbĩ me katĩ wa aka me nguma: Kw’okonĩ kwaku kwa aũme kĩveti kĩsumbĩ kĩũngamĩte kĩvw’ĩkĩte thaavu wa Ovilu.'),
('kam', 'PSA', 45, 10, 'Ĩthukĩĩsye, mwĩĩtu ũũ, na sũanĩa, na tea kũtũ; Ũlwa nĩ andũ maku, o na nyũmba ya ĩthe waku:'),
('kam', 'PSA', 45, 11, 'Kwondũ wa ũu ũla mũsumbĩ akenda wanake waku mũseo; Nĩkwĩthĩwa nĩwe mwĩaĩi waku; naku mũkĩe.'),
('kam', 'PSA', 45, 12, 'Na mwĩĩtu wa Tile akeethĩwa e vo akwete mũthĩnzĩo; Andũ athwii makeesũvana ũseo kwaku.'),
('kam', 'PSA', 45, 13, 'Mwĩĩtu wa mũsumbĩ e nthĩnĩ wa nyũmba nene mbanakavye no ũseo mũthei: Ngũa syake itumĩĩwe ndii sya thaavu.'),
('kam', 'PSA', 45, 14, 'Akatwawa kwa mũsumbĩ e na ngũa itumĩĩwe wanake: Eĩtu atheu atindan’ya make ala maatĩanĩa nake Makaetwe kũla ũĩ.'),
('kam', 'PSA', 45, 15, 'Makatongoew’a na ũtanu na mũyo: Makalika nyũmbanĩ ya mũsumbĩ.'),
('kam', 'PSA', 45, 16, 'Vandũ va aaĩthe maku vakeethĩwa syana syaku, Ila ũkaitw’ĩkĩthya anene me mbee ũsumbĩnĩ nthĩ yonthe.'),
('kam', 'PSA', 45, 17, 'Ngatuma syĩtwa yaku yĩlilikanwa nzyawanĩ syonthe: Kwondũ wa ũu ũkatũngĩwa mũvea nĩ ngo sya andũ tene na tene.'),
('kam', 'PSA', 46, 1, 'Ngai nĩ wĩvitho witũ na vinya witũ, Ũtethyo wĩ vakuvĩ twĩ thĩnanĩ.'),
('kam', 'PSA', 46, 2, 'Kwondũ wa ũu tũikakĩa, o na ethĩwa nthĩ ĩkaalyũka, O na ethĩwa iĩma ikathamĩĩw’a katĩ wa maũkanga;'),
('kam', 'PSA', 46, 3, 'O na ethĩwa manzĩ mamo makalitũka na kũthokoana, O na ethĩwa iĩma ikathingithangw’a nũndũ wa itulumo nene syamo.'),
('kam', 'PSA', 46, 4, 'Kwĩ ũsĩ, tũlũsĩ twaw’o tũtanĩthasya mũsyĩ wa Ngai, Vandũ vatheu va maeema ma Ũla Wĩ Ĩũlũ wa Onthe.'),
('kam', 'PSA', 46, 5, 'Ngai e katĩ waw’o; ndũkathingithika: Ngai akootethya, w’oa ũitema.'),
('kam', 'PSA', 46, 6, 'I mbaĩ nĩsyalonzanilye, mosumbĩ mathingithangw’a: Nake aumya wasya wake, nthĩ yatweka.'),
('kam', 'PSA', 46, 7, 'Yeova wa nguthu e vamwe naitũ; Ngai wa Yakovo nĩ wĩvitho witũ.'),
('kam', 'PSA', 46, 8, 'Ũkai, sisyai mawĩa ma Yeova, Ũndũ ũtw’ĩkĩthĩtye nthĩ nthei.'),
('kam', 'PSA', 46, 9, 'Nake nũtumaa makaũ mathela kũvika kĩtulu kya nthĩ; Nũtũlaa ũta, na ĩtumo aitilanga ilungu; Makasya ma kaũ nũvĩvasya na mwaki.'),
('kam', 'PSA', 46, 10, 'Kilyai, mũmanye ninyie Ngai: Nganenevw’a katĩ wa i mbaĩ, nganenevw’a nthĩ.'),
('kam', 'PSA', 46, 11, 'Yeova wa nguthu e vamwe naitũ; Ngai wa Yakovo nĩ wĩvitho witũ.'),
('kam', 'PSA', 47, 1, 'Kũnangai mbĩ syenyu, inyw’onthe ngo sya andũ; Mũkĩlĩlyei Ngai wasya wa ũkĩlyo.'),
('kam', 'PSA', 47, 2, 'Nĩkwĩthĩwa Yeova Ũla Wĩ Ĩũlũ wa Onthe nĩ wa ũtĩsya; Nĩ Mũsumbĩ mũnene ĩũlũ wa nthĩ yonthe.'),
('kam', 'PSA', 47, 3, 'Nũtumaa ngo sya andũ itheew’a ungu waitũ, Na i mbaĩ ungu wa nyaĩĩ sitũ.'),
('kam', 'PSA', 47, 4, 'Nake nũtũnyuvĩaa ũtiĩwa witũ, Naw’o nĩ ũnene wa Yakovo ũla ũmwendete.'),
('kam', 'PSA', 47, 5, 'Ngai nĩwambata ĩũlũ na wasya mũnene, O Yeova na wasya wa soo.'),
('kam', 'PSA', 47, 6, 'Mũtaĩei Ngai na mbathĩ, inai ndaĩa: Mwinĩei Mũsumbĩ waitũ ndaĩa, inai ndaĩa.'),
('kam', 'PSA', 47, 7, 'Nĩkwĩthĩwa Ngai nĩ Mũsumbĩ wa nthĩ yonthe: Inai ndaĩa mwĩ na ũmanyi.'),
('kam', 'PSA', 47, 8, 'Ngai nũsumbĩkaa ĩũlũ wa i mbaĩ: Ngai nĩwĩkalaa kĩvĩlanĩ kyake kĩtheu kya ũsumbĩ.'),
('kam', 'PSA', 47, 9, 'Anene me mbee ũsumbĩnĩ ma ngo sya andũ nĩmombanĩte vamwe Matw’ĩke andũ ma Ngai wa Avalaamu; Nĩkwĩthĩwa Ngai nĩwe mwene wa ngao sya nthĩ: Nake nũnenevetw’e mũno.'),
('kam', 'PSA', 48, 1, 'Yeova nĩ mũnene, na nĩ wa ũtaĩwa mũno, Ndũanĩ ya Ngai waitũ, kĩĩmanĩ kyake kĩla kĩtheu.'),
('kam', 'PSA', 48, 2, 'Nĩ kĩseo mũno kũtũlanĩ kwakyo, ũtanu wa nthĩ yonthe, Kĩĩma kyu kya Saioni, kĩla kĩ ngalĩ ya ĩũlũ, Ndũa ya Mũsumbĩ ũla mũnene.'),
('kam', 'PSA', 48, 3, 'Nyũmbanĩ nene mbanakavye syayo Ngai eyonanĩtye nĩwe wĩvitho.'),
('kam', 'PSA', 48, 4, 'Nĩkwĩthĩwa, sisya, asumbĩ nĩmoombanie, Mavĩta vamwe.'),
('kam', 'PSA', 48, 5, 'Mamyona, na makwatwa nĩ kũseng’a; Matw’ĩka nda, na mathi mĩtũki.'),
('kam', 'PSA', 48, 6, 'O vau makwatwa nĩ kĩtetemo, Woo, o ta kĩveti kĩkyaũnya.'),
('kam', 'PSA', 48, 7, 'Nĩwanangaa ngalawa sya Talisisi Na kĩseve kĩla kyumaa wumĩlonĩ wa syũa.'),
('kam', 'PSA', 48, 8, 'Tondũ twĩw’ĩte, now’o twonete Ndũanĩ ya Yeova wa nguthu, ndũanĩ ya Ngai waitũ: Ngai akamĩlũlũmĩlya kũvika tene na tene.'),
('kam', 'PSA', 48, 9, 'Nĩtũsũanĩĩte ũseo waku wĩ wendo, we Ngai, Twĩ ĩkalũnĩ yaku katĩ.'),
('kam', 'PSA', 48, 10, 'Tondũ syĩtwa yaku yĩilyĩ, we Ngai, Now’o ndaĩa yaku ĩilyĩ kũvika itulunĩ sya nthĩ: Kw’oko kwaku kwa aũme kusũĩtwe nĩ ũlũngalu.'),
('kam', 'PSA', 48, 11, 'Kĩĩma kya Saioni nĩkĩtane, Eĩtu ma Yuta matane, Nũndũ wa mosilĩlo maku.'),
('kam', 'PSA', 48, 12, 'Tambũkai mũthyũlũlũke Saioni; Talai myako mĩtũlu ya mĩnyoolo ya vo;'),
('kam', 'PSA', 48, 13, 'Sisyai nesa maũvai matũlu mayo; Sũanĩai nyũmba nene mbanakavye syayo: Nĩ kana mũtavan’ye nzyawanĩ ĩla yũkĩte.'),
('kam', 'PSA', 48, 14, 'Nĩkwĩthĩwa Ngai ũũ nĩ Ngai waitũ tene na tene: Nake akeethĩwa mũtongoi waitũ o na kũvika kĩkw’ũ.'),
('kam', 'PSA', 49, 1, 'Ĩw’ai ũũ, inyw’onthe ngo sya andũ; Teai matũ, inyw’onthe ala mũtũaa nthĩ,'),
('kam', 'PSA', 49, 2, 'Anini na anene, Athwii na ngya vamwe.'),
('kam', 'PSA', 49, 3, 'Kanyw’a wakwa ũkaneena ũĩ; Na mosũanĩo ma ngoo yakwa makeethĩwa ma ũmanyi.'),
('kam', 'PSA', 49, 4, 'Ngainamya kũtũ kwakwa kwĩw’e ngelekan’yo: Nthimo yakwa ngavuan’ya na mbeve.'),
('kam', 'PSA', 49, 5, 'Nĩ ũndũ wa kĩ ngũkĩa mĩthenya ya ũthũku, Yĩla ũthũku ũkũnthyũlũlũka itiinyonĩ syakwa?'),
('kam', 'PSA', 49, 6, 'Ala mekwĩkwatya ũthwii woo, Na kwĩkathĩĩaa ũndũ wa ũthwii woo kwingĩva;'),
('kam', 'PSA', 49, 7, 'Vai ũmwe wamo ũtonya kwovosya mwana‐a‐inya wake kwa ũndũ o na wĩva, Kana kũmũnenga Ngai mbovosya kwondũ wake'),
('kam', 'PSA', 49, 8, '(Nĩkwĩthĩwa wovosyo wa mathayũ moo wĩ thooa mũnene, Ndũĩvĩka tene na tene),'),
('kam', 'PSA', 49, 9, 'Nĩ kana ekale thayũ mavinda onthe, Ndakone wanangĩko.'),
('kam', 'PSA', 49, 10, 'Nĩkwĩthĩwa nĩwonaa kana andũ oĩ nĩmakusaa; Mũtumanu na mũng’endu onthe nĩmekwaa, Na makĩtiĩa andũ angĩ ũthwii woo.'),
('kam', 'PSA', 49, 11, 'Malilikano moo ma nthĩnĩ nĩ atĩ nyũmba syoo ikekalaa kũvika tene na tene, Na motũo moo kũvika nzyawa syonthe; Nao metanĩasya nthĩ syoo na masyĩtwa moo ene.'),
('kam', 'PSA', 49, 12, 'Ĩndĩ mũndũ ndekalaa ndaĩanĩ: Ailyĩ ta nyamũ ila syaaa.'),
('kam', 'PSA', 49, 13, 'Ĩno nĩ nzĩa ya ala atumanu: Ĩndĩ andũ ala mamaatĩĩaa makwataa ndeto syoo.'),
('kam', 'PSA', 49, 14, 'Nĩmatw’ĩĩwe ta ndĩthya ya kũthi Seoli; Kĩkw’ũ nĩkyo kĩkeethĩwa mũĩthi woo: Na kĩoko ala ma w’o makamasumbĩka; Na mũmbĩlwe woo mũseo ũkaminĩwa Seoli, Nĩ kana vaikethĩwe vandũ vaw’o va kũtũa.'),
('kam', 'PSA', 49, 15, 'Ĩndĩ Ngai akawovosya thayũ wakwa kuma vinyanĩ wa Seoli; Nĩkwĩthĩwa akambosa.'),
('kam', 'PSA', 49, 16, 'Ndũkethĩwe na w’ĩa yĩla mũndũ ũngĩ ũnũkũthua, Yila ũthwii wa nyũmba yake ũkwingĩvw’a:'),
('kam', 'PSA', 49, 17, 'Nĩkwĩthĩwa akw’a nde kĩndũ ũkathi nakyo: Ũnene wake ndũkatheean’ya nake.'),
('kam', 'PSA', 49, 18, 'O na kau yĩla waĩ thayũ nĩwetanasya thayũ wake (Na andũ nĩmakũtaĩaa, yĩla ũkwĩyĩka mwene nesa),'),
('kam', 'PSA', 49, 19, 'Akathi kũla kwĩ nzyawa ya aaĩthe make; Asu matikona kyeni o na ĩndĩĩ.'),
('kam', 'PSA', 49, 20, 'Mũndũ wĩ na ndaĩa, na nde na ũmanyi, Ailyĩ ta nyamũ ila syaaa.'),
('kam', 'PSA', 50, 1, 'Ũla Mwene Vinya, Ngai, Yeova, nũneenete, Na kwĩta nthĩ kuma syũa yĩkyuma kũvika kũthũa kwayo.'),
('kam', 'PSA', 50, 2, 'E Saioni, wĩanĩu wa ũseo, Ngai nũtisũkĩte.'),
('kam', 'PSA', 50, 3, 'Ngai waitũ nĩ mũku, na ndavindya: Mwaki nũminaa mbee wake, Na ngalĩ syonthe nĩwĩlingĩlwe nĩ kĩuutani kĩ vinya.'),
('kam', 'PSA', 50, 4, 'Nake nĩwĩtaa matu me ĩũlũ, Na nthĩ nayo, nĩ kana asilĩle andũ make:'),
('kam', 'PSA', 50, 5, 'Ũmban’yai atheu makwa vala nĩĩ, Ala matianĩe ũtianĩo nakwa nthembonĩ.'),
('kam', 'PSA', 50, 6, 'Na matu makatavan’ya ũlũngalu wake; Nĩkwĩthĩwa Ngai mwene nĩwe mũsili.'),
('kam', 'PSA', 50, 7, 'Ĩw’ai, inyw’ĩ andũ makwa, na nganeena; We Isilaeli, na ngakũ kũsĩĩa: Ninyie Ngai, Ngai waku.'),
('kam', 'PSA', 50, 8, 'Ndikakũkan’ya nũndũ wa nthembo syaku sya kũtonywa; Kana nũndũ wa nthembo syaku sya ũvĩvw’a ila mbee wakwa mavinda onthe.'),
('kam', 'PSA', 50, 9, 'Ndikosa kasalũ ka mũew’a nyũmbanĩ yaku, Kana nthenge kuma syengonĩ syaku.'),
('kam', 'PSA', 50, 10, 'Nĩkwĩthĩwa kĩla nyamũ yĩ mũtitũnĩ nĩ yakwa, O na indo syĩ iĩmanĩ ngili.'),
('kam', 'PSA', 50, 11, 'Nĩnĩsyĩsĩ nyũnyi syonthe syĩ iĩmanĩ; O na nyamũ sya kĩthekanĩ ila syĩkalaa weũnĩ nĩ syakwa.'),
('kam', 'PSA', 50, 12, 'Kethĩwa nĩnĩsa kwĩw’a nzaa, ndikũtavya; Nĩkwĩthĩwa nthĩ nĩ yakwa, na syĩndũ imyusũĩte.'),
('kam', 'PSA', 50, 13, 'Nakwa ngaya nyama sya nzaũ, Kana kũnyw’a nthakame ya mbũi?'),
('kam', 'PSA', 50, 14, 'Mumĩsye Ngai nthembo ya mũvea; Na ĩanĩsya mawĩvĩto maku ala wamwĩvĩtĩe Ũla Wĩ Ĩũlũ wa Onthe;'),
('kam', 'PSA', 50, 15, 'Mũthenya ũla wĩ na thĩna mbĩkaĩla: Ngakũvonokya, naku ũkandaĩa.'),
('kam', 'PSA', 50, 16, 'Ĩndĩ ũla mũthũku Ngai nũnũũmũkũlya atĩĩ, Nĩkĩ we ũtavanasya myamũlo yakwa, Na kũwetaa ũtianĩo wakwa kanyw’anĩ waku?'),
('kam', 'PSA', 50, 17, 'Nũndũ nũmenaa ũtao, Na kwĩkya ndeto syakwa ĩtina waku.'),
('kam', 'PSA', 50, 18, 'Yĩla wonaa kĩng’eĩ, nĩwĩw’anaa nakyo, Na wĩ kĩanda kĩmwe na ilaalai.'),
('kam', 'PSA', 50, 19, 'Nũnenganae kanyw’a waku ũthũkunĩ, Na ũĩmĩ waku ũneenaa ũkengani.'),
('kam', 'PSA', 50, 20, 'Ũilyĩ nthĩ na kũmũneenea mwana‐ainyia waku; Ũkĩmũsuka mwana‐a‐mwenyu.'),
('kam', 'PSA', 50, 21, 'Nĩweekie maũndũ asu, nakwa navindya; Watalilye kana nĩvw’anene naku: Ĩndĩ ngakũkan’ya, na ngamaia maatĩanĩe mbee wa metho maku.'),
('kam', 'PSA', 50, 22, 'Na yu sũanĩai ũu, inyw’ĩ ala mũlawa nĩ Ngai, Ndikese kũmũtembũanga tũlungu, na vatikethĩwa wa kũmũvonokya:'),
('kam', 'PSA', 50, 23, 'Ũla umasya nthembo ya mũvea nũndaĩaa nyie; Na ũla wĩlũngalasya mwĩkalĩle wake Ngamwon’ya ũtangiĩo wa Ngai.'),
('kam', 'PSA', 51, 1, 'Mbĩw’ĩa tei, ame Ngai, kwĩanana na ũseo waku wĩ wendo: Kwĩanana na wingĩ wa matei maku mololo vuta mavĩtyo makwa.'),
('kam', 'PSA', 51, 2, 'Nthambya ũthũku wakwa vyũ, Na nthesya naĩ yakwa.'),
('kam', 'PSA', 51, 3, 'Nĩkwĩthĩwa nĩnĩmesĩ mavĩtyo makwa; Na naĩ yakwa yĩ mbee wakwa mavinda onthe.'),
('kam', 'PSA', 51, 4, 'Nĩnakũvĩtanĩsye, we wĩ weka, Nĩneekie ũthũku methonĩ maku; Nĩ kana wĩthĩwe wĩ mũlũngalu yĩla wĩneena, Na wĩthĩwe wĩ mũtheu yĩla wĩsila.'),
('kam', 'PSA', 51, 5, 'Sisya, nasyaĩwe ũthũkunĩ; Na mwaitũ angitavĩe o naĩnĩ.'),
('kam', 'PSA', 51, 6, 'Sisya, nĩwendaa w’o wĩthĩwe nthĩnĩ; Na vo nthĩnĩ kĩmbithĩnĩ ũkamanyĩthya ũĩ.'),
('kam', 'PSA', 51, 7, 'Nthesya na ĩsovo, na ngeethĩwa nĩ mũtheu: Nthambya, na ngeethĩwa nĩ mweũ kũvĩta ĩa.'),
('kam', 'PSA', 51, 8, 'Mbĩw’ĩthya ũtanu na mũyo, Nĩ kana mavĩndĩ ala watũlile matane.'),
('kam', 'PSA', 51, 9, 'Vitha ũthyũ waku ũeke kwona naĩ syakwa, Na vuta mothũku makwa onthe.'),
('kam', 'PSA', 51, 10, 'Ame Ngai, mbũmbĩa ngoo ntheu; Na tũnga ĩngĩ veva wa w’o nthĩnĩ wakwa.'),
('kam', 'PSA', 51, 11, 'Ndũkambĩkye kũasa kuma vala ũĩ; Na ndũkambetee Veva waku mũtheu.'),
('kam', 'PSA', 51, 12, 'Ndũngĩa ũtanu wa ũtangĩĩo waku; Na ndw’ĩĩka na veva mũthasye.'),
('kam', 'PSA', 51, 13, 'Nĩvo ĩndĩ ngamanyĩsya avĩtan’ya nzĩa syaku; Na athe makakwĩthyũũĩa.'),
('kam', 'PSA', 51, 14, 'Ame Ngai, nue Ngai wa ũtangĩĩo wakwa, mbonokya ĩvĩtyonĩ ya kwĩtĩkya nthakame; Na ũĩmĩ wakwa ũkaina ũlũngalu waku.'),
('kam', 'PSA', 51, 15, 'Ame Mwĩaĩi, tũmũkan’ya ilomo syakwa; Na kanyw’a wakwa ũkoonan’ya ndaĩa syaku.'),
('kam', 'PSA', 51, 16, 'Nĩkwĩthĩwa ndwendeew’a nĩ nthembo ya kũtonywa; kethĩwa nĩw’o nĩkumya: Ndwendeew’a nĩ nthembo ya ũvĩvw’a.'),
('kam', 'PSA', 51, 17, 'Nthembo sya Ngai nĩ veva mũtũlĩku: Ngoo ĩla ndũlĩku na yĩ na wĩlilo, we Ngai, ndũkamĩvũthya.'),
('kam', 'PSA', 51, 18, 'Ĩka Saioni nesa kwendanĩ kwaku kũseo: Aka maũvai ma Yelusaleme.'),
('kam', 'PSA', 51, 19, 'Nĩvo ũkatanĩa nthembo sya ũlũngalu, Nthembo ya ũvĩvw’a na nthembo nima sya ũvĩvw’a: Nĩvo makathemba tũsalũ twa mũew’a kĩthembeonĩ kyaku.'),
('kam', 'PSA', 52, 1, 'Wĩkathĩĩaa ũthũkunĩ nĩkĩ, we mũndũ wĩ ũtonyi? Ũseo wĩ wendo wa Ngai nĩwĩkalaa mavinda onthe.'),
('kam', 'PSA', 52, 2, 'Ũĩmĩ waku nĩwambĩlĩlasya kĩla ũthũku, Ũilyĩ ta wenzi mũĩ, we mwĩki wa ũkengani.'),
('kam', 'PSA', 52, 3, 'Nĩwendaa ũvũngũ kũvĩta ũseo, Na ũvũngũ kũvĩta kũneena ũlũngalu.'),
('kam', 'PSA', 52, 4, 'Nĩwendaa ndeto syonthe ila imelasya, We ũĩmĩ wĩ na ũkengani.'),
('kam', 'PSA', 52, 5, 'Ngai nake akakwananga kũvika tene na tene; Akakũkwata, na kũkũkuthũa ĩeemanĩ yaku, Na akakũkũa kuma nthĩ ya ala me thayũ.'),
('kam', 'PSA', 52, 6, 'Ala alũngalu makoona ũu, na kũkĩa, Na makamũthekeea, makyasya,'),
('kam', 'PSA', 52, 7, 'Sisya, ũũ nĩwe mũndũ ũla ũtaamũtw’a Ngai ethĩwe vinya wake, Ĩndĩ aĩkĩĩe wingĩ wa ũthwii wake, Na eelũlũmĩlye mwene ũthũkunĩ wake.'),
('kam', 'PSA', 52, 8, 'Ĩndĩ nyie, nĩilyĩ ta mũtĩ mwĩũ wa mũthata nyũmbanĩ ya Ngai: Nĩkwatasya ũseo wĩ wendo wa Ngai kũvika tene na tene.'),
('kam', 'PSA', 52, 9, 'Ngakũtũngĩa mũvea tene na tene, nũndũ nĩwĩkĩte ũu; Na ngeekwatya syĩtwa yaku, atheu maku mene, nĩkwĩthĩwa ũu nĩ ũseo.'),
('kam', 'PSA', 53, 1, 'Ndia yaasya ngoonĩ yayo, Kũti Ngai. Nĩmanangĩkĩte, na mekĩte ũthũku ũla ũthatasya; Vai ũmwe ũla wĩkaa nesa.'),
('kam', 'PSA', 53, 2, 'Ngai asyaĩĩsye ana ma andũ e ĩtunĩ, Asisye ethĩwa ve ũmwe ũla wĩ na ũmanyi, Ũla ũmanthaa Ngai.'),
('kam', 'PSA', 53, 3, 'Onthe nĩmasyokete na ĩtina; onthe vamwe nĩmatw’ĩkĩte avuku; Vai ũmwe wĩkaa nesa aiee, o na ũmwe.'),
('kam', 'PSA', 53, 4, 'Eki ma naĩ mati na ũmanyi, Ala maĩsaa andũ makwa tondũ maĩsaa lĩu, Na matimwĩkaĩlaa Ngai?'),
('kam', 'PSA', 53, 5, 'Vau malikĩlwe nĩ w’ĩa nũnene, vala vataĩ w’ĩa; Nĩkwĩthĩwa Ngai nũnyaĩĩkĩtye mavĩndĩ ma ũla wambie maeema makũthyũlũlũkĩte: Nũmasonoketye, nũndũ Ngai nũmaleete.'),
('kam', 'PSA', 53, 6, 'A! Kethĩwa ũtangĩĩo wa Isilaeli wĩthĩwa wuma Saioni! Yĩla Ngai wĩtũnga andũ make maume kũtavwanĩ, Nĩvo ĩndĩ Yakovo wĩtana, na Isilaeli akeethĩwa na mũyo.'),
('kam', 'PSA', 54, 1, 'Ame Ngai, ndangĩĩa kwondũ wa syĩtwa yaku, Na ũtonyinĩ waku nzilĩla.'),
('kam', 'PSA', 54, 2, 'Ĩw’a mboya yakwa, ame Ngai; Tea matũ wĩw’e ndeto sya kanyw’a wakwa.'),
('kam', 'PSA', 54, 3, 'Nĩkwĩthĩwa aeni nĩmambũkĩlĩle, Na andũ ang’endu nĩmamanthaa thayũ wakwa: Matyaamwia Ngai mbee woo.'),
('kam', 'PSA', 54, 4, 'Sisya, Ngai nĩwe mũtethya wakwa: Mwĩaĩi e vamwe na ala matw’ĩĩkaa thayũ wakwa.'),
('kam', 'PSA', 54, 5, 'Akamaĩva amaitha makwa ũthũku woo: Kwondũ wa w’o waku manange.'),
('kam', 'PSA', 54, 6, 'Ngakumĩsya nthembo ya ngoo ya kwenda; Ngatũngĩa syĩtwa yaku mũvea, ame Yeova, nũndũ ũu nĩ ũseo.'),
('kam', 'PSA', 54, 7, 'Nĩkwĩthĩwa nũmboneketye mathĩnanĩ onthe; Na itho yakwa nĩyonete ũndũ ũla nendie amaitha makwa mekwe.'),
('kam', 'PSA', 55, 1, 'Tea matũ wĩw’e mboya yakwa, ame Ngai; Na ndũkevithe yĩla ngũkwĩsũva.'),
('kam', 'PSA', 55, 2, 'Mbĩthukĩĩsya, na ũinzũngĩa: Nĩngwangaĩka mũnyungunyĩsyonĩ wakwa, na kũluma,'),
('kam', 'PSA', 55, 3, 'Nũndũ wa wasya wa mũmaitha, Nũndũ wa kũnyamaw’a nĩ ala athũku; Nĩkwĩthĩwa nĩmeũmbĩkĩsya ũthũku, Na nĩmeũnthĩn’ya me na ũthatu.'),
('kam', 'PSA', 55, 4, 'Ngoo yakwa nĩnĩũmbalya mũno nthĩnĩ wakwa: Na maw’ĩa ma kĩkw’ũ nĩmambalũkĩle.'),
('kam', 'PSA', 55, 5, 'W’ĩa na kũtetema ningwatĩte, Na w’ĩa mũnene nũmbw’ĩkĩte.'),
('kam', 'PSA', 55, 6, 'Na nasya, A! Kethĩwa nĩ na nthwau ta ĩvũĩ! Nĩthĩwa nĩũlũka, na kũthũmũa.'),
('kam', 'PSA', 55, 7, 'Sisya, nĩthĩwa nanganga kũasa, Na kũtũa weũnĩ.'),
('kam', 'PSA', 55, 8, 'Nĩthĩwa nĩthi mĩtũkĩ vala ve wĩvitho Kuma kĩsevenĩ kĩnene na kĩuutaninĩ.'),
('kam', 'PSA', 55, 9, 'Ananga, ame Mwĩaĩi, na atũa nĩmĩ syoo; Nũndũ nĩnonete ũng’endu na mũtetan’yo ndũanĩ.'),
('kam', 'PSA', 55, 10, 'Mamĩthyũlũlũkaa mũthenya na ũtukũ maũvainĩ mayo: O na ũthũku na wanango me nthĩnĩ wayo.'),
('kam', 'PSA', 55, 11, 'Ũthũku wĩ vo katĩ wayo: Ũnyamao na ũĩ wa ũkengani maiumaa nzĩanĩ nene syayo.'),
('kam', 'PSA', 55, 12, 'Nĩkwĩthĩwa ti mũmaitha ũla wambũthisye; Kethĩwa nĩ w’o nĩthĩwa nĩtonya kũmĩĩsya: O na ti ũla wamenie wetũlilye ĩũlũ wakwa; Kethĩwa nĩ w’o nĩthĩwa nĩvitha kuma kũla ũĩ:'),
('kam', 'PSA', 55, 13, 'Ĩndĩ nue, mũndũ wĩanene nakwa, Mũtindan’ya wakwa, na mũnyanyawa ũla twĩsene mũno.'),
('kam', 'PSA', 55, 14, 'Nĩtweew’anĩte nesa; Twaendaa twĩ vamwe na ĩkomano nyũbanĩ ya Ngai.'),
('kam', 'PSA', 55, 15, 'Kĩkw’ũ nĩkĩmathũlũmũkĩle, Matheee me thayũ Seoli; Nĩkwĩthĩwa ũthũku wĩ ũtũonĩ woo, o vau katĩ wamo.'),
('kam', 'PSA', 55, 16, 'Ĩndĩ nyie, ngamwĩkaĩla Ngai; Na Yeova akandangĩĩa.'),
('kam', 'PSA', 55, 17, 'Wĩoo, na kĩoko, na mũthenya katĩ, ngavoyaa, na kũluma; Nake akeew’a wasya wakwa.'),
('kam', 'PSA', 55, 18, 'Nĩwovoetye thayũ wakwa nĩkale na mũuo kuma kaũnĩ ũla waĩ ĩũlũ wakwa; Nũndũ ala mokitie nakwa maĩ aingĩ.'),
('kam', 'PSA', 55, 19, 'Ngai akamew’a, na kũmathĩn’ya, We ũla wekalaa kuma tene tene, Ala matekwĩalyũla Na mateũmũkĩa Ngai.'),
('kam', 'PSA', 55, 20, 'Nũtambũũkĩtye moko make ĩũlũ wa ala maĩ na mũuo nake: Nĩwanangĩte ũtianĩo wake.'),
('kam', 'PSA', 55, 21, 'Kanyw’a wake waĩ mũtendeũ ta mauta ma meo, Ĩndĩ ngoo yake yaĩ kaũ: Ndeto syake syaĩ mbololo kwĩ mauta, Ĩndĩ syaĩ mbyũ ngũe.'),
('kam', 'PSA', 55, 22, 'Mwaũĩe Yeova mũio waku, nake akakũtw’ĩĩka: Ndakaeka ala alũngalu mathingithangw’e o na ĩndĩĩ.'),
('kam', 'PSA', 55, 23, 'Ĩndĩ we, ame Ngai, ũkamatheesya malike ĩimanĩ ya wanangĩko: Andũ ala mang’aatũkaw’a nĩ nthakame na akengani maikeanĩsya nyuzu ya matukũ moo; Ĩndĩ nyie ngakũĩkĩĩa.'),
('kam', 'PSA', 56, 1, 'Mbĩw’ĩa tei, ame Ngai, nũndũ mũndũ nũnũkwenda kũmelya nyie: Mũthenya w’onthe nũnũũnthĩn’ya na kaũ.'),
('kam', 'PSA', 56, 2, 'Mũthenya w’onthe amaitha makwa nĩmekwenda kũmelya; Nĩkwĩthĩwa nĩ aingĩ ala mekũkita nakwa me na ngathĩĩo.'),
('kam', 'PSA', 56, 3, 'Ĩvinda yĩla ngũkĩa, Ngakũĩkĩĩa.'),
('kam', 'PSA', 56, 4, 'Nthĩnĩ wa Ngai (ngamĩtaĩa ndeto yake), Wĩkwatyo wakwa wĩ nthĩnĩ wa Ngai, ndikakĩa; Ũla wĩ na mwĩĩ atonya kũmbĩka ata?'),
('kam', 'PSA', 56, 5, 'Mũthenya w’onthe mekalaa makyelelũkya ndeto syakwa: Mosũanĩo moo onthe masũanĩaa kũmbĩka ũthũku.'),
('kam', 'PSA', 56, 6, 'Mo mombanaa vamwe, mevithaa, Masyĩmaa mĩendele yakwa, O tondũ meteelile thayũ wakwa.'),
('kam', 'PSA', 56, 7, 'Makavonokw’a nĩ ũthũku woo? Ame Ngai, valũkya ngo sya andũ ũthatunĩ waku.'),
('kam', 'PSA', 56, 8, 'Nũtalaa manganga makwa: Ĩkĩa methoi makwa sũvanĩ waku; Ti maandĩke ĩvukunĩ yaku?'),
('kam', 'PSA', 56, 9, 'Na ĩndĩ amaitha makwa makasyoka na ĩtina mũthenya ũla nĩĩkaĩla: Ũndũ ũũ nĩnĩsĩ, kana Ngai e ngalĩ yakwa.'),
('kam', 'PSA', 56, 10, 'Nthĩnĩ wa Ngai (ngataĩa ndeto yake), Nthĩnĩ wa Yeova (ngataĩa ndeto yake),'),
('kam', 'PSA', 56, 11, 'Wĩkwatyo wakwa wĩ nthĩnĩ wa Ngai, ndikakĩa; Mũndũ atonya kũmbĩka ata?'),
('kam', 'PSA', 56, 12, 'Mawĩvĩto maku ala nakwĩvĩtĩe me ĩũlũ wakwa, we Ngai: Ngakumĩsya nthembo sya mũvea.'),
('kam', 'PSA', 56, 13, 'Nĩkwĩthĩwa nũvonoketye thayũ wakwa kuma kĩkw’ũnĩ: Maũũ makwa tuue wamavonokisye matikavalũke, Nĩ kana nĩkinye mbee wa Ngai Kyeninĩ kya ala me thayũ?'),
('kam', 'PSA', 57, 1, 'Mbĩw’ĩa tei, ame Ngai, mbĩw’ĩa tei; Nĩkwĩthĩwa thayũ wakwa wĩvithaa nthĩnĩ waku: Ĩĩ, ngeevitha muunyĩnĩ wa nthwau syaku, Mũvaka monyamao aa mavĩte.'),
('kam', 'PSA', 57, 2, 'Ngamwĩkaĩla Ngai Ũla Wĩ Ĩũlũ wa Onthe, Nake nĩwe Ngai ũla ũmbĩanĩasya maũndũ onthe.'),
('kam', 'PSA', 57, 3, 'Nake akatũmana kuma ĩtunĩ, na akandangĩĩa, Yĩla ũsu ũla ũnũkwenda kũmelya ũnũũmbũthya; Ngai akatũma ũseo wake wĩ wendo na w’o wake.'),
('kam', 'PSA', 57, 4, 'Thayũ wakwa wĩ katĩ wa mĩnyambũ; Nĩkomaa katĩ wa ala makene mwaki, O na ma andũ, ala maeo moo nĩ matumo na mĩsyĩ, Na nĩmĩ syoo nĩ mbyũ mbũĩ.'),
('kam', 'PSA', 57, 5, 'Ũtũlw’e, ame Ngai, ĩũlũ wa matu; Ũnene waku wĩthĩwe ĩũlũ wa nthĩ yonthe.'),
('kam', 'PSA', 57, 6, 'Nĩmaseũvĩtye kĩtei ũndũ wa matambya makwa; Thayũ wakwa nũkwinama: Nĩmambĩnzĩĩte ĩima; Namo ene nĩmavalũkĩte nthĩnĩ wayo.'),
('kam', 'PSA', 57, 7, 'Ngoo yakwa nĩlũmĩte, ame Ngai, ngoo yakwa nĩlũmĩte: Ngaina, ĩĩ, ngaina ndaĩa.'),
('kam', 'PSA', 57, 8, 'Amũka, ũnene wakwa; amũkai, kĩnanda na mbeve: Nakwa ngaamũka w’oa ũitema.'),
('kam', 'PSA', 57, 9, 'Ngakũtũngĩa mũvea, Mwĩaĩi, katĩ wa ngo sya andũ: Ngakwinĩa ndaĩa katĩ wa ĩ mbaĩ.'),
('kam', 'PSA', 57, 10, 'Nĩkwĩthĩwa ũseo waku wĩ wendo nĩ mũnene kũvika matunĩ, Na w’o waku kũvika matunĩ.'),
('kam', 'PSA', 57, 11, 'Ũtũlw’e ĩũlũ wa matu, ame Ngai; Ũtheu mũtisu waku wĩthĩwe ĩũlũ wa nthĩ yonthe.'),
('kam', 'PSA', 58, 1, 'Nĩ w’o nĩmũneenaa ũlũngalu inyw’ĩ ala mwĩ ũtonyi? Nĩmũsilaa w’o, inyw’ĩ ana ma andũ?'),
('kam', 'PSA', 58, 2, 'Aiee, ngoonĩ syenyu nĩmwĩkaa ũthũku; Nĩmũthimĩaa nthĩ ũng’endu wa moko menyu.'),
('kam', 'PSA', 58, 3, 'Ala athũku nĩmavathanĩtw’e o kuma ĩvunĩ: Nĩmaaa o masyawa, makĩneena movũngũ.'),
('kam', 'PSA', 58, 4, 'Ũoi woo ũtilyĩ ta ũoi wa nzoka: Mailyĩ kĩmbuva kĩla kĩtew’aa nthĩ kĩkĩkunĩka kũtũ kwakyo,'),
('kam', 'PSA', 58, 5, 'Kĩla kĩtew’aa wasya wa ala avoovya, O na makĩvoovya na ũĩ mwingĩ.'),
('kam', 'PSA', 58, 6, 'Ngai, tũlĩla maeo moo, o makanyw’anĩ moo: Kũa maeo manene ma mĩnyambũ ya mũika, ame Yeova.'),
('kam', 'PSA', 58, 7, 'Nĩmatweke ta manzĩ ala mavĩtaa mĩtũkĩ: Yĩla ũvakĩĩsye mĩsyĩ yake, nĩyĩthĩwe ta mĩting’ũe.'),
('kam', 'PSA', 58, 8, 'Methĩwe ta ĩusya yĩla yĩtwekaa na yĩkavĩta, Ta kĩvuno kĩvunĩtwe nĩ mũndũ mũka, kĩla kĩtaona syũa.'),
('kam', 'PSA', 58, 9, 'Mbee wa mbisũ syaku itanew’a mwaki wa mĩw’a, Akamaveta na kĩlingi, ĩla mĩũ na myakanu o ũndũ ũmwe.'),
('kam', 'PSA', 58, 10, 'Ũla mũlũngalu akatana oona ũla ũĩvanĩsyo: Akathambĩsya maũũ make nthakamenĩ ya ala athũku;'),
('kam', 'PSA', 58, 11, 'Kwondũ wa ũu andũ makasya, Nĩ w’o kwĩ ĩtuvi ya ala alũngalu: Nĩ w’o kwĩ Ngai ũla ũsilaa kũũ nthĩ.'),
('kam', 'PSA', 59, 1, 'Mbonokya kwa amaitha makwa, ame Ngai wakwa: Mbia vandũ vatũlu nume kwa ala mambũkĩlĩlaa.'),
('kam', 'PSA', 59, 2, 'Mbonokya kwa ala mekaa ũthũku, Na ndangĩĩa kwa andũ ala mang’aatũkaw’a nĩ nthakame.'),
('kam', 'PSA', 59, 3, 'Nĩkwĩthĩwa, sisya, moveeasya thayũ wakwa; Ala me na ũtonyi nĩmekũmbũmbanĩa: Ti ũndũ wa ĩvĩtyo yakwa, kana ũndũ wa naĩ yakwa, we Yeova.'),
('kam', 'PSA', 59, 4, 'Masembaa na kwĩyũmban’ya o na vate ĩvĩtyo yakwa: Amũka ũndethye, na ũisisya.'),
('kam', 'PSA', 59, 5, 'O naku, ame Yeova Ngai wa nguthu, Ngai wa Isilaeli, Ũkĩla ũkasisye i mbaĩ syonthe: Ndũkamew’ĩe tei avĩtan’ya athũku o na ũmwe.'),
('kam', 'PSA', 59, 6, 'Wĩoo masyoka, maĩaa ta ngitĩ, Na makĩthyũlũlũka ndũa.'),
('kam', 'PSA', 59, 7, 'Sisya, meelũka na makanyw’a moo; Ilomonĩ syoo kwĩ mbyũ: Nĩkwĩthĩwa maasya, nũũ ũla ũnũkwĩw’a?'),
('kam', 'PSA', 59, 8, 'Ĩndĩ we, Yeova, ũkamathekeea; I mbaĩ syonthe ũkaivũthya.'),
('kam', 'PSA', 59, 9, 'Ame vinya wakwa, ngakwĩthukĩĩsya; Nĩkwĩthĩwa Ngai nĩ mwako wakwa mũtũlu wa mũnyoolo.'),
('kam', 'PSA', 59, 10, 'Ngai wakwa akandongoesya na ũseo wake wĩ wendo: Ngai akanenga kwona ũla ngwenda kũla kwĩ amaitha makwa.'),
('kam', 'PSA', 59, 11, 'Ndũkamoae, andũ makwa matikese kũlwa: Manyaĩĩkye na vinya waku, na kũmatheesya, Ame Mwĩaĩi ngao yaitũ.'),
('kam', 'PSA', 59, 12, 'Ũndũ wa naĩ ya makanyw’a moo, na ndeto sya ilomo syoo, Makwatwe o ngathĩĩonĩ syoo, Na ũndũ wa kũumana na movũngũ ala maneenaa.'),
('kam', 'PSA', 59, 13, 'Mamine na ũthilĩku, mamine, nĩ kana matikethĩwe vo ĩngĩ: Mamanye atĩ Ngai nũsumbĩkaa kwa Yakovo, Kũvika itulunĩ sya nthĩ.'),
('kam', 'PSA', 59, 14, 'Wĩoo nĩmasyoke, nĩmaĩe ta ngitĩ, Na kũthyũlũlũka ndũa.'),
('kam', 'PSA', 59, 15, 'Makangangaa kũũ na kũũ makĩmantha kya ũya, Na malea kũvũna makekalaa ũtukũ w’onthe.'),
('kam', 'PSA', 59, 16, 'Ĩndĩ nyie ngaina ũndũ wa vinya waku; Ĩĩ, ngaina na wasya ũndũ wa ũseo waku wĩ wendo kĩoko: Nĩkwĩthĩwa nue wĩthĩawa mwako wakwa mũtũlu mũno wa mũnyoolo, Na wĩvitho mũthenya wa thĩna wakwa.'),
('kam', 'PSA', 59, 17, 'Naku vinya wakwa, ngakwinĩa ngĩkũtaĩa: Nĩkwĩthĩwa Ngai nĩwe mwako wakwa mũtũlu mũno wa mũnyoolo, Ngai ũla ũmbĩw’ĩaa tei.'),
('kam', 'PSA', 60, 1, 'Ame Ngai, nue watwĩkisye ũtee, nue watũtũlile; Nue wathatĩte; tũtũnge ĩngĩ.'),
('kam', 'PSA', 60, 2, 'Nũtumĩte nthĩ ĩthingitha; nũmĩtembũĩte: Linda matw’ĩku mayo; nĩkwĩthĩwa nĩnĩkũtetema.'),
('kam', 'PSA', 60, 3, 'Nũmonetye andũ maku maũndũ maito: Ũtũnyw’ĩthĩtye mbinyu ya kũlũsya.'),
('kam', 'PSA', 60, 4, 'Nũmanengete kĩvevelo asu ala makũkĩaa, Nĩ kana kyũkĩlw’e ĩũlũ nũndũ wa ũla w’o.'),
('kam', 'PSA', 60, 5, 'Nĩ kana endwa maku mavonokw’e, Tangĩĩa na kw’oko kwaku kwa aũme, na ũitũsũngĩa.'),
('kam', 'PSA', 60, 6, 'Ngai nũneenete ũtheunĩ wake: Ngatana; Ngaaan’ya nthĩ ya Sekemu, na kũthima kyanda kya Sukothi.'),
('kam', 'PSA', 60, 7, 'Ngileati nĩ yakwa, o na Manase nĩ yakwa; Evalaimu nĩ ya ũsesea mũtwe wakwa; Yuta nĩyo ndata yakwa ya ũsumbĩ.'),
('kam', 'PSA', 60, 8, 'Moavi nĩ mbisũ yakwa ya kwĩthambĩa; Ngekya kĩatũ kyakwa ĩũlũ wa Etomu: Ũkĩlya wasya nũndũ wakwa, we Vilisitia.'),
('kam', 'PSA', 60, 9, 'Nũũ ũla wĩndwaa ndũanĩ nũmu? Nũũ ũla wĩndongoesya kũvika Etomu?'),
('kam', 'PSA', 60, 10, 'Tuue, we Ngai, ũla watwĩkisye ũtee? Na ndumaalanasya vamwe na nguthu sitũ, we Ngai.'),
('kam', 'PSA', 60, 11, 'Tũtetheesye kwa ĩla nthũ; Nĩkwĩthĩwa ũtethyo wa mũndũ nĩ wa mana.'),
('kam', 'PSA', 60, 12, 'Kwondũ wa Ngai tũkeekaa na ũkũmbaũ; Nĩkwĩthĩwa nĩwe ũla ũkakinyanga nthũ sitũ.'),
('kam', 'PSA', 61, 1, 'Ĩw’a ũkayo wakwa, ame Ngai; Ĩthukĩĩsye mboya yakwa.'),
('kam', 'PSA', 61, 2, 'Ngakwĩkaĩla kuma kĩtulunĩ kya nthĩ, yĩla ngoo yakwa ĩnĩũthelekela: Ndongoesya kũvika yĩla ĩvianĩ ĩtũlu kwĩ nyie.'),
('kam', 'PSA', 61, 3, 'Nĩkwĩthĩwa nue ũtwĩe wĩ wĩvitho wakwa, Mwako mũtũlu wa mũnyoolo wĩ vinya nũndũ wa mũmaitha.'),
('kam', 'PSA', 61, 4, 'Nakwa ngatũa ĩeemanĩ yaku tene na tene: Ngeevitha wĩvithonĩ wa nthwau syaku.'),
('kam', 'PSA', 61, 5, 'Nĩkwĩthĩwa we, Ngai, nĩwĩw’ĩte mawĩvĩto makwa: Nũnengete ũtiĩwa wa ala makĩaa syĩtwa yaku.'),
('kam', 'PSA', 61, 6, 'Ũkaasavya thayũ wa mũsumbĩ; Myaka yake ĩkeethĩwa ta ya nzyawa nyingĩ.'),
('kam', 'PSA', 61, 7, 'Akekala mbee wa Ngai kũvika tene na tene: Mwiĩe ũseo wĩ wendo na w’o, nĩ kana imwĩkalye.'),
('kam', 'PSA', 61, 8, 'Kwondũ wa ũu ngaina ngĩkumya syĩtwa yaku kũvika tene na tene, Nĩ kana nĩanĩasye mawĩvĩto makwa kĩla mũthenya.'),
('kam', 'PSA', 62, 1, 'Thayũ wakwa weteelaa ũkilĩtye Ngai e o weka: Ũtangĩĩo wakwa wumaa kwake.'),
('kam', 'PSA', 62, 2, 'No we weka ĩvia yakwa na ũtangĩĩo wakwa: Nĩwe mwako wakwa mũtũlu mũno wa mũnyoolo; ndikathingithĩka nongi.'),
('kam', 'PSA', 62, 3, 'Mũkekala ĩvinda yĩana ata mũkĩmũvithũkĩa mũndũ, Nĩ kana mũmũae, inyw’onthe, Ta ngũka mbeeku, o ta wiio ũũseesa?'),
('kam', 'PSA', 62, 4, 'Masũanĩaa o kũmũvalũkya kuma ũnenenĩ wake: Matanĩaa movũngũ; Maathimaa na makanyw’a moo, ĩndĩ nthĩnĩ maumanĩaa.'),
('kam', 'PSA', 62, 5, 'Thayũ wakwa, eteela Ngai e weka ũvindĩtye; Nĩkwĩthĩwa wĩkwatyo wakwa wĩ kwake.'),
('kam', 'PSA', 62, 6, 'No we weka ĩvia yakwa na ũtangĩĩo wakwa: Nĩwe mwako wakwa mũtũlu mũno wa mũnyoolo; ndikathingithĩka.'),
('kam', 'PSA', 62, 7, 'Ũtangĩĩo wakwa na ũnene wakwa wĩ kũla kwĩ Ngai: Ĩvia ya vinya wakwa, na wĩvitho wakwa, wĩ nthĩnĩ wa Ngai.'),
('kam', 'PSA', 62, 8, 'Mũĩkĩĩei mavinda onthe, inyw’ĩ andũ; Mũtulũĩlei ngoo syenyu: Ngai nĩwe wĩvitho witũ.'),
('kam', 'PSA', 62, 9, 'Vate ndĩi andũ mate ndaĩa nĩ mĩthũmũ, na andũ me ndaĩa nao nĩ ũvũngũ: Mathimwa ithiminĩ onthe makambata; Onthe nĩ avũthũ kũte mĩthũmũ.'),
('kam', 'PSA', 62, 10, 'Mũtikekwatye kũthĩn’ya, Na mũikekathĩĩe mbutanĩ: Ethĩwa mothwii makaingĩva, manyai kũlũlũmĩlya ngoo syenyu vo.'),
('kam', 'PSA', 62, 11, 'Ngai nũneenete ĩmwe, Kelĩ nĩneewie ũũ, Kana vinya nĩ wa Ngai.'),
('kam', 'PSA', 62, 12, 'O na ũseo wĩ wendo naw’o nĩ waku, we Mwĩaĩi; Nĩkwĩthĩwa ũnengae kĩla mũndũ kwĩanana na wĩa wake.'),
('kam', 'PSA', 63, 1, 'Ame Ngai, nue Ngai wakwa; ngakũmanthaa na kĩthing’ĩĩsyo: Ngoo yakwa nĩyĩw’aa waũni kwondũ waku, mwĩĩ wakwa wĩ na mea naku, Nĩ nthĩ nyũmũ na yĩ mĩnoo, kũla kũte manzĩ.'),
('kam', 'PSA', 63, 2, 'Kwondũ wa ũu nĩnĩkũsyaĩtye wĩ vala vandũ vatheu, None vinya waku na ũtheu mũtisu waku.'),
('kam', 'PSA', 63, 3, 'Nĩkwĩthĩwa ũseo waku wĩ wendo nĩ mũseo kwĩ thayũ, Ilomo syakwa ikakũtaĩa.'),
('kam', 'PSA', 63, 4, 'Kwondũ wa ũu ngakũtaĩaa o yila nĩĩkalaa thayũ: Ngookĩlasya moko makwa syĩtwanĩ yaku.'),
('kam', 'PSA', 63, 5, 'Ngoo yakwa ĩkavũnaa ta ĩnĩũvũnĩthw’a nĩ mũthungo na ũnou; Na kanyw’a wakwa ũkakũtaĩa na ilomo ndanu;'),
('kam', 'PSA', 63, 6, 'Yĩla nĩkũlilikanaa nĩ ũkomonĩ wakwa, Na kũsũanĩaa ũndũ waku mosyaĩĩsyonĩ ma ũtukũ.'),
('kam', 'PSA', 63, 7, 'Nũndũ wĩkalĩte wĩ mũtethya wakwa, Na ngatanĩaa muunyĩnĩ wa nthwau syaku.'),
('kam', 'PSA', 63, 8, 'Ngoo yakwa nĩkũatĩĩaa yĩ vakuvĩ: Kw’oko kwaku kwa aũme nĩkũndw’ĩĩkaa.'),
('kam', 'PSA', 63, 9, 'Ĩndĩ ala mamanthaa thayũ wakwa, mawanange, Makatheea kũndũ kwĩ nthĩnĩ wa nthĩ.'),
('kam', 'PSA', 63, 10, 'Makanenganwe ũvyũnĩ wĩ vinya: Makeethĩwa kĩanda kya mbĩwa.'),
('kam', 'PSA', 63, 11, 'Ĩndĩ mũsumbĩ akatanĩa Ngai: Kĩla mũndũ ũla wĩavaa nake akakathĩĩa; Nũndũ makanyw’a ma ala maneenaa movũngũ makatumw’a.'),
('kam', 'PSA', 64, 1, 'Ĩw’a wasya wakwa, ame Ngai, mũnyungunyĩsyonĩ wakwa: Sũvĩa thayũ wakwa ndikakĩe mũmaitha.'),
('kam', 'PSA', 64, 2, 'Mbithan’ya na ũsũanĩo wa nzama ya eki ma maĩ, Kĩtuu kya ala mekaa ũthũku;'),
('kam', 'PSA', 64, 3, 'Ala manoete nĩmĩ syoo ta ũvyũ, Na nĩmaeleelye mĩsyĩ yoo, nayo nĩ ndeto syĩ ũũ,'),
('kam', 'PSA', 64, 4, 'Nĩ kana mamwĩkye mĩsyĩ ũla mwĩanĩu me syĩmbithĩnĩ: Mamwĩkasya mĩsyĩ na kĩthũlũmũko, na matiũkĩa.'),
('kam', 'PSA', 64, 5, 'Nĩmeyĩkaa vinya ũndũnĩ ũthũku; Nĩmaneenaa ũndũ wa kũtea itei na kĩmbithĩ; Makasya, Nũũ ũla wĩsyona?'),
('kam', 'PSA', 64, 6, 'Nĩmamanthaa mothũku; Makyasya, Nĩtũminĩte kũmantha na kĩthing’ĩĩsyo; Na ũsũanĩo wa nthĩnĩ na ngoo ya kĩla mũndũ syĩ na moliku.'),
('kam', 'PSA', 64, 7, 'Ĩndĩ Ngai akamekya mĩsyĩ; Makokitwa na mũsyĩ kĩthũlũmũko.'),
('kam', 'PSA', 64, 8, 'Kwondũ wa ũu makalulutĩkw’a, nĩmĩ syoo ene ĩkeethĩwa ũndũ nao: Onthe ala mamonaa makathingithya mũtwe.'),
('kam', 'PSA', 64, 9, 'Na andũ onthe makakĩa; Na makatavan’ya wĩko wa Ngai, Na kũsũanĩa na ũĩ mwĩkĩle wake.'),
('kam', 'PSA', 64, 10, 'Ũla mũlũngalu akatanĩaa Yeova, na kwĩvitha nthĩnĩ wake; Na onthe alũngalu ngoonĩ makakathĩĩa.'),
('kam', 'PSA', 65, 1, 'Ndaĩa nĩkweteele ku Saioni, we Ngai; Na wĩvĩto ũkeanĩw’a kwaku.'),
('kam', 'PSA', 65, 2, 'We ũla wĩw’aa mboya, Mĩĩ yonthe ĩkooka kwaku.'),
('kam', 'PSA', 65, 3, 'Mothũku nĩmangĩlasya vinya: Ũkaekea mavĩtyo maitũ.'),
('kam', 'PSA', 65, 4, 'Nĩ mũathime mũndũ ũla ũmũnyuvĩte, na kũtuma akũthengeea, Nĩ kana atũae nthĩnĩ wa nza syaku: Tũkeanĩwa nĩ ũseo wa nyũmba yaku, Ĩkalũ yaku ĩtheu.'),
('kam', 'PSA', 65, 5, 'Ũkatũsũngĩa ũlũngalunĩ na maũndũ ma ũtĩsya, We Ngai wa ũtangĩĩo witũ, Nue wĩkwatyo wa itulu syonthe sya nthĩ, Na wa onthe ala me kũasa ũkanganĩ:'),
('kam', 'PSA', 65, 6, 'Ũla ũlũlũmĩlasya iĩma na vinya wake, Evotoete ũtonyi;'),
('kam', 'PSA', 65, 7, 'Ũla ũvindĩthasya kĩlitũko kya maũkanga, Kĩlitũko kya itulumo syamo, Na kĩtuu kya ngo sya andũ.'),
('kam', 'PSA', 65, 8, 'O na ala matũaa kũasa vyũ nĩmakĩaa mawonan’yo maku: Nũtumaa mawumaalĩlo ma kĩoko na wĩoo matana.'),
('kam', 'PSA', 65, 9, 'Nũmyũkĩaa nthĩ, na kũmĩnyithya, Nũmĩnoasya mũno; Ũsĩ wa Ngai nĩwusũĩte manzĩ: Nũmanengae lĩu wa mbaa ngetha, yĩla ũseũvĩtye nthĩ ta ũu.'),
('kam', 'PSA', 65, 10, 'Nũnyithasya mĩkao yayo na manzĩ maingĩ; Nĩwĩananasya kũndũ kũtũlu kwayo: Nũmyololoasya na mĩono ya mbua; Nũathimaa kũthongoosya kwayo.'),
('kam', 'PSA', 65, 11, 'Nũkunĩkĩlasya mwaka ngovia ya ũsumbĩ ya ũseo waku; Na kũla ũendelaa nĩkwĩtĩkangasya maũnou.'),
('kam', 'PSA', 65, 12, 'Isesi sya weũnĩ nĩsyĩtĩkangasya; Na iĩma nivotoetwe na ũtanu.'),
('kam', 'PSA', 65, 13, 'Isesi nivw’ĩkĩtwe nĩ ndĩthya sya mbũi na malondu; Myanda nayo nĩvw’ĩkĩtwe nĩ lĩu wa mbaa ngetha; Nĩsyũkĩlasya mawasya na ũtanu, o na nĩsinaa.'),
('kam', 'PSA', 66, 1, 'Ũkĩlĩlya Ngai wasya wa ũtanu, nthĩ yonthe:'),
('kam', 'PSA', 66, 2, 'Ina ndaĩa ya syĩtwa yake: Sũng’ũkya ndaĩa syake.'),
('kam', 'PSA', 66, 3, 'Mwĩe Ngai, Mawĩa maku kaĩ nĩ ma ũtĩsya! Kwondũ wa ũnene wa vinya waku amaitha maku makakwĩnyivĩasya.'),
('kam', 'PSA', 66, 4, 'Nthĩ yonthe ĩkakũthaitha, Na ũkwinĩa; Makaina maikumya syĩtwa yaku.'),
('kam', 'PSA', 66, 5, 'Ũkai, mwone mawĩa ma Ngai; Nake nĩ wa kũtĩsya mwĩkĩlenĩ wake kwa ana ma andũ.'),
('kam', 'PSA', 66, 6, 'Nĩwaalyũlile ũkanga watw’ĩka nthĩ nyũmũ; Nĩmaingie ũsĩ maendete na maũũ: Nĩkw’o twamũtanĩĩe.'),
('kam', 'PSA', 66, 7, 'Nũsumbĩkaa kwondũ wa ũtonyi wake tene na tene; Metho make nĩmasiasya i mbaĩ: Ala ang’endu matikenenevye.'),
('kam', 'PSA', 66, 8, 'Taĩai Ngai waitũ, inyw’ĩ ngo sya andũ, Na mũituma wasya wa kũtaĩwa kwake wĩw’ĩka;'),
('kam', 'PSA', 66, 9, 'Ũla wĩkalasya syuu sitũ syĩ thayũ, Na ndaekaa maũũ maitũ mathingithangw’e.'),
('kam', 'PSA', 66, 10, 'Nũndũ, we Ngai, nũtũoetye: Nũtũtatĩte, o tondũ vetha ũtatawa.'),
('kam', 'PSA', 66, 11, 'Nĩwatũetie kĩteinĩ; Nĩwatwaĩkisye mũio mũito inyunyunĩ sitũ.'),
('kam', 'PSA', 66, 12, 'Nĩwavĩtĩlye andũ ĩũlũ wa mĩtwe yaitũ; Nĩtwavĩtĩle mwakinĩ na manzĩnĩ; Ĩndĩ we nĩwatumaalilye vandũ va ũthwii.'),
('kam', 'PSA', 66, 13, 'Ngalika nyũmbanĩ yaku nĩ na nthembo ya kũvĩvw’a; Ngeanĩsya kwaku mawĩvĩto makwa,'),
('kam', 'PSA', 66, 14, 'Ala ilomo syakwa syaneenie, Na kanyw’a wakwa waneenie, yĩla naĩ thĩnanĩ.'),
('kam', 'PSA', 66, 15, 'Ngakũthembea nthembo sya kũvĩvw’a sya ila nou, Ũvani vamwe na ndũũme; Ngathembanĩsya tũsalũ twa mũew’a na mbũi.'),
('kam', 'PSA', 66, 16, 'Ũkai mwĩw’e, inyw’onthe ala mũkĩaa Ngai, Na ngatavan’ya ũndũ wĩkĩte ngoo yakwa.'),
('kam', 'PSA', 66, 17, 'Nĩnamwĩkaĩlile na kanyw’a wakwa, Na nĩwaneneviw’e nĩ ũĩmĩ wakwa.'),
('kam', 'PSA', 66, 18, 'Ethĩwa ngeetĩkĩlaa ũthũku ngoonĩ yakwa, Mwĩaĩi ndakew’a:'),
('kam', 'PSA', 66, 19, 'Ĩndĩ nĩ w’o Ngai nĩwĩw’ĩte; Nĩwĩthukĩĩĩtye wasya wa kũvoya kwakwa.'),
('kam', 'PSA', 66, 20, 'Ngai nataĩwe, Ũla ũtaaveta ũtee mboya yakwa, Kana ũseo wake wĩ wendo kwakwa.'),
('kam', 'PSA', 67, 1, 'Ngai natwĩw’ĩae tei, na kũtũathimaa, Na kũtũtisĩasya ũthyũ wake;'),
('kam', 'PSA', 67, 2, 'Nĩ kana nzĩa yaku ĩmanyĩke kũũ nthĩ, Ũtangĩĩo waku katĩ wa mbaĩ syonthe.'),
('kam', 'PSA', 67, 3, 'Ngo sya andũ nikũtaĩe, we Ngai; Ngo syonthe sya andũ nikũtaĩe.'),
('kam', 'PSA', 67, 4, 'I mbaĩ syĩthĩwe na mũyo na kwina ũndũ wa ũtanu; Nũndũ ũkasilĩla ngo sya andũ na ũlũngalu, Na kũsumbĩkaa mbaĩ ila syĩ ĩũlũ wa nthĩ.'),
('kam', 'PSA', 67, 5, 'Ngo sya andũ nikũtaĩe, we Ngai; Ngo syonthe sya andũ nikũtaĩe.'),
('kam', 'PSA', 67, 6, 'Nthĩ nĩyingĩvĩtye ũsyao wayo: Ngai, o Ngai waitũ, akatũathima.'),
('kam', 'PSA', 67, 7, 'Ngai akatũathima; Na itulu syonthe sya nthĩ ikamũkĩaa.'),
('kam', 'PSA', 68, 1, 'Ngai nĩokĩle, amaitha make nĩmanyaĩĩkw’e; Ala mamũmenaa nao nĩmakĩe mbee wake.'),
('kam', 'PSA', 68, 2, 'O tondũ syũki ĩlũlũngĩlaw’a, o ta ũu malũngye: O tondũ ĩseso yĩtwekaa vala ve mwaki, O ta ũu ala athũku maae mbee wa Ngai.'),
('kam', 'PSA', 68, 3, 'Ĩndĩ ala alũngalu methĩwe na mũyo; nĩmatane mbee wa Ngai: Ĩĩ, matane na mũyo.'),
('kam', 'PSA', 68, 4, 'Mwinĩei Ngai, inai mũkĩkumya syĩtwa yake: Seũvyai lelũ ũndũ wa ũla ũendaa akuĩlwe malatanĩ; Syĩtwa yake nĩ Yeova; tanai mbee wake.'),
('kam', 'PSA', 68, 5, 'Ĩthe wa la makw’ĩĩwe nĩ aaĩthe, na mũsili wa aka ndiwa, Nĩ Ngai e ũtũonĩ wake mũtheu.'),
('kam', 'PSA', 68, 6, 'Ngai nũtumaa ala me ĩvou matũaa nyũmba: Nake nĩumaalasya ala ove ũunĩkonĩ; Ĩndĩ ala ang’endu matũaa nthĩ mbenzeku.'),
('kam', 'PSA', 68, 7, 'We Ngai, yĩla, waumaalile wĩ mbee wa andũ maku, Yĩla wavĩtĩle weũnĩ;'),
('kam', 'PSA', 68, 8, 'Nthĩ nĩyatetemie, O na matu metĩkya mbua Ngai e vo: Sinai kĩya nakyo nĩkyatetemie Ngai e vo, Ngai wa Isilaeli.'),
('kam', 'PSA', 68, 9, 'Naku, we Ngai, nĩwaetie mbua mbingĩ, Yĩla ũtiĩwa waku waĩ na mĩnoo nĩwoolũlũmĩlye.'),
('kam', 'PSA', 68, 10, 'Ũmbano waku nĩwatwĩe kw’o: Naku, Ngai, kwondũ wa ũseo waku nĩwaseũvisye ũndũ wa ngya.'),
('kam', 'PSA', 68, 11, 'Mwĩaĩi nũnenganae ĩla ndeto: Aka ala manyaĩĩkasya ũvoo nĩ nguthu nene.'),
('kam', 'PSA', 68, 12, 'Asumbĩ ma ita nĩmakĩaa, nĩmakĩaa; Na mũndũ mũka ũla wĩkalaa mũsyĩ nũaanasya mũtavo.'),
('kam', 'PSA', 68, 13, 'Yĩla mũũkoma syengonĩ sya malondu, Nĩ ta nthwau sya ĩvũĩ ivw’ĩkĩtwe vetha, Na nzĩa syayo thaavu wĩ ĩuuku.'),
('kam', 'PSA', 68, 14, 'Yĩla Mwene Vinya W’onthe wanyaĩĩkĩsye asumbĩ kw’o, Kwailyĩ ta yĩla kuaa ĩa Nzalimoni.'),
('kam', 'PSA', 68, 15, 'Nĩ kĩĩma kya Ngai kĩĩma kya Mbasani; Nĩ kĩĩma kĩtũlu kĩĩma kya Mbasani.'),
('kam', 'PSA', 68, 16, 'Nũndũ wa kĩ mũũkĩnda na itho, inyw’ĩ iĩma ndũlu, Kĩĩma kĩla Ngai wendete kĩthĩwe ũtũo wake? Ĩĩ, Yeova akakĩtũaa tene na tene.'),
('kam', 'PSA', 68, 17, 'Makasya ma kaũ ma Ngai nĩ ngili mĩongo ĩlĩ, o ngili na ngili: Mwĩaĩi e katĩ woo, o ta ku Sinai, nthĩnĩ wa vala vandũ vatheu.'),
('kam', 'PSA', 68, 18, 'Nĩwambatĩte ĩũlũ, nũtwaĩte andũ me atave; Nĩwosete mĩthĩnzĩo andũnĩ, Ĩĩ, o na kuma kwa ala ang’endu, nĩ kana Yeova Ngai atonye kũtũaa namo.'),
('kam', 'PSA', 68, 19, 'Nataĩwe Yeova, ũla ũkuaa mũio witũ kĩla mũthenya, O Ngai ũla ũtangĩĩo witũ.'),
('kam', 'PSA', 68, 20, 'Ngai kwitũ nĩ Ngai wa movonokyo; Kũvonokya kĩkw’ũnĩ nĩ kwa Yeova ũla Mwĩaĩi.'),
('kam', 'PSA', 68, 21, 'Ĩndĩ Ngai akaatũa mũtwe wa amaitha make, Lolotya wĩ nzw’ĩĩ wa ũla ũendeeaa ivĩtyonĩ yake.'),
('kam', 'PSA', 68, 22, 'Mwĩaĩi nĩwaisye, Ngaete ĩngĩ kuma Mbasani, Ngamaete ĩngĩ kuma syũngũnĩ sya ũkanga;'),
('kam', 'PSA', 68, 23, 'Nĩ kana ũmakinyange, ũlikitye ũnyaĩĩ waku nthakamenĩ, Nĩ kana nĩmĩ sya ngitĩ syaku syĩthĩwe na kĩanda kyasyo kuma kwa amaitha maku.'),
('kam', 'PSA', 68, 24, 'Nĩmonete mĩendele yaku, we Ngai, O mĩendele ya Ngai wakwa, Mũsumbĩ wakwa, nthĩnĩ wa vala vandũ vatheu.'),
('kam', 'PSA', 68, 25, 'Aini nĩmatongoisye mbee, aingi ma mbeve nĩmaatĩĩe, Katĩ wamo eĩtu makĩinga tũthembe.'),
('kam', 'PSA', 68, 26, 'Taĩai Ngai maũmbanonĩ, O Mwĩaĩi, inyw’ĩ ma mbuluti ya Isilaeli.'),
('kam', 'PSA', 68, 27, 'E vo Mbenyamini mũnini mũsumbĩki woo, Anene me mbee ũsumbĩnĩ ma Yuta na nzama yoo, Anene me mbee ũsumbĩnĩ ma Nzevuluni, anene me mbee ũsumbĩnĩ ma Navitali.'),
('kam', 'PSA', 68, 28, 'Ngai waku nĩwĩaĩĩte vinya waku: Ĩkĩa vinya, ame Ngai, ũndũ ũla weekie kwondũ witũ.'),
('kam', 'PSA', 68, 29, 'Nũndũ wa ĩkalũ yaku ku Yelusaleme Asumbĩ makakũetee mĩthĩnzĩo.'),
('kam', 'PSA', 68, 30, 'Kan’ya nyamũ ya mĩanginĩ, Wingĩ wa nzaũ, vamwe na tũsaũ twa ngo sya andũ, Kĩla ũmwe enyivye akyumasya ilungu sya vetha: Nũnyaĩkĩĩtye ngo sya andũ ila syendeeaw’a nĩ kaũ.'),
('kam', 'PSA', 68, 31, 'Anene me mbee ũsumbĩnĩ makauma Misili; Ethiovia ĩkeekalaata kũmũtambũũkĩsya Ngai moko mayo.'),
('kam', 'PSA', 68, 32, 'Mwinĩei Ngai, inyw’ĩ mosumbĩ ma nthĩ; Inai mũkĩkumya Mwĩaĩi;'),
('kam', 'PSA', 68, 33, 'Ũla ũendaa akuĩtwe nĩ ĩtu ya matu, ala ma tene; Sisya, nĩwumasya wasya wake, wasya wĩ ũtonyi.'),
('kam', 'PSA', 68, 34, 'Mũwetei Ngai vinya: Ũnene wake wĩ ĩũlũ wa Isilaelĩ, Na vinya wake wĩ matunĩ.'),
('kam', 'PSA', 68, 35, 'Ame Ngai, wĩ wa ũtĩsya wĩ kũndũnĩ kwaku kũtheu: Ngai wa Isilaeli, nũnengae andũ make vinya na ũtonyi. Ngai nataĩwe.'),
('kam', 'PSA', 69, 1, 'Ndangĩĩa, ame Ngai: Nũndũ manzĩ nĩmalikile ngoonĩ yakwa.'),
('kam', 'PSA', 69, 2, 'Nĩlikĩte mũtondonĩ mũliku, vala vate vandũ va kũũngama: Nĩlikĩte manzĩnĩ maliku, vala manzĩ maingĩ meũvĩtĩla ĩũlũ wakwa.'),
('kam', 'PSA', 69, 3, 'Nĩ na mĩnoo ũndũ wa kũĩa kwakwa; mũmeo wakwa nĩũmie: Metho makwa nĩmeũseekea yĩla nĩeteele Ngai wakwa.'),
('kam', 'PSA', 69, 4, 'Ala mamenete vate kĩtumi nĩ aingĩ kwĩ nzw’ĩĩ sya mũtwe wakwa: Ala mekwenda kũmbeta, nũndũ nĩ amaitha makwa ma ũvũngũ, me na ũtonyi: Kĩla ndaosa mũvaka nĩtũnge.'),
('kam', 'PSA', 69, 5, 'We Ngai, nĩwĩsĩ ũtumanu wakwa; Na naĩ syakwa ti mbithĩku kwaku.'),
('kam', 'PSA', 69, 6, 'Ala makweteelaa maikaasonokw’e kwondũ wakwa, ame Mwĩaĩi Yeova wa nguthu: Ala makũmanthaa matikaanangĩwe ndaĩa kwondũ wakwa, we Ngai wa Isilaeli.'),
('kam', 'PSA', 69, 7, 'Nĩkwĩthĩwa nĩnĩkuĩte kĩvũthya kwondũ waku; Nthoni nivw’ĩkĩte ũthyũ wakwa.'),
('kam', 'PSA', 69, 8, 'Nĩnĩtw’ĩkĩte mũeni kwa ana‐a‐asa makwa, Na mũndũ wa nthĩ ĩngĩ kwa syana sya mwaitũ.'),
('kam', 'PSA', 69, 9, 'Nũndũ kĩwĩu kya nyũmba yaku nĩkĩndĩte; Na ivũthya sya ala makũvũthasya nĩsyambalũkĩle.'),
('kam', 'PSA', 69, 10, 'Yĩla naĩie, na kũsilĩla ngoo yakwa kwondũ wa kũtĩĩa kũya, Kũu kwatw’ĩkie kũvũthw’a kwakwa.'),
('kam', 'PSA', 69, 11, 'Yĩla neevw’ĩkie ngũa ya makunia, Natw’ĩkie wa kũvũthw’a nĩmo.'),
('kam', 'PSA', 69, 12, 'Ala mekalaa mbingĩlonĩ nĩmaneenaa ũndũ wakwa; Nakwa nĩ wathi wa athengi.'),
('kam', 'PSA', 69, 13, 'Ĩndĩ ngalĩ ĩ yakwa, mboya yakwa no kwaku, ame Yeova, ĩvindanĩ yĩla yĩtĩkĩlĩtwe: Ame Ngai, ũseonĩ waku wĩ wendo mwingĩ, Nzũngĩa kwondũ wa w’o wa ũtangĩĩo waku.'),
('kam', 'PSA', 69, 14, 'Ndangĩĩa nume mũtondonĩ, ndikathelekelye: Nĩtangĩĩwe kuma kwa ala mamenaa, na kuma manzĩnĩ maliku.'),
('kam', 'PSA', 69, 15, 'Ndũkaeke manzĩ maingĩ mambw’ĩke, Kana kyũngũ kĩmelye vyũ; Na ndũkaeke yĩla ĩima yĩndumĩsye kanyw’anĩ wayo.'),
('kam', 'PSA', 69, 16, 'Nzũngĩa, ame Yeova; nũndũ ũseo waku wĩ wendo nĩ mũseo: Kwĩanana na wingĩ wa matei maku mololo ĩnthyũũĩe.'),
('kam', 'PSA', 69, 17, 'Ndũkamũvithe mũthũkũmi waku ũthyũ waku; Nũndũ nĩ thĩnanĩ; nzũngĩa mĩtũkĩ.'),
('kam', 'PSA', 69, 18, 'Mĩthengeee ngoo yakwa, na kũmyovosya: Mbovosya ũndũ wa amaitha makwa.'),
('kam', 'PSA', 69, 19, 'Nĩwĩsĩ kũvũthw’a kwakwa, na nthoni syakwa, na kwanangĩwa ndaĩa kwakwa: Nthũ syakwa syonthe syĩ mbee waku.'),
('kam', 'PSA', 69, 20, 'Kĩvũthya nĩkĩtũlĩte ngoo yakwa; na nĩnusũĩtwe nĩ kĩmako: Na nĩnamanthie amwe ma kwĩw’ĩa tei, ĩndĩ vatyaĩ ũmwe; Na akiakisya, ĩndĩ ndyaaona ũmwe.'),
('kam', 'PSA', 69, 21, 'O na nĩmanengie nyongo yĩthĩwe lĩu wakwa; Na ngĩw’a waũni nĩmanengie siki wa ũnyw’a.'),
('kam', 'PSA', 69, 22, 'Mesa yoo mbee wamo nĩtw’ĩke mũkwa; Na yĩla me na mũuo, naw’o ũtw’ĩke kĩtei.'),
('kam', 'PSA', 69, 23, 'Metho moo matulye kĩvindu, nĩ kana matikatonye kwona; Noituma inyunyu syoo itetema mavinda onthe.'),
('kam', 'PSA', 69, 24, 'Onosya ũthilĩku waku ĩũlũ wamo, Na wai wa ũthatu waku ũmakwate.'),
('kam', 'PSA', 69, 25, 'Ũtũo woo nĩwĩthĩwe mũthei; Mũndũ o na wĩva ndakaatũe maeemanĩ moo.'),
('kam', 'PSA', 69, 26, 'Nũndũ nĩmeũmũthĩn’ya ũla ũkũnĩtwe nue; Na nĩmeũneena ũndũ wa woo wa ala mokitĩtwe nue.'),
('kam', 'PSA', 69, 27, 'Ongeleela ũthũku ũthũkunĩ woo; Na ndũkamaeke malike ũlũngalunĩ waku.'),
('kam', 'PSA', 69, 28, 'Mavutwe ĩvukunĩ ya thayũ, Na matikaandĩkwe vamwe na alũngalu.'),
('kam', 'PSA', 69, 29, 'Ĩndĩ nyie nĩ ngya na nĩ na woo: Ũtangĩĩo waku, ame Ngai, ũmbũkĩlye ĩũlũ.'),
('kam', 'PSA', 69, 30, 'Ngataĩa syĩtwa ya Ngai na wathi, Na ngamũnenevya na mũvea.'),
('kam', 'PSA', 69, 31, 'Na ũu ũkamũtan’ya Yeova kũvĩtũka ng’ombe, Kana kasalũ ka mũew’a kala ke na mbya na mavũngũ.'),
('kam', 'PSA', 69, 32, 'Ala auu nĩmonete ũu, na nĩmeũtana: Inyw’ĩ ala mũmanthaa Ngai, ngoo syenyu syĩkale thayũ.'),
('kam', 'PSA', 69, 33, 'Nũndũ Yeova nĩwĩw’aa athĩni, Na ndavũthasya ovwa make.'),
('kam', 'PSA', 69, 34, 'Ĩtu na nthĩ nimũtaĩe, Maũkanga, na kĩla kĩndũ kĩendaa nthĩnĩ wamo.'),
('kam', 'PSA', 69, 35, 'Nũndũ Ngai akatangĩĩa Saioni, na kwaka ndũa sya Yuta; Na makekala kw’o, na ĩkeethĩwa ng’ũndũ yoo.'),
('kam', 'PSA', 69, 36, 'O na ũsyao wa athũkũmi make ũkamĩtiĩwa; Na ala mendaa syĩtwa yake makekala kw’o.'),
('kam', 'PSA', 70, 1, 'Ĩkalaate, ame Ngai, ũmbonokye; Ĩkalaate ũndethye, ame Yeova.'),
('kam', 'PSA', 70, 2, 'Masonokw’e na kũthokoanw’a Ala mamanthaa thayũ wakwa: Matũngwe na ĩtina na kwanangĩwa ndaĩa Ala matanaa ngĩkwa naĩ.'),
('kam', 'PSA', 70, 3, 'Matũngwe na ĩtina nũndũ wa nzonokan’yo syoo Ala maasya, Aa, aa.'),
('kam', 'PSA', 70, 4, 'Onthe ala makũmanthaa matane na kwĩw’aa mũyo nthĩnĩ waku; Na ala mendaa ũtangĩĩo waku maneenae mavinda onthe, Ngai nanenevw’e.'),
('kam', 'PSA', 70, 5, 'Ĩndĩ nyie nĩ ngya na mũthĩni; Ĩkalaate wũke vala nĩĩ, ame Ngai: Nue mũtethya wakwa na mũvonokya wakwa; Ame Yeova, ndũketeele.'),
('kam', 'PSA', 71, 1, 'Nĩvithaa nthĩnĩ waku, ame Yeova: Ndũkaandeke nĩsonokw’e o na ĩndĩĩ.'),
('kam', 'PSA', 71, 2, 'Mbonokya kwondũ wa ũlũngalu waku, na kũndangĩĩa: Tea kũtũ kwaku ũmbĩw’e, na ũindangĩĩa:'),
('kam', 'PSA', 71, 3, 'Ĩthĩwa kwakwa ĩvia ya kũtũa, vala ndonya kũendaa mavinda onthe: Nĩwĩaĩte kũndangĩĩa; Nũndũ nue ĩvia yakwa na ngome yakwa.'),
('kam', 'PSA', 71, 4, 'Mbonokya, ame Ngai wakwa, kuma kw’okonĩ kwa ũla mũthũku, Kuma kw’okonĩ kwa mũndũ ũte mũlũngalu na mwai.'),
('kam', 'PSA', 71, 5, 'Nũndũ nue wĩkwatyo wakwa, we Mwĩaĩi Yeova: Nue ũla naĩkĩĩaa kuma wana wakwa.'),
('kam', 'PSA', 71, 6, 'Nĩnĩtw’ĩĩkĩtwe nue o kuma ĩvunĩ; Nue ũla wanumisye ĩvunĩ ya mwaitũ: Kũkũtaĩa kwakwa kũkeethĩwa mavinda onthe.'),
('kam', 'PSA', 71, 7, 'Nĩĩlyĩ ta ũseng’yo kwa aingĩ; Ĩndĩ nue wĩvitho wakwa wĩ vinya.'),
('kam', 'PSA', 71, 8, 'Kanyw’a wakwa ũkausũwa nĩ ũkũtaĩa, Na ũkũkatha mũthenya w’onthe.'),
('kam', 'PSA', 71, 9, 'Ndũkaambĩkye kũasa ĩvinda ya ũkũu; Ndũkaandie yĩla vinya wakwa wĩthela.'),
('kam', 'PSA', 71, 10, 'Nũndũ amaitha makwa maneenaa ũndũ wakwa; Na ala moveeasya thayũ wakwa masũanĩaa vamwe,'),
('kam', 'PSA', 71, 11, 'Makyasya, Ngai nũmũtiĩte: Atĩĩai na mũimũkwata; nũndũ vati wa kũvonokya.'),
('kam', 'PSA', 71, 12, 'Ame Ngai, ndũkethĩwe kũasa nakwa; Ame Ngai wakwa, ĩkalaate ũndethye.'),
('kam', 'PSA', 71, 13, 'Nisonokw’e na kũminwa ila nthũ sya thayũ wakwa; Nĩmavw’ĩkwe nĩ kũvũthw’a na kwanangĩwa ndaĩa ala mamanthaa kũmbĩka naĩ.'),
('kam', 'PSA', 71, 14, 'Ĩndĩ ngeethĩawa na wĩkwatyo mavinda onthe, Na ngakũtaĩa mbee na mbee.'),
('kam', 'PSA', 71, 15, 'Kanyw’a wakwa ũkatavanasya ũlũngalu waku, Na ũtangĩĩo waku mũthenya w’onthe; Nũndũ ititalĩkya.'),
('kam', 'PSA', 71, 16, 'Ngooka nĩ na meko me ũtonyi ma Mwĩaĩi Yeova: Ngaweta ũlũngalu waku, waku wĩ w’oka.'),
('kam', 'PSA', 71, 17, 'Ame Ngai, nũmanyĩĩtye kuma wana wakwa; Na kũvika yu nĩnĩtavanĩtye mawĩa maku ma ũseng’ya.'),
('kam', 'PSA', 71, 18, 'Ĩĩ, o na yĩla ngakũa na mũtwe wĩ mbuĩ, ame Ngai, ndũkaandie, Kũvika ngethĩwa nĩtavan’ya vinya waku nzyawanĩ ĩla yũkĩte, Ũtonyi waku kwa kĩla ũmwe ũla ũkoka.'),
('kam', 'PSA', 71, 19, 'O na ũlũngalu waku, we Ngai, wĩ ĩũlũ mũno; We ũla wĩkĩte maũndũ manene, We Ngai, nũũ ũilyĩ taku?'),
('kam', 'PSA', 71, 20, 'We, ũla ũtwonetye mathĩna maingĩ na manene, Ũkatũthayũũkya ĩngĩ, Na kũtumya ĩngĩ molikunĩ ma nthĩ.'),
('kam', 'PSA', 71, 21, 'Ongeleela ũnene wakwa, Na ĩthyũũe ĩngĩ na kũngiakisya.'),
('kam', 'PSA', 71, 22, 'Ngakũtaĩa na kĩnanda, O w’o waku, we Ngai wakwa: Ngaina ngĩũkumya na mbeve, We Ũla Mũtheu wa Isilaeli.'),
('kam', 'PSA', 71, 23, 'Ilomo syakwa ikookĩlya wasya wa ũtanu yĩla nĩinaa ngĩũkumya; Na ngoo yakwa, ĩla wovoetye.'),
('kam', 'PSA', 71, 24, 'Ũĩmĩ wakwa naw’o ũkaneenaa ũndũ wa ũlũngalu waku mũthenya w’onthe; Nũndũ nĩmasonoketw’e, nũndũ nĩmathokoanĩtw’e, ala mamanthaa kũmbĩka naĩ.'),
('kam', 'PSA', 72, 1, 'Nenga mũsumbĩ motwi maku, ame Ngai, Na mwana wa mũsumbĩ ũlũngalu waku.'),
('kam', 'PSA', 72, 2, 'Akasilanasya andũ maku na ũlũngalu, Na ngya syaku na sila wa katĩ.'),
('kam', 'PSA', 72, 3, 'Iĩma ikamaeteae andũ mũuo, Na tũlĩma natw’o, kwondũ wa ũlũngalu,'),
('kam', 'PSA', 72, 4, 'Akasilanasya ngya sya andũ, Akatangĩĩa syana sya athĩni, Na kũmũtilanga ilungu ũla ũthĩnasya.'),
('kam', 'PSA', 72, 5, 'Makaũkĩaa o yĩla syũa yĩĩkalaa, O na mwei naw’o, mosyaanĩonĩ onthe.'),
('kam', 'PSA', 72, 6, 'Akatheea ta mbua nyekinĩ mbenge, Ta mĩono ya mbua ĩla ĩnyithasya nthĩ.'),
('kam', 'PSA', 72, 7, 'Mĩthenyanĩ yake ala alũngalu makaaĩlaa, Na kũkeethĩwa mũuo mwingĩ, kũvika mwei ndũkethĩwa ĩngĩ.'),
('kam', 'PSA', 72, 8, 'Nake akasumbĩka kuma ũkanga kũvika ũkanga, Na kuma ũla Ũsĩ kũvika itulunĩ sya nthĩ.'),
('kam', 'PSA', 72, 9, 'Ala matũaa weũnĩ makainama mbee wake; Na amaitha make makanyenya kĩtoo.'),
('kam', 'PSA', 72, 10, 'Asumbĩ ma Talisisi na ma ithama makaumya koti: Asumbĩ ma Sieva na Seva makaumya mĩthĩnzĩo.'),
('kam', 'PSA', 72, 11, 'Ĩĩ, asumbĩ onthe makavalũka mbee wake; Mbaĩ syonthe ikamũthũkũma.'),
('kam', 'PSA', 72, 12, 'Nũndũ akavonokasya mũthĩni yĩla wĩkayaa, Na ngya, ĩla ĩte mũtethya.'),
('kam', 'PSA', 72, 13, 'Akeew’ĩa tei ngya na athĩni, Na mathayũ ma athĩni akamatangĩĩa.'),
('kam', 'PSA', 72, 14, 'Akoovosya mathayũ moo kuma thĩnanĩ na ũng’endunĩ; Na nthakame yoo ĩkeethĩwa yĩ vata mũno methonĩ make:'),
('kam', 'PSA', 72, 15, 'Na makekala thayũ; nake akaolelwa thaavu wa Sieva: Na andũ makamũvoyeaa mavinda onthe; Makamũathimaa mũthenya w’onthe.'),
('kam', 'PSA', 72, 16, 'Kũkeethĩwa lĩu mwingĩ mũno wa mbaa ngetha nthĩ iĩmanĩ ĩũlũ; Ũsyao wa vo ũkathingithĩka ta Levanoni: Na ala me ndũanĩ makaaĩla ta nyeki sya nthĩ.'),
('kam', 'PSA', 72, 17, 'Syĩtwa yake yĩkekalaa tene na tene; Syĩtwa yake yĩkekalaa o yĩla syũa yĩtũaa: Na andũ makaathimwa nthĩnĩ wake; Mbaĩ syonthe ikamwĩtaa mũtanu.'),
('kam', 'PSA', 72, 18, 'Nataĩwe Yeova Ngai, Ngai wa Isilaeli, Ũla wĩkaa maũndũ ma ũseng’ya weka:'),
('kam', 'PSA', 72, 19, 'Na syĩtwa yake ĩtheu yĩtaĩwe tene na tene; Na nthĩ yonthe nĩyusũwe nĩ ũtheu mũtisu wake. Ameni, na Ameni.'),
('kam', 'PSA', 72, 20, 'Mboya sya Ndaviti mwana wa Yese nĩsyathela.'),
('kam', 'PSA', 73, 1, 'Vate ndĩi Ngai nĩ mũseo kwa Isilaeli, O kwa ala atheu ngoo.'),
('kam', 'PSA', 73, 2, 'Ĩndĩ ngalĩ ĩ yakwa, maũũ makwa maĩ vakuvĩ kwathũka; Matambya makwa maĩ vakuvĩ kũtendelũka.'),
('kam', 'PSA', 73, 3, 'Nũndũ naĩ na kĩwĩu kwondũ wa ala me na wĩnenevyo, Yĩla noonie kũunĩka kwa ala athũku.'),
('kam', 'PSA', 73, 4, 'Nũndũ vati mawoo kĩkw’ũnĩ kyoo; Ĩndĩ vinya woo nũlũmĩte.'),
('kam', 'PSA', 73, 5, 'Mati thĩnanĩ ta andũ angĩ; O na matinyamaw’a ta andũ angĩ.'),
('kam', 'PSA', 73, 6, 'Kwondũ wa ũu ngathĩĩo nĩ ta mũnyoo ngingonĩ syoo; Ũng’endu nũmavw’ĩkaa o ta ngũa.'),
('kam', 'PSA', 73, 7, 'Metho moo nĩmaumĩlĩte nĩ kũnoa: Kĩla me nakyo nĩ kingĩ kũthonoka ũndũ ngoo ĩtonya kwenda.'),
('kam', 'PSA', 73, 8, 'Nĩmakaakaanasya, na kũneena me ũthũkunĩ kũthĩn’ya: Nĩmaneenaa na mĩtũlyo.'),
('kam', 'PSA', 73, 9, 'Nĩmaiĩte makanyw’a moo matunĩ, Na nĩmĩ syoo nĩsyangangaa nthĩ.'),
('kam', 'PSA', 73, 10, 'Kwondũ wa ũu andũ make nĩmasyokaa vaa: Na manzĩ ma kĩkombe kyusũu nĩmaminawa nĩo.'),
('kam', 'PSA', 73, 11, 'Na measya, Ngai esĩ ata? Na ve ũmanyi nthĩnĩ wa Ũla Wĩ Ĩũlũ wa Onthe?'),
('kam', 'PSA', 73, 12, 'Sisya, aa nĩ ala athũku; Na, nũndũ mauĩtye mavinda onthe, nĩmongelelaa ũthwii.'),
('kam', 'PSA', 73, 13, 'Vate ndĩi nĩtheetye ngoo yakwa mana, Na kũthambya moko makwa na ũtheu;'),
('kam', 'PSA', 73, 14, 'Nũndũ mũthenya w’onthe nĩkalaa ngĩthĩnw’a, Na kũkũnwa kĩla kĩoko.'),
('kam', 'PSA', 73, 15, 'Kethĩwa nĩnaneenie, Nganeena ũu; Sisya, nĩthĩwa nĩkengete na ũĩ nzyawa ya ana maku.'),
('kam', 'PSA', 73, 16, 'Yĩla nasũanĩe ũndũ ndonya kũmanya ũndũ ũũ, Kwaĩ thĩna kwakwa;'),
('kam', 'PSA', 73, 17, 'Kũvika yĩla nalikile vala vandũ vatheu va Ngai, Na kũsũanĩa mũminũkĩlyo woo.'),
('kam', 'PSA', 73, 18, 'Vate ndĩi nũmaiaa kũndũ kũtendeu; Nũmekasya wanangĩkonĩ.'),
('kam', 'PSA', 73, 19, 'Kaĩ nĩmatw’ĩkĩte athei kavinda ka kũvenya! Nĩmameletwe vyũ nĩ motĩsyo.'),
('kam', 'PSA', 73, 20, 'O ta ndoto yĩla mũndũ wĩamũka, No ta ũu, we Mwĩaĩi, yĩla wĩũkĩla, ũkavũthya mũvw’ano woo.'),
('kam', 'PSA', 73, 21, 'Nũndũ thayũ wakwa nĩweew’ĩthiw’e woo, Nakwa natonywa ngoonĩ yakwa:'),
('kam', 'PSA', 73, 22, 'Naĩ mũng’endu, na mũtumanu; Nailyĩ nyamũ mbee waku.'),
('kam', 'PSA', 73, 23, 'Ĩndĩ o na ũu w’onthe nĩ naku mavinda onthe: Nũngwatĩte kw’oko kwakwa kwa aũme.'),
('kam', 'PSA', 73, 24, 'Ũkandongoeasya na ũtao waku, Na ĩtina ũimbosa ũtheunĩ.'),
('kam', 'PSA', 73, 25, 'Nĩ naũ ĩtunĩ ate o we? Na vati ũmwe kũũ nthĩ ũla nĩmwendaa ate o we.'),
('kam', 'PSA', 73, 26, 'Mwĩĩ wakwa na ngoo yakwa nithelaa vinya; Ĩndĩ Ngai nĩ vinya wa ngoo yakwa na kĩanda kyakwa tene na tene.'),
('kam', 'PSA', 73, 27, 'Nũndũ, sisya, ala me kũasa naku makaaa: Nĩwanangĩte onthe ala mekaa ũmalwaya, makĩũtia.'),
('kam', 'PSA', 73, 28, 'Ĩndĩ nĩ ũseo kwakwa kũthengeea Ngai: Nĩnĩtw’ĩte Mwĩaĩi Yeova wĩvitho wakwa, Nĩ kana nĩtavanasye ũndũ wa mawĩa maku onthe.'),
('kam', 'PSA', 74, 1, 'Ame Ngai, nũndũ wa kĩ ũtwĩkĩtye ũtee tene na tene? Nũndũ wa kĩ ũthatu waku ũtoeesye syũki malondu ma ĩĩthya yaku?'),
('kam', 'PSA', 74, 2, 'Lilikana ũmbano waku, ũla wathooie tene, Ũla woovoetye wĩthĩwe mbaĩ ya ũtiĩwa waku; Kĩĩma kya Saioni, kĩla watwĩe.'),
('kam', 'PSA', 74, 3, 'Kinyangĩlya maũũ maku moombokunĩ ma mavinda onthe, Ũthũku w’onthe ũla mũmaitha wĩkĩte nthĩnĩ wa vala vandũ vatheu.'),
('kam', 'PSA', 74, 4, 'Nthũ syaku nilumĩte ũmbanonĩ waku; Nĩmaũngamĩtye movano moo ta mawonan’yo.'),
('kam', 'PSA', 74, 5, 'Nĩmoonekaa ta andũ ala mookĩlĩlye Kĩkuthu kya mĩtĩ mathoka.'),
('kam', 'PSA', 74, 6, 'O na yu wĩa w’onthe wa kwasũvya wa vo Nĩmanangaa na kathoka na syĩiva.'),
('kam', 'PSA', 74, 7, 'Nĩmakwatĩtye vandũ vaku vatheu mwaki; Nĩmavukĩtye ũtũo wa syĩtwa yaku ũndũ wa kũwĩkya nthĩ.'),
('kam', 'PSA', 74, 8, 'Nĩmaisye ngoonĩ syoo, Twanangei syonthe vyũ: Nĩmavĩvĩtye masinakoke onthe ma Ngai ĩ nthĩ.'),
('kam', 'PSA', 74, 9, 'Tũtyonaa movano maitũ: Kũti mwathani ĩngĩ; O na kũti ũmwe katĩ waitũ ũla wĩsĩ nĩ ĩvinda yĩana ata.'),
('kam', 'PSA', 74, 10, 'Nthũ ĩkavũthya kũvika ĩndĩĩ, ame Ngai? Mũmaitha akauma syĩtwa yaku tene na tene?'),
('kam', 'PSA', 74, 11, 'Nĩkĩ wĩtũnga kw’oko kwaku, o kw’oko kwaku kwa aũme? Kumye kĩthũinĩ kyaku noimamina.'),
('kam', 'PSA', 74, 12, 'Ĩndĩ Ngai nĩ Mũsumbĩ wakwa wa tene, Akĩka ũtangĩĩo katĩ wa nthĩ.'),
('kam', 'PSA', 74, 13, 'Nĩwaaanisye ũkanga kwondũ wa vinya waku: Nĩwatumbangie mĩtwe ya mĩkũnga mĩnene ya manzĩnĩ.'),
('kam', 'PSA', 74, 14, 'Nũtilangĩte ilungu mĩtwe ya leviathani; Nĩwamĩnenganie yĩthĩwe lĩu wa andũ ala matũĩte weũnĩ.'),
('kam', 'PSA', 74, 15, 'Nĩwavũthũie nthongo na manzĩ maingĩ: Nĩwang’alilye mbũsĩ nene mũno.'),
('kam', 'PSA', 74, 16, 'Mũthenya nĩ waku, ũtukũ naw’o nĩ waku; Nũseũvĩtye kyeni o na syũa nayo.'),
('kam', 'PSA', 74, 17, 'Nĩwiĩte mĩvaka yonthe ya nthĩ: Nũtw’ĩte ĩvinda ya syũa na ĩvinda ya mbevo.'),
('kam', 'PSA', 74, 18, 'Lilikana ũũ, kana mũmaitha nũvũthĩtye, ame Yeova, Na kana andũ atumanu nĩmaumĩte syĩtwa yaku.'),
('kam', 'PSA', 74, 19, 'Ame ndũkanenge nyamũ mbai thayũ wa ndumbũ yaku: Ndũkaolwe nĩ thayũ wa ngya syaku tene na tene.'),
('kam', 'PSA', 74, 20, 'Syaĩĩsya ũla ũtianĩo; Nũndũ kũndũ kwa nthĩ kwĩ kĩvindu nĩkusũĩte motũo ma ũng’endu.'),
('kam', 'PSA', 74, 21, 'Ndũkaeke athĩni masyoke makĩsonoka: Ngya na athĩni nĩmataĩe syĩtwa yaku.'),
('kam', 'PSA', 74, 22, 'Ũkĩla, ame Ngai, ĩtetee mwene: Lilikana ũndũ mũndũ mũtumanu ũkũvũthasya mũthenya w’onthe.'),
('kam', 'PSA', 74, 23, 'Ndũkaolwe nĩ wasya wa nthũ syaku: Kĩtuu kya ala makũkĩlĩĩlaa nĩkyambataa mavinda onthe.'),
('kam', 'PSA', 75, 1, 'Nĩtũũkũtũngĩa mũvea, ame Ngai; Nĩtũũtũnga mũvea, nũndũ syĩtwa yaku yĩ vakuvĩ: Andũ nĩmaneenaa ũndũ wa mawĩa maku ma ũseng’ya.'),
('kam', 'PSA', 75, 2, 'Yĩla ngosa ĩvinda yĩla yĩtw’ĩtwe, Ngasilĩla na ũlũngalu.'),
('kam', 'PSA', 75, 3, 'Nthĩ nĩtwekete na andũ onthe ala mamĩtwĩe: Nĩnĩũngamĩtye ituĩ syayo.'),
('kam', 'PSA', 75, 4, 'Nĩnamatavisye ekathĩĩi, Mũtikeke na ngathĩĩo; Na ala athũku, mũtikokĩlye ũvya:'),
('kam', 'PSA', 75, 5, 'Mũtikokĩlye ũvya wenyu ĩũlũ; Mũtikaneene mwĩ na ngingo nyũmũ.'),
('kam', 'PSA', 75, 6, 'Nũndũ kuma wumĩlonĩ wa syũa, kana ũthũĩlonĩ wa syũa, Kana ngalĩ ya ĩtheo, kũtyumaa kũnenevw’a.'),
('kam', 'PSA', 75, 7, 'Ĩndĩ Ngai nĩwe mũsili: Nũnũũtheesya ũmwe, na kũkĩlya ũngĩ.'),
('kam', 'PSA', 75, 8, 'Nũndũ kw’okonĩ kwa Yeova kwĩ kĩkombe, na mbinyu yĩ na ĩvuo; Nĩkyusũĩte mũvulan’yo, naw’o nũwonoasya: Vate ndĩi imongoyo syaw’o, athũku onthe ma nthĩ makaiviva, na kwinyw’a.'),
('kam', 'PSA', 75, 9, 'Ĩndĩ ngatavan’ya tene na tene, Ngaina ngĩkumya Ngai wa Yakovo.'),
('kam', 'PSA', 75, 10, 'Mbya syonthe sya ala athũku ngaitila; Ĩndĩ mbya sya ala alũngalu ikookĩlw’a.'),
('kam', 'PSA', 76, 1, 'Ngai nĩwĩsĩkĩwe kwa Yuta: Syĩtwa yake nĩ ĩnene kwa Isilaeli.'),
('kam', 'PSA', 76, 2, 'O na wĩkalo wake wĩ Saleme, Na ũtũo wake Saioni.'),
('kam', 'PSA', 76, 3, 'Nĩwatũlĩle mĩsyĩ ya ũta kw’o; Ngao, na ũvyũ, na kaũ.'),
('kam', 'PSA', 76, 4, 'We wĩ na ndaĩa nene na ũnene, Kũvĩtũka iĩma syĩ mũtavo.'),
('kam', 'PSA', 76, 5, 'Ala me ngoo syĩ vinya nĩmataviwe, Nĩmakomete too woo; Vati ũmwe wa andũ me ũtonyi waona moko moo.'),
('kam', 'PSA', 76, 6, 'Kwondũ wa ũkan’yo waku, we Ngai wa Yakovo, Ĩkasya ya kaũ na mbalasi nĩsyĩkĩtw’e toonĩ wa kĩkw’ũ.'),
('kam', 'PSA', 76, 7, 'We, o we, wĩ wa ũkĩwa; Na nũũ ũla ũtonya kũũngama mbee waku yĩla ũminĩte kũthata?'),
('kam', 'PSA', 76, 8, 'Nĩwatumie ũtw’ĩo wa sila wĩw’ĩka wumĩte ĩtunĩ; Nthĩ yakĩa, na yavindya,'),
('kam', 'PSA', 76, 9, 'Yĩla Ngai wokĩlile asile, Atangĩĩe ala auu onthe ma nthĩ.'),
('kam', 'PSA', 76, 10, 'Vate ndĩi ũthilĩku wa mũndũ ũkakũtaĩa: Ũthilĩku ũla ũtiele naku ũkeevotoa.'),
('kam', 'PSA', 76, 11, 'Ĩvĩte, nokĩanĩsya kwa Yeova Ngai waku: Onthe ala mamũthyũlũlũkĩte mamũetee mĩthĩnzĩo ũsu waĩle kũkĩwa.'),
('kam', 'PSA', 76, 12, 'Akatila veva wa anene me mbee ũsumbĩnĩ: Nake nĩ ũtĩsyo kwa asumbĩ ma nthĩ.'),
('kam', 'PSA', 77, 1, 'Ngamwĩkaĩla Ngai na wasya wakwa, O Ngai na wasya wakwa; nake akambĩthukĩĩsya.'),
('kam', 'PSA', 77, 2, 'Mũthenya wa thĩna wakwa nĩnamũmanthie Mwĩaĩi: Kw’oko kwakwa kwaĩ kũtambũũku ũtukũ, na kũtyaaleela; Ngoo yakwa yalea kũkiakiw’a.'),
('kam', 'PSA', 77, 3, 'Nĩnĩlilikanaa Ngai, na ngĩthĩn’ya: Nĩnĩnyungunyĩasya, na veva wakwa nũthelaa vinya.'),
('kam', 'PSA', 77, 4, 'Nĩwĩkalasya metho makwa masyaĩĩsye: Nĩũũyĩte ũndũ ndatonya kũneena.'),
('kam', 'PSA', 77, 5, 'Nĩnĩsũanĩĩte ũndũ wa mĩthenya ya tene, Myaka ya mavinda ma tene, tene.'),
('kam', 'PSA', 77, 6, 'Nĩlilikanaa wathi wakwa ũtukũ: Nĩneenanasya na ngoo yakwa mwene; Na veva wakwa ũmanthaa na kĩthing’ĩĩsyo.'),
('kam', 'PSA', 77, 7, 'Mwĩaĩi akekya ũtee tene na tene? Na ndakethĩwa na ũseo ĩngĩ?'),
('kam', 'PSA', 77, 8, 'Ũseo waku wĩ wendo nũthelete kũvika tene na tene? Watho waku ũkalea kwĩanĩw’a tene na tene?'),
('kam', 'PSA', 77, 9, 'Ngai nĩũlĩtwe nĩ kwĩka nesa? Ũthatunĩ wake nũvingĩĩte matei make mololo?'),
('kam', 'PSA', 77, 10, 'Na nasya, ũu nĩ wonzu wakwa; Ĩndĩ ngalilikana myaka ya kw’oko kwa aũme kwa Ũla Wĩ Ĩũlũ wa Onthe.'),
('kam', 'PSA', 77, 11, 'Ngaweta meko ma Yeova; Nũndũ ngalilikana moseng’yo maku ma tene.'),
('kam', 'PSA', 77, 12, 'O na ngasũanĩa ũndũ wa wĩa waku w’onthe, Na kũsũanĩa meko maku.'),
('kam', 'PSA', 77, 13, 'Nzĩa yaku, we Ngai, yĩ nthĩnĩ wa vala vandũ vatheu: Nĩ ngai yĩva nene ĩilyĩ ta Ngai?'),
('kam', 'PSA', 77, 14, 'Nue Ngai ũla wĩkaa moseng’yo: Nũmanyĩthanĩtye vinya waku katĩ wa ngo sya andũ.'),
('kam', 'PSA', 77, 15, 'Nĩwovoetye andũ maku na kw’oko kwaku. Ana ma Yakovo na Yosevu.'),
('kam', 'PSA', 77, 16, 'Manzĩ nĩmakwonie, we Ngai; Manzĩ nĩmakwonie, makĩa: Syũngũ nasyo nĩsyatetemie.'),
('kam', 'PSA', 77, 17, 'Mathweo nĩmoonoisye manzĩ; Matu nĩmaumisye wasya: Mĩsyĩ yaku nayo nĩyaendie kw’onthe.'),
('kam', 'PSA', 77, 18, 'Wasya wa kĩtundumo kyaku waĩ kĩlinginĩ; Motisi mamulĩka nthĩ: Nthĩ yatetema na yathingitha.'),
('kam', 'PSA', 77, 19, 'Nzĩa yaku yaĩ ũkanganĩ, Na nzĩa syaku syaĩ manzĩnĩ maingĩ, Na matambya maku matyaamanyĩka.'),
('kam', 'PSA', 77, 20, 'Nĩwatongoesye andũ maku ta ndĩthya ya mbũi na malondu, Na kw’oko kwa Mose na Aluni.'),
('kam', 'PSA', 78, 1, 'Ĩthukĩĩsyei mĩao yakwa, inyw’ĩ andũ makwa: Teai matũ menyu mwĩw’e ndeto sya kanyw’a wakwa.'),
('kam', 'PSA', 78, 2, 'Ngaathamya kanyw’a wakwa nĩneene ngelekan’yo; Nganeena nthimo sya tene,'),
('kam', 'PSA', 78, 3, 'Ila tweewie na kũmanya, Ila aaĩthe maitũ matũtavisye.'),
('kam', 'PSA', 78, 4, 'Tũtikaaiimĩthya syana syoo, Tũkĩtavya nzyawa ĩla yũkĩte ndaĩa sya Yeova, Na vinya wake, na mawĩa make ma ũseng’ya ala wekie.'),
('kam', 'PSA', 78, 5, 'Nũndũ nĩwalũlũmĩlye ũkũsĩ nthĩnĩ wa Yakovo, Na nĩwatwie mĩao nthĩnĩ wa Isilaeli, Ĩla weaĩe aaĩthe maitũ, Nĩ kana mamĩmanyĩthye syana syoo;'),
('kam', 'PSA', 78, 6, 'Nĩ kana nzyawa ĩla yũkĩte ĩmĩmanye, o ana ala makasyawa; Nao makookĩla na kũmatavya ana moo,'),
('kam', 'PSA', 78, 7, 'Nĩ kana maie wĩkwatyo woo vala ve Ngai, Na matikolwe nĩ mawĩa ma Ngai, Ĩndĩ makwate mĩao yake,'),
('kam', 'PSA', 78, 8, 'Na matikethĩwe ta aaĩthe moo, Nzyawa yĩ ngũlũ na ũng’endu, Nzyawa ĩla ĩtaaseũvya ngoo yayo, Na veva wayo ũtaalũman’ya na Ngai.'),
('kam', 'PSA', 78, 9, 'Syana sya Evalaimu, syĩ na mĩio ya kaũ na ikuĩte mata, Nĩsyeetulũlile mũthenya wa kũkita.'),
('kam', 'PSA', 78, 10, 'Ityaalũmya ũtianĩo wa Ngai, Na syalea kũendaa mĩaonĩ yake;'),
('kam', 'PSA', 78, 11, 'Na nĩsyoolilwe nĩ meko make, Na mawĩa make ma ũseng’ya ala wamonisye.'),
('kam', 'PSA', 78, 12, 'Nĩwekie maũndũ ma ũseng’ya aaĩthe moo mene, Nthĩ ya Misili, kĩlungunĩ kya ku Nzoani.'),
('kam', 'PSA', 78, 13, 'Nĩwaaanisye ũkanga, na amavĩtĩlya vo; Na atuma manzĩ maũngama ta kĩvumbu.'),
('kam', 'PSA', 78, 14, 'Na mũthenya amatongoesya na mũumbĩ, Na ũtukũ w’onthe na kyeni kya mwaki.'),
('kam', 'PSA', 78, 15, 'Aatũĩa mavia weũnĩ, Na amanenga kya ũnyw’a kingĩ ta kyumĩte syũngũnĩ.'),
('kam', 'PSA', 78, 16, 'O na aumya tũlũsĩ yĩla ĩvianĩ, Na atuma manzĩ matheea ta mbũsĩ.'),
('kam', 'PSA', 78, 17, 'Ĩndĩ nĩmaendeeie na kũmũvĩtanĩsya, Kũmũng’endeea weũnĩ Ũla Wĩ Ĩũlũ wa Onthe.'),
('kam', 'PSA', 78, 18, 'Na mamũtata Ngai ngoonĩ syoo Kwondũ wa kwĩtya lĩu kwĩanana na kwenda kwoo.'),
('kam', 'PSA', 78, 19, 'Ĩĩ, nĩmamũneeneie Ngai; Makyasya, Ngai nũtonya kwalan’ya mesa weũnĩ?'),
('kam', 'PSA', 78, 20, 'Sisya, nĩwakũnie ĩvia na manzĩ mauma na vinya, Na tũlũsĩ twavingĩte na tũkakĩla; Nake nũtonya kũnengane kĩmũtũ nakyo? Akanenga andũ make nyama?'),
('kam', 'PSA', 78, 21, 'Kwondũ wa ũu Yeova eew’a, na athilĩka; Na mwaki wamwakanĩa Yakovo, Na ũthatu naw’o wookĩlĩla Isilaeli;'),
('kam', 'PSA', 78, 22, 'Nĩkwĩthĩwa matyaamwĩtĩkĩla Ngai, Na matyaaĩkĩĩa ũtangĩĩonĩ wake.'),
('kam', 'PSA', 78, 23, 'Ĩndĩ eeaĩa matu me ĩũlũ, Na avingũa mĩomo ya ĩtunĩ;'),
('kam', 'PSA', 78, 24, 'Na amauĩsya ũla mana maye, Ĩĩ, amanenga lĩu wumĩte ĩtunĩ.'),
('kam', 'PSA', 78, 25, 'Kĩla mũndũ aya kĩmũtũ kya ala me ũtonyi: Amaetee lĩu wa kũmavũn’ya.'),
('kam', 'PSA', 78, 26, 'Nĩwatumie kĩseve kyumĩte wumĩlonĩ wa syũa kĩuutana matunĩ; Na nũndũ wa vinya wake atongoesya kĩseve kya ngalĩ ya ĩtheo.'),
('kam', 'PSA', 78, 27, 'O na amauĩsya nyama ta kĩtoo, O nyũnyi syĩ nthwau ta kĩthangathĩ kya maũkanga:'),
('kam', 'PSA', 78, 28, 'Na avalũkya katĩ wa mwako woo wa maeema, Kũthyũlũlũka motũo moo.'),
('kam', 'PSA', 78, 29, 'Na ĩndĩ maya, na mavũna vyũ; Na amanenga kwenda kwoo ene.'),
('kam', 'PSA', 78, 30, 'Matyaataanw’a nĩ kĩla mendete, Lĩu woo waĩ o makanyw’anĩ moo,'),
('kam', 'PSA', 78, 31, 'Yĩla ũthatu wa Ngai wamokĩlĩle, Na wooaa ala anou mbee moo, Na wavalũkya nthĩ anake ma Isilaeli.'),
('kam', 'PSA', 78, 32, 'Ĩndĩ o na ũu w’onthe nĩmaendeeie na kwĩka naĩ, Na matyaaĩtĩkĩla mawĩa make ma ũseng’ya.'),
('kam', 'PSA', 78, 33, 'Kwondũ wa ũu nĩwaminĩe mĩthenya yoo maũndũnĩ ma mana, Na myaka yoo ũtĩsyonĩ.'),
('kam', 'PSA', 78, 34, 'Yĩla wamoaie, nĩvo mamũmanthie; Na masyoka na mamũmantha Ngai na kĩthing’ĩĩsyo.'),
('kam', 'PSA', 78, 35, 'Na malilikana kana Ngai nĩ ĩvia yoo, Na Ngai Ũla Wĩ Ĩũlũ wa Onthe mwovosya woo.'),
('kam', 'PSA', 78, 36, 'Ĩndĩ nĩmendeeasya kwake na ndeto sya ũkathĩĩo sya makanyw’a moo, Na kũmũtavya movũngũ na nĩmĩ syoo.'),
('kam', 'PSA', 78, 37, 'Nũndũ ngoo syoo ityaĩ ndũngalu kwake, O na matyaĩ na kĩthito ũtianĩonĩ wake.'),
('kam', 'PSA', 78, 38, 'Ĩndĩ we, nũndũ aĩ na tei, aaekea ũthũku woo, na ndaamananga: Ĩĩ, mavinda maingĩ nĩwathyũũaa ũthatu wake, Na ndaokĩlya ũthilĩku wake w’onthe.'),
('kam', 'PSA', 78, 39, 'Na alilikana kana mo no mwĩĩ, Kĩseve kĩla kĩvĩtaa, na kĩtyũkaa ĩngĩ.'),
('kam', 'PSA', 78, 40, 'Nĩ mavinda meana mamũng’endee weũnĩ, Na kũmwĩw’ĩthya woo yalatanĩ!'),
('kam', 'PSA', 78, 41, 'Na meethyũũa ĩngĩ na mamũtata Ngai, Na kũthatya Ũla Mũtheu wa Isilaeli.'),
('kam', 'PSA', 78, 42, 'Matyaalilikana kw’oko kwake, Kana mũthenya ũla wamovoisye kuma kwa nthũ;'),
('kam', 'PSA', 78, 43, 'Kana ũndũ waiie movano make Misili, Na moseng’yo make kĩlungunĩ kya ku Nzoani,'),
('kam', 'PSA', 78, 44, 'Na atuma mbũsĩ syoo ialyũka nthakame, Na tũlũsĩ twoo, kwondũ wa ũu matyaatonya kũnyw’a.'),
('kam', 'PSA', 78, 45, 'Aete katĩ woo ngi mbingĩ, ila syamaminie; Na syoa, ila syamanangie.'),
('kam', 'PSA', 78, 46, 'O na anenga kĩthesa wingĩvo woo, Na ngie wĩa woo.'),
('kam', 'PSA', 78, 47, 'Nĩwanangie mĩsavivũ yoo na mbua ya mavia, Na mĩkũyũ yoo na ĩmwe yĩkamĩtw’e nĩ mbevo.'),
('kam', 'PSA', 78, 48, 'O na nĩwanenganie ng’ombe syoo mbuanĩ ya mavia, Na ndĩthya syoo sya mbũi na malondu motisinĩ mavyũ.'),
('kam', 'PSA', 78, 49, 'Amekĩsya wai wa ũthatu wake, Ũthilĩku, na woo, na thĩna, O nguthu ya alaĩka ma ũthũku.'),
('kam', 'PSA', 78, 50, 'Nĩwaseũvĩsye ũthatu wake nzĩa; Ndaasũvĩa mathayũ moo matikakw’e, Ĩndĩ anengane thayũ woo mũimũnĩ,'),
('kam', 'PSA', 78, 51, 'Na akũna makithathi onthe ma Misili, Nĩmo kĩtina kya vinya woo maeemanĩ ma Amu.'),
('kam', 'PSA', 78, 52, 'Ĩndĩ amaumaalya andũ make mwene ta malondu, Na amatongoesya weũnĩ ta ndĩthya ya mbũi na malondu.'),
('kam', 'PSA', 78, 53, 'Na amatongoeasya vate mũisyo, kwondũ wa ũu matyaakĩa; Ĩndĩ ũkanga wavw’ĩka amaitha moo.'),
('kam', 'PSA', 78, 54, 'Na amaete mũvakanĩ wake mũtheu, Kĩĩmanĩ kĩĩ, kĩla kw’oko kwake kwa aũme kwosete.'),
('kam', 'PSA', 78, 55, 'O na alũngya i mbaĩ mbee woo, Na amaaanisye kwa kũthima yĩthĩwe ũtiĩwa, Na atuma mbaĩ sya Isilaeli itũa maeemanĩ ma isu.'),
('kam', 'PSA', 78, 56, 'Ĩndĩ nĩmamũtatie na kũmũng’endea Ngai Ũla Wĩ Ĩũlũ wa Onthe, Na matyaakwata mokũsĩ make;'),
('kam', 'PSA', 78, 57, 'Ĩndĩ meetulũla, na meeka ũseleke ta aaĩthe moo; Nĩmaathũkiw’e ũtee ta ĩtati.'),
('kam', 'PSA', 78, 58, 'Nũndũ nĩmamũthatisye ũndũ wa kũndũ kwoo kũtũlu, Na mamwĩkĩa kĩwĩu ũndũ wa mĩvw’anano yoo myasũvye.'),
('kam', 'PSA', 78, 59, 'Yĩla Ngai wewie ũu, athilĩka, Na athĩtha Isilaeli mũno;'),
('kam', 'PSA', 78, 60, 'Kũvika atia wĩkalo wa Silo, Ĩeema yĩla waiĩte katĩ wa andũ;'),
('kam', 'PSA', 78, 61, 'Na anengane vinya wake kũtavwanĩ, Na ndaĩa yake mokonĩ ma mũmaitha.'),
('kam', 'PSA', 78, 62, 'O na nĩwanenganie andũ make ũvyũnĩ, Na athilĩkĩla ũtiĩwa wake.'),
('kam', 'PSA', 78, 63, 'Mwaki nĩwaminie anake moo; Na eĩtu moo atheu matyaĩ na wathi wa mũtwaano.'),
('kam', 'PSA', 78, 64, 'Athembi moo mavalũkw’a na ũvyũ; Na aka ndiwa syoo ityaaĩa.'),
('kam', 'PSA', 78, 65, 'Nĩvo ĩndĩ Ngai waamũkie ta ũmwe wumĩte toonĩ, Ta ngũmbaũ ĩlonzaw’a nĩ mbinyu.'),
('kam', 'PSA', 78, 66, 'Na akũna nthũ syake syasyoka na ĩtina: Aivũthĩthya mavinda onthe.'),
('kam', 'PSA', 78, 67, 'Na ĩngĩ alea ĩeema ya Yosevu, Na ndaanyuva mbaĩ ya Evalaimu,'),
('kam', 'PSA', 78, 68, 'Ĩndĩ anyuva mbaĩ ya Yuta, Kĩĩma kya Saioni kĩla wendaa.'),
('kam', 'PSA', 78, 69, 'Na nĩwakie vala vandũ vake vatheu ta motũlu, Ta nthĩ ĩla ũmĩlũlũmĩlye tene na tene.'),
('kam', 'PSA', 78, 70, 'O na anyuva Ndaviti mũthũkũmi wake, Na amumya syengonĩ sya malondu:'),
('kam', 'PSA', 78, 71, 'Amũete yĩla waatĩĩaa malondu me na tũtena, Eethĩwa mũĩthi wa Yakovo andũ make, na Isilaeli ũtiĩwa wake.'),
('kam', 'PSA', 78, 72, 'Na ĩndĩ aĩ mũĩthi woo kwĩanana na wĩanĩu wa ngoo yake, Na amatongoeasya na ũtuĩka wa moko make.'),
('kam', 'PSA', 79, 1, 'Ame Ngai, i mbaĩ nilikĩte ũtiĩwanĩ waku; Nivukĩtye ĩkalũ yaku ĩtheu; Nitw’ĩkĩthĩtye Yelusaleme ivumbu.'),
('kam', 'PSA', 79, 2, 'Simba sya athũkũmi maku ninengete nyũnyi sya yayaya syĩthĩwe lĩu, Mĩĩ ya atheu maku ninengete nyamũ sya nthĩ.'),
('kam', 'PSA', 79, 3, 'Nĩsyetĩkisye nthakame yoo ta manzĩ kũthyũlũlũka Yelusaleme; Na vatyaĩ ũmwe wa kũmenzĩa nthĩ.'),
('kam', 'PSA', 79, 4, 'Nĩtũtw’ĩkĩte ma kũvũthĩĩw’a nĩ atũi maitũ, Na kũvũĩwa ngũĩ na kũthekeewa nĩ ala matũthyũlũlũkĩte.'),
('kam', 'PSA', 79, 5, 'Iĩ kũvika ĩndiĩ, ame Yeova? Ũkathata tene na tene? Kĩwĩu kyaku kĩkakana ta mwaki?'),
('kam', 'PSA', 79, 6, 'Onoesya ũthatu waku mbaĩ ila itakwĩsĩ, Na mosumbĩ ala matekwĩkaĩla syĩtwa yaku.'),
('kam', 'PSA', 79, 7, 'Nũndũ niminĩte Yakovo, Na nĩsyanangĩte ũtũo wake.'),
('kam', 'PSA', 79, 8, 'Ndũkatũlilikanĩle mothũku ma aaũmae maitũ: Matei maku mololo makomane maitũ mĩtũkĩ; Nũndũ nĩtũtheeetw’e mũno.'),
('kam', 'PSA', 79, 9, 'Tũtethye, ame Ngai wa ũtangĩĩo witũ, kwondũ wa ndaĩa ya syĩtwa yaku; Na tũvonokye, na kũtũekea naĩ sitũ, kwondũ wa syĩtwa yaku.'),
('kam', 'PSA', 79, 10, 'Nũndũ wa kĩ i mbaĩ syaasye, Ngai woo aĩva? Kũĩvanĩsya kwa nthakame ya athũkũmi maku ĩla mbĩtĩku Nĩkũmanyĩke katĩ wa i mbaĩ twene.'),
('kam', 'PSA', 79, 11, 'Kũvevũũka kwa ũla mwove nĩkũke mbee waku: Kwĩanana na ũnene wa vinya waku sũvĩa ala matw’ĩĩwe kũkw’a;'),
('kam', 'PSA', 79, 12, 'Na maĩve atũi maitũ kũndũ mũonza kĩthũinĩ kyoo Kĩvũthya kyoo, kĩla makũvũthisye nakyo, we Mwĩaĩi.'),
('kam', 'PSA', 79, 13, 'Kwondũ wa ũu ithyĩ andũ maku na malondu ma ĩĩthya yaku Tũkakũtũngĩa mũvea tene na tene: Tũkoonan’ya ndaĩa yaku nzyawanĩ syonthe.'),
('kam', 'PSA', 80, 1, 'Tea kũtũ, we Mũĩthi wa Isilaeli, We ũla ũtongoeasya Yosevu ta ndĩthya ya mbũi na malondu; We ũla wĩkalaa ĩũlũ wa akeluvi, tisũka.'),
('kam', 'PSA', 80, 2, 'Akan’ya ũtonyi waku mbee wa Evalaimu na Mbenyamini na Manase, Noyũka ũtũtangĩĩe.'),
('kam', 'PSA', 80, 3, 'Tũthyũũe ĩngĩ, ame Ngai; Noitisĩthya ũthyũ waku, na tũkatangĩĩwa.'),
('kam', 'PSA', 80, 4, 'Ame Yeova Ngai wa nguthu, Ũkathatĩa mboya ya andũ maku kũvika ĩndĩĩ?'),
('kam', 'PSA', 80, 5, 'Nũmaathĩĩtye lĩu wa methoi, Na kũmanenga na kĩthimo kĩnene methoi ma ũnyw’a.'),
('kam', 'PSA', 80, 6, 'Nũtũtw’ĩte ma kũtetanĩw’a kwa atũi maitũ; Na amaitha maitũ nĩmethekeaa.'),
('kam', 'PSA', 80, 7, 'Tũthyũũe ĩngĩ, we Ngai wa nguthu; Noitisĩthya ũthyũ waku, na tũkatangĩĩwa.'),
('kam', 'PSA', 80, 8, 'Nĩwaetie mũsavivũ kuma Misili: Nĩwalũngilye i mbaĩ, na woovanda.'),
('kam', 'PSA', 80, 9, 'Nĩwaseũvisye vandũ vaw’o, Na nĩwatambũũkisye mĩi nthĩnĩ wa nthĩ, na kusũa ĩ nthĩ.'),
('kam', 'PSA', 80, 10, 'Iĩma syavw’ĩkwa nĩ muunyĩ waw’o, Na ndĩso syaw’o syaĩ ta mĩkũũ ya Ngai.'),
('kam', 'PSA', 80, 11, 'Watambũũkya ndĩso syaw’o kũvika ũkanganĩ, Na nthongoo syaw’o kũvika ũla Ũsĩ.'),
('kam', 'PSA', 80, 12, 'Nĩkĩ ũomboete maũvai maw’o, Ũkethĩa onthe ala mavĩtĩlaa nzĩanĩ nĩmekũtw’a?'),
('kam', 'PSA', 80, 13, 'Ngũũe ya mũtitũnĩ nĩwanangaa, Na nyamũ mbai sya kĩthekanĩ nĩsyũĩsaa.'),
('kam', 'PSA', 80, 14, 'Ĩthyũũe ĩngĩ, nĩtũũkwĩsũva, ame Ngai wa nguthu: Keteea nthĩ wĩ ĩtunĩ, na sisya, noyũka vala ve mũsavivũ ũũ,'),
('kam', 'PSA', 80, 15, 'Na kĩtina kĩla kyavandiwe nĩ kw’oko kwaku kwa aũme, Na mũĩso ũla weekĩie vinya kwondũ waku mwene.'),
('kam', 'PSA', 80, 16, 'Nũvĩvĩtw’e na mwaki, nũtemewe nthĩ: Nĩmekwaa ũndũ wa ũkan’yo wa ũthyũ waku.'),
('kam', 'PSA', 80, 17, 'Kw’oko kwaku nĩkwĩthĩwe ĩũlũ wa mũndũ wa kw’oko kwaku kwa aũme, Ĩũlũ wa mwana wa mũndũ ũla wamwĩkĩie vinya ũndũ waku mwene.'),
('kam', 'PSA', 80, 18, 'Na ĩndĩ tũtikasyoka kuma vala ũĩ: Tũthayũũkye, na tũkeekaĩla syĩtwa yaku.'),
('kam', 'PSA', 80, 19, 'Tũthyũũe ĩngĩ, ame Yeova Ngai wa nguthu; Noitisĩthya ũthyũ waku, na tũkatangĩĩwa.'),
('kam', 'PSA', 81, 1, 'Mwinĩei na wasya Ngai vinya witũ: Ũkĩlĩlyai Ngai wa Yakovo wasya wa ũtanu.'),
('kam', 'PSA', 81, 2, 'Anĩĩsyai wathi, etei kathembe, Mbeve nzeo vamwe na kĩnanda.'),
('kam', 'PSA', 81, 3, 'Vuvai soo mwei watisa, Mwei watheea, mũthenya wa mboka yaitũ.'),
('kam', 'PSA', 81, 4, 'Nũndũ nĩ mwamũlo ũndũ wa Isilaeli, Ũtw’ĩo wa Ngai wa Yakovo.'),
('kam', 'PSA', 81, 5, 'Nĩwotwie wĩthĩwe ũkũsĩ kwa Yosevu, Yĩla waumie nthĩ ya Misili, Vala neewie kĩthyomo kĩla ndaamanya.'),
('kam', 'PSA', 81, 6, 'Nĩnaũie kĩtuo kyake mũio: Moko make mataanw’a na kĩkavũ.'),
('kam', 'PSA', 81, 7, 'Nĩweekaĩlile wĩ thĩnanĩ, nakwa nakũvonokya; Nĩnakũsũngĩie kĩmbithĩnĩ kya kĩtundumo; Nĩnakũoesye manzĩnĩ ma Miliva.'),
('kam', 'PSA', 81, 8, 'Ĩthukĩĩsyei, inyw’ĩ andũ makwa, na ngakũkũsĩĩa: Ame Isilaeli, kethĩwa nũmbĩthukĩĩsya!'),
('kam', 'PSA', 81, 9, 'Kũtikethĩwe ngai ngeni nthĩnĩ waku; O na ndũkathaithe ngai o na yĩva ya nthĩ ĩngĩ.'),
('kam', 'PSA', 81, 10, 'Ninyie Yeova Ngai waku, Ũla wakumisye nthĩ ya Misili: Athamya kanyw’a waku vyũ, nakwa ngawusũsya.'),
('kam', 'PSA', 81, 11, 'Ĩndĩ andũ makwa matyaaĩthukĩĩsya wasya wakwa; Na Isilaeli matyaambĩtĩkĩla.'),
('kam', 'PSA', 81, 12, 'Kwondũ wa ũu namaeka maatĩĩe ngũlũ sya ngoo syoo, Nĩ kana maendae motaonĩ moo ene.'),
('kam', 'PSA', 81, 13, 'A! Kethĩwa andũ makwa nĩmambĩthukĩĩsya, Kethĩwa Isilaeli nĩmakinya nzĩanĩ syakwa!'),
('kam', 'PSA', 81, 14, 'Nĩthĩwa nĩmakĩlĩlya vinya amaitha moo mĩtũkĩ, Na kũthyũũĩa nthũ syoo kw’oko kwakwa.'),
('kam', 'PSA', 81, 15, 'Ameni ma Yeova methĩwa mamwĩnyivĩsya: Ĩndĩ ĩvinda yoo yĩkekala tene na tene.'),
('kam', 'PSA', 81, 16, 'O na nũmaĩthya na nganũ ĩla nzeo mbee; Na ngĩkũvũn’ya na ũkĩ wa nzũkĩ wumĩte ivianĩ.'),
('kam', 'PSA', 82, 1, 'Ngai nũũngamaa ũmbanonĩ wa Ngai; Nũsilanasya katĩ wa i ngai.'),
('kam', 'PSA', 82, 2, 'Mũkasilaa sila ũte mũlũngalu kũvika ĩndĩĩ, Na kwendeesya ala athũku?'),
('kam', 'PSA', 82, 3, 'Silan’ya ngya na ala makw’ĩĩwe nĩ aaĩthe: Sila sila wa katĩ kwa ala mathĩnaw’a na ala mate kĩndũ.'),
('kam', 'PSA', 82, 4, 'Tangĩĩa ngya na athĩni: Mavonokye kw’okonĩ kwa ala athũku.'),
('kam', 'PSA', 82, 5, 'Matyĩsĩ, o na matikũmanya; Nĩmangangaa kũũ na kũũ nthĩnĩ wa kĩvindu: Myambĩlĩlyo yonthe ya nthĩ nĩthingithangĩtw’e.'),
('kam', 'PSA', 82, 6, 'Naisye, Inyw’ĩ mwĩ ngai, Na inyw’onthe mwĩ ana ma Ũla Wĩ Ĩũlũ wa Onthe.'),
('kam', 'PSA', 82, 7, 'Ĩndĩ mũkakw’a o ta andũ, Na kũvalũka ta ũmwe wa ala me mbee ũsumbĩnĩ.'),
('kam', 'PSA', 82, 8, 'Ũkĩla, ame Ngai, silĩla nthĩ; Nũndũ mbaĩ syonthe ikeethĩwa ũtiĩwa waku.'),
('kam', 'PSA', 83, 1, 'Ame Ngai, ndũkekilĩlye: Ndũkavindye, ndũkakilye, ame Ngai.'),
('kam', 'PSA', 83, 2, 'Nũndũ, sisya, amaitha maku nĩmeũkĩlya kĩtuu; Na ala makũmenaa nĩmokĩlĩtye mũtwe.'),
('kam', 'PSA', 83, 3, 'Nĩmasamanasya ũndũ wa andũ maku, Na kũsũanĩa vamwe ĩũlũ wa andũ maku ala avithe.'),
('kam', 'PSA', 83, 4, 'Nĩmaĩtye, Ũkai, tũmavete matikethĩwe mbaĩ; Nĩ kana syĩtwa ya Isilaeli yĩtikaalilikanwe ĩngĩ.'),
('kam', 'PSA', 83, 5, 'Nũndũ nĩmasũanĩĩte vamwe na ngoo ĩmwe; Nĩmekũseũvya wĩw’ano ĩũlũ waku:'),
('kam', 'PSA', 83, 6, 'Maeema ma Etomu na Aisumaeli; Moavi, na Aakali;'),
('kam', 'PSA', 83, 7, 'Ngevali, na Amimoni, na Amaleki; Vilisitia vamwe na ala matwĩe Tile:'),
('kam', 'PSA', 83, 8, 'Asuli nayo nĩkwatene nao; Nĩmatethetye ana ma Loto.'),
('kam', 'PSA', 83, 9, 'Meke o tondũ weekie Mitiani, Ta Sisela, ta Yavini, ũsĩnĩ wa Kisoni;'),
('kam', 'PSA', 83, 10, 'Ala maaĩe ku Eni‐ndoli, Ala matw’ĩkie ta vũũ kwondũ wa nthĩ.'),
('kam', 'PSA', 83, 11, 'Tw’ĩkĩthya anene moo me ndaĩa ta Olevi na Nzeevu; Ĩĩ, anene moo onthe me mbee ũsumbĩnĩ ta Nzeva na Nzalimuna;'),
('kam', 'PSA', 83, 12, 'Ala maisye, Twĩyosee methĩwe maitũ Motũo ma Ngai.'),
('kam', 'PSA', 83, 13, 'Ame Ngai wakwa, matw’ĩkĩthye ta kĩlingi kya kĩtoo; Ta ũa mbee wa kĩseve.'),
('kam', 'PSA', 83, 14, 'Ta mwaki ũla ũvĩvasya mũtitũ, Na ta kĩtw’ĩki kĩla kĩkwatasya iĩma mwaki,'),
('kam', 'PSA', 83, 15, 'O ta ũu maatĩĩe na kĩuutani kyaku, Na kũmatĩsya na kĩseve kyaku kĩnene.'),
('kam', 'PSA', 83, 16, 'Usũsya mothyũ moo nthoni, Nĩ kana mamanthe syĩtwa yaku, we Yeova.'),
('kam', 'PSA', 83, 17, 'Masonokw’e na mateve tene na tene; Ĩĩ, mathokoanw’e na kwaa;'),
('kam', 'PSA', 83, 18, 'Nĩ kana mamanye no we wĩ weka, syĩtwa yaku nĩ Yeova, Nue Wĩ Ĩũlũ wa Onthe ĩũlũ wa nthĩ yonthe.'),
('kam', 'PSA', 84, 1, 'A! Mawĩkalo maku nĩ maseo, We Yeova wa nguthu!'),
('kam', 'PSA', 84, 2, 'Ngoo yakwa yĩ na mea, ĩĩ, o na kũthelekela kwondũ wa nza sya Yeova; Ngoo yakwa na mwĩĩ wakwa nĩsyĩkaĩlaa Ngai ũla wĩ thayũ.'),
('kam', 'PSA', 84, 3, 'Ĩĩ, mũthoonzwe nĩwĩyoneete nyũmba, Na nthũngũlũlũ ndala, vala ĩtonya kwia tũswii twayo, O ithembeonĩ syaku, we Yeova wa nguthu, Mũsumbĩ wakwa, na Ngai wakwa.'),
('kam', 'PSA', 84, 4, 'Nĩ aathime ala matũaa nyũmbanĩ yaku: Makaendeea na ũkũtaĩa.'),
('kam', 'PSA', 84, 5, 'Nĩ mũathime mũndũ ũla vinya wake wĩ nthĩnĩ waku; Ũla malelũ ma kũthi Saioni me ngoonĩ yake.'),
('kam', 'PSA', 84, 6, 'Makĩvĩtĩla kyandanĩ kya Kũĩa nĩmeũkĩtw’ĩkĩthya vandũ va mbuluti; Ĩĩ, mbua ya nthwa nĩnĩũkĩvw’ĩka na moathimo.'),
('kam', 'PSA', 84, 7, 'Nĩmaendaa kuma vinyanĩ kũthi vinyanĩ; Kĩla ũmwe woo nĩwumĩlaa mbee wa Ngai ku Saioni'),
('kam', 'PSA', 84, 8, 'Ame Yeova Ngai wa nguthu, ĩw’a mboya yakwa; Tea kũtũ, ame Ngai wa Yakovo.'),
('kam', 'PSA', 84, 9, 'Sisya, ame Ngai ngao yaitũ, Noisisya ũthyũ wa mwĩtĩkĩw’a mauta waku.'),
('kam', 'PSA', 84, 10, 'Nũndũ mũthenya ũmwe nĩ nthĩnĩ wa nza syaku nĩ kavaa kwĩ mĩthenya ngili. Nĩ kavaa kwakwa kwĩthĩwa mũsũvĩi wa mũomonĩ nyũmbanĩ ya Ngai wakwa, Kwĩ kwĩkalaa maeemanĩ ma ũthũku.'),
('kam', 'PSA', 84, 11, 'Nũndũ Yeova Ngai nĩ syũa na ngao: Yeova akanengane mumo na ndaĩa; Ndakamaima kĩndũ kĩseo ala maendaa na mĩendele myaĩlu.'),
('kam', 'PSA', 84, 12, 'We Yeova wa nguthu, Nĩ mũathime mũndũ ũla ũkũĩkĩĩaa.'),
('kam', 'PSA', 85, 1, 'Yeova, nĩwĩkĩĩte nthĩ yaku mwaĩla; Nũtũngĩte Yakovo kuma kũtavwanĩ.'),
('kam', 'PSA', 85, 2, 'Nũekete ũthũku wa andũ maku; Nũvw’ĩkĩte naĩ yoo yonthe.'),
('kam', 'PSA', 85, 3, 'Nũvetete ũthilĩku waku w’onthe; Nĩwĩthyũũĩte ũkoeka wai wa ũthatu waku.'),
('kam', 'PSA', 85, 4, 'Tũthyũũe, ame Ngai wa ũtangĩĩo witũ, Noituma ũthilĩku waku ũla ũtwelekele ũthela.'),
('kam', 'PSA', 85, 5, 'Ũkatũthatĩa tene na tene? Ũkatũasya ũthatu waku kũvika nzyawa syonthe?'),
('kam', 'PSA', 85, 6, 'Ndwĩtũthayũũkya ĩngĩ, Nĩ kana andũ maku makũtanĩae?'),
('kam', 'PSA', 85, 7, 'Twon’ye ũseo waku wĩ wendo, ame Yeova, Noitũnenga ũtangĩĩo waku.'),
('kam', 'PSA', 85, 8, 'Ngeethukĩĩsya ũndũ Ngai Yeova wĩneena; Nũndũ akaneena mũuo kwa andũ make, na kwa atheu make: Ĩndĩ matikethyũũĩe ũtumanu ĩngĩ.'),
('kam', 'PSA', 85, 9, 'Vate ndĩi ũtangĩĩo wake wĩ vakuvĩ na ala mamũkĩaa, Nĩ kana ndaĩa yĩkale nthĩ yaitũ.'),
('kam', 'PSA', 85, 10, 'Tei na w’o nikomanĩte; Ũlũngalu na mũuo nimumunyanĩte.'),
('kam', 'PSA', 85, 11, 'W’o nĩwumĩlĩte nthĩ; Na ũlũngalu nũsyaĩtye nthĩ wĩ ĩtunĩ.'),
('kam', 'PSA', 85, 12, 'Ĩĩ, Yeova akanengane kĩla kĩseo; Na nthĩ yaitũ ĩkaingĩvasya ũsyao wayo.'),
('kam', 'PSA', 85, 13, 'Ũlũngalu ũkatongoasya mbee wake, Na ũkatw’ĩkĩthya matambya make nzĩa ya kũendelaa.'),
('kam', 'PSA', 86, 1, 'Tea kũtũ kwaku, ame Yeova, noinzũngĩa; Nũndũ nĩ ngya na mũthĩni.'),
('kam', 'PSA', 86, 2, 'Sũvĩa thayũ wakwa; nũndũ nĩmũkĩaa Ngai: Ame Ngai wakwa, tangĩĩa mũthũkũmi waku ũla ũkũĩkĩĩaa.'),
('kam', 'PSA', 86, 3, 'Mbĩw’ĩa tei, ame Mwĩaĩi; Nũndũ nĩnĩkwĩkaĩlaa mũthenya w’onthe.'),
('kam', 'PSA', 86, 4, 'Tanĩthya ngoo ya mũthũkũmi waku; Nũndũ nĩnĩkũkĩlĩlasya ngoo yakwa, ame Mwĩaĩi.'),
('kam', 'PSA', 86, 5, 'Nũndũ wĩ mũseo, Mwĩaĩi, na nĩwĩyũmbanĩtye kũekea, Na wĩ na ũseo mwingĩ wĩ wendo kwa onthe ala mekwĩkaĩlaa.'),
('kam', 'PSA', 86, 6, 'Tea kũtũ, ame Yeova, wĩw’e mboya yakwa; Na ĩthukĩĩsye wasya wa mawĩsũvano makwa.'),
('kam', 'PSA', 86, 7, 'Mũthenya wa thĩna wakwa ngakwĩkaĩla; Nũndũ ũkanzũngĩa.'),
('kam', 'PSA', 86, 8, 'Vaiĩ nongi ũilyĩ taku katĩ wa i ngai, we Mwĩaĩi; O na vai mawĩa mailyĩ mawĩa maku.'),
('kam', 'PSA', 86, 9, 'Mbaĩ syonthe ila woombie ikooka na kũthaithĩa mbee waku, we Mwĩaĩi; Na ikataĩa syĩtwa yaku.'),
('kam', 'PSA', 86, 10, 'Nũndũ wĩ mũnene, na nĩwĩkaa maũndũ ma ũseng’ya: No we Ngai wĩ weka.'),
('kam', 'PSA', 86, 11, 'Manyĩsya nyie nzĩa yaku, we Yeova; ngaendaa nthĩnĩ wa w’o waku: Ũmban’ya ngoo yakwa ĩkĩae syĩtwa yaku.'),
('kam', 'PSA', 86, 12, 'Ngakũtaĩa, we Mwĩaĩi Ngai wakwa, na ngoo yakwa yonthe; Na ngataĩa syĩtwa yaku tene na tene.'),
('kam', 'PSA', 86, 13, 'Nũndũ ũseo waku wĩ wendo nĩ mũnene kwakwa; Na nũvonoketye ngoo yakwa kuma kũndũ kwĩ ĩtheo vyũ ku Seoli.'),
('kam', 'PSA', 86, 14, 'We Ngai, ekathĩĩi nĩmambũkĩlĩle, Na nguthu ya andũ ang’endu nĩmanthĩte thayũ wakwa, Na matikwiĩte mbee woo.'),
('kam', 'PSA', 86, 15, 'Ĩndĩ we, Mwĩaĩi, wĩ Ngai wĩ tei na mũseo, Mũmĩĩsya wa kũthata, na wĩ na ũseo mwingĩ wĩ wendo na w’o.'),
('kam', 'PSA', 86, 16, 'Ame ĩnthyũũĩe, noimbĩw’ĩa tei; Nenga mũthũkũmi waku vinya waku, Noitangĩĩa mwana wa mũthũkũmi waku mwĩĩtu.'),
('kam', 'PSA', 86, 17, 'Mbon’ya ũvano wa ũseo, Nĩ kana ala mamenaa matonye kũwona, na kũsonoka, Nĩkwĩthĩwa we, Yeova, nũndethetye, na kũngiakisya.'),
('kam', 'PSA', 87, 1, 'Mwambĩlĩlyo wayo wĩ iĩmanĩ ntheu.'),
('kam', 'PSA', 87, 2, 'Yeova nĩwendaa mbingĩlo sya Saioni Kũvĩtũka motũo onthe ma Yakovo.'),
('kam', 'PSA', 87, 3, 'Nũwetawa maũndũ ma ũkũtaĩa, We ndũa ya Ngai.'),
('kam', 'PSA', 87, 4, 'Ngaweta Laavi na Mbaviloni ta imwe katĩ wa ila imbĩsĩ: Sisya, Vilisitia, na Tile, vamwe na Ethiovia: Ũũ nĩwasyaĩwe kw’o.'),
('kam', 'PSA', 87, 5, 'Ĩĩ, kũkaneenwa ũndũ wa Saioni, Ũũ na ũya nĩmasyaĩwe nthĩnĩ wayo; Na Ũla Wĩ Ĩũlũ wa Onthe we mwene akamĩlũlũmĩlya.'),
('kam', 'PSA', 87, 6, 'Yeova akatala, yĩla wĩandĩka ngo sya andũ, Ũũ nĩwasyaĩwe kw’o.'),
('kam', 'PSA', 87, 7, 'Ala meinaa o na ala mesungaa makasya, Nthongo syakwa syonthe syĩ nthĩnĩ waku.'),
('kam', 'PSA', 88, 1, 'Ame Yeova, Ngai wa ũtangĩĩo wakwa, Nĩngwĩkaĩlĩte mbee waku mũthenya na ũtukũ.'),
('kam', 'PSA', 88, 2, 'Mboya yakwa ĩlike vala ũĩ; Tea kũtũ kwaku wĩw’e kĩĩo kyakwa.'),
('kam', 'PSA', 88, 3, 'Nũndũ ngoo yakwa nĩyusũĩte mathĩna, Na thayũ wakwa nũthengeee Seoli.'),
('kam', 'PSA', 88, 4, 'Nĩndalanĩlw’e na ala matheeaa yĩla ĩimanĩ; Nĩilyĩ ta mũndũ ũte na mũtethya.'),
('kam', 'PSA', 88, 5, 'Nĩkĩtw’e ũtee katĩ wa akw’ũ, Ta oawa ala makomaa mbũanĩ, Ala ũtamalilikana ĩngĩ, Na nĩmavetetwe kw’okonĩ kwaku.'),
('kam', 'PSA', 88, 6, 'Nũmbiĩte ĩimanĩ yĩ ĩtheo vyũ, Kũndũnĩ kwĩ kĩvindu, molikunĩ.'),
('kam', 'PSA', 88, 7, 'Ũthilĩku waku nĩ mũito kwakwa, Na nũnthĩnĩtye na itulumo syaku syonthe.'),
('kam', 'PSA', 88, 8, 'Nĩwĩkĩtye ala nĩsene nao kũasa nakwa; Nũndw’ĩte ũthatyo kwoo: Nĩmbingĩwe, na nditonya kumaala.'),
('kam', 'PSA', 88, 9, 'Itho yakwa nĩyĩseekee nũndũ wa thĩna: Nĩngũkwĩkaĩla kĩla mũthenya, we Yeova; Nĩngũkũtambũũkĩsya moko makwa.'),
('kam', 'PSA', 88, 10, 'Ũkamon’ya akw’ũ moseng’yo? Ala makwie makookĩla na ũkũtaĩa?'),
('kam', 'PSA', 88, 11, 'Ũseo waku wĩ wendo ũkatavanw’a mbũanĩ? Kana kĩthito kyaku Wanangĩkonĩ?'),
('kam', 'PSA', 88, 12, 'Moseng’yo maku makamanyĩka kĩvindunĩ? Na ũlũngalu waku nthĩ ya mbũlwa?'),
('kam', 'PSA', 88, 13, 'Ĩndĩ nĩngwĩkaĩlĩte, we Yeova; Na kĩoko mboya yakwa ĩkambata vala ũĩ.'),
('kam', 'PSA', 88, 14, 'Yeova, nĩkĩ wĩkasya ũtee ngoo yakwa? Nũndũ wa kĩ nũmbithaa ũthyũ waku?'),
('kam', 'PSA', 88, 15, 'Nĩthĩnĩte na kwĩyũmbanĩsya kũkw’a kuma wana wakwa kũvika yu: Yĩla nĩthĩnaw’a nĩ motĩsyo maku nĩvũavũanĩtw’e.'),
('kam', 'PSA', 88, 16, 'Ũthatu waku mwai nũvĩtĩle ĩũlũ wakwa; Motĩsyo maku nĩmambetete.'),
('kam', 'PSA', 88, 17, 'Nĩmanthyũlũlũkile ta manzĩ mũthenya w’onthe; Nĩmanthyũlũlũkile vamwe.'),
('kam', 'PSA', 88, 18, 'Mwendwa na mũnyanya nũmavetete kũasa nakwa, Na ũla nĩsene nake ekw’a kĩvindunĩ.'),
('kam', 'PSA', 89, 1, 'Ngainaa ũndũ wa ũseo wĩ wendo wa Yeova tene na tene: Na ngamanyĩthya nzyawa syonthe kĩthito kyaku na kanyw’a wakwa.'),
('kam', 'PSA', 89, 2, 'Nũndũ naĩtye, Tei ũkaakĩka tene na tene; Kĩthito kyaku ũkakĩlũlũmĩlya matunĩ nthĩnĩ.'),
('kam', 'PSA', 89, 3, 'Nĩtianĩĩte ũtianĩo na mũnyuvwa wakwa, Nĩmwĩavĩĩte Ndaviti mũthũkũmi wakwa:'),
('kam', 'PSA', 89, 4, 'Ũsyao waku ngoolũlũmĩlya tene na tene, Na kwaka kĩvĩla kyaku kya ũsumbĩ kũvika nzyawa syonthe.'),
('kam', 'PSA', 89, 5, 'Na matu makataĩa moseng’yo maku, we Yeova; O na kĩthito kyaku ũmbanonĩ wa ala atheu.'),
('kam', 'PSA', 89, 6, 'Nũndũ nũũ matunĩ ũla ũtonya kũelekanw’a na Yeova? Nũũ katĩ wa ana ma ala me ũtonyi ũilyĩ Yeova,'),
('kam', 'PSA', 89, 7, 'Ngai ũla wa kũtĩsya mũno nzamanĩ ya ala atheu, Na wa ũkĩwa kũvĩtũka onthe ala mamũthyũlũlũkĩte?'),
('kam', 'PSA', 89, 8, 'We Yeova Ngai wa nguthu, Nũũ ũla wĩ ũtonyi, ũilyĩ taku, we Yeova? Na kĩthito kyaku nĩkĩkũthyũlũlũkĩte.'),
('kam', 'PSA', 89, 9, 'Nũsumbĩkaa ngathĩĩo ya ũkanga: Yĩla itulumo syaw’o syũkĩlaa, nĩwivindĩthasya.'),
('kam', 'PSA', 89, 10, 'Nũtũlangĩte Laavi ilungu, ta ũmwe wũaĩtwe; Nũnyaĩĩkĩtye amaitha maku na kw’oko kwa vinya waku.'),
('kam', 'PSA', 89, 11, 'Matu nĩ maku, nthĩ nayo nĩ yaku: Nthĩ na wasũu wayo, nue wasyambĩlĩlye.'),
('kam', 'PSA', 89, 12, 'Ngalĩ ya ĩũlũ na ngalĩ ya ĩtheo, nue wasyũmbie: Tavoli na Elimoni nitanaa syĩtwanĩ yaku.'),
('kam', 'PSA', 89, 13, 'Wĩ na kw’oko kwĩ ũtonyi; Kw’oko kwaku kwĩ vinya, na kw’oko kwaku kwa aũme nĩ kũtũlu.'),
('kam', 'PSA', 89, 14, 'Ũlũngalu na sila wa katĩ nĩsyo wambĩlĩlyo wa kĩvĩla kyaku kya ũsumbĩ: Ũseo wĩ wendo na w’o niendaa mbee wa ũthyũ waku.'),
('kam', 'PSA', 89, 15, 'Kũathimwa nĩ andũ ala mesĩ wasya wa ũtanu: Nĩmaendaa kyeninĩ kya ũthyũ waku, we Yeova.'),
('kam', 'PSA', 89, 16, 'Nĩmatanaa syĩtwanĩ yaku mũthenya w’onthe; Na nĩmanenevaw’a ũlũngalunĩ waku'),
('kam', 'PSA', 89, 17, 'Nũndũ nue ndaĩa ya vinya woo; Na ũseonĩ waku ũvya witũ ũkanenevw’a.'),
('kam', 'PSA', 89, 18, 'Nũndũ ngao yaitũ nĩ ya Yeova; Na mũsumbĩ waitũ nĩ wa Ũla Mũtheu wa Isilaeli.'),
('kam', 'PSA', 89, 19, 'Nĩvo ĩndĩ waneenie na atheu maku woninĩ, Na wasya, Niĩte ũtethyo ĩũlũ wa ũmwe wĩ ũtonyi; Nĩnenevetye ũmwe ũnyuvĩtwe andũnĩ.'),
('kam', 'PSA', 89, 20, 'Nĩnonete Ndaviti mũthũkũmi wakwa; Nĩmwĩtĩkĩĩtye mauta makwa matheu:'),
('kam', 'PSA', 89, 21, 'Ũla kw’oko kwakwa kũkalũlũmĩlya; O na kw’oko kwakwa kũkamwĩkĩa vinya.'),
('kam', 'PSA', 89, 22, 'Mũmaitha ndakamũng’endea, Kana mwana wa ũthũku kũmũthĩn’ya.'),
('kam', 'PSA', 89, 23, 'Na ngakũnĩa nthũ syake mbee wake ivalũke nthĩ, Na kũmakũna ala mamũmenaa.'),
('kam', 'PSA', 89, 24, 'Ĩndĩ kĩthito kyakwa na ũseo wakwa wĩ wendo ikeethĩwa nake; Na syĩtwanĩ yakwa ũvya wake ũkanenevw’a.'),
('kam', 'PSA', 89, 25, 'O na ngailĩĩla kw’oko kwake ũkanganĩ, Na kw’oko kwake kwa aũme mbũsĩnĩ.'),
('kam', 'PSA', 89, 26, 'Akeengaĩla, Nue Ĩthe wakwa, Ngai wakwa, na ĩvĩa ya ũtangĩĩo wakwa.'),
('kam', 'PSA', 89, 27, 'O na ngamũtw’ĩkĩthya mũsyawa wakwa wa mbee, Ũla wĩ ĩũlũ wa asumbĩ ma nthĩ.'),
('kam', 'PSA', 89, 28, 'Ũseo wakwa wĩ wendo ngekalya kwondũ wake tene na tene; Na ũtianĩo wakwa nake ũkalũma.'),
('kam', 'PSA', 89, 29, 'Ũsyao wake naw’o ngatuma wĩkala tene na tene, Na kĩvĩla kyake kya ũsumbĩ ta mĩthenya ya ĩtu.'),
('kam', 'PSA', 89, 30, 'Ethĩwa syana syake ikatia mĩao yakwa, Na itikaenda motw’ĩonĩ makwa;'),
('kam', 'PSA', 89, 31, 'Ethĩwa ikatũla myamũlo yakwa, Na itiũkwata mĩao yakwa;'),
('kam', 'PSA', 89, 32, 'Nĩvo ĩndĩ ngasilĩla ĩvĩtyo yoo na ndata, Na ũthũku woo na makũna.'),
('kam', 'PSA', 89, 33, 'Ĩndĩ ũseo wakwa wĩ wendo ndikaumya kwake vyũ, Kana kũeka kĩthito kyakwa kĩthele.'),
('kam', 'PSA', 89, 34, 'Ũtianĩo wakwa ndikawananga, Kana kũalyũla ũndũ wumĩte ilomonĩ syakwa.'),
('kam', 'PSA', 89, 35, 'Nĩvĩtĩte o ĩmwe na ũtheu wakwa: Ndikamũtavya Ndaviti ũvũngũ:'),
('kam', 'PSA', 89, 36, 'Ũsyao wake ũkekalaa tene na tene, Na kĩvĩla kyake kya ũsumbĩ ta syũa mbee wakwa.'),
('kam', 'PSA', 89, 37, 'Kĩkalũlũmĩlw’a ta mwei tene na tene, Na ta ũkũsĩ wĩ kĩthito ĩtunĩ.'),
('kam', 'PSA', 89, 38, 'Ĩndĩ nĩwekisye ũtee na walea, Wĩthĩĩtwe ũthilĩkĩle mwĩtĩkĩw’a mauta waku.'),
('kam', 'PSA', 89, 39, 'Nũthĩthĩte ũtianĩo wa mũthũkũmi waku: Nũvukĩtye ngovia yake ya ũsumbĩ ũndũ wa kũmĩkya nthĩ.'),
('kam', 'PSA', 89, 40, 'Nĩwanangĩte mbiio syake syonthe; Nũtw’ĩkĩthĩtye ngome syake syĩ vinya moomboku.'),
('kam', 'PSA', 89, 41, 'Onthe ala mavĩtĩlaa nzĩanĩ makĩmũvuta: Nũtw’ĩkĩte wa kũvũthw’a nĩ atũi make.'),
('kam', 'PSA', 89, 42, 'Nũnenevetye kw’oko kwa aũme kwa nthũ syake; Nũtumĩte amaitha make onthe matana.'),
('kam', 'PSA', 89, 43, 'Ĩĩ, nũũtũnga ũvyũ wake, Na ndwaatuma aũngama kaũnĩ.'),
('kam', 'PSA', 89, 44, 'Nũtumĩte ũtisu wake ũthela, Na kwĩkya nthĩ kĩvĩla kyake kya ũsumbĩ.'),
('kam', 'PSA', 89, 45, 'Nũkuvĩvĩtye mĩthenya ya wana wake: Nũmũvw’ĩkĩte nthoni.'),
('kam', 'PSA', 89, 46, 'Nĩ ĩvinda yĩana ata, ame Yeova? Ũkeevitha kũvika tene na tene? Ũthilĩku waku ũkaakana ta mwaki kũvika ĩndĩĩ?'),
('kam', 'PSA', 89, 47, 'Ame lilikana ũndũ ĩvinda yakwa yĩkuvĩvĩte: Kaĩ ũmbĩte ana onthe ma andũ mana!'),
('kam', 'PSA', 89, 48, 'Mũndũ nĩ wĩva ũla ũkekalaa thayũ na ndakona kĩkw’ũ, Ũla ũkavonokya thayũ wake kuma vinyanĩ wa Seoli?'),
('kam', 'PSA', 89, 49, 'Mwĩaĩi, moseo maku me wendo ma tene maĩva, Ala wamwĩavĩe Ndaviti kĩthitonĩ kyaku?'),
('kam', 'PSA', 89, 50, 'Mwĩaĩi, lilikana kũvũthw’a kwa athũkũmi maku; Ũndũ nĩkuaa kĩthũinĩ kyakwa kũvũthw’a nĩ ngo syonthe sya andũ syĩ ũtonyi,'),
('kam', 'PSA', 89, 51, 'Kũla amaitha maku mavũthĩtye nakw’o, we Yeova, Kũla mavũthĩtye matambya ma mwĩtĩkĩw’a mauta waku.'),
('kam', 'PSA', 89, 52, 'Nataĩwe Yeova tene na tene. Ameni, na Ameni.'),
('kam', 'PSA', 90, 1, 'Mwĩaĩi, wĩthĩĩtwe ũtũo witũ Nzyawanĩ syonthe.'),
('kam', 'PSA', 90, 2, 'Ĩĩma itanamba kumĩlw’a, Kana ũtanamba kũmba mũthanga na nthĩ, O kuma tene na tene kũvika tene na tene, nue Ngai.'),
('kam', 'PSA', 90, 3, 'Nũmũtũngaa mũndũ ethĩwe kĩtoo, Na kwasya, Syokai, inyw’ĩ ana ma andũ.'),
('kam', 'PSA', 90, 4, 'Nũndũ myaka ngili methonĩ maku Nĩ ta ĩoo yĩla ĩvĩtu, Na ta ũsyaĩĩsyo wa ũtukũ.'),
('kam', 'PSA', 90, 5, 'Nũũmatwaa ta matwaĩtwe nĩ manzĩ maingĩ; nao nĩ ta akomu: Kĩoko mailyĩ nyeki ila syĩanaa.'),
('kam', 'PSA', 90, 6, 'Kĩoko nikwaĩla, na kwĩana; Wĩoo niũtilwa na kũma.'),
('kam', 'PSA', 90, 7, 'Nũndũ nĩtũminĩtwe ũthatunĩ waku, Na nĩtũthĩnĩtw’e ũthilĩkunĩ waku.'),
('kam', 'PSA', 90, 8, 'Nĩwiĩte mothũku maitũ mbee waku, Na naĩ sitũ sya kĩmbithĩ kyeninĩ kya ũthyũ waku.'),
('kam', 'PSA', 90, 9, 'Nũndũ mĩthenya yaitũ yonthe nĩthelele ũthilĩkunĩ waku: Nĩtũkũmina myaka yaitũ ta kũvevũũka.'),
('kam', 'PSA', 90, 10, 'Mĩthenya ya myaka yaitũ nĩ myaka mĩongo mũonza, Kana ũla wĩ na vinya myaka mĩongo nyanya; Ĩndĩ ngathĩĩo yayo no wĩa na woo; Nũndũ nĩnĩũthela mĩtũkĩ, na ithyĩ nĩtũkũvĩta.'),
('kam', 'PSA', 90, 11, 'Nũũ wĩsĩ vinya wa ũthatu waku, Na ũthilĩku waku kwĩanana na kũkĩwa kũla kũkwaĩla?'),
('kam', 'PSA', 90, 12, 'Tũmanyĩsye kũtala mĩthenya yaitũ, Nĩ kana twĩyosee ngoo yĩ ũĩ.'),
('kam', 'PSA', 90, 13, 'Syoka, ame Yeova; nĩ ĩvinda yĩana ata? Ĩalyũle ũndũ wa athũkũmi maku.'),
('kam', 'PSA', 90, 14, 'Ame tũvũn’ye kĩoko na ũseo waku wĩ wendo, Nĩ kana tũtane na kwĩw’a mũyo mĩthenya yaitũ yonthe.'),
('kam', 'PSA', 90, 15, 'Tũtan’ye kwĩanana na mĩthenya ĩla ũtũthĩnĩtye, Na myaka ĩla twonete ũthũku.'),
('kam', 'PSA', 90, 16, 'Wĩa waku nũmaumĩlĩle athũkũmi maku, Na ũtheu mũtisu waku syana syoo.'),
('kam', 'PSA', 90, 17, 'Na ũseo wa Mwĩaĩi Ngai waitũ wĩthĩwe ĩũlũ waitũ; Na lũlũmĩlya wĩa wa moko maitũ kwitũ; Ĩĩ, wĩa wa moko maitũ ũlũlũmĩlye.'),
('kam', 'PSA', 91, 1, 'Ũla ũtũaa wĩvithonĩ wa Ũla Wĩ Ĩũlũ wa Onthe Ũsu akekalaa muunyĩnĩ wa Mwene Vinya W’onthe.'),
('kam', 'PSA', 91, 2, 'Nganeena ũndũ wa Yeova, Nĩwe wĩvitho wakwa na ngome yakwa yi vinya; Ngai wakwa, ũla nĩmũĩkĩĩaa.'),
('kam', 'PSA', 91, 3, 'Nũndũ akakũvonokasya kĩteinĩ kya mũtei wa nyũnyi, Na mũimũnĩ ũla wũaaa.'),
('kam', 'PSA', 91, 4, 'Akakũvw’ĩkĩaa na nzĩa syake, Na ũkeevithaa ungu wa nthwau syake: W’o wake nĩw’o ngao na kakalo.'),
('kam', 'PSA', 91, 5, 'Ndũkakĩa ũtĩsyo wa ũtukũ, Kana mũsyĩ ũla wĩkaw’a mũthenya;'),
('kam', 'PSA', 91, 6, 'Kana mũimũ ũla ũendaa kĩvindunĩ, Kana wanangĩko ũla wanangaa syũa yaũngama.'),
('kam', 'PSA', 91, 7, 'Andũ ngili makavalũka ũtee waku, Na ngili ĩkũmi kw’okonĩ kwaku kwa aũme; Ĩndĩ ndũkakũthengeea.'),
('kam', 'PSA', 91, 8, 'Ĩndĩ ũkasiasya na metho maku mwene, Na ũkoona wĩĩvanĩsyo wa ala athe.'),
('kam', 'PSA', 91, 9, 'Nũndũ waisye, Yeova nĩwe wĩvitho wakwa! Wamũtwie Ũla Wĩ Ĩũlũ wa Onthe ũtũo waku;'),
('kam', 'PSA', 91, 10, 'Vati ũthũku o na wiva ũkaũvalũkĩla, Kana ũthĩn’yo o na wĩva ũkathengeea ĩeema yaku.'),
('kam', 'PSA', 91, 11, 'Nũndũ akeeaĩa alaĩka make, Makũsũvĩe nzĩanĩ syaku syonthe.'),
('kam', 'PSA', 91, 12, 'Makakũkĩlya mokonĩ moo, Ndũkese ũtulw’a kũũ kwaku nĩ ĩvia.'),
('kam', 'PSA', 91, 13, 'Ũkakinyanga mũnyambũ na kĩmbuva: Mũnyambũ wa mũika na nzoka ũkaikinyangĩa nthĩ.'),
('kam', 'PSA', 91, 14, 'Nĩkwĩthĩwa nũlũlũmĩlĩtye wendo wake vala nĩĩ, kwondũ wa ũu ngamũvonokya: Ngamũtũlya, nĩkwĩthĩwa nũmanyĩte syĩtwa yakwa.'),
('kam', 'PSA', 91, 15, 'Akeengaĩla, nakwa ngamũsũngĩa; Ũnyamaonĩ ngeethĩwa nake: Ngamũvonokya, na kũmũnenevya.'),
('kam', 'PSA', 91, 16, 'Ngamũkolya na thayũ mũasa, Na ngamwon’ya ũtangĩĩo wakwa.'),
('kam', 'PSA', 92, 1, 'Nĩ ũndũ ũseo kũmũtũngĩa Yeova mũvea, Na kwina tũkĩkumya syĩtwa yake, we Ũla Wĩ Ĩũlũ wa Onthe;'),
('kam', 'PSA', 92, 2, 'Kwonan’ya ũseo wake wĩ wendo kĩoko, Na kĩthito kyake kĩla ũtukũ,'),
('kam', 'PSA', 92, 3, 'Na kindũ kya kũinga kĩ na ndii ĩkũmi, na kĩnanda; Na wasya mũuu mbevenĩ.'),
('kam', 'PSA', 92, 4, 'Nũndũ we, Yeova, nũndanĩthisye kwondũ wa wĩa waku: Ngakĩlya vinya mawĩanĩ ma moko maku.'),
('kam', 'PSA', 92, 5, 'Mawĩa maku kaĩ nĩ manene, we Yeova! Mosũanĩo maku nĩ maliku mũno.'),
('kam', 'PSA', 92, 6, 'Mũndũ ũilyĩ ta nyamũ ndamanyaa; O na ndia ndĩmanyaa ũu:'),
('kam', 'PSA', 92, 7, 'Yĩla athũku maumĩlanga ta nyeki, Na yĩla onthe ala mekaa ũthũku maĩlaa; Ũu wĩthĩawa nĩ kana makanangwa tene na tene.'),
('kam', 'PSA', 92, 8, 'Ĩndĩ we, ame Yeova, wĩ ĩũlũ tene na tene.'),
('kam', 'PSA', 92, 9, 'Nũndũ, sisya, amaitha maku, we Yeova, Nũndũ, sisya, amaitha maku makaaa; Onthe ala mekaa ũthũku makanyaĩĩkw’a.'),
('kam', 'PSA', 92, 10, 'Ĩndĩ ũvya wakwa nĩwũnenevetye ta ũvya wa mboo: Nyie nĩnĩtĩkĩĩtw’e mauta ma mĩtũkĩ.'),
('kam', 'PSA', 92, 11, 'Itho yakwa nayo nĩyonete kwenda kwakwa amaithanĩ makwa, Matũ makwa nĩmew’ĩte kwenda kwakwa kwa eki ma naĩ ala mambũkĩlĩĩlaa.'),
('kam', 'PSA', 92, 12, 'Ũla mũlũngalu akaaĩla ta mũtende: Akeana ta mũti wa mũkũũ Levanoni.'),
('kam', 'PSA', 92, 13, 'Nao nĩmavandĩtwe nyũmbanĩ ya Yeova; Makaathimĩka me nza sya Ngai waitũ.'),
('kam', 'PSA', 92, 14, 'Makasyaaa ũsyao me akũu; Makeethĩwa mausũĩtwe nĩ ngoyoo na ũthithinĩu:'),
('kam', 'PSA', 92, 15, 'Nĩ kana kwonanw’e Yeova nĩ mũlũngalu; Nake nĩ ĩvia yakwa, na vati ũndũ ũte ũlũngalu nthĩnĩ wake.'),
('kam', 'PSA', 93, 1, 'Yeova nũsumbĩkaa; nĩwĩvw’ĩkĩte ũnene; Yeova nĩwĩvw’ĩkĩte vinya; nũwĩvotoete: Nthĩ nayo nĩlũmĩte, ũndũ ĩtatonya kũthingithw’a.'),
('kam', 'PSA', 93, 2, 'Kĩvĩla kyaku kya ũsumbĩ nĩkĩlũmĩte kuma tene: Naku wĩ vo kuma tene na tene.'),
('kam', 'PSA', 93, 3, 'Manzĩ maingĩ nĩmokĩlĩte, we Yeova, Manzĩ maingĩ nĩmokĩlĩtye wasya wamo; Manzĩ maingĩ nĩmokĩlasya itulumo syamo.'),
('kam', 'PSA', 93, 4, 'Ĩũlũ wa mawasya ma iw’ũ nyingĩ, Itulumo syĩ vinya sya ũkanga, Yeova ĩũlũ nĩ mwene ũtonyi.'),
('kam', 'PSA', 93, 5, 'Mokũsĩ maku nĩ ma w’o ki: Ũtheu nĩwaĩle nyũmbanĩ yaku, We Yeova, kũvika tene na tene.'),
('kam', 'PSA', 94, 1, 'We Yeova, Ngai mwene ũĩvanĩsyo, We Ngai mwene ũĩvanĩsyo, tisũka.'),
('kam', 'PSA', 94, 2, 'Ĩyũkĩlye, we mũsili wa nthĩ: Manenge ekathĩĩi ũndũ ũmaĩle.'),
('kam', 'PSA', 94, 3, 'Yeova, nĩ ĩvinda yĩana ata ala athũku, Nĩ ĩvinda yĩana ata ala athũku makakĩlya vinya?'),
('kam', 'PSA', 94, 4, 'Nĩmavulũkaa, nĩmaneenaa na wĩtũlyo: Onthe ala mekaa ũthũku nĩmekathĩĩaa.'),
('kam', 'PSA', 94, 5, 'Nĩmatilangaa ilungu andũ maku, Yeova, Na kũthĩn’ya ũtiĩwa waku.'),
('kam', 'PSA', 94, 6, 'Nĩmooaa ndiwa na mwĩkali wa ũeninĩ, Na kũaa ala makw’ĩĩwe nĩ aaĩthe.'),
('kam', 'PSA', 94, 7, 'Na maasya, Yeova ndakona, O na Ngai wa Yakovo ndakasũanĩa.'),
('kam', 'PSA', 94, 8, 'Sũanĩai, inyw’ĩ mũilyĩ ta nyamũ katĩ wa andũ; Na inyw’ĩ ndia, mũkoĩva ĩndĩĩ?'),
('kam', 'PSA', 94, 9, 'Ũla waiie kũtũ, ndakew’a? Ũla wombie itho, ndakona?'),
('kam', 'PSA', 94, 10, 'Ũla ũkũnaa i mbaĩ, ndakonan’ya mavĩtyo, O ũla ũmanyĩasya mũndũ ũĩ?'),
('kam', 'PSA', 94, 11, 'Yeova nĩwĩsĩ mosũanĩo ma mũndũ, Kana nĩ ma mana.'),
('kam', 'PSA', 94, 12, 'We Yeova, nĩ mũathime mũndũ ũla ũmũkũnaa, Na kũmũmanyĩsya kuma mĩaonĩ yaku;'),
('kam', 'PSA', 94, 13, 'Nĩ kana ũmũthũmũsye aume mĩthenyanĩ ya thĩna, Kũvika yĩla ĩima yĩĩnzwa ũndũ wa ala athũku.'),
('kam', 'PSA', 94, 14, 'Nũndũ Yeova ndakekya ũtee andũ make, O na ndakatia ũtiĩwa wake.'),
('kam', 'PSA', 94, 15, 'Nũndũ ũsilĩlo ũkasyokea ũlũngalu; Na onthe alũngalu ngoonĩ makooatĩĩa.'),
('kam', 'PSA', 94, 16, 'Nũũ ũla wĩũkĩla ũndũ wakwa kwondũ wa eki ma naĩ? Nũũ ũla wĩnũngamĩa kwondũ wa ala mekaa ũthũku?'),
('kam', 'PSA', 94, 17, 'Kethĩwa Yeova ndaaĩthĩwa mũtethya wakwa, Mĩtũkĩ thayũ wakwa wĩthĩwa wakililye.'),
('kam', 'PSA', 94, 18, 'Yĩla naisye, Kũũ kwakwa nĩkwatendelũka; Ũseo waku wĩ wendo nĩwandw’ĩĩkie, we Yeova.'),
('kam', 'PSA', 94, 19, 'Mosũanĩonĩ makwa maingĩ nthĩnĩ wakwa Mokiakisyo maku matan’ya ngoo yakwa.'),
('kam', 'PSA', 94, 20, 'Kĩvĩla kya ũsumbĩ kya ũthũku kĩkeethĩwa mũamba naku, Kĩla kĩkaa ũthũku kwondũ wa mwamũlo?'),
('kam', 'PSA', 94, 21, 'Nĩmeyũmbanĩasya thayũ wa ala alũngalu, Na kũtw’ĩa sila nthakame ĩte ĩvĩtyo.'),
('kam', 'PSA', 94, 22, 'Ĩndĩ Yeova wĩthĩĩtwe mwako wakwa mũtũlu wa mũnyoolo, Na Ngai wakwa ĩvia ya wĩvitho wakwa.'),
('kam', 'PSA', 94, 23, 'Na nũmaetee ũthũku woo ene, Na akamaveta me ũthũkunĩ woo ene; Yeova Ngai waitũ akamaveta.'),
('kam', 'PSA', 95, 1, 'Inyw’ĩ ũkai, tũmwinĩei Yeova; Tũkĩlĩlyei wasya wa ũtanu ĩvia ya ũtangĩĩo witũ.'),
('kam', 'PSA', 95, 2, 'Tũke mbee wake twĩ na mũvea; Tũmũkĩlĩlyei wasya wa ũtanu na mbathi sya ndaĩa.'),
('kam', 'PSA', 95, 3, 'Nũndũ Yeova nĩ Ngai mũnene, Na Mũsumbĩ mũnene kwĩ i ngai.'),
('kam', 'PSA', 95, 4, 'Kũndũ kũliku kwa nthĩ kwĩ kw’okonĩ kwake; Motũlu ma iĩma namo nĩ make.'),
('kam', 'PSA', 95, 5, 'Ũkanga nĩ wake, nĩwe wawũmbie; Na moko make nĩmo moombie nthĩ nyũmũ.'),
('kam', 'PSA', 95, 6, 'Inyw’ĩ ũkai, tũthaithe na kwĩkunamya; Tũmũtulĩlyei ndu Yeova Mũmbi waitũ:'),
('kam', 'PSA', 95, 7, 'Nũndũ nĩwe Ngai waitũ, Na ithyi twĩ andũ ma ĩĩthya yake, na malondu ma kw’oko kwake. Ũmũnthĩ, ethĩwa nĩmũkwĩw’a wasya wake,'),
('kam', 'PSA', 95, 8, 'Mũikomye ngoo syenyu, ta vu Meliva, Ta mũthenya wa Masa weũnĩ;'),
('kam', 'PSA', 95, 9, 'Yĩla aaĩthe menyu mandatie Makĩnguũa, na moona wĩa wakwa.'),
('kam', 'PSA', 95, 10, 'Myaka mĩongo ĩna nĩneew’ĩthiw’e woo nĩ ũsyao ũsu, Na nasya, Nĩ ũko wa andũ ala mavĩtasya ngoonĩ syoo, Na matyeesĩ nzĩa syakwa:'),
('kam', 'PSA', 95, 11, 'Kwondũ wa ũu nĩneevĩtie ũthilĩkunĩ wakwa, Matikalika ũthũmũonĩ wakwa.'),
('kam', 'PSA', 96, 1, 'Mwinĩei Yeova wathi weũ: Nthĩ yonthe, mwinĩei Yeova.'),
('kam', 'PSA', 96, 2, 'Mwinĩei Yeova, taĩai syĩtwa yake; Onan’yai ũtangĩĩo wake mũthenya na mũthenya.'),
('kam', 'PSA', 96, 3, 'Tavan’yai ũtheu mũtisu wake katĩ wa i mbaĩ, Mawĩa make ma ũseng’ya katĩ wa ngo syonthe sya andũ.'),
('kam', 'PSA', 96, 4, 'Nũndũ Yeova nĩ mũnene, na nĩ wa kũtaĩwa mũno: Nĩ wa ũkĩwa kũvĩtũka ngai syonthe.'),
('kam', 'PSA', 96, 5, 'Nũndũ ngai syonthe sya ngo sya andũ nĩ mĩvw’anano; Ĩndĩ Yeova nĩwombie matu.'),
('kam', 'PSA', 96, 6, 'Ndaĩa na ũnene syĩ mbee wake: Vinya na wanakavye syĩ nthĩnĩ wa vala vandũ vake vatheu.'),
('kam', 'PSA', 96, 7, 'Mũwetei Yeova, inyw’ĩ mĩvĩa ya ngo sya andũ, Mũwetei Yeova ndaĩa na vinya.'),
('kam', 'PSA', 96, 8, 'Mũnengei Yeova ndaĩa ĩla yaĩlĩte syĩtwa yake: Etei nthembo, na mũkyũka nthĩnĩ wa nza syake.'),
('kam', 'PSA', 96, 9, 'Mũthaithei Yeova na ũseo wa ũtheu: Nthĩ yonthe, tetemeai mbee wake.'),
('kam', 'PSA', 96, 10, 'Neenai katĩ wa i mbaĩ, Yeova nũsumbĩkaa: Nthĩ nayo nĩlũmĩtw’e ũndũ ĩtatonya kũthingithw’a: Akasilan’ya ngo sya andũ na ũlũngalu.'),
('kam', 'PSA', 96, 11, 'Matu nĩmatane, na nthĩ yĩw’e mũyo; Ũkanga nũlitũke, na wusũu waw’o;'),
('kam', 'PSA', 96, 12, 'Mũũnda nũtane, na kyonthe kĩla kĩ nthĩnĩ waw’o; Nĩvo mĩtĩ yonthe ya mũtitũnĩ ĩkaina nũndũ wa ũtanu'),
('kam', 'PSA', 96, 13, 'Mbee wa Yeova; nũndũ nĩwũkĩte, Nũndũ nĩwũkĩte asilĩle nthĩ: Akasilĩla nthĩ na ũlũngalu, Na ngo sya andũ na w’o wake.'),
('kam', 'PSA', 97, 1, 'Yeova nũsumbĩkaa; nthĩ nĩyĩw’e mũyo; Wingĩ wa ithama ũtane.'),
('kam', 'PSA', 97, 2, 'Mathweo na kĩvindu nimũthyũlũlũkĩte: Ũlũnglu na sila wa katĩ nĩ wambĩlĩlyo wa kĩvĩla kyake kya ũsumbĩ.'),
('kam', 'PSA', 97, 3, 'Mwaki nũendaa mbee wake, Ũkĩvĩvya nthũ syake ngalĩ syonthe.'),
('kam', 'PSA', 97, 4, 'Motisi make nĩmamulĩkile nthĩ: Nthĩ yoona na yatetema.'),
('kam', 'PSA', 97, 5, 'Iĩma syatweka ta ĩseso vala ve Yeova, Vala ve Mwĩaĩi wa nthĩ yonthe.'),
('kam', 'PSA', 97, 6, 'Matu nĩmatavanasya ũlũngalu wake, Na ngo syonthe sya andũ nĩsyonete ũnene wake.'),
('kam', 'PSA', 97, 7, 'Onthe ala mathũkũmaa mĩvw’anano myasũvye nĩmasonokw’e, Ala mekathĩĩaa ũndũ wa mĩvw’anano; Mũthaithei, inyw’ĩ ngai syonthe.'),
('kam', 'PSA', 97, 8, 'Saioni nĩkyeewie na kyatana, Na eĩtu ma Yuta nĩmeewie mũyo, Nũndũ wa mosilĩlo maku, we Yeova.'),
('kam', 'PSA', 97, 9, 'Nũndũ we, Yeova, wĩ ĩũlũ mũno mbee wa nthĩ yonthe: Nũnenevetw’e ĩũlũ mũno wa ngai syonthe.'),
('kam', 'PSA', 97, 10, 'Inyw’ĩ ala mũmwendaa Yeova, menai ũthũku: Nũsũvĩaa ngoo sya atheu make; Nũmavonokasya kuma kw’okonĩ kwa ala athũku.'),
('kam', 'PSA', 97, 11, 'Kyeni nĩkĩvuĩĩtwe kwondũ wa ala alũngalu, Na ũtanu kwondũ wa ala alũngalu ngoonĩ.'),
('kam', 'PSA', 97, 12, 'Ĩthĩwai na mũyo nthĩnĩ wa Yeova, inyw’ĩ alũngalu; Na tũngĩai mũvea syĩtwa yake ĩtheu ya ũlilikan’yo.'),
('kam', 'PSA', 98, 1, 'Mwinĩei Mwĩaĩi wathi weũ; Nũndũ nĩwĩkĩte maũndũ ma ũseng’ya: Kw’oko kwake kwa aũme, o kw’oko kwake kũtheu, nĩkũtethetye wĩa wa kũtangĩĩa kwondũ wake.'),
('kam', 'PSA', 98, 2, 'Yeova nũmanyĩthanĩtye ũtangĩĩo wake: Ũlũngalu wake nĩwonanĩtye ũtheinĩ i mbaĩ syene.'),
('kam', 'PSA', 98, 3, 'Nũlilikanĩte ũseo wake wĩ wendo na kĩthito kyake kyelekele nyũmba ya Isilaeli: Itulu syonthe sya nthĩ nĩsyonete ũtangĩĩo wa Ngai waitũ.'),
('kam', 'PSA', 98, 4, 'Ũkĩlĩlyai Yeova wasya wa ũtanu, nthĩ yonthe: Ambĩlĩlyai kwina nũndũ wa ũtanu, ĩĩ, inai mũkĩtaĩa.'),
('kam', 'PSA', 98, 5, 'Inĩai Yeova mũkĩmũkumya mwĩ na mbeve; Mwĩ na mbeve na wasya wĩ mũyo.'),
('kam', 'PSA', 98, 6, 'Mwĩ na masoo na wasya wa soo mũkelemu Ũkĩlyai wasya wa ũtanu mbee wa Mũsumbĩ, Yeova.'),
('kam', 'PSA', 98, 7, 'Ũkanga nũlitũke, na wusũu waw’o; Nthĩ, na ala mamĩtwĩe;'),
('kam', 'PSA', 98, 8, 'Manzĩ maingĩ makũnangan’ye mbĩ syamo; Tũlĩma nĩtwine vamwe nũndũ wa ũtanu'),
('kam', 'PSA', 98, 9, 'Mbee wa Yeova; nũndũ nĩwũkĩte asilĩle nthĩ: Akasilĩla nthĩ na ũlũngalu, Na ngo sya andũ na w’o wake.'),
('kam', 'PSA', 99, 1, 'Yeova nũsumbĩkaa; ngo sya andũ iteteme: Nĩwĩkalaa ĩũlũ wa akeluvi; nthĩ nĩthingithangw’e.'),
('kam', 'PSA', 99, 2, 'Yeova nĩ mũnene ku Saioni; Nake e ĩũlũ mũno wa ngo syonthe sya andũ.'),
('kam', 'PSA', 99, 3, 'Nitaĩe syĩtwa yaku ĩnene na ya ũtĩsya: Nake nĩ mũtheu.'),
('kam', 'PSA', 99, 4, 'Vinya wa mũsumbĩ naw’o nĩwendaa sila wa katĩ; Nũlũmasya ũlũngalu; Nũsilaa sila wa katĩ na wa ũlũngalu nthĩnĩ wa Yakovo.'),
('kam', 'PSA', 99, 5, 'Nenevyai Yeova Ngai waitũ, Na mũithaithĩa kĩvĩlanĩ kyake kya nyaĩĩ: Nake nĩ mũtheu.'),
('kam', 'PSA', 99, 6, 'Mose na Aluni amwe ma athembi make, Na Samueli ũmwe wa ala mekaĩlaa syĩtwa yake; Nao nĩmamwĩkaĩlaa Yeova, nake aimasũngĩa.'),
('kam', 'PSA', 99, 7, 'Aneenaa nao e nthĩnĩ wa kĩtuĩ kya mũumbĩ: Nao makwata mokũsĩ make, Na mwamũlo ũla wamanengie.'),
('kam', 'PSA', 99, 8, 'Nĩwamasũngĩie, we Yeova Ngai waitũ: Waĩ Ngai ũla wamaekeie, O na kau nĩweeĩvanĩsye ũndũ wa mĩkĩle yoo.'),
('kam', 'PSA', 99, 9, 'Nenevyai Yeova Ngai waitũ, Na mũithaithĩa kĩĩmanĩ kyake kĩtheu; Nũndũ Yeova Ngai waitũ nĩ mũtheu.'),
('kam', 'PSA', 100, 1, 'Ũkĩlĩlyei Yeova wasya wa ũtanu, inyw’ĩ nthĩ syonthe.'),
('kam', 'PSA', 100, 2, 'Mũthũkũmei Yeova na mũyo: Ũkai mbee wake mwinĩte.'),
('kam', 'PSA', 100, 3, 'Manyai kana Yeova nĩwe Ngai: Nĩwe ũla watũmbie, naitũ twĩ make; Twĩ andũ make, na twĩ malondu ma ĩĩthya yake.'),
('kam', 'PSA', 100, 4, 'Votelai mbingĩlonĩ syake mwĩ na mũvea, Na nthĩnĩ wa nza syake mwĩ na ndaĩa: Mũtũngĩei mũvea, na taĩai syĩtwa yake.'),
('kam', 'PSA', 100, 5, 'Nũndũ Yeova nĩ mũseo; ũseo wake wĩ wendo nĩwĩkalaa tene na tene, Na kĩthito kyake kwa nzyawa syonthe.'),
('kam', 'PSA', 101, 1, 'Ngaina ũndũ wa ũseo wĩ wendo na ũsili wa katĩ: Ngaina ngĩkũkumya, we Yeova.'),
('kam', 'PSA', 101, 2, 'Nyie ngeekaa na kĩlĩko mũendelenĩ mwĩanĩu: Ame ũkoka kwakwa ĩndĩĩ? Ngaendelaa nyũmbanĩ yakwa nĩ na ngoo mbĩanĩu.'),
('kam', 'PSA', 101, 3, 'Ndikaia kĩndũ kĩthũku mbee wa metho makwa: Nĩnĩmenaa wĩa wa ala mathũkaa ũtee; Ndũkalũman’ya nakwa.'),
('kam', 'PSA', 101, 4, 'Ngoo yĩ ngũlũ ĩkauma vala nĩĩ: Ndikamanya ũndũ ũthũku.'),
('kam', 'PSA', 101, 5, 'O ũla ũsukaa mũtũi wake na kĩmbithĩ, ũsu ngamwananga: Ũla wĩ na metho ma kwĩtũlya na ngoo ĩla ĩkathĩĩaa ndikomĩanĩsya nake.'),
('kam', 'PSA', 101, 6, 'Metho makwa makeethĩwa ĩũlũ wa ala me kĩthito ma ĩ nthĩ, nĩ kana matonye kũtũaa nakwa: Ũla ũendaa na mũendele mwĩanĩu, ũsu akanthũkũma.'),
('kam', 'PSA', 101, 7, 'Ũla ũkenganaa ndakatũa nyũmbanĩ yakwa: Ũla ũneenaa ũvũngũ ndakalũlũmĩlw’a mbee wa metho makwa.'),
('kam', 'PSA', 101, 8, 'Kĩoko na kĩoko ngaanangaa ala athũku onthe ma ĩ nthĩ; Nĩvete eki ma ũthũku onthe maume ndũanĩ ya Yeova.'),
('kam', 'PSA', 102, 1, 'Ĩw’a mboya yakwa, ame Yeova, Na kĩĩo kyakwa nĩkĩvike vala ũĩ.'),
('kam', 'PSA', 102, 2, 'Ndũkambithe ũthyũ waku mũthenya wa thĩna wakwa: Tea kũtũ kwaku; Mũthenya ũla nĩkaya wĩnzũngĩa mĩtũkĩ.'),
('kam', 'PSA', 102, 3, 'Nũndũ mĩthenya yakwa nĩnĩũthela ta syũki, Na mavĩndĩ makwa nĩmavĩe ta kĩsinga.'),
('kam', 'PSA', 102, 4, 'Ngoo yakwa nĩkũnĩtwe ta nyeki, na ĩkavova; Nũndũ nĩnũlawa nĩ kũya lĩu wakwa.'),
('kam', 'PSA', 102, 5, 'Nũndũ wa wasya wa kũluma kwakwa Mavĩndĩ makwa nĩmalũmanĩtye na nyama syakwa.'),
('kam', 'PSA', 102, 6, 'Nĩilyĩ ta ngunĩ ya weũnĩ; Nĩtw’ĩkĩte ta ndundu ya kũndũ kũtie.'),
('kam', 'PSA', 102, 7, 'Nĩnzyaĩĩasya, na nĩtw’ĩkĩte ta mũthoonzwe Wĩ w’oka ĩũlũ wa nyũmba.'),
('kam', 'PSA', 102, 8, 'Amaitha makwa mambũthasya mũthenya w’onthe; Ala manthatĩaa nĩmanumanĩaa.'),
('kam', 'PSA', 102, 9, 'Nũndũ nĩĩte mũu ta lĩu, Na kũvulan’ya kya ũnyw’a kyakwa na kĩĩo,'),
('kam', 'PSA', 102, 10, 'Nũndũ wa kũthilĩka kwaku na ũthatu waku: Nũndũ nũmbũkĩlĩtye, na kũmbĩkya ũtee.'),
('kam', 'PSA', 102, 11, 'Matukũ makwa mailyĩ ta muunyĩ ũla ũendeee; Na nĩnũmĩte ta nyeki.'),
('kam', 'PSA', 102, 12, 'Ĩndĩ we, ame Yeova, ũkekalaa tene na tene; Na syĩtwa yaku ya kũlilikanwa kũvika nzyawanĩ syonthe.'),
('kam', 'PSA', 102, 13, 'We ũkookĩla na kwĩw’ĩa Saioni tei; Nũndũ nĩ ĩvinda ya kũmĩw’ĩa tei, Ĩĩ, ĩvinda yĩla ĩtw’e nĩ ĩviku.'),
('kam', 'PSA', 102, 14, 'Nũndũ athũkũmi maku nĩmendeew’e nĩ mavia mayo, Na kwĩw’ĩa kĩtoo kyayo tei.'),
('kam', 'PSA', 102, 15, 'Kwondũ wa ũu i mbaĩ ikakĩa syĩtwa ya Yeova, Na asumbĩ onthe ma nthĩ makakĩa ũnene waku.'),
('kam', 'PSA', 102, 16, 'Nũndũ Yeova nĩwakĩte Saioni; Nĩwonekete ũtheunĩ mũtisu wake.'),
('kam', 'PSA', 102, 17, 'Nĩwĩtĩkĩlaa mboya ya ngya, Na ndavũthasya mboya syoo.'),
('kam', 'PSA', 102, 18, 'Ũũ ũkaandĩkwa kwondũ wa nzyawa ĩla yĩũka; Na andũ ala makasyawa makamũtaĩa Yeova.'),
('kam', 'PSA', 102, 19, 'Nũndũ nũsyaĩtye nthĩ e ũtũlunĩ wa vandũ vake vatheu; Yeova e ĩtunĩ nĩwasyaisye nthĩ;'),
('kam', 'PSA', 102, 20, 'Ew’e kũvevũũka kwa ũla mwove; Kũthasya asu ala matw’ĩĩwe kũkw’a;'),
('kam', 'PSA', 102, 21, 'Nĩ kana andũ matonye kũtavan’ya syĩtwa ya Yeova ku Saioni, Na ndaĩa yake ku Yelusaleme;'),
('kam', 'PSA', 102, 22, 'O yĩla ngo sya andũ ikũmbana, O na mosumbĩ, kũmũthũkũma Yeova.'),
('kam', 'PSA', 102, 23, 'Nĩwaolile vinya wakwa nzĩanĩ; Nĩwakuvĩvisye matukũ makwa.'),
('kam', 'PSA', 102, 24, 'Nasya, Ame Ngai wakwa, ndũkambete matukũ makwa me katĩ: Myaka yaku nĩendeeaa mosyaanĩonĩ onthe.'),
('kam', 'PSA', 102, 25, 'O tene tene we nĩwakwatisye wambĩlĩlyo wa nthĩ; Na matu nĩ wĩa wa moko maku.'),
('kam', 'PSA', 102, 26, 'Syo ikaaa, ĩndĩ we ũkekalaa; Ĩĩ, syo syonthe ikakũa ta ngũa; Ũkaikũan’ya o ta ngũa, nasyo ikakũanĩka:'),
('kam', 'PSA', 102, 27, 'Ĩndĩ nue ũla wĩkalaa o ũndũ ũmwe, Na myaka yaku ndĩkethĩwa na mũminũkĩlyo.'),
('kam', 'PSA', 102, 28, 'Syana sya athũkũmi maku ikaendeeaa, Na ũsyao woo ũkalũlũmĩlw’a mbee waku.'),
('kam', 'PSA', 103, 1, 'Mũtaĩe Yeova, we ngoo yakwa; Na syonthe ila syĩ nthĩnĩ wakwa, taĩai syĩtwa yake ĩtheu.'),
('kam', 'PSA', 103, 2, 'Mũtaĩe Yeova, we ngoo yakwa, Na ndũkolwe nĩ moseo make onthe:'),
('kam', 'PSA', 103, 3, 'Ũla ũkũekeeaa mothũku maku onthe; Ũla ũvoasya mowau maku onthe;'),
('kam', 'PSA', 103, 4, 'Ũla wovoasya thayũ waku kuma wanangĩkonĩ; Ũla ũkwĩkĩaa ngovia ya ũsumbĩ ya ũseo wĩ wendo na matei mololo;'),
('kam', 'PSA', 103, 5, 'Ũla ũvũnasya kwenda kwaku na maũndũ maseo, Kwondũ wa ũu wana waku nũtũngĩtwe mweũ ta ndiũ.'),
('kam', 'PSA', 103, 6, 'Yeova nĩwĩkaa meko malũngalu, Na kũtw’a mosilĩlo kwondũ wa onthe ala mathĩnaw’a.'),
('kam', 'PSA', 103, 7, 'Nĩwamanyĩthisye Mose nzĩa syake, Na syana sya Isilaeli meko make.'),
('kam', 'PSA', 103, 8, 'Yeova e tei na nĩ mũseo, Mũmĩĩsya wa kũthata, na e na ũseo wĩ wendo mwingĩ.'),
('kam', 'PSA', 103, 9, 'Ndakateta mavinda onthe; O na ndekalasya ũthatu wake tene na tene.'),
('kam', 'PSA', 103, 10, 'Ndatwĩkĩte kwĩanana na naĩ sitũ, Kana kũtũĩva kwĩanana na mothũku maitũ.'),
('kam', 'PSA', 103, 11, 'Nũndũ o tondũ matu me kũasa ĩũlũ wa nthĩ, Now’o ũnenevete ũseo wake wĩ wendo kwa ala mamũkĩaa.'),
('kam', 'PSA', 103, 12, 'O tondũ kũasavĩte kuma wumĩlonĩ wa syũa kũvika ũthũĩlonĩ wayo, Now’o ũvetete kũasa naitũ mothũku maitũ.'),
('kam', 'PSA', 103, 13, 'O tondũ ĩthe wĩw’ĩaa syana syake tei, Now’o Yeova ũmew’ĩaa tei ala mamũkĩaa.'),
('kam', 'PSA', 103, 14, 'Nũndũ nĩwĩsĩ wũmbe witũ; Nũlilikanaa kana twĩ kĩtoo.'),
('kam', 'PSA', 103, 15, 'Na ũndũ wa mũndũ, matukũ make no ta nyeki; O ta ĩlaa ya kĩthekanĩ, now’o waĩlaa.'),
('kam', 'PSA', 103, 16, 'Nũndũ kĩseve nĩkĩvĩtĩlaa ĩũlũ wayo, na yikyaa; Na vandũ vayo vatikayĩmanya ĩngĩ.'),
('kam', 'PSA', 103, 17, 'Ĩndĩ ũseo wĩ wendo wa Yeova nĩ kuma tene na tene kũvika tene na tene ĩũlũ wa ala mamũkĩaa, Na ũlũngalu wake wĩ kwa nzũkũlũ;'),
('kam', 'PSA', 103, 18, 'Kwa ala malũmasya ũtianĩo wake, Na kwa ala malilikanaa mawĩaĩo make mamekae.'),
('kam', 'PSA', 103, 19, 'Yeova nũlũlũmĩlye kĩvĩla kyake kya ũsumbĩ matunĩ; Na ũsumbĩ wake ũsumbĩkĩte ĩũlũ wa onthe.'),
('kam', 'PSA', 103, 20, 'Mũtaĩei Yeova, inyw’ĩ alaĩka make, Ala mwĩ ũtonyi vinyanĩ, ala mwĩanĩasya ndeto yake, Mũkĩw’a wasya wa ndeto yake.'),
('kam', 'PSA', 103, 21, 'Mũtaĩei Yeova, inyw’onthe nguthu syake, Athũkũmi make, ala mwĩkaa ũndũ ũla ũmwendeeasya.'),
('kam', 'PSA', 103, 22, 'Mũtaĩei Yeova, inyw’onthe mawĩa make, Kũndũ kw’onthe kwa ũsumbĩko wake: Taĩa Yeova, we ngoo yakwa.'),
('kam', 'PSA', 104, 1, 'Taĩa Yeova, we ngoo yakwa. We Yeova Ngai wakwa, wĩ mũnene mũno; Ũla ũvw’ĩkĩtwe nĩ ndaĩa na ũnene:'),
('kam', 'PSA', 104, 2, 'Ũla wĩvw’ĩkaa mwene kyeni ta kwĩvw’ĩka ngũa; Ũla ũtambũũkasya matu ta suka;'),
('kam', 'PSA', 104, 3, 'Ũla wiaa mĩamba ya tũsũmba twake manzĩnĩ; Ũla ũtw’ĩkĩthasya mathweo ĩkasya yake; Ũla ũkinyĩlaa ĩũlũ wa nthwau sya kĩseve;'),
('kam', 'PSA', 104, 4, 'Ũla ũtusaa iseve atũmwa make; Itw’ĩki sya mwaki athũkũmi make;'),
('kam', 'PSA', 104, 5, 'Ũla wambĩlĩlye myambĩlĩlyo ya nthĩ, Nĩ kana ndĩkathingithĩke tene na tene.'),
('kam', 'PSA', 104, 6, 'We nĩwamĩvw’ĩkie na kyũngũ ta kũvw’ĩka ngũa; Manzĩ mekala ĩũlũ wa iĩma.'),
('kam', 'PSA', 104, 7, 'Kwondũ wa ũkan’yo waku makĩa; Kwondũ wa wasya wa kĩtundumo kyaku meekalaata mathi'),
('kam', 'PSA', 104, 8, '(Iĩma syookĩla, syanda syalika) O kũvika vandũ vala wambĩlĩlye kwondũ wamo.'),
('kam', 'PSA', 104, 9, 'Nĩwiĩte mũvaka nĩ kana matikokĩle; Matikaasyoke ĩngĩ na kũvw’ĩka nthĩ.'),
('kam', 'PSA', 104, 10, 'Nĩwumĩlasya mbuluti sya manzĩ syandanĩ; Nĩmasembaa katĩ wa iĩma.'),
('kam', 'PSA', 104, 11, 'Mainyuwa nĩ kĩla nyamũ ya kĩtheka; Mang’oi ma kĩthekanĩ makĩlaũkw’a.'),
('kam', 'PSA', 104, 12, 'Ũtee wamo nyũnyi sya yayaya syĩ na wĩkalo wasyo; Ikinĩa mbongenĩ.'),
('kam', 'PSA', 104, 13, 'Nũnyithasya iĩma kuma tũsũmbanĩ twake: Nthĩ nĩyusũĩtwe nĩ ũsyao wa mawĩa maku.'),
('kam', 'PSA', 104, 14, 'Nũmeasya nyeki ũndũ wa indo Na nyũnyi nũndũ wa ũtethyo wa mũndũ; Kana aumye lĩu nthĩ,'),
('kam', 'PSA', 104, 15, 'Na mbinyu ĩla ĩtanasya ngoo ya mũndũ, Na mauta ma kũtisasya ũthyũ wake, Na kĩmũtũ kĩla kĩkĩaa ngoo ya mũndũ vinya.'),
('kam', 'PSA', 104, 16, 'Mĩtĩ ya Yeova nĩkolete, Mĩkũũ ya Levanoni, ĩla ũvandĩte;'),
('kam', 'PSA', 104, 17, 'Vala nyũnyi syakaa ndala syasyo: Na ũndũ wa ĩsaũ, mĩtĩ ya mĩsonovali nĩ nyũmba yayo.'),
('kam', 'PSA', 104, 18, 'Iĩma ndũlu syĩ kwondũ wa mbũi sya kĩthekanĩ; Mavia nĩ wĩvitho wa inyowe.'),
('kam', 'PSA', 104, 19, 'Aiie mwei ũndũ wa mavinda: Syũa nĩyĩsĩ ũthũĩlo wayo.'),
('kam', 'PSA', 104, 20, 'Nũetae kĩvindu, nĩkyo ũtukũ, Kĩla kĩendaa na nyamũ syonthe sya mũtitũ.'),
('kam', 'PSA', 104, 21, 'Mĩnyambũ ya mũika ĩlũmĩlaa sya nzyĩma syayo, Na kũmantha lĩu wayo kuma kwa Ngai.'),
('kam', 'PSA', 104, 22, 'Syũa yauma, ĩkĩendea, Na ĩkĩtindia isumonĩ syayo.'),
('kam', 'PSA', 104, 23, 'Mũndũ nũendaa wĩanĩ wake Na aitethya wĩa wake kũvika wĩoo.'),
('kam', 'PSA', 104, 24, 'A! Yeova, mawĩa maku nĩ maingĩ! Kwa ũĩ nĩwasyũmbie syonthe: Nthĩ nĩyusũĩtwe nĩ mothwii maku.'),
('kam', 'PSA', 104, 25, 'Ũkanga nĩ ũya, mũnene na mũthanthau, Ũla nthĩnĩ waw’o tũtambũkĩlaa tũsamũ tũtatalĩka, Nyamũ ila nini na nene.'),
('kam', 'PSA', 104, 26, 'Nĩvo vaendelaa ngalawa; Nĩvo ve leviathani ĩla wamyũmbie ĩthaũkae nthĩnĩ waw’o.'),
('kam', 'PSA', 104, 27, 'Isu syonthe nikweteele, Nĩ kana winenge lĩu wasyo ĩvinda yaw’o.'),
('kam', 'PSA', 104, 28, 'Nĩwinengae, ikomban’ya; Nũtambũũkasya kw’oko kwaku, ikakola moseo.'),
('kam', 'PSA', 104, 29, 'Nũvithaa ũthyũ waku, ikathĩna; Nĩwosaa mĩthũmũ yasyo, ikakw’a, Na kũsyoka kĩtoonĩ kyasyo.'),
('kam', 'PSA', 104, 30, 'Nũtũmaa Veva waku, ikombĩka; Na nũtũngaa nthĩ nzaũ.'),
('kam', 'PSA', 104, 31, 'Ũtheu mũtisu wa Yeova nĩwĩkale tene na tene; Yeova natanĩe mawĩa make:'),
('kam', 'PSA', 104, 32, 'We ũla ũsiasya nthĩ, na ĩkatetema; Nũkiitaa iĩma, na ikatoa syũki.'),
('kam', 'PSA', 104, 33, 'Ngamwinĩa Yeova o yĩla nĩ thayũ: Ngaina ngĩkatha Ngai wakwa o yĩla nĩĩkalaa.'),
('kam', 'PSA', 104, 34, 'Kĩsũanĩo kyakwa kĩthĩwe kĩ mũyo kwake: Ngatanaa nthĩnĩ wa Yeova.'),
('kam', 'PSA', 104, 35, 'Athe nĩmathele nthĩ. Na ala athũku matikaaĩthĩwe ĩngĩ. Taĩa Yeova, ngoo yakwa. Mũtaĩei Yeova.'),
('kam', 'PSA', 105, 1, 'Tũngĩai Yeova mũvea, ĩkaĩlei syĩtwa yake; Manyĩthyai ngo sya andũ meko make.'),
('kam', 'PSA', 105, 2, 'Mwinĩei, inai mũkĩmũkumya; Neenan’yai mawĩa make onthe ma ũseng’ya.'),
('kam', 'PSA', 105, 3, 'Ĩkathĩĩei syĩtwanĩ yake ĩtheu: Ngoo sya ala mamanthaa Yeova nitane.'),
('kam', 'PSA', 105, 4, 'Mũmanthei Yeova na vinya wake; Manthai ũthyũ wake tene na tene.'),
('kam', 'PSA', 105, 5, 'Lilikanai mawĩa make ma ũseng’ya ala wĩkĩte, Moseng’yo make, na motwi ma kanyw’a wake,'),
('kam', 'PSA', 105, 6, 'Inyw’ĩ ũsyao wa Avalaamu mũthũkũmi wake, Inyw’ĩ ana ma Yakovo, anyuvwa make.'),
('kam', 'PSA', 105, 7, 'We nĩ Yeova Ngai waitũ: Mosilĩlo make me nthĩ yonthe.'),
('kam', 'PSA', 105, 8, 'Nũlilikanaa ũtianĩo wake tene na tene, Ndeto ĩla weaĩe nzyawa ngili,'),
('kam', 'PSA', 105, 9, 'Ũtianĩo ũla watianĩe na Avalaamu, Na wĩvĩto wake kwa Isaka,'),
('kam', 'PSA', 105, 10, 'Na kũwũlũlũmĩlya kwa Yakovo kwĩthĩwa mwamũlo, Kwa Isilaeli kwĩthĩwa ũtianĩo wa tene na tene,'),
('kam', 'PSA', 105, 11, 'Akyasya, Ngakũnenga nthĩ ya Kanaani, Kĩanda kya ũtiĩwa waku;'),
('kam', 'PSA', 105, 12, 'Yĩla maĩ o andũ anini ũtalonĩ, Ĩĩ, anini mũno, na ekali ma ũeninĩ nthĩnĩ wayo.'),
('kam', 'PSA', 105, 13, 'Na mangangaa kuma mbaĩnĩ kũthi mbaĩnĩ, Kuma ũsumbĩnĩ ũmwe kũvika ũkonĩ ũngĩ wa andũ.'),
('kam', 'PSA', 105, 14, 'Ndaaeka mũndũ ameke ũthũku; Ĩĩ, nĩwamakanasya asumbĩ kwondũ woo,'),
('kam', 'PSA', 105, 15, 'Akyasya, Mũtikakiite makwa ala metĩkĩw’e mauta, Na mũtikeke athani makwa naĩ.'),
('kam', 'PSA', 105, 16, 'Na eeta yũa yũke ĩũlũ wa nthĩ; Atũlan’ya vyũ ndata ya lĩu.'),
('kam', 'PSA', 105, 17, 'Atũma mũndũ mbee woo; Yosevu athoow’a ethĩwe ngombo:'),
('kam', 'PSA', 105, 18, 'Mamwĩw’ĩthya maũũ make woo na mbĩngũ: Eekĩwa mĩnyololonĩ ya kĩaa,'),
('kam', 'PSA', 105, 19, 'Kũvika ĩvinda yĩla ndeto yake yeanĩie, Ndeto ya Yeova nĩyamũtatie.'),
('kam', 'PSA', 105, 20, 'Mũsumbĩ atũmana na amũthasya; O mũsumbĩki wa ngo sya andũ, na amũeka athi.'),
('kam', 'PSA', 105, 21, 'Amũtw’a mwĩaĩi wa nyũmba yake, Na mũnene wa syĩndũ syake syonthe;'),
('kam', 'PSA', 105, 22, 'Ove anene make me mbee ũsumbĩnĩ o ũndũ ũnũkwenda, Na kũmanyĩsya atumĩa make ũĩ.'),
('kam', 'PSA', 105, 23, 'Isilaeli nake nĩwokie Misili; Na Yakovo nĩwekalile ũeni nthĩ ya Amu.'),
('kam', 'PSA', 105, 24, 'Na nĩwaingĩvisye andũ make mũno, Na nĩwamekĩie vinya kwĩ nthũ syoo.'),
('kam', 'PSA', 105, 25, 'Nĩwathyũũie ngoo syoo imene andũ make, Syĩke athũkũmi make na ũseleke.'),
('kam', 'PSA', 105, 26, 'Atũmie Mose mũthũkũmi wake, Na Aluni ũla wanyuvĩte.'),
('kam', 'PSA', 105, 27, 'Meeka mawonan’yo make katĩ wamo, Na moseng’yo ku nthĩ ya Amu.'),
('kam', 'PSA', 105, 28, 'Atũma kĩvindu, na kĩvindu kyatulya; Na matyaang’endea ndeto syake.'),
('kam', 'PSA', 105, 29, 'Aalyũla kĩw’ũ kyoo nthakame, Na ooaa makũyũ moo.'),
('kam', 'PSA', 105, 30, 'Nthĩ yoo yeelatwa nĩ syoa Tũsũmbanĩ twa asumbĩ moo.'),
('kam', 'PSA', 105, 31, 'Aneena, na kwooka ngi mbingĩ, Na ndaa mĩvakanĩ yoo yonthe.'),
('kam', 'PSA', 105, 32, 'Amanenga mbua ya mavia vandũ va mbua, Na itw’ĩki sya mwaki nthĩ yoo.'),
('kam', 'PSA', 105, 33, 'O na akũna mĩsavivũ yoo na mĩkũyũ yoo, Na atũla mĩtĩ ya mĩvakanĩ yoo.'),
('kam', 'PSA', 105, 34, 'Aneena, na ngie syooka, Na itooli, ũndũ itatalĩka,'),
('kam', 'PSA', 105, 35, 'Na syaya syamina nyũnyi syonthe sya nthĩ yoo, Na syaya syamina ũsyao wa mũthanga woo.'),
('kam', 'PSA', 105, 36, 'O na ĩngĩ akũna ũsyao wa mbee w’onthe wa nthĩ yoo, Naw’o nĩ wambĩlĩlyo wa vinya woo w’onthe.'),
('kam', 'PSA', 105, 37, 'Na amaumya me na vetha na thaavu; Na kũtyaĩ mũndũ ũmwe mwonzu katĩ wa mbaĩ syake.'),
('kam', 'PSA', 105, 38, 'Misili yaĩ ndanu yĩla maumie; Nũndũ kũkĩwa kwoo nĩkwavalũkile ĩũlũ woo'),
('kam', 'PSA', 105, 39, 'Atambũũkasya ĩthweo ũndũ wa kũvw’ĩka, Na mwaki wa kũnengane kyeni ũtukũ.'),
('kam', 'PSA', 105, 40, 'Mavoya, na aete ngwae, Na amavũnĩthya na kĩmũtũ kya ĩtunĩ.'),
('kam', 'PSA', 105, 41, 'Avingũie ĩvia, na manzĩ mauma na vinya; Masemba kũndũ kũmũ ta ũsĩ.'),
('kam', 'PSA', 105, 42, 'Nũndũ alilikanile ndeto yake ntheu, Na Avalaamu mũthũkũmi wake.'),
('kam', 'PSA', 105, 43, 'Na aumaalya andũ make na mũyo, Na anyuvwa make makina.'),
('kam', 'PSA', 105, 44, 'Na amanenga nthĩ sya i mbaĩ; Na moosa kĩla kyanoewe nĩ ngo sya andũ kĩthĩwe kyoo:'),
('kam', 'PSA', 105, 45, 'Nĩ kana matonye kũkwata myamũlo yake, Na kũsũvĩa mĩao yake. Taĩai Yeova.'),
('kam', 'PSA', 106, 1, 'Taĩai Yeova. Tũngĩai Yeova mũvea; nũndũ nĩ mũseo; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene.'),
('kam', 'PSA', 106, 2, 'Nũũ ũla ũtonya kũweta meko ma Yeova me ũtonyi, Kana kũneenekya ndaĩa yake yonthe?'),
('kam', 'PSA', 106, 3, 'Kũathimwa nĩ ala malũmasya sila wa katĩ, Na ũla wĩkaa ũlũngalu mavinda onthe.'),
('kam', 'PSA', 106, 4, 'Ndilikana, ame Yeova, na ũseo ũla wĩ naw’o kwa andũ maku; Ame mbũkĩa na ũtangĩĩo waku,'),
('kam', 'PSA', 106, 5, 'Nĩ kana none ũunĩko wa anyuvwa maku, Nĩ kana nĩw’e mũyo ũtanunĩ wa mbaĩ yaku, Nĩ kana nĩkathĩĩe vamwe na ũtiĩwa waku.'),
('kam', 'PSA', 106, 6, 'Nĩtũvĩtĩtye twĩ na aaĩthe maitũ, Nĩtwĩkĩte ũthũku, na tũkeka naĩ.'),
('kam', 'PSA', 106, 7, 'Aaĩthe maitũ matyaamanya syama syaku me Misili; Matyaalilikana wingĩ wa moseo maku me wendo, Ĩndĩ mang’endea ũkanganĩ, o Ũkanga Mũtune.'),
('kam', 'PSA', 106, 8, 'Ĩndĩ amatangĩĩa kwondũ wa syĩtwa yake, Nĩ kana amanyĩthan’ye vinya wake wĩ ũtonyi.'),
('kam', 'PSA', 106, 9, 'O na akan’ya Ũkanga Mũtune, na wang’ala: Na ĩndĩ amatongoesya i syũngũnĩ, o ta kũmavĩtĩlya weũnĩ.'),
('kam', 'PSA', 106, 10, 'Na amatangĩĩa kuma kw’okonĩ kwa ũla wamamenete, Na amavonokan’ya kw’okonĩ kwa mũmaitha.'),
('kam', 'PSA', 106, 11, 'Na manzĩ mavw’ĩka nthũ syoo; Vatyaatiala o na ũmwe wamo.'),
('kam', 'PSA', 106, 12, 'Nĩvo ĩndĩ meetĩkĩlile ndeto syake; Maina ndaĩa yake.'),
('kam', 'PSA', 106, 13, 'Mĩtũkĩ moolwa nĩ mawĩa make; Matyaaeteela ũtao wake,'),
('kam', 'PSA', 106, 14, 'Ĩndĩ makwatĩwe nĩ ĩtomo ĩnene weũnĩ, Na matatĩa Ngai yalatanĩ.'),
('kam', 'PSA', 106, 15, 'Na amanenga kĩla mavoyie, Ĩndĩ aete kĩvooi ngoonĩ syoo.'),
('kam', 'PSA', 106, 16, 'O na ĩngĩ mamwĩw’ĩĩa Mose kĩwĩu mwakonĩ wa maeema, Na Aluni mũtheu wa Yeova.'),
('kam', 'PSA', 106, 17, 'Nthĩ yaathamya na yamelya Ndathani, Na yavw’ĩka nguthu ya Avilamu.'),
('kam', 'PSA', 106, 18, 'Na mwaki wakanĩa nguthunĩ yoo; Ũlĩlĩnzĩ wa mwaki wavĩvya athe.'),
('kam', 'PSA', 106, 19, 'Maseũvĩsye kasaũ Olevu, Na mathaitha mũvw’anano mũseũvye wa syĩndũ matwekethetye.'),
('kam', 'PSA', 106, 20, 'Ũũ nĩw’o makũanisye ndaĩa yoo Na mũvwanĩle wa ng’ombe ĩla ĩĩsaa nyeki.'),
('kam', 'PSA', 106, 21, 'Moolwa nĩ Ngai Mũtangĩĩi woo, Ũla wekie maũndũ manene Misili,'),
('kam', 'PSA', 106, 22, 'Mawĩa ma ũseng’ya nthĩ ya Amu, Na mawĩa ma kũmakya ũtee wa Ũkanga Mũtune.'),
('kam', 'PSA', 106, 23, 'Kwondũ wa ũu asya kana nũnũũmananga, Keka Mose mũnyuvwa wake kũũngama mbee wake ũvũthũenĩ, Athyũũe ũthilĩku wake, ndakese kũmananga.'),
('kam', 'PSA', 106, 24, 'Ĩĩ, nĩmavũthisye nthĩ ya kwendeesya, Matyaaĩtĩkĩla ndeto yake,'),
('kam', 'PSA', 106, 25, 'Ĩndĩ manyungunyĩĩsye maeemanĩ moo, Na malea kwĩw’a wasya wa Yeova.'),
('kam', 'PSA', 106, 26, 'Kwondũ wa ũu amevĩtĩa, Kana akamanangĩa weũnĩ.'),
('kam', 'PSA', 106, 27, 'Na kana akanangĩa ũsyao woo katĩ wa i mbaĩ, Na kũmanyaĩĩkĩsya i nthĩ.'),
('kam', 'PSA', 106, 28, 'O na ĩngĩ meekwatan’ya na Mbaaliveoli, Na maya nthembo sya akw’ũ.'),
('kam', 'PSA', 106, 29, 'Ũu nĩw’o mamũthatisye na mĩkĩle yoo; Na ũthĩn’yo wamakuthũkĩa.'),
('kam', 'PSA', 106, 30, 'Nĩvo ĩndĩ Vineasi waũngamie, na atw’a sila; Na ĩndĩ ũthĩn’yo wasiĩĩĩka.'),
('kam', 'PSA', 106, 31, 'Na ũu watalilwe kwake kwĩthĩwa nĩ ũlũngalu, Kwa nzyawa syonthe tene na tene.'),
('kam', 'PSA', 106, 32, 'O na ĩngĩ mamũthatĩsya manzĩnĩ ma Meliva, Kwondũ wa ũu nĩkwaendie naĩ kwa Mose kwondũ woo;'),
('kam', 'PSA', 106, 33, 'Nĩkwĩthĩwa nĩmathatisye veva wake, Na aneena na ilomo syake vate kũsũanĩa.'),
('kam', 'PSA', 106, 34, 'Matyaaananga i ngo sya andũ, Tondũ Yeova wameaĩe,'),
('kam', 'PSA', 106, 35, 'Ĩndĩ meevulan’ya na i mbaĩ, Na kwĩmanyĩsya mawĩa masyo,'),
('kam', 'PSA', 106, 36, 'Na kũthũkũma mĩvw’anano yasyo, Ĩla yatw’ĩkie kĩtei kwoo.'),
('kam', 'PSA', 106, 37, 'Ĩĩ, mathembee ndaimoni ana moo na eĩtu moo,'),
('kam', 'PSA', 106, 38, 'Na metĩkya nthakame ĩte ĩvĩtyo, O nthakame ya ana moo na ya eĩtu moo, Ala mathembee mĩvw’anano ya Kanaani; Na nthĩ yavukw’a nĩ nthakame.'),
('kam', 'PSA', 106, 39, 'Ũu nĩw’o mavukiw’e nĩ mawĩa moo, Na meeka ũmalwaya mekonĩ moo.'),
('kam', 'PSA', 106, 40, 'Kwondũ wa ũu ũthilĩku wa Yeova wakanĩe andũ make, Na athĩtha ũtiĩwa wake.'),
('kam', 'PSA', 106, 41, 'Na amanengane kw’okonĩ kwa i mbaĩ; Na ala mamamenaa mamasumbĩka.'),
('kam', 'PSA', 106, 42, 'O na amaitha moo mamathĩn’ya, Na maetwe ũkombonĩ ĩtheo wa moko moo.'),
('kam', 'PSA', 106, 43, 'Mavinda maingĩ nĩwamavonokasya; Ĩndĩ maĩ ang’endu kwĩtaanĩ kwoo, Na manyivw’a ũthũkunĩ woo.'),
('kam', 'PSA', 106, 44, 'Ĩndĩ o na ũu w’onthe asisya thĩna woo, Yĩla wewie kũkaya kwoo:'),
('kam', 'PSA', 106, 45, 'Na alilikana ũtianĩo wake kwondũ woo, Na eetũnga kwĩanana na wingĩ wa moseo make me wendo.'),
('kam', 'PSA', 106, 46, 'Atuma mew’ĩawa tei Nĩ onthe ala mamatavie.'),
('kam', 'PSA', 106, 47, 'Tũtangĩĩe, ame Yeova Ngai waitũ, Na kũtũmban’ya kuma i mbaĩnĩ, Nĩ kana tũtũngĩe mũvea syĩtwa yaku ĩtheu, Na kũkatha ndaĩanĩ yaku.'),
('kam', 'PSA', 106, 48, 'Nataĩwe Yeova, Ngai wa Isilaeli, Kuma tene na tene kũvika tene na tene. Na andũ onthe masye, Ameni. Mũtaĩei Yeova.'),
('kam', 'PSA', 107, 1, 'Mũtũngĩei Yeova mũvea; nũndũ nĩ mũseo; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene.'),
('kam', 'PSA', 107, 2, 'Ovosye ma Yeova nĩmasye ũu, Ala wovoisye kuma kw’okonĩ kwa nthũ,'),
('kam', 'PSA', 107, 3, 'Na amombanisye kuma i nthĩ, Kuma wumĩlonĩ wa syũa na kuma ũthũĩlonĩ wayo, Kuma ngalĩ ya ĩũlũ na kuma ngalĩ ya ĩtheo.'),
('kam', 'PSA', 107, 4, 'Mangangaa weũnĩ nzĩanĩ ya yalata; Matyaona ndũa matũa.'),
('kam', 'PSA', 107, 5, 'Me na nzaa na waũni, Ngoo syoo syanyala.'),
('kam', 'PSA', 107, 6, 'Nĩvo ĩndĩ meekaĩlile Yeova thĩnanĩ woo, Nake amavonokya monyamaonĩ moo,'),
('kam', 'PSA', 107, 7, 'O na amatongoesya na nzĩa ndũngalu, Nĩ kana maende ndũanĩ matũe.'),
('kam', 'PSA', 107, 8, 'A! Kana andũ mataĩe Yeova nũndũ wa ũseo wake wĩ wendo, Na ũndũ wa mawĩa make ma ũseng’ya kwa ana ma andũ!'),
('kam', 'PSA', 107, 9, 'Nũndũ nũvũnasya ngoo ĩla yĩ na vata, Na ngoo ĩla yĩ na nzaa aimyusũsya na ũseo.'),
('kam', 'PSA', 107, 10, 'Ala mekalĩte kĩvindunĩ na kyuunĩ kya kĩkw’ũ, Movetwe thĩnanĩ na iaa,'),
('kam', 'PSA', 107, 11, 'Nĩkwĩthĩwa nĩmang’endee ndeto sya Ngai, Na mavũthya ũtao wa Ũla Wĩ Ĩũlũ wa Onthe:'),
('kam', 'PSA', 107, 12, 'Kwondũ wa ũu atheesya ngoo syoo na ũthũkũmi wĩ vinya; Mavalũka nthĩ, na kũtyaĩ wa kũmatethya.'),
('kam', 'PSA', 107, 13, 'Nĩvo ĩndĩ meekaĩlile Yeova thĩnanĩ woo, Na amatangĩĩa monyamaonĩ moo.'),
('kam', 'PSA', 107, 14, 'Amaumya kĩvindunĩ na kyuunĩ kya kĩkw’ũ, Na atũlanĩlya katĩ ila syamovete.'),
('kam', 'PSA', 107, 15, 'A! Kana andũ mataĩe Yeova nũndũ wa ũseo wake wĩ wendo, Na nũndũ wa mawĩa make ma ũseng’ya kwa ana ma andũ!'),
('kam', 'PSA', 107, 16, 'Nũndũ nĩwanangie mbingĩlo sya ũthuku, Na kũtũlanĩlya katĩ ivingi sya iaa.'),
('kam', 'PSA', 107, 17, 'Ndia nũndũ wa mavĩtyo masyo, Na nũndũ wa mothũku masyo, nithĩnaa.'),
('kam', 'PSA', 107, 18, 'Ngoo syasyo nitiikĩawa nĩ mĩthemba yonthe ya lĩu; Na nithengeeaa vakuvĩ na mbingĩlo sya kĩkw’ũ.'),
('kam', 'PSA', 107, 19, 'Nĩvo imwĩkaĩlaa Yeova thĩnanĩ wasyo, Nake nĩwitangĩĩaa monyamaonĩ masyo.'),
('kam', 'PSA', 107, 20, 'Nũtũmaa ndeto yake, na kwivosya, Na kwivonokya kuma mawanangĩkonĩ masyo.'),
('kam', 'PSA', 107, 21, 'A! Kana andũ mataĩe Yeova nũndũ wa ũseo wake wĩ wendo, Na nũndũ wa mawĩa make ma ũseng’ya kwa ana ma andũ!'),
('kam', 'PSA', 107, 22, 'Na nĩmathembe nthembo sya mũvea, Na kũtavan’ya mawĩa make wininĩ.'),
('kam', 'PSA', 107, 23, 'Ala maendaa ũkanganĩ me ngalawanĩ, Ala matandĩthĩasya manzĩnĩ maingĩ;'),
('kam', 'PSA', 107, 24, 'Asu monaa mawĩa ma Yeova, Na moseng’yo make kyũngũnĩ.'),
('kam', 'PSA', 107, 25, 'Nĩwĩaaa, na kũkĩlya kĩseve kĩnene, Kĩla kyũkĩlasya itulumo syaw’o.'),
('kam', 'PSA', 107, 26, 'Makyambata ĩũlũ matunĩ, maitheea ĩngĩ syũngũnĩ: Ngoo syoo ikĩtweka nũndũ wa thĩna.'),
('kam', 'PSA', 107, 27, 'Makĩlũalũw’a kũũ na kũũ, na kũlulutĩkanga ta mũthengi, Na ũĩ woo nĩ mũmelye.'),
('kam', 'PSA', 107, 28, 'Na nĩvo meekaĩla Yeova thĩnanĩ woo, Nake aimaumya monyamaonĩ moo.'),
('kam', 'PSA', 107, 29, 'Nũkilĩthasya kĩseve kĩnene, Ũkethĩa itulumo syaw’o nivindĩtye.'),
('kam', 'PSA', 107, 30, 'Nĩvo ĩndĩ meũtana nĩkwĩthĩwa nĩsyakilya; Na ĩndĩ nũmaetae kĩthũmũonĩ kĩla mekwendaa.'),
('kam', 'PSA', 107, 31, 'A! Kana andũ mataĩe Yeova nũndũ wa ũseo wake wĩ wendo, Na nũndũ wa mawĩa make ma ũseng’ya kwa ana ma andũ!'),
('kam', 'PSA', 107, 32, 'O na nĩmamũnenevye ũmbanonĩ wa andũ, Na kũmũtaĩa me ivĩlanĩ sya atumĩa.'),
('kam', 'PSA', 107, 33, 'Nũalyũlaa mbũsĩ ikatw’ĩka weũ, Na mbuluti sya manzĩ ikatw’ĩka nthĩ yĩ waũni;'),
('kam', 'PSA', 107, 34, 'Nthĩ yĩ ũsyao ĩkatw’ĩka yalata yĩ mũnyũ, Nũndũ wa ũthũku wa ala matwĩe kw’o.'),
('kam', 'PSA', 107, 35, 'Nũalyũlaa weũ ũkatw’ĩka ndia ya manzĩ, Na nthĩ nyũmũ ĩthĩwe mbuluti sya manzĩ.'),
('kam', 'PSA', 107, 36, 'Na aimatũsya ala me na nzaa kw’o, Nĩ kana matonye kũseũvya ndũa ya kwĩkalaa,'),
('kam', 'PSA', 107, 37, 'Na kũvuĩa mĩũnda, na kũvanda mĩũnda ya mĩsavivũ, Na kwĩyonea mosyao maingĩ.'),
('kam', 'PSA', 107, 38, 'O na nũmaathimaa, kwondũ wa ũu nĩmaingĩvaa mũno; Na ndaekaa indo syoo inyive.'),
('kam', 'PSA', 107, 39, 'Na ĩngĩ, maoleka na kũkunamw’a nthĩ Kwondũ wa ũnyamao, na thĩna, na woo.'),
('kam', 'PSA', 107, 40, 'Nĩwonoasya kĩvũthya ĩũlũ wa anene me mbee ũsumbĩnĩ, Na kũtuma manganga kũla kũthei, kũte nzĩa.'),
('kam', 'PSA', 107, 41, 'Ĩndĩ nĩwĩkalasya ũla mũthĩni ĩũlũ mũno kuma thĩnanĩ, Na kũtw’ĩkĩthya mĩvĩa ta ndĩthya ya mbũi na malondu.'),
('kam', 'PSA', 107, 42, 'Ala alũngalu makoona ũu, na kũtana; Na ũthũku w’onthe ũkatumya kanyw’a waw’o.'),
('kam', 'PSA', 107, 43, 'Ũla wĩ na ũĩ akakwata maũndũ aa; Na makasũanĩa moseo me wendo ma Yeova.'),
('kam', 'PSA', 108, 1, 'Ngoo yakwa nĩlũmĩte, ame Ngai; Ngaina, ĩĩ, ngaina ndaĩa, o na ũnene wakwa.'),
('kam', 'PSA', 108, 2, 'Amũkai, kĩnanda na mbeve: Nakwa ngaamũkaa w’oa ũitema.'),
('kam', 'PSA', 108, 3, 'Ngakũtũngĩa mũvea, we Yeova, katĩ wa ngo sya andũ; Na ngakwinĩa ndaĩa katĩ wa i mbaĩ.'),
('kam', 'PSA', 108, 4, 'Nũndũ ũseo waku wĩ wendo nĩ mũnene ĩũlũ wa matu; Na w’o waku nũvikĩte matunĩ.'),
('kam', 'PSA', 108, 5, 'Ũnenevw’e ĩũlũ wa matu, ame Ngai, Na ũnene waku ĩũlũ wa nthĩ yonthe.'),
('kam', 'PSA', 108, 6, 'Nĩ kana endwa maku matonye kũvonokw’a, Tangĩĩa na kw’oko kwaku kwa aũme, na ũitũsũngĩa.'),
('kam', 'PSA', 108, 7, 'Ngai nũneenete ũtheunĩ wake: ngatana; Ngaaan’ya Sekemu, na kũthima kyanda kya Sukothi.'),
('kam', 'PSA', 108, 8, 'Ngileati nĩ yakwa; Manase nĩ yakwa; O na Evalaimu nĩ wa kũsesea mũtwe wakwa; Yuta nĩ ndata yakwa ya ũsumbĩ.'),
('kam', 'PSA', 108, 9, 'Moavi nĩ mbisũ yakwa ya kũthambĩa; Ngekya kĩatũ kyakwa ĩũlũ wa Etomu; Ngamyuĩsya ngemi Vilisitia.'),
('kam', 'PSA', 108, 10, 'Nũũ ũla wĩndwaa nthĩnĩ wa ndũa mbiie? Nũũ ũla wĩndongoesya kũvika Etomu?'),
('kam', 'PSA', 108, 11, 'Tuue watwĩkisye ũtee, we Ngai? Ndumaalanasya na nguthu sitũ, we Ngai.'),
('kam', 'PSA', 108, 12, 'Tũtetheesye kwa ĩla nthũ; Nũndũ ũtethyo wa mũndũ nĩ wa mana.'),
('kam', 'PSA', 108, 13, 'Kwondũ wa Ngai tũkeekaa na ũkũmbaũ: Nũndũ nĩwe ũla ũkakinyanga nthũ sitũ.'),
('kam', 'PSA', 109, 1, 'Ndũkavindye, ame Ngai ũla nĩtaĩaa;'),
('kam', 'PSA', 109, 2, 'Nũndũ kanyw’a wa ũla mwathe na kanyw’a wa ũkengani nĩmambathamĩsye: Nĩmaneenee na nĩmĩ ngengani.'),
('kam', 'PSA', 109, 3, 'O na nĩmanthyũlũlũkĩte na ndeto sya kĩmena, Na nĩmambũkitĩte vate kĩtumi.'),
('kam', 'PSA', 109, 4, 'Nũndũ wa wendo wakwa mo nĩ nthũ syakwa: Ĩndĩ nĩnĩnenganĩte mboyanĩ.'),
('kam', 'PSA', 109, 5, 'Ĩndĩ nĩmandĩvĩte ũthũku vandũ va ũseo, Na kĩmena vandũ va wendo wakwa.'),
('kam', 'PSA', 109, 6, 'Ia mũndũ mũthũku ĩũlũ wake; Na nthũ ĩũngame ngalĩ ya kw’oko kwake kwa aũme.'),
('kam', 'PSA', 109, 7, 'Akĩsilĩlwa, oneke e na ĩvĩtyo; Na mboya yake ĩalyũke ĩtw’ĩke naĩ.'),
('kam', 'PSA', 109, 8, 'Matukũ make nĩmethĩwe manini; Na ũngĩ nakwate wĩa wake.'),
('kam', 'PSA', 109, 9, 'Syana syake ikw’ĩĩwe nĩ aaĩthe, Na kĩveti kyake nĩkĩthĩwe ndiwa.'),
('kam', 'PSA', 109, 10, 'Syana syake syĩthĩwe mbangangi, na mboyi; Na nimanthe lĩu wasyo kũndũ kwoo kũla kũthei.'),
('kam', 'PSA', 109, 11, 'Mũandũi nĩose syonthe ila wĩ nasyo; Na aeni nĩmatave sya wĩa wake.'),
('kam', 'PSA', 109, 12, 'O na kũtikethĩwe ũmwe wa kũmwĩka nesa; O na kũtikethĩwe o na ũmwe wa kwĩw’ĩa syana syake ndiwa tei.'),
('kam', 'PSA', 109, 13, 'Ũsyaanĩo wake ũvetwe; Nzyawanĩ ĩla yũkĩte syĩtwa yoo yanangwe.'),
('kam', 'PSA', 109, 14, 'Ũthũku wa aaĩthe make ũlilikanwe nĩ Yeova; Na naĩ ya inyia wake ndĩkaanangwe.'),
('kam', 'PSA', 109, 15, 'Nĩmekalae mbee wa Yeova ĩndĩ yonthe, Nĩ kana atonye kũveta ũlilikan’yo woo nthĩ;'),
('kam', 'PSA', 109, 16, 'Nĩkwĩthĩwa ndaalilikana kwonan’ya ũseo, Ĩndĩ athĩnisye ngya na mũthĩni, Na ala me ngoo ndũlĩku, kũmoaa.'),
('kam', 'PSA', 109, 17, 'Ĩĩ, endie kũumanĩa, na kwasyoka kwake; Na ndaendeew’a nĩ ũathimo, naw’o waĩ kũasa nake.'),
('kam', 'PSA', 109, 18, 'O na ĩngĩ eevw’ĩka kĩumo ta kwĩvw’ĩka ngũa yake, Na kyooka nthĩnĩ wake ta manzĩ, Na ta mauta mavĩndĩnĩ make.'),
('kam', 'PSA', 109, 19, 'Kĩtw’ĩke kwake o ta ngũa ĩla wĩvw’ĩkaa, Na ta mũsivi ũla wĩvotoaa ĩndĩ yonthe.'),
('kam', 'PSA', 109, 20, 'Yĩĩ nĩyo ĩtuvi ya nthũ syakwa kuma kwa Yeova, Na ya ala maneeneaa ngoo yakwa ũthũku.'),
('kam', 'PSA', 109, 21, 'Ĩndĩ ĩka nakwa kwondũ wa syĩtwa yaku, ame Yeova Mwĩaĩi: Nĩkwĩthĩwa ũseo waku wĩ wendo nĩ mũseo, mbonokya;'),
('kam', 'PSA', 109, 22, 'Nũndũ nĩ ngya na mũthĩni, Na ngoo yakwa nĩ mbũkitĩku nthĩnĩ wakwa.'),
('kam', 'PSA', 109, 23, 'Nĩnĩendete o ta muunyĩ ũla ũendeeaa: Nĩnĩlelũkangaw’a o ta ngie.'),
('kam', 'PSA', 109, 24, 'Mau makwa nĩ monzu ũndũ wa kũtĩĩa kũya; Na mwĩĩ wakwa nũnyivĩwe nĩ ũnou.'),
('kam', 'PSA', 109, 25, 'O na ĩngĩ nĩtw’ĩkĩte kĩvũthya kwoo: Yĩla mekũmbona, nĩmekũthingithya mĩtwe yoo.'),
('kam', 'PSA', 109, 26, 'Ndethya, ame Yeova Ngai wakwa; Ndangĩĩa kwĩanana na ũseo waku wĩ wendo:'),
('kam', 'PSA', 109, 27, 'Nĩ kana mamanye kana kũũ nĩ kw’oko kwaku; Na kana we, Yeova, nĩwĩkĩte ũu.'),
('kam', 'PSA', 109, 28, 'Mo nĩmaumane, ĩndĩ we athima: Yĩla meũkĩla, makasonokw’a, Ĩndĩ mũthũkũmi waku akatana.'),
('kam', 'PSA', 109, 29, 'Nthũ syakwa ivw’ĩkwe ũndũ ũte ndaĩa, Na mevw’ĩke nthoni syoo ene ta kĩtonyeo.'),
('kam', 'PSA', 109, 30, 'Ngamũtũngĩa Yeova mũvea mũnene na kanyw’a wakwa; Ĩĩ, ngamũtaĩĩa nguthunĩ.'),
('kam', 'PSA', 109, 31, 'Nũndũ akaũngama ngalĩ ya kw’oko kwa aũme kwa mũthĩni, Amũtangĩĩe kwa ala masilĩlaa thayũ wake.'),
('kam', 'PSA', 110, 1, 'Yeova emwĩa Mwiaĩi wakwa, Ĩkala nthĩ ngalĩ ya kw’oko kwa aũme kwakwa, Mũvaka natw’a amaitha maku kavĩla ka nyaĩĩ syaku.'),
('kam', 'PSA', 110, 2, 'Yeova akatambũũkya ndata ya vinya waku kuma Saioni: Sumbĩka katĩ wa amaitha maku.'),
('kam', 'PSA', 110, 3, 'Andũ maku nĩmeĩthembaa na ngoo ya kwenda Mũthenya wa vinya waku, na ũseo wa ũtheu: Kuma ĩvunĩ ya kũikya Wĩ na ĩmwe ya wana waku.'),
('kam', 'PSA', 110, 4, 'Yeova nĩwĩvĩtĩte, na ndaketũnga: Wĩ mũthembi wa tene na tene O ta ũndũ Melikiseteki wailyĩ.'),
('kam', 'PSA', 110, 5, 'Mwĩaĩi e ngalĩ ya kw’oko kwa aũme kwaku Akakũna asumbĩ mũthenya wa kũthilĩka kwake.'),
('kam', 'PSA', 110, 6, 'Akasilaa katĩ wa i mbaĩ, Akausũsya kũndũ na simba; Nake akakũnangĩa anene nthĩnĩ wa nthĩ mbingĩ.'),
('kam', 'PSA', 110, 7, 'Akanyw’ĩa ma kalũsĩ ku nzĩanĩ: Kwondũ wa ũu akookĩlya mũtwe.'),
('kam', 'PSA', 111, 1, 'Mũtaĩeĩ Yeova. Ngamũtũngĩa Yeova mũvea na ngoo yakwa yonthe, Nzamanĩ ya ala alũngalu, na ũmbanonĩ.'),
('kam', 'PSA', 111, 2, 'Mawĩa ma Yeova nĩ manene, Mamanthawa nĩ onthe ala mendeeawa nĩmo.'),
('kam', 'PSA', 111, 3, 'Wĩa wake wĩ ndaĩa na ũnene; Na ũlũngalu wake nĩwĩkalaa tene na tene.'),
('kam', 'PSA', 111, 4, 'Nũtumaa mawĩa make ma ũseng’ya malilikanwa: Yeova nĩ mũseo na e tei.'),
('kam', 'PSA', 111, 5, 'Nũmanengete lĩu ala mamũkĩaa: Akalilikanaa ũtianĩo wake ĩndĩ yonthe.'),
('kam', 'PSA', 111, 6, 'Nĩwonetye andũ make vinya wa mawĩa make, Aimanenga ũtiĩwa wa i mbaĩ.'),
('kam', 'PSA', 111, 7, 'Mawĩa ma moko make nĩmo w’o na ũsili wa katĩ; Mawĩaĩo make onthe nĩ malũmu.'),
('kam', 'PSA', 111, 8, 'Nĩmalũlũmĩlw’e tene na tene; Nĩmekawa nthĩnĩ wa w’o na ũlũngalunĩ.'),
('kam', 'PSA', 111, 9, 'Nũtũmĩte wovosyo kwa andũ make; Nĩwĩaĩte ũtianĩo wake tene na tene: Syĩtwa yake nĩ ĩtheu na ya kũtaĩwa.'),
('kam', 'PSA', 111, 10, 'Kũmũkĩa Yeova nĩkw’o wambĩlĩlyo wa ũĩ; Ũmanyi mũseo wĩ na onthe ala mekaa mĩao yake: Kũtaĩwa kwake nĩkwĩkalaa tene na tene.'),
('kam', 'PSA', 112, 1, 'Mũtaĩei Yeova. Nĩmũathime mũndũ ũla ũmũkĩaa Yeova, Ũla ũtanĩaa mũno mĩao yake.'),
('kam', 'PSA', 112, 2, 'Ũsyao wake ũkeethĩwa wĩ na ũtonyi kũũ nthĩ: Nzyawa ya mũlũngalu ĩkaathimwa.'),
('kam', 'PSA', 112, 3, 'Ũthwii na syĩndũ syĩ nyũmbanĩ yake; Na ũlũngalu wake nĩwĩkalaa tene na tene.'),
('kam', 'PSA', 112, 4, 'Kyeni nĩkyumĩlĩlaa alũngalu kĩvindunĩ: Nake nĩ mũseo, na e tei, na nĩ mũlũngalu.'),
('kam', 'PSA', 112, 5, 'Nĩ kũseo kwa mũndũ ũla wĩkaa na ĩnee na kũkovethya; Akaseũvya ũvoo wake ũsilĩlonĩ.'),
('kam', 'PSA', 112, 6, 'Nũndũ ndakathingithangw’a o na ĩndĩĩ; Ũla mũlũngalu nũkalilikanwa tene na tene.'),
('kam', 'PSA', 112, 7, 'Ndakakĩa maũvoo mathũku: Ngoo yake nĩlũmĩte, aiĩkĩĩa Yeova.'),
('kam', 'PSA', 112, 8, 'Ngoo yake nĩlũmĩte ndakakĩa, Kũvika oona kwenda kwake ĩũlũ wa nthũ syake.'),
('kam', 'PSA', 112, 9, 'Nũũanĩtye, nũnengete ala athĩni; Ũlũngalu wake nĩwĩkalaa tene na tene: Ũvya wake ũkanenevw’a na ndaĩa.'),
('kam', 'PSA', 112, 10, 'Ũla mũthũku akoona ũu, na kwĩw’a woo; Akavevetan’ya maeo, na kũtweka vyũ; Kwenda kwa ala athũku kũkaaa.'),
('kam', 'PSA', 113, 1, 'Mũtaĩei Yeova. Mũtaĩei, inyw’ĩ athũkũmi ma Yeova, Taĩai syĩtwa ya Yeova.'),
('kam', 'PSA', 113, 2, 'Syĩtwa ya Yeova nĩyĩtaĩwe Kuma yu na kũvika tene na tene.'),
('kam', 'PSA', 113, 3, 'Kuma syũa yauma kũvika yathũa Syĩtwa ya Yeova nĩ ya kũtaĩwa.'),
('kam', 'PSA', 113, 4, 'Yeova e ĩũlũ wa mbaĩ syonthe, Na ũtheu mũtisu wake ĩũlũ wa matu,'),
('kam', 'PSA', 113, 5, 'Nũũ ũilyĩ ta Yeova Ngai waitũ, Ũla wĩ na kĩvĩla kyake ĩũlũ,'),
('kam', 'PSA', 113, 6, 'Ũla wĩnyivasya asisye Syĩndũ syĩ ĩtunĩ na nthĩ?'),
('kam', 'PSA', 113, 7, 'Nĩwũkĩlasya ngya kũmyumya kĩtoonĩ, Na kũkĩlya ũla mũthĩni kũmumya ũtũndanĩ;'),
('kam', 'PSA', 113, 8, 'Nĩ kana amwĩkalye nthĩ vamwe na anene me mbee ũsumbĩnĩ, O vamwe na anene me mbee ũsumbĩnĩ ma andũ make.'),
('kam', 'PSA', 113, 9, 'Nũtumaa mũndũ mũka ngũngũ ekala nyũmbanĩ, Na kwĩthĩwa inyia mũtanu wa syana. Mũtaĩei Yeova.'),
('kam', 'PSA', 114, 1, 'Yĩla Isilaeli waumie Mĩsili, Nyũmba ya Yakovo yaumie andũnĩ me kĩthyomo kĩeni;'),
('kam', 'PSA', 114, 2, 'Yuta atw’ĩka vandũ vake vatheu, Isilaeli atw’ĩka ũsumbĩko wake.'),
('kam', 'PSA', 114, 3, 'Ũkanga nĩwoonie ũu, na wakĩa; Yolotani nĩwatũngiwe na ĩtina.'),
('kam', 'PSA', 114, 4, 'Iĩma syatũlĩlanga ta ndũũme, Tũlĩma ta tũtena twa malondu.'),
('kam', 'PSA', 114, 5, 'Wĩ na kĩ, we ũkanga, ũndũ ũũkĩa? We Yolotani, ũndũ ũĩthyũũa na ĩtina?'),
('kam', 'PSA', 114, 6, 'Inyw’ĩ iĩma, ũndũ mũũtũlĩlanga ta ndũũme; Iny’wĩ tũlĩma, ta tũtena twa malondu?'),
('kam', 'PSA', 114, 7, 'We nthĩ, tetemea mbee wa Mwĩaĩi, Mbee wa Ngai wa Yakovo,'),
('kam', 'PSA', 114, 8, 'Ũla waalyũlile ĩvia yatw’ĩka ndia ya manzĩ, Ĩvia yũmũ kwĩthĩwa nthongo ya manzĩ.'),
('kam', 'PSA', 115, 1, 'Ti vaitũ, ame Yeova, ti vaitũ, Ĩndĩ syĩtwa yaku yĩnengwe ndaĩa. Kwondũ wa ũseo waku wĩ wendo, na kwondũ wa w’o waku.'),
('kam', 'PSA', 115, 2, 'Nũndũ wa kĩ i mbaĩ syaasye, Yu Ngai woo aĩva?'),
('kam', 'PSA', 115, 3, 'Ĩndĩ Ngai waitũ e matunĩ: Nĩwĩkĩte o ũndũ wendie.'),
('kam', 'PSA', 115, 4, 'Mĩvw’anano yoo nĩ vetha na thaavu, Wĩa wa moko ma andũ.'),
('kam', 'PSA', 115, 5, 'Yĩ na makanyw’a, ĩndĩ ndĩneenaa; Yĩ na metho, ĩndĩ ndĩonaa;'),
('kam', 'PSA', 115, 6, 'Yĩ na matũ, ĩndĩ ndĩw’aa; Yĩ na manyiũũ, ĩndĩ ndĩnyungĩaa;'),
('kam', 'PSA', 115, 7, 'Yĩ na moko, ĩndĩ ndĩkwatangaa; Yĩ na maũũ, ĩndĩ ndĩendaa; O na ndĩumasya wasya mĩmeonĩ yayo.'),
('kam', 'PSA', 115, 8, 'Ala mamĩseũvasya makeethĩwa mailyĩ tayo; Ĩĩ, kĩla mũndũ ũla ũmĩĩkĩĩaa.'),
('kam', 'PSA', 115, 9, 'We Isilaeli, ĩkĩĩa Yeova: Nĩwe mũtethya woo na ngao yoo.'),
('kam', 'PSA', 115, 10, 'We nyũmba ya Aluni, ĩkĩĩai Yeova: Nĩwe mũtethya woo na ngao yoo.'),
('kam', 'PSA', 115, 11, 'Inyw’ĩ ala mũkĩaa Yeova, ĩkĩĩai Yeova: Nĩwe mũtethya woo na ngao yoo.'),
('kam', 'PSA', 115, 12, 'Yeova nũtũlilikanĩte; akatũathima: Akaathima nyũmba ya Isilaeli; Akaathima nyũmba ya Aluni.'),
('kam', 'PSA', 115, 13, 'Akaathima ala makĩaa Yeova, Anini na anene.'),
('kam', 'PSA', 115, 14, 'Yeova namwingĩvye mbee na mbee, Inyw’ĩ na syana syenyu.'),
('kam', 'PSA', 115, 15, 'Nĩmũathimĩtwe nĩ Yeova, Ũla watw’ĩkĩthisye ĩtu na nthĩ.'),
('kam', 'PSA', 115, 16, 'Matu nĩ matu ma Yeova; Ĩndĩ nthĩ nũnengete ana ma andũ.'),
('kam', 'PSA', 115, 17, 'Akw’ũ matitaĩaa Yeova, O na ũmwe wa ala matheeaa kũla kũkilĩtye;'),
('kam', 'PSA', 115, 18, 'Ĩndĩ ithyĩ tũkataĩa Yeova Kuma yu na kũvika tene na tene. Mũtaĩei Yeova.'),
('kam', 'PSA', 116, 1, 'Nĩnĩmwendaa Yeova, nĩkwĩthĩwa nĩwĩw’aa Wasya wakwa na mawĩsũvano makwa.'),
('kam', 'PSA', 116, 2, 'Nĩkwĩthĩwa nũteete kũtũ kwake kwakwa, Kwondũ wa ũu ngamwĩkaĩlaa o yĩla nĩ thayũ.'),
('kam', 'PSA', 116, 3, 'Ndii sya kĩkw’ũ nĩsyeendingĩlĩte, Na mawoo ma Seoli nĩmangwatĩte: Nĩnonete thĩna na woo.'),
('kam', 'PSA', 116, 4, 'Nĩvo ĩndĩ neekaĩlile syĩtwa ya Yeova: Ame Yeova, nĩngũkwĩsũva, vonokya thayũ wakwa.'),
('kam', 'PSA', 116, 5, 'Yeova nĩ mũseo, na mũlũngalu; Ĩĩ, Ngai waitũ e tei.'),
('kam', 'PSA', 116, 6, 'Yeova nũsũvĩaa ala mate ũmanyi: Nĩnanyiviw’e, na andangĩĩa.'),
('kam', 'PSA', 116, 7, 'Syoka ũthũmũonĩ waku, we ngoo yakwa; Nũndũ Yeova nũkwĩkĩte na ũlau.'),
('kam', 'PSA', 116, 8, 'Nũndũ nũvonoketye thayũ wakwa kuma kĩkw’ũnĩ, Metho makwa maume methoinĩ, Na maũũ makwa maume kũtiũũkanĩ.'),
('kam', 'PSA', 116, 9, 'Ngaendelaa mbee wa Yeova Nthi ya ala me thayũ.'),
('kam', 'PSA', 116, 10, 'Nĩngwĩtĩkĩla, kwondũ wa ũu nganeena: Nĩnathĩniw’e mũno:'),
('kam', 'PSA', 116, 11, 'Mĩtũkĩnĩ yakwa nĩnaisye, Andũ onthe me ũvũngũ.'),
('kam', 'PSA', 116, 12, 'Nĩmũnenga Yeova kĩ Kwondũ wa moseo make onthe kwakwa?'),
('kam', 'PSA', 116, 13, 'Ngoosa kĩkombe kya ũtangĩĩo, Na kwĩkaĩla syĩtwa ya Yeova.'),
('kam', 'PSA', 116, 14, 'Ngeanĩsya mawĩvĩto makwa kwa Yeova, Ĩĩ, andũ make onthe mene.'),
('kam', 'PSA', 116, 15, 'Methonĩ ma Yeova kĩ vata mũno Kĩkw’ũ kya atheu make.'),
('kam', 'PSA', 116, 16, 'Ame Yeova, vate ndĩi nyie nĩ mũthũkũmi waku: Nĩ mũthũkũmi waku, mwana wa mũthũkũmi waku mwĩĩtu; Nũthaĩtye kĩla kĩmbovete.'),
('kam', 'PSA', 116, 17, 'Ngakũthembea nthembo ya mũvea, Na kwĩkaĩla syĩtwa ya Yeova.'),
('kam', 'PSA', 116, 18, 'Ngeanĩsya mawĩvĩto makwa kwa Yeova, Ĩĩ, andũ make onthe mene,'),
('kam', 'PSA', 116, 19, 'Nthĩnĩ wa nza sya nyũmba ya Yeova, Katĩ waku, we Yelusaleme. Mũtaĩei Yeova.'),
('kam', 'PSA', 117, 1, 'Mũtaĩei Yeova, inyw’ĩ mbaĩ syonthe; Mũkathei, inyw’ĩ ngo syonthe sya andũ.'),
('kam', 'PSA', 117, 2, 'Nũndũ ũseo wake wĩ wendo nĩ mũnene kwitũ; Na w’o wa Yeova nĩwĩkalaa tene na tene. Mũtaĩei Yeova.'),
('kam', 'PSA', 118, 1, 'Mũtũngĩei Yeova mũvea; nũndũ nĩ mũseo; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene.'),
('kam', 'PSA', 118, 2, 'Yu Isilaeli naneene, Kana ũseo wake wĩ wendo nĩwĩkalaa tene na tene.'),
('kam', 'PSA', 118, 3, 'Yu nyũmba ya Aluni nĩneene, Ũseo wake wĩ wendo nĩwĩkalaa tene na tene.'),
('kam', 'PSA', 118, 4, 'Ala makĩaa Yeova maneene, Ũseo wake wĩ wendo nĩwĩkalaa tene na tene.'),
('kam', 'PSA', 118, 5, 'Nĩ ũnyamaonĩ wakwa nĩnamwĩkaĩlile Yeova: Yeova nĩwanzũngĩie na ambĩkalya vandũ vaamu.'),
('kam', 'PSA', 118, 6, 'Yeova e ngalĩ yakwa; ndikakĩa: Mũndũ atonya kũmbĩka ata?'),
('kam', 'PSA', 118, 7, 'Yeova e ngalĩ yakwa katĩ wa ala mandethasya: Kwondũ wa ũu ngoona kwenda kwakwa kũkĩkwa ĩũlũ wa ala mamenaa.'),
('kam', 'PSA', 118, 8, 'Nĩ kavaa kwĩvitha nthĩnĩ wa Yeova Kwĩ kwĩkwatya mũndũ.'),
('kam', 'PSA', 118, 9, 'Nĩ kavaa kwĩvitha nthĩnĩ wa Yeova Kwĩ kwĩkwatya anene me mbee ũsumbĩnĩ.'),
('kam', 'PSA', 118, 10, 'Mbaĩ syonthe ninthyũlũlũkĩte: Syĩtwanĩ ya Yeova ngaiveta.'),
('kam', 'PSA', 118, 11, 'Ninthyũlũlũkĩte; ĩĩ, ninthyũlũlũkĩte: Syĩtwanĩ ya Yeova ngaiveta.'),
('kam', 'PSA', 118, 12, 'Ninthyũlũlũkĩte ta nzũkĩ; nivoetwe ta mwaki wa mĩw’a: Syĩtwanĩ ya Yeova ngaiveta.'),
('kam', 'PSA', 118, 13, 'Nĩwanduutile mũno nĩ kana nĩvalũke; Ĩndĩ Yeova nĩwandethisye.'),
('kam', 'PSA', 118, 14, 'Yeova nĩ vinya wakwa na wathi wakwa; Na nũtw’ĩkĩte ũtangĩĩo wakwa.'),
('kam', 'PSA', 118, 15, 'Wasya wa kũtana na wa ũtangĩĩo wĩ maeemanĩ ma ala alũngalu: Kw’oko kwa aũme kwa Yeova nĩkwĩkaa na ũtonyi.'),
('kam', 'PSA', 118, 16, 'Kw’oko kwa aũme kwa Yeova nĩ kũtaĩe: Kw’oko kwa aũme kwa Yeova nĩkwĩkaa na ũtonyi.'),
('kam', 'PSA', 118, 17, 'Ndikakw’a, ĩndĩ ngekala thayũ, Na kũtavan’ya mawĩa ma Yeova.'),
('kam', 'PSA', 118, 18, 'Yeova nũnzilĩlĩte mũno; Ĩndĩ ndaanengane nĩkw’e.'),
('kam', 'PSA', 118, 19, 'Mbingũĩa mbingĩlo sya ũlũngalu: Ngailikĩla, ngamũtũngĩa Yeova mũvea.'),
('kam', 'PSA', 118, 20, 'Ĩno nĩyo mbingĩlo ya Yeova; Ala alũngalu makamĩvotela.'),
('kam', 'PSA', 118, 21, 'Ngakũtũngĩa mũvea; nũndũ nũnzũngĩĩte, Na nũtw’ĩkĩte ũtangĩĩo wakwa.'),
('kam', 'PSA', 118, 22, 'Ĩvia yĩla aki maleile Nĩyĩtw’ĩkĩte ĩnene ya kĩkotonĩ.'),
('kam', 'PSA', 118, 23, 'Ũu nĩ wĩko wa Yeova; Nĩ ũseng’yo methonĩ maitũ.'),
('kam', 'PSA', 118, 24, 'Ũũ nĩ mũthenya ũla Yeova ũseũvĩtye; Tũkatana na kũwĩw’ĩa mũyo.'),
('kam', 'PSA', 118, 25, 'Tangĩĩa yu, nĩtũũkwĩsũva, ame Yeova: Ame Yeova, nĩtũũkwĩsũva, ete yu ũunĩko.'),
('kam', 'PSA', 118, 26, 'Nĩ mũathime ũla wũkaa syĩtwanĩ ya Yeova: Nĩtũmũathimĩte inyw’ĩ twĩ nyũmbanĩ ya Yeova.'),
('kam', 'PSA', 118, 27, 'Yeova nĩ Ngai, na nũtũnengete kyeni: Oveea nthembo na ndii, o mbyanĩ sya kĩthembeo.'),
('kam', 'PSA', 118, 28, 'Nue Ngai wakwa, na ngakũtũngĩa mũvea: Nue Ngai wakwa, ngakũnenevya.'),
('kam', 'PSA', 118, 29, 'Mũtũngĩei Yeova mũvea; nũndũ nĩ mũseo; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene.'),
('kam', 'PSA', 119, 1, 'Nĩ aathime ala eanĩu nzĩanĩ, Ala maendaa mĩaonĩ ya Yeova.'),
('kam', 'PSA', 119, 2, 'Nĩ aathime ala masũvĩaa mokũsĩ make, Ala mamũmanthaa na ngoo yonthe.'),
('kam', 'PSA', 119, 3, 'Ĩĩ, matyĩkaa ũndũ ũte ũlũngalu; Nĩmaendelaa nzĩanĩ syake.'),
('kam', 'PSA', 119, 4, 'Nũtwĩaĩĩte mawĩaĩo maku, Nĩ kana tũmekae na kĩthing’ĩĩsyo.'),
('kam', 'PSA', 119, 5, 'A! Kethĩwa nzĩa syakwa nilũlũmĩlwa Kũkwata myamũlo yaku!'),
('kam', 'PSA', 119, 6, 'Nĩvo ĩndĩ ndikasonokw’a, Yĩla ngũkwata mĩao yaku yonthe.'),
('kam', 'PSA', 119, 7, 'Ngakũtũngĩa mũvea nĩ na ũlũngalu ngoonĩ, Yĩla ngwĩmanyĩsya mosilĩlo maku malũngalu.'),
('kam', 'PSA', 119, 8, 'Ngakwata myamũlo yaku: Ndũkaandeke nongi.'),
('kam', 'PSA', 119, 9, 'Mwanake akatheasya nzĩa yake na kyaũ? No ũndũ wa kũmĩsũvĩa kwĩanana na ndeto yaku.'),
('kam', 'PSA', 119, 10, 'Nĩkũmanthĩte na ngoo yakwa yonthe: Ndũkandeke nangangae kuma mĩaonĩ yaku.'),
('kam', 'PSA', 119, 11, 'Nĩniĩte ndeto yaku ngoonĩ yakwa, Nĩ kana ndikakũvĩtanĩsye.'),
('kam', 'PSA', 119, 12, 'Wĩ mũtaĩĩku, ame Yeova: Manyĩsya nyie myamũlo yaku.'),
('kam', 'PSA', 119, 13, 'Nĩnĩtavanĩtye na ilomo syakwa Motw’ĩo onthe ma kanyw’a waku.'),
('kam', 'PSA', 119, 14, 'Nĩnĩtanĩte nzĩanĩ ya mokũsĩ maku, O ũndũ nĩtanĩte mothwiinĩ onthe.'),
('kam', 'PSA', 119, 15, 'Ngasũanĩaa mawĩaĩo maku, Na kũsũvĩaa nzĩa syaku.'),
('kam', 'PSA', 119, 16, 'Ngeetanĩthasya myamũlonĩ yaku: Ndikolwa nĩ ndeto yaku.'),
('kam', 'PSA', 119, 17, 'Mwĩke mũthũkũmi waku na ũlau, nĩ kana nĩkale thayũ; Na ngakwata ndeto yaku.'),
('kam', 'PSA', 119, 18, 'Salukya metho makwa, nĩ kana none Maũndũ ma ũseng’ya mĩaonĩ yaku.'),
('kam', 'PSA', 119, 19, 'Nyie nĩ mwĩkali wa ũeninĩ kũũ nthĩ: Ndũkambithe mĩao yaku.'),
('kam', 'PSA', 119, 20, 'Ngoo yakwa nĩ ndũle nĩ mea Ala yĩ namo ũndũ wa motw’ĩo maku mavinda onthe.'),
('kam', 'PSA', 119, 21, 'Nũkanĩtye ekathĩĩi ala maumanĩwe, Ala mangangaa kuma mĩaonĩ yaku.'),
('kam', 'PSA', 119, 22, 'Mbetea kĩvũthya na ntheko; Nũndũ nĩnzũvĩĩte mokũsĩ maku.'),
('kam', 'PSA', 119, 23, 'O na anene me mbee ũsumbĩnĩ mekala nthĩ na kũneenea naĩ; Ĩndĩ mũthũkũmi waku alilikana myamũlo yaku.'),
('kam', 'PSA', 119, 24, 'O na mokũsĩ maku nĩ ũtanu wakwa Na nĩ atai makwa.'),
('kam', 'PSA', 119, 25, 'Ngoo yakwa nĩlũmanĩtye na kĩtoo: Nthayũũkya kwĩanana na ndeto yaku.'),
('kam', 'PSA', 119, 26, 'Nĩnatavanisye nzĩa syakwa, naku nĩwanzũngĩie: Manyĩsya nyie myamũlo yaku.'),
('kam', 'PSA', 119, 27, 'Manyĩthya nyie nzĩa ya mawĩaĩo maku: Nakwa ngasũanĩa mawĩa maku ma ũseng’ya.'),
('kam', 'PSA', 119, 28, 'Ngoo yakwa nĩnĩũtwekw’a nĩ woo: Mbĩkĩa vinya kwĩanana na ndeto yaku.'),
('kam', 'PSA', 119, 29, 'Mbetea nzĩa ya ũvũngũ; Na nenga mĩao yaku na ũseo mwingĩ.'),
('kam', 'PSA', 119, 30, 'Nĩnĩnyuvĩte nzĩa ya kĩthito: Nĩniĩte motw’ĩo maku mbee wakwa.'),
('kam', 'PSA', 119, 31, 'Nĩngũlũman’ya na mokũsĩ maku: Ame Yeova, ndũkaanzonokye.'),
('kam', 'PSA', 119, 32, 'Ngasemba nzĩanĩ ya mĩao yaku, Yĩla wĩnenevya ngoo yakwa.'),
('kam', 'PSA', 119, 33, 'Manyĩsya nyie, ame Yeova, nzĩa ya myamũlo yaku; Na ngamĩkwata kũvika mũminũkĩlyo.'),
('kam', 'PSA', 119, 34, 'Nenga ũmanyi, na ngakwata mĩao yaku; Ĩĩ, ngamĩkaa na ngoo yakwa yonthe.'),
('kam', 'PSA', 119, 35, 'Ndwaĩthasya nzĩanĩ ya mĩao yaku; Nũndũ nĩtanĩaa nthĩnĩ wayo.'),
('kam', 'PSA', 119, 36, 'Elekelya ngoo yakwa mokũsĩnĩ maku, Na ti ĩtomonĩ.'),
('kam', 'PSA', 119, 37, 'Thyũũa metho makwa matikasisye maũndũ ma mana, Na nthayũũkya nzĩanĩ syaku.'),
('kam', 'PSA', 119, 38, 'Lũlũmĩlya ndeto yaku kwa mũthũkũmi waku, Ĩla ĩtumaa ũkĩwa.'),
('kam', 'PSA', 119, 39, 'Mbetea kũvũthw’a kwakwa kũla nĩkĩaa; Nũndũ motw’ĩo maku nĩ maseo.'),
('kam', 'PSA', 119, 40, 'Sisya, nĩnendete mawĩaĩo maku: Nthayũũkya ũlũngalunĩ waku.'),
('kam', 'PSA', 119, 41, 'Moseo maku me wendo namo mambũkĩe, ame Yeova, O ũtangĩĩo waku, kwĩanana na ndeto yaku.'),
('kam', 'PSA', 119, 42, 'Kwondũ wa ũu ngeethĩwa na ũsũngĩo kwa ũla ũmbũthasya; Nũndũ nĩnĩĩkĩĩaa ndeto yaku.'),
('kam', 'PSA', 119, 43, 'Ndũkaaumye nongi ndeto ya w’o kanyw’anĩ wakwa; Nũndũ nĩnĩkwatĩtye motw’ĩo maku.'),
('kam', 'PSA', 119, 44, 'Kwondũ wa ũu ngakwata mĩao yaku ĩndĩ yonthe Kũvika tene na tene.'),
('kam', 'PSA', 119, 45, 'Na ngaendaa nĩ mũthasye; Nũndũ nĩnĩmanthĩte mawĩaĩo maku.'),
('kam', 'PSA', 119, 46, 'O na ĩngĩ ngaweta mokũsĩ maku mbee wa asumbĩ, Na ndikasonokw’a.'),
('kam', 'PSA', 119, 47, 'Ngeetanĩthasya mĩaonĩ yaku, Ĩla nendete.'),
('kam', 'PSA', 119, 48, 'O na ĩngĩ ngookĩlĩlya moko makwa mĩao yaku, ĩla nendete; Na ngasũanĩaa myamũlo yaku.'),
('kam', 'PSA', 119, 49, 'Lilikana ndeto kwa mũthũkũmi waku, Ĩla wandĩkĩĩthisye.'),
('kam', 'PSA', 119, 50, 'Nĩyo ũkiakisyo wakwa thĩnanĩ wakwa; Atĩ ndeto yaku nĩnthayũũkĩtye.'),
('kam', 'PSA', 119, 51, 'Ekathĩĩi nĩmanthekeee mũno: Ĩndĩ ndyaaathũka ũtee kuma mĩaonĩ yaku.'),
('kam', 'PSA', 119, 52, 'Nĩnĩlilikanĩte motw’ĩo maku ma tene, ame Yeova, Na ngekiakisya.'),
('kam', 'PSA', 119, 53, 'Ũthatu mwakanu nũngwatĩte, Nũndũ wa athũku ala matiaa mĩao yaku.'),
('kam', 'PSA', 119, 54, 'Myamũlo yaku yĩthĩawa mbathi syakwa Nyũmbanĩ ya ũeni wakwa.'),
('kam', 'PSA', 119, 55, 'Nĩnĩlilikanĩte syĩtwa yaku ũtukũ, we Yeova, Na nĩnĩkwatĩtye mĩao yaku.'),
('kam', 'PSA', 119, 56, 'Ũũ nĩthĩawa naw’o, Atĩ nĩngwatĩte mawĩaĩo maku.'),
('kam', 'PSA', 119, 57, 'Yeova nĩ kĩanda kyakwa: Nĩnaĩtye kana ngakwata ndeto syaku.'),
('kam', 'PSA', 119, 58, 'Nĩneesũvanie ũseo kwaku na ngoo yakwa yonthe: Mbĩw’ĩa tei kwĩanana na ndeto yaku.'),
('kam', 'PSA', 119, 59, 'Nĩnasũanĩie mĩendele yakwa, Na nathyũũĩa mokũsĩ maku maũũ makwa.'),
('kam', 'PSA', 119, 60, 'Nĩneekalaatile, ndyaaĩkala, Nĩkwate mĩao yaku.'),
('kam', 'PSA', 119, 61, 'Ndii sya athũku nĩsyeendingĩlĩte; Ĩndĩ ndyaaũlwa nĩ mĩao yaku.'),
('kam', 'PSA', 119, 62, 'Ũtukũ katĩ ngookĩlaa nĩkũtũngĩe mũvea Nũndũ wa motw’ĩo maku malũngalu.'),
('kam', 'PSA', 119, 63, 'Nĩ mũtindan’ya wa onthe ala makũkĩaa, Na wa ala makwataa mawĩaĩo maku.'),
('kam', 'PSA', 119, 64, 'Ame Yeova, nthĩ nĩyusũĩte ũseo waku wĩ wendo: Manyĩsya nyie myamũlo yaku.'),
('kam', 'PSA', 119, 65, 'Nĩwĩkĩte mũthũkũmi waku nesa, We Yeova, kwĩanana na ndeto yaku.'),
('kam', 'PSA', 119, 66, 'Manyĩsya nyie kwonaa katĩ o na ũmanyi; Nũndũ nĩnĩtĩkĩlĩte mĩao yaku.'),
('kam', 'PSA', 119, 67, 'Ndanamba kũthĩnw’a naendaa ngyanganga; Ĩndĩ yu nĩngwataa ndeto yaku.'),
('kam', 'PSA', 119, 68, 'We wĩ mũseo, na nĩwĩkaa ũseo; Manyĩsya nyie myamũlo yaku.'),
('kam', 'PSA', 119, 69, 'Ekathĩĩi nĩmanzeũvĩsye ũvũngũ: Ngakwata mawĩaĩo maku na ngoo yakwa yonthe.'),
('kam', 'PSA', 119, 70, 'Ngoo syoo nĩ nou ta mathunya; Ĩndĩ nyie nĩtanaa mĩaonĩ yaku.'),
('kam', 'PSA', 119, 71, 'Nĩ ũseo kwakwa nathĩniw’e; Nĩ kana nĩmanyĩsye myamũlo yaku.'),
('kam', 'PSA', 119, 72, 'Mwĩao wa kanyw’a waku nĩ kavaa kwakwa Kwĩ ngili sya thaavu na vetha.'),
('kam', 'PSA', 119, 73, 'Moko maku nĩmambũmbie na manzeũvya: Nenga ũmanyi, nĩ kana nĩmanyĩsye mĩao yaku.'),
('kam', 'PSA', 119, 74, 'Ala makũkĩaa makambona na kũtana, Nĩkwĩthĩwa nĩnĩkwatĩtye ndeto yaku.'),
('kam', 'PSA', 119, 75, 'Nĩnĩsĩ, ame Yeova, mosilĩlo maku nĩ malũngalu, Na kĩthitonĩ kyaku nũnthĩnĩtye.'),
('kam', 'PSA', 119, 76, 'Nĩngũkwĩsũva, ũseo waku wĩ wendo nĩwĩthĩwe wa kũngiakisya, Kwĩanana na ndeto yaku kwa mũthũkũmi waku.'),
('kam', 'PSA', 119, 77, 'Matei maku mololo nĩmambũkĩe, nĩ kana nĩkale thayũ; Nũndũ mĩao yaku nĩ ũtanu wakwa.'),
('kam', 'PSA', 119, 78, 'Ekathĩĩi nĩmasonokw’e; nũndũ nĩmambalũkĩtye na ũvũngũ: Ĩndĩ ngasũanĩaa mawĩaĩo maku.'),
('kam', 'PSA', 119, 79, 'Ala maũkĩaa nĩmenthyũũĩe; Na makamanya mokũsĩ maku.'),
('kam', 'PSA', 119, 80, 'Ngoo yakwa nĩyĩthĩwe mbĩanĩu myamũlonĩ yaku, Nĩ kana ndikasonoke.'),
('kam', 'PSA', 119, 81, 'Ngoo yakwa yĩ na mũnyalo kwondũ wa ũtangĩĩo waku; Ĩndĩ nĩkwatasya ndeto yaku.'),
('kam', 'PSA', 119, 82, 'Metho makwa nĩmeũseekea kwondũ wa ndeto yaku, O yĩla ngwasya, Ũkangiakisya ĩndĩĩ?'),
('kam', 'PSA', 119, 83, 'Nũndũ nĩndw’ĩkĩte ta kathatwa ka mbinyu ke vala ve syũki; Ĩndĩ ndyũlawa nĩ myamũlo yaku.'),
('kam', 'PSA', 119, 84, 'Mĩthenya ya mũthũkũmi waku nĩ yĩana? Ũkamasilĩla ala manthĩnasya ĩndĩĩ?'),
('kam', 'PSA', 119, 85, 'Ekathĩĩi nĩmenzĩte maima ũndũ wakwa, Ala matekaa kwĩanana na mĩao yaku.'),
('kam', 'PSA', 119, 86, 'Mĩao yaku yonthe nĩ ya kũĩkĩĩwa: Nĩmanthĩnasya na ũvũngũ; ndethya.'),
('kam', 'PSA', 119, 87, 'Maĩ vakuvĩ kũmbeta ĩũlũ wa nthĩ; Ĩndĩ ndyaatia mawĩaĩo maku.'),
('kam', 'PSA', 119, 88, 'Nthayũũkya kwĩanana na ũseo waku wĩ wendo, Nakwa ngakwata ũkũsĩ wa kanyw’a waku.'),
('kam', 'PSA', 119, 89, 'Tene na tene, ame Yeova, Ndeto yaku nĩlũmĩtw’e ĩtunĩ.'),
('kam', 'PSA', 119, 90, 'Kĩthito kyaku nĩ kya nzyawa syonthe: Nũlũlũmĩlĩtye nthĩ, nayo nĩyĩkalaa.'),
('kam', 'PSA', 119, 91, 'Nĩmekalaa ũmũnthĩ kwĩanana na motw’ĩo maku; Nũndũ syĩndũ syonthe nĩ athũkũmi maku.'),
('kam', 'PSA', 119, 92, 'Kethĩwa mĩao yaku ndĩaĩ ũtanu wakwa, Nĩthĩwa naaĩe thĩnanĩ wakwa.'),
('kam', 'PSA', 119, 93, 'Ndikolwa nongi nĩ mawĩaĩo maku; Nũndũ nũnthayũũkĩtye namo.'),
('kam', 'PSA', 119, 94, 'Nyie nĩ waku, ndangĩĩa; Nũndũ nĩnĩmanthĩte mawĩaĩo maku.'),
('kam', 'PSA', 119, 95, 'Ala athũku nĩmambeteele, mambanange; Ĩndĩ ngasũanĩaa mokũsĩ maku.'),
('kam', 'PSA', 119, 96, 'Nĩnonete mũminũkĩlyo wa wĩanĩu w’onthe; Ĩndĩ mwĩao waku nĩ mũthanthau mũno.'),
('kam', 'PSA', 119, 97, 'Mĩao yaku ko nĩnĩmyendetee! Nĩyo nzũanĩaa mũthenya w’onthe.'),
('kam', 'PSA', 119, 98, 'Mĩao yaku nĩtuma nĩthĩwa na ũĩ kwĩ amaitha makwa; Nũndũ yĩ nakwa mavinda onthe.'),
('kam', 'PSA', 119, 99, 'Nĩ na ũmanyi kũvĩtũka amanyĩsya makwa onthe; Nũndũ mokũsĩ maku nĩ ũsũanĩo wakwa.'),
('kam', 'PSA', 119, 100, 'Nĩnĩmanyaa kũvĩtũka ala akũũ, Nĩkwĩthĩwa nĩkwatĩte mawĩaĩo maku.'),
('kam', 'PSA', 119, 101, 'Nĩnziĩĩĩte maũũ makwa na kĩla nzĩa nthũku, Nĩ kana nĩkwate ndeto yaku.')
